[CmdletBinding()]
param(
  [ValidatePattern('^COM[0-9]+$')]
  [string]$VehiclePort = 'COM3',

  [ValidateRange(1200, 2000000)]
  [int]$VehicleBaud = 115200,

  [string]$VehiclePnpDeviceId = `
      'USB\VID_303A&PID_1001&MI_00\7&7131F6A&0&0000',

  [ValidatePattern('^COM[0-9]+$')]
  [string]$GroundPort = 'COM6',

  [ValidateRange(1200, 2000000)]
  [int]$GroundBaud = 57600,

  [string]$GroundPnpDeviceId = `
      'USB\VID_303A&PID_1001&MI_00\7&2159A644&0&0000',

  [string]$FixturePath = '',
  [string]$OutputDirectory = '',

  [ValidateRange(1, 3600)]
  [int]$PortWaitTimeoutSeconds = 600,

  [ValidateRange(5000, 60000)]
  [int]$PowerOffConfirmMs = 5000,

  [ValidateRange(1, 60)]
  [int]$SnapshotTimeoutSeconds = 10,

  [ValidateRange(30, 3600)]
  [int]$DataPlaneReadinessTimeoutSeconds = 720,

  [ValidateRange(30, 3600)]
  [int]$BacklogDrainTimeoutSeconds = 720,

  [ValidateRange(300, 14400)]
  [int]$OverallTimeoutSeconds = 7200,

  [ValidateRange(30, 600)]
  [int]$StallTimeoutSeconds = 120,

  [ValidateRange(30, 300)]
  [int]$DuplicateGuardSeconds = 30,

  [ValidateSet('NORMAL','FUTURE_INDEX_RECOVERY')]
  [string]$ExpectedDiagnosticFaultMode = 'NORMAL',

  [ValidateRange(0, 931)]
  [int]$ExpectedDiagnosticFaultDropIndex = 930,

  [switch]$SelfTest,
  [string]$SelfTestEvidenceDirectory = '',

  [switch]$ReaderBrokerMode,
  [string]$ReaderBrokerPipeName = '',
  [string]$ReaderBrokerSecret = '',
  [string]$ReaderBrokerSourceSha256 = '',
  [ValidateSet('serial','pressure','overflow','timestamp','barrier','ackloss','openio')]
  [string]$ReaderBrokerScenario = 'serial',
  [ValidateRange(1, 65536)]
  [int]$ReaderBrokerRingSlots = 32768,
  [ValidateRange(0, 1048576)]
  [int]$ReaderBrokerVehicleBytes = 0,
  [ValidateRange(0, 1048576)]
  [int]$ReaderBrokerGroundBytes = 0,
  [int]$ReaderBrokerParentPid = 0,

  [ValidateSet('PASS', 'MEASURED_FAIL', 'POWER_OFF_TIMEOUT',
      'READINESS_TIMEOUT', 'READINESS_SYNC_INVALID', 'POSTCLOSE_ERROR')]
  [string]$SelfTestScenario = 'PASS'
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$script:RunWatch = $null
$script:CurrentPhase = 'not_started'
$script:Timeline = $null
$script:OutputDirectoryOwned = $false
$script:MaximumTaggedLineBytes = 16384
$script:ExpectedFixtureHex = 'FD02000063FFBE1500000101D507'
$script:ExpectedFixtureSha256 = `
    'FC3A47A83D35D44E96E044A216FDBF082805F9FACCDD5E4B9252E0C7026D4A75'
$script:CanonicalDefinitionsSha256 = `
    'BD2890D8973C5A694D53AB2866A6B3DBF319FAE40B3CC308AE2DAE91B634F3A8'
$script:ExpectedStatRuntimeIdHex = '535441545F52554E54494D4500000000'
$script:ExpectedParamCount = 932
$script:ExpectedLastIndex = 931
$script:HeartbeatMaximumGapMs = 2500
$script:ReadinessVehicleBReserveMs = [double]3000.0
$script:SnapshotWriteDeadlineMarginMs = [double]500.0
$script:VehiclePartialUsbWakeStallMs = [double]250.0
$script:VehiclePartialUsbWakeMinimumRemainingMs = [double]600.0
$script:VehiclePartialUsbWakeWriteTimeoutMs = [double]100.0
$script:VehiclePartialUsbWakeMaxAttempts = [int]1
$script:VehiclePartialUsbWakeByte = [byte[]]@([byte]0x0D)
$script:ReadinessDeviceMsToleranceMs = [uint64]100
$script:MaxParamValueEvidenceEvents = 2048
$script:SerialReadSliceBytes = [int]32
$script:SerialReadSlicesPerTurn = [int]1
$script:RawCaptureBufferBytes = [int]65536
$script:RawCaptureFlushScheduleMs = [double]25000.0
$script:RawCaptureFlushIntervalMs = [double]30000.0
$script:MaxReadinessPumpCheckpointEvents = [int]4096
$script:ReadinessInitialAndFinallyCheckpointCount = [int]7
$script:ReadinessPassiveCheckpointCount = [int]2
$script:ReadinessBracketCheckpointCount = [int]8
$script:PumpFairnessTargetMs = [double]75.0
$script:PumpFairnessHardLimitMs = [double]100.0
$script:MaxPumpFairnessViolationEvents = [int]64
$script:PumpFairness = $null
$script:PumpAdminStage = 'not_started'
$script:ReaderRingSlotCount = [int]32768
$script:DualPortReaderWorker = $null
$script:ReaderShutdownEvidence = $null
$script:ReaderBrokerProtocolVersion = [int]2
$script:BoundPortIdentityStableMs = [int]5000

if ($ExpectedDiagnosticFaultMode -ceq 'FUTURE_INDEX_RECOVERY' -and
    $ExpectedDiagnosticFaultDropIndex -ne 930) {
  throw ('FUTURE_INDEX_RECOVERY supports only the deterministic ' +
      'compile-time fault index 930.')
}

function Initialize-DualPortReaderWorkerType {
  if ('VcDualPortReader.DualPortReaderWorker' -as [type]) { return }
  [string]$definition = @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Pipes;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

namespace VcDualPortReader {
  public interface IByteSource {
    bool IsOpen { get; }
    int Available { get; }
    int Read(byte[] buffer, int offset, int count);
  }

  public sealed class SerialByteSource : IByteSource {
    private readonly __SERIAL_PORT_TYPE__ port;
    public SerialByteSource(__SERIAL_PORT_TYPE__ portValue) {
      if (portValue == null) throw new ArgumentNullException("portValue");
      port = portValue;
    }
    public bool IsOpen { get { return port.IsOpen; } }
    public int Available { get { return port.BytesToRead; } }
    public int Read(byte[] buffer, int offset, int count) {
      return port.Read(buffer, offset, count);
    }
  }

  public sealed class SyntheticByteSource : IByteSource {
    private readonly object gate = new object();
    private readonly byte[] bytes;
    private int offset;
    public SyntheticByteSource(int byteCount, int seed) {
      if (byteCount < 0) throw new ArgumentOutOfRangeException("byteCount");
      bytes = new byte[byteCount];
      for (int index = 0; index < byteCount; ++index) {
        bytes[index] = (byte)((seed + index * 29) & 0xff);
      }
    }
    public bool IsOpen { get { return true; } }
    public int Available {
      get { lock (gate) { return bytes.Length - offset; } }
    }
    public int Remaining { get { return Available; } }
    public int TotalBytes { get { return bytes.Length; } }
    public int Read(byte[] buffer, int destinationOffset, int count) {
      lock (gate) {
        int wanted = Math.Min(count, bytes.Length - offset);
        if (wanted <= 0) return 0;
        Buffer.BlockCopy(bytes, offset, buffer, destinationOffset, wanted);
        offset += wanted;
        return wanted;
      }
    }
  }

  public sealed class BlockingSyntheticByteSource : IByteSource {
    private readonly byte[] bytes = new byte[32];
    private readonly ManualResetEventSlim readEntered =
        new ManualResetEventSlim(false);
    private readonly ManualResetEventSlim releaseRead =
        new ManualResetEventSlim(false);
    private int consumed;
    public BlockingSyntheticByteSource(int seed) {
      for (int index = 0; index < bytes.Length; ++index) {
        bytes[index] = (byte)((seed + index * 31) & 0xff);
      }
    }
    public bool IsOpen { get { return true; } }
    public int Available { get { return consumed == 0 ? bytes.Length : 0; } }
    public int Read(byte[] buffer, int offset, int count) {
      readEntered.Set();
      releaseRead.Wait();
      if (Interlocked.Exchange(ref consumed, 1) != 0) return 0;
      int wanted = Math.Min(count, bytes.Length);
      Buffer.BlockCopy(bytes, 0, buffer, offset, wanted);
      return wanted;
    }
    public bool WaitForReadEntered(int timeoutMs) {
      return readEntered.Wait(timeoutMs);
    }
    public void ReleaseRead() { releaseRead.Set(); }
  }

  public sealed class CaptureRecord {
    public string Role { get; internal set; }
    public long Sequence { get; internal set; }
    public long RawStartOffset { get; internal set; }
    public long ProducerTimestampTicks { get; internal set; }
    public double ProducerElapsedMs { get; internal set; }
    public int Count { get; internal set; }
    public byte[] Bytes { get; internal set; }
    public string ProducerPhase { get; internal set; }
    public string ProducerEpoch { get; internal set; }
    public UInt32 ContextId { get; internal set; }
    public CaptureRecord(int maximumBytes) {
      Bytes = new byte[maximumBytes];
    }
  }

  internal sealed class CaptureSlot {
    internal readonly byte[] Bytes;
    internal long Sequence;
    internal long RawStartOffset;
    internal long ProducerTimestampTicks;
    internal double ProducerElapsedMs;
    internal int Count;
    internal string ProducerPhase;
    internal string ProducerEpoch;
    internal UInt32 ContextId;
    internal CaptureSlot(int maximumBytes) { Bytes = new byte[maximumBytes]; }
  }

  public sealed class RingPosition {
    public long SequenceExclusive { get; internal set; }
    public long RawOffsetExclusive { get; internal set; }
    public long BoundaryTimestampTicks { get; internal set; }
    public double BoundaryElapsedMs { get; internal set; }
    public UInt32 OldContextId { get; internal set; }
    public UInt32 NewContextId { get; internal set; }
  }

  public sealed class FairnessViolationEvent {
    public long Sequence { get; internal set; }
    public string Kind { get; internal set; }
    public long StartedTimestampTicks { get; internal set; }
    public long FinishedTimestampTicks { get; internal set; }
    public double DurationMs { get; internal set; }
    public UInt32 ContextId { get; internal set; }
    public string Phase { get; internal set; }
    public string Epoch { get; internal set; }
    public int BytesRead { get; internal set; }
    public long RawStartOffset { get; internal set; }
    public long RawEndOffsetExclusive { get; internal set; }
    public long ServiceOrdinal { get; internal set; }
    public long BoundaryGeneration { get; internal set; }
    public string BoundaryKind { get; internal set; }

    public FairnessViolationEvent Clone() {
      return new FairnessViolationEvent {
        Sequence = Sequence,
        Kind = Kind,
        StartedTimestampTicks = StartedTimestampTicks,
        FinishedTimestampTicks = FinishedTimestampTicks,
        DurationMs = DurationMs,
        ContextId = ContextId,
        Phase = Phase,
        Epoch = Epoch,
        BytesRead = BytesRead,
        RawStartOffset = RawStartOffset,
        RawEndOffsetExclusive = RawEndOffsetExclusive,
        ServiceOrdinal = ServiceOrdinal,
        BoundaryGeneration = BoundaryGeneration,
        BoundaryKind = BoundaryKind
      };
    }
  }

  public sealed class FixedCaptureRing {
    private readonly object gate = new object();
    private readonly CaptureSlot[] slots;
    private readonly string role;
    private int head;
    private int tail;
    private int count;
    private long producedSequence;
    private long consumedSequence;
    private long producedRawBytes;
    private long consumedRawBytes;
    private bool overflowLatched;
    private long overflowCount;

    public FixedCaptureRing(string roleValue, int capacity, int maximumBytes) {
      if (String.IsNullOrEmpty(roleValue)) throw new ArgumentNullException("roleValue");
      if (capacity <= 0) throw new ArgumentOutOfRangeException("capacity");
      if (maximumBytes <= 0) throw new ArgumentOutOfRangeException("maximumBytes");
      role = roleValue;
      slots = new CaptureSlot[capacity];
      for (int index = 0; index < capacity; ++index) {
        slots[index] = new CaptureSlot(maximumBytes);
      }
    }

    public int Capacity { get { return slots.Length; } }
    public bool OverflowLatched { get { lock (gate) { return overflowLatched; } } }
    public long OverflowCount { get { lock (gate) { return overflowCount; } } }
    public int QueueDepth { get { lock (gate) { return count; } } }
    public long ProducedSequence { get { lock (gate) { return producedSequence; } } }
    public long ConsumedSequence { get { lock (gate) { return consumedSequence; } } }
    public long ProducedRawBytes { get { lock (gate) { return producedRawBytes; } } }
    public long ConsumedRawBytes { get { lock (gate) { return consumedRawBytes; } } }

    public bool TryEnqueue(byte[] source, int sourceOffset, int byteCount,
        long producerTimestampTicks, double producerElapsedMs,
        string producerPhase, string producerEpoch, UInt32 contextId) {
      lock (gate) {
        if (count == slots.Length) {
          overflowLatched = true;
          ++overflowCount;
          return false;
        }
        CaptureSlot slot = slots[tail];
        Buffer.BlockCopy(source, sourceOffset, slot.Bytes, 0, byteCount);
        slot.Sequence = producedSequence;
        slot.RawStartOffset = producedRawBytes;
        slot.ProducerTimestampTicks = producerTimestampTicks;
        slot.ProducerElapsedMs = producerElapsedMs;
        slot.ProducerPhase = producerPhase;
        slot.ProducerEpoch = producerEpoch;
        slot.ContextId = contextId;
        slot.Count = byteCount;
        tail = (tail + 1) % slots.Length;
        ++count;
        ++producedSequence;
        producedRawBytes += byteCount;
        return true;
      }
    }

    public bool TryDequeueInto(CaptureRecord record) {
      lock (gate) {
        if (count == 0) return false;
        CaptureSlot slot = slots[head];
        Buffer.BlockCopy(slot.Bytes, 0, record.Bytes, 0, slot.Count);
        record.Role = role;
        record.Sequence = slot.Sequence;
        record.RawStartOffset = slot.RawStartOffset;
        record.ProducerTimestampTicks = slot.ProducerTimestampTicks;
        record.ProducerElapsedMs = slot.ProducerElapsedMs;
        record.ProducerPhase = slot.ProducerPhase;
        record.ProducerEpoch = slot.ProducerEpoch;
        record.ContextId = slot.ContextId;
        record.Count = slot.Count;
        head = (head + 1) % slots.Length;
        --count;
        ++consumedSequence;
        consumedRawBytes += slot.Count;
        return true;
      }
    }

    public void CapturePositionInto(RingPosition position) {
      lock (gate) {
        position.SequenceExclusive = producedSequence;
        position.RawOffsetExclusive = producedRawBytes;
      }
    }
  }

  public sealed class RoleReaderSnapshot {
    public string Role { get; internal set; }
    public bool Started { get; internal set; }
    public bool StopRequested { get; internal set; }
    public bool Joined { get; internal set; }
    public bool ThreadAlive { get; internal set; }
    public long ServiceCount { get; internal set; }
    public long BytesRead { get; internal set; }
    public long ZeroByteServiceCount { get; internal set; }
    public double MaxServiceGapMs { get; internal set; }
    public long ServiceGapOverTargetCount { get; internal set; }
    public long ServiceGapOverHardLimitCount { get; internal set; }
    public double MaxReadDurationMs { get; internal set; }
    public long ReadDurationOverTargetCount { get; internal set; }
    public long ReadDurationOverHardLimitCount { get; internal set; }
    public double TargetMs { get; internal set; }
    public double HardLimitMs { get; internal set; }
    public int RingCapacity { get; internal set; }
    public int QueueDepth { get; internal set; }
    public long ProducedSequence { get; internal set; }
    public long ConsumedSequence { get; internal set; }
    public long ProducedRawBytes { get; internal set; }
    public long ConsumedRawBytes { get; internal set; }
    public bool OverflowLatched { get; internal set; }
    public long OverflowCount { get; internal set; }
    public string FatalError { get; internal set; }
    public int ViolationEventCap { get; internal set; }
    public int ViolationEventCount { get; internal set; }
    public long ViolationEventTotalCount { get; internal set; }
    public long ViolationEventOverflowCount { get; internal set; }
    public FairnessViolationEvent[] ViolationEvents { get; internal set; }
    public bool IsFair {
      get {
        return ServiceCount > 0 &&
          MaxServiceGapMs < HardLimitMs &&
          MaxReadDurationMs < HardLimitMs &&
          ServiceGapOverHardLimitCount == 0 &&
          ReadDurationOverHardLimitCount == 0;
      }
    }
    public bool IsConsistent {
      get {
        return ProducedSequence >= ConsumedSequence &&
          ProducedRawBytes >= ConsumedRawBytes &&
          ProducedSequence - ConsumedSequence == QueueDepth;
      }
    }
  }

  public sealed class RoleReader {
    private readonly string role;
    private readonly IByteSource source;
    private readonly FixedCaptureRing ring;
    private readonly byte[] readBuffer;
    private long originTicks;
    private double baseElapsedMs;
    private readonly double targetMs;
    private readonly double hardLimitMs;
    private readonly Thread thread;
    private volatile bool stopRequested;
    private volatile bool started;
    private volatile bool joined;
    private volatile bool armed;
    private volatile string producerPhase;
    private volatile string producerEpoch;
    private int producerContextId;
    private long serviceCount;
    private long bytesRead;
    private long zeroByteServiceCount;
    private long lastServiceStartedTicks;
    private long maxServiceGapTicks;
    private long maxReadDurationTicks;
    private long serviceGapOverTargetCount;
    private long serviceGapOverHardLimitCount;
    private long readDurationOverTargetCount;
    private long readDurationOverHardLimitCount;
    private string fatalError;
    private const int ViolationEventCapacity = 64;
    private readonly object violationGate = new object();
    private readonly FairnessViolationEvent[] violationEvents =
        new FairnessViolationEvent[ViolationEventCapacity];
    private int violationEventCount;
    private long violationEventTotalCount;
    private long violationEventOverflowCount;
    private readonly object barrierGate = new object();
    private readonly RingPosition barrierAckPosition = new RingPosition();
    private long barrierRequestedGeneration;
    private long barrierAcknowledgedGeneration;
    private bool pendingPhaseTransition;
    private string pendingPhase;
    private string pendingEpoch;
    private bool pendingContextIdTransition;
    private int pendingContextId;
    private string pendingBoundaryKind = "none";
    private long appliedBoundaryGeneration;
    private string appliedBoundaryKind = "none";

    public RoleReader(string roleValue, IByteSource sourceValue,
        int ringCapacity, int maximumReadBytes, long originTicksValue,
        double baseElapsedMsValue, double targetMsValue,
        double hardLimitMsValue) {
      role = roleValue;
      source = sourceValue;
      ring = new FixedCaptureRing(roleValue, ringCapacity, maximumReadBytes);
      readBuffer = new byte[maximumReadBytes];
      originTicks = originTicksValue;
      baseElapsedMs = baseElapsedMsValue;
      producerPhase = "not_armed";
      producerEpoch = "not_armed";
      targetMs = targetMsValue;
      hardLimitMs = hardLimitMsValue;
      thread = new Thread(RoleReaderLoop);
      thread.IsBackground = true;
      thread.Name = "VcDualPortReader-" + roleValue;
      thread.Priority = ThreadPriority.AboveNormal;
      for (int index = 0; index < violationEvents.Length; ++index) {
        violationEvents[index] = new FairnessViolationEvent();
      }
    }

    private static double TicksToMs(long ticks) {
      return ((double)ticks * 1000.0) / (double)Stopwatch.Frequency;
    }
    private static void SetMaximum(ref long location, long candidate) {
      long observed = Interlocked.Read(ref location);
      while (candidate > observed) {
        long prior = Interlocked.CompareExchange(ref location, candidate, observed);
        if (prior == observed) return;
        observed = prior;
      }
    }
    private void LatchFatal(Exception error) {
      if (fatalError == null) {
        fatalError = error.GetType().FullName + ": " + error.Message;
      }
    }
    private void RecordViolation(string kind, long startedTicks,
        long finishedTicks, UInt32 contextId, string phase, string epoch,
        int bytes, long rawStartOffset, long rawEndOffsetExclusive,
        long serviceOrdinal, long boundaryGeneration, string boundaryKind) {
      long durationTicks = finishedTicks - startedTicks;
      double durationMs = TicksToMs(durationTicks);
      lock (violationGate) {
        if (kind == "service_gap") {
          ++serviceGapOverTargetCount;
          if (durationMs >= hardLimitMs) ++serviceGapOverHardLimitCount;
        } else if (kind == "read_duration") {
          ++readDurationOverTargetCount;
          if (durationMs >= hardLimitMs) ++readDurationOverHardLimitCount;
        } else {
          throw new InvalidOperationException("unknown fairness violation kind");
        }
        long sequence = violationEventTotalCount++;
        if (violationEventCount >= violationEvents.Length) {
          ++violationEventOverflowCount;
          return;
        }
        FairnessViolationEvent value = violationEvents[violationEventCount++];
        value.Sequence = sequence;
        value.Kind = kind;
        value.StartedTimestampTicks = startedTicks;
        value.FinishedTimestampTicks = finishedTicks;
        value.DurationMs = durationMs;
        value.ContextId = contextId;
        value.Phase = phase ?? "unknown";
        value.Epoch = epoch ?? value.Phase;
        value.BytesRead = bytes;
        value.RawStartOffset = rawStartOffset;
        value.RawEndOffsetExclusive = rawEndOffsetExclusive;
        value.ServiceOrdinal = serviceOrdinal;
        value.BoundaryGeneration = boundaryGeneration;
        value.BoundaryKind = boundaryKind ?? "none";
      }
    }

    public void Arm(long originTicksValue, double baseElapsedMsValue) {
      if (started) throw new InvalidOperationException("cannot arm started reader: " + role);
      originTicks = originTicksValue;
      baseElapsedMs = baseElapsedMsValue;
      lastServiceStartedTicks = originTicksValue;
      armed = true;
    }
    public void SetCaptureContext(string phase, string epoch) {
      producerPhase = phase ?? "unknown";
      producerEpoch = epoch ?? producerPhase;
    }
    public void SetCaptureContextId(UInt32 contextId) {
      Interlocked.Exchange(ref producerContextId, unchecked((int)contextId));
    }
    public void Start() {
      if (started) throw new InvalidOperationException("reader already started: " + role);
      if (!armed) Arm(Stopwatch.GetTimestamp(), 0.0);
      // Producer elapsed time keeps the cross-process origin supplied to Arm,
      // while fairness begins at the actual child thread start boundary.
      Interlocked.Exchange(ref lastServiceStartedTicks,
          Stopwatch.GetTimestamp());
      started = true;
      thread.Start();
    }

    private void ApplyBoundaryIfRequested() {
      long requested = Interlocked.Read(ref barrierRequestedGeneration);
      if (requested <= Interlocked.Read(ref barrierAcknowledgedGeneration)) return;
      lock (barrierGate) {
        requested = Interlocked.Read(ref barrierRequestedGeneration);
        if (requested <= Interlocked.Read(ref barrierAcknowledgedGeneration)) {
          return;
        }
        UInt32 oldContextId = unchecked((UInt32)Interlocked.CompareExchange(
            ref producerContextId, 0, 0));
        ring.CapturePositionInto(barrierAckPosition);
        long boundaryTicks = Stopwatch.GetTimestamp();
        if (pendingPhaseTransition) {
          producerPhase = pendingPhase ?? "unknown";
          producerEpoch = pendingEpoch ?? producerPhase;
        }
        if (pendingContextIdTransition) {
          Interlocked.Exchange(ref producerContextId, pendingContextId);
        }
        UInt32 newContextId = unchecked((UInt32)Interlocked.CompareExchange(
            ref producerContextId, 0, 0));
        barrierAckPosition.BoundaryTimestampTicks = boundaryTicks;
        barrierAckPosition.BoundaryElapsedMs = baseElapsedMs +
            TicksToMs(boundaryTicks - originTicks);
        barrierAckPosition.OldContextId = oldContextId;
        barrierAckPosition.NewContextId = newContextId;
        Interlocked.Exchange(ref appliedBoundaryGeneration, requested);
        appliedBoundaryKind = pendingBoundaryKind ?? "capture";
        Interlocked.Exchange(ref barrierAcknowledgedGeneration, requested);
      }
    }
    private void RequestBoundary(long generation, string boundaryKind,
        bool transitionPhase, string nextPhase, string nextEpoch,
        bool transitionContextId, UInt32 nextContextId) {
      lock (barrierGate) {
        if (generation <= Interlocked.Read(ref barrierRequestedGeneration) ||
            Interlocked.Read(ref barrierRequestedGeneration) >
                Interlocked.Read(ref barrierAcknowledgedGeneration)) {
          throw new InvalidOperationException(
              "reader boundary generation was not strictly serialized: " + role);
        }
        pendingBoundaryKind = boundaryKind ?? "capture";
        pendingPhaseTransition = transitionPhase;
        pendingPhase = nextPhase;
        pendingEpoch = nextEpoch;
        pendingContextIdTransition = transitionContextId;
        pendingContextId = unchecked((int)nextContextId);
        Interlocked.Exchange(ref barrierRequestedGeneration, generation);
      }
    }
    public void RequestBarrier(long generation) {
      RequestBoundary(generation, "capture", false, null, null,
          false, unchecked((UInt32)0));
    }
    public void RequestContextTransition(long generation,
        string phase, string epoch) {
      RequestBoundary(generation, "phase_transition", true,
          phase ?? "unknown", epoch ?? (phase ?? "unknown"),
          false, unchecked((UInt32)0));
    }
    public void RequestContextIdTransition(long generation, UInt32 contextId) {
      RequestBoundary(generation, "context_transition", false, null, null,
          true, contextId);
    }
    public bool WaitForBarrier(long generation, RingPosition destination,
        int timeoutMs) {
      Stopwatch wait = Stopwatch.StartNew();
      while (Interlocked.Read(ref barrierAcknowledgedGeneration) < generation &&
          wait.ElapsedMilliseconds < timeoutMs) Thread.Sleep(0);
      if (Interlocked.Read(ref barrierAcknowledgedGeneration) < generation) {
        return false;
      }
      lock (barrierGate) {
        destination.SequenceExclusive = barrierAckPosition.SequenceExclusive;
        destination.RawOffsetExclusive = barrierAckPosition.RawOffsetExclusive;
        destination.BoundaryTimestampTicks =
            barrierAckPosition.BoundaryTimestampTicks;
        destination.BoundaryElapsedMs = barrierAckPosition.BoundaryElapsedMs;
        destination.OldContextId = barrierAckPosition.OldContextId;
        destination.NewContextId = barrierAckPosition.NewContextId;
      }
      return true;
    }

    private void RoleReaderLoop() {
      while (!stopRequested) {
        ApplyBoundaryIfRequested();
        if (stopRequested) break;
        string servicePhase = producerPhase;
        string serviceEpoch = producerEpoch;
        UInt32 serviceContextId = unchecked((UInt32)Interlocked.CompareExchange(
            ref producerContextId, 0, 0));
        long serviceBoundaryGeneration =
            Interlocked.Read(ref appliedBoundaryGeneration);
        string serviceBoundaryKind = appliedBoundaryKind;
        long serviceStartedTicks = Stopwatch.GetTimestamp();
        long priorStartedTicks = Interlocked.Exchange(
            ref lastServiceStartedTicks, serviceStartedTicks);
        long gapTicks = serviceStartedTicks - priorStartedTicks;
        double gapMs = TicksToMs(gapTicks);
        SetMaximum(ref maxServiceGapTicks, gapTicks);
        long serviceOrdinal = Interlocked.Increment(ref serviceCount);
        long serviceRawStartOffset = ring.ProducedRawBytes;
        if (gapMs >= targetMs) {
          RecordViolation("service_gap", priorStartedTicks,
              serviceStartedTicks, serviceContextId, servicePhase,
              serviceEpoch, 0, serviceRawStartOffset, serviceRawStartOffset,
              serviceOrdinal, serviceBoundaryGeneration, serviceBoundaryKind);
        }
        int read = 0;
        bool idle = true;
        try {
          if (!ring.OverflowLatched && source.IsOpen) {
            int available = source.Available;
            if (available > 0) {
              idle = false;
              int wanted = Math.Min(available, readBuffer.Length);
              try {
                read = source.Read(readBuffer, 0, wanted);
              } catch (TimeoutException) {
                read = 0;
              }
              if (read > 0) {
                long producerTicks = Stopwatch.GetTimestamp();
                double producerElapsedMs = baseElapsedMs +
                    TicksToMs(producerTicks - originTicks);
                if (ring.TryEnqueue(readBuffer, 0, read, producerTicks,
                    producerElapsedMs, servicePhase, serviceEpoch,
                    serviceContextId)) {
                  Interlocked.Add(ref bytesRead, read);
                }
              }
            }
          }
        } catch (Exception error) {
          LatchFatal(error);
          stopRequested = true;
        } finally {
          if (read == 0) Interlocked.Increment(ref zeroByteServiceCount);
          long durationTicks = Stopwatch.GetTimestamp() - serviceStartedTicks;
          double durationMs = TicksToMs(durationTicks);
          SetMaximum(ref maxReadDurationTicks, durationTicks);
          if (durationMs >= targetMs) {
            RecordViolation("read_duration", serviceStartedTicks,
                serviceStartedTicks + durationTicks, serviceContextId,
                servicePhase, serviceEpoch, read, serviceRawStartOffset,
                ring.ProducedRawBytes, serviceOrdinal,
                serviceBoundaryGeneration, serviceBoundaryKind);
          }
        }
        ApplyBoundaryIfRequested();
        if (idle || ring.OverflowLatched) Thread.Sleep(1);
      }
    }

    public bool TryDequeueInto(CaptureRecord record) {
      return ring.TryDequeueInto(record);
    }
    public void CaptureStoppedPositionInto(RingPosition position) {
      if (thread.IsAlive) throw new InvalidOperationException(
          "stopped position requested while reader alive: " + role);
      ring.CapturePositionInto(position);
      long boundaryTicks = Stopwatch.GetTimestamp();
      UInt32 contextId = unchecked((UInt32)Interlocked.CompareExchange(
          ref producerContextId, 0, 0));
      position.BoundaryTimestampTicks = boundaryTicks;
      position.BoundaryElapsedMs = baseElapsedMs +
          TicksToMs(boundaryTicks - originTicks);
      position.OldContextId = contextId;
      position.NewContextId = contextId;
    }
    public bool HasFatalFailure {
      get { return ring.OverflowLatched || fatalError != null; }
    }
    public void RequestStop() {
      stopRequested = true;
    }
    public bool Join(int timeoutMs) {
      if (!started) { joined = true; return true; }
      joined = thread.Join(timeoutMs);
      if (!joined && fatalError == null) fatalError = "reader join timeout";
      return joined;
    }
    public bool StopAndJoin(int timeoutMs) {
      RequestStop();
      return Join(timeoutMs);
    }
    public RoleReaderSnapshot Snapshot() {
      long gapTarget;
      long gapHard;
      long durationTarget;
      long durationHard;
      int traceCount;
      long traceTotal;
      long traceOverflow;
      FairnessViolationEvent[] traceEvents;
      lock (violationGate) {
        gapTarget = serviceGapOverTargetCount;
        gapHard = serviceGapOverHardLimitCount;
        durationTarget = readDurationOverTargetCount;
        durationHard = readDurationOverHardLimitCount;
        traceCount = violationEventCount;
        traceTotal = violationEventTotalCount;
        traceOverflow = violationEventOverflowCount;
        traceEvents = new FairnessViolationEvent[traceCount];
        for (int index = 0; index < traceCount; ++index) {
          traceEvents[index] = violationEvents[index].Clone();
        }
      }
      return new RoleReaderSnapshot {
        Role = role,
        Started = started,
        StopRequested = stopRequested,
        Joined = joined,
        ThreadAlive = thread.IsAlive,
        ServiceCount = Interlocked.Read(ref serviceCount),
        BytesRead = Interlocked.Read(ref bytesRead),
        ZeroByteServiceCount = Interlocked.Read(ref zeroByteServiceCount),
        MaxServiceGapMs = TicksToMs(Interlocked.Read(ref maxServiceGapTicks)),
        ServiceGapOverTargetCount = gapTarget,
        ServiceGapOverHardLimitCount = gapHard,
        MaxReadDurationMs = TicksToMs(Interlocked.Read(ref maxReadDurationTicks)),
        ReadDurationOverTargetCount = durationTarget,
        ReadDurationOverHardLimitCount = durationHard,
        TargetMs = targetMs,
        HardLimitMs = hardLimitMs,
        RingCapacity = ring.Capacity,
        QueueDepth = ring.QueueDepth,
        ProducedSequence = ring.ProducedSequence,
        ConsumedSequence = ring.ConsumedSequence,
        ProducedRawBytes = ring.ProducedRawBytes,
        ConsumedRawBytes = ring.ConsumedRawBytes,
        OverflowLatched = ring.OverflowLatched,
        OverflowCount = ring.OverflowCount,
        FatalError = fatalError,
        ViolationEventCap = ViolationEventCapacity,
        ViolationEventCount = traceCount,
        ViolationEventTotalCount = traceTotal,
        ViolationEventOverflowCount = traceOverflow,
        ViolationEvents = traceEvents
      };
    }
  }

