    public bool Joined { get; internal set; }
    public bool HasFatalFailure { get; internal set; }
    public bool Valid { get; internal set; }
    public int BrokerGc0Delta { get; internal set; }
    public int BrokerGc1Delta { get; internal set; }
    public int BrokerGc2Delta { get; internal set; }
    public bool BrokerGcDuringActiveReads { get; internal set; }
