  public sealed class DualPortReaderWorker {
    public readonly RoleReader VehicleReader;
    public readonly RoleReader GroundReader;
    private long originTicks;
    private double baseElapsedMs;
    private readonly CaptureRecord vehicleConsumerRecord;
    private readonly CaptureRecord groundConsumerRecord;
    private long barrierGeneration;
    private volatile bool armed;
    private volatile bool stopRequested;
    private volatile bool joined;
    private string boundaryFailure;

    public DualPortReaderWorker(IByteSource vehicleSource,
        IByteSource groundSource, int ringCapacity, int maximumReadBytes,
        double baseElapsedMsValue, double targetMs, double hardLimitMs) {
      originTicks = Stopwatch.GetTimestamp();
      baseElapsedMs = baseElapsedMsValue;
      VehicleReader = new RoleReader("vehicle", vehicleSource,
          ringCapacity, maximumReadBytes, originTicks, baseElapsedMs,
          targetMs, hardLimitMs);
      GroundReader = new RoleReader("ground", groundSource,
          ringCapacity, maximumReadBytes, originTicks, baseElapsedMs,
          targetMs, hardLimitMs);
      vehicleConsumerRecord = new CaptureRecord(maximumReadBytes);
      groundConsumerRecord = new CaptureRecord(maximumReadBytes);
    }

    public static DualPortReaderWorker FromSerialPorts(
        __SERIAL_PORT_TYPE__ vehiclePort, __SERIAL_PORT_TYPE__ groundPort,
        int ringCapacity, int maximumReadBytes, double baseElapsedMs,
        double targetMs, double hardLimitMs) {
      return new DualPortReaderWorker(new SerialByteSource(vehiclePort),
          new SerialByteSource(groundPort), ringCapacity, maximumReadBytes,
          baseElapsedMs, targetMs, hardLimitMs);
    }
    public void ArmAt(long originTicksValue, double baseElapsedMsValue) {
      if (armed) throw new InvalidOperationException("worker already armed");
      originTicks = originTicksValue;
      baseElapsedMs = baseElapsedMsValue;
      VehicleReader.Arm(originTicks, baseElapsedMs);
      GroundReader.Arm(originTicks, baseElapsedMs);
      armed = true;
    }
    public void Arm(double baseElapsedMsValue) {
      ArmAt(Stopwatch.GetTimestamp(), baseElapsedMsValue);
    }
    public void SetCaptureContext(string phase, string epoch) {
      VehicleReader.SetCaptureContext(phase, epoch);
      GroundReader.SetCaptureContext(phase, epoch);
    }
    public void SetCaptureContextId(UInt32 contextId) {
      VehicleReader.SetCaptureContextId(contextId);
      GroundReader.SetCaptureContextId(contextId);
    }
    public void Start() {
      if (!armed) Arm(0.0);
      VehicleReader.Start();
      GroundReader.Start();
    }
    public bool TryDequeueVehicle(out CaptureRecord record) {
      record = vehicleConsumerRecord;
      return VehicleReader.TryDequeueInto(vehicleConsumerRecord);
    }
    public bool TryDequeueGround(out CaptureRecord record) {
      record = groundConsumerRecord;
      return GroundReader.TryDequeueInto(groundConsumerRecord);
    }
    private ReaderBarrier RequestBarrierAndWait(int timeoutMs,
        int transitionKind, string phase, string epoch, UInt32 contextId) {
      if (!armed) throw new InvalidOperationException("worker not armed");
      long generation = Interlocked.Increment(ref barrierGeneration);
      ReaderBarrier barrier = new ReaderBarrier { Generation = generation };
      if (transitionKind == 0) {
        VehicleReader.RequestBarrier(generation);
        GroundReader.RequestBarrier(generation);
      } else if (transitionKind == 1) {
        VehicleReader.RequestContextTransition(generation, phase, epoch);
        GroundReader.RequestContextTransition(generation, phase, epoch);
      } else if (transitionKind == 2) {
        VehicleReader.RequestContextIdTransition(generation, contextId);
        GroundReader.RequestContextIdTransition(generation, contextId);
      } else {
        throw new ArgumentOutOfRangeException("transitionKind");
      }
      Stopwatch deadline = Stopwatch.StartNew();
      bool vehicleAck = VehicleReader.WaitForBarrier(
          generation, barrier.Vehicle, timeoutMs);
      int groundTimeoutMs = Math.Max(1,
          timeoutMs - (int)Math.Min(Int32.MaxValue, deadline.ElapsedMilliseconds));
      bool groundAck = vehicleAck && GroundReader.WaitForBarrier(
          generation, barrier.Ground, groundTimeoutMs);
      if (!vehicleAck || !groundAck) {
        boundaryFailure = "dual reader boundary acknowledgement timeout";
        stopRequested = true;
        VehicleReader.RequestStop();
        GroundReader.RequestStop();
        int joinTimeout = Math.Max(1, timeoutMs / 2);
        bool vehicleJoined = VehicleReader.Join(joinTimeout);
        bool groundJoined = GroundReader.Join(joinTimeout);
        joined = vehicleJoined && groundJoined;
        throw new TimeoutException("dual reader barrier acknowledgement timeout");
      }
      long ticks = Stopwatch.GetTimestamp();
      barrier.CapturedTimestampTicks = ticks;
      barrier.CapturedElapsedMs = baseElapsedMs +
          ((double)(ticks - originTicks) * 1000.0 / Stopwatch.Frequency);
      return barrier;
    }
    public ReaderBarrier CaptureBarrier() {
      return RequestBarrierAndWait(5000, 0, null, null,
          unchecked((UInt32)0));
    }
    public ReaderBarrier TransitionCaptureContext(string phase, string epoch) {
      return RequestBarrierAndWait(5000, 1, phase, epoch,
          unchecked((UInt32)0));
    }
    public ReaderBarrier TransitionCaptureContextId(UInt32 contextId) {
      return RequestBarrierAndWait(5000, 2, null, null, contextId);
    }
    public ReaderBarrier CaptureStoppedBarrier() {
      if (!joined) throw new InvalidOperationException(
          "stopped barrier requested before joined shutdown");
      ReaderBarrier barrier = new ReaderBarrier {
        Generation = Interlocked.Read(ref barrierGeneration),
        CapturedTimestampTicks = Stopwatch.GetTimestamp()
      };
      VehicleReader.CaptureStoppedPositionInto(barrier.Vehicle);
      GroundReader.CaptureStoppedPositionInto(barrier.Ground);
      barrier.CapturedElapsedMs = baseElapsedMs +
          ((double)(barrier.CapturedTimestampTicks - originTicks) *
              1000.0 / Stopwatch.Frequency);
      return barrier;
    }
    public bool HasFatalFailure {
      get { return boundaryFailure != null || VehicleReader.HasFatalFailure ||
          GroundReader.HasFatalFailure; }
    }
    public bool StopAndJoin(int timeoutMs) {
      stopRequested = true;
      int eachTimeout = Math.Max(1, timeoutMs / 2);
      VehicleReader.RequestStop();
      GroundReader.RequestStop();
      bool vehicleJoined = VehicleReader.Join(eachTimeout);
      bool groundJoined = GroundReader.Join(eachTimeout);
      joined = vehicleJoined && groundJoined;
      return joined;
    }
    public DualReaderSnapshot Snapshot() {
      RoleReaderSnapshot vehicle = VehicleReader.Snapshot();
      RoleReaderSnapshot ground = GroundReader.Snapshot();
      bool fatal = HasFatalFailure;
      return new DualReaderSnapshot {
        Vehicle = vehicle,
        Ground = ground,
        StopRequested = stopRequested,
        Joined = joined,
        HasFatalFailure = fatal,
        Valid = vehicle.IsFair && ground.IsFair && vehicle.IsConsistent &&
            ground.IsConsistent && !fatal
      };
    }
  }

