    public bool AdminBlockPassed { get; internal set; }
    public bool FloodPassed { get; internal set; }
    public int Gc0Delta { get; internal set; }
    public int Gc1Delta { get; internal set; }
    public int Gc2Delta { get; internal set; }
    public long VehicleServiceDelta { get; internal set; }
    public long GroundServiceDelta { get; internal set; }
    public double ConsumerBlockedMs { get; internal set; }
    public DualReaderSnapshot Snapshot { get; internal set; }
