  public sealed class PowerShellPressureHarness {
    private readonly SyntheticByteSource vehicleSource;
    private readonly SyntheticByteSource groundSource;
    private readonly DualPortReaderWorker worker;
    private readonly Stopwatch consumerBlockWatch;
    private readonly long vehicleServiceStart;
    private readonly long groundServiceStart;

    internal PowerShellPressureHarness() {
      vehicleSource = new SyntheticByteSource(131072, 17);
      groundSource = new SyntheticByteSource(8192, 53);
      worker = new DualPortReaderWorker(vehicleSource, groundSource,
          8192, 32, 0.0, 75.0, 100.0);
      worker.Start();
      WaitUntil(functionVehicleStarted, 2000);
      WaitUntil(functionGroundStarted, 2000);
      vehicleServiceStart = worker.VehicleReader.Snapshot().ServiceCount;
      groundServiceStart = worker.GroundReader.Snapshot().ServiceCount;
      consumerBlockWatch = Stopwatch.StartNew();
    }
    private bool functionVehicleStarted() {
      return worker.VehicleReader.Snapshot().ServiceCount > 0;
    }
    private bool functionGroundStarted() {
      return worker.GroundReader.Snapshot().ServiceCount > 0;
    }
    private static bool WaitUntil(Func<bool> predicate, int timeoutMs) {
      Stopwatch watch = Stopwatch.StartNew();
      while (watch.ElapsedMilliseconds < timeoutMs) {
        if (predicate()) return true;
        Thread.Sleep(1);
      }
      return predicate();
    }
    public PressureHarnessResult Complete(int gc0Delta, int gc1Delta,
        int gc2Delta) {
      while ((vehicleSource.Remaining > 0 || groundSource.Remaining > 0) &&
          consumerBlockWatch.ElapsedMilliseconds < 4000) Thread.Sleep(1);
      worker.StopAndJoin(4000);
      RecordAudit vehicleAudit = WorkerHarness.DrainAndAudit(
          worker, true, vehicleSource.TotalBytes);
      RecordAudit groundAudit = WorkerHarness.DrainAndAudit(
          worker, false, groundSource.TotalBytes);
      DualReaderSnapshot snapshot = worker.Snapshot();
      long vehicleDelta = snapshot.Vehicle.ServiceCount - vehicleServiceStart;
      long groundDelta = snapshot.Ground.ServiceCount - groundServiceStart;
      bool strictFair = snapshot.Vehicle.IsFair && snapshot.Ground.IsFair;
      return new PressureHarnessResult {
        ForcedGcPassed = gc0Delta > 0 && strictFair,
        AdminBlockPassed = consumerBlockWatch.Elapsed.TotalMilliseconds >= 350.0 &&
            vehicleDelta > 20 && groundDelta > 20 && strictFair,
        FloodPassed = vehicleAudit.Valid && groundAudit.Valid &&
            !snapshot.Vehicle.OverflowLatched && !snapshot.Ground.OverflowLatched,
        Gc0Delta = gc0Delta,
        Gc1Delta = gc1Delta,
        Gc2Delta = gc2Delta,
        VehicleServiceDelta = vehicleDelta,
        GroundServiceDelta = groundDelta,
        ConsumerBlockedMs = consumerBlockWatch.Elapsed.TotalMilliseconds,
        Snapshot = snapshot,
        VehicleAudit = vehicleAudit,
        GroundAudit = groundAudit
      };
    }
  }

  public sealed class WorkerHarnessResult {
    public bool OverflowPassed { get; internal set; }
