    public long OverflowRecordCount { get; internal set; }
    public double TimestampConsumerDelayMs { get; internal set; }
    public long TimestampSequence { get; internal set; }
    public long TimestampRawStartOffset { get; internal set; }
    public RecordAudit ShutdownVehicleAudit { get; internal set; }
    public RecordAudit ShutdownGroundAudit { get; internal set; }
  }

  public enum BrokerMessageType {
    HELLO = 1,
    HELLO_ACK = 2,
    DRAIN_BOTH = 3,
    TRANSITION_CONTEXT = 4,
    WRITE_PORT = 5,
    STOP_CAPTURE = 6,
    CLOSE_EXIT = 7,
    CAPTURE_RECORD = 8,
    DRAIN_COMPLETE = 9,
    ACK = 10,
    ERROR = 11,
    OPEN_START = 12,
    WRITE_EXACT_FIXTURE = 13,
    FLUSH_PORT = 14
  }

  internal sealed class BrokerFrame {
    internal BrokerMessageType Type;
    internal long Sequence;
    internal byte[] Payload;
  }

  internal static class BrokerWire {
    internal const uint Magic = 0x42524356U;
    internal const ushort HeaderBytes = 32;
    internal const ushort ProtocolVersion = 2;
    internal const int MaximumPayloadBytes = 1048576;
    internal const int MaximumRecordsPerDrain = 512;
    internal const int MaximumAggregateRecords = 131072;
    internal const int MaximumRecordBytes = 65536;

    internal static void PutUInt16(byte[] buffer, int offset, UInt16 value) {
      buffer[offset] = (byte)value;
      buffer[offset + 1] = (byte)(value >> 8);
    }
    internal static void PutInt32(byte[] buffer, int offset, Int32 value) {
      UInt32 bits = unchecked((UInt32)value);
      for (int index = 0; index < 4; ++index) {
        buffer[offset + index] = (byte)(bits >> (8 * index));
      }
    }
    internal static void PutUInt32(byte[] buffer, int offset, UInt32 value) {
      PutInt32(buffer, offset, unchecked((Int32)value));
    }
    internal static void PutInt64(byte[] buffer, int offset, Int64 value) {
      UInt64 bits = unchecked((UInt64)value);
      for (int index = 0; index < 8; ++index) {
        buffer[offset + index] = (byte)(bits >> (8 * index));
      }
    }
    internal static UInt16 GetUInt16(byte[] buffer, int offset) {
      return (UInt16)(buffer[offset] | (buffer[offset + 1] << 8));
    }
    internal static Int32 GetInt32(byte[] buffer, int offset) {
      UInt32 value = 0;
      for (int index = 0; index < 4; ++index) {
        value |= (UInt32)buffer[offset + index] << (8 * index);
      }
      return unchecked((Int32)value);
    }
    internal static UInt32 GetUInt32(byte[] buffer, int offset) {
      return unchecked((UInt32)GetInt32(buffer, offset));
    }
    internal static Int64 GetInt64(byte[] buffer, int offset) {
      UInt64 value = 0;
      for (int index = 0; index < 8; ++index) {
        value |= (UInt64)buffer[offset + index] << (8 * index);
      }
      return unchecked((Int64)value);
    }

    internal static void ReadExact(Stream stream, byte[] destination,
        int offset, int count) {
      int completed = 0;
      while (completed < count) {
        int read = stream.Read(destination, offset + completed,
            count - completed);
        if (read <= 0) throw new EndOfStreamException(
            "reader broker pipe closed during fixed-length read");
        completed += read;
      }
    }

    internal static void WriteString(BinaryWriter writer, string value,
        int maximumBytes) {
      byte[] bytes = Encoding.UTF8.GetBytes(value ?? String.Empty);
      if (bytes.Length > maximumBytes) throw new InvalidDataException(
          "reader broker string exceeded its bounded UTF-8 length");
      writer.Write(bytes.Length);
      writer.Write(bytes);
    }

    internal static string ReadString(BinaryReader reader, int maximumBytes) {
      int count = reader.ReadInt32();
      if (count < 0 || count > maximumBytes) throw new InvalidDataException(
          "reader broker string length was outside the fixed bound");
      byte[] bytes = reader.ReadBytes(count);
      if (bytes.Length != count) throw new EndOfStreamException(
          "reader broker string payload was truncated");
      return Encoding.UTF8.GetString(bytes);
    }

    internal static void RequireEmpty(BinaryReader reader) {
      if (reader.BaseStream.Position != reader.BaseStream.Length) {
        throw new InvalidDataException("reader broker payload had trailing bytes");
      }
    }

    internal static bool FixedTimeEquals(string first, string second) {
      byte[] a = Encoding.UTF8.GetBytes(first ?? String.Empty);
      byte[] b = Encoding.UTF8.GetBytes(second ?? String.Empty);
      int different = a.Length ^ b.Length;
      int maximum = Math.Max(a.Length, b.Length);
      for (int index = 0; index < maximum; ++index) {
        byte av = index < a.Length ? a[index] : (byte)0;
        byte bv = index < b.Length ? b[index] : (byte)0;
        different |= av ^ bv;
      }
      return different == 0;
    }

    internal static void WriteBarrier(BinaryWriter writer,
        ReaderBarrier barrier) {
      writer.Write(barrier.Generation);
      writer.Write(barrier.CapturedTimestampTicks);
      writer.Write(barrier.CapturedElapsedMs);
      writer.Write(barrier.Vehicle.SequenceExclusive);
      writer.Write(barrier.Vehicle.RawOffsetExclusive);
      writer.Write(barrier.Vehicle.BoundaryTimestampTicks);
      writer.Write(barrier.Vehicle.BoundaryElapsedMs);
      writer.Write(barrier.Vehicle.OldContextId);
      writer.Write(barrier.Vehicle.NewContextId);
      writer.Write(barrier.Ground.SequenceExclusive);
      writer.Write(barrier.Ground.RawOffsetExclusive);
      writer.Write(barrier.Ground.BoundaryTimestampTicks);
      writer.Write(barrier.Ground.BoundaryElapsedMs);
      writer.Write(barrier.Ground.OldContextId);
      writer.Write(barrier.Ground.NewContextId);
    }

    internal static ReaderBarrier ReadBarrier(BinaryReader reader) {
      ReaderBarrier barrier = new ReaderBarrier();
      barrier.Generation = reader.ReadInt64();
      barrier.CapturedTimestampTicks = reader.ReadInt64();
      barrier.CapturedElapsedMs = reader.ReadDouble();
      barrier.Vehicle.SequenceExclusive = reader.ReadInt64();
      barrier.Vehicle.RawOffsetExclusive = reader.ReadInt64();
      barrier.Vehicle.BoundaryTimestampTicks = reader.ReadInt64();
      barrier.Vehicle.BoundaryElapsedMs = reader.ReadDouble();
      barrier.Vehicle.OldContextId = reader.ReadUInt32();
      barrier.Vehicle.NewContextId = reader.ReadUInt32();
      barrier.Ground.SequenceExclusive = reader.ReadInt64();
      barrier.Ground.RawOffsetExclusive = reader.ReadInt64();
      barrier.Ground.BoundaryTimestampTicks = reader.ReadInt64();
      barrier.Ground.BoundaryElapsedMs = reader.ReadDouble();
      barrier.Ground.OldContextId = reader.ReadUInt32();
      barrier.Ground.NewContextId = reader.ReadUInt32();
      return barrier;
    }

    private static void WriteViolationEvent(BinaryWriter writer,
        FairnessViolationEvent value) {
      writer.Write(value.Sequence);
      WriteString(writer, value.Kind, 32);
      writer.Write(value.StartedTimestampTicks);
      writer.Write(value.FinishedTimestampTicks);
      writer.Write(value.DurationMs);
      writer.Write(value.ContextId);
      WriteString(writer, value.Phase, 256);
      WriteString(writer, value.Epoch, 256);
      writer.Write(value.BytesRead);
      writer.Write(value.RawStartOffset);
      writer.Write(value.RawEndOffsetExclusive);
      writer.Write(value.ServiceOrdinal);
      writer.Write(value.BoundaryGeneration);
      WriteString(writer, value.BoundaryKind, 32);
    }

    private static FairnessViolationEvent ReadViolationEvent(
        BinaryReader reader) {
      return new FairnessViolationEvent {
        Sequence = reader.ReadInt64(),
        Kind = ReadString(reader, 32),
        StartedTimestampTicks = reader.ReadInt64(),
        FinishedTimestampTicks = reader.ReadInt64(),
        DurationMs = reader.ReadDouble(),
        ContextId = reader.ReadUInt32(),
        Phase = ReadString(reader, 256),
        Epoch = ReadString(reader, 256),
        BytesRead = reader.ReadInt32(),
        RawStartOffset = reader.ReadInt64(),
        RawEndOffsetExclusive = reader.ReadInt64(),
        ServiceOrdinal = reader.ReadInt64(),
        BoundaryGeneration = reader.ReadInt64(),
        BoundaryKind = ReadString(reader, 32)
      };
    }

    private static void WriteRoleSnapshot(BinaryWriter writer,
        RoleReaderSnapshot value) {
      WriteString(writer, value.Role, 32);
      writer.Write(value.Started);
      writer.Write(value.StopRequested);
      writer.Write(value.Joined);
      writer.Write(value.ThreadAlive);
      writer.Write(value.ServiceCount);
      writer.Write(value.BytesRead);
      writer.Write(value.ZeroByteServiceCount);
      writer.Write(value.MaxServiceGapMs);
      writer.Write(value.ServiceGapOverTargetCount);
      writer.Write(value.ServiceGapOverHardLimitCount);
      writer.Write(value.MaxReadDurationMs);
      writer.Write(value.ReadDurationOverTargetCount);
      writer.Write(value.ReadDurationOverHardLimitCount);
      writer.Write(value.TargetMs);
      writer.Write(value.HardLimitMs);
      writer.Write(value.RingCapacity);
      writer.Write(value.QueueDepth);
      writer.Write(value.ProducedSequence);
      writer.Write(value.ConsumedSequence);
      writer.Write(value.ProducedRawBytes);
      writer.Write(value.ConsumedRawBytes);
      writer.Write(value.OverflowLatched);
      writer.Write(value.OverflowCount);
      WriteString(writer, value.FatalError, 4096);
      if (value.ViolationEventCap != 64 ||
          value.ViolationEventCount < 0 ||
          value.ViolationEventCount > value.ViolationEventCap ||
          value.ViolationEvents == null ||
          value.ViolationEventCount != value.ViolationEvents.Length ||
          value.ViolationEventTotalCount !=
              value.ServiceGapOverTargetCount +
              value.ReadDurationOverTargetCount ||
          value.ViolationEventOverflowCount !=
              value.ViolationEventTotalCount - value.ViolationEventCount) {
        throw new InvalidDataException(
            "reader broker violation snapshot consistency failed");
      }
      writer.Write(value.ViolationEventCap);
      writer.Write(value.ViolationEventCount);
      writer.Write(value.ViolationEventTotalCount);
      writer.Write(value.ViolationEventOverflowCount);
      for (int index = 0; index < value.ViolationEventCount; ++index) {
        WriteViolationEvent(writer, value.ViolationEvents[index]);
      }
    }

    private static RoleReaderSnapshot ReadRoleSnapshot(BinaryReader reader) {
      RoleReaderSnapshot value = new RoleReaderSnapshot {
        Role = ReadString(reader, 32),
        Started = reader.ReadBoolean(),
        StopRequested = reader.ReadBoolean(),
        Joined = reader.ReadBoolean(),
        ThreadAlive = reader.ReadBoolean(),
        ServiceCount = reader.ReadInt64(),
        BytesRead = reader.ReadInt64(),
        ZeroByteServiceCount = reader.ReadInt64(),
        MaxServiceGapMs = reader.ReadDouble(),
        ServiceGapOverTargetCount = reader.ReadInt64(),
        ServiceGapOverHardLimitCount = reader.ReadInt64(),
        MaxReadDurationMs = reader.ReadDouble(),
        ReadDurationOverTargetCount = reader.ReadInt64(),
        ReadDurationOverHardLimitCount = reader.ReadInt64(),
        TargetMs = reader.ReadDouble(),
        HardLimitMs = reader.ReadDouble(),
        RingCapacity = reader.ReadInt32(),
        QueueDepth = reader.ReadInt32(),
        ProducedSequence = reader.ReadInt64(),
        ConsumedSequence = reader.ReadInt64(),
        ProducedRawBytes = reader.ReadInt64(),
        ConsumedRawBytes = reader.ReadInt64(),
        OverflowLatched = reader.ReadBoolean(),
        OverflowCount = reader.ReadInt64(),
        FatalError = ReadString(reader, 4096)
      };
      value.ViolationEventCap = reader.ReadInt32();
      value.ViolationEventCount = reader.ReadInt32();
      value.ViolationEventTotalCount = reader.ReadInt64();
      value.ViolationEventOverflowCount = reader.ReadInt64();
      if (value.ViolationEventCap != 64 ||
          value.ViolationEventCount < 0 ||
          value.ViolationEventCount > value.ViolationEventCap ||
          value.ViolationEventTotalCount !=
              value.ServiceGapOverTargetCount +
              value.ReadDurationOverTargetCount ||
          value.ViolationEventOverflowCount !=
              value.ViolationEventTotalCount - value.ViolationEventCount) {
        throw new InvalidDataException(
            "reader broker violation snapshot bounds failed");
      }
      value.ViolationEvents =
          new FairnessViolationEvent[value.ViolationEventCount];
      for (int index = 0; index < value.ViolationEventCount; ++index) {
        FairnessViolationEvent item = ReadViolationEvent(reader);
        if (item.Sequence < 0 || item.StartedTimestampTicks <= 0 ||
            item.FinishedTimestampTicks < item.StartedTimestampTicks ||
            item.DurationMs < value.TargetMs ||
            (item.Kind != "service_gap" && item.Kind != "read_duration")) {
          throw new InvalidDataException(
              "reader broker violation event content failed");
        }
        value.ViolationEvents[index] = item;
      }
      return value;
    }

    internal static void WriteSnapshot(BinaryWriter writer,
        DualReaderSnapshot value) {
      WriteRoleSnapshot(writer, value.Vehicle);
      WriteRoleSnapshot(writer, value.Ground);
      writer.Write(value.StopRequested);
      writer.Write(value.Joined);
      writer.Write(value.HasFatalFailure);
      writer.Write(value.Valid);
      writer.Write(value.BrokerGc0Delta);
      writer.Write(value.BrokerGc1Delta);
      writer.Write(value.BrokerGc2Delta);
      writer.Write(value.BrokerGcDuringActiveReads);
      writer.Write(value.BrokerPressureElapsedMs);
    }

    internal static DualReaderSnapshot ReadSnapshot(BinaryReader reader) {
      return new DualReaderSnapshot {
        Vehicle = ReadRoleSnapshot(reader),
        Ground = ReadRoleSnapshot(reader),
        StopRequested = reader.ReadBoolean(),
        Joined = reader.ReadBoolean(),
        HasFatalFailure = reader.ReadBoolean(),
        Valid = reader.ReadBoolean(),
        BrokerGc0Delta = reader.ReadInt32(),
        BrokerGc1Delta = reader.ReadInt32(),
        BrokerGc2Delta = reader.ReadInt32(),
        BrokerGcDuringActiveReads = reader.ReadBoolean(),
        BrokerPressureElapsedMs = reader.ReadDouble()
      };
    }

    internal static CaptureRecord DecodeRecord(byte[] payload) {
      using (MemoryStream memory = new MemoryStream(payload, false))
      using (BinaryReader reader = new BinaryReader(memory)) {
        byte role = reader.ReadByte();
        if (role != 1 && role != 2) throw new InvalidDataException(
            "reader broker record role was invalid");
        long sequence = reader.ReadInt64();
        long rawStartOffset = reader.ReadInt64();
        long ticks = reader.ReadInt64();
        double elapsedMs = reader.ReadDouble();
        int count = reader.ReadInt32();
        if (count < 0 || count > MaximumRecordBytes) {
          throw new InvalidDataException(
              "reader broker record byte count exceeded its bound");
        }
        UInt32 contextId = reader.ReadUInt32();
        byte[] bytes = reader.ReadBytes(count);
        if (bytes.Length != count) throw new EndOfStreamException(
            "reader broker record bytes were truncated");
        RequireEmpty(reader);
        CaptureRecord record = new CaptureRecord(Math.Max(1, count));
        record.Role = role == 1 ? "vehicle" : "ground";
        record.Sequence = sequence;
        record.RawStartOffset = rawStartOffset;
        record.ProducerTimestampTicks = ticks;
        record.ProducerElapsedMs = elapsedMs;
        record.Count = count;
        record.ProducerPhase = null;
        record.ProducerEpoch = null;
        record.ContextId = contextId;
        if (count > 0) Buffer.BlockCopy(bytes, 0, record.Bytes, 0, count);
        return record;
      }
    }
  }

  internal sealed class BrokerChannel : IDisposable {
    private readonly Stream stream;
    private readonly object sendGate = new object();
    private long sentSequence;
    private long receivedSequence;
    private readonly byte[] sendHeader = new byte[BrokerWire.HeaderBytes];
    private readonly byte[] receiveHeader = new byte[BrokerWire.HeaderBytes];
    private readonly byte[] recordSendBuffer =
        new byte[41 + BrokerWire.MaximumRecordBytes];

    internal BrokerChannel(Stream streamValue) {
      if (streamValue == null) throw new ArgumentNullException("streamValue");
      stream = streamValue;
    }

    internal long SentSequence { get { return Interlocked.Read(ref sentSequence); } }
    internal long ReceivedSequence { get { return Interlocked.Read(ref receivedSequence); } }

    private void SendCore(BrokerMessageType type, byte[] body,
        int bodyLength) {
      if (bodyLength < 0 || bodyLength > BrokerWire.MaximumPayloadBytes) {
        throw new InvalidDataException("reader broker payload exceeded fixed bound");
      }
      long sequence = sentSequence + 1;
      BrokerWire.PutUInt32(sendHeader, 0, BrokerWire.Magic);
      BrokerWire.PutUInt16(sendHeader, 4, BrokerWire.HeaderBytes);
      BrokerWire.PutUInt16(sendHeader, 6, BrokerWire.ProtocolVersion);
      BrokerWire.PutInt32(sendHeader, 8, (int)type);
      BrokerWire.PutInt32(sendHeader, 12, 0);
      BrokerWire.PutInt64(sendHeader, 16, sequence);
      BrokerWire.PutInt32(sendHeader, 24, bodyLength);
      BrokerWire.PutInt32(sendHeader, 28, 0);
      stream.Write(sendHeader, 0, sendHeader.Length);
      if (bodyLength > 0) stream.Write(body, 0, bodyLength);
      stream.Flush();
      Interlocked.Exchange(ref sentSequence, sequence);
    }

    internal void Send(BrokerMessageType type, byte[] payload) {
      byte[] body = payload ?? new byte[0];
      lock (sendGate) { SendCore(type, body, body.Length); }
    }

    internal void SendCaptureRecord(CaptureRecord record) {
      if (record == null || record.Count < 0 ||
          record.Count > BrokerWire.MaximumRecordBytes) {
        throw new InvalidDataException("capture record send bound failed");
      }
      lock (sendGate) {
        recordSendBuffer[0] = record.Role == "vehicle" ? (byte)1 : (byte)2;
        BrokerWire.PutInt64(recordSendBuffer, 1, record.Sequence);
        BrokerWire.PutInt64(recordSendBuffer, 9, record.RawStartOffset);
        BrokerWire.PutInt64(recordSendBuffer, 17,
            record.ProducerTimestampTicks);
        BrokerWire.PutInt64(recordSendBuffer, 25,
            BitConverter.DoubleToInt64Bits(record.ProducerElapsedMs));
        BrokerWire.PutInt32(recordSendBuffer, 33, record.Count);
        BrokerWire.PutUInt32(recordSendBuffer, 37, record.ContextId);
        if (record.Count > 0) Buffer.BlockCopy(
            record.Bytes, 0, recordSendBuffer, 41, record.Count);
        SendCore(BrokerMessageType.CAPTURE_RECORD, recordSendBuffer,
            41 + record.Count);
      }
    }

    private void ReadExactWithDeadline(byte[] destination, int offset,
        int count, int timeoutMs) {
      if (timeoutMs == Timeout.Infinite) {
        BrokerWire.ReadExact(stream, destination, offset, count);
        return;
      }
      Stopwatch deadline = Stopwatch.StartNew();
      int completed = 0;
      while (completed < count) {
        int remainingMs = timeoutMs - (int)deadline.ElapsedMilliseconds;
        if (remainingMs <= 0) {
          try { stream.Dispose(); } catch { }
          throw new TimeoutException("reader broker bounded receive timeout");
        }
        IAsyncResult pending = stream.BeginRead(destination,
            offset + completed, count - completed, null, null);
        bool signaled = false;
        signaled = pending.AsyncWaitHandle.WaitOne(remainingMs);
        if (!signaled) {
          pending.AsyncWaitHandle.Close();
          try { stream.Dispose(); } catch { }
          throw new TimeoutException("reader broker bounded receive timeout");
        }
        int read;
        try { read = stream.EndRead(pending); }
        finally { pending.AsyncWaitHandle.Close(); }
        if (read <= 0) throw new EndOfStreamException(
            "reader broker pipe closed during bounded receive");
        completed += read;
      }
    }

    internal BrokerFrame Receive() { return Receive(Timeout.Infinite); }

    internal BrokerFrame Receive(int timeoutMs) {
      if (timeoutMs != Timeout.Infinite && timeoutMs <= 0) {
        throw new ArgumentOutOfRangeException("timeoutMs");
      }
      Stopwatch receiveWatch = Stopwatch.StartNew();
      ReadExactWithDeadline(receiveHeader, 0, receiveHeader.Length, timeoutMs);
      uint magic = BrokerWire.GetUInt32(receiveHeader, 0);
      ushort headerBytes = BrokerWire.GetUInt16(receiveHeader, 4);
      ushort version = BrokerWire.GetUInt16(receiveHeader, 6);
      int typeValue = BrokerWire.GetInt32(receiveHeader, 8);
      int flags = BrokerWire.GetInt32(receiveHeader, 12);
      long sequence = BrokerWire.GetInt64(receiveHeader, 16);
      int payloadLength = BrokerWire.GetInt32(receiveHeader, 24);
      int reserved = BrokerWire.GetInt32(receiveHeader, 28);
      if (magic != BrokerWire.Magic || headerBytes != BrokerWire.HeaderBytes ||
          version != BrokerWire.ProtocolVersion || flags != 0 || reserved != 0) {
        throw new InvalidDataException(
            "reader broker fixed header validation failed");
      }
      if (!Enum.IsDefined(typeof(BrokerMessageType), typeValue)) {
        throw new InvalidDataException("reader broker message type was invalid");
      }
      long expected = receivedSequence + 1;
      if (sequence != expected) throw new InvalidDataException(
          "reader broker protocol sequence discontinuity");
      if (payloadLength < 0 || payloadLength > BrokerWire.MaximumPayloadBytes) {
        throw new InvalidDataException(
            "reader broker payload length exceeded fixed bound");
      }
      byte[] payload = new byte[payloadLength];
      if (payloadLength > 0) {
        int remainingMs = timeoutMs == Timeout.Infinite ? Timeout.Infinite :
            timeoutMs - (int)receiveWatch.ElapsedMilliseconds;
        ReadExactWithDeadline(payload, 0, payloadLength, remainingMs);
      }
      Interlocked.Exchange(ref receivedSequence, sequence);
      return new BrokerFrame { Type = (BrokerMessageType)typeValue,
          Sequence = sequence, Payload = payload };
    }

    public void Dispose() { stream.Dispose(); }
  }

  public interface IBrokerPort : IByteSource, IDisposable {
    void Write(byte[] bytes, int offset, int count);
    void Flush();
    long WrittenBytes { get; }
    long WriteOperationCount { get; }
    long FlushCount { get; }
    long LastWriteOperationOrdinal { get; }
    long LastFlushOperationOrdinal { get; }
    int WriteTimeout { get; set; }
  }

  internal sealed class SerialBrokerPort : IBrokerPort {
    private readonly __SERIAL_PORT_TYPE__ port;
    private readonly object ioGate = new object();
    private long writtenBytes;
    private long writeOperationCount;
    private long flushCount;
    private long operationOrdinal;
    private long lastWriteOperationOrdinal;
    private long lastFlushOperationOrdinal;
    internal SerialBrokerPort(__SERIAL_PORT_TYPE__ value) { port = value; }
    public bool IsOpen { get { return port.IsOpen; } }
    public int Available { get { lock (ioGate) { return port.BytesToRead; } } }
    public int Read(byte[] buffer, int offset, int count) {
      lock (ioGate) { return port.Read(buffer, offset, count); }
    }
    public void Write(byte[] bytes, int offset, int count) {
      lock (ioGate) {
        port.Write(bytes, offset, count);
        writtenBytes += count;
        ++writeOperationCount;
        lastWriteOperationOrdinal = ++operationOrdinal;
      }
    }
    public void Flush() {
      lock (ioGate) {
        port.BaseStream.Flush();
        ++flushCount;
        lastFlushOperationOrdinal = ++operationOrdinal;
      }
    }
    public long WrittenBytes { get { return Interlocked.Read(ref writtenBytes); } }
    public long WriteOperationCount {
      get { return Interlocked.Read(ref writeOperationCount); }
    }
    public long FlushCount { get { return Interlocked.Read(ref flushCount); } }
    public long LastWriteOperationOrdinal {
      get { return Interlocked.Read(ref lastWriteOperationOrdinal); }
    }
    public long LastFlushOperationOrdinal {
      get { return Interlocked.Read(ref lastFlushOperationOrdinal); }
    }
    public int WriteTimeout {
      get { return port.WriteTimeout; }
      set { port.WriteTimeout = value; }
    }
    public void Dispose() {
      try { if (port.IsOpen) port.Close(); } finally { port.Dispose(); }
    }
  }

  internal class SyntheticBrokerPort : IBrokerPort {
    private readonly object gate = new object();
    private readonly byte[] bytes;
    private int offset;
    private long writtenBytes;
    private long writeOperationCount;
    private long flushCount;
    private long operationOrdinal;
    private long lastWriteOperationOrdinal;
    private long lastFlushOperationOrdinal;
    private int writeTimeout = 2000;
    internal SyntheticBrokerPort(int byteCount, int seed) {
      if (byteCount < 0) throw new ArgumentOutOfRangeException("byteCount");
      bytes = new byte[byteCount];
      for (int index = 0; index < byteCount; ++index) {
        bytes[index] = (byte)((seed + index * 29) & 0xff);
      }
    }
    public virtual bool IsOpen { get { return true; } }
    public virtual int Available {
      get { lock (gate) { return bytes.Length - offset; } }
    }
    public virtual int Read(byte[] buffer, int destinationOffset, int count) {
      lock (gate) {
        int wanted = Math.Min(count, bytes.Length - offset);
        if (wanted <= 0) return 0;
        Buffer.BlockCopy(bytes, offset, buffer, destinationOffset, wanted);
        offset += wanted;
        return wanted;
      }
    }
    public void Write(byte[] value, int sourceOffset, int count) {
      lock (gate) {
        writtenBytes += count;
        ++writeOperationCount;
        lastWriteOperationOrdinal = ++operationOrdinal;
      }
    }
    public void Flush() {
      lock (gate) {
        ++flushCount;
        lastFlushOperationOrdinal = ++operationOrdinal;
      }
    }
    public long WrittenBytes { get { return Interlocked.Read(ref writtenBytes); } }
    public long WriteOperationCount {
      get { return Interlocked.Read(ref writeOperationCount); }
    }
    public long FlushCount { get { return Interlocked.Read(ref flushCount); } }
    public long LastWriteOperationOrdinal {
      get { return Interlocked.Read(ref lastWriteOperationOrdinal); }
    }
    public long LastFlushOperationOrdinal {
      get { return Interlocked.Read(ref lastFlushOperationOrdinal); }
    }
    public int WriteTimeout {
      get { return writeTimeout; }
      set { writeTimeout = value; }
    }
    public void Dispose() { }
  }

  internal sealed class DelayedSyntheticBrokerPort : SyntheticBrokerPort {
    private readonly int firstReadDelayMs;
    private int firstRead = 1;
    internal DelayedSyntheticBrokerPort(int byteCount, int seed, int delayMs)
        : base(byteCount, seed) { firstReadDelayMs = delayMs; }
    public override int Read(byte[] buffer, int offset, int count) {
      if (Interlocked.Exchange(ref firstRead, 0) == 1) {
        Thread.Sleep(firstReadDelayMs);
      }
      return base.Read(buffer, offset, count);
    }
  }

  internal sealed class TimedReleaseSyntheticBrokerPort : IBrokerPort {
    private readonly object gate = new object();
    private readonly byte[] bytes;
    private readonly int releaseDurationMs;
    private int offset;
    private long writtenBytes;
    private long writeOperationCount;
    private long flushCount;
    private long operationOrdinal;
    private long lastWriteOperationOrdinal;
    private long lastFlushOperationOrdinal;
    private int writeTimeout = 2000;
    private Stopwatch releaseWatch;
    internal TimedReleaseSyntheticBrokerPort(int byteCount, int seed,
        int durationMs) {
      if (byteCount < 0 || durationMs <= 0) {
        throw new ArgumentOutOfRangeException("byteCount");
      }
      bytes = new byte[byteCount];
      releaseDurationMs = durationMs;
      for (int index = 0; index < byteCount; ++index) {
        bytes[index] = (byte)((seed + index * 29) & 0xff);
      }
    }
    internal void StartRelease() {
      lock (gate) {
        if (releaseWatch == null) releaseWatch = Stopwatch.StartNew();
      }
    }
    private int ReleasedCount() {
      if (releaseWatch == null) return 0;
      long elapsed = releaseWatch.ElapsedMilliseconds;
      if (elapsed >= releaseDurationMs) return bytes.Length;
      return (int)Math.Min(bytes.Length,
          ((long)bytes.Length * Math.Max(0, elapsed)) / releaseDurationMs);
    }
    public bool IsOpen { get { return true; } }
    public int Available {
      get { lock (gate) { return Math.Max(0, ReleasedCount() - offset); } }
    }
    public int Read(byte[] destination, int destinationOffset, int count) {
      lock (gate) {
        int wanted = Math.Min(count, Math.Max(0, ReleasedCount() - offset));
        if (wanted <= 0) return 0;
        Buffer.BlockCopy(bytes, offset, destination, destinationOffset, wanted);
        offset += wanted;
        return wanted;
      }
    }
    public void Write(byte[] value, int sourceOffset, int count) {
      lock (gate) {
        writtenBytes += count;
        ++writeOperationCount;
        lastWriteOperationOrdinal = ++operationOrdinal;
      }
    }
    public void Flush() {
      lock (gate) {
        ++flushCount;
        lastFlushOperationOrdinal = ++operationOrdinal;
      }
    }
    public long WrittenBytes { get { return Interlocked.Read(ref writtenBytes); } }
    public long WriteOperationCount {
      get { return Interlocked.Read(ref writeOperationCount); }
    }
    public long FlushCount { get { return Interlocked.Read(ref flushCount); } }
    public long LastWriteOperationOrdinal {
      get { return Interlocked.Read(ref lastWriteOperationOrdinal); }
    }
    public long LastFlushOperationOrdinal {
      get { return Interlocked.Read(ref lastFlushOperationOrdinal); }
    }
    public int WriteTimeout {
      get { return writeTimeout; }
      set { writeTimeout = value; }
    }
    internal double ReleaseElapsedMs {
      get { lock (gate) { return releaseWatch == null ? 0.0 :
          releaseWatch.Elapsed.TotalMilliseconds; } }
    }
    public void Dispose() { }
  }

  public sealed class BrokerDrainResult {
    public CaptureRecord[] Records { get; internal set; }
    public ReaderBarrier Barrier { get; internal set; }
    public DualReaderSnapshot Snapshot { get; internal set; }
    public bool Stopped { get; internal set; }
    public int BoundedRecordCount { get; internal set; }
    public long ProtocolSequence { get; internal set; }
    public UInt32 ContextId { get; internal set; }
    public long QpcFrequency { get; internal set; }
  }

  internal sealed class FixedClientRecordQueue {
    private readonly CaptureRecord[] slots;
    private int head;
    private int tail;
    private int count;
    private int highWater;
    internal FixedClientRecordQueue(int capacity) {
      if (capacity <= 0 || capacity > 65536) {
        throw new ArgumentOutOfRangeException("capacity");
      }
      slots = new CaptureRecord[capacity];
    }
    internal int Capacity { get { return slots.Length; } }
    internal int Count { get { return count; } }
    internal int HighWater { get { return highWater; } }
    internal bool TryEnqueue(CaptureRecord record) {
      if (count == slots.Length) return false;
      slots[tail] = record;
      tail = (tail + 1) % slots.Length;
      ++count;
      if (count > highWater) highWater = count;
      return true;
    }
    internal bool TryDequeue(out CaptureRecord record) {
      if (count == 0) { record = null; return false; }
      record = slots[head];
      slots[head] = null;
      head = (head + 1) % slots.Length;
      --count;
      return true;
    }
  }

