    public long GroundFlushCount { get; internal set; }
    public long GroundLastWriteOperationOrdinal { get; internal set; }
    public long GroundLastFlushOperationOrdinal { get; internal set; }
    public long VehicleWrittenBytes { get; internal set; }
    public long VehicleWriteOperationCount { get; internal set; }
    public long VehicleFlushCount { get; internal set; }
    public long VehicleLastWriteOperationOrdinal { get; internal set; }
    public long VehicleLastFlushOperationOrdinal { get; internal set; }
  }

  public sealed class ReaderBrokerServer {
    private readonly string pipeName;
    private readonly string secret;
    private readonly string sourceSha256;
    private readonly int parentPid;
    private readonly int ringCapacity;
    private readonly int maximumReadBytes;
    private readonly double targetMs;
    private readonly double hardLimitMs;
    private IBrokerPort vehiclePort;
    private IBrokerPort groundPort;
    private bool serialMode;
    private string serialVehicleName;
    private int serialVehicleBaud;
    private string serialGroundName;
    private int serialGroundBaud;
    private long helloOriginTicks;
    private double helloBaseElapsedMs;
    private string syntheticScenario;
    private Thread pressureGcThread;
    private int pressureGc0Delta;
    private int pressureGc1Delta;
    private int pressureGc2Delta;
    private volatile bool pressureGcDuringActiveReads;
    private NamedPipeServerStream pipe;
    private BrokerChannel channel;
    private DualPortReaderWorker worker;
    private Thread parentWatchdog;
    private volatile bool watchdogStop;
    private bool captureStopped;
    private bool captureStarted;
    private bool orderlyClose;
    private bool exactFixtureAccepted;
    private bool exactFixtureAttempted;
    private long sentVehicleSequence;
    private long sentVehicleOffset;
    private long sentGroundSequence;
    private long sentGroundOffset;
    private UInt32 contextId;

    private ReaderBrokerServer(string pipeNameValue, string secretValue,
        string sourceSha256Value, int parentPidValue, int ringCapacityValue,
        int maximumReadBytesValue, double targetMsValue, double hardLimitMsValue,
        IBrokerPort vehiclePortValue, IBrokerPort groundPortValue) {
      pipeName = pipeNameValue;
      secret = secretValue;
      sourceSha256 = sourceSha256Value;
      parentPid = parentPidValue;
      ringCapacity = ringCapacityValue;
      maximumReadBytes = maximumReadBytesValue;
      targetMs = targetMsValue;
      hardLimitMs = hardLimitMsValue;
      vehiclePort = vehiclePortValue;
      groundPort = groundPortValue;
    }

    private static __SERIAL_PORT_TYPE__ NewSerialPort(string name, int baud) {
      __SERIAL_PORT_TYPE__ port = new __SERIAL_PORT_TYPE__();
      port.PortName = name;
      port.BaudRate = baud;
      port.DataBits = 8;
      port.Parity = System.IO.Ports.Parity.None;
      port.StopBits = System.IO.Ports.StopBits.One;
      port.Handshake = System.IO.Ports.Handshake.None;
      port.DtrEnable = false;
      port.RtsEnable = false;
      port.ReadTimeout = 20;
      port.WriteTimeout = 2000;
      return port;
    }

    public static int RunSerial(string pipeName, string secret,
        string sourceSha256, int parentPid, string vehiclePortName,
        int vehicleBaud, string groundPortName, int groundBaud,
        int ringCapacity, int maximumReadBytes, double targetMs,
        double hardLimitMs) {
      ReaderBrokerServer server = new ReaderBrokerServer(pipeName, secret,
          sourceSha256, parentPid, ringCapacity, maximumReadBytes,
          targetMs, hardLimitMs, null, null);
      server.serialMode = true;
      server.serialVehicleName = vehiclePortName;
      server.serialVehicleBaud = vehicleBaud;
      server.serialGroundName = groundPortName;
      server.serialGroundBaud = groundBaud;
      return server.Run();
    }

    public static int RunSynthetic(string pipeName, string secret,
        string sourceSha256, int parentPid, string scenario,
        int ringCapacity, int vehicleBytes, int groundBytes,
        int maximumReadBytes, double targetMs, double hardLimitMs) {
      int actualVehicleBytes = vehicleBytes;
      int actualGroundBytes = groundBytes;
      if (scenario == "pressure") {
        if (actualVehicleBytes == 0) actualVehicleBytes = 131072;
        if (actualGroundBytes == 0) actualGroundBytes = 8192;
      } else if (scenario == "overflow") {
        if (actualVehicleBytes == 0) actualVehicleBytes = 1024;
      } else if (scenario == "timestamp") {
        if (actualVehicleBytes == 0) actualVehicleBytes = 32;
      } else if (scenario == "barrier") {
        if (actualVehicleBytes == 0) actualVehicleBytes = 32;
      } else if (scenario == "ackloss") {
        actualVehicleBytes = 0;
        actualGroundBytes = 0;
      } else if (scenario == "openio") {
        actualVehicleBytes = 0;
        actualGroundBytes = 0;
      } else {
        throw new ArgumentException("unsupported synthetic broker scenario");
      }
      IBrokerPort vehicle = scenario == "pressure" ?
          (IBrokerPort)new TimedReleaseSyntheticBrokerPort(
              actualVehicleBytes, 17, 700) : scenario == "barrier" ?
          (IBrokerPort)new DelayedSyntheticBrokerPort(
              actualVehicleBytes, 17, 250) :
          (IBrokerPort)new SyntheticBrokerPort(actualVehicleBytes, 17);
      IBrokerPort ground = scenario == "pressure" ?
          (IBrokerPort)new TimedReleaseSyntheticBrokerPort(
              actualGroundBytes, 53, 700) :
          (IBrokerPort)new SyntheticBrokerPort(actualGroundBytes, 53);
      ReaderBrokerServer server = new ReaderBrokerServer(pipeName, secret,
          sourceSha256, parentPid, ringCapacity, maximumReadBytes,
          targetMs, hardLimitMs, vehicle, ground);
      server.syntheticScenario = scenario;
      return server.Run();
    }

    private void StartPressureGc() {
      if (syntheticScenario != "pressure") return;
      pressureGcThread = new Thread(new ThreadStart(delegate {
        Thread.Sleep(125);
        DualReaderSnapshot before = worker.Snapshot();
        int gc0 = GC.CollectionCount(0);
        int gc1 = GC.CollectionCount(1);
        int gc2 = GC.CollectionCount(2);
        byte[][] pressure = new byte[48][];
        for (int index = 0; index < pressure.Length; ++index) {
          pressure[index] = new byte[262144];
          pressure[index][0] = (byte)index;
        }
        pressure = null;
        GC.Collect(GC.MaxGeneration, GCCollectionMode.Forced);
        GC.WaitForPendingFinalizers();
        GC.Collect(GC.MaxGeneration, GCCollectionMode.Forced);
        Thread.Sleep(25);
        DualReaderSnapshot after = worker.Snapshot();
        pressureGc0Delta = GC.CollectionCount(0) - gc0;
        pressureGc1Delta = GC.CollectionCount(1) - gc1;
        pressureGc2Delta = GC.CollectionCount(2) - gc2;
        pressureGcDuringActiveReads =
            before.Vehicle.BytesRead > 0 && before.Ground.BytesRead > 0 &&
            after.Vehicle.BytesRead > before.Vehicle.BytesRead &&
            after.Ground.BytesRead > before.Ground.BytesRead;
      }));
      pressureGcThread.IsBackground = true;
      pressureGcThread.Name = "VcReaderBroker-PressureFullGc";
      pressureGcThread.Start();
    }

    private DualReaderSnapshot DecorateSnapshot(DualReaderSnapshot snapshot) {
      snapshot.BrokerGc0Delta = pressureGc0Delta;
      snapshot.BrokerGc1Delta = pressureGc1Delta;
      snapshot.BrokerGc2Delta = pressureGc2Delta;
      snapshot.BrokerGcDuringActiveReads = pressureGcDuringActiveReads;
      TimedReleaseSyntheticBrokerPort timed =
          vehiclePort as TimedReleaseSyntheticBrokerPort;
      snapshot.BrokerPressureElapsedMs = timed == null ? 0.0 :
          timed.ReleaseElapsedMs;
      return snapshot;
    }

    private void StartParentWatchdog() {
      if (parentPid <= 0) return;
      parentWatchdog = new Thread(new ThreadStart(delegate {
        try {
          using (Process parent = Process.GetProcessById(parentPid)) {
            while (!watchdogStop && !parent.HasExited) Thread.Sleep(50);
            if (!watchdogStop && pipe != null) {
              try { pipe.Dispose(); } catch { }
            }
          }
        } catch {
          if (!watchdogStop && pipe != null) {
            try { pipe.Dispose(); } catch { }
          }
        }
      }));
      parentWatchdog.IsBackground = true;
      parentWatchdog.Name = "VcReaderBroker-ParentWatchdog";
      parentWatchdog.Start();
    }

    private static byte[] MakePayload(Action<BinaryWriter> write) {
      using (MemoryStream memory = new MemoryStream())
      using (BinaryWriter writer = new BinaryWriter(memory)) {
        write(writer);
        writer.Flush();
        return memory.ToArray();
      }
    }

    private static string Sha256Hex(byte[] bytes) {
      using (SHA256 algorithm = SHA256.Create()) {
        byte[] hash = algorithm.ComputeHash(bytes);
        StringBuilder text = new StringBuilder(64);
        for (int index = 0; index < hash.Length; ++index) {
          text.Append(hash[index].ToString("X2"));
        }
        return text.ToString();
      }
    }

    private void SendError(Exception error) {
      try {
        channel.Send(BrokerMessageType.ERROR, MakePayload(delegate(BinaryWriter w) {
          BrokerWire.WriteString(w, error.GetType().FullName + ": " +
              error.Message, 4096);
        }));
      } catch { }
    }

    private void AcceptHello(BrokerFrame frame) {
      if (frame.Type != BrokerMessageType.HELLO) throw new InvalidDataException(
          "reader broker first message was not HELLO");
      long originTicks;
      double baseElapsedMs;
      string nonce;
      using (MemoryStream memory = new MemoryStream(frame.Payload, false))
      using (BinaryReader reader = new BinaryReader(memory)) {
        string suppliedSecret = BrokerWire.ReadString(reader, 256);
        string suppliedSha = BrokerWire.ReadString(reader, 64);
        long suppliedFrequency = reader.ReadInt64();
        originTicks = reader.ReadInt64();
        baseElapsedMs = reader.ReadDouble();
        int suppliedParentPid = reader.ReadInt32();
        nonce = BrokerWire.ReadString(reader, 128);
        BrokerWire.RequireEmpty(reader);
        if (!BrokerWire.FixedTimeEquals(secret, suppliedSecret)) {
          throw new UnauthorizedAccessException(
              "reader broker HELLO secret mismatch");
        }
        if (!String.Equals(sourceSha256, suppliedSha,
            StringComparison.OrdinalIgnoreCase)) {
          throw new UnauthorizedAccessException(
              "reader broker HELLO runner SHA-256 mismatch");
        }
        if (suppliedFrequency != Stopwatch.Frequency || originTicks <= 0) {
          throw new InvalidDataException(
              "reader broker HELLO QPC mapping mismatch");
        }
        if (suppliedParentPid != parentPid || nonce.Length != 64) {
          throw new UnauthorizedAccessException(
              "reader broker HELLO parent PID/nonce mismatch");
        }
      }
      helloOriginTicks = originTicks;
      helloBaseElapsedMs = baseElapsedMs;
      channel.Send(BrokerMessageType.HELLO_ACK,
          MakePayload(delegate(BinaryWriter writer) {
            writer.Write((int)BrokerWire.ProtocolVersion);
            BrokerWire.WriteString(writer, sourceSha256, 64);
            writer.Write(Stopwatch.Frequency);
            writer.Write(ringCapacity);
            writer.Write(BrokerWire.MaximumRecordsPerDrain);
            BrokerWire.WriteString(writer, "broker_owns_both_serial_ports", 64);
            writer.Write(maximumReadBytes);
            writer.Write(targetMs);
            writer.Write(hardLimitMs);
            writer.Write(20);
            writer.Write(2000);
            BrokerWire.WriteString(writer, "vehicle", 32);
            BrokerWire.WriteString(writer, "ground", 32);
            BrokerWire.WriteString(writer,
                serialMode ? "serial" : syntheticScenario, 32);
            BrokerWire.WriteString(writer,
                serialMode ? serialVehicleName : "", 256);
            writer.Write(serialMode ? serialVehicleBaud : 0);
            BrokerWire.WriteString(writer,
                serialMode ? serialGroundName : "", 256);
            writer.Write(serialMode ? serialGroundBaud : 0);
            writer.Write(parentPid);
            writer.Write(Process.GetCurrentProcess().Id);
            BrokerWire.WriteString(writer, nonce, 128);
          }));
    }

    private void OpenAndStartCapture() {
      if (captureStarted) throw new InvalidOperationException(
          "OPEN_START must occur exactly once");
      if (syntheticScenario == "openio") {
        throw new IOException("OPEN_START synthetic IOException");
      }
      if (serialMode) {
        __SERIAL_PORT_TYPE__ vehicle =
            NewSerialPort(serialVehicleName, serialVehicleBaud);
        __SERIAL_PORT_TYPE__ ground =
            NewSerialPort(serialGroundName, serialGroundBaud);
        try {
          vehiclePort = new SerialBrokerPort(vehicle);
          groundPort = new SerialBrokerPort(ground);
          worker = new DualPortReaderWorker(vehiclePort, groundPort,
              ringCapacity, maximumReadBytes, helloBaseElapsedMs,
              targetMs, hardLimitMs);
          worker.ArmAt(helloOriginTicks, helloBaseElapsedMs);
          worker.SetCaptureContext("", "");
          worker.SetCaptureContextId(contextId);
          GC.Collect();
          GC.WaitForPendingFinalizers();
          GC.Collect();
          try { vehicle.Open(); }
          catch (Exception error) {
            throw new IOException("OPEN_START vehicle COM open failed: " +
                error.GetType().FullName + ": " + error.Message, error);
          }
          try { ground.Open(); }
          catch (Exception error) {
            throw new IOException("OPEN_START ground COM open failed: " +
                error.GetType().FullName + ": " + error.Message, error);
          }
        } catch {
          try { if (groundPort != null) groundPort.Dispose(); } catch { }
          try { if (vehiclePort != null) vehiclePort.Dispose(); } catch { }
          groundPort = null;
          vehiclePort = null;
          throw;
        }
      }
      if (vehiclePort == null || groundPort == null) {
        throw new InvalidOperationException(
            "OPEN_START did not establish both broker-owned sources");
      }
      if (worker == null) {
        worker = new DualPortReaderWorker(vehiclePort, groundPort,
            ringCapacity, maximumReadBytes, helloBaseElapsedMs,
            targetMs, hardLimitMs);
        worker.ArmAt(helloOriginTicks, helloBaseElapsedMs);
        worker.SetCaptureContext("", "");
        worker.SetCaptureContextId(contextId);
      }
      TimedReleaseSyntheticBrokerPort timedVehicle =
          vehiclePort as TimedReleaseSyntheticBrokerPort;
      TimedReleaseSyntheticBrokerPort timedGround =
          groundPort as TimedReleaseSyntheticBrokerPort;
      if (timedVehicle != null) timedVehicle.StartRelease();
      if (timedGround != null) timedGround.StartRelease();
      worker.Start();
      StartPressureGc();
      captureStarted = true;
    }

    private void SendRecord(CaptureRecord record) {
      long expectedSequence = record.Role == "vehicle" ?
          sentVehicleSequence : sentGroundSequence;
      long expectedOffset = record.Role == "vehicle" ?
          sentVehicleOffset : sentGroundOffset;
      if (record.Sequence != expectedSequence ||
          record.RawStartOffset != expectedOffset ||
          record.ProducerTimestampTicks <= 0) {
        throw new InvalidDataException(
            "reader broker producer record sequence/offset discontinuity");
      }
      channel.SendCaptureRecord(record);
      if (record.Role == "vehicle") {
        ++sentVehicleSequence;
        sentVehicleOffset += record.Count;
      } else {
        ++sentGroundSequence;
        sentGroundOffset += record.Count;
      }
    }

    private int DrainRole(bool vehicle, long sequenceExclusive,
        int maximumRecords) {
      long sent = vehicle ? sentVehicleSequence : sentGroundSequence;
      if (sequenceExclusive < sent) {
        throw new InvalidDataException(
            "reader broker bounded record count was violated");
      }
      int count = 0;
      Stopwatch wait = Stopwatch.StartNew();
      while ((vehicle ? sentVehicleSequence : sentGroundSequence) <
          sequenceExclusive && count < maximumRecords) {
        CaptureRecord record;
        bool available = vehicle ? worker.TryDequeueVehicle(out record) :
            worker.TryDequeueGround(out record);
        if (!available) {
          if (wait.ElapsedMilliseconds >= 5000) throw new TimeoutException(
              "reader broker barrier drain record timeout");
          Thread.Sleep(0);
          continue;
        }
        SendRecord(record);
        ++count;
      }
      return count;
    }

    private void SendDrain(ReaderBarrier barrier, bool stopped) {
      bool finalChunk = false;
      while (!finalChunk) {
        int recordCount = DrainRole(true,
            barrier.Vehicle.SequenceExclusive,
            BrokerWire.MaximumRecordsPerDrain);
        recordCount += DrainRole(false,
            barrier.Ground.SequenceExclusive,
            BrokerWire.MaximumRecordsPerDrain - recordCount);
        finalChunk = sentVehicleSequence >=
                barrier.Vehicle.SequenceExclusive &&
            sentGroundSequence >= barrier.Ground.SequenceExclusive;
        DualReaderSnapshot snapshot = DecorateSnapshot(worker.Snapshot());
        channel.Send(BrokerMessageType.DRAIN_COMPLETE,
            MakePayload(delegate(BinaryWriter writer) {
              writer.Write(stopped);
              writer.Write(recordCount);
              writer.Write(finalChunk);
              writer.Write(contextId);
              BrokerWire.WriteBarrier(writer, barrier);
              BrokerWire.WriteSnapshot(writer, snapshot);
            }));
      }
    }

    private ReaderBarrier CaptureCurrentBarrier() {
      if (captureStopped) return worker.CaptureStoppedBarrier();
      return worker.CaptureBarrier();
    }

    private void HandleRequest(BrokerFrame frame) {
      if (frame.Type == BrokerMessageType.OPEN_START) {
        if (frame.Payload.Length != 0) throw new InvalidDataException(
            "OPEN_START payload must be empty");
        OpenAndStartCapture();
        channel.Send(BrokerMessageType.ACK,
            MakePayload(delegate(BinaryWriter writer) {
              BrokerWire.WriteString(writer, "OPEN_START", 32);
              writer.Write(0);
            }));
        return;
      }
      if (!captureStarted) throw new InvalidOperationException(
          "reader broker request preceded OPEN_START");
      if (worker.HasFatalFailure &&
          frame.Type != BrokerMessageType.DRAIN_BOTH &&
          frame.Type != BrokerMessageType.STOP_CAPTURE &&
          frame.Type != BrokerMessageType.CLOSE_EXIT) {
        SendError(new InvalidOperationException(
            "reader broker fatal/overflow latch permits drain and shutdown only"));
        return;
      }
      if (frame.Type == BrokerMessageType.DRAIN_BOTH) {
        if (frame.Payload.Length != 0) throw new InvalidDataException(
            "DRAIN_BOTH payload must be empty");
        SendDrain(CaptureCurrentBarrier(), captureStopped);
        return;
      }
      if (frame.Type == BrokerMessageType.TRANSITION_CONTEXT) {
        if (captureStopped) throw new InvalidOperationException(
            "capture context transition after STOP_CAPTURE");
        UInt32 nextContextId;
        using (MemoryStream memory = new MemoryStream(frame.Payload, false))
        using (BinaryReader reader = new BinaryReader(memory)) {
          nextContextId = reader.ReadUInt32();
          BrokerWire.RequireEmpty(reader);
        }
        ReaderBarrier barrier = worker.TransitionCaptureContextId(nextContextId);
        contextId = nextContextId;
        SendDrain(barrier, false);
        return;
      }
      if (frame.Type == BrokerMessageType.WRITE_PORT) {
        if (captureStopped) throw new InvalidOperationException(
            "serial write after STOP_CAPTURE");
        using (MemoryStream memory = new MemoryStream(frame.Payload, false))
        using (BinaryReader reader = new BinaryReader(memory)) {
          byte role = reader.ReadByte();
          int writeTimeout = reader.ReadInt32();
          int count = reader.ReadInt32();
          if ((role != 1 && role != 2) || count < 0 ||
              count > BrokerWire.MaximumRecordBytes || writeTimeout <= 0) {
            throw new InvalidDataException("reader broker WRITE_PORT bound failed");
          }
          byte[] bytes = reader.ReadBytes(count);
          if (bytes.Length != count) throw new EndOfStreamException(
              "reader broker WRITE_PORT payload was truncated");
          BrokerWire.RequireEmpty(reader);
          IBrokerPort destination = role == 1 ? vehiclePort : groundPort;
          destination.WriteTimeout = writeTimeout;
          try { destination.Write(bytes, 0, count); }
          catch (TimeoutException error) { SendError(error); return; }
          channel.Send(BrokerMessageType.ACK,
              MakePayload(delegate(BinaryWriter writer) {
                BrokerWire.WriteString(writer, "WRITE_PORT", 32);
                writer.Write(count);
              }));
        }
        return;
      }
      if (frame.Type == BrokerMessageType.FLUSH_PORT) {
        if (captureStopped) throw new InvalidOperationException(
            "serial flush after STOP_CAPTURE");
        if (frame.Payload.Length != 1 ||
            (frame.Payload[0] != 1 && frame.Payload[0] != 2)) {
          throw new InvalidDataException("FLUSH_PORT role was invalid");
        }
        (frame.Payload[0] == 1 ? vehiclePort : groundPort).Flush();
        channel.Send(BrokerMessageType.ACK,
            MakePayload(delegate(BinaryWriter writer) {
              BrokerWire.WriteString(writer, "FLUSH_PORT", 32);
              writer.Write(0);
            }));
        return;
      }
      if (frame.Type == BrokerMessageType.WRITE_EXACT_FIXTURE) {
        if (captureStopped || exactFixtureAttempted) {
          SendError(new InvalidOperationException(
              "WRITE_EXACT_FIXTURE exact-once latch rejected request"));
          return;
        }
        using (MemoryStream memory = new MemoryStream(frame.Payload, false))
        using (BinaryReader reader = new BinaryReader(memory)) {
          byte role = reader.ReadByte();
          int writeTimeout = reader.ReadInt32();
          int count = reader.ReadInt32();
          string expectedSha = BrokerWire.ReadString(reader, 64);
          if ((role != 1 && role != 2) || count <= 0 ||
              count > BrokerWire.MaximumRecordBytes ||
              expectedSha.Length != 64 || writeTimeout <= 0) {
            throw new InvalidDataException(
                "WRITE_EXACT_FIXTURE payload contract failed");
          }
          byte[] bytes = reader.ReadBytes(count);
          if (bytes.Length != count) throw new EndOfStreamException(
              "WRITE_EXACT_FIXTURE bytes were truncated");
          BrokerWire.RequireEmpty(reader);
          string actualSha = Sha256Hex(bytes);
          if (!String.Equals(expectedSha, actualSha,
              StringComparison.OrdinalIgnoreCase)) {
            throw new InvalidDataException(
                "WRITE_EXACT_FIXTURE SHA-256 mismatch");
          }
          exactFixtureAttempted = true;
          IBrokerPort destination = role == 1 ? vehiclePort : groundPort;
          destination.WriteTimeout = writeTimeout;
          try {
            destination.Write(bytes, 0, count);
            destination.Flush();
          } catch (TimeoutException error) { SendError(error); return; }
          exactFixtureAccepted = true;
          if (syntheticScenario == "ackloss") {
            SendError(new IOException(
                "synthetic response loss after exact fixture commit"));
            return;
          }
          channel.Send(BrokerMessageType.ACK,
              MakePayload(delegate(BinaryWriter writer) {
                BrokerWire.WriteString(writer, "WRITE_EXACT_FIXTURE", 32);
                writer.Write(count);
                BrokerWire.WriteString(writer, actualSha, 64);
              }));
        }
        return;
      }
      if (frame.Type == BrokerMessageType.STOP_CAPTURE) {
        if (frame.Payload.Length != 0 || captureStopped) {
          throw new InvalidOperationException(
              "STOP_CAPTURE must occur exactly once with an empty payload");
        }
        if (!worker.StopAndJoin(5000)) throw new TimeoutException(
            "STOP_CAPTURE failed to join both reader threads");
        if (pressureGcThread != null && pressureGcThread.IsAlive &&
            !pressureGcThread.Join(2000)) {
          throw new TimeoutException(
              "STOP_CAPTURE pressure GC evidence join timeout");
        }
        captureStopped = true;
        SendDrain(worker.CaptureStoppedBarrier(), true);
        return;
      }
      if (frame.Type == BrokerMessageType.CLOSE_EXIT) {
        if (frame.Payload.Length != 0 || !captureStopped) {
          throw new InvalidOperationException(
              "CLOSE_EXIT requires completed STOP_CAPTURE");
        }
        DualReaderSnapshot snapshot = worker.Snapshot();
        if (!snapshot.Joined || snapshot.Vehicle.ThreadAlive ||
            snapshot.Ground.ThreadAlive || snapshot.Vehicle.QueueDepth != 0 ||
            snapshot.Ground.QueueDepth != 0) {
          throw new InvalidOperationException(
              "CLOSE_EXIT refused inconsistent stopped/drained state");
        }
        bool groundClosed = false;
        bool vehicleClosed = false;
        long groundCloseTicks = 0;
        long vehicleCloseTicks = 0;
        long groundWrittenBytes = groundPort.WrittenBytes;
        long groundWriteOperationCount = groundPort.WriteOperationCount;
        long groundFlushCount = groundPort.FlushCount;
        long groundLastWriteOperationOrdinal =
            groundPort.LastWriteOperationOrdinal;
        long groundLastFlushOperationOrdinal =
            groundPort.LastFlushOperationOrdinal;
        long vehicleWrittenBytes = vehiclePort.WrittenBytes;
        long vehicleWriteOperationCount = vehiclePort.WriteOperationCount;
        long vehicleFlushCount = vehiclePort.FlushCount;
        long vehicleLastWriteOperationOrdinal =
            vehiclePort.LastWriteOperationOrdinal;
        long vehicleLastFlushOperationOrdinal =
            vehiclePort.LastFlushOperationOrdinal;
        try { groundPort.Dispose(); groundClosed = true; }
        catch { groundClosed = false; }
        finally {
          groundCloseTicks = Stopwatch.GetTimestamp();
          groundPort = null;
        }
        try { vehiclePort.Dispose(); vehicleClosed = true; }
        catch { vehicleClosed = false; }
        finally {
          vehicleCloseTicks = Stopwatch.GetTimestamp();
          vehiclePort = null;
        }
        channel.Send(BrokerMessageType.ACK,
            MakePayload(delegate(BinaryWriter writer) {
              BrokerWire.WriteString(writer, "CLOSE_EXIT", 32);
              writer.Write(groundClosed);
              writer.Write(groundCloseTicks);
              writer.Write(vehicleClosed);
              writer.Write(vehicleCloseTicks);
              writer.Write(exactFixtureAccepted);
              writer.Write(exactFixtureAttempted);
              writer.Write(groundWrittenBytes);
              writer.Write(groundWriteOperationCount);
              writer.Write(groundFlushCount);
              writer.Write(groundLastWriteOperationOrdinal);
              writer.Write(groundLastFlushOperationOrdinal);
              writer.Write(vehicleWrittenBytes);
              writer.Write(vehicleWriteOperationCount);
              writer.Write(vehicleFlushCount);
              writer.Write(vehicleLastWriteOperationOrdinal);
              writer.Write(vehicleLastFlushOperationOrdinal);
            }));
        orderlyClose = true;
        return;
      }
      throw new InvalidDataException(
          "reader broker received an invalid request type");
    }

    private int Run() {
      try {
        if (String.IsNullOrWhiteSpace(pipeName) || pipeName.Length > 200) {
          throw new ArgumentException("reader broker pipe name was invalid");
        }
        if (ringCapacity <= 0 || ringCapacity > 65536 ||
            maximumReadBytes <= 0 || maximumReadBytes > 4096) {
          throw new ArgumentOutOfRangeException(
              "reader broker ring/read bounds were invalid");
        }
        pipe = new NamedPipeServerStream(pipeName, PipeDirection.InOut, 1,
            PipeTransmissionMode.Byte,
            PipeOptions.Asynchronous | PipeOptions.WriteThrough,
            65536, 65536);
        StartParentWatchdog();
        pipe.WaitForConnection();
        channel = new BrokerChannel(pipe);
        AcceptHello(channel.Receive());
        while (!orderlyClose) HandleRequest(channel.Receive());
        return 0;
      } catch (EndOfStreamException) {
        return orderlyClose ? 0 : 3;
      } catch (IOException error) {
        if (!orderlyClose && channel != null) SendError(error);
        return orderlyClose ? 0 : 3;
      } catch (Exception error) {
        if (channel != null) SendError(error);
        return 2;
      } finally {
        watchdogStop = true;
        if (worker != null && !captureStopped) {
          try { worker.StopAndJoin(5000); } catch { }
        }
        if (channel != null) {
          try { channel.Dispose(); } catch { }
          channel = null;
          pipe = null;
        } else if (pipe != null) {
          try { pipe.Dispose(); } catch { }
          pipe = null;
        }
        if (groundPort != null) { try { groundPort.Dispose(); } catch { } }
        if (vehiclePort != null) { try { vehiclePort.Dispose(); } catch { } }
        if (parentWatchdog != null && parentWatchdog.IsAlive) {
          try { parentWatchdog.Join(250); } catch { }
        }
      }
    }
  }

  public sealed class ReaderBrokerClient : IDisposable {
    private const int DefaultRpcTimeoutMs = 30000;
    private readonly NamedPipeClientStream pipe;
    private readonly BrokerChannel channel;
    private readonly object requestGate = new object();
    private long expectedVehicleSequence;
    private long expectedVehicleOffset;
    private long expectedGroundSequence;
    private long expectedGroundOffset;
    private bool captureStopped;
    private bool closeExited;
    private UInt32 contextId;
    private long qpcFrequency;
    private int maximumRecordsPerDrain;
    private int brokerProcessId;
    private int verifiedParentProcessId;
    private string helloNonce;
    private FixedClientRecordQueue vehicleRecords;
    private FixedClientRecordQueue groundRecords;
    private readonly Dictionary<UInt32, string[]> contextMap =
        new Dictionary<UInt32, string[]>();
    private ReaderBarrier latestBarrier;
    private ReaderBarrier stoppedBarrier;
    private DualReaderSnapshot latestSnapshot;
    private BrokerCloseReport latestCloseReport;

    private ReaderBrokerClient(NamedPipeClientStream pipeValue,
        BrokerChannel channelValue) {
      pipe = pipeValue;
      channel = channelValue;
      contextMap[0U] = new string[] { "broker_start", "broker_start" };
    }

    public long ProtocolSequence { get { return channel.ReceivedSequence; } }
    public long QpcFrequency { get { return qpcFrequency; } }
    public int MaximumRecordsPerDrain { get { return maximumRecordsPerDrain; } }
    public UInt32 ContextId { get { return contextId; } }
    public bool CaptureStopped { get { return captureStopped; } }
    public int VehicleQueueDepth {
      get { lock (requestGate) { return vehicleRecords == null ? 0 :
          vehicleRecords.Count; } }
    }
    public int GroundQueueDepth {
      get { lock (requestGate) { return groundRecords == null ? 0 :
          groundRecords.Count; } }
    }
    public int VehicleQueueHighWater {
      get { lock (requestGate) { return vehicleRecords == null ? 0 :
          vehicleRecords.HighWater; } }
    }
    public int VehicleQueueCapacity {
      get { lock (requestGate) { return vehicleRecords == null ? 0 :
          vehicleRecords.Capacity; } }
    }
    public int GroundQueueCapacity {
      get { lock (requestGate) { return groundRecords == null ? 0 :
          groundRecords.Capacity; } }
    }
    public int GroundQueueHighWater {
      get { lock (requestGate) { return groundRecords == null ? 0 :
          groundRecords.HighWater; } }
    }
    public BrokerCloseReport LatestCloseReport { get { return latestCloseReport; } }
    public int BrokerProcessId { get { return brokerProcessId; } }
    public int VerifiedParentProcessId { get { return verifiedParentProcessId; } }
    public string HelloNonce { get { return helloNonce; } }

    private static byte[] MakePayload(Action<BinaryWriter> write) {
      using (MemoryStream memory = new MemoryStream())
      using (BinaryWriter writer = new BinaryWriter(memory)) {
        write(writer);
        writer.Flush();
        return memory.ToArray();
      }
    }

    private static Exception DecodeError(byte[] payload) {
      using (MemoryStream memory = new MemoryStream(payload, false))
      using (BinaryReader reader = new BinaryReader(memory)) {
        string message = BrokerWire.ReadString(reader, 4096);
        BrokerWire.RequireEmpty(reader);
        if (message.StartsWith("System.TimeoutException:",
            StringComparison.Ordinal)) return new TimeoutException(message);
        return new IOException("reader broker ERROR: " + message);
      }
    }

    public static ReaderBrokerClient Connect(string pipeName, string secret,
        string sourceSha256, int timeoutMs, long qpcOriginTicks,
        double baseElapsedMs, int expectedBrokerProcessId) {
      return ConnectCore(pipeName, secret, sourceSha256, timeoutMs,
          qpcOriginTicks, baseElapsedMs, expectedBrokerProcessId, false,
          0, 32, 75.0, 100.0, 20, 2000, null, null, 0, null, 0,
          "broker_start", "broker_start");
    }

    public static ReaderBrokerClient Connect(string pipeName, string secret,
        string sourceSha256, int timeoutMs, long qpcOriginTicks,
        double baseElapsedMs, int expectedBrokerProcessId,
        int expectedRingCapacity, int expectedReadBytes,
        double expectedTargetMs, double expectedHardLimitMs,
        int expectedReadTimeoutMs, int expectedWriteTimeoutMs,
        string expectedScenario, string expectedVehiclePort,
        int expectedVehicleBaud, string expectedGroundPort,
        int expectedGroundBaud) {
      if (expectedRingCapacity <= 0 || expectedRingCapacity > 65536) {
        throw new ArgumentOutOfRangeException("expectedRingCapacity");
      }
      return ConnectCore(pipeName, secret, sourceSha256, timeoutMs,
          qpcOriginTicks, baseElapsedMs, expectedBrokerProcessId, true,
          expectedRingCapacity, expectedReadBytes, expectedTargetMs,
          expectedHardLimitMs, expectedReadTimeoutMs, expectedWriteTimeoutMs,
          expectedScenario, expectedVehiclePort, expectedVehicleBaud,
          expectedGroundPort, expectedGroundBaud,
          "broker_start", "broker_start");
    }

    public static ReaderBrokerClient Connect(string pipeName, string secret,
        string sourceSha256, int timeoutMs, long qpcOriginTicks,
        double baseElapsedMs, int expectedBrokerProcessId,
        int expectedRingCapacity, int expectedReadBytes,
        double expectedTargetMs, double expectedHardLimitMs,
        int expectedReadTimeoutMs, int expectedWriteTimeoutMs,
        string expectedScenario, string expectedVehiclePort,
        int expectedVehicleBaud, string expectedGroundPort,
        int expectedGroundBaud, string initialPhase, string initialEpoch) {
      if (expectedRingCapacity <= 0 || expectedRingCapacity > 65536) {
        throw new ArgumentOutOfRangeException("expectedRingCapacity");
      }
      return ConnectCore(pipeName, secret, sourceSha256, timeoutMs,
          qpcOriginTicks, baseElapsedMs, expectedBrokerProcessId, true,
          expectedRingCapacity, expectedReadBytes, expectedTargetMs,
          expectedHardLimitMs, expectedReadTimeoutMs, expectedWriteTimeoutMs,
          expectedScenario, expectedVehiclePort, expectedVehicleBaud,
          expectedGroundPort, expectedGroundBaud, initialPhase, initialEpoch);
    }

    private static ReaderBrokerClient ConnectCore(string pipeName,
        string secret, string sourceSha256, int timeoutMs,
        long qpcOriginTicks, double baseElapsedMs,
        int expectedBrokerProcessId, bool strictConfiguration,
        int expectedRingCapacity, int expectedReadBytes,
        double expectedTargetMs, double expectedHardLimitMs,
        int expectedReadTimeoutMs, int expectedWriteTimeoutMs,
        string expectedScenario, string expectedVehiclePort,
        int expectedVehicleBaud, string expectedGroundPort,
        int expectedGroundBaud, string initialPhase, string initialEpoch) {
      if (timeoutMs <= 0) throw new ArgumentOutOfRangeException("timeoutMs");
      NamedPipeClientStream pipe = new NamedPipeClientStream(".", pipeName,
          PipeDirection.InOut, PipeOptions.Asynchronous);
      BrokerChannel channel = null;
      try {
        pipe.Connect(timeoutMs);
        pipe.ReadMode = PipeTransmissionMode.Byte;
        channel = new BrokerChannel(pipe);
        string nonce = ((Guid.NewGuid().ToString("N")) +
            (Guid.NewGuid().ToString("N"))).ToUpperInvariant();
        int clientProcessId = Process.GetCurrentProcess().Id;
        channel.Send(BrokerMessageType.HELLO,
            MakePayload(delegate(BinaryWriter writer) {
              BrokerWire.WriteString(writer, secret, 256);
              BrokerWire.WriteString(writer, sourceSha256, 64);
              writer.Write(Stopwatch.Frequency);
              writer.Write(qpcOriginTicks);
              writer.Write(baseElapsedMs);
              writer.Write(clientProcessId);
              BrokerWire.WriteString(writer, nonce, 128);
            }));
        BrokerFrame response = channel.Receive(timeoutMs);
        if (response.Type == BrokerMessageType.ERROR) throw DecodeError(
            response.Payload);
        if (response.Type != BrokerMessageType.HELLO_ACK) {
          throw new InvalidDataException("reader broker HELLO_ACK was missing");
        }
        ReaderBrokerClient client = new ReaderBrokerClient(pipe, channel);
        client.contextMap[0U] = new string[] {
            initialPhase ?? "unknown", initialEpoch ??
                (initialPhase ?? "unknown") };
        using (MemoryStream memory = new MemoryStream(response.Payload, false))
        using (BinaryReader reader = new BinaryReader(memory)) {
          int protocol = reader.ReadInt32();
          string actualSha = BrokerWire.ReadString(reader, 64);
          client.qpcFrequency = reader.ReadInt64();
          int ringCapacity = reader.ReadInt32();
          client.maximumRecordsPerDrain = reader.ReadInt32();
          string ownership = BrokerWire.ReadString(reader, 64);
          int negotiatedReadBytes = reader.ReadInt32();
          double negotiatedTargetMs = reader.ReadDouble();
          double negotiatedHardLimitMs = reader.ReadDouble();
          int negotiatedReadTimeoutMs = reader.ReadInt32();
          int negotiatedWriteTimeoutMs = reader.ReadInt32();
          string vehicleRole = BrokerWire.ReadString(reader, 32);
          string groundRole = BrokerWire.ReadString(reader, 32);
          string negotiatedScenario = BrokerWire.ReadString(reader, 32);
          string negotiatedVehiclePort = BrokerWire.ReadString(reader, 256);
          int negotiatedVehicleBaud = reader.ReadInt32();
          string negotiatedGroundPort = BrokerWire.ReadString(reader, 256);
          int negotiatedGroundBaud = reader.ReadInt32();
          client.verifiedParentProcessId = reader.ReadInt32();
          client.brokerProcessId = reader.ReadInt32();
          client.helloNonce = BrokerWire.ReadString(reader, 128);
          BrokerWire.RequireEmpty(reader);
          if (protocol != BrokerWire.ProtocolVersion ||
              !String.Equals(actualSha, sourceSha256,
                  StringComparison.OrdinalIgnoreCase) ||
              client.qpcFrequency != Stopwatch.Frequency ||
              ringCapacity <= 0 ||
              client.maximumRecordsPerDrain !=
                  BrokerWire.MaximumRecordsPerDrain ||
              ownership != "broker_owns_both_serial_ports" ||
              vehicleRole != "vehicle" || groundRole != "ground") {
            throw new InvalidDataException(
                "reader broker HELLO_ACK contract validation failed");
          }
          if (strictConfiguration &&
              (ringCapacity != expectedRingCapacity ||
               negotiatedReadBytes != expectedReadBytes ||
               negotiatedTargetMs != expectedTargetMs ||
               negotiatedHardLimitMs != expectedHardLimitMs ||
               negotiatedReadTimeoutMs != expectedReadTimeoutMs ||
               negotiatedWriteTimeoutMs != expectedWriteTimeoutMs ||
               negotiatedScenario != expectedScenario ||
               !String.Equals(negotiatedVehiclePort,
                   expectedVehiclePort ?? "",
                   StringComparison.OrdinalIgnoreCase) ||
               negotiatedVehicleBaud != expectedVehicleBaud ||
               !String.Equals(negotiatedGroundPort,
                   expectedGroundPort ?? "",
                   StringComparison.OrdinalIgnoreCase) ||
               negotiatedGroundBaud != expectedGroundBaud)) {
            throw new InvalidDataException(
                "reader broker HELLO_ACK requested configuration mismatch");
          }
          client.vehicleRecords = new FixedClientRecordQueue(ringCapacity);
          client.groundRecords = new FixedClientRecordQueue(ringCapacity);
          if (client.verifiedParentProcessId != clientProcessId ||
              client.brokerProcessId != expectedBrokerProcessId ||
              client.helloNonce != nonce) {
            throw new InvalidDataException(
                "reader broker HELLO_ACK PID/nonce validation failed");
          }
        }
        channel.Send(BrokerMessageType.OPEN_START, new byte[0]);
        BrokerFrame openResponse = channel.Receive(timeoutMs);
        if (openResponse.Type == BrokerMessageType.ERROR) throw DecodeError(
            openResponse.Payload);
        if (openResponse.Type != BrokerMessageType.ACK) {
          throw new InvalidDataException("reader broker OPEN_START ACK was missing");
        }
        using (MemoryStream memory = new MemoryStream(
            openResponse.Payload, false))
        using (BinaryReader reader = new BinaryReader(memory)) {
          if (BrokerWire.ReadString(reader, 32) != "OPEN_START" ||
              reader.ReadInt32() != 0) {
            throw new InvalidDataException(
                "reader broker OPEN_START ACK content was invalid");
          }
          BrokerWire.RequireEmpty(reader);
        }
        return client;
      } catch {
        if (channel != null) channel.Dispose(); else pipe.Dispose();
        throw;
      }
    }

    private void ValidateRecord(CaptureRecord record) {
      long expectedSequence = record.Role == "vehicle" ?
          expectedVehicleSequence : expectedGroundSequence;
      long expectedOffset = record.Role == "vehicle" ?
          expectedVehicleOffset : expectedGroundOffset;
      if (record.Sequence != expectedSequence ||
          record.RawStartOffset != expectedOffset ||
          record.ProducerTimestampTicks <= 0) {
        throw new InvalidDataException(
            "reader broker client record sequence/offset discontinuity");
      }
      if (record.Role == "vehicle") {
        ++expectedVehicleSequence;
        expectedVehicleOffset += record.Count;
      } else {
        ++expectedGroundSequence;
        expectedGroundOffset += record.Count;
      }
    }

    private void DecorateViolationEvents(RoleReaderSnapshot roleSnapshot) {
      if (roleSnapshot == null || roleSnapshot.ViolationEvents == null) return;
      for (int index = 0; index < roleSnapshot.ViolationEvents.Length;
          ++index) {
        FairnessViolationEvent item = roleSnapshot.ViolationEvents[index];
        string[] mappedContext;
        if (contextMap.TryGetValue(item.ContextId, out mappedContext)) {
          item.Phase = mappedContext[0];
          item.Epoch = mappedContext[1];
        } else {
          item.Phase = "context_" + item.ContextId.ToString();
          item.Epoch = item.Phase;
        }
      }
    }

    private void DecorateSnapshotContextNames(DualReaderSnapshot snapshot) {
      if (snapshot == null) return;
      DecorateViolationEvents(snapshot.Vehicle);
      DecorateViolationEvents(snapshot.Ground);
    }

    private int RemainingTimeout(Stopwatch watch, int timeoutMs) {
      int remaining = timeoutMs - (int)watch.ElapsedMilliseconds;
      if (remaining <= 0) {
        try { channel.Dispose(); } catch { }
        closeExited = true;
        throw new TimeoutException("reader broker RPC deadline expired");
      }
      return remaining;
    }

    private BrokerFrame ReceiveBounded(int timeoutMs) {
      try { return channel.Receive(timeoutMs); }
      catch (TimeoutException) {
        try { channel.Dispose(); } catch { }
        closeExited = true;
        throw;
      }
    }

    private BrokerDrainResult ReceiveDrain(int timeoutMs) {
      List<CaptureRecord> records = new List<CaptureRecord>();
      int currentChunkRecordCount = 0;
      int maximumChunkRecordCount = 0;
      Stopwatch deadline = Stopwatch.StartNew();
      while (true) {
        BrokerFrame frame = ReceiveBounded(RemainingTimeout(
            deadline, timeoutMs));
        if (frame.Type == BrokerMessageType.ERROR) throw DecodeError(frame.Payload);
        if (frame.Type == BrokerMessageType.CAPTURE_RECORD) {
          if (currentChunkRecordCount >= maximumRecordsPerDrain ||
              records.Count >= BrokerWire.MaximumAggregateRecords) {
            throw new InvalidDataException(
                "reader broker client bounded record count was exceeded");
          }
          CaptureRecord record = BrokerWire.DecodeRecord(frame.Payload);
          string[] mappedContext;
          if (contextMap.TryGetValue(record.ContextId, out mappedContext)) {
            record.ProducerPhase = mappedContext[0];
            record.ProducerEpoch = mappedContext[1];
          } else {
            record.ProducerPhase = "context_" + record.ContextId.ToString();
            record.ProducerEpoch = record.ProducerPhase;
          }
          ValidateRecord(record);
          records.Add(record);
          ++currentChunkRecordCount;
          bool queued = record.Role == "vehicle" ?
              vehicleRecords.TryEnqueue(record) :
              groundRecords.TryEnqueue(record);
          if (!queued) {
            try { channel.Dispose(); } catch { }
            throw new InvalidDataException(
                "reader broker client fixed queue overflowed fail-closed");
          }
          continue;
        }
        if (frame.Type != BrokerMessageType.DRAIN_COMPLETE) {
          throw new InvalidDataException(
              "reader broker drain response type was invalid");
        }
        using (MemoryStream memory = new MemoryStream(frame.Payload, false))
        using (BinaryReader reader = new BinaryReader(memory)) {
          bool stopped = reader.ReadBoolean();
          int boundedRecordCount = reader.ReadInt32();
          bool finalChunk = reader.ReadBoolean();
          UInt32 returnedContextId = reader.ReadUInt32();
          ReaderBarrier barrier = BrokerWire.ReadBarrier(reader);
          DualReaderSnapshot snapshot = BrokerWire.ReadSnapshot(reader);
          BrokerWire.RequireEmpty(reader);
          DecorateSnapshotContextNames(snapshot);
          bool deliveredBeyondBarrier =
              expectedVehicleSequence > barrier.Vehicle.SequenceExclusive ||
              expectedGroundSequence > barrier.Ground.SequenceExclusive ||
              expectedVehicleOffset > barrier.Vehicle.RawOffsetExclusive ||
              expectedGroundOffset > barrier.Ground.RawOffsetExclusive;
          bool finalEndpointMismatch = finalChunk &&
              (expectedVehicleSequence != barrier.Vehicle.SequenceExclusive ||
               expectedGroundSequence != barrier.Ground.SequenceExclusive ||
               expectedVehicleOffset != barrier.Vehicle.RawOffsetExclusive ||
               expectedGroundOffset != barrier.Ground.RawOffsetExclusive);
          bool prematureNonFinal = !finalChunk &&
              expectedVehicleSequence == barrier.Vehicle.SequenceExclusive &&
              expectedGroundSequence == barrier.Ground.SequenceExclusive;
          if (boundedRecordCount != currentChunkRecordCount ||
              boundedRecordCount < 0 ||
              boundedRecordCount > maximumRecordsPerDrain ||
              deliveredBeyondBarrier || finalEndpointMismatch ||
              prematureNonFinal || (!finalChunk && boundedRecordCount == 0)) {
            throw new InvalidDataException(
                "reader broker drain completion consistency failed");
          }
          maximumChunkRecordCount = Math.Max(maximumChunkRecordCount,
              boundedRecordCount);
          latestBarrier = barrier;
          latestSnapshot = snapshot;
          if (stopped) stoppedBarrier = barrier;
          if (!finalChunk) {
            currentChunkRecordCount = 0;
            continue;
          }
          return new BrokerDrainResult {
            Records = records.ToArray(),
            Barrier = barrier,
            Snapshot = snapshot,
            Stopped = stopped,
            BoundedRecordCount = maximumChunkRecordCount,
            ProtocolSequence = channel.ReceivedSequence,
            ContextId = returnedContextId,
            QpcFrequency = qpcFrequency
          };
        }
      }
    }

    public BrokerDrainResult DrainBoth() {
      return DrainBoth(DefaultRpcTimeoutMs);
    }

    public BrokerDrainResult DrainBoth(int timeoutMs) {
      lock (requestGate) {
        if (closeExited) throw new ObjectDisposedException("ReaderBrokerClient");
        channel.Send(BrokerMessageType.DRAIN_BOTH, new byte[0]);
        return ReceiveDrain(timeoutMs);
      }
    }

    public bool TryDequeueVehicle(out CaptureRecord record) {
      lock (requestGate) {
        if (vehicleRecords.Count == 0 && !captureStopped && !closeExited) {
          DrainBoth();
        }
        if (vehicleRecords.Count == 0) { record = null; return false; }
        return vehicleRecords.TryDequeue(out record);
      }
    }

    public bool TryDequeueGround(out CaptureRecord record) {
      lock (requestGate) {
        if (groundRecords.Count == 0 && !captureStopped && !closeExited) {
          DrainBoth();
        }
        if (groundRecords.Count == 0) { record = null; return false; }
        return groundRecords.TryDequeue(out record);
      }
    }

    public ReaderBarrier CaptureBarrier() {
      return DrainBoth().Barrier;
    }

    public BrokerDrainResult TransitionContext(UInt32 nextContextId) {
      lock (requestGate) {
        if (captureStopped || closeExited) throw new InvalidOperationException(
            "reader broker context transition after stop/close");
        if (!contextMap.ContainsKey(nextContextId)) {
          string generated = "context_" + nextContextId.ToString();
          contextMap[nextContextId] = new string[] { generated, generated };
        }
        channel.Send(BrokerMessageType.TRANSITION_CONTEXT,
            MakePayload(delegate(BinaryWriter writer) {
              writer.Write(nextContextId);
            }));
        BrokerDrainResult result = ReceiveDrain(DefaultRpcTimeoutMs);
        if (result.ContextId != nextContextId ||
            result.Barrier.Vehicle.NewContextId != nextContextId ||
            result.Barrier.Ground.NewContextId != nextContextId) {
          try { channel.Dispose(); } catch { }
          closeExited = true;
          throw new InvalidDataException(
              "reader broker transition context handoff mismatch");
        }
        contextId = nextContextId;
        return result;
      }
    }

    public ReaderBarrier TransitionCaptureContext(string phase, string epoch) {
      lock (requestGate) {
        UInt32 next = checked(contextId + 1U);
        contextMap[next] = new string[] { phase ?? "unknown",
            epoch ?? (phase ?? "unknown") };
        return TransitionContext(next).Barrier;
      }
    }

    private void WritePort(byte role, byte[] bytes, int writeTimeout) {
      if (bytes == null) throw new ArgumentNullException("bytes");
      if (bytes.Length > BrokerWire.MaximumRecordBytes) {
        throw new ArgumentOutOfRangeException("bytes");
      }
      lock (requestGate) {
        if (captureStopped || closeExited) throw new InvalidOperationException(
            "reader broker write after stop/close");
        channel.Send(BrokerMessageType.WRITE_PORT,
            MakePayload(delegate(BinaryWriter writer) {
              writer.Write(role);
              writer.Write(writeTimeout);
              writer.Write(bytes.Length);
              writer.Write(bytes);
            }));
        BrokerFrame response = ReceiveBounded(DefaultRpcTimeoutMs);
        if (response.Type == BrokerMessageType.ERROR) throw DecodeError(
            response.Payload);
        if (response.Type != BrokerMessageType.ACK) throw new InvalidDataException(
            "reader broker WRITE_PORT ACK was missing");
        using (MemoryStream memory = new MemoryStream(response.Payload, false))
        using (BinaryReader reader = new BinaryReader(memory)) {
          if (BrokerWire.ReadString(reader, 32) != "WRITE_PORT" ||
              reader.ReadInt32() != bytes.Length) {
            throw new InvalidDataException(
                "reader broker WRITE_PORT ACK content was invalid");
          }
          BrokerWire.RequireEmpty(reader);
        }
      }
    }
    public void WriteVehicle(byte[] bytes) { WritePort(1, bytes, 2000); }
    public void WriteGround(byte[] bytes) { WritePort(2, bytes, 2000); }
    public void WriteVehicle(byte[] bytes, int writeTimeout) {
      WritePort(1, bytes, writeTimeout);
    }
    public void WriteGround(byte[] bytes, int writeTimeout) {
      WritePort(2, bytes, writeTimeout);
    }

    public void FlushPort(bool vehicle) {
      lock (requestGate) {
        channel.Send(BrokerMessageType.FLUSH_PORT,
            new byte[] { vehicle ? (byte)1 : (byte)2 });
        BrokerFrame response = ReceiveBounded(DefaultRpcTimeoutMs);
        if (response.Type == BrokerMessageType.ERROR) throw DecodeError(
            response.Payload);
        if (response.Type != BrokerMessageType.ACK) throw new InvalidDataException(
            "reader broker FLUSH_PORT ACK was missing");
        using (MemoryStream memory = new MemoryStream(response.Payload, false))
        using (BinaryReader reader = new BinaryReader(memory)) {
          if (BrokerWire.ReadString(reader, 32) != "FLUSH_PORT" ||
              reader.ReadInt32() != 0) {
            throw new InvalidDataException(
                "reader broker FLUSH_PORT ACK content was invalid");
          }
          BrokerWire.RequireEmpty(reader);
        }
      }
    }

    public void WriteExactFixture(bool vehicle, byte[] bytes,
        string expectedSha256, int writeTimeout) {
      if (bytes == null) throw new ArgumentNullException("bytes");
      lock (requestGate) {
        channel.Send(BrokerMessageType.WRITE_EXACT_FIXTURE,
            MakePayload(delegate(BinaryWriter writer) {
              writer.Write(vehicle ? (byte)1 : (byte)2);
              writer.Write(writeTimeout);
              writer.Write(bytes.Length);
              BrokerWire.WriteString(writer, expectedSha256, 64);
              writer.Write(bytes);
            }));
        BrokerFrame response = ReceiveBounded(DefaultRpcTimeoutMs);
        if (response.Type == BrokerMessageType.ERROR) throw DecodeError(
            response.Payload);
        if (response.Type != BrokerMessageType.ACK) throw new InvalidDataException(
            "reader broker WRITE_EXACT_FIXTURE ACK was missing");
        using (MemoryStream memory = new MemoryStream(response.Payload, false))
        using (BinaryReader reader = new BinaryReader(memory)) {
          string operation = BrokerWire.ReadString(reader, 32);
          int acceptedBytes = reader.ReadInt32();
          string acceptedSha = BrokerWire.ReadString(reader, 64);
          BrokerWire.RequireEmpty(reader);
          if (operation != "WRITE_EXACT_FIXTURE" ||
              acceptedBytes != bytes.Length ||
              !String.Equals(acceptedSha, expectedSha256,
                  StringComparison.OrdinalIgnoreCase)) {
            throw new InvalidDataException(
                "reader broker WRITE_EXACT_FIXTURE ACK validation failed");
          }
        }
      }
    }

    public BrokerDrainResult StopCapture() {
      return StopCapture(DefaultRpcTimeoutMs);
    }

    public BrokerDrainResult StopCapture(int timeoutMs) {
      lock (requestGate) {
        if (captureStopped || closeExited) throw new InvalidOperationException(
            "reader broker STOP_CAPTURE must occur exactly once");
        channel.Send(BrokerMessageType.STOP_CAPTURE, new byte[0]);
        BrokerDrainResult result = ReceiveDrain(timeoutMs);
        if (!result.Stopped || !result.Snapshot.Joined ||
            result.Snapshot.Vehicle.ThreadAlive ||
            result.Snapshot.Ground.ThreadAlive ||
            result.Snapshot.Vehicle.QueueDepth != 0 ||
            result.Snapshot.Ground.QueueDepth != 0) {
          throw new InvalidDataException(
              "reader broker STOP_CAPTURE response was inconsistent");
        }
        captureStopped = true;
        return result;
      }
    }

    public bool StopAndJoin(int timeoutMs) {
      if (timeoutMs <= 0) throw new ArgumentOutOfRangeException("timeoutMs");
      if (!captureStopped) StopCapture(timeoutMs);
      return latestSnapshot != null && latestSnapshot.Joined;
    }

    public ReaderBarrier CaptureStoppedBarrier() {
      if (!captureStopped || stoppedBarrier == null) {
        throw new InvalidOperationException(
            "reader broker stopped barrier requested before STOP_CAPTURE");
      }
      return stoppedBarrier;
    }

    public DualReaderSnapshot Snapshot() {
      lock (requestGate) {
        if (latestSnapshot == null && !closeExited) DrainBoth();
        return latestSnapshot;
      }
    }

    public bool HasFatalFailure {
      get {
        DualReaderSnapshot snapshot = Snapshot();
        return snapshot == null || snapshot.HasFatalFailure;
      }
    }

    public void CloseExit() {
      CloseExit(DefaultRpcTimeoutMs);
    }

    private static bool IsValidPortOperationEvidence(long writtenBytes,
        long writeCount, long flushCount, long lastWriteOrdinal,
        long lastFlushOrdinal) {
      if (writtenBytes < 0 || writeCount < 0 || flushCount < 0 ||
          lastWriteOrdinal < 0 || lastFlushOrdinal < 0) return false;
      if ((writeCount == 0) != (lastWriteOrdinal == 0) ||
          (flushCount == 0) != (lastFlushOrdinal == 0)) return false;
      long operationCount = writeCount + flushCount;
      if (operationCount < writeCount || operationCount < flushCount) {
        return false;
      }
      long maximumOrdinal = Math.Max(lastWriteOrdinal, lastFlushOrdinal);
      if (maximumOrdinal != operationCount ||
          lastWriteOrdinal > operationCount ||
          lastFlushOrdinal > operationCount ||
          (lastWriteOrdinal != 0 &&
           lastWriteOrdinal == lastFlushOrdinal)) return false;
      return true;
    }

    public void CloseExit(int timeoutMs) {
      lock (requestGate) {
        if (!captureStopped || closeExited) throw new InvalidOperationException(
            "reader broker CLOSE_EXIT requires STOP_CAPTURE exactly once");
        channel.Send(BrokerMessageType.CLOSE_EXIT, new byte[0]);
        BrokerFrame response = ReceiveBounded(timeoutMs);
        if (response.Type == BrokerMessageType.ERROR) throw DecodeError(
            response.Payload);
        if (response.Type != BrokerMessageType.ACK) throw new InvalidDataException(
            "reader broker CLOSE_EXIT ACK was missing");
        using (MemoryStream memory = new MemoryStream(response.Payload, false))
        using (BinaryReader reader = new BinaryReader(memory)) {
          if (BrokerWire.ReadString(reader, 32) != "CLOSE_EXIT") {
            throw new InvalidDataException(
                "reader broker CLOSE_EXIT ACK operation was invalid");
          }
          latestCloseReport = new BrokerCloseReport {
            GroundCloseSucceeded = reader.ReadBoolean(),
            GroundCloseQpcTicks = reader.ReadInt64(),
            VehicleCloseSucceeded = reader.ReadBoolean(),
            VehicleCloseQpcTicks = reader.ReadInt64(),
            ExactFixtureAccepted = reader.ReadBoolean(),
            ExactFixtureAttempted = reader.ReadBoolean(),
            GroundWrittenBytes = reader.ReadInt64(),
            GroundWriteOperationCount = reader.ReadInt64(),
            GroundFlushCount = reader.ReadInt64(),
            GroundLastWriteOperationOrdinal = reader.ReadInt64(),
            GroundLastFlushOperationOrdinal = reader.ReadInt64(),
            VehicleWrittenBytes = reader.ReadInt64(),
            VehicleWriteOperationCount = reader.ReadInt64(),
            VehicleFlushCount = reader.ReadInt64(),
            VehicleLastWriteOperationOrdinal = reader.ReadInt64(),
            VehicleLastFlushOperationOrdinal = reader.ReadInt64()
          };
          BrokerWire.RequireEmpty(reader);
          if (!latestCloseReport.GroundCloseSucceeded ||
              !latestCloseReport.VehicleCloseSucceeded ||
              latestCloseReport.GroundCloseQpcTicks <= 0 ||
              latestCloseReport.VehicleCloseQpcTicks <= 0 ||
              (latestCloseReport.ExactFixtureAccepted &&
               !latestCloseReport.ExactFixtureAttempted) ||
              !IsValidPortOperationEvidence(
                  latestCloseReport.GroundWrittenBytes,
                  latestCloseReport.GroundWriteOperationCount,
                  latestCloseReport.GroundFlushCount,
                  latestCloseReport.GroundLastWriteOperationOrdinal,
                  latestCloseReport.GroundLastFlushOperationOrdinal) ||
              !IsValidPortOperationEvidence(
                  latestCloseReport.VehicleWrittenBytes,
                  latestCloseReport.VehicleWriteOperationCount,
                  latestCloseReport.VehicleFlushCount,
                  latestCloseReport.VehicleLastWriteOperationOrdinal,
                  latestCloseReport.VehicleLastFlushOperationOrdinal)) {
            throw new InvalidDataException(
                "reader broker CLOSE_EXIT close evidence was invalid");
          }
        }
        closeExited = true;
        channel.Dispose();
      }
    }

    public void Dispose() {
      if (!closeExited) {
        try { channel.Dispose(); } catch { }
        closeExited = true;
      }
    }
  }

  public sealed class BrokerSerialProxy : IDisposable {
    private readonly ReaderBrokerClient client;
    private readonly bool vehicle;
    private readonly BrokerSerialStream baseStream;
    private bool open = true;
    private int writeTimeout = 2000;
    internal BrokerSerialProxy(ReaderBrokerClient clientValue,
        bool vehicleValue) {
      client = clientValue;
      vehicle = vehicleValue;
      baseStream = new BrokerSerialStream(clientValue, vehicleValue);
    }
    public bool IsOpen { get { return open; } }
    public int WriteTimeout {
      get { return writeTimeout; }
      set {
        if (value <= 0) throw new ArgumentOutOfRangeException("value");
        writeTimeout = value;
      }
    }
    public bool DtrEnable {
      get { return false; }
      set { if (value) throw new InvalidOperationException(
          "reader broker DTR must remain disabled"); }
    }
    public bool RtsEnable {
      get { return false; }
      set { if (value) throw new InvalidOperationException(
          "reader broker RTS must remain disabled"); }
    }
    public Stream BaseStream { get { return baseStream; } }
    public void Open() { open = true; }
    public void Close() { open = false; }
    public void Write(byte[] bytes, int offset, int count) {
      if (!open) throw new InvalidOperationException("broker serial proxy closed");
      if (bytes == null) throw new ArgumentNullException("bytes");
      if (offset < 0 || count < 0 || offset + count > bytes.Length) {
        throw new ArgumentOutOfRangeException("offset");
      }
      byte[] exact = new byte[count];
      if (count > 0) Buffer.BlockCopy(bytes, offset, exact, 0, count);
      if (vehicle) client.WriteVehicle(exact, writeTimeout);
      else client.WriteGround(exact, writeTimeout);
    }
    public void WriteExactFixture(byte[] bytes, string expectedSha256) {
      if (!open) throw new InvalidOperationException("broker serial proxy closed");
      client.WriteExactFixture(vehicle, bytes, expectedSha256, writeTimeout);
    }
    public void Dispose() { open = false; }
  }

  internal sealed class BrokerSerialStream : Stream {
    private readonly ReaderBrokerClient client;
    private readonly bool vehicle;
    internal BrokerSerialStream(ReaderBrokerClient value, bool vehicleValue) {
      client = value;
      vehicle = vehicleValue;
    }
    public override bool CanRead { get { return false; } }
    public override bool CanSeek { get { return false; } }
    public override bool CanWrite { get { return true; } }
    public override long Length { get { throw new NotSupportedException(); } }
    public override long Position {
      get { throw new NotSupportedException(); }
      set { throw new NotSupportedException(); }
    }
    public override void Flush() { client.FlushPort(vehicle); }
    public override int Read(byte[] buffer, int offset, int count) {
      throw new NotSupportedException();
    }
    public override long Seek(long offset, SeekOrigin origin) {
      throw new NotSupportedException();
    }
    public override void SetLength(long value) {
      throw new NotSupportedException();
    }
    public override void Write(byte[] buffer, int offset, int count) {
      byte[] exact = new byte[count];
      if (count > 0) Buffer.BlockCopy(buffer, offset, exact, 0, count);
      if (vehicle) client.WriteVehicle(exact); else client.WriteGround(exact);
    }
  }

  public sealed class ReaderBrokerClientBundle {
    public ReaderBrokerClient Client { get; internal set; }
    public BrokerSerialProxy VehicleProxy { get; internal set; }
    public BrokerSerialProxy GroundProxy { get; internal set; }
    public static ReaderBrokerClientBundle Create(ReaderBrokerClient client) {
      if (client == null) throw new ArgumentNullException("client");
      return new ReaderBrokerClientBundle {
        Client = client,
        VehicleProxy = new BrokerSerialProxy(client, true),
        GroundProxy = new BrokerSerialProxy(client, false)
      };
    }
  }

  public static class BrokerProcessContainment {
    private const uint JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE = 0x00002000;
    private const int JobObjectExtendedLimitInformation = 9;

    [StructLayout(LayoutKind.Sequential)]
    private struct IO_COUNTERS {
      public UInt64 ReadOperationCount;
      public UInt64 WriteOperationCount;
      public UInt64 OtherOperationCount;
      public UInt64 ReadTransferCount;
      public UInt64 WriteTransferCount;
      public UInt64 OtherTransferCount;
    }
    [StructLayout(LayoutKind.Sequential)]
    private struct JOBOBJECT_BASIC_LIMIT_INFORMATION {
      public Int64 PerProcessUserTimeLimit;
      public Int64 PerJobUserTimeLimit;
      public UInt32 LimitFlags;
      public UIntPtr MinimumWorkingSetSize;
      public UIntPtr MaximumWorkingSetSize;
      public UInt32 ActiveProcessLimit;
      public Int64 Affinity;
      public Int32 PriorityClass;
      public Int32 SchedulingClass;
    }
    [StructLayout(LayoutKind.Sequential)]
    private struct JOBOBJECT_EXTENDED_LIMIT_INFORMATION {
      public JOBOBJECT_BASIC_LIMIT_INFORMATION BasicLimitInformation;
      public IO_COUNTERS IoInfo;
      public UIntPtr ProcessMemoryLimit;
      public UIntPtr JobMemoryLimit;
      public UIntPtr PeakProcessMemoryUsed;
      public UIntPtr PeakJobMemoryUsed;
    }

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode)]
    private static extern IntPtr CreateJobObject(IntPtr attributes, string name);
    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool SetInformationJobObject(IntPtr job, int infoClass,
        IntPtr information, UInt32 informationLength);
    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AssignProcessToJobObject(IntPtr job,
        IntPtr process);
    [DllImport("kernel32.dll")]
    private static extern bool CloseHandle(IntPtr handle);
    [DllImport("shell32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    private static extern IntPtr CommandLineToArgvW(string commandLine,
        out int argumentCount);
    [DllImport("kernel32.dll")]
    private static extern IntPtr LocalFree(IntPtr memory);

    public static IntPtr CreateKillOnCloseJob() {
      IntPtr job = CreateJobObject(IntPtr.Zero, null);
      if (job == IntPtr.Zero) throw new System.ComponentModel.Win32Exception(
          Marshal.GetLastWin32Error(), "CreateJobObject failed");
      int size = Marshal.SizeOf(typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
      IntPtr buffer = Marshal.AllocHGlobal(size);
      try {
        JOBOBJECT_EXTENDED_LIMIT_INFORMATION value =
            new JOBOBJECT_EXTENDED_LIMIT_INFORMATION();
        value.BasicLimitInformation.LimitFlags =
            JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
        Marshal.StructureToPtr(value, buffer, false);
        if (!SetInformationJobObject(job,
            JobObjectExtendedLimitInformation, buffer, (uint)size)) {
          throw new System.ComponentModel.Win32Exception(
              Marshal.GetLastWin32Error(), "SetInformationJobObject failed");
        }
        return job;
      } catch {
        CloseHandle(job);
        throw;
      } finally {
        Marshal.FreeHGlobal(buffer);
      }
    }

    public static void AssignProcessToKillOnCloseJob(IntPtr job,
        Process process) {
      if (job == IntPtr.Zero) throw new ArgumentException("job");
      if (process == null) throw new ArgumentNullException("process");
      if (!AssignProcessToJobObject(job, process.Handle)) {
        throw new System.ComponentModel.Win32Exception(
            Marshal.GetLastWin32Error(), "AssignProcessToJobObject failed");
      }
    }

    public static void CloseJob(IntPtr job) {
      if (job != IntPtr.Zero) CloseHandle(job);
    }

    public static string[] ParseWindowsCommandLine(string commandLine) {
      if (commandLine == null) throw new ArgumentNullException("commandLine");
      int count;
      IntPtr argv = CommandLineToArgvW(commandLine, out count);
      if (argv == IntPtr.Zero) throw new System.ComponentModel.Win32Exception(
          Marshal.GetLastWin32Error(), "CommandLineToArgvW failed");
      try {
        string[] values = new string[count];
        for (int index = 0; index < count; ++index) {
          IntPtr pointer = Marshal.ReadIntPtr(argv, index * IntPtr.Size);
          values[index] = Marshal.PtrToStringUni(pointer);
        }
        return values;
      } finally { LocalFree(argv); }
    }
  }

  public static class WorkerHarness {
    private static bool WaitUntil(Func<bool> predicate, int timeoutMs) {
      Stopwatch watch = Stopwatch.StartNew();
      while (watch.ElapsedMilliseconds < timeoutMs) {
        if (predicate()) return true;
        Thread.Sleep(1);
      }
      return predicate();
    }
    public static PowerShellPressureHarness StartPowerShellPressure() {
      return new PowerShellPressureHarness();
    }
    public static RecordAudit DrainAndAudit(DualPortReaderWorker worker,
        bool vehicle, long expectedBytes) {
      long expectedSequence = 0;
      long expectedOffset = 0;
      long count = 0;
      double maximumDelay = 0.0;
      CaptureRecord record;
      while (vehicle ? worker.TryDequeueVehicle(out record) :
          worker.TryDequeueGround(out record)) {
        if (record.Sequence != expectedSequence ||
            record.RawStartOffset != expectedOffset ||
            record.ProducerTimestampTicks <= 0) {
          return new RecordAudit { Valid = false, RecordCount = count,
              ByteCount = expectedOffset, MaximumConsumerDelayMs = maximumDelay };
        }
        double nowMs = (double)Stopwatch.GetTimestamp() * 1000.0 /
            Stopwatch.Frequency;
        double producerAbsoluteMs = (double)record.ProducerTimestampTicks *
            1000.0 / Stopwatch.Frequency;
        maximumDelay = Math.Max(maximumDelay, nowMs - producerAbsoluteMs);
        ++expectedSequence;
        expectedOffset += record.Count;
        ++count;
      }
      return new RecordAudit { Valid = expectedOffset == expectedBytes,
          RecordCount = count, ByteCount = expectedOffset,
          MaximumConsumerDelayMs = maximumDelay };
    }

    public static WorkerHarnessResult RunAll() {
      SyntheticByteSource overflowVehicle = new SyntheticByteSource(1024, 7);
      SyntheticByteSource overflowGround = new SyntheticByteSource(0, 9);
      DualPortReaderWorker overflowWorker = new DualPortReaderWorker(
          overflowVehicle, overflowGround, 4, 32, 0.0, 75.0, 100.0);
      overflowWorker.Start();
      WaitUntil(delegate { return overflowWorker.VehicleReader.Snapshot().OverflowLatched; }, 2000);
      overflowWorker.StopAndJoin(2000);
      RecordAudit overflowAudit = DrainAndAudit(overflowWorker, true, 128);
      DualReaderSnapshot overflowSnapshot = overflowWorker.Snapshot();
      bool overflowPassed = overflowSnapshot.Vehicle.OverflowLatched &&
          overflowSnapshot.Vehicle.OverflowCount > 0 &&
          overflowSnapshot.Vehicle.ProducedSequence == 4 &&
          overflowSnapshot.Vehicle.ProducedRawBytes == 128 &&
          overflowAudit.Valid && overflowSnapshot.HasFatalFailure &&
          !overflowSnapshot.Valid;

      SyntheticByteSource timeVehicle = new SyntheticByteSource(32, 11);
      SyntheticByteSource timeGround = new SyntheticByteSource(0, 13);
      DualPortReaderWorker timeWorker = new DualPortReaderWorker(
          timeVehicle, timeGround, 8, 32, 0.0, 75.0, 100.0);
      const double timestampBaseElapsedMs = 12345.0;
      timeWorker.Arm(timestampBaseElapsedMs);
      timeWorker.SetCaptureContext("timestamp_phase", "timestamp_epoch");
      Stopwatch timestampWatch = Stopwatch.StartNew();
      timeWorker.Start();
      WaitUntil(delegate { return timeWorker.VehicleReader.Snapshot().ProducedSequence >= 1; }, 2000);
      Thread.Sleep(150);
      CaptureRecord delayedRecord;
      bool gotDelayed = timeWorker.TryDequeueVehicle(out delayedRecord);
      double consumerDelay = gotDelayed ?
          ((double)(Stopwatch.GetTimestamp() - delayedRecord.ProducerTimestampTicks) *
              1000.0 / Stopwatch.Frequency) : 0.0;
      timeWorker.StopAndJoin(2000);
      bool timestampPassed = gotDelayed && delayedRecord.Sequence == 0 &&
          delayedRecord.RawStartOffset == 0 &&
          delayedRecord.ProducerTimestampTicks > 0 && consumerDelay >= 100.0 &&
          delayedRecord.ProducerElapsedMs >= timestampBaseElapsedMs &&
          delayedRecord.ProducerElapsedMs <
              timestampBaseElapsedMs + timestampWatch.Elapsed.TotalMilliseconds &&
          delayedRecord.ProducerPhase == "timestamp_phase" &&
          delayedRecord.ProducerEpoch == "timestamp_epoch";

      BlockingSyntheticByteSource shutdownVehicle =
          new BlockingSyntheticByteSource(19);
      SyntheticByteSource shutdownGround = new SyntheticByteSource(0, 23);
      DualPortReaderWorker shutdownWorker = new DualPortReaderWorker(
          shutdownVehicle, shutdownGround, 16, 32, 0.0, 75.0, 100.0);
      shutdownWorker.SetCaptureContext("before_barrier", "epoch_0");
      shutdownWorker.Start();
      bool readWasInFlight = shutdownVehicle.WaitForReadEntered(2000);
      ReaderBarrier shutdownBarrier = null;
      Exception barrierError = null;
      Thread barrierRequester = new Thread(new ThreadStart(delegate {
        try { shutdownBarrier = shutdownWorker.CaptureBarrier(); }
        catch (Exception error) { barrierError = error; }
      }));
      barrierRequester.IsBackground = true;
      barrierRequester.Start();
      Thread.Sleep(20);
      bool barrierWaitedForInFlightRead = barrierRequester.IsAlive;
      shutdownVehicle.ReleaseRead();
      bool barrierRequesterJoined = barrierRequester.Join(2000);
      bool barrierInFlightPassed = readWasInFlight &&
          barrierWaitedForInFlightRead && barrierRequesterJoined &&
          barrierError == null && shutdownBarrier != null &&
          shutdownBarrier.Vehicle.SequenceExclusive == 1 &&
          shutdownBarrier.Vehicle.RawOffsetExclusive == 32 &&
          shutdownBarrier.Ground.SequenceExclusive == 0;
      bool shutdownJoined = shutdownWorker.StopAndJoin(4000);
      RecordAudit shutdownVehicleAudit = DrainAndAudit(
          shutdownWorker, true, 32);
      RecordAudit shutdownGroundAudit = DrainAndAudit(
          shutdownWorker, false, 0);
      DualReaderSnapshot shutdownSnapshot = shutdownWorker.Snapshot();
      bool shutdownPassed = barrierInFlightPassed && shutdownJoined &&
          shutdownSnapshot.Joined &&
          !shutdownSnapshot.Vehicle.ThreadAlive &&
          !shutdownSnapshot.Ground.ThreadAlive &&
          shutdownSnapshot.Vehicle.QueueDepth == 0 &&
          shutdownSnapshot.Ground.QueueDepth == 0 &&
          shutdownSnapshot.Vehicle.ProducedSequence ==
              shutdownBarrier.Vehicle.SequenceExclusive &&
          shutdownSnapshot.Ground.ProducedSequence ==
              shutdownBarrier.Ground.SequenceExclusive &&
          shutdownVehicleAudit.Valid && shutdownGroundAudit.Valid &&
          shutdownSnapshot.Vehicle.IsConsistent &&
          shutdownSnapshot.Ground.IsConsistent;

      return new WorkerHarnessResult {
        OverflowPassed = overflowPassed,
        TimestampPassed = timestampPassed,
        ShutdownPassed = shutdownPassed,
        BarrierInFlightPassed = barrierInFlightPassed,
        OverflowSnapshot = overflowSnapshot,
        ShutdownSnapshot = shutdownSnapshot,
        OverflowRecordCount = overflowAudit.RecordCount,
        TimestampConsumerDelayMs = consumerDelay,
        TimestampSequence = gotDelayed ? delayedRecord.Sequence : -1,
        TimestampRawStartOffset = gotDelayed ? delayedRecord.RawStartOffset : -1,
        ShutdownVehicleAudit = shutdownVehicleAudit,
        ShutdownGroundAudit = shutdownGroundAudit
      };
    }
  }
}
'@
  $definition = $definition.Replace('__SERIAL_PORT_TYPE__',
      ('System.IO.Ports.' + 'SerialPort'))
  Add-Type -TypeDefinition $definition -Language CSharp
}

function Invoke-ReaderBrokerMode {
  [CmdletBinding()]
  param()

  # These names are intentionally kept beside the mode boundary so the
  # child-side protocol surface can be audited without executing live code.
  [string[]]$protocolCommands = @(
    'HELLO','OPEN_START','DRAIN_BOTH','WRITE_EXACT_FIXTURE',
    'STOP_CAPTURE','CLOSE_EXIT')
  [type]$namedPipeServerType = [System.IO.Pipes.NamedPipeServerStream]
  [bool]$broker_owns_both_serial_ports =
      ($ReaderBrokerScenario -ceq 'serial')
  if ($protocolCommands.Count -ne 6 -or $null -eq $namedPipeServerType) {
    throw 'reader broker protocol declaration was unavailable'
  }
  if ([string]::IsNullOrWhiteSpace($ReaderBrokerPipeName) -or
      $ReaderBrokerPipeName.Length -gt 200) {
    throw 'reader broker pipe name is invalid'
  }
  if ($ReaderBrokerSecret -notmatch '^[0-9A-Fa-f]{64}$') {
    throw 'reader broker secret must be exact 64-hex'
  }
  if ($ReaderBrokerSourceSha256 -notmatch '^[0-9A-Fa-f]{64}$') {
    throw 'reader broker source SHA-256 must be exact 64-hex'
  }
  if ($ReaderBrokerParentPid -le 0) {
    throw 'reader broker parent PID must be positive'
  }
  [string]$actualSourceSha256 = [string](Get-FileHash -Algorithm SHA256 `
      -LiteralPath $PSCommandPath -ErrorAction Stop).Hash
  if (-not [string]::Equals($actualSourceSha256,
      $ReaderBrokerSourceSha256,
      [StringComparison]::OrdinalIgnoreCase)) {
    throw 'reader broker source hash binding failed before port ownership'
  }
  if (-not ('System.IO.Ports.SerialPort' -as [type])) {
    Add-Type -AssemblyName System.IO.Ports
  }
  Initialize-DualPortReaderWorkerType

  if ($ReaderBrokerScenario -ceq 'serial') {
    if (-not $broker_owns_both_serial_ports) {
      throw 'broker_owns_both_serial_ports contract failed'
    }
    return [int][VcDualPortReader.ReaderBrokerServer]::RunSerial(
        $ReaderBrokerPipeName, $ReaderBrokerSecret,
        $ReaderBrokerSourceSha256, $ReaderBrokerParentPid,
        $VehiclePort, $VehicleBaud, $GroundPort, $GroundBaud,
        $ReaderBrokerRingSlots, $script:SerialReadSliceBytes,
        $script:PumpFairnessTargetMs, $script:PumpFairnessHardLimitMs)
  }
  # synthetic scenarios never enumerate, construct, or open a COM port.
  return [int][VcDualPortReader.ReaderBrokerServer]::RunSynthetic(
      $ReaderBrokerPipeName, $ReaderBrokerSecret,
      $ReaderBrokerSourceSha256, $ReaderBrokerParentPid,
      $ReaderBrokerScenario, $ReaderBrokerRingSlots,
      $ReaderBrokerVehicleBytes, $ReaderBrokerGroundBytes,
      $script:SerialReadSliceBytes, $script:PumpFairnessTargetMs,
      $script:PumpFairnessHardLimitMs)
}

function ConvertTo-WindowsCommandLineArgument {
  [CmdletBinding()]
  param([AllowEmptyString()][string]$Value = '')

  if ($null -eq $Value) { $Value = '' }
  $builder = New-Object System.Text.StringBuilder
  [void]$builder.Append('"')
  [int]$backslashCount = 0
  foreach ($character in $Value.ToCharArray()) {
    if ($character -eq [char]92) {
      ++$backslashCount
      continue
    }
    if ($character -eq [char]34) {
      if ($backslashCount -gt 0) {
        [void]$builder.Append(([string][char]92) *
            (2 * $backslashCount))
      }
      [void]$builder.Append(([string][char]92) + ([string][char]34))
      $backslashCount = 0
      continue
    }
    if ($backslashCount -gt 0) {
      [void]$builder.Append(([string][char]92) * $backslashCount)
      $backslashCount = 0
    }
    [void]$builder.Append($character)
  }
  if ($backslashCount -gt 0) {
    [void]$builder.Append(([string][char]92) * (2 * $backslashCount))
  }
  [void]$builder.Append('"')
  return $builder.ToString()
}

function New-ReaderClockAnchor {
  [CmdletBinding()]
  param(
    [Parameter(Mandatory = $true)]
    [System.Diagnostics.Stopwatch]$RunWatch
  )
  [long]$beforeTicks = [System.Diagnostics.Stopwatch]::GetTimestamp()
  [double]$baseElapsedMs = [double]$RunWatch.Elapsed.TotalMilliseconds
  [long]$afterTicks = [System.Diagnostics.Stopwatch]::GetTimestamp()
  if ($afterTicks -lt $beforeTicks) {
    throw 'Reader clock anchor QPC bracket moved backwards.'
  }
  [long]$originTicks = $beforeTicks + [long][Math]::Floor(
      [double]($afterTicks - $beforeTicks) / 2.0)
  return [pscustomobject][ordered]@{
    qpc_origin_ticks=$originTicks
    base_elapsed_ms=$baseElapsedMs
    bracket_before_qpc_ticks=$beforeTicks
    bracket_after_qpc_ticks=$afterTicks
    bracket_span_qpc_ticks=[long]($afterTicks - $beforeTicks)
  }
}

function New-PumpFairnessRoleState {
  param(
    [Parameter(Mandatory = $true)][string]$Role,
    [Parameter(Mandatory = $true)][double]$StartedElapsedMs
  )
  return [pscustomobject][ordered]@{
    role=$Role;service_count=[uint64]0;bytes_read=[uint64]0
    zero_byte_service_count=[uint64]0
    last_service_started_elapsed_ms=$StartedElapsedMs
    last_service_start_raw_offset=[long]0
    last_service_start_gc0=[int][GC]::CollectionCount(0)
    last_service_start_gc1=[int][GC]::CollectionCount(1)
    last_service_start_gc2=[int][GC]::CollectionCount(2)
    max_service_gap_ms=[double]0;max_service_gap_phase=$null
    service_gap_over_target_count=[uint64]0
    service_gap_over_hard_limit_count=[uint64]0
    max_read_parse_duration_ms=[double]0
    max_read_parse_duration_phase=$null
    max_read_parse_duration_bytes=0
    read_parse_duration_over_target_count=[uint64]0
    read_parse_duration_over_hard_limit_count=[uint64]0
    service_active=$false
    service_started_elapsed_ms=[double]0
    service_start_raw_offset=[long]0
    service_start_phase=$null
    service_start_admin_stage=$null
    service_start_gc0=[int]0;service_start_gc1=[int]0
    service_start_gc2=[int]0
    reentry_count=[uint64]0
    completion_without_start_count=[uint64]0
    integrity_failure_latched=$false
    violation_event_total_count=[uint64]0
    violation_event_overflow_count=[uint64]0
    violation_events=New-Object 'System.Collections.Generic.List[object]'
  }
}

function New-PumpFairnessState {
  param([Parameter(Mandatory = $true)][double]$StartedElapsedMs)
  return [pscustomobject][ordered]@{
    schema_version=2
    target_ms=$script:PumpFairnessTargetMs
    hard_limit_ms=$script:PumpFairnessHardLimitMs
    started_elapsed_ms=$StartedElapsedMs
    vehicle=New-PumpFairnessRoleState -Role 'vehicle' `
        -StartedElapsedMs $StartedElapsedMs
    ground=New-PumpFairnessRoleState -Role 'ground' `
        -StartedElapsedMs $StartedElapsedMs
  }
}

function New-PumpFairnessStateFromReaderClockAnchor {
  [CmdletBinding()]
  param([Parameter(Mandatory = $true)]$ClockAnchor)
  $qpcProperty = $ClockAnchor.PSObject.Properties['qpc_origin_ticks']
  $baseProperty = $ClockAnchor.PSObject.Properties['base_elapsed_ms']
  if ($null -eq $qpcProperty -or $null -eq $baseProperty) {
    throw 'Reader clock anchor requires qpc_origin_ticks/base_elapsed_ms.'
  }
  if ($null -eq $qpcProperty.Value -or
      -not ($qpcProperty.Value -is [long])) {
    throw 'Reader clock anchor qpc_origin_ticks must be Int64.'
  }
  if ($null -eq $baseProperty.Value -or
      -not ($baseProperty.Value -is [double])) {
    throw 'Reader clock anchor base_elapsed_ms must be Double.'
  }
  [long]$qpcOriginTicks = [long]$qpcProperty.Value
  [double]$startedElapsedMs = [double]$baseProperty.Value
  if ($qpcOriginTicks -le 0) {
    throw 'Reader clock anchor qpc_origin_ticks must be positive.'
  }
  if ([double]::IsNaN($startedElapsedMs) -or
      [double]::IsInfinity($startedElapsedMs) -or
      $startedElapsedMs -lt 0.0) {
    throw 'Reader clock anchor base_elapsed_ms must be finite/nonnegative.'
  }
  $state = New-PumpFairnessState -StartedElapsedMs $startedElapsedMs
  if ([double]$state.started_elapsed_ms -ne $startedElapsedMs -or
      [double]$state.vehicle.last_service_started_elapsed_ms -ne
          $startedElapsedMs -or
      [double]$state.ground.last_service_started_elapsed_ms -ne
          $startedElapsedMs) {
    throw 'Reader clock anchor was not preserved by pump fairness state.'
  }
  return $state
}

function Start-ReaderBrokerClient {
  [CmdletBinding()]
  param(
    [ValidateSet('serial','pressure','overflow','timestamp','barrier','ackloss','openio')]
    [string]$Scenario = 'serial',
    [ValidateRange(1,65536)][int]$RingSlots =
        $script:ReaderRingSlotCount,
    [ValidateRange(0,1048576)][int]$VehicleBytes = 0,
    [ValidateRange(0,1048576)][int]$GroundBytes = 0,
    [ValidateRange(1000,120000)][int]$ConnectTimeoutMs = 30000,
    [double]$BaseElapsedMs = [double]::NaN,
    [long]$QpcOriginTicks = 0,
    [Parameter(Mandatory = $true)]
    [ValidatePattern('^[0-9A-F]{64}$')]
    [string]$ExpectedRunnerSha256,
    [string]$InitialPhase = '',
    [string]$InitialEpoch = '',
    [ValidateRange(0,65536)][int]$SelfTestExpectedRingSlots = 0
  )

  # Parent owns this handle. JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE guarantees
  # cleanup if the parent terminates without the normal STOP/CLOSE sequence.
  # Native containment call: AssignProcessToJobObject.
  [uint32]$JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE = [uint32]0x00002000
  [type]$namedPipeClientType = [System.IO.Pipes.NamedPipeClientStream]
  if ($null -eq $namedPipeClientType -or
      $JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE -ne [uint32]0x00002000) {
    throw 'NamedPipeClientStream/job containment contract unavailable'
  }
  if (-not ('System.IO.Ports.SerialPort' -as [type])) {
    Add-Type -AssemblyName System.IO.Ports
  }
  Initialize-DualPortReaderWorkerType
  [string]$sourcePath = (Resolve-Path -LiteralPath $PSCommandPath).Path
  [string]$launchSourceSha256 = [string](Get-FileHash -Algorithm SHA256 `
      -LiteralPath $sourcePath -ErrorAction Stop).Hash
  if (-not [string]::Equals($launchSourceSha256,
      $ExpectedRunnerSha256, [StringComparison]::Ordinal)) {
    throw ('reader broker launch refused source mutation: initial=' +
        $ExpectedRunnerSha256 + ' launch=' + $launchSourceSha256)
  }
  [string]$runner_sha256 = $ExpectedRunnerSha256
  [string]$pipeName = ('vc_lora_reader_' +
      [Guid]::NewGuid().ToString('N'))
  [string]$secret = (([Guid]::NewGuid().ToString('N')) +
      ([Guid]::NewGuid().ToString('N'))).ToUpperInvariant()
  [bool]$callerClockPairProvided = ($QpcOriginTicks -gt 0 -and
      -not [double]::IsNaN($BaseElapsedMs))
  if ($Scenario -ceq 'serial' -and -not $callerClockPairProvided) {
    throw 'Serial reader broker requires a caller-sampled QPC/RunWatch pair.'
  }
  [string]$clockAnchorSource = 'caller_supplied_pair'
  if ($QpcOriginTicks -le 0) {
    if ([double]::IsNaN($BaseElapsedMs)) {
      if ($null -ne $script:RunWatch) {
        $localClockAnchor = New-ReaderClockAnchor -RunWatch $script:RunWatch
        $QpcOriginTicks = [long]$localClockAnchor.qpc_origin_ticks
        $BaseElapsedMs = [double]$localClockAnchor.base_elapsed_ms
        $clockAnchorSource = 'local_runwatch_pair'
      } else {
        $QpcOriginTicks = [System.Diagnostics.Stopwatch]::GetTimestamp()
        $BaseElapsedMs = [double]0.0
        $clockAnchorSource = 'local_zero_pair'
      }
    } else {
      $QpcOriginTicks = [System.Diagnostics.Stopwatch]::GetTimestamp()
      $clockAnchorSource = 'synthetic_explicit_base_local_qpc'
    }
  } elseif ([double]::IsNaN($BaseElapsedMs)) {
    throw 'Reader clock anchor QPC origin has no matching elapsed base.'
  }
  [long]$qpcOriginTicks = [long]$QpcOriginTicks
  [long]$qpc_frequency = [System.Diagnostics.Stopwatch]::Frequency
  if ([string]::IsNullOrWhiteSpace($InitialPhase)) {
    $InitialPhase = if ($Scenario -ceq 'serial') {
      'ports_opening'
    } else { 'synthetic_' + $Scenario }
  }
  if ([string]::IsNullOrWhiteSpace($InitialEpoch)) {
    $InitialEpoch = if ($Scenario -ceq 'serial') {
      'boot_observe'
    } else { $InitialPhase }
  }

  [string]$powerShellExe = (Get-Command powershell.exe `
      -ErrorAction Stop).Source
  $argumentParts = New-Object 'System.Collections.Generic.List[string]'
  foreach ($literal in @('-NoProfile','-NonInteractive',
      '-ExecutionPolicy','Bypass','-File')) {
    $argumentParts.Add($literal)
  }
  $argumentParts.Add((ConvertTo-WindowsCommandLineArgument `
      -Value $sourcePath))
  $argumentParts.Add('-ReaderBrokerMode')
  foreach ($pair in @(
      @('-ReaderBrokerPipeName',$pipeName),
      @('-ReaderBrokerSecret',$secret),
      @('-ReaderBrokerSourceSha256',$runner_sha256),
      @('-ReaderBrokerScenario',$Scenario),
      @('-ReaderBrokerRingSlots',[string]$RingSlots),
      @('-ReaderBrokerVehicleBytes',[string]$VehicleBytes),
      @('-ReaderBrokerGroundBytes',[string]$GroundBytes),
      @('-ReaderBrokerParentPid',[string]$PID),
      @('-VehiclePort',$VehiclePort),
      @('-VehicleBaud',[string]$VehicleBaud),
      @('-GroundPort',$GroundPort),
      @('-GroundBaud',[string]$GroundBaud))) {
    $argumentParts.Add([string]$pair[0])
    $argumentParts.Add((ConvertTo-WindowsCommandLineArgument `
        -Value ([string]$pair[1])))
  }

  $process = $null
  $client = $null
  [IntPtr]$jobHandle = [IntPtr]::Zero
  try {
    $process = Start-Process -FilePath $powerShellExe `
        -ArgumentList ($argumentParts -join ' ') -PassThru `
        -WindowStyle Hidden
    $jobHandle =
        [VcDualPortReader.BrokerProcessContainment]::CreateKillOnCloseJob()
    [VcDualPortReader.BrokerProcessContainment]::AssignProcessToKillOnCloseJob(
        $jobHandle, $process)
    [string]$expectedVehiclePort = if ($Scenario -ceq 'serial') {
      $VehiclePort
    } else { '' }
    [int]$expectedVehicleBaud = if ($Scenario -ceq 'serial') {
      $VehicleBaud
    } else { 0 }
    [string]$expectedGroundPort = if ($Scenario -ceq 'serial') {
      $GroundPort
    } else { '' }
    [int]$expectedGroundBaud = if ($Scenario -ceq 'serial') {
      $GroundBaud
    } else { 0 }
    # Live and synthetic launch paths must use the strict 20-argument
    # overload. The legacy seven-argument overload is compile compatibility
    # only and is forbidden here.
    [int]$expectedRingSlots = if ($SelfTestExpectedRingSlots -gt 0) {
      $SelfTestExpectedRingSlots
    } else { $RingSlots }
    $client = [VcDualPortReader.ReaderBrokerClient]::Connect(
        $pipeName, $secret, $runner_sha256, $ConnectTimeoutMs,
        $qpcOriginTicks, $BaseElapsedMs, [int]$process.Id,
        $expectedRingSlots, $script:SerialReadSliceBytes,
        $script:PumpFairnessTargetMs, $script:PumpFairnessHardLimitMs,
        20, 2000, $Scenario, $expectedVehiclePort,
        $expectedVehicleBaud, $expectedGroundPort, $expectedGroundBaud,
        $InitialPhase, $InitialEpoch)
    $bundle = [VcDualPortReader.ReaderBrokerClientBundle]::Create($client)
    $lifecycle = [pscustomobject][ordered]@{
      schema_version=1
      runner_sha256=$runner_sha256
      launch_source_sha256=$launchSourceSha256
      source_immutable_from_initial_hash=$true
      protocol_version=$script:ReaderBrokerProtocolVersion
      protocol_sequence=[long]$client.ProtocolSequence
      bounded_record_count=[int]0
      context_id=[uint32]$client.ContextId
      initial_phase=$InitialPhase
      initial_epoch=$InitialEpoch
      qpc_frequency=$qpc_frequency
      clock_anchor=[ordered]@{
        source=$clockAnchorSource
        caller_pair_provided=$callerClockPairProvided
        qpc_origin_ticks=$qpcOriginTicks
        base_elapsed_ms=[double]$BaseElapsedMs
      }
      negotiated_ring_slots=$RingSlots
      negotiated_read_slice_bytes=$script:SerialReadSliceBytes
      negotiated_target_ms=$script:PumpFairnessTargetMs
      negotiated_hard_limit_ms=$script:PumpFairnessHardLimitMs
      negotiated_read_timeout_ms=20
      negotiated_write_timeout_ms=2000
      broker_owns_both_serial_ports=($Scenario -ceq 'serial')
      stop_capture_sent=$false
      stop_capture_request_qpc_ticks=$null
      stop_capture_ack_qpc_ticks=$null
      stop_capture_valid=$false
      capture_footer_recorded=$false
      capture_footer_fsync_elapsed_ms=$null
      capture_footer_fsync_qpc_ticks=$null
      close_exit_sent=$false
      close_exit_ack_qpc_ticks=$null
      ground_close_succeeded=$false
      ground_close_qpc_ticks=$null
      vehicle_close_succeeded=$false
      vehicle_close_qpc_ticks=$null
      exact_fixture_expected_attempted_at_close=$false
      exact_fixture_expected_at_close=$false
      exact_fixture_attempted_by_child=$false
      exact_fixture_accepted_by_child=$false
      ground_written_bytes=$null
      ground_write_operation_count=$null
      ground_flush_count=$null
      ground_last_write_operation_ordinal=$null
      ground_last_flush_operation_ordinal=$null
      vehicle_written_bytes=$null
      vehicle_write_operation_count=$null
      vehicle_flush_count=$null
      vehicle_last_write_operation_ordinal=$null
      vehicle_last_flush_operation_ordinal=$null
      broker_process_exited=$false
      broker_exit_code=$null
      broker_process_exit_elapsed_ms=$null
      job_assigned_before_open_start=$true
      final_seal_after_broker_exit=$false
      lifecycle_valid=$false
    }
    return [pscustomobject][ordered]@{
      client=$client
      worker=$client
      vehicle_proxy=$bundle.VehicleProxy
      ground_proxy=$bundle.GroundProxy
      process=$process
      job_handle=$jobHandle
      lifecycle=$lifecycle
      pipe_name=$pipeName
      scenario=$Scenario
    }
  } catch {
    if ($null -ne $client) { try { $client.Dispose() } catch {} }
    if ($null -ne $process -and -not $process.HasExited) {
      try { $process.Kill() } catch {}
      try {
        if ($process.WaitForExit(5000)) {
          $process.WaitForExit()
          $process.Refresh()
        }
      } catch {}
    }
    if ($jobHandle -ne [IntPtr]::Zero) {
      [VcDualPortReader.BrokerProcessContainment]::CloseJob($jobHandle)
    }
    throw
  }
}

function Stop-ReaderBrokerAndDrain {
  [CmdletBinding()]
  param(
    [Parameter(Mandatory = $true)]$Bundle,
    [Parameter(Mandatory = $true)]$VehicleState,
    [Parameter(Mandatory = $true)]$GroundState
  )

  if ($null -eq $Bundle.client -or $null -eq $Bundle.lifecycle) {
    throw 'reader broker STOP_CAPTURE bundle was incomplete'
  }
  $Bundle.lifecycle.stop_capture_request_qpc_ticks =
      [System.Diagnostics.Stopwatch]::GetTimestamp()
  $Bundle.lifecycle.stop_capture_sent = $true
  $shutdown = Stop-DualPortReaderWorkerAndDrain `
      -VehicleState $VehicleState -GroundState $GroundState
  $Bundle.lifecycle.stop_capture_ack_qpc_ticks =
      [System.Diagnostics.Stopwatch]::GetTimestamp()
  $Bundle.lifecycle.protocol_sequence =
      [long]$Bundle.client.ProtocolSequence
  $Bundle.lifecycle.context_id = [uint32]$Bundle.client.ContextId
  $Bundle.lifecycle.stop_capture_valid =
      ([bool]$shutdown.joined -and [bool]$shutdown.valid)
  return $shutdown
}

function Close-ReaderBrokerAfterFooter {
  [CmdletBinding()]
  param(
    [Parameter(Mandatory = $true)]$Bundle,
    [Parameter(Mandatory = $true)][bool]$FooterRecorded,
    [Parameter(Mandatory = $true)][double]$FooterFsyncElapsedMs,
    [Parameter(Mandatory = $true)][long]$FooterFsyncQpcTicks,
    [Parameter(Mandatory = $true)][bool]$ExpectedExactFixtureAttempted,
    [Parameter(Mandatory = $true)][bool]$ExpectedExactFixtureAccepted,
    [ValidateRange(1000,60000)][int]$ProcessExitTimeoutMs = 10000
  )

  if (-not $FooterRecorded -or
      -not [bool]$Bundle.lifecycle.stop_capture_valid) {
    throw 'reader broker CLOSE_EXIT requires a durable footer after valid STOP_CAPTURE'
  }
  $Bundle.lifecycle.capture_footer_recorded = $true
  $Bundle.lifecycle.capture_footer_fsync_elapsed_ms =
      [Math]::Round($FooterFsyncElapsedMs,3)
  $Bundle.lifecycle.capture_footer_fsync_qpc_ticks = $FooterFsyncQpcTicks
  $Bundle.client.CloseExit()
  $Bundle.lifecycle.close_exit_sent = $true
  $Bundle.lifecycle.close_exit_ack_qpc_ticks =
      [System.Diagnostics.Stopwatch]::GetTimestamp()
  $closeReport = $Bundle.client.LatestCloseReport
  $Bundle.lifecycle.ground_close_succeeded =
      [bool]$closeReport.GroundCloseSucceeded
  $Bundle.lifecycle.ground_close_qpc_ticks =
      [long]$closeReport.GroundCloseQpcTicks
  $Bundle.lifecycle.vehicle_close_succeeded =
      [bool]$closeReport.VehicleCloseSucceeded
  $Bundle.lifecycle.vehicle_close_qpc_ticks =
      [long]$closeReport.VehicleCloseQpcTicks
  $Bundle.lifecycle.exact_fixture_expected_attempted_at_close =
      $ExpectedExactFixtureAttempted
  $Bundle.lifecycle.exact_fixture_expected_at_close =
      $ExpectedExactFixtureAccepted
  $Bundle.lifecycle.exact_fixture_attempted_by_child =
      [bool]$closeReport.ExactFixtureAttempted
  $Bundle.lifecycle.exact_fixture_accepted_by_child =
      [bool]$closeReport.ExactFixtureAccepted
  $Bundle.lifecycle.ground_written_bytes =
      [long]$closeReport.GroundWrittenBytes
  $Bundle.lifecycle.ground_write_operation_count =
      [long]$closeReport.GroundWriteOperationCount
  $Bundle.lifecycle.ground_flush_count =
      [long]$closeReport.GroundFlushCount
  $Bundle.lifecycle.ground_last_write_operation_ordinal =
      [long]$closeReport.GroundLastWriteOperationOrdinal
  $Bundle.lifecycle.ground_last_flush_operation_ordinal =
      [long]$closeReport.GroundLastFlushOperationOrdinal
  $Bundle.lifecycle.vehicle_written_bytes =
      [long]$closeReport.VehicleWrittenBytes
  $Bundle.lifecycle.vehicle_write_operation_count =
      [long]$closeReport.VehicleWriteOperationCount
  $Bundle.lifecycle.vehicle_flush_count =
      [long]$closeReport.VehicleFlushCount
  $Bundle.lifecycle.vehicle_last_write_operation_ordinal =
      [long]$closeReport.VehicleLastWriteOperationOrdinal
  $Bundle.lifecycle.vehicle_last_flush_operation_ordinal =
      [long]$closeReport.VehicleLastFlushOperationOrdinal

  [bool]$boundedExit = $Bundle.process.WaitForExit($ProcessExitTimeoutMs)
  if (-not $boundedExit) {
    if ($Bundle.job_handle -ne [IntPtr]::Zero) {
      [VcDualPortReader.BrokerProcessContainment]::CloseJob(
          $Bundle.job_handle)
      $Bundle.job_handle = [IntPtr]::Zero
    }
    if (-not $Bundle.process.WaitForExit(5000)) {
      try { $Bundle.process.Kill() } catch {}
      [void]$Bundle.process.WaitForExit(5000)
    }
    throw 'reader broker process exit exceeded its bounded deadline'
  }
  # Windows PowerShell 5.1 requires the parameterless wait before ExitCode
  # is reliable after redirected/asynchronous process completion.
  $Bundle.process.WaitForExit()
  $Bundle.process.Refresh()
  $Bundle.lifecycle.broker_process_exited = $true
  $Bundle.lifecycle.broker_exit_code = [int]$Bundle.process.ExitCode
  $Bundle.lifecycle.broker_process_exit_elapsed_ms = if (
      $null -ne $script:RunWatch) {
    [Math]::Round($script:RunWatch.Elapsed.TotalMilliseconds,3)
  } else { [double]0.0 }
  if ($Bundle.job_handle -ne [IntPtr]::Zero) {
    [VcDualPortReader.BrokerProcessContainment]::CloseJob(
        $Bundle.job_handle)
    $Bundle.job_handle = [IntPtr]::Zero
  }
  [bool]$ordered = (
    [long]$Bundle.lifecycle.stop_capture_ack_qpc_ticks -le
        $FooterFsyncQpcTicks -and
    $FooterFsyncQpcTicks -lt
        [long]$Bundle.lifecycle.ground_close_qpc_ticks -and
    $FooterFsyncQpcTicks -lt
        [long]$Bundle.lifecycle.vehicle_close_qpc_ticks -and
    [long]$Bundle.lifecycle.ground_close_qpc_ticks -le
        [long]$Bundle.lifecycle.close_exit_ack_qpc_ticks -and
    [long]$Bundle.lifecycle.vehicle_close_qpc_ticks -le
        [long]$Bundle.lifecycle.close_exit_ack_qpc_ticks)
  $Bundle.lifecycle.lifecycle_valid = (
    $ordered -and $Bundle.lifecycle.ground_close_succeeded -and
    $Bundle.lifecycle.vehicle_close_succeeded -and
    [bool]$Bundle.lifecycle.exact_fixture_attempted_by_child -eq
        $ExpectedExactFixtureAttempted -and
    [bool]$Bundle.lifecycle.exact_fixture_accepted_by_child -eq
        $ExpectedExactFixtureAccepted -and
    (-not $ExpectedExactFixtureAccepted -or
      ($ExpectedExactFixtureAttempted -and
       [long]$Bundle.lifecycle.ground_written_bytes -ge 14 -and
       [long]$Bundle.lifecycle.ground_write_operation_count -ge 1 -and
       [long]$Bundle.lifecycle.ground_flush_count -ge 1)) -and
    $Bundle.lifecycle.broker_process_exited -and
    [int]$Bundle.lifecycle.broker_exit_code -eq 0)
  if (-not $Bundle.lifecycle.lifecycle_valid) {
    throw 'reader broker STOP_CAPTURE/footer/CLOSE_EXIT/exit ordering was invalid'
  }
  return $Bundle.lifecycle
}

function Stop-ReaderBrokerEmergency {
  [CmdletBinding()]
  param([Parameter(Mandatory = $true)]$Bundle)

  try { if ($null -ne $Bundle.client) { $Bundle.client.Dispose() } } catch {}
  if ($Bundle.job_handle -ne [IntPtr]::Zero) {
    try {
      [VcDualPortReader.BrokerProcessContainment]::CloseJob(
          $Bundle.job_handle)
    } catch {}
    $Bundle.job_handle = [IntPtr]::Zero
  }
  if ($null -ne $Bundle.process -and -not $Bundle.process.HasExited) {
    try {
      if (-not $Bundle.process.WaitForExit(5000)) {
        $Bundle.process.Kill()
        [void]$Bundle.process.WaitForExit(5000)
      }
    } catch {}
  }
  if ($null -ne $Bundle.process -and $Bundle.process.HasExited) {
    try {
      $Bundle.process.WaitForExit()
      $Bundle.process.Refresh()
      $Bundle.lifecycle.broker_process_exited = $true
      $Bundle.lifecycle.broker_exit_code = [int]$Bundle.process.ExitCode
    } catch {}
  }
  return $Bundle.lifecycle
}

function Set-ReaderCaptureContext {
  param(
    [Parameter(Mandatory = $true)][string]$Phase,
    [string]$Epoch = ''
  )
  if ($null -eq $script:DualPortReaderWorker) { return $null }
  if ([string]::IsNullOrEmpty($Epoch)) { $Epoch = $Phase }
  $transitionBarrier =
      $script:DualPortReaderWorker.TransitionCaptureContext($Phase, $Epoch)
  return Invoke-ReaderBarrierDrain -VehicleState $script:vehicleCapture `
      -GroundState $script:groundCapture -Barrier $transitionBarrier
}

function Get-SerialReadSliceSize {
  param(
    [int]$Available,
    [int]$BufferLength,
    [int]$MaximumBytesPerRead = $script:SerialReadSliceBytes
  )
  if ($Available -le 0 -or $BufferLength -le 0 -or
      $MaximumBytesPerRead -le 0) {
    return 0
  }
  return [int][Math]::Min($Available,
      [Math]::Min($BufferLength, $MaximumBytesPerRead))
}

function Get-MaxReadinessPumpCheckpointCount {
  param(
    [Parameter(Mandatory = $true)][int]$TimeoutSeconds,
    [Parameter(Mandatory = $true)][int]$SnapshotTimeoutSeconds
  )
  [int]$boundedSnapshotSeconds = [Math]::Min($SnapshotTimeoutSeconds, 20)
  [int]$pipelineReserveSeconds = $boundedSnapshotSeconds + 13
  [int]$availableFiveSecondWindows = [Math]::Max(0,
      [Math]::Floor(($TimeoutSeconds - $pipelineReserveSeconds) / 5.0))
  [int]$pairedWindows = [Math]::Floor($availableFiveSecondWindows / 2.0)
  [int]$remainder = $availableFiveSecondWindows % 2
  [int]$candidateCount = if ($availableFiveSecondWindows -gt 0) {
    $pairedWindows + 1
  } else { 0 }
  [int]$passiveCount = $candidateCount + $remainder
  [int]$scheduledFsyncCheckpointCount =
      2 * [Math]::Floor($TimeoutSeconds / 25.0)
  [int]$maximum =
      $script:ReadinessInitialAndFinallyCheckpointCount +
      ($script:ReadinessPassiveCheckpointCount * $passiveCount) +
      ($script:ReadinessBracketCheckpointCount * $candidateCount) +
      $scheduledFsyncCheckpointCount
  return [pscustomobject][ordered]@{
    timeout_seconds=$TimeoutSeconds
    bounded_snapshot_seconds=$boundedSnapshotSeconds
    pipeline_reserve_seconds=$pipelineReserveSeconds
    available_five_second_windows=$availableFiveSecondWindows
    passive_attempt_maximum=$passiveCount
    candidate_attempt_maximum=$candidateCount
    scheduled_fsync_checkpoint_maximum=$scheduledFsyncCheckpointCount
    calculated_checkpoint_maximum=$maximum
    fixed_cap=$script:MaxReadinessPumpCheckpointEvents
    valid=($maximum -le $script:MaxReadinessPumpCheckpointEvents)
  }
}

function Get-ReadinessRawFsyncAgeDecision {
  param(
    [Parameter(Mandatory = $true)][double]$LastRawFlushElapsedMs,
    [Parameter(Mandatory = $true)][double]$CurrentElapsedMs
  )
  [double]$ageMs = $CurrentElapsedMs - $LastRawFlushElapsedMs
  [bool]$finite = (-not [double]::IsNaN($LastRawFlushElapsedMs) -and
    -not [double]::IsInfinity($LastRawFlushElapsedMs) -and
    -not [double]::IsNaN($CurrentElapsedMs) -and
    -not [double]::IsInfinity($CurrentElapsedMs) -and
    -not [double]::IsNaN($ageMs) -and
    -not [double]::IsInfinity($ageMs))
  [bool]$valid = ($finite -and $LastRawFlushElapsedMs -ge 0.0 -and
    $CurrentElapsedMs -ge $LastRawFlushElapsedMs -and
    $ageMs -le $script:RawCaptureFlushIntervalMs)
  return [pscustomobject][ordered]@{
    last_raw_flush_elapsed_ms=$LastRawFlushElapsedMs
    current_elapsed_ms=$CurrentElapsedMs
    age_ms=$ageMs
    hard_limit_ms=$script:RawCaptureFlushIntervalMs
    finite=$finite
    valid=$valid
  }
}

function Get-BytesSha256 {
  param([Parameter(Mandatory = $true)][AllowEmptyCollection()][byte[]]$Bytes)
  $algorithm = [System.Security.Cryptography.SHA256]::Create()
  try {
    [byte[]]$hash = $algorithm.ComputeHash($Bytes)
  } finally {
    $algorithm.Dispose()
  }
  return (($hash | ForEach-Object { $_.ToString('X2') }) -join '')
}

function ConvertTo-Hex {
  param([Parameter(Mandatory = $true)][AllowEmptyCollection()][byte[]]$Bytes)
  return (($Bytes | ForEach-Object { $_.ToString('X2') }) -join '')
}

function ConvertFrom-Hex {
  param([Parameter(Mandatory = $true)][string]$Hex)
  if (($Hex.Length % 2) -ne 0 -or $Hex -notmatch '^[0-9A-Fa-f]*$') {
    throw 'Invalid hexadecimal input.'
  }
  [byte[]]$bytes = New-Object byte[] ($Hex.Length / 2)
  for ($index = 0; $index -lt $bytes.Length; ++$index) {
    $bytes[$index] = [Convert]::ToByte($Hex.Substring($index * 2, 2), 16)
  }
  return $bytes
}

function Write-BytesDurable {
  param(
    [Parameter(Mandatory = $true)][string]$Path,
    [Parameter(Mandatory = $true)][AllowNull()]
    [AllowEmptyCollection()][byte[]]$Bytes
  )
  if ($null -eq $Bytes) { $Bytes = [byte[]]@() }
  $stream = New-Object System.IO.FileStream(
      $Path,
      [System.IO.FileMode]::CreateNew,
      [System.IO.FileAccess]::Write,
      [System.IO.FileShare]::Read,
      4096,
      [System.IO.FileOptions]::WriteThrough)
  try {
    if ($Bytes.Length -gt 0) { $stream.Write($Bytes, 0, $Bytes.Length) }
    $stream.Flush($true)
  } finally {
    $stream.Dispose()
  }
}

function Write-TextDurable {
  param(
    [Parameter(Mandatory = $true)][string]$Path,
    [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Text
  )
  $encoding = New-Object System.Text.UTF8Encoding($false)
  Write-BytesDurable -Path $Path -Bytes $encoding.GetBytes($Text)
}

function Write-JsonDurable {
  param(
    [Parameter(Mandatory = $true)][string]$Path,
    [Parameter(Mandatory = $true)]$Value,
    [int]$Depth = 30
  )
  [string]$json = if ($Value -is [Array]) {
    if ($Value.Count -eq 0) {
      '[]'
    } else {
      ConvertTo-Json -InputObject $Value -Depth $Depth
    }
  } else {
    $Value | ConvertTo-Json -Depth $Depth
  }
  $json = [regex]::Replace($json, '\[\s*\]', '[]')
  [string]$text = $json + [Environment]::NewLine
  Write-TextDurable -Path $Path -Text $text
}

function New-DurableJsonlStream {
  param([Parameter(Mandatory = $true)][string]$Path)
  return (New-Object System.IO.FileStream(
      $Path,
      [System.IO.FileMode]::CreateNew,
      [System.IO.FileAccess]::Write,
      [System.IO.FileShare]::Read,
      4096,
      [System.IO.FileOptions]::WriteThrough))
}

function Open-DurableJsonlAppendStream {
  param([Parameter(Mandatory = $true)][string]$Path)
  if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
    throw "Durable JSONL append target is missing: $Path"
  }
  return (New-Object System.IO.FileStream(
      $Path,
      [System.IO.FileMode]::Append,
      [System.IO.FileAccess]::Write,
      [System.IO.FileShare]::Read,
      4096,
      [System.IO.FileOptions]::WriteThrough))
}

function Seal-EvidenceStreamsBeforeRawHash {
  param(
    [Parameter(Mandatory = $true)]$VehicleRawStream,
    [Parameter(Mandatory = $true)]$GroundRawStream,
    [Parameter(Mandatory = $true)]$LiveProgressStream,
    [Parameter(Mandatory = $true)][string]$VehicleRawPath,
    [Parameter(Mandatory = $true)][string]$GroundRawPath,
    [Parameter(Mandatory = $true)][long]$ExpectedVehicleBytes,
    [Parameter(Mandatory = $true)][long]$ExpectedGroundBytes
  )
  $closeErrors = New-Object 'System.Collections.Generic.List[string]'
  try {
    if ($VehicleRawStream.CanWrite) { $VehicleRawStream.Flush($true) }
  } catch { $closeErrors.Add("vehicle raw Flush(true): $($_.Exception.Message)") }
  try {
    if ($GroundRawStream.CanWrite) { $GroundRawStream.Flush($true) }
  } catch { $closeErrors.Add("ground raw Flush(true): $($_.Exception.Message)") }
  try {
    if ($LiveProgressStream.CanWrite) { $LiveProgressStream.Flush($true) }
  } catch { $closeErrors.Add("live progress Flush(true): $($_.Exception.Message)") }
  try { $VehicleRawStream.Dispose() } catch {
    $closeErrors.Add("vehicle raw Dispose: $($_.Exception.Message)")
  }
  try { $GroundRawStream.Dispose() } catch {
    $closeErrors.Add("ground raw Dispose: $($_.Exception.Message)")
  }
  try { $LiveProgressStream.Dispose() } catch {
    $closeErrors.Add("live progress Dispose: $($_.Exception.Message)")
  }
  if ($closeErrors.Count -ne 0) {
    throw ('Evidence stream close failed before hashing: ' +
      ($closeErrors.ToArray() -join '; '))
  }

  $vehicleFile = Get-Item -LiteralPath $VehicleRawPath -ErrorAction Stop
  $groundFile = Get-Item -LiteralPath $GroundRawPath -ErrorAction Stop
  if ([long]$vehicleFile.Length -ne $ExpectedVehicleBytes -or
      [long]$groundFile.Length -ne $ExpectedGroundBytes) {
    throw ('Raw evidence length mismatch after close: vehicle={0}/{1} ' +
      'ground={2}/{3}' -f [long]$vehicleFile.Length,
      $ExpectedVehicleBytes, [long]$groundFile.Length, $ExpectedGroundBytes)
  }
  $vehicleHashResult = Get-FileHash -Algorithm SHA256 `
      -LiteralPath $VehicleRawPath -ErrorAction Stop
  [string]$vehicleSha256 = [string]$vehicleHashResult.Hash
  $groundHashResult = Get-FileHash -Algorithm SHA256 `
      -LiteralPath $GroundRawPath -ErrorAction Stop
  [string]$groundSha256 = [string]$groundHashResult.Hash
  if ($vehicleSha256 -notmatch '^[0-9A-F]{64}$' -or
      $groundSha256 -notmatch '^[0-9A-F]{64}$') {
    throw 'Raw evidence SHA-256 result was not an exact uppercase 64-hex value.'
  }
  return [pscustomobject][ordered]@{
    schema_version=1
    seal_valid=$true
    failure_reason=$null
    vehicle_bytes=[long]$vehicleFile.Length
    vehicle_sha256=$vehicleSha256
    ground_bytes=[long]$groundFile.Length
    ground_sha256=$groundSha256
    streams_disposed_before_hash=$true
  }
}

function Write-DurableJsonlRecord {
  param(
    [Parameter(Mandatory = $true)]$Stream,
    [Parameter(Mandatory = $true)]$Value
  )
  $encoding = New-Object System.Text.UTF8Encoding($false)
  [byte[]]$bytes = $encoding.GetBytes(
      (($Value | ConvertTo-Json -Depth 20 -Compress) + "`n"))
  $Stream.Write($bytes, 0, $bytes.Length)
  $Stream.Flush($true)
}

function Test-RoleIdentityBinding {
  param(
    [Parameter(Mandatory = $true)][AllowEmptyCollection()]
    [object[]]$Inventory,
    [Parameter(Mandatory = $true)][string]$ExpectedVehiclePort,
    [Parameter(Mandatory = $true)][string]$ExpectedVehicleIdentity,
    [Parameter(Mandatory = $true)][string]$ExpectedGroundPort,
    [Parameter(Mandatory = $true)][string]$ExpectedGroundIdentity
  )
  $checks = New-Object 'System.Collections.Generic.List[object]'
  [bool]$rolesDistinct = (-not [string]::Equals($ExpectedVehiclePort,
      $ExpectedGroundPort, [StringComparison]::OrdinalIgnoreCase) -and
      -not [string]::Equals($ExpectedVehicleIdentity,
          $ExpectedGroundIdentity, [StringComparison]::OrdinalIgnoreCase))
  $checks.Add([pscustomobject]@{
    name='roles_distinct'; valid=$rolesDistinct
  })
  $selected = [ordered]@{}
  foreach ($role in @(
      @('vehicle', $ExpectedVehiclePort, $ExpectedVehicleIdentity),
      @('ground', $ExpectedGroundPort, $ExpectedGroundIdentity))) {
    [string]$roleName = [string]$role[0]
    [string]$port = [string]$role[1]
    [string]$identity = [string]$role[2]
    $portRows = @($Inventory | Where-Object {
        [string]::Equals([string]$_.port, $port,
            [StringComparison]::OrdinalIgnoreCase) })
    $exactRows = @($portRows | Where-Object {
        [string]::Equals([string]$_.pnp_device_id, $identity,
            [StringComparison]::OrdinalIgnoreCase) -and
        [string]::Equals([string]$_.status, 'OK',
            [StringComparison]::OrdinalIgnoreCase) -and
        [int]$_.problem_code -eq 0 })
    [bool]$roleValid = ($portRows.Count -eq 1 -and $exactRows.Count -eq 1)
    $checks.Add([pscustomobject]@{
      name=($roleName + '_port_identity_status_problem_exact')
      valid=$roleValid; expected_port=$port
      expected_pnp_device_id=$identity; port_match_count=$portRows.Count
      exact_match_count=$exactRows.Count
    })
    $selected[$roleName] = if ($exactRows.Count -eq 1) {
      $exactRows[0]
    } else { $null }
  }
  [bool]$noDuplicateInventoryIdentity = $true
  $identityRows = @($Inventory | Where-Object {
      [string]::Equals([string]$_.pnp_device_id, $ExpectedVehicleIdentity,
          [StringComparison]::OrdinalIgnoreCase) -or
      [string]::Equals([string]$_.pnp_device_id, $ExpectedGroundIdentity,
          [StringComparison]::OrdinalIgnoreCase) })
  if ($identityRows.Count -ne 2) { $noDuplicateInventoryIdentity = $false }
  $checks.Add([pscustomobject]@{
    name='no_duplicate_or_role_swapped_identity'
    valid=$noDuplicateInventoryIdentity
    matching_identity_row_count=$identityRows.Count
  })
  return [pscustomobject][ordered]@{
    valid = @($checks | Where-Object { -not $_.valid }).Count -eq 0
    checks = $checks.ToArray()
    selected = [pscustomobject]$selected
  }
}

function Test-BoundInventoryPollSequence {
  param(
    [Parameter(Mandatory = $true)][object[]]$Polls,
    [Parameter(Mandatory = $true)][string]$ExpectedVehiclePort,
    [Parameter(Mandatory = $true)][string]$ExpectedVehicleIdentity,
    [Parameter(Mandatory = $true)][string]$ExpectedGroundPort,
    [Parameter(Mandatory = $true)][string]$ExpectedGroundIdentity,
    [ValidateRange(1,1000)][int]$RequiredConsecutiveValidPolls = 1,
    [ValidateRange(1,60000)][int]$PollIntervalMs = 250
  )
  [int]$pollCount = 0
  [int]$emptyPollCount = 0
  [int]$consecutiveValidPolls = 0
  $lastBinding = $null
  [object[]]$lastInventory = @()
  foreach ($poll in @($Polls)) {
    ++$pollCount
    $lastInventory = @($poll.inventory)
    if ($lastInventory.Count -eq 0) { ++$emptyPollCount }
    $lastBinding = Test-RoleIdentityBinding -Inventory $lastInventory `
        -ExpectedVehiclePort $ExpectedVehiclePort `
        -ExpectedVehicleIdentity $ExpectedVehicleIdentity `
        -ExpectedGroundPort $ExpectedGroundPort `
        -ExpectedGroundIdentity $ExpectedGroundIdentity
    if ($lastBinding.valid) {
      ++$consecutiveValidPolls
      if ($consecutiveValidPolls -ge $RequiredConsecutiveValidPolls) {
        return [pscustomobject][ordered]@{
          found=$true;timed_out=$false;poll_count=$pollCount
          empty_poll_count=$emptyPollCount;inventory=$lastInventory
          binding=$lastBinding
          required_consecutive_valid_poll_count=
              $RequiredConsecutiveValidPolls
          consecutive_valid_poll_count=$consecutiveValidPolls
          modeled_continuous_stable_ms=
              (($consecutiveValidPolls - 1) * $PollIntervalMs)
          lifecycle_events=@('ports_reappeared','ports_opened')
          modeled_open_counts=[ordered]@{vehicle=1;ground=1}
          request_write_count=0
        }
      }
    } else {
      $consecutiveValidPolls = 0
    }
  }
  return [pscustomobject][ordered]@{
    found=$false;timed_out=$true;poll_count=$pollCount
    empty_poll_count=$emptyPollCount;inventory=$lastInventory
    binding=$lastBinding
    required_consecutive_valid_poll_count=$RequiredConsecutiveValidPolls
    consecutive_valid_poll_count=$consecutiveValidPolls
    modeled_continuous_stable_ms=
        ([Math]::Max(0,$consecutiveValidPolls - 1) * $PollIntervalMs)
    lifecycle_events=@()
    modeled_open_counts=[ordered]@{vehicle=0;ground=0}
    request_write_count=0
  }
}

function Get-PrePowerIdentityDecision {
  param([Parameter(Mandatory = $true)]$Binding)
  if (-not [bool]$Binding.valid) {
    return [pscustomobject][ordered]@{
      valid=$false;status='FAIL';exit_code=1
      message='pre-power COM/PNP identity binding was not exact; no request sent'
      wait_started=$false;power_off_wait_allowed=$false
      modeled_open_counts=[ordered]@{vehicle=0;ground=0}
      request_write_count=0
    }
  }
  return [pscustomobject][ordered]@{
    valid=$true;status='CONTINUE';exit_code=$null;message=$null
    wait_started=$false;power_off_wait_allowed=$true
    modeled_open_counts=[ordered]@{vehicle=0;ground=0}
    request_write_count=0
  }
}

function Get-SnapshotUInt64 {
  param($Snapshot, [Parameter(Mandatory = $true)][string]$Key)
  if ($null -eq $Snapshot -or $Snapshot.status -ne 'COMPLETE') {
    return [pscustomobject]@{ found=$false; value=$null }
  }
  foreach ($response in @($Snapshot.responses)) {
    $property = $response.fields.PSObject.Properties[$Key]
    if ($null -eq $property) { continue }
    [uint64]$value = 0
    if ([uint64]::TryParse([string]$property.Value, [ref]$value)) {
      return [pscustomobject]@{ found=$true; value=$value }
    }
  }
  return [pscustomobject]@{ found=$false; value=$null }
}

function Get-VehicleVcstat3UInt64 {
  param(
    $Snapshot,
    [Parameter(Mandatory = $true)][string]$Key
  )
  [string]$snapshotStatus = if ($null -ne $Snapshot -and
      $null -ne $Snapshot.PSObject.Properties['status']) {
    [string]$Snapshot.status
  } else { 'MISSING' }
  [int]$vcstat3Count = 0
  [bool]$fieldPresent = $false
  [bool]$uint64Valid = $false
  [string]$rawValue = $null
  [Nullable[uint64]]$value = $null
  if ($snapshotStatus -ceq 'COMPLETE') {
    foreach ($response in @($Snapshot.responses)) {
      if ($null -eq $response -or
          $null -eq $response.PSObject.Properties['tag'] -or
          [string]$response.tag -cne 'VCSTAT3') { continue }
      ++$vcstat3Count
      if ($null -eq $response.PSObject.Properties['fields'] -or
          $null -eq $response.fields) { continue }
      $property = $response.fields.PSObject.Properties[$Key]
      if ($null -eq $property) { continue }
      $fieldPresent = $true
      $rawValue = [string]$property.Value
      [uint64]$parsed = 0
      if ([uint64]::TryParse($rawValue, [ref]$parsed)) {
        $uint64Valid = $true
        $value = $parsed
      }
    }
  }
  [bool]$valid = ($snapshotStatus -ceq 'COMPLETE' -and
      $vcstat3Count -eq 1 -and $fieldPresent -and $uint64Valid)
  return [pscustomobject][ordered]@{
    key=$Key;snapshot_status=$snapshotStatus;vcstat3_count=$vcstat3Count
    field_present=$fieldPresent;uint64_valid=$uint64Valid
    raw_value=$rawValue;value=$value;valid=$valid
  }
}

function Get-VehicleVcstat3String {
  param(
    $Snapshot,
    [Parameter(Mandatory = $true)][string]$Key
  )
  [string]$snapshotStatus = if ($null -ne $Snapshot -and
      $null -ne $Snapshot.PSObject.Properties['status']) {
    [string]$Snapshot.status
  } else { 'MISSING' }
  [int]$vcstat3Count = 0
  [bool]$fieldPresent = $false
  [string]$rawValue = $null
  if ($snapshotStatus -ceq 'COMPLETE') {
    foreach ($response in @($Snapshot.responses)) {
      if ($null -eq $response -or
          $null -eq $response.PSObject.Properties['tag'] -or
          [string]$response.tag -cne 'VCSTAT3') { continue }
      ++$vcstat3Count
      if ($null -eq $response.PSObject.Properties['fields'] -or
          $null -eq $response.fields) { continue }
      $property = $response.fields.PSObject.Properties[$Key]
      if ($null -eq $property) { continue }
      $fieldPresent = $true
      $rawValue = [string]$property.Value
    }
  }
  [bool]$valid = ($snapshotStatus -ceq 'COMPLETE' -and
      $vcstat3Count -eq 1 -and $fieldPresent)
  return [pscustomobject][ordered]@{
    key=$Key;snapshot_status=$snapshotStatus;vcstat3_count=$vcstat3Count
    field_present=$fieldPresent;raw_value=$rawValue;value=$rawValue;valid=$valid
  }
}

function Get-VehicleVcstat3Delta {
  param(
    $Baseline,
    $Post,
    [Parameter(Mandatory = $true)][string]$Key
  )
  $before = Get-VehicleVcstat3UInt64 -Snapshot $Baseline -Key $Key
  $after = Get-VehicleVcstat3UInt64 -Snapshot $Post -Key $Key
  [bool]$found = ($before.valid -and $after.valid)
  [bool]$monotonic = ($found -and
      [uint64]$after.value -ge [uint64]$before.value)
  return [pscustomobject][ordered]@{
    key=$Key;found=$found;monotonic=$monotonic
    before=$before.value;after=$after.value
    delta=if ($monotonic) {
      [uint64]$after.value - [uint64]$before.value
    } else { $null }
  }
}

function Test-VehicleHeartbeatGrantDiagnosticContract {
  param($BaselineVehicle, $M0Vehicle, $M1Vehicle)
  $checks = New-Object 'System.Collections.Generic.List[object]'
  $phaseSnapshots = [ordered]@{
    baseline=$BaselineVehicle;m0=$M0Vehicle;m1=$M1Vehicle
  }
  $snapshotEvidence = [ordered]@{}
  foreach ($phaseName in @('baseline','m0','m1')) {
    $phaseSnapshot = $phaseSnapshots[$phaseName]
    $phaseEvidence = [ordered]@{}
    foreach ($key in @('hgd','hdm')) {
      $reading = Get-VehicleVcstat3UInt64 -Snapshot $phaseSnapshot -Key $key
      $phaseEvidence[$key] = $reading
      $checks.Add([pscustomobject][ordered]@{
        name=('vehicle_{0}_vcstat3_{1}_uint64' -f $phaseName,$key)
        phase=$phaseName;key=$key;rule='exact_VCSTAT3_uint64'
        actual=$reading.value;valid=[bool]$reading.valid
      })
    }
    $snapshotEvidence[$phaseName] = [pscustomobject]$phaseEvidence
  }

  $counterEvidence = [ordered]@{}
  foreach ($key in @('hgd','hdm')) {
    $baselineReading = $snapshotEvidence.baseline.$key
    $m0Reading = $snapshotEvidence.m0.$key
    $m1Reading = $snapshotEvidence.m1.$key
    [bool]$allValuesValid = ($baselineReading.valid -and
        $m0Reading.valid -and $m1Reading.valid)
    [bool]$baselineToM0Monotonic = ($allValuesValid -and
        [uint64]$m0Reading.value -ge [uint64]$baselineReading.value)
    [bool]$m0ToM1Monotonic = ($allValuesValid -and
        [uint64]$m1Reading.value -ge [uint64]$m0Reading.value)
    [bool]$monotonicNonDecreasing = ($baselineToM0Monotonic -and
        $m0ToM1Monotonic)
    $baselineToM0Delta = if ($baselineToM0Monotonic) {
      [uint64]$m0Reading.value - [uint64]$baselineReading.value
    } else { $null }
    $m0ToM1Delta = if ($m0ToM1Monotonic) {
      [uint64]$m1Reading.value - [uint64]$m0Reading.value
    } else { $null }
    $baselineToM1Delta = if ($monotonicNonDecreasing) {
      [uint64]$m1Reading.value - [uint64]$baselineReading.value
    } else { $null }
    $checks.Add([pscustomobject][ordered]@{
      name=('vehicle_{0}_monotonic_non_decreasing' -f $key)
      key=$key;rule='baseline_le_m0_le_m1'
      valid=$monotonicNonDecreasing
    })
    $counterEvidence[$key] = [pscustomobject][ordered]@{
      key=$key;baseline=$baselineReading.value;m0=$m0Reading.value
      m1=$m1Reading.value;baseline_to_m0=$baselineToM0Delta
      m0_to_m1=$m0ToM1Delta;baseline_to_m1=$baselineToM1Delta
      monotonic_non_decreasing=$monotonicNonDecreasing
      minimum_delta_required=$false
    }
  }
  [bool]$hdmDeltaZero = ($counterEvidence.hdm.monotonic_non_decreasing -and
      [uint64]$counterEvidence.hdm.baseline_to_m1 -eq [uint64]0)
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_hdm_delta_zero';key='hdm';rule='baseline_to_m1_delta_zero'
    expected=[uint64]0;actual=$counterEvidence.hdm.baseline_to_m1
    valid=$hdmDeltaZero
  })
  $failed = @($checks | Where-Object {-not $_.valid})
  return [pscustomobject][ordered]@{
    schema_version=1
    contract='Vehicle VCSTAT3 hgd/hdm baseline-M0-M1 auxiliary diagnostics'
    valid=($failed.Count -eq 0);failed_count=$failed.Count
    first_failed=if($failed.Count -gt 0){$failed[0].name}else{$null}
    snapshots=[pscustomobject]$snapshotEvidence
    counters=[pscustomobject]$counterEvidence
    hdm_delta_zero=$hdmDeltaZero
    hgd_minimum_delta_required=$false
    checks=$checks.ToArray()
  }
}

function Get-SnapshotString {
  param($Snapshot, [Parameter(Mandatory = $true)][string]$Key)
  if ($null -eq $Snapshot -or $Snapshot.status -ne 'COMPLETE') {
    return [pscustomobject]@{ found=$false; value=$null }
  }
  foreach ($response in @($Snapshot.responses)) {
    $property = $response.fields.PSObject.Properties[$Key]
    if ($null -ne $property) {
      return [pscustomobject]@{ found=$true; value=[string]$property.Value }
    }
  }
  return [pscustomobject]@{ found=$false; value=$null }
}

function Get-SnapshotDelta {
  param($Baseline, $Post, [Parameter(Mandatory = $true)][string]$Key)
  $before = Get-SnapshotUInt64 -Snapshot $Baseline -Key $Key
  $after = Get-SnapshotUInt64 -Snapshot $Post -Key $Key
  [bool]$monotonic = ($before.found -and $after.found -and
      [uint64]$after.value -ge [uint64]$before.value)
  return [pscustomobject][ordered]@{
    key=$Key; found=($before.found -and $after.found)
    monotonic=$monotonic; before=$before.value; after=$after.value
    delta=if ($monotonic) {
      [uint64]$after.value - [uint64]$before.value
    } else { $null }
  }
}

function Get-NextQueryId {
  param([Parameter(Mandatory = $true)][uint32]$Current)
  if ($Current -eq 0) { throw 'query id zero is invalid' }
  if ($Current -eq [uint32]::MaxValue) { return [uint32]1 }
  return [uint32]($Current + 1)
}

function Test-GroundOrderedDiscardContinuity {
  param(
    [Parameter(Mandatory = $true)]$BeforeGroundSnapshot,
    [Parameter(Mandatory = $true)]$AfterGroundSnapshot,
    [string]$NamePrefix = 'ground_ordered_discard'
  )
  $checks = New-Object 'System.Collections.Generic.List[object]'
  $beforeBoot = Get-SnapshotUInt64 -Snapshot $BeforeGroundSnapshot -Key 'boot'
  $afterBoot = Get-SnapshotUInt64 -Snapshot $AfterGroundSnapshot -Key 'boot'
  [bool]$sameBoot = ($beforeBoot.found -and $afterBoot.found -and
      [uint64]$beforeBoot.value -ne 0 -and
      [uint64]$beforeBoot.value -eq [uint64]$afterBoot.value)
  $checks.Add([pscustomobject][ordered]@{
    name=($NamePrefix + '_same_boot');key='boot';rule='same_boot'
    before=$beforeBoot.value;after=$afterBoot.value;valid=$sameBoot
  })
  foreach ($key in @('obdf','obdb')) {
    $delta = Get-SnapshotDelta -Baseline $BeforeGroundSnapshot `
        -Post $AfterGroundSnapshot -Key $key
    [bool]$valid = ($delta.found -and $delta.monotonic -and
        [uint64]$delta.delta -eq 0)
    $checks.Add([pscustomobject][ordered]@{
      name=($NamePrefix + '_' + $key + '_delta_zero')
      key=$key;rule='delta_zero';before=$delta.before;after=$delta.after
      delta=$delta.delta;valid=$valid
    })
  }
  return [pscustomobject][ordered]@{
    valid=(@($checks | Where-Object {-not $_.valid}).Count -eq 0)
    same_boot=$sameBoot
    checks=$checks.ToArray()
  }
}

function Test-BaselineSetup {
  param(
    $GroundSnapshot,
    $VehicleSnapshot,
    [AllowNull()]$PreviousGroundSnapshot = $null,
    [AllowNull()]$PreviousVehicleSnapshot = $null
  )
  $checks = New-Object 'System.Collections.Generic.List[object]'
  foreach ($spec in @(
      @('ground_ready', $GroundSnapshot, 'ready', [uint64]1),
      @('ground_fail', $GroundSnapshot, 'fail', [uint64]0),
      @('ground_runtime_stop', $GroundSnapshot, 'rse', [uint64]0),
      @('vehicle_ready', $VehicleSnapshot, 'r', [uint64]1),
      @('vehicle_fail', $VehicleSnapshot, 'f', [uint64]0),
      @('ground_proxy_state_idle', $GroundSnapshot, 'pst', [uint64]0),
      @('ground_proxy_mode_native', $GroundSnapshot, 'pmode', [uint64]1),
      @('ground_proxy_active_idle', $GroundSnapshot, 'pact', [uint64]0),
      @('ground_proxy_index_idle', $GroundSnapshot, 'pidx', [uint64]0),
      @('ground_proxy_count_idle', $GroundSnapshot, 'pcnt', [uint64]0),
      @('ground_proxy_admission_idle', $GroundSnapshot, 'padm', [uint64]0),
      @('ground_proxy_dequeue_idle', $GroundSnapshot, 'pdeq', [uint64]0),
      @('ground_proxy_recovery_inactive', $GroundSnapshot, 'pract', [uint64]0),
      @('ground_proxy_recovery_latch_invalid', $GroundSnapshot, 'prlv', [uint64]0),
      @('ground_proxy_recovery_latch_reason_none', $GroundSnapshot, 'prlr', [uint64]0),
      @('ground_proxy_recovery_latch_expected_zero', $GroundSnapshot, 'prlex', [uint64]0),
      @('ground_proxy_recovery_latch_received_sentinel', $GroundSnapshot, 'prlrx', [uint64]65535),
      @('ground_proxy_recovery_latch_count_zero', $GroundSnapshot, 'prlcnt', [uint64]0),
      @('ground_proxy_recovery_latch_sequence_zero', $GroundSnapshot, 'prlseq', [uint64]0),
      @('ground_proxy_recovery_latch_time_zero', $GroundSnapshot, 'prlms', [uint64]0),
      @('ground_radio_parser_buffer_empty', $GroundSnapshot, 'rfpbuf', [uint64]0),
      @('ground_radio_demux_buffer_empty', $GroundSnapshot, 'rfdmbuf', [uint64]0),
      @('ground_radio_demux_escape_mode_enabled', $GroundSnapshot, 'rfdmesc', [uint64]1))) {
    $field = Get-SnapshotUInt64 -Snapshot $spec[1] -Key ([string]$spec[2])
    $checks.Add([pscustomobject][ordered]@{
      name=[string]$spec[0]; key=[string]$spec[2]
      expected=[uint64]$spec[3]; actual=$field.value
      valid=($field.found -and [uint64]$field.value -eq [uint64]$spec[3])
    })
  }
  foreach ($bootSpec in @(
      @('ground_boot_nonzero', $GroundSnapshot),
      @('vehicle_boot_nonzero', $VehicleSnapshot))) {
    $boot = Get-SnapshotUInt64 -Snapshot $bootSpec[1] -Key 'boot'
    $checks.Add([pscustomobject]@{
      name=[string]$bootSpec[0]; key='boot'; expected='nonzero'
      actual=$boot.value; valid=($boot.found -and [uint64]$boot.value -ne 0)
    })
  }
  foreach ($positiveSpec in @(
      @('vehicle_d7_frames_positive', $VehicleSnapshot, 'd7f'),
      @('ground_rf_frames_positive', $GroundSnapshot, 'rfv'),
      @('ground_usb_accepted_positive', $GroundSnapshot, 'usbacc'))) {
    $field = Get-SnapshotUInt64 -Snapshot $positiveSpec[1] `
        -Key ([string]$positiveSpec[2])
    $checks.Add([pscustomobject]@{
      name=[string]$positiveSpec[0];key=[string]$positiveSpec[2]
      expected='positive';actual=$field.value
      valid=($field.found -and [uint64]$field.value -gt 0)
    })
  }
  $vehicleD722 = Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'd722'
  $groundRf22 = Get-SnapshotUInt64 -Snapshot $GroundSnapshot -Key 'rf22'
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_ground_param22_reconciled';key='d722==rf22'
    expected='equal';vehicle_d722=$vehicleD722.value
    ground_rf22=$groundRf22.value
    valid=($vehicleD722.found -and $groundRf22.found -and
      [uint64]$vehicleD722.value -eq [uint64]$groundRf22.value)
  })
  foreach ($zeroSpec in @(
      @('vehicle_generic_param_fifo_empty',$VehicleSnapshot,'pgq'),
      @('vehicle_generic_param_inactive',$VehicleSnapshot,'pga'),
      @('vehicle_pending_request_empty',$VehicleSnapshot,'prq'),
      @('vehicle_priority_target_lane_empty',$VehicleSnapshot,'ptq'),
      @('vehicle_egress_fail_zero',$VehicleSnapshot,'ef'),
      @('ground_download_queue_empty',$GroundSnapshot,'dlq'),
      @('ground_param22_ordered_backlog_empty',$GroundSnapshot,'obp22'))) {
    $field = Get-SnapshotUInt64 -Snapshot $zeroSpec[1] `
        -Key ([string]$zeroSpec[2])
    $checks.Add([pscustomobject][ordered]@{
      name=[string]$zeroSpec[0];key=[string]$zeroSpec[2]
      expected=[uint64]0;actual=$field.value
      valid=($field.found -and [uint64]$field.value -eq 0)
    })
  }
  foreach ($presenceSpec in @(
      @('vehicle_native_diagnostic_snf_present',$VehicleSnapshot,'snf'),
      @('vehicle_native_diagnostic_snbusy_present',$VehicleSnapshot,'snbusy'),
      @('vehicle_native_diagnostic_sncf_present',$VehicleSnapshot,'sncf'),
      @('vehicle_native_diagnostic_sncb_present',$VehicleSnapshot,'sncb'),
      @('vehicle_native_diagnostic_snff_present',$VehicleSnapshot,'snff'),
      @('vehicle_native_diagnostic_sncsf_present',$VehicleSnapshot,'sncsf'),
      @('vehicle_native_diagnostic_sncsb_present',$VehicleSnapshot,'sncsb'),
      @('vehicle_native_diagnostic_sncof_present',$VehicleSnapshot,'sncof'),
      @('vehicle_native_diagnostic_sncob_present',$VehicleSnapshot,'sncob'),
      @('vehicle_native_diagnostic_snfsf_present',$VehicleSnapshot,'snfsf'),
      @('vehicle_native_diagnostic_snfof_present',$VehicleSnapshot,'snfof'),
      @('vehicle_native_diagnostic_snffm_present',$VehicleSnapshot,'snffm'),
      @('vehicle_native_diagnostic_snflm_present',$VehicleSnapshot,'snflm'),
      @('vehicle_native_diagnostic_snfmg_present',$VehicleSnapshot,'snfmg'),
      @('vehicle_native_diagnostic_snftr_present',$VehicleSnapshot,'snftr'),
      @('vehicle_native_diagnostic_sncerr_present',$VehicleSnapshot,'sncerr'),
      @('vehicle_native_diagnostic_snul_present',$VehicleSnapshot,'snul'),
      @('vehicle_native_diagnostic_snur_present',$VehicleSnapshot,'snur'),
      @('vehicle_native_diagnostic_snuv_present',$VehicleSnapshot,'snuv'),
      @('vehicle_native_diagnostic_snusg_present',$VehicleSnapshot,'snusg'),
      @('vehicle_native_diagnostic_snusz_present',$VehicleSnapshot,'snusz'),
      @('vehicle_native_diagnostic_snup_present',$VehicleSnapshot,'snup'),
      @('vehicle_native_diagnostic_snusy_present',$VehicleSnapshot,'snusy'),
      @('vehicle_native_diagnostic_snucp_present',$VehicleSnapshot,'snucp'),
      @('vehicle_native_diagnostic_snusq_present',$VehicleSnapshot,'snusq'),
      @('vehicle_native_diagnostic_snumask_present',$VehicleSnapshot,'snumask'),
      @('vehicle_native_diagnostic_snui_present',$VehicleSnapshot,'snui'),
      @('vehicle_native_diagnostic_snuc_present',$VehicleSnapshot,'snuc'),
      @('vehicle_native_diagnostic_snut_present',$VehicleSnapshot,'snut'),
      @('vehicle_native_diagnostic_snums_present',$VehicleSnapshot,'snums'),
      @('vehicle_native_diagnostic_snq_present',$VehicleSnapshot,'snq'),
      @('vehicle_native_diagnostic_snseq_present',$VehicleSnapshot,'snseq'),
      @('vehicle_target_diagnostic_stqf_present',$VehicleSnapshot,'stqf'),
      @('vehicle_target_diagnostic_stdup_present',$VehicleSnapshot,'stdup'),
      @('vehicle_target_diagnostic_stsel_present',$VehicleSnapshot,'stsel'),
      @('vehicle_target_diagnostic_stchunk_present',$VehicleSnapshot,'stchunk'),
      @('vehicle_target_diagnostic_stdone_present',$VehicleSnapshot,'stdone'),
      @('vehicle_target_diagnostic_strej_present',$VehicleSnapshot,'strej'),
      @('ground_native_diagnostic_pnat_present',$GroundSnapshot,'pnat'),
      @('ground_native_diagnostic_ppois_present',$GroundSnapshot,'ppois'),
      @('ground_native_diagnostic_pnq_present',$GroundSnapshot,'pnq'),
      @('ground_native_diagnostic_ppre_present',$GroundSnapshot,'ppre'),
      @('ground_radio_diagnostic_mcr_present',$GroundSnapshot,'mcr'),
      @('ground_radio_diagnostic_rfpbs_present',$GroundSnapshot,'rfpbs'),
      @('ground_radio_diagnostic_rfpfa_present',$GroundSnapshot,'rfpfa'),
      @('ground_radio_diagnostic_rfpno_present',$GroundSnapshot,'rfpno'),
      @('ground_radio_diagnostic_rfpbl_present',$GroundSnapshot,'rfpbl'),
      @('ground_radio_diagnostic_rfpcr_present',$GroundSnapshot,'rfpcr'),
      @('ground_radio_diagnostic_rfpum_present',$GroundSnapshot,'rfpum'),
      @('ground_radio_diagnostic_rfpuf_present',$GroundSnapshot,'rfpuf'),
      @('ground_radio_diagnostic_rfprs_present',$GroundSnapshot,'rfprs'),
      @('ground_radio_diagnostic_rfpbuf_present',$GroundSnapshot,'rfpbuf'),
      @('ground_radio_diagnostic_rfdmbuf_present',$GroundSnapshot,'rfdmbuf'),
      @('ground_radio_diagnostic_rfdmesc_present',$GroundSnapshot,'rfdmesc'),
      @('ground_recovery_diagnostic_pvto_present',$GroundSnapshot,'pvto'),
      @('ground_recovery_diagnostic_pract_present',$GroundSnapshot,'pract'),
      @('ground_recovery_diagnostic_prold_present',$GroundSnapshot,'prold'),
      @('ground_recovery_diagnostic_prfut_present',$GroundSnapshot,'prfut'),
      @('ground_recovery_diagnostic_prgap_present',$GroundSnapshot,'prgap'),
      @('ground_recovery_diagnostic_prto_present',$GroundSnapshot,'prto'),
      @('ground_recovery_diagnostic_prq_present',$GroundSnapshot,'prq'),
      @('ground_recovery_diagnostic_prtx_present',$GroundSnapshot,'prtx'),
      @('ground_recovery_diagnostic_prv_present',$GroundSnapshot,'prv'),
      @('ground_recovery_diagnostic_prusb_present',$GroundSnapshot,'prusb'),
      @('ground_recovery_diagnostic_punm_present',$GroundSnapshot,'punm'),
      @('ground_recovery_diagnostic_prlv_present',$GroundSnapshot,'prlv'),
      @('ground_recovery_diagnostic_prlr_present',$GroundSnapshot,'prlr'),
      @('ground_recovery_diagnostic_prlex_present',$GroundSnapshot,'prlex'),
      @('ground_recovery_diagnostic_prlrx_present',$GroundSnapshot,'prlrx'),
      @('ground_recovery_diagnostic_prlcnt_present',$GroundSnapshot,'prlcnt'),
      @('ground_recovery_diagnostic_prlseq_present',$GroundSnapshot,'prlseq'),
      @('ground_recovery_diagnostic_prlms_present',$GroundSnapshot,'prlms'))) {
    $field = Get-SnapshotUInt64 -Snapshot $presenceSpec[1] `
        -Key ([string]$presenceSpec[2])
    $checks.Add([pscustomobject][ordered]@{
      name=[string]$presenceSpec[0];key=[string]$presenceSpec[2]
      expected='present';actual=$field.value;valid=$field.found
    })
  }
  foreach ($unexpectedKey in @('snul','snur','snuv','snusg','snusz','snup',
      'snusy','snucp','snusq','snumask','snui','snuc','snut','snums')) {
    $reading = Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key $unexpectedKey
    $checks.Add([pscustomobject][ordered]@{
      name=('vehicle_native_unexpected_baseline_zero_' + $unexpectedKey)
      key=$unexpectedKey;expected=[uint64]0;actual=$reading.value
      valid=($reading.found -and [uint64]$reading.value -eq 0)
    })
  }
  foreach ($cleanErrorKey in @(
      'snbusy','snseq','stdup','strej','sncof','sncob','snfof',
      'sncerr','snftr')) {
    $reading = Get-SnapshotUInt64 -Snapshot $VehicleSnapshot `
        -Key $cleanErrorKey
    $checks.Add([pscustomobject][ordered]@{
      name=('vehicle_native_clean_baseline_zero_' + $cleanErrorKey)
      key=$cleanErrorKey;expected=[uint64]0;actual=$reading.value
      valid=($reading.found -and [uint64]$reading.value -eq 0)
    })
  }
  foreach ($absoluteZeroSpec in @(
      @($VehicleSnapshot,'cc'),@($VehicleSnapshot,'rcr'),
      @($VehicleSnapshot,'riv'),@($VehicleSnapshot,'ocr'),
      @($VehicleSnapshot,'oiv'),@($VehicleSnapshot,'eiv'),
      @($VehicleSnapshot,'eov'),@($VehicleSnapshot,'out'),
      @($VehicleSnapshot,'d6cr'),@($VehicleSnapshot,'d7cr'),
      @($VehicleSnapshot,'pvbad'),@($VehicleSnapshot,'pvov'),
      @($VehicleSnapshot,'eo'),@($VehicleSnapshot,'sc'),
      @($VehicleSnapshot,'evo'),@($GroundSnapshot,'mcr'),
      @($GroundSnapshot,'rfpno'),@($GroundSnapshot,'rfpbl'),
      @($GroundSnapshot,'rfpcr'),@($GroundSnapshot,'rfpum'),
      @($GroundSnapshot,'rfpuf'))) {
    $reading = Get-SnapshotUInt64 -Snapshot $absoluteZeroSpec[0] `
        -Key ([string]$absoluteZeroSpec[1])
    $checks.Add([pscustomobject][ordered]@{
      name=('power_cycle_clean_baseline_zero_' + [string]$absoluteZeroSpec[1])
      key=[string]$absoluteZeroSpec[1];expected=[uint64]0
      actual=$reading.value
      valid=($reading.found -and [uint64]$reading.value -eq 0)
    })
  }
  foreach ($hexSpec in @(
      @('snuval','^[0-9A-Fa-f]{8}$','00000000'),
      @('snuid','^[0-9A-Fa-f]{32}$','00000000000000000000000000000000'))) {
    [string]$hexKey = [string]$hexSpec[0]
    [string]$hexPattern = [string]$hexSpec[1]
    [string]$hexExpected = [string]$hexSpec[2]
    $reading = Get-SnapshotString -Snapshot $VehicleSnapshot -Key $hexKey
    $checks.Add([pscustomobject][ordered]@{
      name=('vehicle_native_unexpected_baseline_' + $hexKey + '_zero')
      key=$hexKey;expected=$hexExpected;actual=$reading.value
      valid=($reading.found -and [string]$reading.value -match $hexPattern -and
        [string]$reading.value -ceq $hexExpected)
    })
  }
  # Keep the tail of the native schema explicitly downstream of the fixed-
  # width latch fields.  This proves that a truncated VCSTAT3 line cannot be
  # mistaken for a complete classifier merely because its prefix parsed.
  foreach ($nativeTailKey in @('snq','snseq')) {
    $reading = Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key $nativeTailKey
    $checks.Add([pscustomobject][ordered]@{
      name=('vehicle_native_schema_tail_present_' + $nativeTailKey)
      key=$nativeTailKey;expected='present_after_snuid'
      actual=$reading.value;valid=$reading.found
    })
  }
  foreach ($groundNativeTailKey in @('pnat','ppois','pnq','ppre')) {
    $reading = Get-SnapshotUInt64 -Snapshot $GroundSnapshot `
        -Key $groundNativeTailKey
    $checks.Add([pscustomobject][ordered]@{
      name=('ground_native_schema_tail_present_' + $groundNativeTailKey)
      key=$groundNativeTailKey;expected='present'
      actual=$reading.value;valid=$reading.found
    })
  }
  foreach ($counterKey in @('obdf','obdb')) {
    $field = Get-SnapshotUInt64 -Snapshot $GroundSnapshot -Key $counterKey
    $checks.Add([pscustomobject][ordered]@{
      name=('ground_ordered_discard_' + $counterKey + '_present')
      key=$counterKey;expected='present';actual=$field.value
      valid=$field.found
    })
  }
  [bool]$relatedDropErrorZero = $true
  foreach ($errorSpec in @(
      @($VehicleSnapshot,'pvbad'),@($VehicleSnapshot,'pvov'),
      @($VehicleSnapshot,'eo'),@($VehicleSnapshot,'evo'),
      @($GroundSnapshot,'obif'),@($GroundSnapshot,'obof'),
      @($GroundSnapshot,'psfail'),@($GroundSnapshot,'prej'))) {
    $field = Get-SnapshotUInt64 -Snapshot $errorSpec[0] `
        -Key ([string]$errorSpec[1])
    [bool]$zero = ($field.found -and [uint64]$field.value -eq 0)
    if (-not $zero) { $relatedDropErrorZero = $false }
    $checks.Add([pscustomobject][ordered]@{
      name=('related_drop_error_' + [string]$errorSpec[1] + '_zero')
      key=[string]$errorSpec[1];expected=[uint64]0;actual=$field.value
      valid=$zero
    })
  }
  $checks.Add([pscustomobject][ordered]@{
    name='related_drop_error_zero';key='related_drop_error_set'
    expected=$true;actual=$relatedDropErrorZero;valid=$relatedDropErrorZero
  })
  $discardContinuity = $null
  if ($null -ne $PreviousGroundSnapshot) {
    $discardContinuity = Test-GroundOrderedDiscardContinuity `
        -BeforeGroundSnapshot $PreviousGroundSnapshot `
        -AfterGroundSnapshot $GroundSnapshot `
        -NamePrefix 'backlog_drain_to_baseline'
    foreach ($check in @($discardContinuity.checks)) { $checks.Add($check) }
  }
  $vehicleBootContinuity = $null
  if ($null -ne $PreviousVehicleSnapshot) {
    $previousVehicleBoot = Get-SnapshotUInt64 `
        -Snapshot $PreviousVehicleSnapshot -Key 'boot'
    $currentVehicleBoot = Get-SnapshotUInt64 -Snapshot $VehicleSnapshot `
        -Key 'boot'
    [bool]$vehicleSameBoot = ($previousVehicleBoot.found -and
        $currentVehicleBoot.found -and
        [uint64]$previousVehicleBoot.value -ne 0 -and
        [uint64]$previousVehicleBoot.value -eq
          [uint64]$currentVehicleBoot.value)
    $vehicleBootCheck = [pscustomobject][ordered]@{
      name='baseline_pair_vehicle_same_boot';key='boot';rule='same_boot'
      before=$previousVehicleBoot.value;after=$currentVehicleBoot.value
      valid=$vehicleSameBoot
    }
    $checks.Add($vehicleBootCheck)
    $vehicleBootContinuity = [pscustomobject][ordered]@{
      valid=$vehicleSameBoot;same_boot=$vehicleSameBoot
      check=$vehicleBootCheck
    }
    foreach ($counterSpec in @(
        @('baseline_pair_vehicle_d722_monotonic',
          $PreviousVehicleSnapshot,$VehicleSnapshot,'d722'),
        @('baseline_pair_ground_rf22_monotonic',
          $PreviousGroundSnapshot,$GroundSnapshot,'rf22'))) {
      if ($null -eq $counterSpec[1]) { continue }
      $delta = Get-SnapshotDelta -Baseline $counterSpec[1] `
          -Post $counterSpec[2] -Key ([string]$counterSpec[3])
      $checks.Add([pscustomobject][ordered]@{
        name=[string]$counterSpec[0];key=[string]$counterSpec[3]
        rule='monotonic';before=$delta.before;after=$delta.after
        delta=$delta.delta;valid=($delta.found -and $delta.monotonic)
      })
    }
  }
  $knownStatRuntimeChecks = New-Object `
      'System.Collections.Generic.List[object]'
  $knownPreviousVehicleBoot = Get-SnapshotUInt64 `
      -Snapshot $PreviousVehicleSnapshot -Key 'boot'
  $knownCurrentVehicleBoot = Get-SnapshotUInt64 `
      -Snapshot $VehicleSnapshot -Key 'boot'
  [bool]$knownSameVehicleBoot = ($knownPreviousVehicleBoot.found -and
      $knownCurrentVehicleBoot.found -and
      [uint64]$knownPreviousVehicleBoot.value -ne 0 -and
      [uint64]$knownPreviousVehicleBoot.value -eq
        [uint64]$knownCurrentVehicleBoot.value)
  $knownStatRuntimeChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_vehicle_same_boot';key='boot'
    rule='same_boot';before=$knownPreviousVehicleBoot.value
    after=$knownCurrentVehicleBoot.value;valid=$knownSameVehicleBoot
  })
  $knownPvid = Get-SnapshotString -Snapshot $VehicleSnapshot -Key 'pvid'
  $knownStatRuntimeChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_exact_id';key='pvid';expected='STAT_RUNTIME'
    actual=$knownPvid.value
    valid=($knownPvid.found -and
      [string]$knownPvid.value -ceq 'STAT_RUNTIME')
  })
  foreach ($knownSpec in @(
      @('known_stat_runtime_index','pvidx',[uint64]65535),
      @('known_stat_runtime_count','pvcnt',[uint64]932),
      @('known_stat_runtime_type','pvtype',[uint64]6),
      @('known_stat_runtime_system','pvsys',[uint64]1),
      @('known_stat_runtime_component','pvcomp',[uint64]1),
      @('known_stat_runtime_single_lane_empty','pvs1',[uint64]0),
      @('known_stat_runtime_parser_buffer_empty','d7pb',[uint64]0),
      @('known_stat_runtime_bad_zero','pvbad',[uint64]0),
      @('known_stat_runtime_overflow_zero','pvov',[uint64]0),
      @('known_stat_runtime_previous_pgq_empty','pgq',[uint64]0))) {
    $knownSnapshot = if ([string]$knownSpec[0] -ceq
        'known_stat_runtime_previous_pgq_empty') {
      $PreviousVehicleSnapshot
    } else { $VehicleSnapshot }
    $knownField = Get-SnapshotUInt64 -Snapshot $knownSnapshot `
        -Key ([string]$knownSpec[1])
    $knownStatRuntimeChecks.Add([pscustomobject][ordered]@{
      name=[string]$knownSpec[0];key=[string]$knownSpec[1]
      expected=[uint64]$knownSpec[2];actual=$knownField.value
      valid=($knownField.found -and
        [uint64]$knownField.value -eq [uint64]$knownSpec[2])
    })
  }
  foreach ($knownQueueSpec in @(
      @('known_stat_runtime_current_pgq_one','pgq',[uint64]1),
      @('known_stat_runtime_pga_zero','pga',[uint64]0),
      @('known_stat_runtime_prq_zero','prq',[uint64]0),
      @('known_stat_runtime_ptq_zero','ptq',[uint64]0))) {
    $knownQueueField = Get-SnapshotUInt64 -Snapshot $VehicleSnapshot `
        -Key ([string]$knownQueueSpec[1])
    $knownStatRuntimeChecks.Add([pscustomobject][ordered]@{
      name=[string]$knownQueueSpec[0];key=[string]$knownQueueSpec[1]
      expected=[uint64]$knownQueueSpec[2];actual=$knownQueueField.value
      valid=($knownQueueField.found -and
        [uint64]$knownQueueField.value -eq [uint64]$knownQueueSpec[2])
    })
  }
  $knownD722Delta = Get-SnapshotDelta `
      -Baseline $PreviousVehicleSnapshot -Post $VehicleSnapshot -Key 'd722'
  $knownRf22Delta = Get-SnapshotDelta `
      -Baseline $PreviousGroundSnapshot -Post $GroundSnapshot -Key 'rf22'
  $knownPvokDelta = Get-SnapshotDelta `
      -Baseline $PreviousVehicleSnapshot -Post $VehicleSnapshot -Key 'pvok'
  foreach ($knownDeltaSpec in @(
      @('known_stat_runtime_d722_delta_one',$knownD722Delta),
      @('known_stat_runtime_rf22_delta_one',$knownRf22Delta),
      @('known_stat_runtime_pvok_delta_one',$knownPvokDelta))) {
    $knownDelta = $knownDeltaSpec[1]
    $knownStatRuntimeChecks.Add([pscustomobject][ordered]@{
      name=[string]$knownDeltaSpec[0];key=$knownDelta.key
      rule='delta_one';before=$knownDelta.before;after=$knownDelta.after
      delta=$knownDelta.delta
      valid=($knownDelta.found -and $knownDelta.monotonic -and
        [uint64]$knownDelta.delta -eq 1)
    })
  }
  $knownCurrentD722 = Get-SnapshotUInt64 -Snapshot $VehicleSnapshot `
      -Key 'd722'
  $knownCurrentRf22 = Get-SnapshotUInt64 -Snapshot $GroundSnapshot `
      -Key 'rf22'
  $knownStatRuntimeChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_d722_rf22_reconciled';key='d722==rf22'
    expected='equal';vehicle_d722=$knownCurrentD722.value
    ground_rf22=$knownCurrentRf22.value
    valid=($knownCurrentD722.found -and $knownCurrentRf22.found -and
      [uint64]$knownCurrentD722.value -eq [uint64]$knownCurrentRf22.value)
  })
  $knownPreviousVehicleMs = Get-SnapshotUInt64 `
      -Snapshot $PreviousVehicleSnapshot -Key 'ms'
  $knownCurrentVehicleMs = Get-SnapshotUInt64 `
      -Snapshot $VehicleSnapshot -Key 'ms'
  $knownPvms = Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvms'
  [bool]$knownPvmsFresh = ($knownPreviousVehicleMs.found -and
      $knownCurrentVehicleMs.found -and $knownPvms.found -and
      [uint64]$knownPvms.value -gt [uint64]$knownPreviousVehicleMs.value -and
      [uint64]$knownPvms.value -le [uint64]$knownCurrentVehicleMs.value)
  $knownStatRuntimeChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_pvms_fresh_between_snapshots';key='pvms'
    rule='previous_ms < pvms <= current_ms'
    previous_ms=$knownPreviousVehicleMs.value;actual=$knownPvms.value
    current_ms=$knownCurrentVehicleMs.value;valid=$knownPvmsFresh
  })
  [bool]$knownDiscardContinuous = ($null -ne $discardContinuity -and
      [bool]$discardContinuity.valid)
  $knownStatRuntimeChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_ground_discard_continuity'
    key='obdf/obdb';expected=$true;actual=$knownDiscardContinuous
    valid=$knownDiscardContinuous
  })
  $knownStatRuntimeRace = [pscustomobject][ordered]@{
    valid=(@($knownStatRuntimeChecks | Where-Object {-not $_.valid}).Count -eq 0)
    classification='exact_known_STAT_RUNTIME_baseline_race'
    pvid=$knownPvid.value;pvidx=(Get-SnapshotUInt64 `
      -Snapshot $VehicleSnapshot -Key 'pvidx').value
    pvcnt=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvcnt').value
    pvtype=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvtype').value
    pvsys=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvsys').value
    pvcomp=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvcomp').value
    pvms=$knownPvms.value;d722_delta=$knownD722Delta.delta
    rf22_delta=$knownRf22Delta.delta;pvok_delta=$knownPvokDelta.delta
    checks=$knownStatRuntimeChecks.ToArray()
  }

  # A sequential Vehicle-then-Ground baseline pair can contain the same
  # fully reconciled periodic STAT_RUNTIME transition while Vehicle has also
  # begun parsing the following D7 frame.  Preserve every exact observer and
  # counter predicate above, replace only the mutually exclusive d7pb==0
  # predicate with a bounded partial-frame proof, and require that the prior
  # parser was empty and its CRC-error counter did not move.  This shape never
  # makes a baseline valid; it can only authorize another complete pair.
  $knownStatRuntimeReconciledPartialChecks = New-Object `
      'System.Collections.Generic.List[object]'
  foreach ($knownCheck in $knownStatRuntimeChecks) {
    if ([string]$knownCheck.name -cne
        'known_stat_runtime_parser_buffer_empty') {
      $knownStatRuntimeReconciledPartialChecks.Add($knownCheck)
    }
  }
  $knownReconciledPartialPreviousD7pb = Get-SnapshotUInt64 `
      -Snapshot $PreviousVehicleSnapshot -Key 'd7pb'
  $knownStatRuntimeReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_reconciled_partial_previous_d7pb_empty'
        key='d7pb';expected=[uint64]0
        actual=$knownReconciledPartialPreviousD7pb.value
        valid=($knownReconciledPartialPreviousD7pb.found -and
          [uint64]$knownReconciledPartialPreviousD7pb.value -eq [uint64]0)
      })
  $knownReconciledPartialCurrentD7pb = Get-SnapshotUInt64 `
      -Snapshot $VehicleSnapshot -Key 'd7pb'
  $knownStatRuntimeReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_reconciled_partial_current_d7pb_bounded'
        key='d7pb';rule='1 <= d7pb <= 279'
        minimum=[uint64]1;maximum=[uint64]279
        actual=$knownReconciledPartialCurrentD7pb.value
        valid=($knownReconciledPartialCurrentD7pb.found -and
          [uint64]$knownReconciledPartialCurrentD7pb.value -ge [uint64]1 -and
          [uint64]$knownReconciledPartialCurrentD7pb.value -le [uint64]279)
      })
  $knownReconciledPartialD7crDelta = Get-SnapshotDelta `
      -Baseline $PreviousVehicleSnapshot -Post $VehicleSnapshot -Key 'd7cr'
  $knownStatRuntimeReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_reconciled_partial_d7cr_delta_zero'
        key='d7cr';expected_delta=[uint64]0
        before=$knownReconciledPartialD7crDelta.before
        after=$knownReconciledPartialD7crDelta.after
        delta=$knownReconciledPartialD7crDelta.delta
        valid=($knownReconciledPartialD7crDelta.found -and
          $knownReconciledPartialD7crDelta.monotonic -and
          [uint64]$knownReconciledPartialD7crDelta.delta -eq [uint64]0)
      })
  $knownStatRuntimeReconciledPartialRace = [pscustomobject][ordered]@{
    valid=(@($knownStatRuntimeReconciledPartialChecks | Where-Object {
          -not $_.valid}).Count -eq 0)
    classification=
      'exact_known_STAT_RUNTIME_reconciled_partial_D7_baseline_race'
    pvid=$knownPvid.value
    pvidx=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvidx').value
    pvcnt=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvcnt').value
    pvtype=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvtype').value
    pvsys=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvsys').value
    pvcomp=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvcomp').value
    pvms=$knownPvms.value;d7pb=$knownReconciledPartialCurrentD7pb.value
    d722_delta=$knownD722Delta.delta;rf22_delta=$knownRf22Delta.delta
    pvok_delta=$knownPvokDelta.delta
    d7cr_delta=$knownReconciledPartialD7crDelta.delta
    checks=$knownStatRuntimeReconciledPartialChecks.ToArray()
  }

  # R1 exposed the fully reconciled form while the one queued periodic
  # STAT_RUNTIME frame was still the active generic frame and the following
  # D7 frame had begun parsing.  Keep the established pga==0 predicate intact;
  # this separate exact shape replaces only d7pb==0 and pga==0, remains an
  # invalid baseline, and can only authorize another complete pair.
  $knownStatRuntimeActiveReconciledPartialChecks = New-Object `
      'System.Collections.Generic.List[object]'
  foreach ($knownCheck in $knownStatRuntimeChecks) {
    if ([string]$knownCheck.name -cne
        'known_stat_runtime_parser_buffer_empty' -and
        [string]$knownCheck.name -cne 'known_stat_runtime_pga_zero') {
      $knownStatRuntimeActiveReconciledPartialChecks.Add($knownCheck)
    }
  }
  $knownActivePreviousPga = Get-SnapshotUInt64 `
      -Snapshot $PreviousVehicleSnapshot -Key 'pga'
  $knownStatRuntimeActiveReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_active_reconciled_partial_previous_pga_empty'
        key='pga';expected=[uint64]0;actual=$knownActivePreviousPga.value
        valid=($knownActivePreviousPga.found -and
          [uint64]$knownActivePreviousPga.value -eq [uint64]0)
      })
  $knownActiveCurrentPga = Get-SnapshotUInt64 `
      -Snapshot $VehicleSnapshot -Key 'pga'
  $knownStatRuntimeActiveReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_active_reconciled_partial_pga_one'
        key='pga';expected=[uint64]1;actual=$knownActiveCurrentPga.value
        valid=($knownActiveCurrentPga.found -and
          [uint64]$knownActiveCurrentPga.value -eq [uint64]1)
      })
  $knownActivePreviousD7pb = Get-SnapshotUInt64 `
      -Snapshot $PreviousVehicleSnapshot -Key 'd7pb'
  $knownStatRuntimeActiveReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_active_reconciled_partial_previous_d7pb_empty'
        key='d7pb';expected=[uint64]0;actual=$knownActivePreviousD7pb.value
        valid=($knownActivePreviousD7pb.found -and
          [uint64]$knownActivePreviousD7pb.value -eq [uint64]0)
      })
  $knownActiveCurrentD7pb = Get-SnapshotUInt64 `
      -Snapshot $VehicleSnapshot -Key 'd7pb'
  $knownStatRuntimeActiveReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_active_reconciled_partial_current_d7pb_bounded'
        key='d7pb';rule='1 <= d7pb <= 279'
        minimum=[uint64]1;maximum=[uint64]279
        actual=$knownActiveCurrentD7pb.value
        valid=($knownActiveCurrentD7pb.found -and
          [uint64]$knownActiveCurrentD7pb.value -ge [uint64]1 -and
          [uint64]$knownActiveCurrentD7pb.value -le [uint64]279)
      })
  $knownActiveD7crDelta = Get-SnapshotDelta `
      -Baseline $PreviousVehicleSnapshot -Post $VehicleSnapshot -Key 'd7cr'
  $knownStatRuntimeActiveReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_active_reconciled_partial_d7cr_delta_zero'
        key='d7cr';expected_delta=[uint64]0
        before=$knownActiveD7crDelta.before;after=$knownActiveD7crDelta.after
        delta=$knownActiveD7crDelta.delta
        valid=($knownActiveD7crDelta.found -and
          $knownActiveD7crDelta.monotonic -and
          [uint64]$knownActiveD7crDelta.delta -eq [uint64]0)
      })
  $knownActivePreviousD722 = Get-SnapshotUInt64 `
      -Snapshot $PreviousVehicleSnapshot -Key 'd722'
  $knownActivePreviousRf22 = Get-SnapshotUInt64 `
      -Snapshot $PreviousGroundSnapshot -Key 'rf22'
  $knownStatRuntimeActiveReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_active_reconciled_partial_previous_reconciled'
        key='previous_d722==previous_rf22';expected='equal'
        vehicle_d722=$knownActivePreviousD722.value
        ground_rf22=$knownActivePreviousRf22.value
        valid=($knownActivePreviousD722.found -and
          $knownActivePreviousRf22.found -and
          [uint64]$knownActivePreviousD722.value -eq
            [uint64]$knownActivePreviousRf22.value)
      })
  $knownActivePreviousVehicleQ = Get-SnapshotUInt64 `
      -Snapshot $PreviousVehicleSnapshot -Key 'q'
  $knownActiveCurrentVehicleQ = Get-SnapshotUInt64 `
      -Snapshot $VehicleSnapshot -Key 'q'
  [bool]$knownActiveVehicleQNext = (
      $knownActivePreviousVehicleQ.found -and
      $knownActiveCurrentVehicleQ.found -and
      [uint64]$knownActivePreviousVehicleQ.value -le
        [uint64][uint32]::MaxValue -and
      [uint64]$knownActiveCurrentVehicleQ.value -le
        [uint64][uint32]::MaxValue -and
      (([uint64]$knownActivePreviousVehicleQ.value -lt
          [uint64][uint32]::MaxValue -and
        [uint64]$knownActiveCurrentVehicleQ.value -eq
          ([uint64]$knownActivePreviousVehicleQ.value + [uint64]1)) -or
       ([uint64]$knownActivePreviousVehicleQ.value -eq
          [uint64][uint32]::MaxValue -and
        [uint64]$knownActiveCurrentVehicleQ.value -eq [uint64]0)))
  $knownStatRuntimeActiveReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_active_reconciled_partial_vehicle_q_next'
        key='q';rule='next_uint32_with_wrap'
        before=$knownActivePreviousVehicleQ.value
        after=$knownActiveCurrentVehicleQ.value;valid=$knownActiveVehicleQNext
      })
  $knownActivePreviousGroundQ = Get-SnapshotUInt64 `
      -Snapshot $PreviousGroundSnapshot -Key 'q'
  $knownActiveCurrentGroundQ = Get-SnapshotUInt64 `
      -Snapshot $GroundSnapshot -Key 'q'
  [bool]$knownActiveGroundQNext = (
      $knownActivePreviousGroundQ.found -and
      $knownActiveCurrentGroundQ.found -and
      [uint64]$knownActivePreviousGroundQ.value -le
        [uint64][uint32]::MaxValue -and
      [uint64]$knownActiveCurrentGroundQ.value -le
        [uint64][uint32]::MaxValue -and
      (([uint64]$knownActivePreviousGroundQ.value -lt
          [uint64][uint32]::MaxValue -and
        [uint64]$knownActiveCurrentGroundQ.value -eq
          ([uint64]$knownActivePreviousGroundQ.value + [uint64]1)) -or
       ([uint64]$knownActivePreviousGroundQ.value -eq
          [uint64][uint32]::MaxValue -and
        [uint64]$knownActiveCurrentGroundQ.value -eq [uint64]0)))
  $knownStatRuntimeActiveReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_active_reconciled_partial_ground_q_next'
        key='q';rule='next_uint32_with_wrap'
        before=$knownActivePreviousGroundQ.value
        after=$knownActiveCurrentGroundQ.value;valid=$knownActiveGroundQNext
      })
  $knownActivePreviousVehicleMs = Get-SnapshotUInt64 `
      -Snapshot $PreviousVehicleSnapshot -Key 'ms'
  $knownActiveCurrentVehicleMs = Get-SnapshotUInt64 `
      -Snapshot $VehicleSnapshot -Key 'ms'
  $knownStatRuntimeActiveReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_active_reconciled_partial_vehicle_ms_increased'
        key='ms';rule='strictly_increased'
        before=$knownActivePreviousVehicleMs.value
        after=$knownActiveCurrentVehicleMs.value
        valid=($knownActivePreviousVehicleMs.found -and
          $knownActiveCurrentVehicleMs.found -and
          [uint64]$knownActiveCurrentVehicleMs.value -gt
            [uint64]$knownActivePreviousVehicleMs.value)
      })
  $knownActivePreviousGroundMs = Get-SnapshotUInt64 `
      -Snapshot $PreviousGroundSnapshot -Key 'ms'
  $knownActiveCurrentGroundMs = Get-SnapshotUInt64 `
      -Snapshot $GroundSnapshot -Key 'ms'
  $knownStatRuntimeActiveReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_active_reconciled_partial_ground_ms_increased'
        key='ms';rule='strictly_increased'
        before=$knownActivePreviousGroundMs.value
        after=$knownActiveCurrentGroundMs.value
        valid=($knownActivePreviousGroundMs.found -and
          $knownActiveCurrentGroundMs.found -and
          [uint64]$knownActiveCurrentGroundMs.value -gt
            [uint64]$knownActivePreviousGroundMs.value)
      })
  $knownStatRuntimeActiveReconciledPartialChecks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_active_reconciled_partial_related_drop_error_zero'
        key='related_drop_error_set';expected=$true
        actual=$relatedDropErrorZero;valid=$relatedDropErrorZero
      })
  $knownStatRuntimeActiveReconciledPartialRace = [pscustomobject][ordered]@{
    valid=(@($knownStatRuntimeActiveReconciledPartialChecks |
          Where-Object {-not $_.valid}).Count -eq 0)
    classification=
      'exact_known_STAT_RUNTIME_active_reconciled_partial_D7_baseline_race'
    pvid=$knownPvid.value
    pvidx=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvidx').value
    pvcnt=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvcnt').value
    pvtype=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvtype').value
    pvsys=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvsys').value
    pvcomp=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvcomp').value
    pvms=$knownPvms.value;pga=$knownActiveCurrentPga.value
    d7pb=$knownActiveCurrentD7pb.value;d722_delta=$knownD722Delta.delta
    rf22_delta=$knownRf22Delta.delta;pvok_delta=$knownPvokDelta.delta
    d7cr_delta=$knownActiveD7crDelta.delta
    vehicle_q_before=$knownActivePreviousVehicleQ.value
    vehicle_q_after=$knownActiveCurrentVehicleQ.value
    ground_q_before=$knownActivePreviousGroundQ.value
    ground_q_after=$knownActiveCurrentGroundQ.value
    checks=$knownStatRuntimeActiveReconciledPartialChecks.ToArray()
  }

  # A second exact observer shape exists while the newly parsed periodic
  # STAT_RUNTIME frame is still queued on Vehicle and has not yet reached the
  # Ground RF counter.  It remains an invalid baseline and may only authorize
  # another complete Vehicle/Ground pair inside the original shared deadline.
  $knownStatRuntimeVehicleAheadChecks = New-Object `
      'System.Collections.Generic.List[object]'
  $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_vehicle_ahead_vehicle_same_boot';key='boot'
    rule='same_boot';before=$knownPreviousVehicleBoot.value
    after=$knownCurrentVehicleBoot.value;valid=$knownSameVehicleBoot
  })
  $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_vehicle_ahead_exact_id';key='pvid'
    expected='STAT_RUNTIME';actual=$knownPvid.value
    valid=($knownPvid.found -and
      [string]$knownPvid.value -ceq 'STAT_RUNTIME')
  })
  foreach ($aheadSpec in @(
      @('known_stat_runtime_vehicle_ahead_index','pvidx',[uint64]65535),
      @('known_stat_runtime_vehicle_ahead_count','pvcnt',[uint64]932),
      @('known_stat_runtime_vehicle_ahead_type','pvtype',[uint64]6),
      @('known_stat_runtime_vehicle_ahead_system','pvsys',[uint64]1),
      @('known_stat_runtime_vehicle_ahead_component','pvcomp',[uint64]1),
      @('known_stat_runtime_vehicle_ahead_single_lane_empty','pvs1',[uint64]0),
      @('known_stat_runtime_vehicle_ahead_bad_zero','pvbad',[uint64]0),
      @('known_stat_runtime_vehicle_ahead_overflow_zero','pvov',[uint64]0))) {
    $aheadField = Get-SnapshotUInt64 -Snapshot $VehicleSnapshot `
        -Key ([string]$aheadSpec[1])
    $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
      name=[string]$aheadSpec[0];key=[string]$aheadSpec[1]
      expected=[uint64]$aheadSpec[2];actual=$aheadField.value
      valid=($aheadField.found -and
        [uint64]$aheadField.value -eq [uint64]$aheadSpec[2])
    })
  }
  foreach ($aheadPreviousSpec in @(
      @('known_stat_runtime_vehicle_ahead_previous_pgq_empty','pgq'),
      @('known_stat_runtime_vehicle_ahead_previous_d7pb_empty','d7pb'))) {
    $aheadPreviousField = Get-SnapshotUInt64 `
        -Snapshot $PreviousVehicleSnapshot `
        -Key ([string]$aheadPreviousSpec[1])
    $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
      name=[string]$aheadPreviousSpec[0];key=[string]$aheadPreviousSpec[1]
      expected=[uint64]0;actual=$aheadPreviousField.value
      valid=($aheadPreviousField.found -and
        [uint64]$aheadPreviousField.value -eq 0)
    })
  }
  foreach ($aheadQueueSpec in @(
      @('known_stat_runtime_vehicle_ahead_current_pgq_one','pgq',[uint64]1),
      @('known_stat_runtime_vehicle_ahead_pga_zero','pga',[uint64]0),
      @('known_stat_runtime_vehicle_ahead_prq_zero','prq',[uint64]0),
      @('known_stat_runtime_vehicle_ahead_ptq_zero','ptq',[uint64]0))) {
    $aheadQueueField = Get-SnapshotUInt64 -Snapshot $VehicleSnapshot `
        -Key ([string]$aheadQueueSpec[1])
    $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
      name=[string]$aheadQueueSpec[0];key=[string]$aheadQueueSpec[1]
      expected=[uint64]$aheadQueueSpec[2];actual=$aheadQueueField.value
      valid=($aheadQueueField.found -and
        [uint64]$aheadQueueField.value -eq [uint64]$aheadQueueSpec[2])
    })
  }
  $aheadCurrentD7pb = Get-SnapshotUInt64 -Snapshot $VehicleSnapshot `
      -Key 'd7pb'
  $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_vehicle_ahead_current_d7pb_bounded';key='d7pb'
    rule='1 <= d7pb <= 279';minimum=[uint64]1;maximum=[uint64]279
    actual=$aheadCurrentD7pb.value
    valid=($aheadCurrentD7pb.found -and
      [uint64]$aheadCurrentD7pb.value -ge [uint64]1 -and
      [uint64]$aheadCurrentD7pb.value -le [uint64]279)
  })
  $aheadD722Delta = Get-SnapshotDelta `
      -Baseline $PreviousVehicleSnapshot -Post $VehicleSnapshot -Key 'd722'
  $aheadRf22Delta = Get-SnapshotDelta `
      -Baseline $PreviousGroundSnapshot -Post $GroundSnapshot -Key 'rf22'
  $aheadPvokDelta = Get-SnapshotDelta `
      -Baseline $PreviousVehicleSnapshot -Post $VehicleSnapshot -Key 'pvok'
  foreach ($aheadDeltaSpec in @(
      @('known_stat_runtime_vehicle_ahead_d722_delta_one',
        $aheadD722Delta,[uint64]1),
      @('known_stat_runtime_vehicle_ahead_rf22_delta_zero',
        $aheadRf22Delta,[uint64]0),
      @('known_stat_runtime_vehicle_ahead_pvok_delta_one',
        $aheadPvokDelta,[uint64]1))) {
    $aheadDelta = $aheadDeltaSpec[1]
    $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
      name=[string]$aheadDeltaSpec[0];key=$aheadDelta.key
      expected_delta=[uint64]$aheadDeltaSpec[2]
      before=$aheadDelta.before;after=$aheadDelta.after;delta=$aheadDelta.delta
      valid=($aheadDelta.found -and $aheadDelta.monotonic -and
        [uint64]$aheadDelta.delta -eq [uint64]$aheadDeltaSpec[2])
    })
  }
  $aheadD7crDelta = Get-SnapshotDelta `
      -Baseline $PreviousVehicleSnapshot -Post $VehicleSnapshot -Key 'd7cr'
  $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_vehicle_ahead_d7cr_delta_zero';key='d7cr'
    expected_delta=[uint64]0;before=$aheadD7crDelta.before
    after=$aheadD7crDelta.after;delta=$aheadD7crDelta.delta
    valid=($aheadD7crDelta.found -and $aheadD7crDelta.monotonic -and
      [uint64]$aheadD7crDelta.delta -eq 0)
  })
  $aheadPreviousD722 = Get-SnapshotUInt64 `
      -Snapshot $PreviousVehicleSnapshot -Key 'd722'
  $aheadPreviousRf22 = Get-SnapshotUInt64 `
      -Snapshot $PreviousGroundSnapshot -Key 'rf22'
  $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_vehicle_ahead_previous_reconciled'
    key='previous_d722==previous_rf22';expected='equal'
    vehicle_d722=$aheadPreviousD722.value;ground_rf22=$aheadPreviousRf22.value
    valid=($aheadPreviousD722.found -and $aheadPreviousRf22.found -and
      [uint64]$aheadPreviousD722.value -eq [uint64]$aheadPreviousRf22.value)
  })
  [bool]$aheadCurrentExactlyOne = ($knownCurrentD722.found -and
      $knownCurrentRf22.found -and
      [uint64]$knownCurrentRf22.value -lt [uint64]::MaxValue -and
      [uint64]$knownCurrentD722.value -eq
        ([uint64]$knownCurrentRf22.value + [uint64]1))
  $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_vehicle_ahead_current_ahead_one'
    key='current_d722==current_rf22+1';expected='vehicle_ahead_one'
    vehicle_d722=$knownCurrentD722.value;ground_rf22=$knownCurrentRf22.value
    valid=$aheadCurrentExactlyOne
  })
  $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_vehicle_ahead_pvms_fresh_between_snapshots'
    key='pvms';rule='previous_ms < pvms <= current_ms'
    previous_ms=$knownPreviousVehicleMs.value;actual=$knownPvms.value
    current_ms=$knownCurrentVehicleMs.value;valid=$knownPvmsFresh
  })
  $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_vehicle_ahead_ground_discard_continuity'
    key='obdf/obdb';expected=$true;actual=$knownDiscardContinuous
    valid=$knownDiscardContinuous
  })
  $knownStatRuntimeVehicleAheadChecks.Add([pscustomobject][ordered]@{
    name='known_stat_runtime_vehicle_ahead_related_drop_error_zero'
    key='related_drop_error_set';expected=$true
    actual=$relatedDropErrorZero;valid=$relatedDropErrorZero
  })
  $knownStatRuntimeVehicleAheadRace = [pscustomobject][ordered]@{
    valid=(@($knownStatRuntimeVehicleAheadChecks | Where-Object {
          -not $_.valid}).Count -eq 0)
    classification='exact_known_STAT_RUNTIME_vehicle_ahead_baseline_race'
    pvid=$knownPvid.value
    pvidx=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvidx').value
    pvcnt=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvcnt').value
    pvtype=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvtype').value
    pvsys=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvsys').value
    pvcomp=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvcomp').value
    pvms=$knownPvms.value;d7pb=$aheadCurrentD7pb.value
    d722_delta=$aheadD722Delta.delta;rf22_delta=$aheadRf22Delta.delta
    pvok_delta=$aheadPvokDelta.delta;d7cr_delta=$aheadD7crDelta.delta
    checks=$knownStatRuntimeVehicleAheadChecks.ToArray()
  }

  # R3 captured the exact Vehicle-ahead STAT_RUNTIME transition before any
  # byte of the following D7 frame had arrived.  Preserve the established
  # 1..279 partial-D7 classifier and model this empty-parser instant as a
  # separate RETRY-only observer.  The prior queues, both diagnostic sequence
  # clocks, and both device clocks must prove one fresh complete pair.
  $knownStatRuntimeVehicleAheadEmptyD7Checks = New-Object `
      'System.Collections.Generic.List[object]'
  foreach ($knownCheck in $knownStatRuntimeVehicleAheadChecks) {
    if ([string]$knownCheck.name -cne
        'known_stat_runtime_vehicle_ahead_current_d7pb_bounded') {
      $knownStatRuntimeVehicleAheadEmptyD7Checks.Add($knownCheck)
    }
  }
  $knownEmptyCurrentD7pb = Get-SnapshotUInt64 `
      -Snapshot $VehicleSnapshot -Key 'd7pb'
  $knownStatRuntimeVehicleAheadEmptyD7Checks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_vehicle_ahead_empty_current_d7pb_zero'
        key='d7pb';expected=[uint64]0;actual=$knownEmptyCurrentD7pb.value
        valid=($knownEmptyCurrentD7pb.found -and
          [uint64]$knownEmptyCurrentD7pb.value -eq [uint64]0)
      })
  foreach ($knownEmptyPreviousSpec in @(
      @('known_stat_runtime_vehicle_ahead_empty_previous_pga_zero','pga'),
      @('known_stat_runtime_vehicle_ahead_empty_previous_prq_zero','prq'),
      @('known_stat_runtime_vehicle_ahead_empty_previous_ptq_zero','ptq'),
      @('known_stat_runtime_vehicle_ahead_empty_previous_pvs1_zero','pvs1'))) {
    $knownEmptyPreviousField = Get-SnapshotUInt64 `
        -Snapshot $PreviousVehicleSnapshot `
        -Key ([string]$knownEmptyPreviousSpec[1])
    $knownStatRuntimeVehicleAheadEmptyD7Checks.Add(
        [pscustomobject][ordered]@{
          name=[string]$knownEmptyPreviousSpec[0]
          key=[string]$knownEmptyPreviousSpec[1]
          expected=[uint64]0;actual=$knownEmptyPreviousField.value
          valid=($knownEmptyPreviousField.found -and
            [uint64]$knownEmptyPreviousField.value -eq [uint64]0)
        })
  }
  $knownEmptyPreviousVehicleQ = Get-SnapshotUInt64 `
      -Snapshot $PreviousVehicleSnapshot -Key 'q'
  $knownEmptyCurrentVehicleQ = Get-SnapshotUInt64 `
      -Snapshot $VehicleSnapshot -Key 'q'
  [bool]$knownEmptyVehicleQNext = (
      $knownEmptyPreviousVehicleQ.found -and
      $knownEmptyCurrentVehicleQ.found -and
      [uint64]$knownEmptyPreviousVehicleQ.value -le
        [uint64][uint32]::MaxValue -and
      [uint64]$knownEmptyCurrentVehicleQ.value -le
        [uint64][uint32]::MaxValue -and
      (([uint64]$knownEmptyPreviousVehicleQ.value -lt
          [uint64][uint32]::MaxValue -and
        [uint64]$knownEmptyCurrentVehicleQ.value -eq
          ([uint64]$knownEmptyPreviousVehicleQ.value + [uint64]1)) -or
       ([uint64]$knownEmptyPreviousVehicleQ.value -eq
          [uint64][uint32]::MaxValue -and
        [uint64]$knownEmptyCurrentVehicleQ.value -eq [uint64]0)))
  $knownStatRuntimeVehicleAheadEmptyD7Checks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_vehicle_ahead_empty_vehicle_q_next'
        key='q';rule='next_uint32_with_wrap'
        before=$knownEmptyPreviousVehicleQ.value
        after=$knownEmptyCurrentVehicleQ.value;valid=$knownEmptyVehicleQNext
      })
  $knownEmptyPreviousGroundQ = Get-SnapshotUInt64 `
      -Snapshot $PreviousGroundSnapshot -Key 'q'
  $knownEmptyCurrentGroundQ = Get-SnapshotUInt64 `
      -Snapshot $GroundSnapshot -Key 'q'
  [bool]$knownEmptyGroundQNext = (
      $knownEmptyPreviousGroundQ.found -and
      $knownEmptyCurrentGroundQ.found -and
      [uint64]$knownEmptyPreviousGroundQ.value -le
        [uint64][uint32]::MaxValue -and
      [uint64]$knownEmptyCurrentGroundQ.value -le
        [uint64][uint32]::MaxValue -and
      (([uint64]$knownEmptyPreviousGroundQ.value -lt
          [uint64][uint32]::MaxValue -and
        [uint64]$knownEmptyCurrentGroundQ.value -eq
          ([uint64]$knownEmptyPreviousGroundQ.value + [uint64]1)) -or
       ([uint64]$knownEmptyPreviousGroundQ.value -eq
          [uint64][uint32]::MaxValue -and
        [uint64]$knownEmptyCurrentGroundQ.value -eq [uint64]0)))
  $knownStatRuntimeVehicleAheadEmptyD7Checks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_vehicle_ahead_empty_ground_q_next'
        key='q';rule='next_uint32_with_wrap'
        before=$knownEmptyPreviousGroundQ.value
        after=$knownEmptyCurrentGroundQ.value;valid=$knownEmptyGroundQNext
      })
  $knownEmptyPreviousVehicleMs = Get-SnapshotUInt64 `
      -Snapshot $PreviousVehicleSnapshot -Key 'ms'
  $knownEmptyCurrentVehicleMs = Get-SnapshotUInt64 `
      -Snapshot $VehicleSnapshot -Key 'ms'
  $knownStatRuntimeVehicleAheadEmptyD7Checks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_vehicle_ahead_empty_vehicle_ms_increased'
        key='ms';rule='strictly_increased'
        before=$knownEmptyPreviousVehicleMs.value
        after=$knownEmptyCurrentVehicleMs.value
        valid=($knownEmptyPreviousVehicleMs.found -and
          $knownEmptyCurrentVehicleMs.found -and
          [uint64]$knownEmptyCurrentVehicleMs.value -gt
            [uint64]$knownEmptyPreviousVehicleMs.value)
      })
  $knownEmptyPreviousGroundMs = Get-SnapshotUInt64 `
      -Snapshot $PreviousGroundSnapshot -Key 'ms'
  $knownEmptyCurrentGroundMs = Get-SnapshotUInt64 `
      -Snapshot $GroundSnapshot -Key 'ms'
  $knownStatRuntimeVehicleAheadEmptyD7Checks.Add(
      [pscustomobject][ordered]@{
        name='known_stat_runtime_vehicle_ahead_empty_ground_ms_increased'
        key='ms';rule='strictly_increased'
        before=$knownEmptyPreviousGroundMs.value
        after=$knownEmptyCurrentGroundMs.value
        valid=($knownEmptyPreviousGroundMs.found -and
          $knownEmptyCurrentGroundMs.found -and
          [uint64]$knownEmptyCurrentGroundMs.value -gt
            [uint64]$knownEmptyPreviousGroundMs.value)
      })
  $knownStatRuntimeVehicleAheadEmptyD7Race = [pscustomobject][ordered]@{
    valid=(@($knownStatRuntimeVehicleAheadEmptyD7Checks |
          Where-Object {-not $_.valid}).Count -eq 0)
    classification=
      'exact_known_STAT_RUNTIME_vehicle_ahead_empty_D7_baseline_race'
    pvid=$knownPvid.value
    pvidx=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvidx').value
    pvcnt=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvcnt').value
    pvtype=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvtype').value
    pvsys=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvsys').value
    pvcomp=(Get-SnapshotUInt64 -Snapshot $VehicleSnapshot -Key 'pvcomp').value
    pvms=$knownPvms.value;d7pb=$knownEmptyCurrentD7pb.value
    d722_delta=$aheadD722Delta.delta;rf22_delta=$aheadRf22Delta.delta
    pvok_delta=$aheadPvokDelta.delta;d7cr_delta=$aheadD7crDelta.delta
    vehicle_q_before=$knownEmptyPreviousVehicleQ.value
    vehicle_q_after=$knownEmptyCurrentVehicleQ.value
    ground_q_before=$knownEmptyPreviousGroundQ.value
    ground_q_after=$knownEmptyCurrentGroundQ.value
    checks=$knownStatRuntimeVehicleAheadEmptyD7Checks.ToArray()
  }
  return [pscustomobject][ordered]@{
    valid=@($checks | Where-Object {-not $_.valid}).Count -eq 0
    ground_ordered_discard_continuity=$discardContinuity
    vehicle_boot_continuity=$vehicleBootContinuity
    known_stat_runtime_race=$knownStatRuntimeRace
    known_stat_runtime_reconciled_partial_d7_race=
      $knownStatRuntimeReconciledPartialRace
    known_stat_runtime_active_reconciled_partial_d7_race=
      $knownStatRuntimeActiveReconciledPartialRace
    known_stat_runtime_vehicle_ahead_race=$knownStatRuntimeVehicleAheadRace
    known_stat_runtime_vehicle_ahead_empty_d7_race=
      $knownStatRuntimeVehicleAheadEmptyD7Race
    checks=$checks.ToArray()
  }
}

function Get-BaselineAttemptDisposition {
  param(
    [Parameter(Mandatory = $true)]$BaselineSetup,
    [Parameter(Mandatory = $true)][int]$AttemptNumber,
    [int]$MaxAttempts = 3,
    [Parameter(Mandatory = $true)][bool]$RetryBudgetAvailable
  )
  [object[]]$failedChecks = [object[]]@(
      $BaselineSetup.checks | Where-Object {-not $_.valid})
  [object[]]$failedCheckNames = [object[]]@(
      $failedChecks | ForEach-Object {[string]$_.name})
  [bool]$singleReconciliationFailure = ($failedChecks.Count -eq 1 -and
      [string]$failedChecks[0].name -ceq
        'vehicle_ground_param22_reconciled')
  [bool]$singleKnownStatRuntimeFailure = ($failedChecks.Count -eq 1 -and
      [string]$failedChecks[0].name -ceq
        'vehicle_generic_param_fifo_empty')
  # The periodic STAT_RUNTIME observer can be captured one bounded Vehicle
  # slice before its matching Ground RF observation.  Match the complete set
  # of baseline failures by name so array ordering cannot change the result.
  [bool]$exactVehicleAheadFailureSet = ($failedCheckNames.Count -eq 2 -and
      $failedCheckNames -ccontains 'vehicle_ground_param22_reconciled' -and
      $failedCheckNames -ccontains 'vehicle_generic_param_fifo_empty')
  [bool]$exactActiveReconciledPartialFailureSet = (
      $failedCheckNames.Count -eq 2 -and
      $failedCheckNames -ccontains 'vehicle_generic_param_fifo_empty' -and
      $failedCheckNames -ccontains 'vehicle_generic_param_inactive')
  $knownStatRuntimeRace = $BaselineSetup.PSObject.Properties[
      'known_stat_runtime_race']
  [bool]$knownStatRuntimeObserverExact = ($null -ne $knownStatRuntimeRace -and
      $null -ne $knownStatRuntimeRace.Value -and
      [bool]$knownStatRuntimeRace.Value.valid)
  $knownStatRuntimeReconciledPartialRace =
      $BaselineSetup.PSObject.Properties[
        'known_stat_runtime_reconciled_partial_d7_race']
  [bool]$knownStatRuntimeReconciledPartialObserverExact = (
      $null -ne $knownStatRuntimeReconciledPartialRace -and
      $null -ne $knownStatRuntimeReconciledPartialRace.Value -and
      [bool]$knownStatRuntimeReconciledPartialRace.Value.valid)
  $knownStatRuntimeActiveReconciledPartialRace =
      $BaselineSetup.PSObject.Properties[
        'known_stat_runtime_active_reconciled_partial_d7_race']
  [bool]$knownStatRuntimeActiveReconciledPartialObserverExact = (
      $null -ne $knownStatRuntimeActiveReconciledPartialRace -and
      $null -ne $knownStatRuntimeActiveReconciledPartialRace.Value -and
      [bool]$knownStatRuntimeActiveReconciledPartialRace.Value.valid)
  $knownStatRuntimeVehicleAheadRace = $BaselineSetup.PSObject.Properties[
      'known_stat_runtime_vehicle_ahead_race']
  [bool]$knownStatRuntimeVehicleAheadObserverExact = (
      $null -ne $knownStatRuntimeVehicleAheadRace -and
      $null -ne $knownStatRuntimeVehicleAheadRace.Value -and
      [bool]$knownStatRuntimeVehicleAheadRace.Value.valid)
  $knownStatRuntimeVehicleAheadEmptyD7Race =
      $BaselineSetup.PSObject.Properties[
        'known_stat_runtime_vehicle_ahead_empty_d7_race']
  [bool]$knownStatRuntimeVehicleAheadEmptyD7ObserverExact = (
      $null -ne $knownStatRuntimeVehicleAheadEmptyD7Race -and
      $null -ne $knownStatRuntimeVehicleAheadEmptyD7Race.Value -and
      [bool]$knownStatRuntimeVehicleAheadEmptyD7Race.Value.valid)
  [bool]$groundAheadOne = $false
  if ($singleReconciliationFailure) {
    $mismatch = $failedChecks[0]
    if ($null -ne $mismatch.vehicle_d722 -and
        $null -ne $mismatch.ground_rf22 -and
        [uint64]$mismatch.vehicle_d722 -lt [uint64]::MaxValue) {
      $groundAheadOne = ([uint64]$mismatch.ground_rf22 -eq
          ([uint64]$mismatch.vehicle_d722 + [uint64]1))
    }
  }
  [bool]$attemptAvailable = ($AttemptNumber -lt $MaxAttempts)
  [bool]$knownStatRuntimeRetryCandidate = ($singleKnownStatRuntimeFailure -and
      $knownStatRuntimeObserverExact)
  [bool]$knownStatRuntimeReconciledPartialRetryCandidate = (
      $singleKnownStatRuntimeFailure -and
      $knownStatRuntimeReconciledPartialObserverExact)
  [bool]$knownStatRuntimeActiveReconciledPartialRetryCandidate = (
      $exactActiveReconciledPartialFailureSet -and
      $knownStatRuntimeActiveReconciledPartialObserverExact)
  [bool]$knownStatRuntimeVehicleAheadRetryCandidate = (
      $exactVehicleAheadFailureSet -and
      $knownStatRuntimeVehicleAheadObserverExact)
  [bool]$knownStatRuntimeVehicleAheadEmptyD7RetryCandidate = (
      $exactVehicleAheadFailureSet -and
      $knownStatRuntimeVehicleAheadEmptyD7ObserverExact)
  [bool]$param22RetryCandidate = ($singleReconciliationFailure -and
      $groundAheadOne)
  [bool]$retryEligible = (-not [bool]$BaselineSetup.valid -and
      ($param22RetryCandidate -or $knownStatRuntimeRetryCandidate -or
        $knownStatRuntimeReconciledPartialRetryCandidate -or
        $knownStatRuntimeActiveReconciledPartialRetryCandidate -or
        $knownStatRuntimeVehicleAheadEmptyD7RetryCandidate -or
        $knownStatRuntimeVehicleAheadRetryCandidate) -and
      $attemptAvailable -and $RetryBudgetAvailable)
  [string]$action = 'REJECT'
  [string]$reason = 'baseline_contract_failed'
  if ([bool]$BaselineSetup.valid) {
    $action = 'ACCEPT';$reason = 'baseline_contract_valid'
  } elseif ($retryEligible) {
    $action = 'RETRY'
    $reason = if ($knownStatRuntimeActiveReconciledPartialRetryCandidate) {
      'known_stat_runtime_active_reconciled_partial_d7_baseline_race'
    } elseif ($knownStatRuntimeVehicleAheadEmptyD7RetryCandidate) {
      'known_stat_runtime_vehicle_ahead_empty_d7_baseline_race'
    } elseif ($knownStatRuntimeVehicleAheadRetryCandidate) {
      'known_stat_runtime_vehicle_ahead_baseline_race'
    } elseif ($knownStatRuntimeReconciledPartialRetryCandidate) {
      'known_stat_runtime_reconciled_partial_d7_baseline_race'
    } elseif ($knownStatRuntimeRetryCandidate) {
      'known_stat_runtime_baseline_race'
    } else { 'single_param22_reconciliation_race' }
  } elseif (($param22RetryCandidate -or $knownStatRuntimeRetryCandidate -or
        $knownStatRuntimeReconciledPartialRetryCandidate -or
        $knownStatRuntimeActiveReconciledPartialRetryCandidate -or
        $knownStatRuntimeVehicleAheadEmptyD7RetryCandidate -or
        $knownStatRuntimeVehicleAheadRetryCandidate) -and
      -not $attemptAvailable) {
    $reason = 'retry_exhausted'
  } elseif (($param22RetryCandidate -or $knownStatRuntimeRetryCandidate -or
        $knownStatRuntimeReconciledPartialRetryCandidate -or
        $knownStatRuntimeActiveReconciledPartialRetryCandidate -or
        $knownStatRuntimeVehicleAheadEmptyD7RetryCandidate -or
        $knownStatRuntimeVehicleAheadRetryCandidate) -and
      -not $RetryBudgetAvailable) {
    $reason = 'shared_deadline_exhausted'
  } elseif ($exactActiveReconciledPartialFailureSet) {
    $reason =
      'unsafe_non_exact_stat_runtime_active_reconciled_partial_d7_baseline_race'
  } elseif ($exactVehicleAheadFailureSet) {
    $reason = 'unsafe_non_exact_stat_runtime_vehicle_ahead_baseline_race'
  } elseif ($singleReconciliationFailure) {
    $reason = 'unsafe_param22_mismatch_direction_or_magnitude'
  } elseif ($singleKnownStatRuntimeFailure) {
    $reason = 'unsafe_non_exact_stat_runtime_baseline_race'
  }
  return [pscustomobject][ordered]@{
    action=$action;reason=$reason;attempt_number=$AttemptNumber
    max_attempts=$MaxAttempts;failed_check_count=$failedChecks.Count
    failed_check_names=$failedCheckNames
    single_reconciliation_failure=$singleReconciliationFailure
    ground_ahead_one=$groundAheadOne
    single_known_stat_runtime_failure=$singleKnownStatRuntimeFailure
    known_stat_runtime_observer_exact=$knownStatRuntimeObserverExact
    known_stat_runtime_race=if ($null -ne $knownStatRuntimeRace) {
      $knownStatRuntimeRace.Value
    } else { $null }
    known_stat_runtime_reconciled_partial_observer_exact=
      $knownStatRuntimeReconciledPartialObserverExact
    known_stat_runtime_reconciled_partial_d7_race=
      if ($null -ne $knownStatRuntimeReconciledPartialRace) {
        $knownStatRuntimeReconciledPartialRace.Value
      } else { $null }
    exact_active_reconciled_partial_failure_set=
      $exactActiveReconciledPartialFailureSet
    known_stat_runtime_active_reconciled_partial_observer_exact=
      $knownStatRuntimeActiveReconciledPartialObserverExact
    known_stat_runtime_active_reconciled_partial_d7_race=
      if ($null -ne $knownStatRuntimeActiveReconciledPartialRace) {
        $knownStatRuntimeActiveReconciledPartialRace.Value
      } else { $null }
    exact_vehicle_ahead_failure_set=$exactVehicleAheadFailureSet
    known_stat_runtime_vehicle_ahead_observer_exact=
      $knownStatRuntimeVehicleAheadObserverExact
    known_stat_runtime_vehicle_ahead_race=
      if ($null -ne $knownStatRuntimeVehicleAheadRace) {
        $knownStatRuntimeVehicleAheadRace.Value
      } else { $null }
    known_stat_runtime_vehicle_ahead_empty_d7_observer_exact=
      $knownStatRuntimeVehicleAheadEmptyD7ObserverExact
    known_stat_runtime_vehicle_ahead_empty_d7_race=
      if ($null -ne $knownStatRuntimeVehicleAheadEmptyD7Race) {
        $knownStatRuntimeVehicleAheadEmptyD7Race.Value
      } else { $null }
    retry_budget_available=$RetryBudgetAvailable
    retry_eligible=$retryEligible
    retry_exhausted=($reason -ceq 'retry_exhausted')
    fixture_write_count=0
  }
}

function Test-BacklogDrainObservation {
  param(
    [Parameter(Mandatory = $true)]$GroundSnapshot,
    [Parameter(Mandatory = $true)]$VehicleSnapshot,
    [Parameter(Mandatory = $true)][double]$ObservedElapsedMs
  )
  $baselineSetup = Test-BaselineSetup -GroundSnapshot $GroundSnapshot `
      -VehicleSnapshot $VehicleSnapshot
  $vehicleResponse = Test-ReadinessSnapshotResponse `
      -Snapshot $VehicleSnapshot -ExpectedQ $VehicleSnapshot.expected_q
  $groundResponse = Test-ReadinessSnapshotResponse `
      -Snapshot $GroundSnapshot -ExpectedQ $GroundSnapshot.expected_q
  return [pscustomobject][ordered]@{
    valid=([bool]$baselineSetup.valid -and $vehicleResponse.valid -and
      $groundResponse.valid)
    observed_elapsed_ms=$ObservedElapsedMs
    ground_snapshot=$GroundSnapshot;vehicle_snapshot=$VehicleSnapshot
    baseline_setup=$baselineSetup;vehicle_response=$vehicleResponse
    ground_response=$groundResponse
  }
}

function Test-BacklogDrainStablePair {
  param(
    [Parameter(Mandatory = $true)]$FirstObservation,
    [Parameter(Mandatory = $true)]$SecondObservation
  )
  $firstVehicle = $FirstObservation.vehicle_snapshot
  $secondVehicle = $SecondObservation.vehicle_snapshot
  $firstGround = $FirstObservation.ground_snapshot
  $secondGround = $SecondObservation.ground_snapshot
  [double]$passiveSeparationMs = [double]$SecondObservation.observed_elapsed_ms -
      [double]$FirstObservation.observed_elapsed_ms
  $firstVehicleBoot = Get-SnapshotUInt64 -Snapshot $firstVehicle -Key 'boot'
  $secondVehicleBoot = Get-SnapshotUInt64 -Snapshot $secondVehicle -Key 'boot'
  $firstGroundBoot = Get-SnapshotUInt64 -Snapshot $firstGround -Key 'boot'
  $secondGroundBoot = Get-SnapshotUInt64 -Snapshot $secondGround -Key 'boot'
  $firstD722 = Get-SnapshotUInt64 -Snapshot $firstVehicle -Key 'd722'
  $secondD722 = Get-SnapshotUInt64 -Snapshot $secondVehicle -Key 'd722'
  $firstRf22 = Get-SnapshotUInt64 -Snapshot $firstGround -Key 'rf22'
  $secondRf22 = Get-SnapshotUInt64 -Snapshot $secondGround -Key 'rf22'
  [bool]$sameBoot = ($firstVehicleBoot.found -and $secondVehicleBoot.found -and
      $firstGroundBoot.found -and $secondGroundBoot.found -and
      [uint64]$firstVehicleBoot.value -eq [uint64]$secondVehicleBoot.value -and
      [uint64]$firstGroundBoot.value -eq [uint64]$secondGroundBoot.value)
  [bool]$d722Stable = ($firstD722.found -and $secondD722.found -and
      [uint64]$firstD722.value -eq [uint64]$secondD722.value)
  [bool]$rf22Stable = ($firstRf22.found -and $secondRf22.found -and
      [uint64]$firstRf22.value -eq [uint64]$secondRf22.value)
  $discardContinuity = Test-GroundOrderedDiscardContinuity `
      -BeforeGroundSnapshot $firstGround -AfterGroundSnapshot $secondGround `
      -NamePrefix 'backlog_drain_stable_pair'
  [bool]$qNext = ($secondVehicle.q_uint32 -eq
        (Get-NextQueryId -Current ([uint32]$firstVehicle.q_uint32)) -and
      $secondGround.q_uint32 -eq
        (Get-NextQueryId -Current ([uint32]$firstGround.q_uint32)))
  $checks = New-Object 'System.Collections.Generic.List[object]'
  foreach ($check in @(
    [pscustomobject]@{name='first_observation_clean';valid=[bool]$FirstObservation.valid},
    [pscustomobject]@{name='second_observation_clean';valid=[bool]$SecondObservation.valid},
    [pscustomobject]@{name='passive_separation_at_least_5000ms';valid=($passiveSeparationMs -ge 5000.0)},
    [pscustomobject]@{name='same_boot';valid=$sameBoot},
    [pscustomobject]@{name='q_next';valid=$qNext},
    [pscustomobject]@{name='d722_stable';valid=$d722Stable},
    [pscustomobject]@{name='rf22_stable';valid=$rf22Stable})) {
    $checks.Add($check)
  }
  foreach ($check in @($discardContinuity.checks)) { $checks.Add($check) }
  return [pscustomobject][ordered]@{
    valid=(@($checks | Where-Object {-not $_.valid}).Count -eq 0)
    passive_separation_ms=$passiveSeparationMs;same_boot=$sameBoot
    q_next=$qNext;d722_stable=$d722Stable;rf22_stable=$rf22Stable
    ground_ordered_discard_continuity=$discardContinuity
    checks=$checks.ToArray()
  }
}

function Test-PreRequestRecoveryBacklogPairPromotion {
  param(
    [Parameter(Mandatory = $true)]$RecoveryBacklogGate,
    [Parameter(Mandatory = $true)]$PreviousOfficialVehicle,
    [Parameter(Mandatory = $true)]$PreviousOfficialGround
  )
  $checks = New-Object 'System.Collections.Generic.List[object]'
  $gateValidProperty = $RecoveryBacklogGate.PSObject.Properties['valid']
  $syncInvalidProperty =
      $RecoveryBacklogGate.PSObject.Properties['sync_invalid']
  $timedOutProperty = $RecoveryBacklogGate.PSObject.Properties['timed_out']
  $fixtureWriteProperty =
      $RecoveryBacklogGate.PSObject.Properties['fixture_write_count']
  $requiredCountProperty = $RecoveryBacklogGate.PSObject.Properties[
      'required_stable_observation_count']
  $minimumSeparationProperty = $RecoveryBacklogGate.PSObject.Properties[
      'minimum_passive_separation_ms']
  $deadlineExtendedProperty =
      $RecoveryBacklogGate.PSObject.Properties['deadline_extended']
  [bool]$gateContractValid = ($null -ne $gateValidProperty -and
      [bool]$gateValidProperty.Value -and $null -ne $timedOutProperty -and
      -not [bool]$timedOutProperty.Value -and
      $null -ne $syncInvalidProperty -and
      -not [bool]$syncInvalidProperty.Value -and
      $null -ne $fixtureWriteProperty -and
      [int]$fixtureWriteProperty.Value -eq 0 -and
      $null -ne $requiredCountProperty -and
      [int]$requiredCountProperty.Value -eq 2 -and
      $null -ne $minimumSeparationProperty -and
      [double]$minimumSeparationProperty.Value -ge 5000.0 -and
      $null -ne $deadlineExtendedProperty -and
      -not [bool]$deadlineExtendedProperty.Value)
  $checks.Add([pscustomobject][ordered]@{
    name='recovery_backlog_gate_contract';valid=$gateContractValid
  })

  $observationsProperty =
      $RecoveryBacklogGate.PSObject.Properties['observations']
  $stablePairsProperty =
      $RecoveryBacklogGate.PSObject.Properties['stable_pairs']
  [object[]]$observations = if ($null -ne $observationsProperty) {
    [object[]]@($observationsProperty.Value)
  } else { [object[]]@() }
  [object[]]$stablePairs = if ($null -ne $stablePairsProperty) {
    [object[]]@($stablePairsProperty.Value)
  } else { [object[]]@() }
  [bool]$cardinalityValid = ($observations.Count -ge 2 -and
      $stablePairs.Count -ge 1)
  $checks.Add([pscustomobject][ordered]@{
    name='recovery_backlog_final_pair_cardinality';valid=$cardinalityValid
    observation_count=$observations.Count;stable_pair_count=$stablePairs.Count
  })

  $firstObservation = if ($observations.Count -ge 2) {
    $observations[$observations.Count - 2]
  } else { $null }
  $secondObservation = if ($observations.Count -ge 2) {
    $observations[$observations.Count - 1]
  } else { $null }
  $recordedStablePair = if ($stablePairs.Count -ge 1) {
    $stablePairs[$stablePairs.Count - 1]
  } else { $null }
  $recomputedStablePair = if ($null -ne $firstObservation -and
      $null -ne $secondObservation) {
    Test-BacklogDrainStablePair -FirstObservation $firstObservation `
        -SecondObservation $secondObservation
  } else { $null }
  [bool]$recordedStableValid = ($null -ne $recordedStablePair -and
      $null -ne $recordedStablePair.PSObject.Properties['valid'] -and
      [bool]$recordedStablePair.valid)
  [bool]$recomputedStableValid = ($null -ne $recomputedStablePair -and
      [bool]$recomputedStablePair.valid -and
      [double]$recomputedStablePair.passive_separation_ms -ge 5000.0)
  $checks.Add([pscustomobject][ordered]@{
    name='recovery_backlog_final_stable_pair_revalidated'
    recorded_valid=$recordedStableValid
    recomputed_valid=$recomputedStableValid
    valid=($recordedStableValid -and $recomputedStableValid)
  })

  $lastVehicleProperty =
      $RecoveryBacklogGate.PSObject.Properties['last_vehicle_snapshot']
  $lastGroundProperty =
      $RecoveryBacklogGate.PSObject.Properties['last_ground_snapshot']
  $lastVehicle = if ($null -ne $lastVehicleProperty) {
    $lastVehicleProperty.Value
  } else { $null }
  $lastGround = if ($null -ne $lastGroundProperty) {
    $lastGroundProperty.Value
  } else { $null }
  $secondVehicle = if ($null -ne $secondObservation -and
      $null -ne $secondObservation.PSObject.Properties['vehicle_snapshot']) {
    $secondObservation.vehicle_snapshot
  } else { $null }
  $secondGround = if ($null -ne $secondObservation -and
      $null -ne $secondObservation.PSObject.Properties['ground_snapshot']) {
    $secondObservation.ground_snapshot
  } else { $null }
  [bool]$vehicleIdentityValid = ($null -ne $lastVehicle -and
      $null -ne $secondVehicle -and
      [object]::ReferenceEquals($lastVehicle, $secondVehicle) -and
      [string]$lastVehicle.status -ceq 'COMPLETE' -and
      [uint32]$lastVehicle.q_uint32 -eq [uint32]$secondVehicle.q_uint32 -and
      [uint64]$lastVehicle.ms_uint64 -eq [uint64]$secondVehicle.ms_uint64)
  [bool]$groundIdentityValid = ($null -ne $lastGround -and
      $null -ne $secondGround -and
      [object]::ReferenceEquals($lastGround, $secondGround) -and
      [string]$lastGround.status -ceq 'COMPLETE' -and
      [uint32]$lastGround.q_uint32 -eq [uint32]$secondGround.q_uint32 -and
      [uint64]$lastGround.ms_uint64 -eq [uint64]$secondGround.ms_uint64)
  $checks.Add([pscustomobject][ordered]@{
    name='recovery_backlog_last_snapshots_are_final_observation'
    vehicle_identity=$vehicleIdentityValid;ground_identity=$groundIdentityValid
    valid=($vehicleIdentityValid -and $groundIdentityValid)
  })

  $baselineSetup = if ($null -ne $lastVehicle -and $null -ne $lastGround) {
    Test-BaselineSetup -GroundSnapshot $lastGround `
        -VehicleSnapshot $lastVehicle `
        -PreviousGroundSnapshot $PreviousOfficialGround `
        -PreviousVehicleSnapshot $PreviousOfficialVehicle
  } else { $null }
  [bool]$baselineSetupValid = ($null -ne $baselineSetup -and
      [bool]$baselineSetup.valid)
  $checks.Add([pscustomobject][ordered]@{
    name='recovery_backlog_promoted_pair_strict_baseline_recheck'
    valid=$baselineSetupValid
    failed_checks=if($null -ne $baselineSetup){
      [object[]]@($baselineSetup.checks | Where-Object {-not $_.valid})
    }else{[object[]]@()}
  })
  [bool]$valid = (@($checks | Where-Object {-not $_.valid}).Count -eq 0)
  return [pscustomobject][ordered]@{
    schema_version=1;valid=$valid
    status=if($valid){'PROMOTED'}else{'REJECTED'}
    source='recovery_backlog_last_stable_pair'
    checks=$checks.ToArray();baseline_setup=$baselineSetup
    recorded_stable_pair=$recordedStablePair
    recomputed_stable_pair=$recomputedStablePair
    selected_vehicle_snapshot=if($valid){$lastVehicle}else{$null}
    selected_ground_snapshot=if($valid){$lastGround}else{$null}
    additional_diagnostic_query_count=0
    fixture_write_count=0
    skip_next_recovery_capture=$valid
  }
}

function Test-BacklogRecoveredSnapshotContinuity {
  param(
    [Parameter(Mandatory = $true)][ValidateSet('vehicle','ground')]
      [string]$Role,
    [Parameter(Mandatory = $true)][AllowNull()]$PreviousSnapshot,
    [Parameter(Mandatory = $true)]$AnchorSnapshot,
    [Parameter(Mandatory = $true)]$RecoveredSnapshot,
    [Parameter(Mandatory = $true)][int]$QueryWriteCount,
    [Nullable[uint32]]$FailedPartialQ = $null
  )
  $checks = New-Object 'System.Collections.Generic.List[object]'
  if ($null -eq $PreviousSnapshot) {
    [Nullable[uint32]]$expectedAnchorQ = $null
    [Nullable[uint32]]$expectedRecoveredQ = $null
    if ($null -ne $FailedPartialQ) {
      [uint32]$nextAnchorQ = Get-NextQueryId -Current `
          ([uint32]$FailedPartialQ)
      $expectedAnchorQ = $nextAnchorQ
      [uint32]$nextRecoveredQ = Get-NextQueryId -Current $nextAnchorQ
      $expectedRecoveredQ = $nextRecoveredQ
    }
    $anchorResponse = Test-ReadinessSnapshotResponse `
        -Snapshot $AnchorSnapshot -ExpectedQ $expectedAnchorQ
    $recoveredResponse = Test-ReadinessSnapshotResponse `
        -Snapshot $RecoveredSnapshot -ExpectedQ $expectedRecoveredQ
    $anchorBoot = Get-SnapshotUInt64 -Snapshot $AnchorSnapshot -Key 'boot'
    $recoveredBoot = Get-SnapshotUInt64 `
        -Snapshot $RecoveredSnapshot -Key 'boot'
    [bool]$sameBoot = ($anchorBoot.found -and $recoveredBoot.found -and
        [uint64]$anchorBoot.value -ne 0 -and
        [uint64]$anchorBoot.value -eq [uint64]$recoveredBoot.value)
    [bool]$msIncreasing = ($AnchorSnapshot.status -eq 'COMPLETE' -and
        $RecoveredSnapshot.status -eq 'COMPLETE' -and
        [uint64]$AnchorSnapshot.ms_uint64 -lt
          [uint64]$RecoveredSnapshot.ms_uint64)
    [string]$counterKey = if ($Role -ceq 'vehicle') {'d722'} else {'rf22'}
    $counterDelta = Get-SnapshotDelta -Baseline $AnchorSnapshot `
        -Post $RecoveredSnapshot -Key $counterKey
    [bool]$counterMonotonic = ($counterDelta.found -and
        $counterDelta.monotonic)
    $checks = New-Object 'System.Collections.Generic.List[object]'
    foreach ($row in @(
        @('failed_partial_q_present',($null -ne $FailedPartialQ)),
        @('anchor_response_valid',$anchorResponse.valid),
        @('recovered_response_valid',$recoveredResponse.valid),
        @('anchor_q_next',$anchorResponse.expected_q_exact),
        @('recovered_q_next',$recoveredResponse.expected_q_exact),
        @('same_boot',$sameBoot),@('ms_increasing',$msIncreasing),
        @(($counterKey + '_monotonic'),$counterMonotonic),
        @('query_write_count_bounded',($QueryWriteCount -ge 2 -and
            $QueryWriteCount -le 3)))) {
      $checks.Add([pscustomobject]@{name=[string]$row[0];valid=[bool]$row[1]})
    }
    $discardContinuity = $null
    if ($Role -ceq 'ground') {
      $discardContinuity = Test-GroundOrderedDiscardContinuity `
          -BeforeGroundSnapshot $AnchorSnapshot `
          -AfterGroundSnapshot $RecoveredSnapshot `
          -NamePrefix 'backlog_recovery_ground_anchor_confirmation'
      foreach ($check in @($discardContinuity.checks)) { $checks.Add($check) }
    }
    $anchor_confirmation_no_previous = [pscustomobject][ordered]@{
      mode='anchor_confirmation_no_previous'
      anchor_snapshot=$AnchorSnapshot;recovered_snapshot=$RecoveredSnapshot
      failed_partial_q=$FailedPartialQ;expected_anchor_q=$expectedAnchorQ
      expected_recovered_q=$expectedRecoveredQ
      same_boot=$sameBoot;ms_monotonic=$msIncreasing
      counter_monotonic=$counterMonotonic
      valid=(@($checks | Where-Object {-not $_.valid}).Count -eq 0)
    }
    return [pscustomobject][ordered]@{
      valid=$anchor_confirmation_no_previous.valid
      role=$Role;same_boot=$sameBoot;q_bound=$true
      q_next=$recoveredResponse.expected_q_exact;ms_increasing=$msIncreasing
      counter_key=$counterKey;counter_monotonic=$counterMonotonic
      anchor_snapshot=$AnchorSnapshot;recovered_snapshot=$RecoveredSnapshot
      query_write_count=$QueryWriteCount
      ground_ordered_discard_continuity=$discardContinuity
      ordered_proof=$anchor_confirmation_no_previous
      checks=$checks.ToArray()
    }
  }
  $anchorResponse = Test-ReadinessSnapshotResponse -Snapshot $AnchorSnapshot
  [Nullable[uint32]]$expectedRecoveredQ = $null
  if ($anchorResponse.valid) {
    $expectedRecoveredQ = Get-NextQueryId -Current `
        ([uint32]$AnchorSnapshot.q_uint32)
  }
  $recoveredResponse = Test-ReadinessSnapshotResponse `
      -Snapshot $RecoveredSnapshot -ExpectedQ $expectedRecoveredQ
  [uint32]$previousNextQ = Get-NextQueryId -Current `
      ([uint32]$PreviousSnapshot.q_uint32)
  [uint32]$previousNextNextQ = Get-NextQueryId -Current $previousNextQ
  [bool]$anchorQBound = ($anchorResponse.valid -and
      ([uint32]$AnchorSnapshot.q_uint32 -eq $previousNextQ -or
       [uint32]$AnchorSnapshot.q_uint32 -eq $previousNextNextQ))
  $previousBoot = Get-SnapshotUInt64 -Snapshot $PreviousSnapshot -Key 'boot'
  $anchorBoot = Get-SnapshotUInt64 -Snapshot $AnchorSnapshot -Key 'boot'
  $recoveredBoot = Get-SnapshotUInt64 -Snapshot $RecoveredSnapshot -Key 'boot'
  [bool]$sameBoot = ($previousBoot.found -and $anchorBoot.found -and
      $recoveredBoot.found -and [uint64]$previousBoot.value -ne 0 -and
      [uint64]$previousBoot.value -eq [uint64]$anchorBoot.value -and
      [uint64]$anchorBoot.value -eq [uint64]$recoveredBoot.value)
  [bool]$msIncreasing = ($PreviousSnapshot.status -eq 'COMPLETE' -and
      $AnchorSnapshot.status -eq 'COMPLETE' -and
      $RecoveredSnapshot.status -eq 'COMPLETE' -and
      [uint64]$PreviousSnapshot.ms_uint64 -lt
        [uint64]$AnchorSnapshot.ms_uint64 -and
      [uint64]$AnchorSnapshot.ms_uint64 -lt
        [uint64]$RecoveredSnapshot.ms_uint64)
  [string]$counterKey = if ($Role -ceq 'vehicle') {'d722'} else {'rf22'}
  $firstDelta = Get-SnapshotDelta -Baseline $PreviousSnapshot `
      -Post $AnchorSnapshot -Key $counterKey
  $secondDelta = Get-SnapshotDelta -Baseline $AnchorSnapshot `
      -Post $RecoveredSnapshot -Key $counterKey
  [bool]$counterMonotonic = ($firstDelta.found -and $firstDelta.monotonic -and
      $secondDelta.found -and $secondDelta.monotonic)
  foreach ($row in @(
      @('anchor_response_valid',$anchorResponse.valid),
      @('recovered_response_valid',$recoveredResponse.valid),
      @('anchor_q_within_failed_write_bound',$anchorQBound),
      @('recovered_q_next',$recoveredResponse.expected_q_exact),
      @('same_boot',$sameBoot),@('ms_increasing',$msIncreasing),
      @(($counterKey + '_monotonic'),$counterMonotonic),
      @('query_write_count_bounded',($QueryWriteCount -ge 2 -and
          $QueryWriteCount -le 3)))) {
    $checks.Add([pscustomobject]@{name=[string]$row[0];valid=[bool]$row[1]})
  }
  $discardContinuity = $null
  if ($Role -ceq 'ground') {
    $discardContinuity = Test-GroundOrderedDiscardContinuity `
        -BeforeGroundSnapshot $PreviousSnapshot `
        -AfterGroundSnapshot $RecoveredSnapshot `
        -NamePrefix 'backlog_recovery_ground'
    foreach ($check in @($discardContinuity.checks)) { $checks.Add($check) }
  }
  $orderedProof = [pscustomobject][ordered]@{
    same_boot=$sameBoot
    ms_monotonic=$msIncreasing
    q_within_failed_write_bound=$anchorQBound
    counter_monotonic=$counterMonotonic
    valid=(@($checks | Where-Object {-not $_.valid}).Count -eq 0)
  }
  return [pscustomobject][ordered]@{
    valid=$orderedProof.valid
    role=$Role;same_boot=$sameBoot;q_bound=$anchorQBound
    q_next=$recoveredResponse.expected_q_exact;ms_increasing=$msIncreasing
    counter_key=$counterKey;counter_monotonic=$counterMonotonic
    anchor_snapshot=$AnchorSnapshot;recovered_snapshot=$RecoveredSnapshot
    query_write_count=$QueryWriteCount
    ground_ordered_discard_continuity=$discardContinuity
    ordered_proof=$orderedProof
    checks=$checks.ToArray()
  }
}

function Test-PreRequestVehicleGate {
  param(
    [Parameter(Mandatory = $true)]$OfficialVehicle,
    [Parameter(Mandatory = $true)]$OfficialGround,
    [Parameter(Mandatory = $true)]$PreRequestVehicle
  )
  [uint32]$expectedQ = Get-NextQueryId -Current `
      ([uint32]$OfficialVehicle.q_uint32)
  $response = Test-ReadinessSnapshotResponse -Snapshot $PreRequestVehicle `
      -ExpectedQ $expectedQ
  $officialBoot = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'boot'
  $currentBoot = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'boot'
  $officialD722 = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'd722'
  $currentD722 = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'd722'
  $groundRf22 = Get-SnapshotUInt64 -Snapshot $OfficialGround -Key 'rf22'
  [bool]$sameBoot = ($officialBoot.found -and $currentBoot.found -and
      [uint64]$officialBoot.value -eq [uint64]$currentBoot.value)
  [bool]$d722Stable = ($officialD722.found -and $currentD722.found -and
      [uint64]$officialD722.value -eq [uint64]$currentD722.value)
  [bool]$d722Rf22Reconciled = ($currentD722.found -and $groundRf22.found -and
      [uint64]$currentD722.value -eq [uint64]$groundRf22.value)
  [bool]$msIncreasing = ([uint64]$PreRequestVehicle.ms_uint64 -gt
      [uint64]$OfficialVehicle.ms_uint64)
  $checks = New-Object 'System.Collections.Generic.List[object]'
  foreach ($row in @(
      @('response_exact',$response.valid),@('same_boot',$sameBoot),
      @('q_next',$response.expected_q_exact),@('ms_increasing',$msIncreasing),
      @('d722_stable',$d722Stable),
      @('d722_rf22_reconciled',$d722Rf22Reconciled))) {
    $checks.Add([pscustomobject]@{name=[string]$row[0];valid=[bool]$row[1]})
  }
  foreach ($zeroSpec in @(
      @('pgq','pgq'),@('pga','pga'),@('prq','prq'),@('ptq','ptq'),
      @('ef','ef'),
      @('related_drop_error_zero_pvbad','pvbad'),
      @('related_drop_error_zero_pvov','pvov'),
      @('related_drop_error_zero_eo','eo'),
      @('related_drop_error_zero_evo','evo'))) {
    $field = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle `
        -Key ([string]$zeroSpec[1])
    $checks.Add([pscustomobject]@{
      name=[string]$zeroSpec[0]
      valid=($field.found -and [uint64]$field.value -eq 0)
      actual=$field.value
    })
  }
  $currentD7pb = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'd7pb'
  $checks.Add([pscustomobject]@{
    name='d7pb_empty';key='d7pb';expected=[uint64]0
    actual=$currentD7pb.value
    valid=($currentD7pb.found -and
      [uint64]$currentD7pb.value -eq [uint64]0)
  })
  [bool]$relatedDropErrorZero = (@($checks | Where-Object {
      $_.name -like 'related_drop_error_zero_*' -and -not $_.valid
    }).Count -eq 0)
  $checks.Add([pscustomobject]@{
    name='related_drop_error_zero';valid=$relatedDropErrorZero
  })
  return [pscustomobject][ordered]@{
    valid=(@($checks | Where-Object {-not $_.valid}).Count -eq 0)
    same_boot=$sameBoot;q_next=$response.expected_q_exact
    ms_increasing=$msIncreasing;d722_stable=$d722Stable
    d722_rf22_reconciled=$d722Rf22Reconciled
    response=$response;checks=$checks.ToArray()
  }
}

function Test-PostSnapshotContract {
  param($BaselineGround, $PostGround, [Alias('Baseline')]$BaselineVehicle,
        $PostVehicle,
        [uint64]$MatchingUsbParamValues = 932,
        [ValidateSet('NORMAL','FUTURE_INDEX_RECOVERY')]
        [string]$ExpectedDiagnosticFaultMode = 'NORMAL',
        [ValidateRange(0, 931)]
        [int]$ExpectedDiagnosticFaultDropIndex = 930)
  if ($ExpectedDiagnosticFaultMode -ceq 'FUTURE_INDEX_RECOVERY' -and
      $ExpectedDiagnosticFaultDropIndex -ne 930) {
    throw 'The directed FutureIndexRecovery assessment supports drop index 930 only.'
  }
  $checks = New-Object 'System.Collections.Generic.List[object]'
  function Add-ExactDelta {
    param([string]$Name, $Before, $After, [string]$Key, [uint64]$Expected,
      [switch]$RequireAbsoluteZero)
    $delta = Get-SnapshotDelta -Baseline $Before -Post $After -Key $Key
    $beforeReading = Get-SnapshotUInt64 -Snapshot $Before -Key $Key
    $afterReading = Get-SnapshotUInt64 -Snapshot $After -Key $Key
    [bool]$absoluteValid = (-not $RequireAbsoluteZero -or
      ($Expected -eq 0 -and $beforeReading.found -and $afterReading.found -and
       [uint64]$beforeReading.value -eq 0 -and
       [uint64]$afterReading.value -eq 0))
    $checks.Add([pscustomobject][ordered]@{
      name=$Name; key=$Key
      rule=if ($RequireAbsoluteZero) {
        'baseline_post_and_delta_zero'
      } else { 'exact_delta' }
      expected=$Expected
      actual=if ($RequireAbsoluteZero) {
        [ordered]@{before=$beforeReading.value;after=$afterReading.value
          delta=$delta.delta}
      } else { $delta.delta }
      valid=($delta.monotonic -and [uint64]$delta.delta -eq $Expected -and
        $absoluteValid)
    })
  }
  foreach ($role in @(
      @('ground', $BaselineGround, $PostGround),
      @('vehicle', $BaselineVehicle, $PostVehicle))) {
    $beforeBoot = Get-SnapshotUInt64 -Snapshot $role[1] -Key 'boot'
    $afterBoot = Get-SnapshotUInt64 -Snapshot $role[2] -Key 'boot'
    $checks.Add([pscustomobject]@{
      name=([string]$role[0] + '_same_boot'); key='boot'; rule='same_boot'
      valid=($beforeBoot.found -and $afterBoot.found -and
        [uint64]$beforeBoot.value -ne 0 -and
        [uint64]$beforeBoot.value -eq [uint64]$afterBoot.value)
    })
    [bool]$qValid = ($null -ne $role[1] -and $null -ne $role[2] -and
        $role[1].status -eq 'COMPLETE' -and $role[2].status -eq 'COMPLETE' -and
        [uint32]$role[2].q_uint32 -eq
            (Get-NextQueryId -Current ([uint32]$role[1].q_uint32)))
    $checks.Add([pscustomobject]@{
      name=([string]$role[0] + '_query_q_plus_one')
      key='q'; rule='q+1'; valid=$qValid
    })
    [bool]$msValid = ($null -ne $role[1] -and $null -ne $role[2] -and
        $role[1].status -eq 'COMPLETE' -and $role[2].status -eq 'COMPLETE' -and
        [uint64]$role[2].ms_uint64 -gt [uint64]$role[1].ms_uint64)
    $checks.Add([pscustomobject]@{
      name=([string]$role[0] + '_uint64_ms_increasing')
      key='ms'; rule='uint64_strictly_increasing'; valid=$msValid
    })
  }
  Add-ExactDelta 'ground_param_request_list_u21' $BaselineGround $PostGround `
      'u21' 1
  Add-ExactDelta 'ground_proxy_request_completed_upcon' $BaselineGround `
      $PostGround 'upcon' 1
  Add-ExactDelta 'ground_proxy_native_list_leased_once' $BaselineGround `
      $PostGround 'pnat' 1
  Add-ExactDelta 'ground_proxy_native_poison_zero' $BaselineGround `
      $PostGround 'ppois' 0
  Add-ExactDelta 'ground_proxy_unmatched_values_forwarded_zero' `
      $BaselineGround $PostGround 'punm' 0

  [string[]]$recoveryCounterKeys = @(
    'pvto','prold','prfut','prgap','prto','prq','prtx','prv','prusb','punm')
  [string[]]$recoveryGaugeKeys = @(
    'pract','prlv','prlr','prlex','prlrx','prlcnt','prlseq','prlms')
  $recoveryDeltas = [ordered]@{}
  foreach ($key in @($recoveryCounterKeys +
      @('pnq','ppre','pgen','ptx','deq','rf22','rfv','rfpbs','rfpfa',
        'rfprs'))) {
    $recoveryDeltas[$key] = Get-SnapshotDelta -Baseline $BaselineGround `
        -Post $PostGround -Key $key
  }
  $recoveryPost = [ordered]@{}
  foreach ($key in @($recoveryGaugeKeys + @('rfpbuf','rfdmbuf','rfdmesc'))) {
    $recoveryPost[$key] = Get-SnapshotUInt64 -Snapshot $PostGround -Key $key
  }
  [bool]$recoveryEvidenceComplete = $true
  $precommitQuarantineEvidence = $recoveryDeltas['ppre']
  $checks.Add([pscustomobject][ordered]@{
    name='ground_proxy_precommit_quarantine_present';key='ppre'
    rule='baseline_and_post_present_monotonic';expected=$true
    actual=[ordered]@{
      found=$precommitQuarantineEvidence.found
      monotonic=$precommitQuarantineEvidence.monotonic
    }
    valid=($precommitQuarantineEvidence.found -and
      $precommitQuarantineEvidence.monotonic)
  })
  if (-not ($precommitQuarantineEvidence.found -and
      $precommitQuarantineEvidence.monotonic)) {
    $recoveryEvidenceComplete = $false
  }
  foreach ($key in $recoveryCounterKeys) {
    $checks.Add([pscustomobject][ordered]@{
      name=('ground_recovery_counter_' + $key + '_present');key=$key
      rule='baseline_and_post_present';expected=$true
      actual=[bool]$recoveryDeltas[$key].found
      valid=[bool]$recoveryDeltas[$key].found
    })
    if (-not [bool]$recoveryDeltas[$key].found) {
      $recoveryEvidenceComplete = $false
    }
  }
  foreach ($key in $recoveryGaugeKeys) {
    $checks.Add([pscustomobject][ordered]@{
      name=('ground_recovery_latch_' + $key + '_present');key=$key
      rule='post_present';expected=$true
      actual=[bool]$recoveryPost[$key].found
      valid=[bool]$recoveryPost[$key].found
    })
    if (-not [bool]$recoveryPost[$key].found) {
      $recoveryEvidenceComplete = $false
    }
  }
  $checks.Add([pscustomobject][ordered]@{
    name='ground_recovery_evidence_complete';key='GCSTAT3 recovery schema'
    rule='all_required';expected=$true;actual=$recoveryEvidenceComplete
    valid=$recoveryEvidenceComplete
  })

  foreach ($key in @('mcr','rfpno','rfpbl','rfpcr','rfpum','rfpuf')) {
    Add-ExactDelta ('ground_radio_parser_error_delta_zero_' + $key) `
        $BaselineGround $PostGround $key 0 -RequireAbsoluteZero
  }
  $radioBytes = $recoveryDeltas['rfpbs']
  $radioFrames = $recoveryDeltas['rfpfa']
  $radioObserverFrames = $recoveryDeltas['rfv']
  $radioResets = $recoveryDeltas['rfprs']
  $rf22Delta = $recoveryDeltas['rf22']
  $checks.Add([pscustomobject][ordered]@{
    name='ground_radio_parser_bytes_positive';key='rfpbs';rule='positive_delta'
    expected='>0';actual=$radioBytes.delta
    valid=($radioBytes.found -and $radioBytes.monotonic -and
      [uint64]$radioBytes.delta -gt 0)
  })
  $checks.Add([pscustomobject][ordered]@{
    name='ground_radio_parser_frames_positive';key='rfpfa';rule='positive_delta'
    expected='>0';actual=$radioFrames.delta
    valid=($radioFrames.found -and $radioFrames.monotonic -and
      [uint64]$radioFrames.delta -gt 0)
  })
  $checks.Add([pscustomobject][ordered]@{
    name='ground_radio_parser_observer_frame_accounting';key='rfpfa==rfv'
    rule='exact_relation';expected='equal';parser_frames=$radioFrames.delta
    observer_frames=$radioObserverFrames.delta
    valid=($radioFrames.found -and $radioFrames.monotonic -and
      $radioObserverFrames.found -and $radioObserverFrames.monotonic -and
      [uint64]$radioFrames.delta -eq [uint64]$radioObserverFrames.delta)
  })
  $checks.Add([pscustomobject][ordered]@{
    name='ground_radio_parser_covers_all_param_values';key='rfpfa>=rf22'
    rule='minimum_relation';expected='rfpfa>=rf22'
    parser_frames=$radioFrames.delta;param_values=$rf22Delta.delta
    valid=($radioFrames.found -and $radioFrames.monotonic -and
      $rf22Delta.found -and $rf22Delta.monotonic -and
      [uint64]$radioFrames.delta -ge [uint64]$rf22Delta.delta)
  })
  $checks.Add([pscustomobject][ordered]@{
    name='ground_radio_parser_resets_monotonic';key='rfprs';rule='monotonic'
    expected='monotonic';actual=$radioResets.delta
    valid=($radioResets.found -and $radioResets.monotonic)
  })
  foreach ($bufferSpec in @(
      @('ground_radio_parser_buffer_empty_post','rfpbuf'),
      @('ground_radio_demux_buffer_empty_post','rfdmbuf'))) {
    $reading = $recoveryPost[[string]$bufferSpec[1]]
    $checks.Add([pscustomobject][ordered]@{
      name=[string]$bufferSpec[0];key=[string]$bufferSpec[1];rule='post_exact'
      expected=[uint64]0;actual=$reading.value
      valid=($reading.found -and [uint64]$reading.value -eq 0)
    })
  }
  $escapeMode = $recoveryPost['rfdmesc']
  $checks.Add([pscustomobject][ordered]@{
    name='ground_radio_demux_escape_mode_enabled_post';key='rfdmesc'
    rule='post_exact';expected=[uint64]1;actual=$escapeMode.value
    valid=($escapeMode.found -and [uint64]$escapeMode.value -eq 1)
  })

  # native_stream_path choices are deliberately exhaustive and disjoint:
  # NORMAL, FUTURE_INDEX_RECOVERY, INTER_VALUE_TIMEOUT_RECOVERY, INVALID.
  [string]$nativeStreamPath = 'INVALID'
  [bool]$normalRecoveryEvidence = $recoveryEvidenceComplete
  if ($normalRecoveryEvidence) {
    foreach ($key in $recoveryCounterKeys) {
      $delta = $recoveryDeltas[$key]
      if (-not ($delta.monotonic -and [uint64]$delta.delta -eq 0)) {
        $normalRecoveryEvidence = $false
      }
    }
    $normalRecoveryGaugeExpected = [ordered]@{
      pract=[uint64]0;prlv=[uint64]0;prlr=[uint64]0;prlex=[uint64]0
      prlrx=[uint64]65535;prlcnt=[uint64]0;prlseq=[uint64]0;prlms=[uint64]0
    }
    foreach ($key in $recoveryGaugeKeys) {
      $reading = $recoveryPost[$key]
      if (-not ($reading.found -and [uint64]$reading.value -eq
          [uint64]$normalRecoveryGaugeExpected[$key])) {
        $normalRecoveryEvidence = $false
      }
    }
  }
  [bool]$futureRecoveryEvidence = ($recoveryEvidenceComplete -and
      $recoveryPost['pract'].value -eq 1 -and
      $recoveryPost['prlv'].value -eq 1 -and
      $recoveryPost['prlr'].value -eq 1 -and
      $recoveryDeltas['pvto'].delta -eq 0 -and
      $recoveryDeltas['prgap'].delta -eq 1 -and
      $recoveryDeltas['prto'].delta -eq 0 -and
      $recoveryDeltas['prfut'].delta -ge 1)
  [bool]$timeoutRecoveryEvidence = ($recoveryEvidenceComplete -and
      $recoveryPost['pract'].value -eq 1 -and
      $recoveryPost['prlv'].value -eq 1 -and
      $recoveryPost['prlr'].value -eq 2 -and
      $recoveryDeltas['pvto'].delta -eq 1 -and
      $recoveryDeltas['prgap'].delta -eq 0 -and
      $recoveryDeltas['prto'].delta -eq 1)
  if ($normalRecoveryEvidence) {
    $nativeStreamPath = 'NORMAL'
  } elseif ($futureRecoveryEvidence -and -not $timeoutRecoveryEvidence) {
    $nativeStreamPath = 'FUTURE_INDEX_RECOVERY'
  } elseif ($timeoutRecoveryEvidence -and -not $futureRecoveryEvidence) {
    $nativeStreamPath = 'INTER_VALUE_TIMEOUT_RECOVERY'
  }
  $checks.Add([pscustomobject][ordered]@{
    name='native_stream_path_recognized';key='native_stream_path'
    rule='exact_path';expected=@('NORMAL','FUTURE_INDEX_RECOVERY',
      'INTER_VALUE_TIMEOUT_RECOVERY');actual=$nativeStreamPath
    valid=($nativeStreamPath -cne 'INVALID')
  })

  if ($nativeStreamPath -ceq 'NORMAL') {
    $normalQuarantine = $recoveryDeltas['pnq']
    $normalPrecommitQuarantine = $recoveryDeltas['ppre']
    $checks.Add([pscustomobject][ordered]@{
      name='ground_proxy_native_quarantine_is_precommit_only'
      key='pnq==ppre';rule='exact_relation';expected='equal'
      pnq=$normalQuarantine.delta;ppre=$normalPrecommitQuarantine.delta
      valid=($normalQuarantine.found -and $normalQuarantine.monotonic -and
        $normalPrecommitQuarantine.found -and
        $normalPrecommitQuarantine.monotonic -and
        [uint64]$normalQuarantine.delta -eq
          [uint64]$normalPrecommitQuarantine.delta)
    })
    Add-ExactDelta 'ground_proxy_generated_index_reads_zero' $BaselineGround `
        $PostGround 'pgen' 0
    Add-ExactDelta 'ground_proxy_transmitted_native_list_once' $BaselineGround `
        $PostGround 'ptx' 1
    Add-ExactDelta 'ground_proxy_dequeued_native_list_once' $BaselineGround `
        $PostGround 'deq' 1
    [uint64]$normalExpectedRf22 = [uint64]$script:ExpectedParamCount +
        [uint64]$normalQuarantine.delta
    $checks.Add([pscustomobject][ordered]@{
      name='ground_rf_param_values_exact';key='rf22'
      rule='932_plus_precommit_quarantine';expected=$normalExpectedRf22
      actual=$recoveryDeltas['rf22'].delta
      valid=($normalQuarantine.found -and $normalQuarantine.monotonic -and
        $normalPrecommitQuarantine.found -and
        $normalPrecommitQuarantine.monotonic -and
        [uint64]$normalQuarantine.delta -eq
          [uint64]$normalPrecommitQuarantine.delta -and
        $recoveryDeltas['rf22'].found -and
        $recoveryDeltas['rf22'].monotonic -and
        [uint64]$recoveryDeltas['rf22'].delta -eq $normalExpectedRf22)
    })
  } elseif ($nativeStreamPath -ceq 'FUTURE_INDEX_RECOVERY' -or
      $nativeStreamPath -ceq 'INTER_VALUE_TIMEOUT_RECOVERY') {
    $expectedIndex = $recoveryPost['prlex']
    [bool]$expectedIndexValid = ($expectedIndex.found -and
      [uint64]$expectedIndex.value -lt [uint64]$script:ExpectedParamCount)
    [uint64]$recoveryRequestCount = 0
    if ($expectedIndexValid) {
      $recoveryRequestCount = [uint64]$script:ExpectedParamCount -
          [uint64]$recoveryPost['prlex'].value
    }
    $checks.Add([pscustomobject][ordered]@{
      name='ground_recovery_expected_index_in_range';key='prlex'
      rule='0..931';expected='less_than_ExpectedParamCount'
      actual=$expectedIndex.value;valid=$expectedIndexValid
    })
    $checks.Add([pscustomobject][ordered]@{
      name='ground_recovery_request_count_positive';key='prq'
      rule='exact_missing_tail';expected=$recoveryRequestCount
      actual=$recoveryDeltas['prq'].delta
      valid=($expectedIndexValid -and $recoveryRequestCount -ge 1 -and
        $recoveryDeltas['prq'].monotonic -and
        [uint64]$recoveryDeltas['prq'].delta -eq $recoveryRequestCount)
    })
    foreach ($accountSpec in @(
        @('ground_recovery_generated_missing_tail','pgen',$recoveryRequestCount),
        @('ground_recovery_tx_accepted_missing_tail','prtx',$recoveryRequestCount),
        @('ground_recovery_values_seen_missing_tail','prv',$recoveryRequestCount),
        @('ground_recovery_values_usb_queued_missing_tail','prusb',$recoveryRequestCount),
        @('ground_proxy_total_tx_native_plus_recovery','ptx',
          [uint64](1 + $recoveryRequestCount)),
        @('ground_proxy_total_dequeue_native_plus_recovery','deq',
          [uint64](1 + $recoveryRequestCount)))) {
      [string]$accountKey = [string]$accountSpec[1]
      [uint64]$accountExpected = [uint64]$accountSpec[2]
      $accountDelta = $recoveryDeltas[$accountKey]
      $checks.Add([pscustomobject][ordered]@{
        name=[string]$accountSpec[0];key=$accountKey;rule='exact_relation'
        expected=$accountExpected;actual=$accountDelta.delta
        valid=($accountDelta.found -and $accountDelta.monotonic -and
          [uint64]$accountDelta.delta -eq $accountExpected)
      })
    }
    $checks.Add([pscustomobject][ordered]@{
      name='ground_recovery_request_accounting_equal';key='prq==prtx==prv==prusb'
      rule='exact_relation';expected=$recoveryRequestCount
      actual=[ordered]@{
        prq=$recoveryDeltas['prq'].delta;prtx=$recoveryDeltas['prtx'].delta
        prv=$recoveryDeltas['prv'].delta;prusb=$recoveryDeltas['prusb'].delta
      }
      valid=($recoveryDeltas['prq'].found -and
        $recoveryDeltas['prtx'].found -and $recoveryDeltas['prv'].found -and
        $recoveryDeltas['prusb'].found -and
        [uint64]$recoveryDeltas['prq'].delta -eq $recoveryRequestCount -and
        [uint64]$recoveryDeltas['prtx'].delta -eq $recoveryRequestCount -and
        [uint64]$recoveryDeltas['prv'].delta -eq $recoveryRequestCount -and
        [uint64]$recoveryDeltas['prusb'].delta -eq $recoveryRequestCount)
    })
    $checks.Add([pscustomobject][ordered]@{
      name='ground_recovery_old_duplicates_zero';key='prold';rule='exact_delta'
      expected=[uint64]0;actual=$recoveryDeltas['prold'].delta
      valid=($recoveryDeltas['prold'].found -and
        $recoveryDeltas['prold'].monotonic -and
        [uint64]$recoveryDeltas['prold'].delta -eq 0)
