    $checks.Add([pscustomobject][ordered]@{
      name='ground_recovery_quarantine_is_future_or_precommit'
      key='pnq==prfut+ppre';rule='exact_relation'
      expected='sum';pnq=$recoveryDeltas['pnq'].delta
      prfut=$recoveryDeltas['prfut'].delta
      ppre=$recoveryDeltas['ppre'].delta
      valid=($recoveryDeltas['pnq'].found -and
        $recoveryDeltas['pnq'].monotonic -and
        $recoveryDeltas['prfut'].found -and
        $recoveryDeltas['prfut'].monotonic -and
        $recoveryDeltas['ppre'].found -and
        $recoveryDeltas['ppre'].monotonic -and
        [uint64]$recoveryDeltas['pnq'].delta -eq
          ([uint64]$recoveryDeltas['prfut'].delta +
           [uint64]$recoveryDeltas['ppre'].delta))
    })
    [uint64]$expectedRf22 = 0
    if ($recoveryDeltas['pnq'].found -and $recoveryDeltas['pnq'].monotonic) {
      $expectedRf22 = [uint64]$script:ExpectedParamCount +
          [uint64]$recoveryDeltas['pnq'].delta
      if ($ExpectedDiagnosticFaultMode -ceq 'FUTURE_INDEX_RECOVERY') {
        ++$expectedRf22
      }
    }
    $checks.Add([pscustomobject][ordered]@{
      name='ground_rf_param_values_recovery_exact';key='rf22'
      rule='932_plus_quarantine';expected=$expectedRf22
      actual=$recoveryDeltas['rf22'].delta
      valid=($recoveryDeltas['pnq'].found -and
        $recoveryDeltas['pnq'].monotonic -and
        $recoveryDeltas['rf22'].found -and
        $recoveryDeltas['rf22'].monotonic -and
        [uint64]$recoveryDeltas['rf22'].delta -eq $expectedRf22)
    })
    $baselineLatchTime = Get-SnapshotUInt64 -Snapshot $BaselineGround -Key 'ms'
    $postLatchTime = Get-SnapshotUInt64 -Snapshot $PostGround -Key 'ms'
