    $checks.Add([pscustomobject][ordered]@{
      name='ground_recovery_latch_time_inside_snapshot_interval';key='prlms'
      rule='baseline_ms<prlms<=post_ms';expected='inside interval'
      actual=$latchObservedTime.value
      valid=($baselineLatchTime.found -and $postLatchTime.found -and
        $latchObservedTime.found -and
