        expected='0/1/0/>=1'
        actual=[ordered]@{
          pvto=$recoveryDeltas['pvto'].delta
          prgap=$recoveryDeltas['prgap'].delta
          prto=$recoveryDeltas['prto'].delta
          prfut=$recoveryDeltas['prfut'].delta
        }
        valid=($recoveryDeltas['pvto'].delta -eq 0 -and
          $recoveryDeltas['prgap'].delta -eq 1 -and
          $recoveryDeltas['prto'].delta -eq 0 -and
          $recoveryDeltas['prfut'].delta -ge 1)
      })
      $checks.Add([pscustomobject][ordered]@{
        name='ground_future_recovery_latch_exact';key='prl*'
        rule='future_latch';expected='valid/reason1/future/count932/byte-seq'
        actual=[ordered]@{
          valid=$recoveryPost['prlv'].value;reason=$recoveryPost['prlr'].value
          expected_index=$recoveryPost['prlex'].value
          received_index=$recoveryPost['prlrx'].value
          received_count=$recoveryPost['prlcnt'].value
          received_sequence=$recoveryPost['prlseq'].value
        }
        valid=($expectedIndexValid -and
          $recoveryPost['prlv'].value -eq 1 -and
          $recoveryPost['prlr'].value -eq 1 -and
          [uint64]$recoveryPost['prlrx'].value -gt
            [uint64]$recoveryPost['prlex'].value -and
          [uint64]$recoveryPost['prlrx'].value -lt
            [uint64]$script:ExpectedParamCount -and
          [uint64]$recoveryPost['prlcnt'].value -eq
            [uint64]$script:ExpectedParamCount -and
          [uint64]$recoveryPost['prlseq'].value -le 255)
      })
    } else {
      [bool]$timeoutCountValid = ($expectedIndexValid -and
        (([uint64]$recoveryPost['prlex'].value -eq 0 -and
          ([uint64]$recoveryPost['prlcnt'].value -eq 0 -or
           [uint64]$recoveryPost['prlcnt'].value -eq
