         ([uint64]$recoveryPost['prlex'].value -gt 0 -and
          [uint64]$recoveryPost['prlcnt'].value -eq
            [uint64]$script:ExpectedParamCount)))
      $checks.Add([pscustomobject][ordered]@{
        name='ground_timeout_recovery_reason_counters_exact'
        key='pvto/prgap/prto';rule='timeout_exact';expected='1/0/1'
        actual=[ordered]@{
          pvto=$recoveryDeltas['pvto'].delta
          prgap=$recoveryDeltas['prgap'].delta
          prto=$recoveryDeltas['prto'].delta
        }
        valid=($recoveryDeltas['pvto'].delta -eq 1 -and
          $recoveryDeltas['prgap'].delta -eq 0 -and
          $recoveryDeltas['prto'].delta -eq 1)
