  $checks.Add([pscustomobject]@{
    name='ground_matching_USB_param_values_932';key='raw indexed #22'
    rule='exact_observed';expected=[uint64]932;actual=$MatchingUsbParamValues
    valid=($MatchingUsbParamValues -eq 932)
  })
  function Add-VehicleExactDelta {
    param([string]$Name, [string]$Key, [uint64]$Expected,
      [switch]$RequireAbsoluteZero)
    $delta = Get-VehicleVcstat3Delta -Baseline $BaselineVehicle `
        -Post $PostVehicle -Key $Key
    $checks.Add([pscustomobject][ordered]@{
      name=$Name;key=$Key
      rule=if ($RequireAbsoluteZero) {
        'exact_VCSTAT3_baseline_post_and_delta_zero'
      } else { 'exact_VCSTAT3_delta' }
      expected=$Expected
      actual=if ($RequireAbsoluteZero) {
        [ordered]@{before=$delta.before;after=$delta.after;delta=$delta.delta}
      } else { $delta.delta }
      valid=($delta.found -and $delta.monotonic -and
        [uint64]$delta.delta -eq $Expected -and
        (-not $RequireAbsoluteZero -or
         ($Expected -eq 0 -and [uint64]$delta.before -eq 0 -and
          [uint64]$delta.after -eq 0)))
    })
    return $delta
  }

  $nativeDeltas = [ordered]@{}
  foreach ($key in @(
      'd722','stqf','stdup','stsel','stchunk','stdone','strej',
      'snf','snbusy','sncf','sncsf','sncof','sncb','sncsb','sncob',
      'snff','snfsf','snfof','snftr','sncerr','snq','snseq')) {
    $nativeDeltas[$key] = Get-VehicleVcstat3Delta `
        -Baseline $BaselineVehicle -Post $PostVehicle -Key $key
  }
  $null = Add-VehicleExactDelta 'vehicle_native_fence_committed_once' `
      'snf' 1
  $null = Add-VehicleExactDelta 'vehicle_native_fence_busy_zero' `
      'snbusy' 0 -RequireAbsoluteZero
  $null = Add-VehicleExactDelta 'vehicle_native_frames_queued_exact' `
      'snq' 932
  $null = Add-VehicleExactDelta 'vehicle_native_sequence_failures_zero' `
      'snseq' 0 -RequireAbsoluteZero

  $sncf = $nativeDeltas['sncf']; $sncsf = $nativeDeltas['sncsf']
  $sncof = $nativeDeltas['sncof']; $sncb = $nativeDeltas['sncb']
  $sncsb = $nativeDeltas['sncsb']; $sncob = $nativeDeltas['sncob']
  $snff = $nativeDeltas['snff']; $snfsf = $nativeDeltas['snfsf']
  $snfof = $nativeDeltas['snfof']
