      $sncsf.monotonic -and $sncof.found -and $sncof.monotonic -and
      [decimal]$sncf.delta -eq
        ([decimal]$sncsf.delta + [decimal]$sncof.delta))
  })
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_native_cancel_byte_partition_exact';key='sncb==sncsb+sncob'
    rule='exact_partition';expected='sncb=sncsb+sncob'
    actual=[ordered]@{sncb=$sncb.delta;sncsb=$sncsb.delta;sncob=$sncob.delta}
    valid=($sncb.found -and $sncb.monotonic -and $sncsb.found -and
      $sncsb.monotonic -and $sncob.found -and $sncob.monotonic -and
      [decimal]$sncb.delta -eq
        ([decimal]$sncsb.delta + [decimal]$sncob.delta))
  })
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_native_stat_runtime_cancel_bytes_exact';key='sncsb==37*sncsf'
    rule='37_byte_exact_frame';expected='sncsb=37*sncsf'
    actual=[ordered]@{sncsb=$sncsb.delta;sncsf=$sncsf.delta}
    valid=($sncsb.found -and $sncsb.monotonic -and $sncsf.found -and
