  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_native_other_filtered_zero';key='snfof'
    rule='baseline_post_and_delta_zero';expected=[uint64]0
    actual=[ordered]@{before=$snfof.before;after=$snfof.after
      delta=$snfof.delta}
    valid=($snfof.found -and $snfof.monotonic -and
      [uint64]$snfof.before -eq 0 -and [uint64]$snfof.after -eq 0 -and
      [uint64]$snfof.delta -eq 0)
  })
  $sncerr = $nativeDeltas['sncerr']
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_native_classification_errors_zero';key='sncerr'
    rule='baseline_post_and_delta_zero';expected=[uint64]0
    actual=[ordered]@{before=$sncerr.before;after=$sncerr.after
      delta=$sncerr.delta}
    valid=($sncerr.found -and $sncerr.monotonic -and
      [uint64]$sncerr.before -eq 0 -and [uint64]$sncerr.after -eq 0 -and
