  $snftr = $nativeDeltas['snftr']
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_native_filter_time_regressions_zero';key='snftr'
    rule='baseline_post_and_delta_zero';expected=[uint64]0
    actual=[ordered]@{before=$snftr.before;after=$snftr.after
      delta=$snftr.delta}
    valid=($snftr.found -and $snftr.monotonic -and
      [uint64]$snftr.before -eq 0 -and [uint64]$snftr.after -eq 0 -and
      [uint64]$snftr.delta -eq 0)
  })

  $baselineFilterCount = Get-VehicleVcstat3UInt64 `
      -Snapshot $BaselineVehicle -Key 'snfsf'
  $baselineFirstFilter = Get-VehicleVcstat3UInt64 `
      -Snapshot $BaselineVehicle -Key 'snffm'
  $baselineLastFilter = Get-VehicleVcstat3UInt64 `
      -Snapshot $BaselineVehicle -Key 'snflm'
  $baselineMinimumGap = Get-VehicleVcstat3UInt64 `
      -Snapshot $BaselineVehicle -Key 'snfmg'
  $postFirstFilter = Get-VehicleVcstat3UInt64 `
      -Snapshot $PostVehicle -Key 'snffm'
  $postLastFilter = Get-VehicleVcstat3UInt64 `
      -Snapshot $PostVehicle -Key 'snflm'
  $postMinimumGap = Get-VehicleVcstat3UInt64 `
      -Snapshot $PostVehicle -Key 'snfmg'
  [bool]$cadenceEvidenceComplete = ($snfsf.found -and $snfsf.monotonic -and
      $baselineFilterCount.valid -and $baselineFirstFilter.valid -and
      $baselineLastFilter.valid -and $baselineMinimumGap.valid -and
      $postFirstFilter.valid -and $postLastFilter.valid -and
      $postMinimumGap.valid)
  [bool]$cleanCadenceBaseline = ($cadenceEvidenceComplete -and
      [uint64]$baselineFilterCount.value -eq 0 -and
      [uint64]$baselineFirstFilter.value -eq 0 -and
      [uint64]$baselineLastFilter.value -eq 0 -and
      [uint64]$baselineMinimumGap.value -eq 0)
  [bool]$filterCadenceValid = $false
  [uint64]$filteredCount = if ($snfsf.found -and $snfsf.monotonic) {
    [uint64]$snfsf.delta
  } else { [uint64]0 }
  if ($cleanCadenceBaseline) {
    [uint64]$firstMs = [uint64]$postFirstFilter.value
    [uint64]$lastMs = [uint64]$postLastFilter.value
    [uint64]$minimumGapMs = [uint64]$postMinimumGap.value
    [uint64]$baselineMs = [uint64]$BaselineVehicle.ms_uint64
    [uint64]$postMs = [uint64]$PostVehicle.ms_uint64
    if ($filteredCount -eq 0) {
      $filterCadenceValid = ($firstMs -eq 0 -and $lastMs -eq 0 -and
        $minimumGapMs -eq 0)
    } elseif ($filteredCount -eq 1) {
      $filterCadenceValid = ($firstMs -gt $baselineMs -and
        $firstMs -eq $lastMs -and $lastMs -le $postMs -and
        $minimumGapMs -eq 0)
    } else {
      $filterCadenceValid = ($firstMs -gt $baselineMs -and
        $firstMs -lt $lastMs -and $lastMs -le $postMs -and
        $minimumGapMs -gt 0 -and
        ([decimal]$minimumGapMs * ([decimal]$filteredCount - 1)) -le
          ([decimal]$lastMs - [decimal]$firstMs))
    }
  }
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_native_filter_timestamps_coherent';key='snfsf/snffm/snflm/snfmg'
    rule='count_conditional_absolute_cadence'
    expected='F0=zeros;F1=one in interval;F>=2=ordered positive feasible gap'
    actual=[ordered]@{filtered_count=$filteredCount
      first=$postFirstFilter.value;last=$postLastFilter.value
      minimum_gap=$postMinimumGap.value}
    valid=$filterCadenceValid
  })

  [string[]]$unexpectedNumericKeys = @(
    'snul','snur','snuv','snusg','snusz','snup','snusy','snucp','snusq',
    'snumask','snui','snuc','snut','snums')
  [bool]$unexpectedLatchClear = $true
  $unexpectedEvidence = [ordered]@{}
  foreach ($key in $unexpectedNumericKeys) {
    $before = Get-VehicleVcstat3UInt64 -Snapshot $BaselineVehicle -Key $key
    $after = Get-VehicleVcstat3UInt64 -Snapshot $PostVehicle -Key $key
    $unexpectedEvidence[$key] = [ordered]@{
      before=$before.value;after=$after.value
    }
    if (-not ($before.valid -and $after.valid -and
        [uint64]$before.value -eq 0 -and [uint64]$after.value -eq 0)) {
      $unexpectedLatchClear = $false
    }
