  $afterUnexpectedValue = Get-VehicleVcstat3String `
      -Snapshot $PostVehicle -Key 'snuval'
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_native_unexpected_value_hex8_zero';key='snuval'
    rule='baseline_and_post_fixed_hex_zero';expected='00000000'
    actual=[ordered]@{before=$beforeUnexpectedValue.value
      after=$afterUnexpectedValue.value}
    valid=($beforeUnexpectedValue.valid -and $afterUnexpectedValue.valid -and
