    valid=($beforeUnexpectedId.valid -and $afterUnexpectedId.valid -and
      [string]$beforeUnexpectedId.value -match '^[0-9A-Fa-f]{32}$' -and
      [string]$afterUnexpectedId.value -match '^[0-9A-Fa-f]{32}$' -and
      [string]$beforeUnexpectedId.value -ceq
        '00000000000000000000000000000000' -and
      [string]$afterUnexpectedId.value -ceq
        '00000000000000000000000000000000')
  })

  [uint64]$expectedTargetResponses = 0
  [bool]$targetExpectationDefined = ($nativeStreamPath -ceq 'NORMAL')
  if ($nativeStreamPath -ceq 'FUTURE_INDEX_RECOVERY' -or
      $nativeStreamPath -ceq 'INTER_VALUE_TIMEOUT_RECOVERY') {
    $recoveryExpectedIndexReading = $recoveryPost['prlex']
    if ($recoveryExpectedIndexReading.found -and
        [uint64]$recoveryExpectedIndexReading.value -lt
          [uint64]$script:ExpectedParamCount) {
      $expectedTargetResponses = [uint64]$script:ExpectedParamCount -
          [uint64]$recoveryExpectedIndexReading.value
      $targetExpectationDefined = $true
    }
  }
  $targetQueued = $nativeDeltas['stqf']
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_target_frames_queued_exact';key='stqf'
    rule='exact_recovery_target_delta';expected=$expectedTargetResponses
    actual=$targetQueued.delta
    valid=($targetExpectationDefined -and $targetQueued.found -and
      $targetQueued.monotonic -and
      [uint64]$targetQueued.delta -eq $expectedTargetResponses)
  })
  $targetSelected = $nativeDeltas['stsel']
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_target_selections_exact';key='stsel'
    rule='exact_recovery_target_delta';expected=$expectedTargetResponses
    actual=$targetSelected.delta
    valid=($targetExpectationDefined -and $targetSelected.found -and
      $targetSelected.monotonic -and
      [uint64]$targetSelected.delta -eq $expectedTargetResponses)
  })
  [uint64]$expectedTargetChunks = [uint64](2 * $expectedTargetResponses)
  $targetChunks = $nativeDeltas['stchunk']
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_target_chunks_exact';key='stchunk'
    rule='two_chunks_per_target_frame';expected=$expectedTargetChunks
    actual=$targetChunks.delta
    valid=($targetExpectationDefined -and $targetChunks.found -and
      $targetChunks.monotonic -and
