  $targetCompleted = $nativeDeltas['stdone']
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_target_frames_completed_exact';key='stdone'
    rule='exact_recovery_target_delta';expected=$expectedTargetResponses
    actual=$targetCompleted.delta
    valid=($targetExpectationDefined -and $targetCompleted.found -and
      $targetCompleted.monotonic -and
