    rule='baseline_post_and_delta_zero';expected=[uint64]0
    actual=[ordered]@{before=$targetRejected.before
      after=$targetRejected.after;delta=$targetRejected.delta}
    valid=($targetRejected.found -and $targetRejected.monotonic -and
      [uint64]$targetRejected.before -eq 0 -and
      [uint64]$targetRejected.after -eq 0 -and
      [uint64]$targetRejected.delta -eq 0)
  })
  $d722 = $nativeDeltas['d722']; $snq = $nativeDeltas['snq']
  $stqf = $nativeDeltas['stqf']
  $checks.Add([pscustomobject][ordered]@{
    name='vehicle_d7_param_value_full_partition_exact'
    key='d722==sncf+snff+snq+stqf';rule='exact_partition'
    expected='d722=sncf+snff+snq+stqf'
    actual=[ordered]@{d722=$d722.delta;sncf=$sncf.delta
      snff=$snff.delta;snq=$snq.delta;stqf=$stqf.delta}
    valid=($d722.found -and $d722.monotonic -and $sncf.found -and
      $sncf.monotonic -and $snff.found -and $snff.monotonic -and
      $snq.found -and $snq.monotonic -and $stqf.found -and
      $stqf.monotonic -and [decimal]$d722.delta -eq
        ([decimal]$sncf.delta + [decimal]$snff.delta +
         [decimal]$snq.delta + [decimal]$stqf.delta))
  })
  foreach ($postHealth in @(
      @('ground_ready_post', $PostGround, 'ready', [uint64]1),
      @('ground_fail_post', $PostGround, 'fail', [uint64]0),
      @('ground_runtime_stop_post', $PostGround, 'rse', [uint64]0),
      @('vehicle_ready_post', $PostVehicle, 'r', [uint64]1),
      @('vehicle_fail_post', $PostVehicle, 'f', [uint64]0),
      @('proxy_watchdog_reason_none', $PostGround, 'pwr', [uint64]0))) {
    $healthValue = Get-SnapshotUInt64 -Snapshot $postHealth[1] `
        -Key ([string]$postHealth[2])
    $checks.Add([pscustomobject]@{
      name=[string]$postHealth[0];key=[string]$postHealth[2]
      rule='post_exact';expected=[uint64]$postHealth[3]
      actual=$healthValue.value
      valid=($healthValue.found -and
        [uint64]$healthValue.value -eq [uint64]$postHealth[3])
    })
  }
  foreach ($postExact in @(
      @('proxy_complete_state', 'pst', [uint64]4),
      @('proxy_mode_native', 'pmode', [uint64]1),
      @('proxy_not_active', 'pact', [uint64]0),
      @('proxy_last_index', 'pidx', [uint64]931),
      @('proxy_count', 'pcnt', [uint64]932),
      @('proxy_admission_idle', 'padm', [uint64]0),
      @('proxy_dequeue_idle', 'pdeq', [uint64]0))) {
    $actual = Get-SnapshotUInt64 -Snapshot $PostGround -Key ([string]$postExact[1])
    $checks.Add([pscustomobject]@{
      name=[string]$postExact[0]; key=[string]$postExact[1]
      rule='post_exact'; expected=[uint64]$postExact[2]; actual=$actual.value
      valid=($actual.found -and [uint64]$actual.value -eq [uint64]$postExact[2])
    })
  }
  foreach ($key in @('ucr','uiv','udf','udb','uoe','urc','uic','dli','dlo',
      'upinv','epinv','rfinv','obif','obof','hd','dnak','xnak','inak',
      'pwto','psfail','prej','pwe')) {
    $delta = Get-SnapshotDelta -Baseline $BaselineGround -Post $PostGround `
        -Key $key
    $before = Get-SnapshotUInt64 -Snapshot $BaselineGround -Key $key
    $after = Get-SnapshotUInt64 -Snapshot $PostGround -Key $key
    $checks.Add([pscustomobject]@{
      name=('ground_error_delta_zero_' + $key);key=$key
      rule='baseline_post_and_delta_zero'
      valid=($delta.monotonic -and $before.found -and $after.found -and
        [uint64]$before.value -eq 0 -and [uint64]$after.value -eq 0 -and
        [uint64]$delta.delta -eq 0)
    })
  }
  foreach ($key in @('cc','rcr','riv','ocr','oiv','eiv','eov','out',
      'd6cr','d7cr','pvbad','pvov','eo','sc','evo')) {
    $delta = Get-SnapshotDelta -Baseline $BaselineVehicle -Post $PostVehicle `
        -Key $key
    $before = Get-SnapshotUInt64 -Snapshot $BaselineVehicle -Key $key
    $after = Get-SnapshotUInt64 -Snapshot $PostVehicle -Key $key
    $checks.Add([pscustomobject]@{
      name=('vehicle_error_delta_zero_' + $key);key=$key
      rule='baseline_post_and_delta_zero'
      valid=($delta.monotonic -and $before.found -and $after.found -and
        [uint64]$before.value -eq 0 -and [uint64]$after.value -eq 0 -and
        [uint64]$delta.delta -eq 0)
    })
  }

  [bool]$directedFutureRequested =
      $ExpectedDiagnosticFaultMode -ceq 'FUTURE_INDEX_RECOVERY'
  if ($directedFutureRequested) {
    $checks.Add([pscustomobject][ordered]@{
      name='directed_future_path_exact';key='native_stream_path'
      rule='exact';expected='FUTURE_INDEX_RECOVERY';actual=$nativeStreamPath
      valid=($nativeStreamPath -ceq 'FUTURE_INDEX_RECOVERY')
    })

    $directedLatchExpected = [ordered]@{
      expected_index=[uint64]$ExpectedDiagnosticFaultDropIndex
      received_index=[uint64]($ExpectedDiagnosticFaultDropIndex + 1)
      received_count=[uint64]$script:ExpectedParamCount
      reason=[uint64]1
    }
    $directedLatchActual = [ordered]@{
      expected_index=$recoveryPost['prlex'].value
      received_index=$recoveryPost['prlrx'].value
      received_count=$recoveryPost['prlcnt'].value
      reason=$recoveryPost['prlr'].value
    }
    $checks.Add([pscustomobject][ordered]@{
      name='directed_future_latch_exact';key='prlex/prlrx/prlcnt/prlr'
      rule='exact';expected=$directedLatchExpected;actual=$directedLatchActual
      valid=($recoveryPost['prlex'].found -and
        $recoveryPost['prlrx'].found -and $recoveryPost['prlcnt'].found -and
        $recoveryPost['prlr'].found -and
        [uint64]$recoveryPost['prlex'].value -eq
          [uint64]$ExpectedDiagnosticFaultDropIndex -and
        [uint64]$recoveryPost['prlrx'].value -eq
          [uint64]($ExpectedDiagnosticFaultDropIndex + 1) -and
        [uint64]$recoveryPost['prlcnt'].value -eq
          [uint64]$script:ExpectedParamCount -and
        [uint64]$recoveryPost['prlr'].value -eq [uint64]1)
    })

    $directedFutureExactDeltas = [ordered]@{
      pvto=[uint64]0;prgap=[uint64]1;prto=[uint64]0;prfut=[uint64]1
      ppre=[uint64]0;pnq=[uint64]1;prold=[uint64]0
    }
    foreach ($key in $directedFutureExactDeltas.Keys) {
      $delta = $recoveryDeltas[$key]
      [uint64]$expected = [uint64]$directedFutureExactDeltas[$key]
      $checks.Add([pscustomobject][ordered]@{
        name=('directed_future_' + $key + '_delta_exact');key=$key
        rule='exact_delta';expected=$expected;actual=$delta.delta
        valid=($delta.found -and $delta.monotonic -and
          [uint64]$delta.delta -eq $expected)
      })
    }

    [uint64]$directedFutureMissingTail =
        [uint64]$script:ExpectedParamCount -
        [uint64]$ExpectedDiagnosticFaultDropIndex
    foreach ($key in @('prq','prtx','prv','prusb','pgen')) {
      $delta = $recoveryDeltas[$key]
      $checks.Add([pscustomobject][ordered]@{
        name=('directed_future_' + $key + '_missing_tail_exact');key=$key
        rule='exact_missing_tail';expected=$directedFutureMissingTail
        actual=$delta.delta
        valid=($delta.found -and $delta.monotonic -and
          [uint64]$delta.delta -eq $directedFutureMissingTail)
      })
    }
    foreach ($spec in @(
        @('ptx','directed_future_ptx_native_plus_tail_exact'),
        @('deq','directed_future_deq_native_plus_tail_exact'))) {
      [string]$key = [string]$spec[0]
      $delta = $recoveryDeltas[$key]
      [uint64]$expected = [uint64](1 + $directedFutureMissingTail)
      $checks.Add([pscustomobject][ordered]@{
        name=[string]$spec[1];key=$key;rule='native_plus_missing_tail'
        expected=$expected;actual=$delta.delta
        valid=($delta.found -and $delta.monotonic -and
          [uint64]$delta.delta -eq $expected)
      })
    }
    [uint64]$directedExpectedRf22 =
        [uint64]$script:ExpectedParamCount +
        [uint64]$directedFutureExactDeltas['pnq'] + [uint64]1
    $directedRf22 = $recoveryDeltas['rf22']
    $checks.Add([pscustomobject][ordered]@{
      name='directed_future_rf22_exact';key='rf22'
      rule='932_plus_one_future_quarantine_plus_one_recovered_drop'
      expected=$directedExpectedRf22;actual=$directedRf22.delta
      valid=($directedRf22.found -and $directedRf22.monotonic -and
        [uint64]$directedRf22.delta -eq $directedExpectedRf22)
    })
  }

  [object[]]$directedFutureChecks = @($checks | Where-Object {
      $_.name -like 'directed_future_*'
    })
  [object[]]$failedDirectedFutureChecks = @($directedFutureChecks |
      Where-Object {-not $_.valid})
  $diagnosticFaultExpectation = [ordered]@{
    requested=$directedFutureRequested;mode=$ExpectedDiagnosticFaultMode
    index=[uint64]$ExpectedDiagnosticFaultDropIndex
    macro='VC_LORA_HIL_DROP_NATIVE_PARAM_INDEX_930'
    expected_future_index=[uint64]($ExpectedDiagnosticFaultDropIndex + 1)
    expected_missing_tail=[uint64]($script:ExpectedParamCount -
        $ExpectedDiagnosticFaultDropIndex)
    exact_check_count=$directedFutureChecks.Count
    failed_check_count=$failedDirectedFutureChecks.Count
    verified_exact=($directedFutureRequested -and
      $directedFutureChecks.Count -eq 17 -and
      $failedDirectedFutureChecks.Count -eq 0)
  }
  $postContractResult = [ordered]@{
    valid=@($checks | Where-Object {-not $_.valid}).Count -eq 0
    failed_count=@($checks | Where-Object {-not $_.valid}).Count
    first_failed=if (@($checks | Where-Object {-not $_.valid}).Count -gt 0) {
      @($checks | Where-Object {-not $_.valid})[0].name
    } else { $null }
    native_stream_path=$nativeStreamPath
    recovery_evidence=[ordered]@{
      complete=$recoveryEvidenceComplete;deltas=$recoveryDeltas;post=$recoveryPost
    }
    checks=$checks.ToArray()
  }
  if ($directedFutureRequested) {
    $postContractResult['diagnostic_fault_expectation'] =
        $diagnosticFaultExpectation
  }
  return [pscustomobject]$postContractResult
}

function Update-X25Crc {
  param(
    [Parameter(Mandatory = $true)][int]$Crc,
    [Parameter(Mandatory = $true)][byte]$Value
  )
  [int]$temporary = ([int]$Value -bxor ($Crc -band 0xFF))
  $temporary = ($temporary -bxor (($temporary -shl 4) -band 0xFF)) `
      -band 0xFF
  return ((($Crc -shr 8) -bxor ($temporary -shl 8) -bxor
      ($temporary -shl 3) -bxor ($temporary -shr 4)) -band 0xFFFF)
}

function Get-MavlinkCrc {
  param(
    [Parameter(Mandatory = $true)][byte[]]$Bytes,
    [Parameter(Mandatory = $true)][int]$Start,
    [Parameter(Mandatory = $true)][int]$Count,
    [Parameter(Mandatory = $true)][byte]$Extra
  )
  [int]$crc = 0xFFFF
  for ($index = 0; $index -lt $Count; ++$index) {
    $crc = Update-X25Crc -Crc $crc -Value $Bytes[$Start + $index]
  }
  return (Update-X25Crc -Crc $crc -Value $Extra)
}

function Test-MavlinkFrameCrc {
  param([byte[]]$Frame, [byte]$Extra)
  if ($Frame.Length -lt 8) { return $false }
  [int]$headerLength = if ($Frame[0] -eq 0xFD) {
    10
  } elseif ($Frame[0] -eq 0xFE) {
    6
  } else {
    return $false
  }
  [int]$checksumIndex = $headerLength + [int]$Frame[1]
  if ($checksumIndex + 1 -ge $Frame.Length) { return $false }
  [int]$crc = Get-MavlinkCrc -Bytes $Frame -Start 1 `
      -Count ($checksumIndex - 1) -Extra $Extra
  return ($Frame[$checksumIndex] -eq ($crc -band 0xFF) -and
      $Frame[$checksumIndex + 1] -eq (($crc -shr 8) -band 0xFF))
}

function Get-UInt16Le {
  param([byte[]]$Bytes, [int]$Offset)
  return [uint16]([int]$Bytes[$Offset] -bor
      ([int]$Bytes[$Offset + 1] -shl 8))
}

function Import-MavlinkDefinitions {
  param([Parameter(Mandatory = $true)][string]$Path)
  if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
    throw "MAVLink definition source is missing: $Path"
  }
  [string]$actualSha = (Get-FileHash -Algorithm SHA256 `
      -LiteralPath $Path).Hash
  if ($actualSha -ne $script:CanonicalDefinitionsSha256) {
    throw "Canonical MAVLink definitions SHA mismatch: $actualSha"
  }
  [string]$source = [System.IO.File]::ReadAllText($Path)
  $matches = [regex]::Matches($source,
      '\{\s*(\d+)U\s*,\s*(\d+)U\s*,\s*(\d+)U\s*,\s*(\d+)U\s*\}')
  $definitions = @{}
  foreach ($match in $matches) {
    [int]$messageId = [int]$match.Groups[1].Value
    $definitions[$messageId] = [pscustomobject][ordered]@{
      message_id = $messageId
      crc_extra = [byte][int]$match.Groups[2].Value
      minimum_payload_length = [int]$match.Groups[3].Value
      maximum_payload_length = [int]$match.Groups[4].Value
    }
  }
  if ($matches.Count -ne 80 -or $definitions.Count -ne 80 -or
      -not $definitions.ContainsKey(0) -or
      $definitions[0].crc_extra -ne 50 -or
      -not $definitions.ContainsKey(21) -or
      $definitions[21].crc_extra -ne 159 -or
      -not $definitions.ContainsKey(22) -or
      $definitions[22].crc_extra -ne 220) {
    throw 'Authoritative canonical80 MAVLink definitions are incomplete.'
  }
  return [pscustomobject][ordered]@{
    path = (Resolve-Path -LiteralPath $Path).Path
    sha256 = $actualSha
    count = $definitions.Count
    definition_count = 80
    definitions = $definitions
  }
}

function Test-ExactRequestFixture {
  param([Parameter(Mandatory = $true)][byte[]]$Bytes)
  $errors = New-Object 'System.Collections.Generic.List[string]'
  [string]$hex = ConvertTo-Hex -Bytes $Bytes
  [string]$sha = Get-BytesSha256 -Bytes $Bytes
  if ($Bytes.Length -ne 14) {
    $errors.Add("length=$($Bytes.Length), expected=14")
  }
  if ($hex -ne $script:ExpectedFixtureHex) {
    $errors.Add("hex=$hex, expected=$($script:ExpectedFixtureHex)")
  }
  if ($sha -ne $script:ExpectedFixtureSha256) {
    $errors.Add("sha256=$sha, expected=$($script:ExpectedFixtureSha256)")
  }
  if ($Bytes.Length -ge 14) {
    [int]$messageId = [int]$Bytes[7] -bor
        ([int]$Bytes[8] -shl 8) -bor ([int]$Bytes[9] -shl 16)
    if ($Bytes[0] -ne 0xFD -or $Bytes[1] -ne 2 -or
        $Bytes[2] -ne 0 -or $Bytes[3] -ne 0) {
      $errors.Add('fixture must be an unsigned MAVLink2 frame with payload length 2')
    }
    if ($Bytes[4] -ne 99 -or $Bytes[5] -ne 255 -or
        $Bytes[6] -ne 190) {
      $errors.Add('fixture sequence/source must be 99/255/190')
    }
    if ($messageId -ne 21) {
      $errors.Add("message_id=$messageId, expected PARAM_REQUEST_LIST #21")
    }
    if ($Bytes[10] -ne 1 -or $Bytes[11] -ne 1) {
      $errors.Add('fixture target must be 1/1')
    }
    if (-not (Test-MavlinkFrameCrc -Frame $Bytes -Extra 159)) {
      $errors.Add('fixture CRC is invalid for CRC extra 159')
    }
  }
  return [pscustomobject][ordered]@{
    valid = ($errors.Count -eq 0)
    size_bytes = $Bytes.Length
    hex = $hex
    sha256 = $sha
    message_id = 21
    sequence = 99
    source_system = 255
    source_component = 190
    target_system = 1
    target_component = 1
    crc_extra = 159
    errors = $errors.ToArray()
  }
}

function New-Mavlink2TestFrame {
  param(
    [Parameter(Mandatory = $true)][int]$MessageId,
    [Parameter(Mandatory = $true)][AllowEmptyCollection()][byte[]]$Payload,
    [Parameter(Mandatory = $true)][byte]$CrcExtra,
    [byte]$Sequence = 1,
    [byte]$SystemId = 1,
    [byte]$ComponentId = 1
  )
  [byte[]]$frame = New-Object byte[] (12 + $Payload.Length)
  $frame[0] = 0xFD
  $frame[1] = [byte]$Payload.Length
  $frame[2] = 0
  $frame[3] = 0
  $frame[4] = $Sequence
  $frame[5] = $SystemId
  $frame[6] = $ComponentId
  $frame[7] = [byte]($MessageId -band 0xFF)
  $frame[8] = [byte](($MessageId -shr 8) -band 0xFF)
  $frame[9] = [byte](($MessageId -shr 16) -band 0xFF)
  [Array]::Copy($Payload, 0, $frame, 10, $Payload.Length)
  [int]$crc = Get-MavlinkCrc -Bytes $frame -Start 1 `
      -Count (9 + $Payload.Length) -Extra $CrcExtra
  $frame[10 + $Payload.Length] = [byte]($crc -band 0xFF)
  $frame[11 + $Payload.Length] = [byte](($crc -shr 8) -band 0xFF)
  return $frame
}

function New-ParamValuePayload {
  param(
    [Parameter(Mandatory = $true)][AllowEmptyString()][string]$ParamId,
    [Parameter(Mandatory = $true)][int]$Index,
    [int]$Count = 932,
    [byte]$Type = 6
  )
  [byte[]]$payload = New-Object byte[] 25
  [uint32]$valueBits = [uint32]$Index
  $payload[0] = [byte]($valueBits -band 0xFF)
  $payload[1] = [byte](($valueBits -shr 8) -band 0xFF)
  $payload[2] = [byte](($valueBits -shr 16) -band 0xFF)
  $payload[3] = [byte](($valueBits -shr 24) -band 0xFF)
  $payload[4] = [byte]($Count -band 0xFF)
  $payload[5] = [byte](($Count -shr 8) -band 0xFF)
  $payload[6] = [byte]($Index -band 0xFF)
  $payload[7] = [byte](($Index -shr 8) -band 0xFF)
  [byte[]]$idBytes = [System.Text.Encoding]::ASCII.GetBytes($ParamId)
  [Array]::Copy($idBytes, 0, $payload, 8, [Math]::Min(16, $idBytes.Length))
  $payload[24] = $Type
  return $payload
}

function New-ParamListState {
  param(
    [ValidateSet('pre_request_readiness','pre_request_m0','official',
        'post_cutoff')]
    [string]$CaptureScope = 'official',
    [ValidateRange(1, 65536)]
    [int]$MaxEventCount = $script:MaxParamValueEvidenceEvents
  )
  [bool[]]$seen = New-Object bool[] $script:ExpectedParamCount
  return [pscustomobject][ordered]@{
    capture_scope = $CaptureScope
    max_event_count = $MaxEventCount
    first_anomaly = $null
    expected_param_count = 932
    expected_last_index = 931
    expected_source_system = 1
    expected_source_component = 1
    strict_ascending = $true
    next_expected_index = 0
    indexed_frame_count = [uint64]0
    unique_count = [uint64]0
    duplicate_count = [uint64]0
    missing_count = [uint64]932
    out_of_order_count = [uint64]0
    out_of_range_count = [uint64]0
    count_mismatch_count = [uint64]0
    wrong_source_count = [uint64]0
    bad_payload_length_count = [uint64]0
    invalid_param_id_count = [uint64]0
    duplicate_param_id_count = [uint64]0
    unique_param_id_count = [uint64]0
    invalid_param_type_count = [uint64]0
    known_stat_runtime_sentinel_count = [uint64]0
    unknown_sentinel_count = [uint64]0
    extra_param_value_count = [uint64]0
    first_index = $null
    last_index = $null
    last_accepted_elapsed_ms = $null
    completion_elapsed_ms = $null
    seen = $seen
    param_id_seen = @{}
    events = New-Object 'System.Collections.Generic.List[object]'
  }
}

function Register-ParamListAnomaly {
  param(
    [Parameter(Mandatory = $true)]$State,
    [Parameter(Mandatory = $true)][System.Collections.IDictionary]$Event,
    [Parameter(Mandatory = $true)][string]$AnomalyClass
  )
  $Event['anomaly_classes'] = @($Event['anomaly_classes']) + $AnomalyClass
  if ($null -eq $State.first_anomaly) {
    $State.first_anomaly = [pscustomobject][ordered]@{
      anomaly_class=$AnomalyClass
      elapsed_ms=$Event['elapsed_ms']
      raw_start_offset=$Event['raw_start_offset']
      raw_end_offset_exclusive=$Event['raw_end_offset_exclusive']
      sequence=$Event['sequence']
      param_index=if($Event.Contains('param_index')){$Event['param_index']}else{$null}
      param_id=if($Event.Contains('param_id')){$Event['param_id']}else{$null}
      capture_scope=[string]$State.capture_scope
    }
  }
}

function Add-ParamListEventEvidence {
  param(
    [Parameter(Mandatory = $true)]$State,
    [Parameter(Mandatory = $true)]$Event
  )
  if ($State.events.Count -ge [int]$State.max_event_count) {
    throw ('PARAM_VALUE evidence event cap {0} exceeded; refusing truncation' -f
      [int]$State.max_event_count)
  }
  $State.events.Add([pscustomobject]$Event)
}

function Test-ParamIdBytes {
  param([Parameter(Mandatory = $true)][byte[]]$IdBytes)
  [bool]$sawTerminator = $false
  [int]$textLength = 0
  foreach ($value in $IdBytes) {
    if ($value -eq 0) {
      $sawTerminator = $true
      continue
    }
    if ($sawTerminator -or $value -lt 0x20 -or $value -gt 0x7E) {
      return $false
    }
    ++$textLength
  }
  return ($textLength -gt 0)
}

function Add-ParamValuePayload {
  param(
    [Parameter(Mandatory = $true)]$State,
    [Parameter(Mandatory = $true)][byte[]]$Payload,
    [Parameter(Mandatory = $true)][int]$SystemId,
    [Parameter(Mandatory = $true)][int]$ComponentId,
    [Parameter(Mandatory = $true)][int]$Sequence,
    [Parameter(Mandatory = $true)][double]$ElapsedMs,
    [long]$RawStartOffset = -1,
    [long]$RawEndOffsetExclusive = -1,
    [string]$ProducerPhase = '',
    [string]$ProducerEpoch = ''
  )
  $event = [ordered]@{
    message_id = 22
    crc_valid = $true
    sequence = $Sequence
    system_id = $SystemId
    component_id = $ComponentId
    payload_length = $Payload.Length
    payload_hex = ConvertTo-Hex -Bytes $Payload
    elapsed_ms = [Math]::Round($ElapsedMs, 3)
    raw_start_offset = $RawStartOffset
    raw_end_offset_exclusive = $RawEndOffsetExclusive
    capture_scope = [string]$State.capture_scope
    producer_phase = if([string]::IsNullOrEmpty($ProducerPhase)){
      [string]$script:CurrentPhase
    }else{$ProducerPhase}
    producer_epoch = if([string]::IsNullOrEmpty($ProducerEpoch)){
      [string]$script:CurrentPhase
    }else{$ProducerEpoch}
    classification = 'unclassified'
    anomaly_classes = @()
  }
  [string]$paramValueHex = $null
  if ($Payload.Length -ge 4) {
    [uint32]$paramValueBits = ([uint32]$Payload[0] -bor
        ([uint32]$Payload[1] -shl 8) -bor
        ([uint32]$Payload[2] -shl 16) -bor
        ([uint32]$Payload[3] -shl 24))
    $paramValueHex = $paramValueBits.ToString('X8')
  }
  # Add-ParamValuePayload is reached only after Complete-MavlinkCandidate has
  # accepted the frame CRC.  Retain both the explicit CRC fact and the exact
  # IEEE754 wire bits so a bounded pre-M0 event can be correlated with pvval.
  $event.param_value_hex = $paramValueHex
  $event.param_value_bits_hex = $paramValueHex
  if ($SystemId -ne 1 -or $ComponentId -ne 1) {
    ++$State.wrong_source_count
    ++$State.extra_param_value_count
    $event.classification = 'wrong_source'
    Register-ParamListAnomaly -State $State -Event $event `
        -AnomalyClass 'wrong_source'
    Add-ParamListEventEvidence -State $State -Event $event
    return
  }
  if ($Payload.Length -ne 25) {
    ++$State.bad_payload_length_count
    ++$State.extra_param_value_count
    $event.classification = 'bad_payload_length'
    Register-ParamListAnomaly -State $State -Event $event `
        -AnomalyClass 'bad_payload_length'
    Add-ParamListEventEvidence -State $State -Event $event
    return
  }
  [int]$count = Get-UInt16Le -Bytes $Payload -Offset 4
  [int]$index = Get-UInt16Le -Bytes $Payload -Offset 6
  [byte[]]$idBytes = New-Object byte[] 16
  [Array]::Copy($Payload, 8, $idBytes, 0, 16)
  [string]$idHex = ConvertTo-Hex -Bytes $idBytes
  [string]$id = [System.Text.Encoding]::ASCII.GetString($idBytes).TrimEnd([char]0)
  [int]$type = $Payload[24]
  $event.param_count = $count
  $event.param_index = $index
  $event.param_id = $id
  $event.param_id_hex = $idHex
  $event.param_type = $type

  if ($index -eq 0xFFFF) {
    if ($idHex -eq $script:ExpectedStatRuntimeIdHex -and
        $id -eq 'STAT_RUNTIME' -and $count -eq 932 -and $type -eq 6) {
      ++$State.known_stat_runtime_sentinel_count
      $event.classification = 'known_STAT_RUNTIME_sentinel'
    } else {
      ++$State.unknown_sentinel_count
      ++$State.extra_param_value_count
      $event.classification = 'unknown_sentinel'
      Register-ParamListAnomaly -State $State -Event $event `
          -AnomalyClass 'unknown_sentinel'
    }
    Add-ParamListEventEvidence -State $State -Event $event
    return
  }

  ++$State.indexed_frame_count
  $event.classification = 'indexed'
  if ($State.first_index -eq $null) { $State.first_index = $index }
  $State.last_index = $index
  if ($count -ne 932) {
    ++$State.count_mismatch_count
    Register-ParamListAnomaly -State $State -Event $event `
        -AnomalyClass 'count_mismatch'
  }
  if ($index -lt 0 -or $index -gt 931) {
    ++$State.out_of_range_count
    ++$State.extra_param_value_count
    $State.strict_ascending = $false
    Register-ParamListAnomaly -State $State -Event $event `
        -AnomalyClass 'out_of_range'
  } else {
    if (-not (Test-ParamIdBytes -IdBytes $idBytes)) {
      ++$State.invalid_param_id_count
      Register-ParamListAnomaly -State $State -Event $event `
          -AnomalyClass 'invalid_param_id'
    } elseif ($State.param_id_seen.ContainsKey($id)) {
      ++$State.duplicate_param_id_count
      Register-ParamListAnomaly -State $State -Event $event `
          -AnomalyClass 'duplicate_param_id'
    } else {
      $State.param_id_seen[$id] = $true
      ++$State.unique_param_id_count
    }
    if ($type -lt 1 -or $type -gt 10) {
      ++$State.invalid_param_type_count
      Register-ParamListAnomaly -State $State -Event $event `
          -AnomalyClass 'invalid_param_type'
    }
    if ($State.seen[$index]) {
      ++$State.duplicate_count
      ++$State.extra_param_value_count
      $State.strict_ascending = $false
      Register-ParamListAnomaly -State $State -Event $event `
          -AnomalyClass 'duplicate_index'
    } else {
      $State.seen[$index] = $true
      ++$State.unique_count
      if ($index -ne $State.next_expected_index) {
        ++$State.out_of_order_count
        $State.strict_ascending = $false
        Register-ParamListAnomaly -State $State -Event $event `
            -AnomalyClass 'out_of_order'
      } else {
        ++$State.next_expected_index
        $State.last_accepted_elapsed_ms = $ElapsedMs
        if ($index -eq 931) { $State.completion_elapsed_ms = $ElapsedMs }
      }
    }
  }
  $State.missing_count = [uint64](932 - [int]$State.unique_count)
  Add-ParamListEventEvidence -State $State -Event $event
}

function Complete-ParamListAssessment {
  param([Parameter(Mandatory = $true)]$State)
  $State.missing_count = [uint64](932 - [int]$State.unique_count)
  [bool]$valid = ($State.indexed_frame_count -eq 932 -and
      $State.unique_count -eq 932 -and $State.missing_count -eq 0 -and
      $State.first_index -eq 0 -and $State.last_index -eq 931 -and
      $State.next_expected_index -eq 932 -and $State.strict_ascending -and
      $State.duplicate_count -eq 0 -and
      $State.out_of_order_count -eq 0 -and
      $State.out_of_range_count -eq 0 -and
      $State.count_mismatch_count -eq 0 -and
      $State.wrong_source_count -eq 0 -and
      $State.bad_payload_length_count -eq 0 -and
      $State.invalid_param_id_count -eq 0 -and
      $State.duplicate_param_id_count -eq 0 -and
      $State.unique_param_id_count -eq 932 -and
      $State.invalid_param_type_count -eq 0 -and
      $State.unknown_sentinel_count -eq 0 -and
      $State.extra_param_value_count -eq 0)
  return [pscustomobject][ordered]@{
    valid = $valid
    expected_param_count = 932
    expected_last_index = 931
    expected_source_system = 1
    expected_source_component = 1
    indexed_frame_count = $State.indexed_frame_count
    unique_count = $State.unique_count
    missing_count = $State.missing_count
    duplicate_count = $State.duplicate_count
    out_of_order_count = $State.out_of_order_count
    out_of_range_count = $State.out_of_range_count
    count_mismatch_count = $State.count_mismatch_count
    wrong_source_count = $State.wrong_source_count
    bad_payload_length_count = $State.bad_payload_length_count
    invalid_param_id_count = $State.invalid_param_id_count
    duplicate_param_id_count = $State.duplicate_param_id_count
    unique_param_ids = $State.unique_param_id_count
    invalid_param_type_count = $State.invalid_param_type_count
    known_stat_runtime_sentinel_count = `
        $State.known_stat_runtime_sentinel_count
    unknown_sentinel_count = $State.unknown_sentinel_count
    extra_param_value_count = $State.extra_param_value_count
    first_index = $State.first_index
    last_index = $State.last_index
    next_expected_index = $State.next_expected_index
    strict_ascending = $State.strict_ascending
    completion_elapsed_ms = $State.completion_elapsed_ms
    first_anomaly = $State.first_anomaly
    event_count = $State.events.Count
    max_event_count = $State.max_event_count
  }
}

function Get-ProxyTerminalClassification {
  param([AllowNull()]$PostGround)
  $pst = Get-SnapshotUInt64 -Snapshot $PostGround -Key 'pst'
  $pact = Get-SnapshotUInt64 -Snapshot $PostGround -Key 'pact'
  [string]$classification = 'Unavailable'
  if ($null -ne $PostGround -and $PostGround.status -eq 'COMPLETE' -and
      $pst.found -and $pact.found) {
    if ([uint64]$pst.value -eq 4 -and [uint64]$pact.value -eq 0) {
      $classification = 'Complete'
    } elseif ([uint64]$pst.value -eq 5 -and [uint64]$pact.value -eq 0) {
      $classification = 'Failed'
    } elseif ([uint64]$pst.value -eq 0 -and [uint64]$pact.value -eq 0) {
      $classification = 'Idle'
    } else {
      $classification = 'ActiveOrNonterminal'
    }
  }
  return [pscustomobject][ordered]@{
    classification=$classification;snapshot_status=if($null -ne $PostGround){
      $PostGround.status
    }else{'NOT_RUN'}
    pst=$pst.value;pact=$pact.value
  }
}

function New-ParamListDiagnosticEvidence {
  param(
    [AllowNull()]$BacklogDrainGate,
    [AllowNull()]$BaselinePairGate,
    [AllowNull()]$BaselineSetup,
    [AllowNull()]$PreRequestPairGate,
    [AllowNull()]$PreRequestVehicleGate,
    [AllowNull()]$PreRequestBacklogGate,
    [AllowNull()]$M0,
    [AllowNull()]$M1,
    [AllowEmptyString()][string]$StopReason = 'not_run',
    [AllowNull()]$OfficialState,
    [AllowNull()]$OfficialAssessment,
    [AllowNull()]$ParserIntegrity,
    [AllowNull()]$HeartbeatMetrics,
    [AllowNull()]$PostCutoffState,
    [AllowNull()]$PostGround,
    [AllowNull()]$PostAssessment,
    [AllowNull()]$PostDiagnosticPlan,
    [AllowNull()]$SyncInvalidContinuation
  )
  [object[]]$officialEvents = [object[]]@()
  if ($null -ne $OfficialState) {
    $officialEvents = [object[]]$OfficialState.events.ToArray()
  }
  [object[]]$postCutoffEvents = [object[]]@()
  if ($null -ne $PostCutoffState) {
    $postCutoffEvents = [object[]]$PostCutoffState.events.ToArray()
  }
  return [pscustomobject][ordered]@{
    schema_version=1
    backlog_drain_gate=$BacklogDrainGate
    baseline_pair_gate=$BaselinePairGate
    baseline_setup=$BaselineSetup
    pre_request_pair_gate=$PreRequestPairGate
    pre_request_vehicle_gate=$PreRequestVehicleGate
    pre_request_backlog_gate=$PreRequestBacklogGate
    official=[ordered]@{
      m0=$M0;m1=$M1;stop_reason=$StopReason;cutoff_reason=$StopReason
      cutoff_elapsed_ms=if($null -ne $M1){$M1.elapsed_ms}else{$null}
      cutoff_ground_raw_offset=if($null -ne $M1){
        $M1.ground_raw_offset
      }else{$null}
      event_count=@($officialEvents).Count
      first_anomaly=if($null -ne $OfficialState){
        $OfficialState.first_anomaly
      }else{$null}
      assessment=$OfficialAssessment
      parser_integrity=$ParserIntegrity
      heartbeat=$HeartbeatMetrics
      events=$officialEvents
    }
    post_cutoff=[ordered]@{
      event_count=@($postCutoffEvents).Count;events=$postCutoffEvents
    }
    proxy_terminal=Get-ProxyTerminalClassification -PostGround $PostGround
    post_proxy_assessment=$PostAssessment
    post_diagnostic_plan=$PostDiagnosticPlan
    sync_invalid_continuation=$SyncInvalidContinuation
  }
}

function New-MavlinkParserState {
  param([Parameter(Mandatory = $true)][hashtable]$Definitions)
  return [pscustomobject][ordered]@{
    Buffer = New-Object 'System.Collections.Generic.List[byte]'
    ExpectedLength = 0
    StartOffset = [long]-1
    Enabled = $true
    Definitions = $Definitions
    ValidEvents = New-Object 'System.Collections.Generic.List[object]'
    HeartbeatEvents = New-Object 'System.Collections.Generic.List[object]'
    ParamList = New-ParamListState
    Unsupported = [uint64]0
    UnsupportedFlags = [uint64]0
    BadPayloadLength = [uint64]0
    BadCrc = [uint64]0
    NoiseBytes = [uint64]0
    InvalidLength = [uint64]0
  }
}

function Clear-MavlinkCandidate {
  param($Parser)
  $Parser.Buffer.Clear()
  $Parser.ExpectedLength = 0
  $Parser.StartOffset = [long]-1
}

function Reset-MavlinkAnalysis {
  param($Parser)
  Clear-MavlinkCandidate -Parser $Parser
  $Parser.ValidEvents.Clear()
  $Parser.HeartbeatEvents.Clear()
  $Parser.ParamList = New-ParamListState
  $Parser.Unsupported = [uint64]0
  $Parser.UnsupportedFlags = [uint64]0
  $Parser.BadPayloadLength = [uint64]0
  $Parser.BadCrc = [uint64]0
  $Parser.NoiseBytes = [uint64]0
  $Parser.InvalidLength = [uint64]0
}

function Disable-AndResetMavlinkAnalysis {
  param([Parameter(Mandatory = $true)]$Parser)
  [void](Set-ReaderCaptureContext -Phase ([string]$script:CurrentPhase) `
      -Epoch 'parser_disabled')
  $Parser.Enabled = $false
  Reset-MavlinkAnalysis -Parser $Parser
  return [pscustomobject][ordered]@{
    disabled=(-not $Parser.Enabled)
    buffer_empty=($Parser.Buffer.Count -eq 0)
    expected_length_zero=($Parser.ExpectedLength -eq 0)
  }
}

function Complete-MavlinkCandidate {
  param($Parser, [long]$EndOffsetExclusive, [double]$ElapsedMs,
        [string]$ProducerPhase = '', [string]$ProducerEpoch = '')
  [byte[]]$frame = $Parser.Buffer.ToArray()
  [int]$headerLength = if ($frame[0] -eq 0xFD) { 10 } else { 6 }
  [int]$payloadLength = $frame[1]
  [int]$messageId = 0
  [int]$sequence = 0
  [int]$systemId = 0
  [int]$componentId = 0
  if ($frame[0] -eq 0xFD) {
    $messageId = [int]$frame[7] -bor ([int]$frame[8] -shl 8) -bor
        ([int]$frame[9] -shl 16)
    $sequence = $frame[4]
    $systemId = $frame[5]
    $componentId = $frame[6]
  } else {
    $messageId = $frame[5]
    $sequence = $frame[2]
    $systemId = $frame[3]
    $componentId = $frame[4]
  }
  $definition = $null
  if ($Parser.Definitions.ContainsKey($messageId)) {
    $definition = $Parser.Definitions[$messageId]
  }
  if ($null -eq $definition) {
    ++$Parser.Unsupported
  } elseif ($frame[0] -eq 0xFD -and
      ($frame[2] -ne 0 -or $frame[3] -ne 0)) {
    ++$Parser.UnsupportedFlags
  } elseif ($payloadLength -lt $definition.minimum_payload_length -or
      $payloadLength -gt $definition.maximum_payload_length -or
      ($frame[0] -eq 0xFE -and
       $payloadLength -ne $definition.minimum_payload_length)) {
    ++$Parser.BadPayloadLength
  } elseif (-not (Test-MavlinkFrameCrc -Frame $frame `
      -Extra ([byte]$definition.crc_extra))) {
    ++$Parser.BadCrc
  } else {
    [byte[]]$payload = New-Object byte[] $payloadLength
    if ($payloadLength -gt 0) {
      [Array]::Copy($frame, $headerLength, $payload, 0, $payloadLength)
    }
    $event = [pscustomobject][ordered]@{
      message_id = $messageId
      crc_valid = $true
      sequence = $sequence
      system_id = $systemId
      component_id = $componentId
      payload_length = $payloadLength
      payload_hex = ConvertTo-Hex -Bytes $payload
      frame_version = if ($frame[0] -eq 0xFD) { 2 } else { 1 }
      signed = ($frame[0] -eq 0xFD -and ($frame[2] -band 1) -ne 0)
      elapsed_ms = [Math]::Round($ElapsedMs, 3)
      raw_start_offset = $Parser.StartOffset
      raw_end_offset_exclusive = $EndOffsetExclusive
      phase = if([string]::IsNullOrEmpty($ProducerPhase)){
        [string]$script:CurrentPhase
      }else{$ProducerPhase}
      producer_epoch = if([string]::IsNullOrEmpty($ProducerEpoch)){
        [string]$script:CurrentPhase
      }else{$ProducerEpoch}
    }
    $Parser.ValidEvents.Add($event)
    if ($messageId -eq 0 -and $systemId -eq 1 -and $componentId -eq 1) {
      $Parser.HeartbeatEvents.Add($event)
    }
    if ($messageId -eq 22) {
      Add-ParamValuePayload -State $Parser.ParamList -Payload $payload `
          -SystemId $systemId -ComponentId $componentId `
          -Sequence $sequence -ElapsedMs $ElapsedMs `
          -RawStartOffset $Parser.StartOffset `
          -RawEndOffsetExclusive $EndOffsetExclusive `
          -ProducerPhase $ProducerPhase -ProducerEpoch $ProducerEpoch
    }
  }
  Clear-MavlinkCandidate -Parser $Parser
}

function Add-MavlinkAnalysisByte {
  param(
    [Parameter(Mandatory = $true)]$Parser,
    [Parameter(Mandatory = $true)][byte]$Byte,
    [Parameter(Mandatory = $true)][long]$RawOffset,
    [Parameter(Mandatory = $true)][double]$ElapsedMs,
    [string]$ProducerPhase = '',
    [string]$ProducerEpoch = ''
  )
  if (-not $Parser.Enabled) { return }
  if ($Parser.Buffer.Count -eq 0) {
    if ($Byte -eq 0xFD -or $Byte -eq 0xFE) {
      $Parser.StartOffset = $RawOffset
      $Parser.Buffer.Add($Byte)
    } else {
      ++$Parser.NoiseBytes
    }
    return
  }
  $Parser.Buffer.Add($Byte)
  if ($Parser.Buffer.Count -eq 2 -and $Parser.Buffer[0] -eq 0xFE) {
    $Parser.ExpectedLength = 8 + [int]$Parser.Buffer[1]
  } elseif ($Parser.Buffer.Count -eq 3 -and $Parser.Buffer[0] -eq 0xFD) {
    [int]$signatureLength = if (($Parser.Buffer[2] -band 1) -ne 0) {
      13
    } else { 0 }
    $Parser.ExpectedLength = 12 + [int]$Parser.Buffer[1] + $signatureLength
  }
  if ($Parser.ExpectedLength -gt 300 -or $Parser.Buffer.Count -gt 300) {
    ++$Parser.InvalidLength
    Clear-MavlinkCandidate -Parser $Parser
  } elseif ($Parser.ExpectedLength -gt 0 -and
      $Parser.Buffer.Count -eq $Parser.ExpectedLength) {
    Complete-MavlinkCandidate -Parser $Parser `
        -EndOffsetExclusive ($RawOffset + 1) -ElapsedMs $ElapsedMs `
        -ProducerPhase $ProducerPhase -ProducerEpoch $ProducerEpoch
  }
}

function Get-ParserIntegrity {
  param([Parameter(Mandatory = $true)]$Parser)
  [bool]$valid = ($Parser.Unsupported -eq 0 -and
      $Parser.UnsupportedFlags -eq 0 -and
      $Parser.BadPayloadLength -eq 0 -and $Parser.BadCrc -eq 0 -and
      $Parser.NoiseBytes -eq 0 -and $Parser.InvalidLength -eq 0 -and
      $Parser.Buffer.Count -eq 0 -and $Parser.ExpectedLength -eq 0)
  return [pscustomobject][ordered]@{
    valid = $valid
    unsupported = $Parser.Unsupported
    unsupported_flags = $Parser.UnsupportedFlags
    bad_payload_length = $Parser.BadPayloadLength
    bad_crc = $Parser.BadCrc
    noise_bytes = $Parser.NoiseBytes
    invalid_length = $Parser.InvalidLength
    partial_buffer_bytes = $Parser.Buffer.Count
    expected_length = $Parser.ExpectedLength
  }
}

function Get-HeartbeatWindowMetrics {
  param(
    [Parameter(Mandatory = $true)][System.Collections.IEnumerable]$Events,
    [Parameter(Mandatory = $true)][double]$M0ElapsedMs,
    [Parameter(Mandatory = $true)][double]$M1ElapsedMs,
    [double]$MaximumGapMs = 2500.0
  )
  $heartbeats = @($Events | Where-Object {
      $_.message_id -eq 0 -and $_.system_id -eq 1 -and
      $_.component_id -eq 1 -and
      [double]$_.elapsed_ms -ge $M0ElapsedMs -and
      [double]$_.elapsed_ms -le $M1ElapsedMs
    } | Sort-Object { [double]$_.elapsed_ms })
  $gaps = New-Object 'System.Collections.Generic.List[object]'
  if ($heartbeats.Count -gt 0) {
    $gaps.Add([pscustomobject][ordered]@{
      kind = 'edge_from_M0'
      gap_ms = [double]$heartbeats[0].elapsed_ms - $M0ElapsedMs
    })
    for ($index = 1; $index -lt $heartbeats.Count; ++$index) {
      $gaps.Add([pscustomobject][ordered]@{
        kind = 'consecutive'
        gap_ms = [double]$heartbeats[$index].elapsed_ms -
            [double]$heartbeats[$index - 1].elapsed_ms
      })
    }
    $gaps.Add([pscustomobject][ordered]@{
      kind = 'tail_to_M1'
      gap_ms = $M1ElapsedMs - [double]$heartbeats[-1].elapsed_ms
    })
  }
  $exceedances = @($gaps | Where-Object {
      [double]$_.gap_ms -gt $MaximumGapMs })
  [double]$maximum = 0.0
  if ($gaps.Count -gt 0) {
    $maximum = [double](($gaps | Measure-Object -Property gap_ms -Maximum).Maximum)
  }
  return [pscustomobject][ordered]@{
    valid = ($heartbeats.Count -ge 2 -and $exceedances.Count -eq 0)
    source_system = 1
    source_component = 1
    heartbeat_max_gap_ms = 2500
    count = $heartbeats.Count
    first_edge_ms = if ($gaps.Count -gt 0) { $gaps[0].gap_ms } else { $null }
    maximum_gap_ms = if ($gaps.Count -gt 0) { $maximum } else { $null }
    tail_edge_ms = if ($gaps.Count -gt 0) { $gaps[-1].gap_ms } else { $null }
    gaps = $gaps.ToArray()
    exceedance_count = $exceedances.Count
  }
}

function New-HeartbeatWindowAccumulator {
  param(
    [Parameter(Mandatory = $true)][double]$M0ElapsedMs,
    [double]$MaximumGapMs = 2500.0
  )
  return [pscustomobject][ordered]@{
    m0_elapsed_ms = $M0ElapsedMs
    maximum_gap_ms = $MaximumGapMs
    next_event_index = [int]0
    count = [int]0
    first_elapsed_ms = $null
    last_elapsed_ms = $null
    first_edge_ms = $null
    maximum_closed_gap_ms = [double]0.0
    closed_exceedance_count = [int]0
    closed_gaps = New-Object 'System.Collections.Generic.List[object]'
    last_update_elapsed_ms = $M0ElapsedMs
  }
}

function Update-HeartbeatWindowAccumulator {
  param(
    [Parameter(Mandatory = $true)]$State,
    [Parameter(Mandatory = $true)][System.Collections.IList]$Events,
    [Parameter(Mandatory = $true)][double]$ThroughElapsedMs
  )
  if ($ThroughElapsedMs -lt [double]$State.last_update_elapsed_ms) {
    throw 'Heartbeat accumulator update time moved backwards.'
  }
  if ($Events.Count -lt [int]$State.next_event_index) {
    throw 'Heartbeat accumulator source history was truncated.'
  }
  while ([int]$State.next_event_index -lt $Events.Count) {
    $event = $Events[[int]$State.next_event_index]
    [double]$eventElapsedMs = [double]$event.elapsed_ms
    if ($eventElapsedMs -gt $ThroughElapsedMs) { break }
    ++$State.next_event_index
    if ($event.message_id -ne 0 -or $event.system_id -ne 1 -or
        $event.component_id -ne 1 -or
        $eventElapsedMs -lt [double]$State.m0_elapsed_ms) {
      continue
    }
    [string]$gapKind = 'edge_from_M0'
    [double]$gapMs = $eventElapsedMs - [double]$State.m0_elapsed_ms
    if ([int]$State.count -gt 0) {
      if ($eventElapsedMs -lt [double]$State.last_elapsed_ms) {
        throw 'Heartbeat accumulator event time moved backwards.'
      }
      $gapKind = 'consecutive'
      $gapMs = $eventElapsedMs - [double]$State.last_elapsed_ms
    } else {
      $State.first_elapsed_ms = $eventElapsedMs
      $State.first_edge_ms = $gapMs
    }
    $State.closed_gaps.Add([pscustomobject][ordered]@{
      kind = $gapKind
      gap_ms = $gapMs
    })
    if ($gapMs -gt [double]$State.maximum_closed_gap_ms) {
      $State.maximum_closed_gap_ms = $gapMs
    }
    if ($gapMs -gt [double]$State.maximum_gap_ms) {
      ++$State.closed_exceedance_count
    }
    ++$State.count
    $State.last_elapsed_ms = $eventElapsedMs
  }
  $State.last_update_elapsed_ms = $ThroughElapsedMs
}

function Get-HeartbeatWindowAccumulatorSnapshot {
  param(
    [Parameter(Mandatory = $true)]$State,
    [Parameter(Mandatory = $true)][double]$M1ElapsedMs,
    [switch]$IncludeGaps
  )
  if ($M1ElapsedMs -lt [double]$State.last_update_elapsed_ms) {
    throw 'Heartbeat accumulator snapshot precedes its last update.'
  }
  [double]$maximum = [double]$State.maximum_closed_gap_ms
  [double]$tailEdgeMs = 0.0
  [int]$exceedanceCount = [int]$State.closed_exceedance_count
  [object[]]$gapArray = @()
  if ([int]$State.count -gt 0) {
    $tailEdgeMs = $M1ElapsedMs - [double]$State.last_elapsed_ms
    if ($tailEdgeMs -lt 0.0) {
      throw 'Heartbeat accumulator tail edge is negative.'
    }
    if ($tailEdgeMs -gt $maximum) { $maximum = $tailEdgeMs }
    if ($tailEdgeMs -gt [double]$State.maximum_gap_ms) {
      ++$exceedanceCount
    }
    if ($IncludeGaps.IsPresent) {
      [object[]]$closedGapArray = [object[]]$State.closed_gaps.ToArray()
      $gapArray = New-Object object[] ($closedGapArray.Length + 1)
      if ($closedGapArray.Length -gt 0) {
        [Array]::Copy($closedGapArray, 0, $gapArray, 0,
            $closedGapArray.Length)
      }
      $gapArray[$closedGapArray.Length] = [pscustomobject][ordered]@{
        kind = 'tail_to_M1'
        gap_ms = $tailEdgeMs
      }
    }
  }
  return [pscustomobject][ordered]@{
    valid = ([int]$State.count -ge 2 -and $exceedanceCount -eq 0)
    source_system = 1
    source_component = 1
    heartbeat_max_gap_ms = 2500
    count = [int]$State.count
    first_edge_ms = if ([int]$State.count -gt 0) {
      [double]$State.first_edge_ms
    } else { $null }
    maximum_gap_ms = if ([int]$State.count -gt 0) { $maximum } else { $null }
    tail_edge_ms = if ([int]$State.count -gt 0) { $tailEdgeMs } else { $null }
    gaps = $gapArray
    exceedance_count = $exceedanceCount
  }
}

function Get-DataPlaneReadinessWindowDecision {
  param(
    [Parameter(Mandatory = $true)][double]$GateStartedElapsedMs,
    [Parameter(Mandatory = $true)][double]$CurrentElapsedMs,
    [Parameter(Mandatory = $true)][int]$TimeoutSeconds
  )
  [double]$deadlineMs = $GateStartedElapsedMs +
      ([double]$TimeoutSeconds * 1000.0)
  [double]$remainingMs = $deadlineMs - $CurrentElapsedMs
  [double]$requiredRemainingMs = 5000.0 +
      [double]$script:ReadinessVehicleBReserveMs
  return [pscustomobject][ordered]@{
    gate_started_elapsed_ms=$GateStartedElapsedMs
    deadline_elapsed_ms=$deadlineMs
    current_elapsed_ms=$CurrentElapsedMs
    remaining_ms=$remainingMs
    required_remaining_ms=$requiredRemainingMs
    vehicle_B_reserve_ms=[double]$script:ReadinessVehicleBReserveMs
    can_start_full_window=($remainingMs -ge $requiredRemainingMs)
    timed_out=($remainingMs -lt $requiredRemainingMs)
  }
}

function Get-DeadlineBoundSnapshotBudget {
  param(
    [Parameter(Mandatory = $true)][double]$CurrentElapsedMs,
    [Parameter(Mandatory = $true)][double]$DeadlineElapsedMs,
    [Parameter(Mandatory = $true)][double]$ConfiguredTimeoutSeconds,
    [Parameter(Mandatory = $true)][double]$ReserveAfterMs
  )
  [double]$configuredTimeoutMs = $ConfiguredTimeoutSeconds * 1000.0
  [double]$availableMs = $DeadlineElapsedMs - $CurrentElapsedMs -
      $ReserveAfterMs
  [double]$budgetMs = [Math]::Min($configuredTimeoutMs,
      [Math]::Max(0.0, $availableMs))
  return [pscustomobject][ordered]@{
    current_elapsed_ms=$CurrentElapsedMs
    deadline_elapsed_ms=$DeadlineElapsedMs
    reserve_after_ms=$ReserveAfterMs
    configured_timeout_ms=$configuredTimeoutMs
    available_ms=$availableMs;budget_ms=$budgetMs
    query_deadline_elapsed_ms=$CurrentElapsedMs + $budgetMs
    can_query=($budgetMs -gt 0.0)
  }
}

function Get-DeadlineBoundWritePlan {
  param(
    [Parameter(Mandatory = $true)][double]$RemainingMs,
    [Parameter(Mandatory = $true)][double]$ConfiguredWriteTimeoutMs,
    [Parameter(Mandatory = $true)][double]$MarginMs
  )
  [double]$availableBeforeMarginMs = [Math]::Max(0.0,
      $RemainingMs - $MarginMs)
  [double]$wholeMillisecondBudget = [Math]::Floor(
      $availableBeforeMarginMs)
  [double]$writeTimeoutMs = [Math]::Min($ConfiguredWriteTimeoutMs,
      $wholeMillisecondBudget)
  return [pscustomobject][ordered]@{
    remaining_ms=$RemainingMs;configured_write_timeout_ms=$ConfiguredWriteTimeoutMs
    margin_ms=$MarginMs;available_before_margin_ms=$availableBeforeMarginMs
    write_timeout_ms=$writeTimeoutMs;can_write=($writeTimeoutMs -ge 1.0)
    base_stream_flush_allowed=$false
  }
}

function Get-VehiclePartialUsbWakeDecision {
  param(
    [Parameter(Mandatory = $true)][bool]$AllowVehiclePartialUsbWake,
    [Parameter(Mandatory = $true)][string]$Role,
    [Nullable[uint32]]$ExpectedQ,
    [Parameter(Mandatory = $true)][int]$QueryCount,
    [Parameter(Mandatory = $true)][int]$QueryAttemptCount,
    [Parameter(Mandatory = $true)][bool]$WriteTimedOut,
    [Parameter(Mandatory = $true)][bool]$ReportComplete,
    [AllowNull()]$PreQueryMatcherSnapshot,
    [AllowNull()]$CurrentMatcherSnapshot,
    [Parameter(Mandatory = $true)][int]$StartLineIndex,
    [Parameter(Mandatory = $true)][long]$StartRawOffset,
    [Parameter(Mandatory = $true)][double]$LastRawProgressElapsedMs,
    [Parameter(Mandatory = $true)][double]$CurrentElapsedMs,
    [Parameter(Mandatory = $true)][int]$WakeAttemptCount,
    [Parameter(Mandatory = $true)][double]$EffectiveDeadlineElapsedMs
  )
  [bool]$expectedQPresent = ($null -ne $ExpectedQ -and
      [uint32]$ExpectedQ -ne [uint32]0)
  [bool]$roleExact = ($Role -ceq 'vehicle')
  [bool]$queryExact = ($QueryCount -eq 1 -and
      $QueryAttemptCount -eq 1 -and -not $WriteTimedOut)
  [bool]$attemptAvailable = ($WakeAttemptCount -eq 0 -and
      $WakeAttemptCount -lt $script:VehiclePartialUsbWakeMaxAttempts)
  [bool]$preMatcherPresent = ($null -ne $PreQueryMatcherSnapshot)
  [bool]$currentMatcherPresent = ($null -ne $CurrentMatcherSnapshot)
  [bool]$preMatcherClean = ($preMatcherPresent -and
      [string]$PreQueryMatcherSnapshot.role -ceq 'vehicle' -and
      [long]$PreQueryMatcherSnapshot.pending_byte_count -eq 0 -and
      [string]$PreQueryMatcherSnapshot.pending_bytes_hex -ceq '' -and
      [long]$PreQueryMatcherSnapshot.pending_start_offset -eq -1 -and
      [long]$PreQueryMatcherSnapshot.tagged_line_count -eq $StartLineIndex -and
      [long]$PreQueryMatcherSnapshot.raw_bytes -eq $StartRawOffset)
  [bool]$overflowExact = ($preMatcherPresent -and $currentMatcherPresent -and
      [uint64]$CurrentMatcherSnapshot.overflow_count -eq
        [uint64]$PreQueryMatcherSnapshot.overflow_count)
  [bool]$taggedLineExact = ($currentMatcherPresent -and
      [string]$CurrentMatcherSnapshot.role -ceq 'vehicle' -and
      [long]$CurrentMatcherSnapshot.tagged_line_count -eq $StartLineIndex)
  [int]$pendingByteCount = if ($currentMatcherPresent) {
    [int]$CurrentMatcherSnapshot.pending_byte_count
  } else { 0 }
  [string]$pendingHex = if ($currentMatcherPresent) {
    [string]$CurrentMatcherSnapshot.pending_bytes_hex
  } else { '' }
  [byte[]]$pendingBytes = [byte[]]@()
  [bool]$pendingHexValid = $false
  if ($pendingByteCount -gt 0 -and
      $pendingHex -cmatch '^(?:[0-9A-Fa-f]{2})+$') {
    try {
      $pendingBytes = ConvertFrom-Hex -Hex $pendingHex
      $pendingHexValid = ($pendingBytes.Length -eq $pendingByteCount)
    } catch {
      $pendingBytes = [byte[]]@()
      $pendingHexValid = $false
    }
  }
  [bool]$pendingPrintable = $pendingHexValid
  if ($pendingPrintable) {
    foreach ($pendingByte in $pendingBytes) {
      if ($pendingByte -lt [byte]0x20 -or $pendingByte -gt [byte]0x7E) {
        $pendingPrintable = $false
        break
      }
    }
  }
  [bool]$pendingStartExact = ($currentMatcherPresent -and
      [long]$CurrentMatcherSnapshot.pending_start_offset -eq $StartRawOffset)
  [bool]$rawContiguous = ($currentMatcherPresent -and
      [long]$CurrentMatcherSnapshot.raw_bytes -eq
        ($StartRawOffset + [long]$pendingByteCount))
  [string]$pendingText = if ($pendingPrintable) {
    [Text.Encoding]::ASCII.GetString($pendingBytes)
  } else { '' }
  [string]$expectedQText = if ($expectedQPresent) {
    ([uint32]$ExpectedQ).ToString(
      [Globalization.CultureInfo]::InvariantCulture)
  } else { '' }
  [string]$canonicalPrefixPattern =
      '\AVCSTAT1 q=' + [regex]::Escape($expectedQText) +
      ' ms=[0-9]+ v=6 boot=[0-9]+ ss=[0-9]+ sf=[0-9]+ r=[0-9]+' +
      ' f=[0-9]+ st=[0-9]+ sid=[0-9]+ cy=[0-9]+ aux=[0-9]+' +
      ' rb=[0-9]+ ew=[0-9]+ ef=[0-9]+ gr=[0-9]+ ' +
      '(?:d(?:o(?:n(?:e(?:=[0-9]*)?)?)?)?)?\z'
  [bool]$prefixExact = ($pendingPrintable -and $expectedQPresent -and
      $pendingText -cmatch $canonicalPrefixPattern)
  [double]$stallMs = [Math]::Max(0.0,
      $CurrentElapsedMs - $LastRawProgressElapsedMs)
  [bool]$stallReached = ($stallMs -ge
      $script:VehiclePartialUsbWakeStallMs)
  [double]$remainingMs = [Math]::Max(0.0,
      $EffectiveDeadlineElapsedMs - $CurrentElapsedMs)
  $writePlan = Get-DeadlineBoundWritePlan -RemainingMs $remainingMs `
      -ConfiguredWriteTimeoutMs $script:VehiclePartialUsbWakeWriteTimeoutMs `
      -MarginMs $script:SnapshotWriteDeadlineMarginMs
  [bool]$deadlineExact = ($remainingMs -ge
      $script:VehiclePartialUsbWakeMinimumRemainingMs -and
      [bool]$writePlan.can_write -and
      [double]$writePlan.write_timeout_ms -eq
        $script:VehiclePartialUsbWakeWriteTimeoutMs -and
      -not [bool]$writePlan.base_stream_flush_allowed)
  [bool]$eligible = ($AllowVehiclePartialUsbWake -and $roleExact -and
      $expectedQPresent -and $queryExact -and -not $ReportComplete -and
      $attemptAvailable -and $preMatcherClean -and $overflowExact -and
      $taggedLineExact -and $pendingPrintable -and $pendingStartExact -and
      $rawContiguous -and $prefixExact -and $stallReached -and $deadlineExact)
  [string]$reason = if (-not $AllowVehiclePartialUsbWake) {
    'not_opted_in'
  } elseif (-not $roleExact) {
    'wrong_role'
  } elseif (-not $expectedQPresent) {
    'missing_expected_q'
  } elseif (-not $queryExact) {
    'query_not_exact'
  } elseif ($ReportComplete) {
    'report_complete'
  } elseif (-not $attemptAvailable) {
    'attempt_exhausted'
  } elseif (-not $preMatcherClean) {
    'pre_query_matcher_dirty'
  } elseif (-not $overflowExact) {
    'matcher_overflow_changed'
  } elseif (-not $taggedLineExact) {
    'tagged_line_progress'
  } elseif (-not $pendingPrintable) {
    'pending_not_printable'
  } elseif (-not $pendingStartExact -or -not $rawContiguous) {
    'raw_not_contiguous'
  } elseif (-not $prefixExact) {
    'prefix_not_exact'
  } elseif (-not $stallReached) {
    'stall_below_threshold'
  } elseif (-not $deadlineExact) {
    'insufficient_deadline'
  } else { 'eligible' }
  return [pscustomobject][ordered]@{
    eligible=$eligible;reason=$reason
    allow_vehicle_partial_usb_wake=$AllowVehiclePartialUsbWake
    role=$Role;role_exact=$roleExact;expected_q=$ExpectedQ
    expected_q_present=$expectedQPresent;query_exact=$queryExact
    report_complete=$ReportComplete;wake_attempt_count=$WakeAttemptCount
    attempt_available=$attemptAvailable;pre_query_matcher_clean=$preMatcherClean
    overflow_exact=$overflowExact;tagged_line_exact=$taggedLineExact
    pending_byte_count=$pendingByteCount;pending_bytes_hex=$pendingHex
    pending_sha256=if($pendingHexValid){
      Get-BytesSha256 -Bytes $pendingBytes
    }else{$null}
    pending_printable=$pendingPrintable;pending_start_exact=$pendingStartExact
    raw_contiguous=$rawContiguous;canonical_prefix_exact=$prefixExact
    start_line_index=$StartLineIndex;start_raw_offset=$StartRawOffset
    last_raw_progress_elapsed_ms=$LastRawProgressElapsedMs
    current_elapsed_ms=$CurrentElapsedMs;stall_ms=$stallMs
    stall_threshold_ms=$script:VehiclePartialUsbWakeStallMs
    effective_deadline_elapsed_ms=$EffectiveDeadlineElapsedMs
    remaining_ms=$remainingMs
    minimum_remaining_ms=$script:VehiclePartialUsbWakeMinimumRemainingMs
    wake_byte_hex=(ConvertTo-Hex -Bytes $script:VehiclePartialUsbWakeByte)
    max_attempts=$script:VehiclePartialUsbWakeMaxAttempts
    write_plan=$writePlan
  }
}

function Test-ReadinessSnapshotResponse {
  param(
    [Parameter(Mandatory = $true)]$Snapshot,
    [Nullable[uint32]]$ExpectedQ = $null
  )
  $statusProperty = $Snapshot.PSObject.Properties['status']
  $queryCountProperty = $Snapshot.PSObject.Properties['query_count']
  $queryAttemptCountProperty = `
      $Snapshot.PSObject.Properties['query_attempt_count']
  $writeTimedOutProperty = $Snapshot.PSObject.Properties['write_timed_out']
  $qProperty = $Snapshot.PSObject.Properties['q_uint32']
  [string]$status = if ($null -ne $statusProperty) {
    [string]$statusProperty.Value
  } else { '' }
  [int]$queryCount = if ($null -ne $queryCountProperty) {
    [int]$queryCountProperty.Value
  } else { 0 }
  [int]$queryAttemptCount = if ($null -ne $queryAttemptCountProperty) {
    [int]$queryAttemptCountProperty.Value
  } else { 0 }
  [bool]$writeTimedOut = if ($null -ne $writeTimedOutProperty) {
    [bool]$writeTimedOutProperty.Value
  } else { $true }
  [bool]$qPresent = ($null -ne $qProperty -and $null -ne $qProperty.Value)
  [Nullable[uint32]]$actualQ = $null
  if ($qPresent) { $actualQ = [uint32]$qProperty.Value }
  [bool]$expectedQExact = $qPresent
  if ($null -ne $ExpectedQ) {
    $expectedQExact = ($qPresent -and
        [uint32]$actualQ -eq [uint32]$ExpectedQ)
  }
  [bool]$valid = ($status -eq 'COMPLETE' -and $queryCount -eq 1 -and
      -not $writeTimedOut -and $qPresent -and $expectedQExact)
  return [pscustomobject][ordered]@{
    status=$status;query_count=$queryCount
    query_attempt_count=$queryAttemptCount;write_timed_out=$writeTimedOut
    q_present=$qPresent;q_uint32=$actualQ;expected_q=$ExpectedQ
    expected_q_exact=$expectedQExact;valid=$valid
    raw_rx_start_offset=if($null -ne
        $Snapshot.PSObject.Properties['raw_rx_start_offset']){
      [long]$Snapshot.raw_rx_start_offset
    }else{[long]-1}
    raw_rx_end_offset=if($null -ne
        $Snapshot.PSObject.Properties['raw_rx_end_offset']){
      [long]$Snapshot.raw_rx_end_offset
    }else{[long]-1}
  }
}

function Select-LatestCompleteDiagnosticSnapshot {
  param(
    [AllowNull()]$CurrentSnapshot,
    [AllowNull()]$CandidateSnapshot
  )
  if ($null -eq $CandidateSnapshot) { return $CurrentSnapshot }
  $candidateResponse = Test-ReadinessSnapshotResponse `
      -Snapshot $CandidateSnapshot
  if ($candidateResponse.valid) { return $CandidateSnapshot }
  return $CurrentSnapshot
}

function Get-BacklogSnapshotRecoveryDisposition {
  param(
    [Parameter(Mandatory = $true)]$Response,
    [Parameter(Mandatory = $true)][int]$AttemptNumber,
    [int]$MaxAttempts = 3,
    [Parameter(Mandatory = $true)][bool]$RetryBudgetAvailable,
    [Parameter(Mandatory = $true)]$MatcherBefore,
    [Parameter(Mandatory = $true)]$MatcherAfter,
    [bool]$AllowUnanchoredGroundRecovery = $false,
    [Parameter(Mandatory = $true)][ValidateSet('vehicle','ground')]
      [string]$Role,
    [Nullable[uint32]]$ExpectedQ = $null,
    [int]$UnexpectedTaggedRowCount = 0,
    [bool]$RecoveryAlreadyUsed = $false
  )
  [bool]$overflowStable = ([uint64]$MatcherAfter.overflow_count -eq
      [uint64]$MatcherBefore.overflow_count)
  [bool]$pendingEligible = ([int]$MatcherAfter.pending_byte_count -eq 0)
  [bool]$pendingOwnRole = $false
  [bool]$pendingQExact = $false
  [bool]$pendingQPresent = $false
  [Nullable[uint32]]$pendingQUInt32 = $null
  [bool]$pendingSpanBound = $false
  [string]$pendingText = ''
  if ([int]$MatcherAfter.pending_byte_count -gt 0) {
    try {
      $pendingText = [System.Text.Encoding]::ASCII.GetString(
          (ConvertFrom-Hex -Hex ([string]$MatcherAfter.pending_bytes_hex)))
    } catch { $pendingText = '' }
    [string]$tagBase = if ($Role -ceq 'vehicle') {'VCSTAT'} else {'GCSTAT'}
    $pendingOwnRole = ($pendingText -match
        ('^' + [regex]::Escape($tagBase) + '[123](?:\s|$)'))
    $qMatch = [regex]::Match($pendingText, '(?:^|\s)q=([0-9]+)(?:\s|$)')
    if ($qMatch.Success) {
      [uint32]$pendingQ = 0
      $pendingQPresent = [uint32]::TryParse($qMatch.Groups[1].Value,
          [ref]$pendingQ)
      if ($pendingQPresent) {
        $pendingQUInt32 = $pendingQ
        if ($null -ne $ExpectedQ) {
          $pendingQExact = ($pendingQ -eq [uint32]$ExpectedQ)
        }
      }
    }
    $pendingSpanBound = ([long]$MatcherAfter.pending_start_offset -ge
        [long]$Response.raw_rx_start_offset -and
        [long]$MatcherAfter.pending_start_offset -lt
          [long]$Response.raw_rx_end_offset)
  }
  [bool]$unanchoredGroundRecovery = ($Role -ceq 'ground' -and
      $AllowUnanchoredGroundRecovery -and $null -eq $ExpectedQ -and
      $pendingQPresent)
  if ($unanchoredGroundRecovery) { $pendingQExact = $true }
  if ([int]$MatcherAfter.pending_byte_count -gt 0) {
    $pendingEligible = ($pendingOwnRole -and $pendingQExact -and
        $pendingSpanBound)
  }
  [bool]$attemptCapacity = ($AttemptNumber + 2 -le $MaxAttempts)
  [bool]$timeoutShape = ([string]$Response.status -ceq 'TIMEOUT' -and
      [int]$Response.query_count -eq 1 -and
      [int]$Response.query_attempt_count -eq 1 -and
      -not [bool]$Response.write_timed_out -and
      ($null -ne $ExpectedQ -or $unanchoredGroundRecovery))
  [bool]$retryEligible = ($timeoutShape -and $overflowStable -and
      $pendingEligible -and $UnexpectedTaggedRowCount -eq 0 -and
      -not $RecoveryAlreadyUsed -and $attemptCapacity -and
      $RetryBudgetAvailable)
  [string]$action = 'REJECT'
  [string]$reason = 'unsafe_snapshot_response'
  if ([bool]$Response.valid) {
    $action = 'ACCEPT';$reason = 'snapshot_response_valid'
  } elseif ($retryEligible) {
    $action = 'RESYNC';$reason = 'bounded_partial_snapshot_resynchronization'
  } elseif ($RecoveryAlreadyUsed -or -not $attemptCapacity) {
    $reason = 'retry_exhausted'
  } elseif ($timeoutShape -and $overflowStable -and $pendingEligible -and
      $UnexpectedTaggedRowCount -eq 0 -and -not $RetryBudgetAvailable) {
    $reason = 'shared_deadline_exhausted'
  } elseif (-not $overflowStable) {
    $reason = 'matcher_overflow_changed'
  } elseif (-not $pendingEligible) {
    $reason = 'ambiguous_pending_matcher_state'
  } elseif ($UnexpectedTaggedRowCount -ne 0) {
    $reason = 'unexpected_tagged_rows'
  }
  return [pscustomobject][ordered]@{
    action=$action;reason=$reason;attempt_number=$AttemptNumber
    max_attempts=$MaxAttempts;retry_eligible=$retryEligible
    retry_budget_available=$RetryBudgetAvailable
    retry_exhausted=($reason -ceq 'retry_exhausted')
    overflow_stable=$overflowStable;pending_eligible=$pendingEligible
    pending_own_role=$pendingOwnRole;pending_q_exact=$pendingQExact
    pending_q_present=$pendingQPresent;pending_q_uint32=$pendingQUInt32
    pending_span_bound=$pendingSpanBound;pending_text=$pendingText
    unanchored_ground_recovery=$unanchoredGroundRecovery
    unexpected_tagged_row_count=$UnexpectedTaggedRowCount
    recovery_already_used=$RecoveryAlreadyUsed;fixture_write_count=0
  }
}

function Select-ReadinessLastVehicleSnapshot {
  param(
    [Parameter(Mandatory = $true)][AllowNull()]$CurrentSnapshot,
    [Parameter(Mandatory = $true)]$VehicleAfter,
    [Parameter(Mandatory = $true)]$VehicleAResponse,
    [Parameter(Mandatory = $true)]$VehicleBResponse,
    [Parameter(Mandatory = $true)]$WindowAssessment,
    [Parameter(Mandatory = $true)][bool]$WithinDeadline
  )
  if ($VehicleAResponse.valid -and $VehicleBResponse.valid -and
      $WindowAssessment.valid -and $WithinDeadline) {
    return $VehicleAfter
  }
  return $CurrentSnapshot
}

function Test-DataPlaneReadinessWindow {
  param(
    [Parameter(Mandatory = $true)][System.Collections.IEnumerable]$Events,
    [Parameter(Mandatory = $true)]$ParserIntegrity,
    [Parameter(Mandatory = $true)][double]$WindowStartElapsedMs,
    [Parameter(Mandatory = $true)][double]$WindowEndElapsedMs,
    [Parameter(Mandatory = $true)]$VehicleBefore,
    [Parameter(Mandatory = $true)]$VehicleAfter
  )
  $heartbeat = Get-HeartbeatWindowMetrics -Events $Events `
      -M0ElapsedMs $WindowStartElapsedMs -M1ElapsedMs $WindowEndElapsedMs `
      -MaximumGapMs $script:HeartbeatMaximumGapMs
  $beforeQ = Get-SnapshotUInt64 -Snapshot $VehicleBefore -Key 'q'
  $afterQ = Get-SnapshotUInt64 -Snapshot $VehicleAfter -Key 'q'
  [bool]$qNext = $false
  if ($beforeQ.found -and $afterQ.found) {
    [uint32]$expectedQ = Get-NextQueryId -Current ([uint32]$beforeQ.value)
    $qNext = ([uint32]$afterQ.value -eq $expectedQ)
  }
  $beforeBoot = Get-SnapshotUInt64 -Snapshot $VehicleBefore -Key 'boot'
  $afterBoot = Get-SnapshotUInt64 -Snapshot $VehicleAfter -Key 'boot'
  [bool]$sameBoot = ($beforeBoot.found -and $afterBoot.found -and
      [uint64]$beforeBoot.value -ne 0 -and
      [uint64]$beforeBoot.value -eq [uint64]$afterBoot.value)
  $beforeMs = Get-SnapshotUInt64 -Snapshot $VehicleBefore -Key 'ms'
  $afterMs = Get-SnapshotUInt64 -Snapshot $VehicleAfter -Key 'ms'
  [bool]$msIncreasing = ($beforeMs.found -and $afterMs.found -and
      [uint64]$afterMs.value -gt [uint64]$beforeMs.value)
  [uint64]$deviceMsToleranceMs = $script:ReadinessDeviceMsToleranceMs
  [double]$windowDurationMs = $WindowEndElapsedMs - $WindowStartElapsedMs
  [double]$toleratedDurationMs = [Math]::Max(0.0,
      $windowDurationMs - [double]$deviceMsToleranceMs)
  [uint64]$requiredDeviceMsDelta = [uint64][Math]::Floor(
      $toleratedDurationMs)
  [uint64]$deviceMsDelta = [uint64]0
  if ($msIncreasing) {
    $deviceMsDelta = [uint64]$afterMs.value - [uint64]$beforeMs.value
  }
  [bool]$msBracketsWindow = ($msIncreasing -and
      $deviceMsDelta -ge $requiredDeviceMsDelta)
  $beforeReady = Get-SnapshotUInt64 -Snapshot $VehicleBefore -Key 'r'
  $afterReady = Get-SnapshotUInt64 -Snapshot $VehicleAfter -Key 'r'
  $beforeFail = Get-SnapshotUInt64 -Snapshot $VehicleBefore -Key 'f'
  $afterFail = Get-SnapshotUInt64 -Snapshot $VehicleAfter -Key 'f'
  [bool]$vehicleHealthy = ($beforeReady.found -and $afterReady.found -and
      $beforeFail.found -and $afterFail.found -and
      [uint64]$beforeReady.value -eq 1 -and
      [uint64]$afterReady.value -eq 1 -and
      [uint64]$beforeFail.value -eq 0 -and
      [uint64]$afterFail.value -eq 0)
  $d7Bytes = Get-SnapshotDelta -Baseline $VehicleBefore `
      -Post $VehicleAfter -Key 'd7b'
  $d7Frames = Get-SnapshotDelta -Baseline $VehicleBefore `
      -Post $VehicleAfter -Key 'd7f'
  [bool]$d7BytesIncreasing = ($d7Bytes.monotonic -and
      [uint64]$d7Bytes.delta -gt 0)
  [bool]$d7FramesIncreasing = ($d7Frames.monotonic -and
      [uint64]$d7Frames.delta -gt 0)
  [bool]$parserClean = ($null -ne $ParserIntegrity -and
      [bool]$ParserIntegrity.valid)
  [bool]$primaryHeartbeat = ($heartbeat.valid -and
      [int]$heartbeat.count -ge 2)
  $checks = @(
    [pscustomobject]@{name='parser_clean';valid=$parserClean},
    [pscustomobject]@{name='primary_heartbeat_count_edge_gap_tail';valid=$primaryHeartbeat},
    [pscustomobject]@{name='vehicle_q_next';valid=$qNext},
    [pscustomobject]@{name='vehicle_same_boot';valid=$sameBoot},
    [pscustomobject]@{name='vehicle_ms_brackets_window';valid=$msBracketsWindow},
    [pscustomobject]@{name='vehicle_ready_fail_healthy';valid=$vehicleHealthy},
    [pscustomobject]@{name='vehicle_d7_bytes_increasing';valid=$d7BytesIncreasing},
    [pscustomobject]@{name='vehicle_d7_frames_increasing';valid=$d7FramesIncreasing})
  return [pscustomobject][ordered]@{
    valid=(@($checks | Where-Object {-not $_.valid}).Count -eq 0)
    window_start_elapsed_ms=$WindowStartElapsedMs
    window_end_elapsed_ms=$WindowEndElapsedMs
    window_duration_ms=$windowDurationMs
    parser_integrity=$ParserIntegrity
    heartbeat=$heartbeat
    vehicle_transition=[ordered]@{
      before_q=$beforeQ.value;after_q=$afterQ.value;q_next=$qNext
      before_boot=$beforeBoot.value;after_boot=$afterBoot.value
      same_boot=$sameBoot;before_ms=$beforeMs.value;after_ms=$afterMs.value
      ms_increasing=$msIncreasing;ms_brackets_window=$msBracketsWindow
      device_ms_delta=$deviceMsDelta
      required_device_ms_delta=$requiredDeviceMsDelta
      device_ms_tolerance_ms=$deviceMsToleranceMs
      ready_fail_healthy=$vehicleHealthy
      d7b_before=$d7Bytes.before;d7b_after=$d7Bytes.after
      d7b_delta=$d7Bytes.delta;d7b_increasing=$d7BytesIncreasing
      d7f_before=$d7Frames.before;d7f_after=$d7Frames.after
      d7f_delta=$d7Frames.delta;d7f_increasing=$d7FramesIncreasing
    }
    checks=$checks
  }
}

function Copy-ParamListEventsToEvidence {
  param(
    [Parameter(Mandatory = $true)]$SourceState,
    [Parameter(Mandatory = $true)]$Destination
  )
  [int]$copied = 0
  foreach ($sourceEvent in $SourceState.events.ToArray()) {
    if ($Destination.Count -ge $script:MaxParamValueEvidenceEvents) {
      throw ('pre-request PARAM_VALUE evidence cap exceeded; ' +
        'refusing truncation')
    }
    $Destination.Add($sourceEvent)
    ++$copied
  }
  return $copied
}

function New-ReadinessParserEpoch {
  param(
    [Parameter(Mandatory = $true)]$Parser,
    [Parameter(Mandatory = $true)][string]$Name,
    [Parameter(Mandatory = $true)][double]$StartElapsedMs,
    [Parameter(Mandatory = $true)][long]$StartRawOffset
  )
  if ($null -ne $script:DualPortReaderWorker) {
    [void](Set-ReaderCaptureContext -Phase ([string]$script:CurrentPhase) `
        -Epoch $Name)
    $StartElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
    $StartRawOffset = [long]$script:groundCapture.RawBytes
  }
  $Parser.Enabled = $true
  $Parser.ParamList.capture_scope = 'pre_request_readiness'
  return [pscustomobject][ordered]@{
    name=$Name;start_elapsed_ms=$StartElapsedMs
    start_raw_offset=$StartRawOffset;closed=$false;result=$null
  }
}

function Complete-ReadinessParserEpoch {
  param(
    [Parameter(Mandatory = $true)]$Epoch,
    [Parameter(Mandatory = $true)]$Parser,
    [Parameter(Mandatory = $true)]$Destination,
    [Parameter(Mandatory = $true)][double]$EndElapsedMs,
    [Parameter(Mandatory = $true)][long]$EndRawOffset
  )
  if ($Epoch.closed) { return $Epoch.result }
  if ($null -ne $script:DualPortReaderWorker) {
    [void](Set-ReaderCaptureContext -Phase ([string]$script:CurrentPhase) `
        -Epoch ('closed_after_' + [string]$Epoch.name))
    $EndElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
    $EndRawOffset = [long]$script:groundCapture.RawBytes
  }
  $Parser.Enabled = $false
  [object[]]$heartbeatEvents = [object[]]@()
  if ($Parser.HeartbeatEvents.Count -gt 0) {
    $heartbeatEvents = [object[]]$Parser.HeartbeatEvents.ToArray()
  }
  [object[]]$validEvents = [object[]]@()
  if ($Parser.ValidEvents.Count -gt 0) {
    $validEvents = [object[]]$Parser.ValidEvents.ToArray()
  }
  [int]$sourceEventCount = $Parser.ParamList.events.Count
  [int]$destinationBefore = $Destination.Count
  [int]$copiedEventCount = Copy-ParamListEventsToEvidence `
      -SourceState $Parser.ParamList -Destination $Destination
  $integrity = Get-ParserIntegrity -Parser $Parser
  $result = [pscustomobject][ordered]@{
    name=[string]$Epoch.name
    start_elapsed_ms=[double]$Epoch.start_elapsed_ms
    end_elapsed_ms=$EndElapsedMs
    raw_start_offset=[long]$Epoch.start_raw_offset
    raw_end_offset=$EndRawOffset
    source_event_count=$sourceEventCount
    copied_event_count=$copiedEventCount
    destination_count_before=$destinationBefore
    destination_count_after=$Destination.Count
    heartbeat_events=$heartbeatEvents
    valid_events=$validEvents
    integrity=$integrity
  }
  Reset-MavlinkAnalysis -Parser $Parser
  $Epoch.closed = $true
  $Epoch.result = $result
  return $Epoch.result
}

function Complete-ReadinessParserEpochChecked {
  param(
    [Parameter(Mandatory = $true)]$Epoch,
    [Parameter(Mandatory = $true)]$Parser,
    [Parameter(Mandatory = $true)]$Destination,
    [Parameter(Mandatory = $true)][double]$EndElapsedMs,
    [Parameter(Mandatory = $true)][long]$EndRawOffset,
    [Parameter(Mandatory = $true)][string]$Stage,
    [AllowNull()]$MatcherSnapshot
  )
  $epochResult = Complete-ReadinessParserEpoch -Epoch $Epoch `
      -Parser $Parser -Destination $Destination `
      -EndElapsedMs $EndElapsedMs -EndRawOffset $EndRawOffset
  [bool]$syncInvalid = (-not [bool]$epochResult.integrity.valid)
  $groundLatch = $null
  if ($syncInvalid) {
    $epochFailureResponse = [pscustomobject][ordered]@{
      name=[string]$epochResult.name
      start_elapsed_ms=[double]$epochResult.start_elapsed_ms
      end_elapsed_ms=[double]$epochResult.end_elapsed_ms
      raw_start_offset=[long]$epochResult.raw_start_offset
      raw_end_offset=[long]$epochResult.raw_end_offset
      source_event_count=[int]$epochResult.source_event_count
      copied_event_count=[int]$epochResult.copied_event_count
      integrity=$epochResult.integrity
    }
    $groundLatch = New-ReadinessSyncInvalidLatch -Role 'ground' `
        -Stage $Stage -Failure 'parser_integrity_invalid' `
        -Response $epochFailureResponse -MatcherSnapshot $MatcherSnapshot
  }
  $epochResult | Add-Member -MemberType NoteProperty `
      -Name sync_invalid -Value $syncInvalid -Force
  $epochResult | Add-Member -MemberType NoteProperty `
      -Name ground_sync_invalid -Value $groundLatch -Force
  $epochResult | Add-Member -MemberType NoteProperty `
      -Name vehicle_query_count -Value 0 -Force
  $epochResult | Add-Member -MemberType NoteProperty `
      -Name request_write_count -Value 0 -Force
  return $epochResult
}

function Test-DataPlanePassiveCandidate {
  param(
    [Parameter(Mandatory = $true)][System.Collections.IEnumerable]$Events,
    [Parameter(Mandatory = $true)]$ParserIntegrity,
    [Parameter(Mandatory = $true)]$Capture,
    [Parameter(Mandatory = $true)][bool]$Idle,
    [Parameter(Mandatory = $true)][long]$GroundRawStartOffset,
    [Parameter(Mandatory = $true)][long]$GroundRawEndOffset
  )
  [double]$windowStartMs = [double]$Capture.started_elapsed_ms
  [double]$windowEndMs = [double]$Capture.finished_elapsed_ms
  [double]$windowDurationMs = $windowEndMs - $windowStartMs
  $heartbeat = Get-HeartbeatWindowMetrics -Events $Events `
      -M0ElapsedMs $windowStartMs -M1ElapsedMs $windowEndMs `
      -MaximumGapMs $script:HeartbeatMaximumGapMs
  [bool]$captureCompleted = [bool]$Capture.completed_duration
  [bool]$fullWindow = ($captureCompleted -and $windowDurationMs -ge 5000.0)
  [bool]$parserClean = ($null -ne $ParserIntegrity -and
      $ParserIntegrity.valid -eq $true)
  [bool]$primaryHeartbeat = ($heartbeat.valid -eq $true -and
      [int]$heartbeat.count -ge 2)
  [bool]$syncInvalid = (-not $parserClean)
  [bool]$candidate = ($Idle -and $fullWindow -and $parserClean -and
      $primaryHeartbeat)
  return [pscustomobject][ordered]@{
    candidate=$candidate;sync_invalid=$syncInvalid;idle=$Idle
    capture_completed=$captureCompleted;full_window=$fullWindow
    window_start_elapsed_ms=$windowStartMs
    window_end_elapsed_ms=$windowEndMs;window_duration_ms=$windowDurationMs
    ground_raw_start_offset=$GroundRawStartOffset
    ground_raw_end_offset=$GroundRawEndOffset
    parser_integrity=$ParserIntegrity;heartbeat=$heartbeat
  }
}

function Get-ReadinessPassiveWindowDecision {
  param(
    [Parameter(Mandatory = $true)][double]$GateStartedElapsedMs,
    [Parameter(Mandatory = $true)][double]$CurrentElapsedMs,
    [Parameter(Mandatory = $true)][int]$TimeoutSeconds,
    [Parameter(Mandatory = $true)][int]$SnapshotTimeoutSeconds
  )
  [double]$deadlineElapsedMs = $GateStartedElapsedMs +
      ([double]$TimeoutSeconds * 1000.0)
  [double]$remainingMs = $deadlineElapsedMs - $CurrentElapsedMs
  [double]$snapshotTimeoutMs = [double]$SnapshotTimeoutSeconds * 1000.0
  [double]$passiveWindowMs = 5000.0
  [double]$freshWindowMs = 5000.0
  [double]$requiredRemainingMs = $passiveWindowMs + $snapshotTimeoutMs +
      $freshWindowMs + [double]$script:ReadinessVehicleBReserveMs
  return [pscustomobject][ordered]@{
    gate_started_elapsed_ms=$GateStartedElapsedMs
    deadline_elapsed_ms=$deadlineElapsedMs;current_elapsed_ms=$CurrentElapsedMs
    remaining_ms=$remainingMs;required_remaining_ms=$requiredRemainingMs
    passive_window_ms=$passiveWindowMs;snapshot_timeout_ms=$snapshotTimeoutMs
    fresh_window_ms=$freshWindowMs
    vehicle_B_reserve_ms=[double]$script:ReadinessVehicleBReserveMs
    can_start_full_pipeline=($remainingMs -ge $requiredRemainingMs)
    timed_out=($remainingMs -lt $requiredRemainingMs)
  }
}

function Get-CaptureMatcherSnapshot {
  param([Parameter(Mandatory = $true)]$State)
  [byte[]]$pendingBytes = $State.MatcherCandidate.ToArray()
  return [pscustomobject][ordered]@{
    role=[string]$State.Role
    pending_byte_count=[int]$pendingBytes.Length
    pending_bytes_hex=ConvertTo-Hex -Bytes $pendingBytes
    pending_start_offset=[long]$State.MatcherStartOffset
    overflow_count=[uint64]$State.MatcherOverflows
    tagged_line_count=[int]$State.TaggedLines.Count
    raw_bytes=[long]$State.RawBytes
  }
}

function Test-CaptureMatcherClean {
  param(
    [Parameter(Mandatory = $true)]$State,
    [Parameter(Mandatory = $true)][uint64]$ExpectedOverflowCount
  )
  $snapshot = Get-CaptureMatcherSnapshot -State $State
  [bool]$valid = ($snapshot.pending_byte_count -eq 0 -and
      $snapshot.pending_start_offset -eq -1 -and
      [uint64]$snapshot.overflow_count -eq $ExpectedOverflowCount)
  return [pscustomobject][ordered]@{
    valid=$valid;expected_overflow_count=$ExpectedOverflowCount
    snapshot=$snapshot
  }
}

function New-ReadinessSyncInvalidLatch {
  param(
    [Parameter(Mandatory = $true)][string]$Role,
    [Parameter(Mandatory = $true)][string]$Stage,
    [Parameter(Mandatory = $true)][string]$Failure,
    [AllowNull()]$Response,
    [AllowNull()]$MatcherSnapshot
  )
  return [pscustomobject][ordered]@{
    latched=$true;role=$Role;stage=$Stage;failure=$Failure
    elapsed_ms=if($null -ne $script:RunWatch){
      [Math]::Round($script:RunWatch.Elapsed.TotalMilliseconds,3)
    }else{$null}
    response=$Response;matcher_at_latch=$MatcherSnapshot
  }
}

function Get-ReadinessSnapshotTransition {
  param(
    [Parameter(Mandatory = $true)][ValidateSet('A','B')][string]$Stage,
    [Parameter(Mandatory = $true)]$Snapshot,
    [Nullable[uint32]]$ExpectedQ = $null,
    [AllowNull()]$CurrentCompleteB,
    [AllowNull()]$PreQueryMatcherSnapshot,
    [AllowNull()]$MatcherSnapshot
  )
  $response = Test-ReadinessSnapshotResponse -Snapshot $Snapshot `
      -ExpectedQ $ExpectedQ
  [bool]$postQueryMatcherClean = (
    $null -ne $PreQueryMatcherSnapshot -and
    $null -ne $MatcherSnapshot -and
    [long]$MatcherSnapshot.pending_byte_count -eq 0 -and
    [long]$MatcherSnapshot.pending_start_offset -eq -1 -and
    [uint64]$MatcherSnapshot.overflow_count -eq
      [uint64]$PreQueryMatcherSnapshot.overflow_count)
  if (-not $response.valid -or -not $postQueryMatcherClean) {
    [string]$failure = if (-not $response.valid -and
        $response.write_timed_out) {
      'write_timed_out'
    } elseif (-not $response.valid -and $response.status -ne 'COMPLETE') {
      'timeout_or_partial'
    } elseif (-not $response.valid -and -not $response.expected_q_exact) {
      'wrong_q'
    } elseif (-not $postQueryMatcherClean) {
      'post_query_matcher_dirty'
    } else { 'invalid_response' }
    $latch = New-ReadinessSyncInvalidLatch -Role 'vehicle' `
        -Stage $Stage -Failure $failure -Response $response `
        -MatcherSnapshot $MatcherSnapshot
    return [pscustomobject][ordered]@{
      valid=$false;response=$response;sync_invalid_latch=$latch
      matcher_before_query=$PreQueryMatcherSnapshot
      matcher_after_query=$MatcherSnapshot
      post_query_matcher_clean=$postQueryMatcherClean
      next_complete_B=$CurrentCompleteB
      subsequent_diagnostic_query_count=0;request_write_count=0
    }
  }
  $nextCompleteB = $CurrentCompleteB
  if ($Stage -eq 'B') { $nextCompleteB = $Snapshot }
  return [pscustomobject][ordered]@{
    valid=$true;response=$response;sync_invalid_latch=$null
    matcher_before_query=$PreQueryMatcherSnapshot
    matcher_after_query=$MatcherSnapshot
    post_query_matcher_clean=$postQueryMatcherClean
    next_complete_B=$nextCompleteB
    subsequent_diagnostic_query_count=$null;request_write_count=$null
  }
}

function Get-ReadinessExpectedA {
  param([AllowNull()]$LastCompleteVehicleB)
  [Nullable[uint32]]$expectedA = $null
  if ($null -ne $LastCompleteVehicleB -and
      $LastCompleteVehicleB.status -eq 'COMPLETE' -and
      $null -ne $LastCompleteVehicleB.q_uint32) {
    $expectedA = Get-NextQueryId -Current `
        ([uint32]$LastCompleteVehicleB.q_uint32)
  }
  return $expectedA
}

