function Get-PostDiagnosticPlan {
  param(
    [AllowNull()]$DataPlaneReadiness,
    [AllowNull()]$BacklogDrainGate,
    [AllowNull()]$BaselinePairGate,
    [AllowNull()]$PreRequestPairGate = $null,
    [AllowNull()]$InjectionState = $null
  )
  [bool]$readinessSyncInvalid = $false
  if ($null -ne $DataPlaneReadiness) {
    $readinessSyncProperty = `
        $DataPlaneReadiness.PSObject.Properties['sync_invalid']
    $readinessSyncInvalid = ($null -ne $readinessSyncProperty -and
        $readinessSyncProperty.Value -eq $true)
  }
  [bool]$backlogSyncInvalid = $false
  if ($null -ne $BacklogDrainGate) {
    $backlogSyncProperty = `
        $BacklogDrainGate.PSObject.Properties['sync_invalid']
    $backlogSyncInvalid = ($null -ne $backlogSyncProperty -and
        $backlogSyncProperty.Value -eq $true)
  }
  [bool]$baselineSyncInvalid = $false
  if ($null -ne $BaselinePairGate) {
    $baselineSyncProperty = `
        $BaselinePairGate.PSObject.Properties['sync_invalid']
    $baselineSyncInvalid = ($null -ne $baselineSyncProperty -and
        $baselineSyncProperty.Value -eq $true)
  }
  [bool]$preRequestSyncInvalid = $false
  if ($null -ne $PreRequestPairGate) {
    $preRequestSyncProperty = `
        $PreRequestPairGate.PSObject.Properties['sync_invalid']
    $preRequestSyncInvalid = ($null -ne $preRequestSyncProperty -and
        $preRequestSyncProperty.Value -eq $true)
  }
  [bool]$anySyncInvalid = ($readinessSyncInvalid -or
      $backlogSyncInvalid -or $baselineSyncInvalid -or
      $preRequestSyncInvalid)
  $sourceList = New-Object 'System.Collections.Generic.List[string]'
  if ($readinessSyncInvalid) { $sourceList.Add('readiness') }
  if ($backlogSyncInvalid) { $sourceList.Add('backlog') }
  if ($baselineSyncInvalid) { $sourceList.Add('baseline') }
  if ($preRequestSyncInvalid) { $sourceList.Add('pre_request') }
  [object[]]$sources = [object[]]$sourceList.ToArray()
  [int]$requestAttemptCount = 0
  [int]$requestWriteCount = 0
  [bool]$requestWriteUncertain = $false
  [string]$requestWriteDisposition = 'NOT_ATTEMPTED'
  if ($null -ne $InjectionState) {
    $attemptProperty = $InjectionState.PSObject.Properties['attempt_count']
    $writeProperty = $InjectionState.PSObject.Properties['write_count']
    $uncertainProperty =
        $InjectionState.PSObject.Properties['write_uncertain']
    $dispositionProperty =
        $InjectionState.PSObject.Properties['write_disposition']
    if ($null -ne $attemptProperty) {
      $requestAttemptCount = [int]$attemptProperty.Value
    }
    if ($null -ne $writeProperty) {
      $requestWriteCount = [int]$writeProperty.Value
    }
    if ($null -ne $uncertainProperty) {
      $requestWriteUncertain = [bool]$uncertainProperty.Value
    }
    if ($null -ne $dispositionProperty) {
      $requestWriteDisposition = [string]$dispositionProperty.Value
    }
  }
  [bool]$requestAcknowledgedExactlyOnce = (
      $requestAttemptCount -eq 1 -and $requestWriteCount -eq 1 -and
      -not $requestWriteUncertain -and
      $requestWriteDisposition -ceq 'ACKNOWLEDGED_EXACTLY_ONCE')
  [bool]$evaluateSuccessContract = (-not $anySyncInvalid -and
      $requestAcknowledgedExactlyOnce)
  return [pscustomobject][ordered]@{
    readiness_sync_invalid=$readinessSyncInvalid
    backlog_sync_invalid=$backlogSyncInvalid
    baseline_sync_invalid=$baselineSyncInvalid
    pre_request_sync_invalid=$preRequestSyncInvalid
    any_sync_invalid=$anySyncInvalid;sources=$sources
    run_ground=(-not $anySyncInvalid);run_vehicle=(-not $anySyncInvalid)
    suppressed_status=if($anySyncInvalid){'NOT_RUN_SYNC_INVALID'}else{$null}
    suppression_reason=if($anySyncInvalid){'SYNC_INVALID'}else{$null}
    request_attempt_count=$requestAttemptCount
    request_write_count=$requestWriteCount
    request_write_uncertain=$requestWriteUncertain
    request_write_disposition=$requestWriteDisposition
    request_acknowledged_exactly_once=$requestAcknowledgedExactlyOnce
    evaluate_success_contract=$evaluateSuccessContract
    assessment_status=if($evaluateSuccessContract){
      'RUN_SUCCESS_CONTRACT'
    }elseif($anySyncInvalid){
      'NOT_RUN_SYNC_INVALID'
    }else{'NOT_RUN_REQUEST_SUPPRESSED'}
  }
}

function New-RequestSuppressedPostAssessment {
  param([Parameter(Mandatory = $true)]$PostDiagnosticPlan)
  if ([bool]$PostDiagnosticPlan.evaluate_success_contract) {
    throw 'request-suppressed assessment cannot replace an applicable success contract'
  }
  if ([bool]$PostDiagnosticPlan.any_sync_invalid) {
    throw 'sync-invalid post diagnostics use the dedicated suppression path'
  }
  [object[]]$checks = [object[]]@()
  return [pscustomobject][ordered]@{
    schema_version=1;valid=$false;status='NOT_RUN_REQUEST_SUPPRESSED'
    applicable=$false;evaluated=$false;failed_count=0;first_failed=$null
    reason='exact PARAM_REQUEST_LIST fixture was not acknowledged exactly once'
    fixture_write_count=[int]$PostDiagnosticPlan.request_write_count
    request_attempt_count=[int]$PostDiagnosticPlan.request_attempt_count
    request_write_uncertain=[bool]$PostDiagnosticPlan.request_write_uncertain
    request_write_disposition=[string]$PostDiagnosticPlan.request_write_disposition
    side_effect_contract='diagnostic_snapshots_only_no_success_delta_claim'
    checks=$checks
  }
}

function Get-SyncInvalidMatcherAtLatch {
  param(
    [Parameter(Mandatory = $true)][ValidateSet('vehicle','ground')]
      [string]$Role,
    [AllowNull()]$DataPlaneReadiness,
    [AllowNull()]$BacklogDrainGate,
    [AllowNull()]$BaselinePairGate,
    [AllowNull()]$PreRequestPairGate
  )
  [string]$propertyName = $Role + '_sync_invalid'
  foreach ($gate in @($DataPlaneReadiness,$BacklogDrainGate,
      $BaselinePairGate,$PreRequestPairGate)) {
    if ($null -eq $gate) { continue }
    $latchProperty = $gate.PSObject.Properties[$propertyName]
    if ($null -ne $latchProperty -and $null -ne $latchProperty.Value -and
        [bool]$latchProperty.Value.latched) {
      return $latchProperty.Value.matcher_at_latch
    }
  }
  if ($null -ne $PreRequestPairGate) {
    foreach ($nestedName in @('last_recovery_backlog_gate',
        'last_recovery_baseline_gate')) {
      $nestedProperty = $PreRequestPairGate.PSObject.Properties[$nestedName]
      if ($null -eq $nestedProperty -or $null -eq $nestedProperty.Value) {
        continue
      }
      $latchProperty = $nestedProperty.Value.PSObject.Properties[$propertyName]
      if ($null -ne $latchProperty -and $null -ne $latchProperty.Value -and
          [bool]$latchProperty.Value.latched) {
        return $latchProperty.Value.matcher_at_latch
      }
    }
  }
  return $null
}

function New-SyncInvalidContinuationEvidence {
  param(
    [AllowNull()]$MatcherAtLatch,
    [Parameter(Mandatory = $true)]$BeforeFooterPump,
    [Parameter(Mandatory = $true)]$AfterFooterPump,
    [Parameter(Mandatory = $true)][uint64]$DiagnosticWriteCountBefore,
    [Parameter(Mandatory = $true)][uint64]$DiagnosticWriteCountAfter
  )
  [uint64]$writeDelta = $DiagnosticWriteCountAfter -
      $DiagnosticWriteCountBefore
  return [pscustomobject][ordered]@{
    valid=($writeDelta -eq 0);matcher_at_latch=$MatcherAtLatch
    before_footer_pump=$BeforeFooterPump;after_footer_pump=$AfterFooterPump
    diagnostic_write_count_before=$DiagnosticWriteCountBefore
    diagnostic_write_count_after=$DiagnosticWriteCountAfter
    diagnostic_write_count_delta=$writeDelta
  }
}

function Select-CorrelatedReportFromRows {
  param(
    [Parameter(Mandatory = $true)][System.Collections.IList]$Rows,
    [Parameter(Mandatory = $true)][string]$TagBase,
    [Parameter(Mandatory = $true)][int]$StartLineIndex,
    [Parameter(Mandatory = $true)][long]$MinimumRawStartOffset,
    [Nullable[uint32]]$ExpectedQ
  )
  $groups = [ordered]@{}
  for ($index = $StartLineIndex; $index -lt $Rows.Count; ++$index) {
    $candidate = $Rows[$index]
    if (-not $candidate.valid_correlation) { continue }
    if ([long]$candidate.raw_start_offset -lt $MinimumRawStartOffset) {
      continue
    }
    if ($null -ne $ExpectedQ -and
        [uint32]$candidate.q_uint32 -ne [uint32]$ExpectedQ) { continue }
    [string]$groupKey = '{0}:{1}' -f $candidate.q_uint32,
        $candidate.ms_uint64
    if (-not $groups.Contains($groupKey)) { $groups[$groupKey] = [ordered]@{} }
    if (-not $groups[$groupKey].Contains($candidate.tag)) {
      $groups[$groupKey][$candidate.tag] = $candidate
    }
    [string[]]$tags = @("${TagBase}1", "${TagBase}2", "${TagBase}3")
    [bool]$complete = $true
    foreach ($tag in $tags) {
      if (-not $groups[$groupKey].Contains($tag)) { $complete = $false }
    }
    if ($complete) {
      [object[]]$responses = [object[]]@($tags | ForEach-Object {
        $groups[$groupKey][$_]
      })
      return [pscustomobject]@{
        complete=$true;q_uint32=[uint32]$candidate.q_uint32
        ms_uint64=[uint64]$candidate.ms_uint64;responses=$responses
      }
    }
  }
  [object[]]$emptyResponses = [object[]]@()
  return [pscustomobject]@{
    complete=$false;q_uint32=$null;ms_uint64=$null
    responses=$emptyResponses
  }
}

function Write-SnapshotText {
  param([string]$Path, $Snapshot)
  [string]$text = ''
  if ($null -ne $Snapshot -and $Snapshot.status -eq 'COMPLETE') {
    $text = (($Snapshot.responses | ForEach-Object {$_.line}) -join "`n") +
        "`n"
  } elseif ($null -ne $Snapshot -and
      $Snapshot.status -eq 'NOT_RUN_SYNC_INVALID') {
    $text = "NOT_RUN_SYNC_INVALID query_count=0 query_attempt_count=0 reason=SYNC_INVALID`n"
  }
  Write-TextDurable -Path $Path -Text $text
}

function Test-PreRequestBacklogGate {
  param(
    [Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$ReadinessEvents,
    [Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$M0Events,
    [bool]$M0EpochCompleted = $true
  )
  [object[]]$readinessEventArray = @($ReadinessEvents)
  [object[]]$m0EventArray = @($M0Events)
  $allEvents = New-Object 'System.Collections.Generic.List[object]'
  foreach ($event in $readinessEventArray) { $allEvents.Add($event) }
  foreach ($event in $m0EventArray) { $allEvents.Add($event) }
  [object[]]$allEventArray = $allEvents.ToArray()
  $knownStat = @($allEventArray | Where-Object {
      $_.classification -eq 'known_STAT_RUNTIME_sentinel'
    })
  $staleGeneric = @($allEventArray | Where-Object {
      $_.classification -ne 'known_STAT_RUNTIME_sentinel'
  })
  return [pscustomobject][ordered]@{
    schema_version=2
    decision_scope='fresh_m0_only'
    m0_epoch_completed=$M0EpochCompleted
    valid=($M0EpochCompleted -and $m0EventArray.Count -eq 0)
    not_run=(-not $M0EpochCompleted)
    veto_event_count=$m0EventArray.Count
    historical_readiness_event_count=$readinessEventArray.Count
    readiness_events_audit_only=$true
    stale_param_value_count=$allEvents.Count
    stale_generic_count=$staleGeneric.Count
    known_stat_runtime_sentinel_count=$knownStat.Count
    readiness_event_count=$readinessEventArray.Count
    m0_event_count=$m0EventArray.Count
    events=$allEventArray
    historical_readiness_events=$readinessEventArray
    m0_veto_events=$m0EventArray
  }
}

function Test-M0CausalGate {
  param(
    [Parameter(Mandatory = $true)]$Parser,
    [Parameter(Mandatory = $true)][double]$M0ElapsedMs,
    [Parameter(Mandatory = $true)][double]$GateEndElapsedMs,
    [AllowEmptyCollection()][object[]]$ReadinessParamValueEvents = @(),
    [long]$M0GroundRawOffset = -1,
    [long]$M0GateEndGroundRawOffset = -1
  )
  $preRequestIntegrity = Get-ParserIntegrity -Parser $Parser
  [int]$preRequestParamValues = $Parser.ParamList.events.Count
  $preRequestBacklogGate = Test-PreRequestBacklogGate `
      -ReadinessEvents $ReadinessParamValueEvents `
      -M0Events $Parser.ParamList.events.ToArray() -M0EpochCompleted $true
  $m0Heartbeat = Get-HeartbeatWindowMetrics `
      -Events $Parser.HeartbeatEvents -M0ElapsedMs $M0ElapsedMs `
      -M1ElapsedMs $GateEndElapsedMs `
      -MaximumGapMs $script:HeartbeatMaximumGapMs
  [bool]$valid = ($preRequestIntegrity.valid -and
      $preRequestParamValues -eq 0 -and $preRequestBacklogGate.valid -and
      $m0Heartbeat.valid -and
      [int]$m0Heartbeat.count -ge 2)
  return [pscustomobject][ordered]@{
    valid=$valid
    parser_integrity=$preRequestIntegrity
    target_param_value_count=$preRequestParamValues
    pre_request_backlog_gate=$preRequestBacklogGate
    parser_buffer_empty=($Parser.Buffer.Count -eq 0)
    m0_ground_raw_offset=$M0GroundRawOffset
    m0_gate_end_ground_raw_offset=$M0GateEndGroundRawOffset
    heartbeat=$m0Heartbeat
  }
}

function Test-ExactPreM0TailStatRuntimeRace {
  param(
    [AllowNull()]$PreM0TailEvidence,
    [Parameter(Mandatory = $true)]$OfficialVehicle,
    [Parameter(Mandatory = $true)]$PreRequestVehicle,
    [Parameter(Mandatory = $true)][long]$M0GroundRawOffset,
    [Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$M0Events
  )
  $checks = New-Object 'System.Collections.Generic.List[object]'
  [object[]]$events = [object[]]@()
  [object[]]$validEvents = [object[]]@()
  [bool]$validEventsAvailable = $false
  [bool]$completedDuration = $false
  [int]$requestedMilliseconds = 0
  [long]$tailRawStart = [long]-1
  [long]$tailRawEnd = [long]-1
  [bool]$tailIntegrityValid = $false
  [bool]$tailEvidenceValid = $false
  [string]$tailCaptureScope = ''
  [string]$tailProducerPhase = ''
  [string]$tailProducerEpoch = ''
  if ($null -ne $PreM0TailEvidence) {
    $completedDuration = [bool]$PreM0TailEvidence.completed_duration
    $requestedMilliseconds = [int]$PreM0TailEvidence.requested_milliseconds
    $tailRawStart = [long]$PreM0TailEvidence.raw_start_offset
    $tailRawEnd = [long]$PreM0TailEvidence.raw_end_offset
    $tailIntegrityValid = [bool]$PreM0TailEvidence.integrity.valid
    $tailEvidenceValid = [bool]$PreM0TailEvidence.valid
    $tailCaptureScope = [string]$PreM0TailEvidence.capture_scope
    $tailProducerPhase = [string]$PreM0TailEvidence.producer_phase
    $tailProducerEpoch = [string]$PreM0TailEvidence.producer_epoch
    $events = [object[]]@($PreM0TailEvidence.events)
    $validEventsProperty =
        $PreM0TailEvidence.PSObject.Properties['valid_events']
    if ($null -ne $validEventsProperty) {
      $validEventsAvailable = $true
      $validEvents = [object[]]@($validEventsProperty.Value)
    }
  }

  $pvid = Get-SnapshotString -Snapshot $PreRequestVehicle -Key 'pvid'
  $pvval = Get-SnapshotString -Snapshot $PreRequestVehicle -Key 'pvval'
  $pvidx = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvidx'
  $pvcnt = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvcnt'
  $pvtype = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvtype'
  $pvseq = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvseq'
  $pvsys = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvsys'
  $pvcomp = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvcomp'

  [bool]$crcValid = $false
  [bool]$messageExact = $false
  [bool]$classificationExact = $false
  [bool]$anomalyFree = $false
  [bool]$idExact = $false
  [bool]$valueExact = $false
  [bool]$tupleExact = $false
  [bool]$sourceExact = $false
  [bool]$sequenceExact = $false
  [bool]$rawRangeExact = $false
  [bool]$boundaryExact = $false
  [bool]$directBoundaryExact = $false
  [bool]$targetValidEventMirrorExact = $false
  [bool]$targetPayloadExact = $false
  [bool]$leadingHeartbeatChainExact = $false
  [int]$leadingHeartbeatCount = 0
  [bool]$trailingHeartbeatChainExact = $false
  [int]$trailingHeartbeatCount = 0
  [bool]$fullTailWireChainExact = $false
  [string]$boundaryMode = 'invalid'
  [bool]$producerExact = $false
  if ($events.Count -eq 1) {
    $event = $events[0]
    $paramPayloadHexProperty = $event.PSObject.Properties['payload_hex']
    $crcValid = ([bool]$event.crc_valid -eq $true)
    $messageExact = ([int]$event.message_id -eq 22)
    $classificationExact = ([string]$event.classification -ceq
        'known_STAT_RUNTIME_sentinel')
    $anomalyFree = (@($event.anomaly_classes).Count -eq 0)
    $idExact = ($pvid.found -and [string]$pvid.value -ceq 'STAT_RUNTIME' -and
        [string]$event.param_id -ceq 'STAT_RUNTIME' -and
        [string]$event.param_id_hex -ceq $script:ExpectedStatRuntimeIdHex)
    $valueExact = ($pvval.found -and
        [string]$event.param_value_hex -ceq [string]$pvval.value -and
        [string]$event.param_value_bits_hex -ceq [string]$pvval.value)
    $tupleExact = ($pvidx.found -and [uint64]$pvidx.value -eq 65535 -and
        $pvcnt.found -and [uint64]$pvcnt.value -eq 932 -and
        $pvtype.found -and [uint64]$pvtype.value -eq 6 -and
        [int]$event.param_index -eq [int]$pvidx.value -and
        [int]$event.param_count -eq [int]$pvcnt.value -and
        [int]$event.param_type -eq [int]$pvtype.value)
    $sourceExact = ($pvsys.found -and [uint64]$pvsys.value -eq 1 -and
        $pvcomp.found -and [uint64]$pvcomp.value -eq 1 -and
        [int]$event.system_id -eq [int]$pvsys.value -and
        [int]$event.component_id -eq [int]$pvcomp.value)
    $sequenceExact = ($pvseq.found -and [uint64]$pvseq.value -le 255 -and
        [int]$event.sequence -eq [int]$pvseq.value)
    $rawRangeExact = ([long]$event.raw_start_offset -ge
          [long]$PreM0TailEvidence.raw_start_offset -and
        [long]$event.raw_end_offset_exclusive -le
          [long]$PreM0TailEvidence.raw_end_offset -and
        [long]$event.raw_start_offset -lt
          [long]$event.raw_end_offset_exclusive)
    $directBoundaryExact = ([long]$event.raw_end_offset_exclusive -eq
          [long]$M0GroundRawOffset -and
        [long]$PreM0TailEvidence.raw_end_offset -eq
          [long]$M0GroundRawOffset)
    if ($directBoundaryExact) {
      $boundaryExact = $true
      $boundaryMode = 'direct_STAT_RUNTIME_boundary'
    } elseif ($validEventsAvailable -and $validEvents.Count -gt 1 -and
        [long]$PreM0TailEvidence.raw_end_offset -eq
          [long]$M0GroundRawOffset) {
      [int]$targetMirrorIndex = -1
      [int]$targetMirrorCount = 0
      for ([int]$validIndex = 0;
          $validIndex -lt $validEvents.Count; ++$validIndex) {
        $validEvent = $validEvents[$validIndex]
        if ($null -eq $validEvent) { continue }
        $messageIdProperty = $validEvent.PSObject.Properties['message_id']
        $crcValidProperty = $validEvent.PSObject.Properties['crc_valid']
        $sequenceProperty = $validEvent.PSObject.Properties['sequence']
        $systemIdProperty = $validEvent.PSObject.Properties['system_id']
        $componentIdProperty =
            $validEvent.PSObject.Properties['component_id']
        $payloadLengthProperty =
            $validEvent.PSObject.Properties['payload_length']
        $payloadHexProperty =
            $validEvent.PSObject.Properties['payload_hex']
        $frameVersionProperty =
            $validEvent.PSObject.Properties['frame_version']
        $signedProperty = $validEvent.PSObject.Properties['signed']
        $rawStartProperty =
            $validEvent.PSObject.Properties['raw_start_offset']
        $rawEndProperty =
            $validEvent.PSObject.Properties['raw_end_offset_exclusive']
        $phaseProperty = $validEvent.PSObject.Properties['phase']
        $epochProperty = $validEvent.PSObject.Properties['producer_epoch']
        if ($null -ne $messageIdProperty -and
            $null -ne $crcValidProperty -and
            $null -ne $sequenceProperty -and
            $null -ne $systemIdProperty -and
            $null -ne $componentIdProperty -and
            $null -ne $payloadLengthProperty -and
            $null -ne $payloadHexProperty -and
            $null -ne $paramPayloadHexProperty -and
            $null -ne $frameVersionProperty -and
            $null -ne $signedProperty -and
            $null -ne $rawStartProperty -and $null -ne $rawEndProperty -and
            $null -ne $phaseProperty -and $null -ne $epochProperty -and
            [int]$messageIdProperty.Value -eq 22 -and
            $crcValidProperty.Value -is [bool] -and
            [bool]$crcValidProperty.Value -eq $true -and
            [int]$sequenceProperty.Value -eq [int]$event.sequence -and
            [int]$systemIdProperty.Value -eq [int]$event.system_id -and
            [int]$componentIdProperty.Value -eq [int]$event.component_id -and
            [int]$payloadLengthProperty.Value -eq 25 -and
            [string]$payloadHexProperty.Value -ceq
              [string]$paramPayloadHexProperty.Value -and
            [int]$frameVersionProperty.Value -eq 2 -and
            $signedProperty.Value -is [bool] -and
            [bool]$signedProperty.Value -eq $false -and
            [long]$rawStartProperty.Value -eq
              [long]$event.raw_start_offset -and
            [long]$rawEndProperty.Value -eq
              [long]$event.raw_end_offset_exclusive -and
            [long]$rawEndProperty.Value - [long]$rawStartProperty.Value -eq
              37 -and
            [string]$phaseProperty.Value -ceq $tailProducerPhase -and
            [string]$epochProperty.Value -ceq $tailProducerEpoch) {
          ++$targetMirrorCount
          $targetMirrorIndex = $validIndex
          $targetPayloadExact = $true
        }
      }
      $targetValidEventMirrorExact = ($targetMirrorCount -eq 1)
      if ($targetValidEventMirrorExact) {
        [long]$expectedLeadingRawStart = $tailRawStart
        [bool]$leadingChainValid = $true
        for ([int]$leadingIndex = 0;
            $leadingIndex -lt $targetMirrorIndex; ++$leadingIndex) {
          $leadingEvent = $validEvents[$leadingIndex]
          if ($null -eq $leadingEvent) {
            $leadingChainValid = $false
            break
          }
          $leadingMessageId =
              $leadingEvent.PSObject.Properties['message_id']
          $leadingCrcValid =
              $leadingEvent.PSObject.Properties['crc_valid']
          $leadingSystemId =
              $leadingEvent.PSObject.Properties['system_id']
          $leadingComponentId =
              $leadingEvent.PSObject.Properties['component_id']
          $leadingPayloadLength =
              $leadingEvent.PSObject.Properties['payload_length']
          $leadingFrameVersion =
              $leadingEvent.PSObject.Properties['frame_version']
          $leadingSigned = $leadingEvent.PSObject.Properties['signed']
          $leadingRawStart =
              $leadingEvent.PSObject.Properties['raw_start_offset']
          $leadingRawEnd =
              $leadingEvent.PSObject.Properties['raw_end_offset_exclusive']
          $leadingPhase = $leadingEvent.PSObject.Properties['phase']
          $leadingEpoch =
              $leadingEvent.PSObject.Properties['producer_epoch']
          if ($null -eq $leadingMessageId -or
              $null -eq $leadingCrcValid -or
              $null -eq $leadingSystemId -or
              $null -eq $leadingComponentId -or
              $null -eq $leadingPayloadLength -or
              $null -eq $leadingFrameVersion -or
              $null -eq $leadingSigned -or
              $null -eq $leadingRawStart -or $null -eq $leadingRawEnd -or
              $null -eq $leadingPhase -or $null -eq $leadingEpoch -or
              [int]$leadingMessageId.Value -ne 0 -or
              -not ($leadingCrcValid.Value -is [bool]) -or
              [bool]$leadingCrcValid.Value -ne $true -or
              [int]$leadingSystemId.Value -ne 1 -or
              [int]$leadingComponentId.Value -ne 1 -or
              [int]$leadingPayloadLength.Value -ne 9 -or
              [int]$leadingFrameVersion.Value -ne 2 -or
              -not ($leadingSigned.Value -is [bool]) -or
              [bool]$leadingSigned.Value -ne $false -or
              [long]$leadingRawStart.Value -ne $expectedLeadingRawStart -or
              [long]$leadingRawEnd.Value -
                [long]$leadingRawStart.Value -ne 21 -or
              [string]$leadingPhase.Value -cne $tailProducerPhase -or
              [string]$leadingEpoch.Value -cne $tailProducerEpoch) {
            $leadingChainValid = $false
            break
          }
          $expectedLeadingRawStart = [long]$leadingRawEnd.Value
          ++$leadingHeartbeatCount
        }
        $leadingHeartbeatChainExact = ($leadingChainValid -and
            $expectedLeadingRawStart -eq [long]$event.raw_start_offset)
      }
      if ($targetValidEventMirrorExact -and $targetPayloadExact -and
          $leadingHeartbeatChainExact -and
          $targetMirrorIndex -lt ($validEvents.Count - 1)) {
        [long]$expectedTrailingRawStart =
            [long]$event.raw_end_offset_exclusive
        [bool]$trailingChainValid = $true
        for ([int]$trailingIndex = $targetMirrorIndex + 1;
            $trailingIndex -lt $validEvents.Count; ++$trailingIndex) {
          $trailingEvent = $validEvents[$trailingIndex]
          if ($null -eq $trailingEvent) {
            $trailingChainValid = $false
            break
          }
          $trailingMessageId =
              $trailingEvent.PSObject.Properties['message_id']
          $trailingCrcValid =
              $trailingEvent.PSObject.Properties['crc_valid']
          $trailingSystemId =
              $trailingEvent.PSObject.Properties['system_id']
          $trailingComponentId =
              $trailingEvent.PSObject.Properties['component_id']
          $trailingPayloadLength =
              $trailingEvent.PSObject.Properties['payload_length']
          $trailingFrameVersion =
              $trailingEvent.PSObject.Properties['frame_version']
          $trailingSigned = $trailingEvent.PSObject.Properties['signed']
          $trailingRawStart =
              $trailingEvent.PSObject.Properties['raw_start_offset']
          $trailingRawEnd =
              $trailingEvent.PSObject.Properties['raw_end_offset_exclusive']
          $trailingPhase = $trailingEvent.PSObject.Properties['phase']
          $trailingEpoch =
              $trailingEvent.PSObject.Properties['producer_epoch']
          if ($null -eq $trailingMessageId -or
              $null -eq $trailingCrcValid -or
              $null -eq $trailingSystemId -or
              $null -eq $trailingComponentId -or
              $null -eq $trailingPayloadLength -or
              $null -eq $trailingFrameVersion -or
              $null -eq $trailingSigned -or
              $null -eq $trailingRawStart -or $null -eq $trailingRawEnd -or
              $null -eq $trailingPhase -or $null -eq $trailingEpoch -or
              [int]$trailingMessageId.Value -ne 0 -or
              -not ($trailingCrcValid.Value -is [bool]) -or
              [bool]$trailingCrcValid.Value -ne $true -or
              [int]$trailingSystemId.Value -ne 1 -or
              [int]$trailingComponentId.Value -ne 1 -or
              [int]$trailingPayloadLength.Value -ne 9 -or
              [int]$trailingFrameVersion.Value -ne 2 -or
              -not ($trailingSigned.Value -is [bool]) -or
              [bool]$trailingSigned.Value -ne $false -or
              [long]$trailingRawStart.Value -ne
                $expectedTrailingRawStart -or
              [long]$trailingRawEnd.Value -
                [long]$trailingRawStart.Value -ne 21 -or
              [string]$trailingPhase.Value -cne $tailProducerPhase -or
              [string]$trailingEpoch.Value -cne $tailProducerEpoch) {
            $trailingChainValid = $false
            break
          }
          $expectedTrailingRawStart = [long]$trailingRawEnd.Value
          ++$trailingHeartbeatCount
        }
        $trailingHeartbeatChainExact = ($trailingChainValid -and
            $trailingHeartbeatCount -ge 1 -and
            $expectedTrailingRawStart -eq [long]$M0GroundRawOffset)
        $fullTailWireChainExact = ($leadingHeartbeatChainExact -and
            $targetValidEventMirrorExact -and $targetPayloadExact -and
            $trailingHeartbeatChainExact -and
            $tailRawStart -ge 0 -and $tailRawEnd -eq $M0GroundRawOffset)
        if ($fullTailWireChainExact) {
          $boundaryExact = $true
          $boundaryMode = 'contiguous_vehicle_heartbeat_chain'
        }
      }
    }
    $producerExact = ($tailCaptureScope -ceq 'pre_request_readiness' -and
        $tailProducerPhase -match '^pre_request_attempt_[1-3]_recovery_3s$' -and
        $tailProducerEpoch -ceq $tailProducerPhase -and
        [string]$event.capture_scope -ceq $tailCaptureScope -and
        [string]$event.producer_phase -ceq $tailProducerPhase -and
        [string]$event.producer_epoch -ceq $tailProducerEpoch)
  }
  [bool]$m0Empty = (@($M0Events).Count -eq 0)
  [bool]$officialVehicleComplete = ($null -ne $OfficialVehicle -and
      $OfficialVehicle.status -ceq 'COMPLETE')
  [bool]$captureExact = ($completedDuration -and
      $requestedMilliseconds -eq 3000)
  [bool]$tailBoundaryRangeValid = ($tailRawStart -ge 0 -and
      $tailRawEnd -ge $tailRawStart -and $tailRawEnd -eq $M0GroundRawOffset)

  foreach ($row in @(
      @('official_vehicle_complete',$officialVehicleComplete),
      @('tail_evidence_valid',$tailEvidenceValid),
      @('completed_3000ms_capture',$captureExact),
      @('tail_integrity_valid',$tailIntegrityValid),
      @('tail_boundary_range_valid',$tailBoundaryRangeValid),
      @('exactly_one_tail_param_value',($events.Count -eq 1)),
      @('crc_valid',$crcValid),@('message_22',$messageExact),
      @('classification_known_stat_runtime',$classificationExact),
      @('anomaly_classes_empty',$anomalyFree),@('param_id_exact',$idExact),
      @('param_value_bits_exact',$valueExact),@('tuple_exact',$tupleExact),
      @('source_exact',$sourceExact),@('sequence_exact',$sequenceExact),
      @('raw_range_exact',$rawRangeExact),@('m0_boundary_exact',$boundaryExact),
      @('producer_phase_epoch_exact',$producerExact),@('m0_events_empty',$m0Empty))) {
    $checks.Add([pscustomobject][ordered]@{
      name=[string]$row[0];valid=[bool]$row[1]
    })
  }
  return [pscustomobject][ordered]@{
    schema_version=1
    classification='exact_pre_M0_tail_STAT_RUNTIME_race'
    valid=(@($checks | Where-Object {-not $_.valid}).Count -eq 0)
    completed_duration=$completedDuration
    requested_milliseconds=$requestedMilliseconds
    raw_start_offset=$tailRawStart;raw_end_offset=$tailRawEnd
    m0_ground_raw_offset=$M0GroundRawOffset
    integrity=if($null -ne $PreM0TailEvidence){
      $PreM0TailEvidence.integrity
    }else{$null}
    events=$events;valid_events=$validEvents;m0_events=[object[]]@($M0Events)
    boundary_mode=$boundaryMode;direct_boundary_exact=$directBoundaryExact
    target_valid_event_mirror_exact=$targetValidEventMirrorExact
    target_payload_exact=$targetPayloadExact
    leading_heartbeat_chain_exact=$leadingHeartbeatChainExact
    leading_heartbeat_count=$leadingHeartbeatCount
    trailing_heartbeat_chain_exact=$trailingHeartbeatChainExact
    trailing_heartbeat_count=$trailingHeartbeatCount
    full_tail_wire_chain_exact=$fullTailWireChainExact
    pvid=$pvid.value;pvval=$pvval.value;pvidx=$pvidx.value;pvcnt=$pvcnt.value
    pvtype=$pvtype.value;pvseq=$pvseq.value;pvsys=$pvsys.value
    pvcomp=$pvcomp.value;checks=$checks.ToArray();fixture_write_count=0
  }
}

function Test-ExactObservedM0StatRuntimePartialD7Race {
  param(
    [Parameter(Mandatory = $true)]$CausalGate,
    [Parameter(Mandatory = $true)]$PreRequestVehicle,
    [Parameter(Mandatory = $true)][long]$M0GroundRawOffset,
    [Parameter(Mandatory = $true)][long]$M0GateEndGroundRawOffset,
    [Parameter(Mandatory = $true)]
    [AllowEmptyCollection()][object[]]$M0Events
  )
  function Get-EvidenceProperty {
    param([AllowNull()]$Object,[Parameter(Mandatory=$true)][string]$Name)
    if ($null -eq $Object) {
      return [pscustomobject]@{found=$false;value=$null}
    }
    $property = $Object.PSObject.Properties[$Name]
    if ($null -eq $property) {
      return [pscustomobject]@{found=$false;value=$null}
    }
    return [pscustomobject]@{found=$true;value=$property.Value}
  }

  [object[]]$events = [object[]]@($M0Events)
  $checks = New-Object 'System.Collections.Generic.List[object]'
  $pvid = Get-SnapshotString -Snapshot $PreRequestVehicle -Key 'pvid'
  $pvval = Get-SnapshotString -Snapshot $PreRequestVehicle -Key 'pvval'
  $pvidx = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvidx'
  $pvcnt = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvcnt'
  $pvtype = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvtype'
  $pvseq = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvseq'
  $pvsys = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvsys'
  $pvcomp = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvcomp'

  [bool]$eventSchemaExact = $false
  [bool]$crcValid = $false
  [bool]$messageExact = $false
  [bool]$payloadLengthExact = $false
  [bool]$classificationExact = $false
  [bool]$anomalyFree = $false
  [bool]$idExact = $false
  [bool]$valueExact = $false
  [bool]$tupleExact = $false
  [bool]$sourceExact = $false
  [bool]$sequenceExact = $false
  [bool]$producerExact = $false
  [bool]$rawRangeExact = $false
  [bool]$elapsedExact = $false
  $event = $null
  if ($events.Count -eq 1) {
    $event = $events[0]
    $eventProperties = [ordered]@{}
    foreach ($eventPropertyName in @(
        'crc_valid','message_id','payload_length','classification',
        'anomaly_classes','param_id','param_id_hex','param_value_hex',
        'param_value_bits_hex','param_index','param_count','param_type',
        'system_id','component_id','sequence','capture_scope',
        'producer_phase','producer_epoch','raw_start_offset',
        'raw_end_offset_exclusive','elapsed_ms')) {
      $eventProperties[$eventPropertyName] = Get-EvidenceProperty `
          -Object $event -Name $eventPropertyName
    }
    $eventSchemaExact = (@($eventProperties.Values | Where-Object {
      -not $_.found
    }).Count -eq 0)
    if ($eventSchemaExact) {
      $crcValid = ([bool]$eventProperties.crc_valid.value -eq $true)
      $messageExact = ([int]$eventProperties.message_id.value -eq 22)
      $payloadLengthExact = ([int]$eventProperties.payload_length.value -eq 25)
      $classificationExact = ([string]$eventProperties.classification.value `
          -ceq 'known_STAT_RUNTIME_sentinel')
      $anomalyFree = (@($eventProperties.anomaly_classes.value).Count -eq 0)
      $idExact = ($pvid.found -and
          [string]$pvid.value -ceq 'STAT_RUNTIME' -and
          [string]$eventProperties.param_id.value -ceq 'STAT_RUNTIME' -and
          [string]$eventProperties.param_id_hex.value -ceq
            $script:ExpectedStatRuntimeIdHex)
      $valueExact = ($pvval.found -and
          [string]$eventProperties.param_value_hex.value -ceq
            [string]$pvval.value -and
          [string]$eventProperties.param_value_bits_hex.value -ceq
            [string]$pvval.value)
      $tupleExact = ($pvidx.found -and [uint64]$pvidx.value -eq 65535 -and
          $pvcnt.found -and [uint64]$pvcnt.value -eq 932 -and
          $pvtype.found -and [uint64]$pvtype.value -eq 6 -and
          [int]$eventProperties.param_index.value -eq [int]$pvidx.value -and
          [int]$eventProperties.param_count.value -eq [int]$pvcnt.value -and
          [int]$eventProperties.param_type.value -eq [int]$pvtype.value)
      $sourceExact = ($pvsys.found -and [uint64]$pvsys.value -eq 1 -and
          $pvcomp.found -and [uint64]$pvcomp.value -eq 1 -and
          [int]$eventProperties.system_id.value -eq [int]$pvsys.value -and
          [int]$eventProperties.component_id.value -eq [int]$pvcomp.value)
      $sequenceExact = ($pvseq.found -and [uint64]$pvseq.value -le 255 -and
          [int]$eventProperties.sequence.value -eq [int]$pvseq.value)
      $producerExact = (
          [string]$eventProperties.capture_scope.value -ceq 'pre_request_m0' -and
          [string]$eventProperties.producer_phase.value -ceq
            'M0_pre_request_clean_5s' -and
          [string]$eventProperties.producer_epoch.value -ceq
            'M0_pre_request_clean_5s')
      [long]$rawStart = [long]$eventProperties.raw_start_offset.value
      [long]$rawEnd = [long]$eventProperties.raw_end_offset_exclusive.value
      $rawRangeExact = ($M0GroundRawOffset -ge 0 -and
          $M0GateEndGroundRawOffset -ge $M0GroundRawOffset -and
          $rawStart -ge $M0GroundRawOffset -and $rawEnd -gt $rawStart -and
          $rawEnd -le $M0GateEndGroundRawOffset -and
          ($rawEnd - $rawStart) -eq 37)
      $elapsedExact = ([double]$eventProperties.elapsed_ms.value -ge 0.0)
    }
  }

  $causalValid = Get-EvidenceProperty -Object $CausalGate -Name 'valid'
  $parserIntegrity = Get-EvidenceProperty -Object $CausalGate `
      -Name 'parser_integrity'
  $parserValid = if ($parserIntegrity.found) {
    Get-EvidenceProperty -Object $parserIntegrity.value -Name 'valid'
  } else { [pscustomobject]@{found=$false;value=$null} }
  $targetCount = Get-EvidenceProperty -Object $CausalGate `
      -Name 'target_param_value_count'
  $parserBufferEmpty = Get-EvidenceProperty -Object $CausalGate `
      -Name 'parser_buffer_empty'
  $causalM0RawStart = Get-EvidenceProperty -Object $CausalGate `
      -Name 'm0_ground_raw_offset'
  $causalM0RawEnd = Get-EvidenceProperty -Object $CausalGate `
      -Name 'm0_gate_end_ground_raw_offset'
  $heartbeat = Get-EvidenceProperty -Object $CausalGate -Name 'heartbeat'
  $heartbeatValid = if ($heartbeat.found) {
    Get-EvidenceProperty -Object $heartbeat.value -Name 'valid'
  } else { [pscustomobject]@{found=$false;value=$null} }
  $heartbeatCount = if ($heartbeat.found) {
    Get-EvidenceProperty -Object $heartbeat.value -Name 'count'
  } else { [pscustomobject]@{found=$false;value=$null} }
  $backlog = Get-EvidenceProperty -Object $CausalGate `
      -Name 'pre_request_backlog_gate'
  $backlogValues = [ordered]@{}
  foreach ($backlogName in @(
      'm0_epoch_completed','valid','veto_event_count',
      'stale_param_value_count','stale_generic_count',
      'known_stat_runtime_sentinel_count','m0_event_count','m0_veto_events')) {
    $backlogValues[$backlogName] = if ($backlog.found) {
      Get-EvidenceProperty -Object $backlog.value -Name $backlogName
    } else { [pscustomobject]@{found=$false;value=$null} }
  }
  [bool]$backlogSchemaExact = (@($backlogValues.Values | Where-Object {
    -not $_.found
  }).Count -eq 0)
  [bool]$backlogEventSame = $false
  if ($backlogSchemaExact -and $events.Count -eq 1 -and
      @($backlogValues.m0_veto_events.value).Count -eq 1) {
    $backlogEvent = @($backlogValues.m0_veto_events.value)[0]
    $backlogEventRawStart = Get-EvidenceProperty -Object $backlogEvent `
        -Name 'raw_start_offset'
    $backlogEventRawEnd = Get-EvidenceProperty -Object $backlogEvent `
        -Name 'raw_end_offset_exclusive'
    $backlogEventSequence = Get-EvidenceProperty -Object $backlogEvent `
        -Name 'sequence'
    $eventRawStart = Get-EvidenceProperty -Object $event -Name 'raw_start_offset'
    $eventRawEnd = Get-EvidenceProperty -Object $event `
        -Name 'raw_end_offset_exclusive'
    $eventSequence = Get-EvidenceProperty -Object $event -Name 'sequence'
    $backlogEventSame = ($backlogEventRawStart.found -and
        $backlogEventRawEnd.found -and $backlogEventSequence.found -and
        $eventRawStart.found -and $eventRawEnd.found -and
        $eventSequence.found -and
        [long]$backlogEventRawStart.value -eq [long]$eventRawStart.value -and
        [long]$backlogEventRawEnd.value -eq [long]$eventRawEnd.value -and
        [int]$backlogEventSequence.value -eq [int]$eventSequence.value)
  }
  [bool]$causalExact = ($causalValid.found -and
      -not [bool]$causalValid.value -and $parserValid.found -and
      [bool]$parserValid.value -and $targetCount.found -and
      [int]$targetCount.value -eq 1 -and $parserBufferEmpty.found -and
      [bool]$parserBufferEmpty.value -and $heartbeatValid.found -and
      [bool]$heartbeatValid.value -and $heartbeatCount.found -and
      [int]$heartbeatCount.value -ge 2 -and $backlogSchemaExact -and
      [bool]$backlogValues.m0_epoch_completed.value -and
      -not [bool]$backlogValues.valid.value -and
      [int]$backlogValues.veto_event_count.value -eq 1 -and
      [int]$backlogValues.stale_param_value_count.value -eq 1 -and
      [int]$backlogValues.stale_generic_count.value -eq 0 -and
      [int]$backlogValues.known_stat_runtime_sentinel_count.value -eq 1 -and
      [int]$backlogValues.m0_event_count.value -eq 1 -and
      $causalM0RawStart.found -and $causalM0RawEnd.found -and
      [long]$causalM0RawStart.value -eq $M0GroundRawOffset -and
      [long]$causalM0RawEnd.value -eq $M0GateEndGroundRawOffset -and
      $backlogEventSame)

  foreach ($row in @(
      @('exactly_one_m0_event',($events.Count -eq 1)),
      @('event_schema_exact',$eventSchemaExact),@('crc_valid',$crcValid),
      @('message_22',$messageExact),@('payload_length_25',$payloadLengthExact),
      @('classification_known_stat_runtime',$classificationExact),
      @('anomaly_classes_empty',$anomalyFree),@('param_id_exact',$idExact),
      @('param_value_bits_exact',$valueExact),@('tuple_exact',$tupleExact),
      @('source_exact',$sourceExact),@('sequence_exact',$sequenceExact),
      @('producer_phase_epoch_exact',$producerExact),
      @('raw_range_exact',$rawRangeExact),@('elapsed_nonnegative',$elapsedExact),
      @('causal_exact_one_known_event',$causalExact))) {
    $checks.Add([pscustomobject][ordered]@{
      name=[string]$row[0];valid=[bool]$row[1]
    })
  }
  return [pscustomobject][ordered]@{
    schema_version=1
    classification='exact_observed_STAT_RUNTIME_partial_D7_race'
    valid=(@($checks | Where-Object {-not $_.valid}).Count -eq 0)
    m0_ground_raw_offset=$M0GroundRawOffset
    m0_gate_end_ground_raw_offset=$M0GateEndGroundRawOffset;events=$events
    pvid=$pvid.value;pvval=$pvval.value;pvidx=$pvidx.value;pvcnt=$pvcnt.value
    pvtype=$pvtype.value;pvseq=$pvseq.value;pvsys=$pvsys.value
    pvcomp=$pvcomp.value;causal_exact=$causalExact
    checks=$checks.ToArray();fixture_write_count=0
  }
}

function Test-ExactPostM0VehicleSnapshotStatRuntimePartialD7Race {
  param(
    [Parameter(Mandatory = $true)]$CausalGate,
    [Parameter(Mandatory = $true)]$OfficialVehicle,
    [Parameter(Mandatory = $true)]$OfficialGround,
    [Parameter(Mandatory = $true)]$PreRequestVehicle,
    [AllowNull()]$M0Capture,
    [AllowNull()]$DiagnosticEndBarrier,
    [Parameter(Mandatory = $true)]
    [AllowEmptyCollection()][object[]]$M0Events
  )
  function Get-PostM0EvidenceProperty {
    param([AllowNull()]$Object,[Parameter(Mandatory=$true)][string]$Name)
    if ($null -eq $Object) {
      return [pscustomobject]@{found=$false;value=$null}
    }
    $property = $Object.PSObject.Properties[$Name]
    if ($null -eq $property) {
      return [pscustomobject]@{found=$false;value=$null}
    }
    return [pscustomobject]@{found=$true;value=$property.Value}
  }

  [object[]]$events = [object[]]@($M0Events)
  $checks = New-Object 'System.Collections.Generic.List[object]'
  $pvid = Get-SnapshotString -Snapshot $PreRequestVehicle -Key 'pvid'
  $pvval = Get-SnapshotString -Snapshot $PreRequestVehicle -Key 'pvval'
  $pvidx = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvidx'
  $pvcnt = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvcnt'
  $pvtype = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvtype'
  $pvseq = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvseq'
  $pvsys = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvsys'
  $pvcomp = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvcomp'

  [bool]$eventSchemaExact = $false
  [bool]$crcValid = $false
  [bool]$messageExact = $false
  [bool]$payloadLengthExact = $false
  [bool]$classificationExact = $false
  [bool]$anomalyFree = $false
  [bool]$idExact = $false
  [bool]$valueExact = $false
  [bool]$tupleExact = $false
  [bool]$sourceExact = $false
  [bool]$sequenceExact = $false
  [bool]$producerExact = $false
  [bool]$rawRangeExact = $false
  [bool]$elapsedRangeExact = $false
  [long]$rawStart = -1
  [long]$rawEnd = -1
  [double]$eventElapsedMs = -1.0
  $event = $null

  $snapshotName = Get-PostM0EvidenceProperty -Object $PreRequestVehicle `
      -Name 'name'
  $snapshotStatus = Get-PostM0EvidenceProperty -Object $PreRequestVehicle `
      -Name 'status'
  $snapshotQueryCount = Get-PostM0EvidenceProperty `
      -Object $PreRequestVehicle -Name 'query_count'
  $snapshotQueryAttemptCount = Get-PostM0EvidenceProperty `
      -Object $PreRequestVehicle -Name 'query_attempt_count'
  $snapshotWriteTimedOut = Get-PostM0EvidenceProperty `
      -Object $PreRequestVehicle -Name 'write_timed_out'
  $snapshotAbsoluteDeadlineReached = Get-PostM0EvidenceProperty `
      -Object $PreRequestVehicle -Name 'absolute_deadline_reached'
  $snapshotStarted = Get-PostM0EvidenceProperty -Object $PreRequestVehicle `
      -Name 'started_elapsed_ms'
  $snapshotFinished = Get-PostM0EvidenceProperty -Object $PreRequestVehicle `
      -Name 'finished_elapsed_ms'
  $queryStartBarrier = Get-PostM0EvidenceProperty -Object $PreRequestVehicle `
      -Name 'capture_start_barrier'
  $queryStartBarrierActive = if ($queryStartBarrier.found) {
    Get-PostM0EvidenceProperty -Object $queryStartBarrier.value -Name 'active'
  } else { [pscustomobject]@{found=$false;value=$null} }
  $diagnosticRawStart = if ($queryStartBarrier.found) {
    Get-PostM0EvidenceProperty -Object $queryStartBarrier.value `
        -Name 'ground_raw_offset_exclusive'
  } else { [pscustomobject]@{found=$false;value=$null} }
  $diagnosticStartElapsed = if ($queryStartBarrier.found) {
    Get-PostM0EvidenceProperty -Object $queryStartBarrier.value `
        -Name 'ground_boundary_elapsed_ms'
  } else { [pscustomobject]@{found=$false;value=$null} }
  $diagnosticEndBarrierActive = Get-PostM0EvidenceProperty `
      -Object $DiagnosticEndBarrier -Name 'active'
  $diagnosticRawEnd = Get-PostM0EvidenceProperty `
      -Object $DiagnosticEndBarrier -Name 'ground_raw_offset_exclusive'
  $diagnosticEndElapsed = Get-PostM0EvidenceProperty `
      -Object $DiagnosticEndBarrier -Name 'ground_boundary_elapsed_ms'

  $m0Started = Get-PostM0EvidenceProperty -Object $M0Capture `
      -Name 'started_elapsed_ms'
  $m0Requested = Get-PostM0EvidenceProperty -Object $M0Capture `
      -Name 'requested_milliseconds'
  $m0Target = Get-PostM0EvidenceProperty -Object $M0Capture `
      -Name 'target_elapsed_ms'
  $m0EffectiveEnd = Get-PostM0EvidenceProperty -Object $M0Capture `
      -Name 'effective_end_elapsed_ms'
  $m0Finished = Get-PostM0EvidenceProperty -Object $M0Capture `
      -Name 'finished_elapsed_ms'
  $m0Completed = Get-PostM0EvidenceProperty -Object $M0Capture `
      -Name 'completed_duration'
  $m0DeadlineReached = Get-PostM0EvidenceProperty -Object $M0Capture `
      -Name 'deadline_reached'
  $m0StartBarrier = Get-PostM0EvidenceProperty -Object $M0Capture `
      -Name 'start_barrier'
  $m0StartBarrierActive = if ($m0StartBarrier.found) {
    Get-PostM0EvidenceProperty -Object $m0StartBarrier.value -Name 'active'
  } else { [pscustomobject]@{found=$false;value=$null} }
  $m0StartRawOffset = if ($m0StartBarrier.found) {
    Get-PostM0EvidenceProperty -Object $m0StartBarrier.value `
        -Name 'ground_raw_offset_exclusive'
  } else { [pscustomobject]@{found=$false;value=$null} }
  $m0StartBoundaryElapsed = if ($m0StartBarrier.found) {
    Get-PostM0EvidenceProperty -Object $m0StartBarrier.value `
        -Name 'ground_boundary_elapsed_ms'
  } else { [pscustomobject]@{found=$false;value=$null} }
  [bool]$m0CaptureExact = ($m0Started.found -and $m0Requested.found -and
      $m0Target.found -and $m0EffectiveEnd.found -and $m0Finished.found -and
      $m0Completed.found -and $m0DeadlineReached.found -and
      $m0StartBarrierActive.found -and [bool]$m0StartBarrierActive.value -and
      $m0StartRawOffset.found -and [long]$m0StartRawOffset.value -ge 0 -and
      $m0StartBoundaryElapsed.found -and
      [double]$m0StartBoundaryElapsed.value -le [double]$m0Started.value -and
      [int]$m0Requested.value -eq 5000 -and [bool]$m0Completed.value -and
      -not [bool]$m0DeadlineReached.value -and
      [double]$m0EffectiveEnd.value -eq [double]$m0Target.value -and
      [double]$m0Target.value - [double]$m0Started.value -ge 5000.0 -and
      [double]$m0Finished.value -ge [double]$m0Target.value)
  [bool]$snapshotEnvelopeExact = ($snapshotName.found -and
      [string]$snapshotName.value -match '^pre_request_vehicle_[1-3]$' -and
      $snapshotStatus.found -and [string]$snapshotStatus.value -ceq 'COMPLETE' -and
      $snapshotQueryCount.found -and [int]$snapshotQueryCount.value -eq 1 -and
      $snapshotQueryAttemptCount.found -and
      [int]$snapshotQueryAttemptCount.value -eq 1 -and
      $snapshotWriteTimedOut.found -and
      -not [bool]$snapshotWriteTimedOut.value -and
      $snapshotAbsoluteDeadlineReached.found -and
      -not [bool]$snapshotAbsoluteDeadlineReached.value -and
      $snapshotStarted.found -and $snapshotFinished.found -and
      [double]$snapshotFinished.value -ge [double]$snapshotStarted.value)
  [bool]$brokerBoundaryExact = ($queryStartBarrierActive.found -and
      [bool]$queryStartBarrierActive.value -and $diagnosticRawStart.found -and
      [long]$diagnosticRawStart.value -ge 0 -and
      $diagnosticStartElapsed.found -and
      $diagnosticEndBarrierActive.found -and
      [bool]$diagnosticEndBarrierActive.value -and $diagnosticRawEnd.found -and
      [long]$diagnosticRawEnd.value -ge [long]$diagnosticRawStart.value -and
      $diagnosticEndElapsed.found -and
      [double]$diagnosticEndElapsed.value -ge
        [double]$diagnosticStartElapsed.value)
  [bool]$m0BeforeSnapshotExact = ($m0CaptureExact -and
      $snapshotEnvelopeExact -and $diagnosticStartElapsed.found -and
      [double]$m0Finished.value -le [double]$diagnosticStartElapsed.value -and
      [double]$diagnosticStartElapsed.value -le
        [double]$snapshotStarted.value -and
      $diagnosticEndElapsed.found -and
      [double]$snapshotFinished.value -le
        [double]$diagnosticEndElapsed.value)

  if ($events.Count -eq 1) {
    $event = $events[0]
    $eventProperties = [ordered]@{}
    foreach ($eventPropertyName in @(
        'crc_valid','message_id','payload_length','classification',
        'anomaly_classes','param_id','param_id_hex','param_value_hex',
        'param_value_bits_hex','param_index','param_count','param_type',
        'system_id','component_id','sequence','capture_scope',
        'producer_phase','producer_epoch','raw_start_offset',
        'raw_end_offset_exclusive','elapsed_ms')) {
      $eventProperties[$eventPropertyName] = Get-PostM0EvidenceProperty `
          -Object $event -Name $eventPropertyName
    }
    $eventSchemaExact = (@($eventProperties.Values | Where-Object {
      -not $_.found
    }).Count -eq 0)
    if ($eventSchemaExact) {
      $crcValid = ([bool]$eventProperties.crc_valid.value -eq $true)
      $messageExact = ([int]$eventProperties.message_id.value -eq 22)
      $payloadLengthExact = ([int]$eventProperties.payload_length.value -eq 25)
      $classificationExact = ([string]$eventProperties.classification.value `
          -ceq 'known_STAT_RUNTIME_sentinel')
      $anomalyFree = (@($eventProperties.anomaly_classes.value).Count -eq 0)
      $idExact = ($pvid.found -and
          [string]$pvid.value -ceq 'STAT_RUNTIME' -and
          [string]$eventProperties.param_id.value -ceq 'STAT_RUNTIME' -and
          [string]$eventProperties.param_id_hex.value -ceq
            $script:ExpectedStatRuntimeIdHex)
      $valueExact = ($pvval.found -and
          [string]$eventProperties.param_value_hex.value -ceq
            [string]$pvval.value -and
          [string]$eventProperties.param_value_bits_hex.value -ceq
            [string]$pvval.value)
      $tupleExact = ($pvidx.found -and [uint64]$pvidx.value -eq 65535 -and
          $pvcnt.found -and [uint64]$pvcnt.value -eq 932 -and
          $pvtype.found -and [uint64]$pvtype.value -eq 6 -and
          [int]$eventProperties.param_index.value -eq [int]$pvidx.value -and
          [int]$eventProperties.param_count.value -eq [int]$pvcnt.value -and
          [int]$eventProperties.param_type.value -eq [int]$pvtype.value)
      $sourceExact = ($pvsys.found -and [uint64]$pvsys.value -eq 1 -and
          $pvcomp.found -and [uint64]$pvcomp.value -eq 1 -and
          [int]$eventProperties.system_id.value -eq [int]$pvsys.value -and
          [int]$eventProperties.component_id.value -eq [int]$pvcomp.value)
      $sequenceExact = ($pvseq.found -and [uint64]$pvseq.value -le 255 -and
          [int]$eventProperties.sequence.value -eq [int]$pvseq.value)
      $producerExact = ($snapshotName.found -and
          [string]$eventProperties.capture_scope.value -ceq 'pre_request_m0' -and
          [string]$eventProperties.producer_phase.value -ceq
            [string]$snapshotName.value -and
          [string]$eventProperties.producer_epoch.value -ceq
            [string]$snapshotName.value)
      $rawStart = [long]$eventProperties.raw_start_offset.value
      $rawEnd = [long]$eventProperties.raw_end_offset_exclusive.value
      $eventElapsedMs = [double]$eventProperties.elapsed_ms.value
      $rawRangeExact = ($brokerBoundaryExact -and
          $rawStart -ge [long]$diagnosticRawStart.value -and
          $rawEnd -gt $rawStart -and
          $rawEnd -le [long]$diagnosticRawEnd.value -and
          ($rawEnd - $rawStart) -eq 37)
      $elapsedRangeExact = ($m0BeforeSnapshotExact -and
          $eventElapsedMs -gt [double]$m0Finished.value -and
          $eventElapsedMs -ge [double]$snapshotStarted.value -and
          $eventElapsedMs -le [double]$snapshotFinished.value -and
          $eventElapsedMs -le [double]$diagnosticEndElapsed.value)
    }
  }

  $causalValid = Get-PostM0EvidenceProperty -Object $CausalGate -Name 'valid'
  $parserIntegrity = Get-PostM0EvidenceProperty -Object $CausalGate `
      -Name 'parser_integrity'
  $parserValid = if ($parserIntegrity.found) {
    Get-PostM0EvidenceProperty -Object $parserIntegrity.value -Name 'valid'
  } else { [pscustomobject]@{found=$false;value=$null} }
  $targetCount = Get-PostM0EvidenceProperty -Object $CausalGate `
      -Name 'target_param_value_count'
  $parserBufferEmpty = Get-PostM0EvidenceProperty -Object $CausalGate `
      -Name 'parser_buffer_empty'
  $causalM0RawStart = Get-PostM0EvidenceProperty -Object $CausalGate `
      -Name 'm0_ground_raw_offset'
  $causalM0RawEnd = Get-PostM0EvidenceProperty -Object $CausalGate `
      -Name 'm0_gate_end_ground_raw_offset'
  $heartbeat = Get-PostM0EvidenceProperty -Object $CausalGate -Name 'heartbeat'
  $heartbeatValid = if ($heartbeat.found) {
    Get-PostM0EvidenceProperty -Object $heartbeat.value -Name 'valid'
  } else { [pscustomobject]@{found=$false;value=$null} }
  $heartbeatCount = if ($heartbeat.found) {
    Get-PostM0EvidenceProperty -Object $heartbeat.value -Name 'count'
  } else { [pscustomobject]@{found=$false;value=$null} }
  $backlog = Get-PostM0EvidenceProperty -Object $CausalGate `
      -Name 'pre_request_backlog_gate'
  $backlogValues = [ordered]@{}
  foreach ($backlogName in @(
      'decision_scope','m0_epoch_completed','valid','veto_event_count',
      'historical_readiness_event_count','readiness_events_audit_only',
      'm0_event_count','m0_veto_events')) {
    $backlogValues[$backlogName] = if ($backlog.found) {
      Get-PostM0EvidenceProperty -Object $backlog.value -Name $backlogName
    } else { [pscustomobject]@{found=$false;value=$null} }
  }
  [bool]$backlogSchemaExact = (@($backlogValues.Values | Where-Object {
    -not $_.found
  }).Count -eq 0)
  [bool]$freshM0PartitionExact = ($backlogSchemaExact -and
      [string]$backlogValues.decision_scope.value -ceq 'fresh_m0_only' -and
      [bool]$backlogValues.m0_epoch_completed.value -and
      -not [bool]$backlogValues.valid.value -and
      [int]$backlogValues.veto_event_count.value -eq 1 -and
      [int]$backlogValues.historical_readiness_event_count.value -ge 0 -and
      [bool]$backlogValues.readiness_events_audit_only.value -and
      [int]$backlogValues.m0_event_count.value -eq 1 -and
      @($backlogValues.m0_veto_events.value).Count -eq 1)
  [bool]$backlogEventSame = $false
  if ($freshM0PartitionExact -and $events.Count -eq 1) {
    $backlogEvent = @($backlogValues.m0_veto_events.value)[0]
    $backlogRawStart = Get-PostM0EvidenceProperty -Object $backlogEvent `
        -Name 'raw_start_offset'
    $backlogRawEnd = Get-PostM0EvidenceProperty -Object $backlogEvent `
        -Name 'raw_end_offset_exclusive'
    $backlogSequence = Get-PostM0EvidenceProperty -Object $backlogEvent `
        -Name 'sequence'
    $backlogParamId = Get-PostM0EvidenceProperty -Object $backlogEvent `
        -Name 'param_id'
    $backlogValue = Get-PostM0EvidenceProperty -Object $backlogEvent `
        -Name 'param_value_bits_hex'
    $backlogEventSame = ($backlogRawStart.found -and $backlogRawEnd.found -and
        $backlogSequence.found -and $backlogParamId.found -and
        $backlogValue.found -and
        [long]$backlogRawStart.value -eq $rawStart -and
        [long]$backlogRawEnd.value -eq $rawEnd -and
        [int]$backlogSequence.value -eq [int]$event.sequence -and
        [string]$backlogParamId.value -ceq [string]$event.param_id -and
        [string]$backlogValue.value -ceq [string]$event.param_value_bits_hex)
  }
  [bool]$causalPartitionExact = ($causalValid.found -and
      -not [bool]$causalValid.value -and $parserValid.found -and
      [bool]$parserValid.value -and $targetCount.found -and
      [int]$targetCount.value -eq 1 -and $parserBufferEmpty.found -and
      [bool]$parserBufferEmpty.value -and $heartbeatValid.found -and
      [bool]$heartbeatValid.value -and $heartbeatCount.found -and
      [int]$heartbeatCount.value -ge 2 -and $freshM0PartitionExact -and
      $causalM0RawStart.found -and [long]$causalM0RawStart.value -ge 0 -and
      $m0StartRawOffset.found -and
      [long]$causalM0RawStart.value -eq [long]$m0StartRawOffset.value -and
      $causalM0RawEnd.found -and
      [long]$causalM0RawEnd.value -ge [long]$causalM0RawStart.value -and
      $diagnosticRawStart.found -and
      [long]$causalM0RawEnd.value -eq [long]$diagnosticRawStart.value -and
      $backlogEventSame)
  [bool]$officialSnapshotsComplete = ($null -ne $OfficialVehicle -and
      $null -ne $OfficialGround -and $OfficialVehicle.status -ceq 'COMPLETE' -and
      $OfficialGround.status -ceq 'COMPLETE')

  foreach ($row in @(
      @('official_snapshots_complete',$officialSnapshotsComplete),
      @('m0_completed_exact_5000ms',$m0CaptureExact),
      @('snapshot_envelope_exact',$snapshotEnvelopeExact),
      @('broker_boundaries_exact',$brokerBoundaryExact),
      @('m0_finished_before_snapshot',$m0BeforeSnapshotExact),
      @('exactly_one_fresh_m0_event',($events.Count -eq 1)),
      @('event_schema_exact',$eventSchemaExact),@('crc_valid',$crcValid),
      @('message_22',$messageExact),@('payload_length_25',$payloadLengthExact),
      @('classification_known_stat_runtime',$classificationExact),
      @('anomaly_classes_empty',$anomalyFree),@('param_id_exact',$idExact),
      @('param_value_bits_exact',$valueExact),@('tuple_exact',$tupleExact),
      @('source_exact',$sourceExact),@('sequence_exact',$sequenceExact),
      @('producer_same_vehicle_snapshot',$producerExact),
      @('diagnostic_raw_range_exact',$rawRangeExact),
      @('post_m0_snapshot_elapsed_range_exact',$elapsedRangeExact),
      @('fresh_m0_partition_exact',$freshM0PartitionExact),
      @('causal_partition_exact',$causalPartitionExact))) {
    $checks.Add([pscustomobject][ordered]@{
      name=[string]$row[0];valid=[bool]$row[1]
    })
  }
  return [pscustomobject][ordered]@{
    schema_version=1
    classification='exact_post_M0_vehicle_snapshot_STAT_RUNTIME_partial_D7_race'
    valid=(@($checks | Where-Object {-not $_.valid}).Count -eq 0)
    m0_capture=$M0Capture;snapshot_name=$snapshotName.value
    diagnostic_raw_start_offset=$diagnosticRawStart.value
    diagnostic_raw_end_offset=$diagnosticRawEnd.value
    diagnostic_start_elapsed_ms=$diagnosticStartElapsed.value
    diagnostic_end_elapsed_ms=$diagnosticEndElapsed.value
    event_elapsed_ms=$eventElapsedMs;events=$events
    pvid=$pvid.value;pvval=$pvval.value;pvidx=$pvidx.value;pvcnt=$pvcnt.value
    pvtype=$pvtype.value;pvseq=$pvseq.value;pvsys=$pvsys.value
    pvcomp=$pvcomp.value;fresh_m0_partition_exact=$freshM0PartitionExact
    causal_partition_exact=$causalPartitionExact
    checks=$checks.ToArray();fixture_write_count=0
  }
}

function Test-IsolatedPartialD7SnapshotRaceContract {
  param(
    [Parameter(Mandatory = $true)]$CausalGate,
    [Parameter(Mandatory = $true)]$PreRequestVehicleGate,
    [Parameter(Mandatory = $true)]$OfficialVehicle,
    [Parameter(Mandatory = $true)]$OfficialGround,
    [Parameter(Mandatory = $true)]$PreRequestVehicle,
    [Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$M0Events
  )
  $checks = New-Object 'System.Collections.Generic.List[object]'
  function Add-IsolatedD7Check {
    param([string]$Name, [bool]$Valid, $Actual = $null,
          $Expected = $true)
    $checks.Add([pscustomobject][ordered]@{
      name=$Name;expected=$Expected;actual=$Actual;valid=$Valid
    })
  }

  [string[]]$failedNames = [string[]]@(
    $PreRequestVehicleGate.checks | Where-Object {-not $_.valid} |
      ForEach-Object {[string]$_.name})
  [string[]]$requiredVehicleCheckNames = [string[]]@(
      'response_exact','same_boot','q_next','ms_increasing','d722_stable',
      'd722_rf22_reconciled','pgq','pga','prq','ptq','ef',
      'related_drop_error_zero_pvbad','related_drop_error_zero_pvov',
      'related_drop_error_zero_eo','related_drop_error_zero_evo',
      'd7pb_empty','related_drop_error_zero')
  [bool]$vehicleGateShapeExact = (-not [bool]$PreRequestVehicleGate.valid -and
      @($PreRequestVehicleGate.checks).Count -eq
        $requiredVehicleCheckNames.Count)
  foreach ($requiredVehicleCheckName in $requiredVehicleCheckNames) {
    [object[]]$matchingVehicleChecks = [object[]]@(
        $PreRequestVehicleGate.checks | Where-Object {
          [string]$_.name -ceq $requiredVehicleCheckName
        })
    [bool]$requiredCheckValid = $false
    if ($requiredVehicleCheckName -ceq 'd7pb_empty') {
      $requiredCheckValid = ($matchingVehicleChecks.Count -eq 1 -and
          -not [bool]$matchingVehicleChecks[0].valid)
    } else {
      $requiredCheckValid = ($matchingVehicleChecks.Count -eq 1 -and
          [bool]$matchingVehicleChecks[0].valid)
    }
    if (-not $requiredCheckValid) { $vehicleGateShapeExact = $false }
  }
  Add-IsolatedD7Check -Name 'vehicle_gate_shape_exact' `
      -Valid $vehicleGateShapeExact -Actual ([ordered]@{
        gate_valid=[bool]$PreRequestVehicleGate.valid
        check_names=[string[]]@($PreRequestVehicleGate.checks.name)
      }) -Expected 'all required checks pass except d7pb_empty'
  Add-IsolatedD7Check -Name 'only_d7pb_empty_failed' `
      -Valid ($failedNames.Count -eq 1 -and
        $failedNames[0] -ceq 'd7pb_empty') `
      -Actual ($failedNames -join ',') -Expected 'd7pb_empty'

  [object[]]$events = [object[]]@($M0Events)
  [bool]$m0EpochCompleted =
      [bool]$CausalGate.pre_request_backlog_gate.m0_epoch_completed
  [bool]$parserClean = [bool]$CausalGate.parser_integrity.valid
  [bool]$heartbeatClean = ([bool]$CausalGate.heartbeat.valid -and
      [int]$CausalGate.heartbeat.count -ge 2)
  Add-IsolatedD7Check -Name 'causal_gate_valid' `
      -Valid ([bool]$CausalGate.valid) -Actual ([bool]$CausalGate.valid)
  Add-IsolatedD7Check -Name 'm0_epoch_completed' -Valid $m0EpochCompleted `
      -Actual $m0EpochCompleted
  Add-IsolatedD7Check -Name 'parser_integrity_valid' -Valid $parserClean `
      -Actual $parserClean
  Add-IsolatedD7Check -Name 'heartbeat_valid' -Valid $heartbeatClean `
      -Actual $heartbeatClean
  Add-IsolatedD7Check -Name 'm0_events_empty' -Valid ($events.Count -eq 0) `
      -Actual $events.Count -Expected 0

  [bool]$snapshotsComplete = (
      [string]$OfficialVehicle.status -ceq 'COMPLETE' -and
      [string]$OfficialGround.status -ceq 'COMPLETE' -and
      [string]$PreRequestVehicle.status -ceq 'COMPLETE')
  Add-IsolatedD7Check -Name 'snapshots_complete' -Valid $snapshotsComplete `
      -Actual ([ordered]@{official_vehicle=$OfficialVehicle.status
        official_ground=$OfficialGround.status
        current_vehicle=$PreRequestVehicle.status}) -Expected 'COMPLETE'

  $officialD7pb = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'd7pb'
  $currentD7pb = Get-SnapshotUInt64 `
      -Snapshot $PreRequestVehicle -Key 'd7pb'
  [bool]$partialBounded = ($officialD7pb.found -and
      [uint64]$officialD7pb.value -eq 0 -and $currentD7pb.found -and
      [uint64]$currentD7pb.value -ge 1 -and
      [uint64]$currentD7pb.value -le 279)
  Add-IsolatedD7Check -Name 'd7pb_official_empty_current_bounded' `
      -Valid $partialBounded `
      -Actual ([ordered]@{official=$officialD7pb.value;current=$currentD7pb.value}) `
      -Expected 'official=0,current=1..279'

  $officialBoot = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'boot'
  $currentBoot = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'boot'
  [bool]$sameBoot = ($officialBoot.found -and $currentBoot.found -and
      [uint64]$officialBoot.value -ne 0 -and
      [uint64]$officialBoot.value -eq [uint64]$currentBoot.value)
  Add-IsolatedD7Check -Name 'same_nonzero_boot' -Valid $sameBoot `
      -Actual ([ordered]@{official=$officialBoot.value;current=$currentBoot.value})

  $officialD722 = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'd722'
  $currentD722 = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'd722'
  $officialPvok = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'pvok'
  $currentPvok = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvok'
  $officialRf22 = Get-SnapshotUInt64 -Snapshot $OfficialGround -Key 'rf22'
  $d722Delta = Get-SnapshotDelta -Baseline $OfficialVehicle `
      -Post $PreRequestVehicle -Key 'd722'
  $pvokDelta = Get-SnapshotDelta -Baseline $OfficialVehicle `
      -Post $PreRequestVehicle -Key 'pvok'
  [bool]$parameterCountersStable = ($d722Delta.found -and
      $d722Delta.monotonic -and [uint64]$d722Delta.delta -eq 0 -and
      $pvokDelta.found -and $pvokDelta.monotonic -and
      [uint64]$pvokDelta.delta -eq 0 -and $officialD722.found -and
      $currentD722.found -and $officialPvok.found -and $currentPvok.found -and
      $officialRf22.found -and [uint64]$officialD722.value -eq
        [uint64]$officialPvok.value -and [uint64]$officialD722.value -eq
        [uint64]$officialRf22.value -and [uint64]$currentD722.value -eq
        [uint64]$currentPvok.value -and [uint64]$currentD722.value -eq
        [uint64]$officialRf22.value)
  Add-IsolatedD7Check -Name 'parameter_counters_stable_reconciled' `
      -Valid $parameterCountersStable `
      -Actual ([ordered]@{d722_delta=$d722Delta.delta
        pvok_delta=$pvokDelta.delta;rf22=$officialRf22.value}) `
      -Expected 'd722_delta=0,pvok_delta=0,d722=pvok=rf22'

  [bool]$observerUnchanged = $true
  $observerEvidence = [ordered]@{}
  foreach ($key in @('pvid','pvval')) {
    $before = Get-SnapshotString -Snapshot $OfficialVehicle -Key $key
    $after = Get-SnapshotString -Snapshot $PreRequestVehicle -Key $key
    $observerEvidence[$key] = [ordered]@{
      before=$before.value;after=$after.value
    }
    if (-not $before.found -or -not $after.found -or
        [string]$before.value -cne [string]$after.value) {
      $observerUnchanged = $false
    }
  }
  foreach ($key in @(
      'pvidx','pvcnt','pvtype','pvseq','pvsys','pvcomp','pvms')) {
    $delta = Get-SnapshotDelta -Baseline $OfficialVehicle `
        -Post $PreRequestVehicle -Key $key
    $observerEvidence[$key] = [ordered]@{
      before=$delta.before;after=$delta.after;delta=$delta.delta
    }
    if (-not $delta.found -or -not $delta.monotonic -or
        [uint64]$delta.delta -ne 0) { $observerUnchanged = $false }
  }
  $lastId = Get-SnapshotString -Snapshot $PreRequestVehicle -Key 'pvid'
  $lastIndex = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvidx'
  $lastCount = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvcnt'
  $lastType = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvtype'
  $lastSystem = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvsys'
  $lastComponent = Get-SnapshotUInt64 `
      -Snapshot $PreRequestVehicle -Key 'pvcomp'
  [bool]$knownObserverTuple = ($lastId.found -and
      [string]$lastId.value -ceq 'STAT_RUNTIME' -and $lastIndex.found -and
      [uint64]$lastIndex.value -eq 65535 -and $lastCount.found -and
      [uint64]$lastCount.value -eq 932 -and $lastType.found -and
      [uint64]$lastType.value -eq 6 -and $lastSystem.found -and
      [uint64]$lastSystem.value -eq 1 -and $lastComponent.found -and
      [uint64]$lastComponent.value -eq 1)
  Add-IsolatedD7Check -Name 'last_param_observer_unchanged' `
      -Valid ($observerUnchanged -and $knownObserverTuple) `
      -Actual $observerEvidence `
      -Expected 'unchanged known STAT_RUNTIME tuple'

  [bool]$queuesEmpty = $true
  $queueEvidence = [ordered]@{}
  foreach ($key in @('pgq','pga','prq','ptq','pvs1')) {
    $before = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key $key
    $after = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key $key
    $queueEvidence[$key] = [ordered]@{
      official=$before.value;current=$after.value
    }
    if (-not $before.found -or -not $after.found -or
        [uint64]$before.value -ne 0 -or [uint64]$after.value -ne 0) {
      $queuesEmpty = $false
    }
  }
  Add-IsolatedD7Check -Name 'all_parameter_queues_empty' `
      -Valid $queuesEmpty -Actual $queueEvidence -Expected 0

  [bool]$errorsZero = $true
  $errorEvidence = [ordered]@{}
  foreach ($key in @('ef','pvbad','pvov','eo','evo','d6cr','d7cr')) {
    $before = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key $key
    $after = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key $key
    $errorEvidence[$key] = [ordered]@{
      official=$before.value;current=$after.value
    }
    if (-not $before.found -or -not $after.found -or
        [uint64]$before.value -ne 0 -or [uint64]$after.value -ne 0) {
      $errorsZero = $false
    }
  }
  Add-IsolatedD7Check -Name 'transport_and_parser_errors_zero' `
      -Valid $errorsZero -Actual $errorEvidence -Expected 0

  $d7Bytes = Get-SnapshotDelta -Baseline $OfficialVehicle `
      -Post $PreRequestVehicle -Key 'd7b'
  $d7Frames = Get-SnapshotDelta -Baseline $OfficialVehicle `
      -Post $PreRequestVehicle -Key 'd7f'
  $d7Invalid = Get-SnapshotDelta -Baseline $OfficialVehicle `
      -Post $PreRequestVehicle -Key 'd7iv'
  [bool]$d7Active = ($d7Bytes.found -and $d7Bytes.monotonic -and
      [uint64]$d7Bytes.delta -gt 0 -and $d7Frames.found -and
      $d7Frames.monotonic -and $d7Invalid.found -and $d7Invalid.monotonic -and
      ([uint64]$d7Frames.delta + [uint64]$d7Invalid.delta) -gt 0)
  Add-IsolatedD7Check -Name 'd7_stream_active_and_monotonic' `
      -Valid $d7Active `
      -Actual ([ordered]@{d7b_delta=$d7Bytes.delta
        d7f_delta=$d7Frames.delta;d7iv_delta=$d7Invalid.delta})

  return [pscustomobject][ordered]@{
    schema_version=1
    classification='exact_isolated_partial_D7_snapshot_race'
    valid=(@($checks | Where-Object {-not $_.valid}).Count -eq 0)
    failed_vehicle_check_names=$failedNames
    official_d7pb=$officialD7pb.value;current_d7pb=$currentD7pb.value
    d722_delta=$d722Delta;pvok_delta=$pvokDelta
    observer_unchanged=$observerUnchanged
    queue_evidence=$queueEvidence;error_evidence=$errorEvidence
    d7b_delta=$d7Bytes;d7f_delta=$d7Frames;d7iv_delta=$d7Invalid
    checks=$checks.ToArray();fixture_write_count=0
  }
}

function Get-PreRequestAttemptDisposition {
  param(
    [Parameter(Mandatory = $true)]$CausalGate,
    [Parameter(Mandatory = $true)]$PreRequestVehicleGate,
    [Parameter(Mandatory = $true)]$OfficialVehicle,
    [Parameter(Mandatory = $true)]$OfficialGround,
    [Parameter(Mandatory = $true)]$PreRequestVehicle,
    [Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$M0Events,
    [AllowNull()]$PreM0TailEvidence = $null,
    [AllowNull()]$M0Capture = $null,
    [AllowNull()]$DiagnosticEndBarrier = $null,
    [long]$M0GroundRawOffset = -1,
    [long]$M0GateEndGroundRawOffset = -1,
    [Parameter(Mandatory = $true)][int]$AttemptNumber,
    [int]$MaxAttempts = 3,
    [Parameter(Mandatory = $true)][bool]$RetryBudgetAvailable,
    [bool]$IsolatedPartialD7ExtraRetryAvailable = $false,
    [bool]$ExactObservedStatRuntimeExtraRetryAvailable = $false
  )
  [object[]]$events = [object[]]@($M0Events)
  [object[]]$failedVehicleChecks = [object[]]@(
      $PreRequestVehicleGate.checks | Where-Object {-not $_.valid})
  [object[]]$failedVehicleNames = [object[]]@(
      $failedVehicleChecks | ForEach-Object {[string]$_.name})
  [string[]]$allowedVehicleFailures = [string[]]@(
      'd722_stable','d722_rf22_reconciled','pgq')
  [bool]$onlyAllowedVehicleFailures = ($failedVehicleNames.Count -ge 2 -and
      @($failedVehicleNames | Where-Object {
        $allowedVehicleFailures -cnotcontains $_
      }).Count -eq 0 -and
       $failedVehicleNames -ccontains 'd722_stable' -and
       $failedVehicleNames -ccontains 'd722_rf22_reconciled')
  [bool]$exactActiveVehicleFailureSet = ($failedVehicleNames.Count -eq 4 -and
      $failedVehicleNames -ccontains 'd722_stable' -and
      $failedVehicleNames -ccontains 'd722_rf22_reconciled' -and
      $failedVehicleNames -ccontains 'pgq' -and
      $failedVehicleNames -ccontains 'pga')
  [bool]$exactSilentQueuedVehicleFailureSet = (
      $failedVehicleNames.Count -eq 3 -and
      $failedVehicleNames -ccontains 'd722_stable' -and
      $failedVehicleNames -ccontains 'd722_rf22_reconciled' -and
      $failedVehicleNames -ccontains 'pgq')
  [bool]$exactSilentVehicleFailureSet = ($failedVehicleNames.Count -eq 2 -and
      $failedVehicleNames -ccontains 'd722_stable' -and
      $failedVehicleNames -ccontains 'd722_rf22_reconciled')
  [bool]$exactSilentPartialVehicleFailureSet = (
      $failedVehicleNames.Count -eq 3 -and
      $failedVehicleNames -ccontains 'd722_stable' -and
      $failedVehicleNames -ccontains 'd722_rf22_reconciled' -and
      $failedVehicleNames -ccontains 'd7pb_empty')
  [bool]$exactPostM0SnapshotVehicleFailureSet = (
      $failedVehicleNames.Count -eq 4 -and
      $failedVehicleNames -ccontains 'd722_stable' -and
      $failedVehicleNames -ccontains 'd722_rf22_reconciled' -and
      $failedVehicleNames -ccontains 'pgq' -and
      $failedVehicleNames -ccontains 'd7pb_empty')
  [bool]$m0EpochCompleted = [bool]$CausalGate.pre_request_backlog_gate.m0_epoch_completed
  [bool]$parserClean = [bool]$CausalGate.parser_integrity.valid
  [bool]$heartbeatClean = ([bool]$CausalGate.heartbeat.valid -and
      [int]$CausalGate.heartbeat.count -ge 2)
  [object[]]$knownEvents = [object[]]@($events | Where-Object {
      $_.classification -ceq 'known_STAT_RUNTIME_sentinel'
    })
  [int]$unknownOrIndexedCount = @($events | Where-Object {
      $_.classification -ne 'known_STAT_RUNTIME_sentinel'
    }).Count
  [bool]$allAnomalyClassesEmpty = (@($events | Where-Object {
      @($_.anomaly_classes).Count -ne 0
    }).Count -eq 0)
  [bool]$exactKnownEvent = ($events.Count -eq 1 -and
      $knownEvents.Count -eq 1 -and $unknownOrIndexedCount -eq 0 -and
      $allAnomalyClassesEmpty -and
      [int]$knownEvents[0].system_id -eq 1 -and
      [int]$knownEvents[0].component_id -eq 1 -and
      [string]$knownEvents[0].param_id -ceq 'STAT_RUNTIME' -and
      [string]$knownEvents[0].param_id_hex -ceq
        $script:ExpectedStatRuntimeIdHex -and
      [int]$knownEvents[0].param_index -eq 65535 -and
      [int]$knownEvents[0].param_count -eq 932 -and
      [int]$knownEvents[0].param_type -eq 6)
  $d722Delta = Get-SnapshotDelta -Baseline $OfficialVehicle `
      -Post $PreRequestVehicle -Key 'd722'
  $pgq = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pgq'
  $pga = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pga'
  $prq = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'prq'
  $ptq = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'ptq'
  $pvs1 = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvs1'
  $d7pb = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'd7pb'
  $pvid = Get-SnapshotString -Snapshot $PreRequestVehicle -Key 'pvid'
  $pvidx = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvidx'
  $pvcnt = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvcnt'
  $pvtype = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvtype'
  $pvsys = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvsys'
  $pvcomp = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvcomp'
  $pvms = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvms'
  $officialPgq = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'pgq'
  $officialPga = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'pga'
  $officialPrq = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'prq'
  $officialPtq = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'ptq'
  $officialPvs1 = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'pvs1'
  $officialD7pb = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'd7pb'
  $currentD7pb = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'd7pb'
  [bool]$silentD7pbEmpty = ($officialD7pb.found -and
      $currentD7pb.found -and [uint64]$officialD7pb.value -eq [uint64]0 -and
      [uint64]$currentD7pb.value -eq [uint64]0)
  [bool]$silentPartialD7pbBounded = ($officialD7pb.found -and
      $currentD7pb.found -and [uint64]$officialD7pb.value -eq [uint64]0 -and
      [uint64]$currentD7pb.value -ge [uint64]1 -and
      [uint64]$currentD7pb.value -le [uint64]279)
  [bool]$priorAndCurrentPartialD7pbBounded = ($officialD7pb.found -and
      $currentD7pb.found -and
      [uint64]$officialD7pb.value -ge [uint64]1 -and
      [uint64]$officialD7pb.value -le [uint64]279 -and
      [uint64]$currentD7pb.value -ge [uint64]1 -and
      [uint64]$currentD7pb.value -le [uint64]279)
  [bool]$queuedOfficialD7pbBounded = ($officialD7pb.found -and
      [uint64]$officialD7pb.value -le [uint64]279)
  [bool]$observerExact = ($pvid.found -and
      [string]$pvid.value -ceq 'STAT_RUNTIME' -and
      $pvidx.found -and [uint64]$pvidx.value -eq 65535 -and
       $pvcnt.found -and [uint64]$pvcnt.value -eq 932 -and
       $pvtype.found -and [uint64]$pvtype.value -eq 6)
  [bool]$silentObserverExact = ($observerExact -and $pvsys.found -and
      [uint64]$pvsys.value -eq 1 -and $pvcomp.found -and
      [uint64]$pvcomp.value -eq 1)
  [bool]$sentinelDeltaExact = ($d722Delta.found -and
      $d722Delta.monotonic -and [uint64]$d722Delta.delta -eq
        [uint64]$knownEvents.Count)
  [bool]$schedulerBound = ($pgq.found -and
      [uint64]$pgq.value -le [uint64]$knownEvents.Count)
  [bool]$exactActiveSchedulerState = ($pgq.found -and
      [uint64]$pgq.value -eq [uint64]1 -and $pga.found -and
      [uint64]$pga.value -eq [uint64]1 -and $prq.found -and
      [uint64]$prq.value -eq [uint64]0 -and $ptq.found -and
      [uint64]$ptq.value -eq [uint64]0 -and $pvs1.found -and
      [uint64]$pvs1.value -eq [uint64]0 -and $d7pb.found -and
      [uint64]$d7pb.value -eq [uint64]0)
  [bool]$exactSilentQueuedOfficialSchedulerState = ($officialPgq.found -and
      [uint64]$officialPgq.value -eq [uint64]0 -and $officialPga.found -and
      [uint64]$officialPga.value -eq [uint64]0 -and $officialPrq.found -and
      [uint64]$officialPrq.value -eq [uint64]0 -and $officialPtq.found -and
      [uint64]$officialPtq.value -eq [uint64]0 -and $officialPvs1.found -and
      [uint64]$officialPvs1.value -eq [uint64]0)
  [bool]$exactSilentQueuedSchedulerState = (
      $exactSilentQueuedOfficialSchedulerState -and $pgq.found -and
      [uint64]$pgq.value -eq [uint64]1 -and $pga.found -and
      [uint64]$pga.value -eq [uint64]0 -and $prq.found -and
      [uint64]$prq.value -eq [uint64]0 -and $ptq.found -and
      [uint64]$ptq.value -eq [uint64]0 -and $pvs1.found -and
      [uint64]$pvs1.value -eq [uint64]0 -and $currentD7pb.found -and
      [uint64]$currentD7pb.value -eq [uint64]0)
  [bool]$exactPostM0SnapshotSchedulerState = ($pgq.found -and
      [uint64]$pgq.value -eq [uint64]1 -and $pga.found -and
      [uint64]$pga.value -eq [uint64]0 -and $prq.found -and
      [uint64]$prq.value -eq [uint64]0 -and $ptq.found -and
      [uint64]$ptq.value -eq [uint64]0 -and $pvs1.found -and
      [uint64]$pvs1.value -eq [uint64]0 -and $currentD7pb.found -and
      [uint64]$currentD7pb.value -ge [uint64]1 -and
      [uint64]$currentD7pb.value -le [uint64]279)
  $officialBoot = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'boot'
  $currentBoot = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'boot'
  [bool]$silentSameBoot = ($officialBoot.found -and $currentBoot.found -and
      [uint64]$officialBoot.value -ne 0 -and
      [uint64]$officialBoot.value -eq [uint64]$currentBoot.value)
  $officialD722 = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'd722'
  $officialRf22 = Get-SnapshotUInt64 -Snapshot $OfficialGround -Key 'rf22'
  $currentD722 = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'd722'
  $officialPvok = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'pvok'
  $currentPvok = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'pvok'
  $silentPvokDelta = Get-SnapshotDelta -Baseline $OfficialVehicle `
      -Post $PreRequestVehicle -Key 'pvok'
  $silentD7crDelta = Get-SnapshotDelta -Baseline $OfficialVehicle `
      -Post $PreRequestVehicle -Key 'd7cr'
  [bool]$silentD722DeltaOne = ($d722Delta.found -and
      $d722Delta.monotonic -and [uint64]$d722Delta.delta -eq 1)
  [bool]$silentPvokDeltaOne = ($silentPvokDelta.found -and
      $silentPvokDelta.monotonic -and [uint64]$silentPvokDelta.delta -eq 1)
  [bool]$silentD7crDeltaZero = ($silentD7crDelta.found -and
      $silentD7crDelta.monotonic -and [uint64]$silentD7crDelta.delta -eq 0)
  [bool]$silentOfficialReconciled = ($officialD722.found -and
      $officialRf22.found -and [uint64]$officialD722.value -eq
        [uint64]$officialRf22.value)
  [bool]$silentCurrentAheadOne = ($currentD722.found -and
      $officialRf22.found -and [uint64]$officialRf22.value -lt
        [uint64]::MaxValue -and [uint64]$currentD722.value -eq
        ([uint64]$officialRf22.value + [uint64]1))
  [bool]$silentObserverCountersAligned = ($officialD722.found -and
      $officialPvok.found -and $currentD722.found -and $currentPvok.found -and
      [uint64]$officialD722.value -eq [uint64]$officialPvok.value -and
      [uint64]$currentD722.value -eq [uint64]$currentPvok.value)
  $officialMs = Get-SnapshotUInt64 -Snapshot $OfficialVehicle -Key 'ms'
  $currentMs = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle -Key 'ms'
  [bool]$silentPvmsFresh = ($officialMs.found -and $currentMs.found -and
      $pvms.found -and [uint64]$pvms.value -gt [uint64]$officialMs.value -and
      [uint64]$pvms.value -le [uint64]$currentMs.value)
  [bool]$silentQueueEmpty = $true
  [bool]$silentNonParserQueueEmpty = $true
  $silentQueueValues = [ordered]@{}
  foreach ($silentQueueKey in @('pgq','pga','prq','ptq','pvs1','d7pb')) {
    $silentQueueField = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle `
        -Key $silentQueueKey
    $silentQueueValues[$silentQueueKey] = $silentQueueField.value
    if (-not $silentQueueField.found -or
      [uint64]$silentQueueField.value -ne 0) { $silentQueueEmpty = $false }
    if ($silentQueueKey -cne 'd7pb' -and (-not $silentQueueField.found -or
        [uint64]$silentQueueField.value -ne 0)) {
      $silentNonParserQueueEmpty = $false
    }
  }
  [bool]$silentRelatedErrorZero = $silentD7crDeltaZero
  $silentErrorValues = [ordered]@{}
  foreach ($silentErrorKey in @('ef','pvbad','pvov','eo','evo')) {
    $silentErrorField = Get-SnapshotUInt64 -Snapshot $PreRequestVehicle `
        -Key $silentErrorKey
    $silentErrorValues[$silentErrorKey] = $silentErrorField.value
    if (-not $silentErrorField.found -or
        [uint64]$silentErrorField.value -ne 0) {
      $silentRelatedErrorZero = $false
    }
  }
  [bool]$exactActiveErrorZero = $silentRelatedErrorZero
  $exactActiveErrorValues = [ordered]@{}
  foreach ($exactActiveErrorKey in @('d6cr','d7cr')) {
    $exactActiveErrorField = Get-SnapshotUInt64 `
        -Snapshot $PreRequestVehicle -Key $exactActiveErrorKey
    $exactActiveErrorValues[$exactActiveErrorKey] = $exactActiveErrorField.value
    if (-not $exactActiveErrorField.found -or
        [uint64]$exactActiveErrorField.value -ne 0) {
      $exactActiveErrorZero = $false
    }
  }
  [bool]$exactPostM0OfficialErrorZero = $true
  $exactPostM0OfficialErrorValues = [ordered]@{}
  foreach ($exactPostM0OfficialErrorKey in @(
      'ef','pvbad','pvov','eo','evo','d6cr','d7cr')) {
    $exactPostM0OfficialErrorField = Get-SnapshotUInt64 `
        -Snapshot $OfficialVehicle -Key $exactPostM0OfficialErrorKey
    $exactPostM0OfficialErrorValues[$exactPostM0OfficialErrorKey] =
        $exactPostM0OfficialErrorField.value
    if (-not $exactPostM0OfficialErrorField.found -or
        [uint64]$exactPostM0OfficialErrorField.value -ne [uint64]0) {
      $exactPostM0OfficialErrorZero = $false
    }
  }
  [bool]$exactPostM0OfficialIdleReconciled = (
      $OfficialVehicle.status -ceq 'COMPLETE' -and
      $OfficialGround.status -ceq 'COMPLETE' -and
      $exactSilentQueuedOfficialSchedulerState -and $officialD7pb.found -and
      [uint64]$officialD7pb.value -eq [uint64]0 -and
      $silentOfficialReconciled -and $officialD722.found -and
      $officialPvok.found -and
      [uint64]$officialD722.value -eq [uint64]$officialPvok.value -and
      $exactPostM0OfficialErrorZero)
  $preM0TailRaceEvidence = Test-ExactPreM0TailStatRuntimeRace `
      -PreM0TailEvidence $PreM0TailEvidence `
      -OfficialVehicle $OfficialVehicle `
      -PreRequestVehicle $PreRequestVehicle `
      -M0GroundRawOffset $M0GroundRawOffset -M0Events $events
  $observedPartialEventEvidence =
      Test-ExactObservedM0StatRuntimePartialD7Race `
        -CausalGate $CausalGate -PreRequestVehicle $PreRequestVehicle `
        -M0GroundRawOffset $M0GroundRawOffset `
        -M0GateEndGroundRawOffset $M0GateEndGroundRawOffset `
        -M0Events $events
  $exactPostM0SnapshotEventEvidence =
      Test-ExactPostM0VehicleSnapshotStatRuntimePartialD7Race `
        -CausalGate $CausalGate -OfficialVehicle $OfficialVehicle `
        -OfficialGround $OfficialGround `
        -PreRequestVehicle $PreRequestVehicle -M0Capture $M0Capture `
        -DiagnosticEndBarrier $DiagnosticEndBarrier -M0Events $events
  $isolatedPartialD7Race = Test-IsolatedPartialD7SnapshotRaceContract `
      -CausalGate $CausalGate `
      -PreRequestVehicleGate $PreRequestVehicleGate `
      -OfficialVehicle $OfficialVehicle -OfficialGround $OfficialGround `
      -PreRequestVehicle $PreRequestVehicle -M0Events $events
  [bool]$attemptAvailable = ($AttemptNumber -lt $MaxAttempts)
  [bool]$isolatedPartialD7FinalStandardAttempt = (
      $MaxAttempts -eq 3 -and $AttemptNumber -eq 3)
  [bool]$isolatedPartialD7RetryCandidate = (
      [bool]$isolatedPartialD7Race.valid -and
      $isolatedPartialD7FinalStandardAttempt)
  [bool]$isolatedPartialD7RetryEligible = (
      $isolatedPartialD7RetryCandidate -and
      $IsolatedPartialD7ExtraRetryAvailable -and $RetryBudgetAvailable)
  [bool]$exactSentinelRace = (-not [bool]$CausalGate.valid -and
      -not [bool]$PreRequestVehicleGate.valid -and $m0EpochCompleted -and
      $parserClean -and $heartbeatClean -and $exactKnownEvent -and
      $onlyAllowedVehicleFailures -and $sentinelDeltaExact -and
      $schedulerBound -and $observerExact)
  [bool]$exactActiveStatRuntimeRace = (
      -not [bool]$CausalGate.valid -and
      -not [bool]$PreRequestVehicleGate.valid -and $m0EpochCompleted -and
      $parserClean -and $heartbeatClean -and $exactKnownEvent -and
      $exactActiveVehicleFailureSet -and $sentinelDeltaExact -and
      $silentD722DeltaOne -and $silentPvokDeltaOne -and $silentSameBoot -and
      $silentOfficialReconciled -and $silentCurrentAheadOne -and
      $silentObserverCountersAligned -and $silentObserverExact -and
      $silentPvmsFresh -and $exactActiveSchedulerState -and
      $exactActiveErrorZero)
  [bool]$exactSilentInFlightStatRuntimeRace = (
      [bool]$CausalGate.valid -and -not [bool]$PreRequestVehicleGate.valid -and
      $m0EpochCompleted -and $parserClean -and $heartbeatClean -and
      $events.Count -eq 0 -and $allAnomalyClassesEmpty -and
      $exactSilentVehicleFailureSet -and $silentSameBoot -and
      $silentOfficialReconciled -and $silentCurrentAheadOne -and
      $silentD722DeltaOne -and $silentPvokDeltaOne -and
      $silentObserverCountersAligned -and $silentObserverExact -and
      $silentPvmsFresh -and $silentD7pbEmpty -and $silentQueueEmpty -and
      $silentRelatedErrorZero)
  [bool]$exactLateQueuedStatRuntimeRace = (
      [bool]$CausalGate.valid -and -not [bool]$PreRequestVehicleGate.valid -and
      $m0EpochCompleted -and $parserClean -and $heartbeatClean -and
      $events.Count -eq 0 -and $allAnomalyClassesEmpty -and
      $exactSilentQueuedVehicleFailureSet -and $silentSameBoot -and
      $silentOfficialReconciled -and $silentCurrentAheadOne -and
      $silentD722DeltaOne -and $silentPvokDeltaOne -and
      $silentObserverCountersAligned -and $silentObserverExact -and
      $silentPvmsFresh -and $queuedOfficialD7pbBounded -and
      $exactSilentQueuedSchedulerState -and $exactActiveErrorZero)
  [bool]$exactPreM0TailStatRuntimeRace = (
      [bool]$CausalGate.valid -and -not [bool]$PreRequestVehicleGate.valid -and
      $m0EpochCompleted -and $parserClean -and $heartbeatClean -and
      $events.Count -eq 0 -and $allAnomalyClassesEmpty -and
      $exactSilentPartialVehicleFailureSet -and $silentPartialD7pbBounded -and
      $silentSameBoot -and $silentOfficialReconciled -and
      $silentCurrentAheadOne -and $silentD722DeltaOne -and
      $silentPvokDeltaOne -and $silentObserverCountersAligned -and
      $silentObserverExact -and $silentPvmsFresh -and
      $silentNonParserQueueEmpty -and $silentRelatedErrorZero -and
      [bool]$preM0TailRaceEvidence.valid)
  [bool]$exactPreM0TailHeartbeatGapPriorPartialD7Race = (
      [bool]$CausalGate.valid -and -not [bool]$PreRequestVehicleGate.valid -and
      $m0EpochCompleted -and $parserClean -and $heartbeatClean -and
      $events.Count -eq 0 -and $allAnomalyClassesEmpty -and
      $exactSilentPartialVehicleFailureSet -and
      $priorAndCurrentPartialD7pbBounded -and
      $exactSilentQueuedOfficialSchedulerState -and
      $silentSameBoot -and $silentOfficialReconciled -and
      $silentCurrentAheadOne -and $silentD722DeltaOne -and
      $silentPvokDeltaOne -and $silentObserverCountersAligned -and
      $silentObserverExact -and $silentPvmsFresh -and
      $silentNonParserQueueEmpty -and $silentRelatedErrorZero -and
      [bool]$preM0TailRaceEvidence.valid -and
      [string]$preM0TailRaceEvidence.boundary_mode -ceq
        'contiguous_vehicle_heartbeat_chain' -and
      [bool]$preM0TailRaceEvidence.target_valid_event_mirror_exact -and
      [bool]$preM0TailRaceEvidence.target_payload_exact -and
      [bool]$preM0TailRaceEvidence.full_tail_wire_chain_exact -and
      [bool]$preM0TailRaceEvidence.trailing_heartbeat_chain_exact -and
      [int]$preM0TailRaceEvidence.trailing_heartbeat_count -ge 1 -and
      $exactActiveErrorZero)
  [bool]$exactObservedStatRuntimePartialD7Race = (
      -not [bool]$CausalGate.valid -and
      -not [bool]$PreRequestVehicleGate.valid -and $m0EpochCompleted -and
      $parserClean -and $heartbeatClean -and $exactKnownEvent -and
      $allAnomalyClassesEmpty -and $exactSilentPartialVehicleFailureSet -and
      $sentinelDeltaExact -and $silentPartialD7pbBounded -and
      $exactSilentQueuedOfficialSchedulerState -and
      $silentNonParserQueueEmpty -and $silentSameBoot -and
      $silentOfficialReconciled -and $silentCurrentAheadOne -and
      $silentD722DeltaOne -and $silentPvokDeltaOne -and
      $silentObserverCountersAligned -and $silentObserverExact -and
      $silentPvmsFresh -and $exactActiveErrorZero -and
      [bool]$observedPartialEventEvidence.valid)
  [bool]$exactPostM0VehicleSnapshotStatRuntimeRace = (
      -not [bool]$CausalGate.valid -and
      -not [bool]$PreRequestVehicleGate.valid -and $m0EpochCompleted -and
      $parserClean -and $heartbeatClean -and $exactKnownEvent -and
      $allAnomalyClassesEmpty -and $exactPostM0SnapshotVehicleFailureSet -and
      $sentinelDeltaExact -and $exactPostM0OfficialIdleReconciled -and
      $exactPostM0SnapshotSchedulerState -and $silentSameBoot -and
      $silentD722DeltaOne -and $silentPvokDeltaOne -and
      $silentObserverCountersAligned -and $silentObserverExact -and
      $silentPvmsFresh -and $exactActiveErrorZero -and
      [bool]$exactPostM0SnapshotEventEvidence.valid)
  [bool]$retryCandidate = ($exactSentinelRace -or $exactActiveStatRuntimeRace -or
      $exactSilentInFlightStatRuntimeRace -or $exactPreM0TailStatRuntimeRace -or
      $exactPreM0TailHeartbeatGapPriorPartialD7Race -or
      $exactLateQueuedStatRuntimeRace -or
      $exactObservedStatRuntimePartialD7Race -or
      $exactPostM0VehicleSnapshotStatRuntimeRace)
  # R14 live evidence can align the bounded retry cadence with the periodic
  # STAT_RUNTIME producer three times in a row.  Only the strongest form -- one
  # exact wire-observed generic sentinel with the already-proven failure set --
  # may borrow the single dedicated attempt-4 slot.  It remains RETRY-only;
  # attempt 4 must independently pass the ordinary clean-M0 gates.
  [bool]$exactObservedStatRuntimeFinalStandardAttempt = (
      $MaxAttempts -eq 3 -and $AttemptNumber -eq $MaxAttempts)
  [bool]$exactObservedStatRuntimeExtraRetryCandidate = (
      $exactSentinelRace -and $exactObservedStatRuntimeFinalStandardAttempt)
  [bool]$exactObservedStatRuntimeExtraRetryEligible = (
      $exactObservedStatRuntimeExtraRetryCandidate -and
      $ExactObservedStatRuntimeExtraRetryAvailable -and
      $RetryBudgetAvailable)
  [bool]$retryEligible = ($retryCandidate -and $attemptAvailable -and
      $RetryBudgetAvailable)
  [string]$action = 'REJECT'
  [string]$reason = 'pre_request_contract_failed'
  if ([bool]$CausalGate.valid -and [bool]$PreRequestVehicleGate.valid) {
    $action = 'ACCEPT';$reason = 'clean_m0_and_vehicle_gate_valid'
  } elseif ($isolatedPartialD7RetryEligible) {
    # A sole bounded d7pb failure can be an atomic diagnostic snapshot taken
    # while the D7 parser is between frame bytes.  It is never accepted.  On
    # the final standard attempt only, a separate one-shot token may request
    # one complete bilateral drain/promotion cycle under the original deadline.
    $action = 'RETRY_ISOLATED_D7PB'
    $reason = 'exact_isolated_partial_D7_snapshot_race'
  } elseif ($isolatedPartialD7RetryCandidate -and
      -not $IsolatedPartialD7ExtraRetryAvailable) {
    $reason = 'isolated_partial_D7_extra_retry_exhausted'
  } elseif ($isolatedPartialD7RetryCandidate -and
      -not $RetryBudgetAvailable) {
    $reason = 'shared_deadline_exhausted'
  } elseif ([bool]$isolatedPartialD7Race.valid -and
      $AttemptNumber -gt $MaxAttempts) {
    $reason = 'isolated_partial_D7_extra_retry_exhausted'
  } elseif ([bool]$isolatedPartialD7Race.valid) {
    $reason = 'isolated_partial_D7_only_final_standard_attempt'
  } elseif ($exactObservedStatRuntimeExtraRetryEligible) {
    $action = 'RETRY_EXACT_STAT_RUNTIME'
    $reason = 'exact_wire_observed_STAT_RUNTIME_extra_retry'
  } elseif ($exactObservedStatRuntimeExtraRetryCandidate -and
      -not $ExactObservedStatRuntimeExtraRetryAvailable) {
    $reason = 'exact_wire_observed_STAT_RUNTIME_extra_retry_exhausted'
  } elseif ($exactObservedStatRuntimeExtraRetryCandidate -and
      -not $RetryBudgetAvailable) {
    $reason = 'shared_deadline_exhausted'
  } elseif ($retryEligible) {
    # Only an exact observed STAT_RUNTIME race may reach RETRY. An M0-observed
    # frame with a partial D7 shadow also requires exact wire-to-observer
    # Vehicle observer correlation. Every race remains RETRY-only and bounded.
    $action = 'RETRY'
    $reason = if ($exactPostM0VehicleSnapshotStatRuntimeRace) {
      'exact_post_M0_vehicle_snapshot_STAT_RUNTIME_partial_D7_race'
    } elseif ($exactPreM0TailHeartbeatGapPriorPartialD7Race) {
      'exact_pre_M0_tail_STAT_RUNTIME_heartbeat_gap_prior_partial_D7_race'
    } elseif ($exactPreM0TailStatRuntimeRace) {
      'exact_pre_M0_tail_STAT_RUNTIME_race'
    } elseif ($exactObservedStatRuntimePartialD7Race) {
      'exact_observed_STAT_RUNTIME_partial_D7_race'
    } elseif ($exactLateQueuedStatRuntimeRace) {
      'exact_late_queued_STAT_RUNTIME_race'
    } elseif ($exactSilentInFlightStatRuntimeRace) {
      'exact_silent_inflight_STAT_RUNTIME_race'
    } elseif ($exactActiveStatRuntimeRace) {
      'exact_active_STAT_RUNTIME_m0_race'
    } else { 'exact_stat_runtime_m0_race' }
  } elseif ($retryCandidate -and -not $attemptAvailable) {
    $reason = 'retry_exhausted'
  } elseif ($retryCandidate -and -not $RetryBudgetAvailable) {
    $reason = 'shared_deadline_exhausted'
  } elseif (-not $parserClean) {
    $reason = 'parser_integrity_invalid'
  } elseif (-not $heartbeatClean) {
    $reason = 'heartbeat_gate_invalid'
  } elseif ($unknownOrIndexedCount -ne 0) {
    $reason = 'unknown_or_indexed_m0_event'
  }
  return [pscustomobject][ordered]@{
    action=$action;reason=$reason;attempt_number=$AttemptNumber
    max_attempts=$MaxAttempts
    retry_eligible=($retryEligible -or $isolatedPartialD7RetryEligible -or
        $exactObservedStatRuntimeExtraRetryEligible)
    general_retry_eligible=$retryEligible
    retry_budget_available=$RetryBudgetAvailable
    retry_exhausted=($reason -ceq 'retry_exhausted' -or
        $reason -ceq 'isolated_partial_D7_extra_retry_exhausted' -or
        $reason -ceq 'exact_wire_observed_STAT_RUNTIME_extra_retry_exhausted')
    isolated_partial_d7_extra_retry_available=
        $IsolatedPartialD7ExtraRetryAvailable
    isolated_partial_d7_final_standard_attempt=
        $isolatedPartialD7FinalStandardAttempt
    isolated_partial_d7_retry_candidate=$isolatedPartialD7RetryCandidate
    isolated_partial_d7_retry_eligible=$isolatedPartialD7RetryEligible
    isolated_partial_d7_extra_retry_selected=
        ($action -ceq 'RETRY_ISOLATED_D7PB')
    exact_observed_stat_runtime_final_standard_attempt=
        $exactObservedStatRuntimeFinalStandardAttempt
    exact_observed_stat_runtime_extra_retry_available=
        $ExactObservedStatRuntimeExtraRetryAvailable
    exact_observed_stat_runtime_extra_retry_candidate=
        $exactObservedStatRuntimeExtraRetryCandidate
    exact_observed_stat_runtime_extra_retry_eligible=
        $exactObservedStatRuntimeExtraRetryEligible
    exact_observed_stat_runtime_extra_retry_selected=
        ($action -ceq 'RETRY_EXACT_STAT_RUNTIME')
    isolated_partial_d7_race=$isolatedPartialD7Race
    m0_epoch_completed=$m0EpochCompleted;parser_clean=$parserClean
    heartbeat_clean=$heartbeatClean;m0_event_count=$events.Count
    known_stat_runtime_count=$knownEvents.Count
    unknown_or_indexed_count=$unknownOrIndexedCount
    anomaly_classes_empty=$allAnomalyClassesEmpty
    exact_known_event=$exactKnownEvent
    failed_vehicle_check_names=$failedVehicleNames
    only_allowed_vehicle_failures=$onlyAllowedVehicleFailures
    exact_active_vehicle_failure_set=$exactActiveVehicleFailureSet
    exact_silent_queued_vehicle_failure_set=$exactSilentQueuedVehicleFailureSet
    exact_silent_vehicle_failure_set=$exactSilentVehicleFailureSet
    d722_delta=$d722Delta;sentinel_delta_exact=$sentinelDeltaExact
    pgq=$pgq.value;pga=$pga.value;prq=$prq.value;ptq=$ptq.value
    pvs1=$pvs1.value;d7pb=$d7pb.value;scheduler_bound=$schedulerBound
    exact_active_scheduler_state=$exactActiveSchedulerState
    official_pgq=$officialPgq.value
    official_pga=$officialPga.value;official_prq=$officialPrq.value
    official_ptq=$officialPtq.value;official_pvs1=$officialPvs1.value
    exact_silent_queued_official_scheduler_state=
        $exactSilentQueuedOfficialSchedulerState
    exact_silent_queued_scheduler_state=$exactSilentQueuedSchedulerState
    pvid=$pvid.value;pvidx=$pvidx.value;pvcnt=$pvcnt.value
    pvtype=$pvtype.value;observer_exact=$observerExact
    exact_late_queued_STAT_RUNTIME_race=$exactLateQueuedStatRuntimeRace
    exact_silent_inflight_STAT_RUNTIME_race=$exactSilentInFlightStatRuntimeRace
    exact_pre_M0_tail_STAT_RUNTIME_race=$exactPreM0TailStatRuntimeRace
    exact_pre_M0_tail_STAT_RUNTIME_heartbeat_gap_prior_partial_D7_race=
        $exactPreM0TailHeartbeatGapPriorPartialD7Race
    exact_observed_STAT_RUNTIME_partial_D7_race=
        $exactObservedStatRuntimePartialD7Race
    observed_partial_event_evidence=$observedPartialEventEvidence
    exact_silent_partial_vehicle_failure_set=$exactSilentPartialVehicleFailureSet
    exact_post_M0_snapshot_vehicle_failure_set=
        $exactPostM0SnapshotVehicleFailureSet
    silent_d7pb_empty=$silentD7pbEmpty
    silent_partial_d7pb_bounded=$silentPartialD7pbBounded
    prior_and_current_partial_d7pb_bounded=$priorAndCurrentPartialD7pbBounded
    queued_official_d7pb_bounded=$queuedOfficialD7pbBounded
    pre_m0_tail_race_evidence=$preM0TailRaceEvidence
    exact_post_M0_vehicle_snapshot_STAT_RUNTIME_partial_D7_race=
        $exactPostM0VehicleSnapshotStatRuntimeRace
    exact_post_M0_snapshot_event_evidence=$exactPostM0SnapshotEventEvidence
    exact_post_M0_snapshot_scheduler_state=$exactPostM0SnapshotSchedulerState
    exact_post_M0_official_idle_reconciled=$exactPostM0OfficialIdleReconciled
    exact_post_M0_official_error_zero=$exactPostM0OfficialErrorZero
    exact_post_M0_official_error_values=$exactPostM0OfficialErrorValues
    exact_active_STAT_RUNTIME_m0_race=$exactActiveStatRuntimeRace
    exact_active_error_zero=$exactActiveErrorZero
    exact_active_error_values=$exactActiveErrorValues
    silent_same_boot=$silentSameBoot
    silent_official_reconciled=$silentOfficialReconciled
    silent_current_ahead_one=$silentCurrentAheadOne
    silent_d722_delta_one=$silentD722DeltaOne
    silent_pvok_delta=$silentPvokDelta
    silent_pvok_delta_one=$silentPvokDeltaOne
    silent_d7cr_delta=$silentD7crDelta
    silent_d7cr_delta_zero=$silentD7crDeltaZero
    silent_observer_counters_aligned=$silentObserverCountersAligned
    silent_observer_exact=$silentObserverExact
    pvsys=$pvsys.value;pvcomp=$pvcomp.value;pvms=$pvms.value
    silent_pvms_fresh=$silentPvmsFresh
    silent_queue_empty=$silentQueueEmpty
    silent_nonparser_queue_empty=$silentNonParserQueueEmpty
    silent_queue_values=$silentQueueValues
    silent_related_error_zero=$silentRelatedErrorZero
    silent_error_values=$silentErrorValues
    fixture_write_count=0
  }
}

function Test-TimeoutDecision {
  param(
    [double]$ElapsedSeconds,
    [double]$StallSeconds,
    [int]$Indexed,
    [int]$OverallLimitSeconds = 7200,
    [int]$StallLimitSeconds = 120
  )
  return [pscustomobject][ordered]@{
    overall_timeout = ($ElapsedSeconds -ge $OverallLimitSeconds)
    stall_timeout = ($Indexed -lt 932 -and $StallSeconds -ge $StallLimitSeconds)
  }
}

function New-ProgressState {
  return [pscustomobject][ordered]@{
    last_elapsed_seconds = [double]0
    last_indexed = 0
  }
}

function Write-ProgressIfDue {
  param(
    [Parameter(Mandatory = $true)]$ProgressState,
    [Parameter(Mandatory = $true)][int]$Indexed,
    [Parameter(Mandatory = $true)][int]$LastIndex,
    [Parameter(Mandatory = $true)][double]$ElapsedSeconds,
    [Parameter(Mandatory = $true)][double]$HeartbeatMaximumMs,
    [Parameter(Mandatory = $true)][double]$StallSeconds,
    [switch]$SuppressConsole
  )
  [bool]$timeDue = (($ElapsedSeconds -
      [double]$ProgressState.last_elapsed_seconds) -ge 30.0)
  [bool]$indexDue = (($Indexed - [int]$ProgressState.last_indexed) -ge 25)
  if (-not $timeDue -and -not $indexDue) {
    return [pscustomobject]@{ emitted = $false; line = $null }
  }
  [string]$line = 'PROGRESS indexed={0}/932 last={1} elapsed_s={2:F1} hb_max_ms={3:F1} stall_s={4:F1}' -f `
      $Indexed, $LastIndex, $ElapsedSeconds, $HeartbeatMaximumMs, $StallSeconds
  if (-not $SuppressConsole.IsPresent) { Write-Host $line }
  $ProgressState.last_elapsed_seconds = $ElapsedSeconds
  $ProgressState.last_indexed = $Indexed
  return [pscustomobject]@{ emitted = $true; line = $line }
}

function Get-BacklogDrainEvidenceProjection {
  [CmdletBinding()]
  param(
    [AllowNull()]$BacklogDrainGate,
    [AllowNull()]$GroundParser,
    [ValidateRange(1,3600)][int]$TimeoutSeconds
  )
  if ($null -ne $BacklogDrainGate) { return $BacklogDrainGate }
  [bool]$groundParserDisabledAndReset = ($null -ne $GroundParser -and
      $null -ne $GroundParser.PSObject.Properties['Enabled'] -and
      -not [bool]$GroundParser.Enabled)
  return [pscustomobject][ordered]@{
    schema_version=1;valid=$false;timed_out=$false;sync_invalid=$false
    not_run=$true;timeout_seconds=$TimeoutSeconds
    attempt_count=0;observations=[object[]]@();stable_pairs=[object[]]@()
    last_vehicle_snapshot=$null;last_ground_snapshot=$null
    ground_parser_disabled_and_reset=$groundParserDisabledAndReset
  }
}

function Resolve-FinalizationFailure {
  [CmdletBinding()]
  param(
    [AllowNull()][AllowEmptyString()][string]$PrimaryFailure,
    [Parameter(Mandatory = $true)][ValidateNotNullOrEmpty()]
    [string]$FinalizationFailure
  )
  [bool]$primaryPreserved =
      -not [string]::IsNullOrWhiteSpace($PrimaryFailure)
  return [pscustomobject][ordered]@{
    primary_failure=if($primaryPreserved){
      $PrimaryFailure
    }else{$FinalizationFailure}
    finalization_failure=$FinalizationFailure
    primary_preserved=$primaryPreserved
  }
}

function Get-RawEvidenceFallbackProjection {
  [CmdletBinding()]
  param(
    [ValidateRange(0,[long]::MaxValue)][long]$VehicleRawBytes,
    [ValidateRange(0,[long]::MaxValue)][long]$GroundRawBytes,
    [Parameter(Mandatory = $true)][ValidateNotNullOrEmpty()]
    [string]$FailureReason
  )
  return [pscustomobject][ordered]@{
    schema_version=1;seal_valid=$false;failure_reason=$FailureReason
    vehicle_bytes=$VehicleRawBytes;vehicle_sha256=$null
    ground_bytes=$GroundRawBytes;ground_sha256=$null
    streams_disposed_before_hash=$false
  }
}

function Get-PumpFairnessFallbackProjection {
  [CmdletBinding()]
  param(
    [ValidateRange(0.001,[double]::MaxValue)][double]$TargetMs,
    [ValidateRange(0.001,[double]::MaxValue)][double]$HardLimitMs,
    [Parameter(Mandatory = $true)][ValidateNotNullOrEmpty()]
    [string]$FailureReason
  )
  return [pscustomobject][ordered]@{
    schema_version=4;measurement_complete=$false;valid=$false
    failure_reason=$FailureReason;target_ms=$TargetMs;hard_limit_ms=$HardLimitMs
    violation_event_count=0;violation_event_total_count=0
    violation_event_overflow_count=0;violation_events=[object[]]@()
    started_elapsed_ms=$null;completed_elapsed_ms=$null
    reader_shutdown=$null;vehicle=$null;ground=$null
  }
}

function Write-ExactRequestOnce {
  param(
    [Parameter(Mandatory = $true)]$Serial,
    [Parameter(Mandatory = $true)][byte[]]$Fixture,
    [Parameter(Mandatory = $true)]$InjectionState
  )
  $attemptProperty = $InjectionState.PSObject.Properties['attempt_count']
  if ($InjectionState.write_count -ne 0 -or
      ($null -ne $attemptProperty -and
       [int]$attemptProperty.Value -ne 0)) {
    throw 'PARAM_REQUEST_LIST injection was attempted more than once.'
  }
  if ($Fixture.Length -ne 14 -or
      (ConvertTo-Hex -Bytes $Fixture) -ne $script:ExpectedFixtureHex) {
    throw 'PARAM_REQUEST_LIST injection is not the frozen exact 14-byte fixture.'
  }
  foreach ($propertyDefinition in @(
      @('attempt_count', [int]0),
      @('write_uncertain', [bool]$false),
      @('write_disposition', 'NOT_ATTEMPTED'))) {
    if ($null -eq $InjectionState.PSObject.Properties[
        [string]$propertyDefinition[0]]) {
      $InjectionState | Add-Member -MemberType NoteProperty `
          -Name ([string]$propertyDefinition[0]) `
          -Value $propertyDefinition[1]
    }
  }
  # Latch before the RPC. If the child commits the bytes and its ACK is lost,
  # the disposition remains uncertain and this process can never retransmit.
  $InjectionState.attempt_count = 1
  $InjectionState.write_uncertain = $true
  $InjectionState.write_disposition = 'IN_FLIGHT_UNCERTAIN_NO_RETRY'
  try {
    if ($null -ne $Serial.PSObject.Methods['WriteExactFixture']) {
      $Serial.WriteExactFixture($Fixture, $script:ExpectedFixtureSha256)
    } else {
      $Serial.Write($Fixture, 0, $Fixture.Length)
      $Serial.BaseStream.Flush()
    }
  } catch {
    $InjectionState.write_disposition = 'ACK_UNCERTAIN_NO_RETRY'
    throw
  }
  $InjectionState.write_count = 1
  $InjectionState.write_uncertain = $false
  $InjectionState.write_disposition = 'ACKNOWLEDGED_EXACTLY_ONCE'
  $InjectionState.final_write_elapsed_ms = if ($null -ne $script:RunWatch) {
    [Math]::Round($script:RunWatch.Elapsed.TotalMilliseconds, 3)
  } else { [double]0 }
  $InjectionState.final_write_utc = [DateTime]::UtcNow.ToString('o')
}

function New-OfflineWriteSerial {
  $state = [pscustomobject]@{
    write_count = 0
    bytes = New-Object 'System.Collections.Generic.List[byte]'
  }
  $baseStream = New-Object psobject
  $baseStream | Add-Member -MemberType ScriptMethod -Name Flush -Value {}
  $serial = [pscustomobject]@{ state = $state; BaseStream = $baseStream }
  $serial | Add-Member -MemberType ScriptMethod -Name Write -Value {
    param([byte[]]$Buffer, [int]$Offset, [int]$Count)
    ++$this.state.write_count
    for ($index = 0; $index -lt $Count; ++$index) {
      $this.state.bytes.Add($Buffer[$Offset + $index])
    }
  }
  return $serial
}

function New-OfflineSnapshot {
  param(
    [Parameter(Mandatory = $true)][hashtable]$Fields,
    [uint32]$Q = 1,
    [uint64]$Ms = 100,
    [string]$TagBase = 'STAT'
  )
  $snapshotFields = $Fields.Clone()
  $snapshotFields['q'] = [uint64]$Q
  $snapshotFields['ms'] = [uint64]$Ms
  return [pscustomobject][ordered]@{
    status='COMPLETE';query_count=1;query_attempt_count=1
    write_timed_out=$false;expected_q=$null
    q_uint32=$Q;ms_uint64=$Ms;absolute_deadline_reached=$false
    responses=@(
      [pscustomobject]@{tag=($TagBase + '1');fields=[pscustomobject]$snapshotFields;line=($TagBase + '1')},
      [pscustomobject]@{tag=($TagBase + '2');fields=[pscustomobject]$snapshotFields;line=($TagBase + '2')},
      [pscustomobject]@{tag=($TagBase + '3');fields=[pscustomobject]$snapshotFields;line=($TagBase + '3')})
  }
}

function Get-ReaderBrokerRecordAudit {
  [CmdletBinding()]
  param(
    [Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$Records,
    [Parameter(Mandatory = $true)][long]$ExpectedVehicleBytes,
    [Parameter(Mandatory = $true)][long]$ExpectedGroundBytes
  )

  $roleState = [ordered]@{
    vehicle=[ordered]@{
      sequence=[long]0;offset=[long]0;seed=[int]17;records=[long]0
      first_ticks=$null;last_ticks=$null;context_ids=@{}
    }
    ground=[ordered]@{
      sequence=[long]0;offset=[long]0;seed=[int]53;records=[long]0
      first_ticks=$null;last_ticks=$null;context_ids=@{}
    }
  }
  [bool]$valid = $true
  [string]$firstError = ''
  foreach ($record in $Records) {
    [string]$role = [string]$record.Role
    if (-not $roleState.Contains($role)) {
      $valid = $false
      if ([string]::IsNullOrEmpty($firstError)) {
        $firstError = "unknown role=$role"
      }
      continue
    }
    $state = $roleState[$role]
    if ([long]$record.Sequence -ne [long]$state.sequence -or
        [long]$record.RawStartOffset -ne [long]$state.offset -or
        [long]$record.ProducerTimestampTicks -le 0 -or
        [int]$record.Count -le 0 -or [int]$record.Count -gt 32) {
      $valid = $false
      if ([string]::IsNullOrEmpty($firstError)) {
        $firstError = ('metadata discontinuity role={0} sequence={1}/{2} ' +
            'offset={3}/{4} count={5}') -f $role,$record.Sequence,
            $state.sequence,$record.RawStartOffset,$state.offset,$record.Count
      }
    }
    for ($byteIndex = 0; $byteIndex -lt [int]$record.Count;
        ++$byteIndex) {
      [int]$expected = ([int]$state.seed +
          (([long]$record.RawStartOffset + $byteIndex) * 29)) -band 0xFF
      if ([int]$record.Bytes[$byteIndex] -ne $expected) {
        $valid = $false
        if ([string]::IsNullOrEmpty($firstError)) {
          $firstError = "pattern mismatch role=$role offset=$($record.RawStartOffset + $byteIndex)"
        }
        break
      }
    }
    if ($null -eq $state.first_ticks) {
      $state.first_ticks = [long]$record.ProducerTimestampTicks
    }
    $state.last_ticks = [long]$record.ProducerTimestampTicks
    $state.context_ids[[string]$record.ContextId] = $true
    ++$state.sequence
    ++$state.records
    $state.offset += [int]$record.Count
  }
  if ([long]$roleState.vehicle.offset -ne $ExpectedVehicleBytes -or
      [long]$roleState.ground.offset -ne $ExpectedGroundBytes) {
    $valid = $false
    if ([string]::IsNullOrEmpty($firstError)) {
      $firstError = ('byte total mismatch vehicle={0}/{1} ground={2}/{3}') -f
          $roleState.vehicle.offset,$ExpectedVehicleBytes,
          $roleState.ground.offset,$ExpectedGroundBytes
    }
  }
  return [pscustomobject][ordered]@{
    valid=$valid;first_error=$firstError
    record_count=$Records.Count
    vehicle=[pscustomobject][ordered]@{
      records=[long]$roleState.vehicle.records
      bytes=[long]$roleState.vehicle.offset
      first_producer_ticks=$roleState.vehicle.first_ticks
      last_producer_ticks=$roleState.vehicle.last_ticks
      context_ids=@($roleState.vehicle.context_ids.Keys | Sort-Object)
    }
    ground=[pscustomobject][ordered]@{
      records=[long]$roleState.ground.records
      bytes=[long]$roleState.ground.offset
      first_producer_ticks=$roleState.ground.first_ticks
      last_producer_ticks=$roleState.ground.last_ticks
      context_ids=@($roleState.ground.context_ids.Keys | Sort-Object)
    }
  }
}

function Complete-ReaderBrokerSelfTestProcess {
  [CmdletBinding()]
  param(
    [Parameter(Mandatory = $true)]$Bundle,
    [ValidateRange(1000,60000)][int]$TimeoutMs = 10000
  )

  [bool]$boundedExit = $Bundle.process.WaitForExit($TimeoutMs)
  if (-not $boundedExit) {
    if ($Bundle.job_handle -ne [IntPtr]::Zero) {
      [VcDualPortReader.BrokerProcessContainment]::CloseJob(
          $Bundle.job_handle)
      $Bundle.job_handle = [IntPtr]::Zero
    }
    throw 'synthetic reader broker process exit timed out'
  }
  $Bundle.process.WaitForExit()
  $Bundle.process.Refresh()
  [int]$exitCode = [int]$Bundle.process.ExitCode
  if ($Bundle.job_handle -ne [IntPtr]::Zero) {
    [VcDualPortReader.BrokerProcessContainment]::CloseJob(
        $Bundle.job_handle)
    $Bundle.job_handle = [IntPtr]::Zero
  }
  return [pscustomobject][ordered]@{
    bounded_wait_succeeded=$boundedExit
    parameterless_wait_completed=$true
    refreshed=$true
    process_id=[int]$Bundle.process.Id
    exit_code=$exitCode
    exit_qpc_ticks=[System.Diagnostics.Stopwatch]::GetTimestamp()
  }
}

function Invoke-ReaderBrokerOfflineHarness {
  [CmdletBinding()]
  param(
    [Parameter(Mandatory = $true)][string]$EvidenceDirectory,
    [Parameter(Mandatory = $true)][byte[]]$Fixture
  )

  [string]$sourceSha256 = [string](Get-FileHash -Algorithm SHA256 `
      -LiteralPath $PSCommandPath -ErrorAction Stop).Hash
  $result = [ordered]@{
    schema_version=1
    runner_sha256=$sourceSha256
    protocol_version=$script:ReaderBrokerProtocolVersion
    producer_clock='System.Diagnostics.Stopwatch.GetTimestamp'
    consumer_timestamp_substitution=$false
    fairness_hard_limit_ms=$script:PumpFairnessHardLimitMs
    power_shell_allocation_count=6000
    power_shell_allocation_bytes_each=512
    explicit_consumer_block_ms=350
    synthetic_serial_enumeration_count=0
    synthetic_serial_port_construction_count=0
    synthetic_serial_open_count=0
    pressure=$null;overflow=$null;timestamp=$null;barrier=$null
    uncertainty=$null;open_start_ioexception=$null
    config_mismatch=$null;argv=$null;errors=@()
  }
  $harnessErrors = New-Object 'System.Collections.Generic.List[string]'

  $pressureBundle = $null
  try {
    $pressureBundle = Start-ReaderBrokerClient -Scenario 'pressure' `
        -RingSlots 8192 -VehicleBytes 48000 -GroundBytes 4800 `
        -ConnectTimeoutMs 30000 -BaseElapsedMs 1234.0 `
        -ExpectedRunnerSha256 $sourceSha256
    $pressureBefore = $pressureBundle.client.Snapshot()

    [byte[]]$normalWrite = [byte[]](1,2,3,4,5)
    $pressureBundle.ground_proxy.WriteExactFixture(
        $Fixture, $script:ExpectedFixtureSha256)
    [bool]$secondExactRejected = $false
    try {
      $pressureBundle.ground_proxy.WriteExactFixture(
          $Fixture, $script:ExpectedFixtureSha256)
    } catch { $secondExactRejected = $true }
    $pressureBundle.vehicle_proxy.Write(
        $normalWrite, 0, $normalWrite.Length)
    $pressureBundle.vehicle_proxy.BaseStream.Flush()

    [int]$gc0Before = [GC]::CollectionCount(0)
    [int]$gc1Before = [GC]::CollectionCount(1)
    [int]$gc2Before = [GC]::CollectionCount(2)
    [long]$blockStartTicks =
        [System.Diagnostics.Stopwatch]::GetTimestamp()
    $allocationPressure =
        New-Object 'System.Collections.Generic.List[object]'
    for ($pressureIndex = 0; $pressureIndex -lt 6000;
        ++$pressureIndex) {
      [byte[]]$payload = New-Object byte[] 512
      $payload[0] = [byte]($pressureIndex -band 0xFF)
      $allocationPressure.Add([pscustomobject][ordered]@{
        index=$pressureIndex
        phase='stage005_style_parent_allocation_pressure'
        payload=$payload
      })
    }
    [GC]::Collect()
    [GC]::WaitForPendingFinalizers()
    [GC]::Collect()
    Start-Sleep -Milliseconds 350
    [long]$blockEndTicks =
        [System.Diagnostics.Stopwatch]::GetTimestamp()
    [int]$gc0Delta = [GC]::CollectionCount(0) - $gc0Before
    [int]$gc1Delta = [GC]::CollectionCount(1) - $gc1Before
    [int]$gc2Delta = [GC]::CollectionCount(2) - $gc2Before
    $allocationPressure.Clear();$allocationPressure=$null

    $pressureStop = $pressureBundle.client.StopCapture()
    [long]$stopAckTicks =
        [System.Diagnostics.Stopwatch]::GetTimestamp()
    $pressureRecords = New-Object 'System.Collections.Generic.List[object]'
    while ($true) {
      [VcDualPortReader.CaptureRecord]$record = $null
      if (-not $pressureBundle.client.TryDequeueVehicle([ref]$record)) {
        break
      }
      $pressureRecords.Add($record)
    }
    while ($true) {
      [VcDualPortReader.CaptureRecord]$record = $null
      if (-not $pressureBundle.client.TryDequeueGround([ref]$record)) {
        break
      }
      $pressureRecords.Add($record)
    }
    # The role-local audit sorts the interleaved transport result by its
    # per-role producer sequence before validating byte patterns.
    [object[]]$orderedPressureRecords = @($pressureRecords.ToArray() |
        Sort-Object @{Expression={if($_.Role -eq 'vehicle'){0}else{1}}},
            Sequence)
    $pressureAudit = Get-ReaderBrokerRecordAudit `
        -Records $orderedPressureRecords -ExpectedVehicleBytes 48000 `
        -ExpectedGroundBytes 4800
    [long]$footerWriteStartedTicks =
        [System.Diagnostics.Stopwatch]::GetTimestamp()
    [string]$footerPath = Join-Path $EvidenceDirectory `
        'reader_broker_synthetic_footer.json'
    Write-JsonDurable -Path $footerPath -Value ([ordered]@{
      schema_version=1;stop_capture_ack_qpc_ticks=$stopAckTicks
      status='SELFTEST';runner_sha256=$sourceSha256
    })
    [long]$footerFsyncTicks =
        [System.Diagnostics.Stopwatch]::GetTimestamp()
    $pressureBundle.client.CloseExit()
    [long]$closeAckTicks =
        [System.Diagnostics.Stopwatch]::GetTimestamp()
    $closeReport = $pressureBundle.client.LatestCloseReport
    $pressureExit = Complete-ReaderBrokerSelfTestProcess `
        -Bundle $pressureBundle

    [long]$frequency = [System.Diagnostics.Stopwatch]::Frequency
    [double]$blockDurationMs =
        [double]($blockEndTicks-$blockStartTicks)*1000.0/$frequency
    [bool]$vehicleReadDuringBlock = @($orderedPressureRecords |
        Where-Object {$_.Role -eq 'vehicle' -and
          [long]$_.ProducerTimestampTicks -ge $blockStartTicks -and
          [long]$_.ProducerTimestampTicks -le $blockEndTicks}).Count -gt 0
    [bool]$groundReadDuringBlock = @($orderedPressureRecords |
        Where-Object {$_.Role -eq 'ground' -and
          [long]$_.ProducerTimestampTicks -ge $blockStartTicks -and
          [long]$_.ProducerTimestampTicks -le $blockEndTicks}).Count -gt 0
    $pressureAfter = $pressureStop.Snapshot
    $result.pressure = [pscustomobject][ordered]@{
      parent_gc=[ordered]@{gen0_delta=$gc0Delta;gen1_delta=$gc1Delta
        gen2_delta=$gc2Delta;block_duration_ms=[Math]::Round($blockDurationMs,3)}
      service_before=$pressureBefore
      service_after=$pressureAfter
      vehicle_read_during_parent_block=$vehicleReadDuringBlock
      ground_read_during_parent_block=$groundReadDuringBlock
      records=$pressureAudit
      record_count_contract=[ordered]@{
        maximum_bytes_per_record=32
        vehicle_minimum_records=[Math]::Ceiling(48000.0/32.0)
        ground_minimum_records=[Math]::Ceiling(4800.0/32.0)
        actual_vehicle_records=[long]$pressureAudit.vehicle.records
        actual_ground_records=[long]$pressureAudit.ground.records
        rationale='synthetic/SerialPort reads may legally return any 1..32 byte partial slice; sequence, raw offset, pattern, and total bytes remain exact'
      }
      stop_response_record_count=[int]$pressureStop.Records.Count
      maximum_chunk_record_count=[int]$pressureStop.BoundedRecordCount
      maximum_records_per_drain=[int]$pressureBundle.client.MaximumRecordsPerDrain
      client_queue=[ordered]@{
        vehicle_capacity=[int]$pressureBundle.client.VehicleQueueCapacity
        vehicle_high_water=[int]$pressureBundle.client.VehicleQueueHighWater
        vehicle_final_depth=[int]$pressureBundle.client.VehicleQueueDepth
        ground_capacity=[int]$pressureBundle.client.GroundQueueCapacity
        ground_high_water=[int]$pressureBundle.client.GroundQueueHighWater
        ground_final_depth=[int]$pressureBundle.client.GroundQueueDepth
      }
      lifecycle_context_id_type=
          $pressureBundle.lifecycle.context_id.GetType().FullName
      lifecycle_context_id_schema_numeric=(
          ($pressureBundle.lifecycle | ConvertTo-Json -Compress) -match
              '"context_id"\s*:\s*[0-9]+')
      exact_second_rejected=$secondExactRejected
      close_report=$closeReport
      stop_ack_qpc_ticks=$stopAckTicks
      footer_write_started_qpc_ticks=$footerWriteStartedTicks
      footer_fsync_qpc_ticks=$footerFsyncTicks
      close_ack_qpc_ticks=$closeAckTicks
      process_exit=$pressureExit
      lifecycle_ordered=($stopAckTicks -le $footerWriteStartedTicks -and
          $footerWriteStartedTicks -le $footerFsyncTicks -and
          $footerFsyncTicks -lt [long]$closeReport.GroundCloseQpcTicks -and
          $footerFsyncTicks -lt [long]$closeReport.VehicleCloseQpcTicks -and
          [long]$closeReport.GroundCloseQpcTicks -le $closeAckTicks -and
          [long]$closeReport.VehicleCloseQpcTicks -le $closeAckTicks -and
          $closeAckTicks -le [long]$pressureExit.exit_qpc_ticks)
    }
  } catch {
    $harnessErrors.Add('pressure: ' + $_.Exception.GetType().FullName +
        ': ' + $_.Exception.Message)
    if ($null -ne $pressureBundle) {
      try { [void](Stop-ReaderBrokerEmergency -Bundle $pressureBundle) }
      catch {}
    }
  }

  $overflowBundle = $null
  try {
    $overflowBundle = Start-ReaderBrokerClient -Scenario 'overflow' `
        -RingSlots 4 -VehicleBytes 1024 -GroundBytes 0 `
        -ConnectTimeoutMs 30000 -BaseElapsedMs 2345.0 `
        -ExpectedRunnerSha256 $sourceSha256
    Start-Sleep -Milliseconds 100
    $overflowSnapshot = $overflowBundle.client.Snapshot()
    [bool[]]$mutationRejected = @($false,$false,$false,$false)
    try { $overflowBundle.vehicle_proxy.Write([byte[]](9),0,1) }
    catch { $mutationRejected[0]=$true }
    try { $overflowBundle.vehicle_proxy.BaseStream.Flush() }
    catch { $mutationRejected[1]=$true }
    try { $overflowBundle.ground_proxy.WriteExactFixture(
        $Fixture,$script:ExpectedFixtureSha256) }
    catch { $mutationRejected[2]=$true }
    try { [void]$overflowBundle.client.TransitionCaptureContext(
        'fatal_forbidden','fatal_forbidden') }
    catch { $mutationRejected[3]=$true }
    $overflowStop = $overflowBundle.client.StopCapture()
    $overflowRecords = New-Object 'System.Collections.Generic.List[object]'
    while ($true) {
      [VcDualPortReader.CaptureRecord]$record = $null
      if (-not $overflowBundle.client.TryDequeueVehicle([ref]$record)) {break}
      $overflowRecords.Add($record)
    }
    $overflowAudit = Get-ReaderBrokerRecordAudit `
        -Records $overflowRecords.ToArray() -ExpectedVehicleBytes 128 `
        -ExpectedGroundBytes 0
    $overflowBundle.client.CloseExit()
    $overflowClose = $overflowBundle.client.LatestCloseReport
    $overflowExit = Complete-ReaderBrokerSelfTestProcess `
        -Bundle $overflowBundle
    $result.overflow = [pscustomobject][ordered]@{
      snapshot=$overflowSnapshot;stop=$overflowStop.Snapshot
      records=$overflowAudit;mutation_rejected=$mutationRejected
      close_report=$overflowClose;process_exit=$overflowExit
    }
  } catch {
    $harnessErrors.Add('overflow: ' + $_.Exception.GetType().FullName +
        ': ' + $_.Exception.Message)
    if ($null -ne $overflowBundle) {
      try { [void](Stop-ReaderBrokerEmergency -Bundle $overflowBundle) }
      catch {}
    }
  }

  $timestampBundle = $null
  try {
    $timestampBundle = Start-ReaderBrokerClient -Scenario 'timestamp' `
        -RingSlots 8 -VehicleBytes 32 -GroundBytes 0 `
        -ConnectTimeoutMs 30000 -BaseElapsedMs 3456.0 `
        -ExpectedRunnerSha256 $sourceSha256
    Start-Sleep -Milliseconds 175
    [long]$timestampConsumerTicks =
        [System.Diagnostics.Stopwatch]::GetTimestamp()
    $timestampStop = $timestampBundle.client.StopCapture()
    [VcDualPortReader.CaptureRecord]$timestampRecord = $null
    [bool]$timestampGot = $timestampBundle.client.TryDequeueVehicle(
        [ref]$timestampRecord)
    [double]$timestampDelayMs = if ($timestampGot) {
      [double]($timestampConsumerTicks-
          [long]$timestampRecord.ProducerTimestampTicks)*1000.0 /
          [System.Diagnostics.Stopwatch]::Frequency
    } else { [double]0.0 }
    $timestampBundle.client.CloseExit()
    $timestampExit = Complete-ReaderBrokerSelfTestProcess `
        -Bundle $timestampBundle
    $result.timestamp = [pscustomobject][ordered]@{
      got_record=$timestampGot;consumer_delay_ms=[Math]::Round($timestampDelayMs,3)
      sequence=if($timestampGot){[long]$timestampRecord.Sequence}else{-1}
      raw_start_offset=if($timestampGot){
        [long]$timestampRecord.RawStartOffset}else{-1}
      producer_timestamp_ticks=if($timestampGot){
        [long]$timestampRecord.ProducerTimestampTicks}else{0}
      producer_elapsed_ms=if($timestampGot){
        [double]$timestampRecord.ProducerElapsedMs}else{$null}
      stop=$timestampStop.Snapshot;process_exit=$timestampExit
    }
  } catch {
    $harnessErrors.Add('timestamp: ' + $_.Exception.GetType().FullName +
        ': ' + $_.Exception.Message)
    if ($null -ne $timestampBundle) {
      try { [void](Stop-ReaderBrokerEmergency -Bundle $timestampBundle) }
      catch {}
    }
  }

  $barrierBundle = $null
  try {
    $barrierParentWatch = [System.Diagnostics.Stopwatch]::StartNew()
    $barrierClockAnchor = New-ReaderClockAnchor -RunWatch $barrierParentWatch
    [int]$barrierLaunchDelayMs = 175
    Start-Sleep -Milliseconds $barrierLaunchDelayMs
    $barrierBundle = Start-ReaderBrokerClient -Scenario 'barrier' `
        -RingSlots 16 -VehicleBytes 64 -GroundBytes 0 `
        -ConnectTimeoutMs 30000 `
        -QpcOriginTicks ([long]$barrierClockAnchor.qpc_origin_ticks) `
        -BaseElapsedMs ([double]$barrierClockAnchor.base_elapsed_ms) `
        -ExpectedRunnerSha256 $sourceSha256 `
        -InitialPhase 'ports_opening' -InitialEpoch 'boot_observe'
    [double]$barrierParentHorizonMs =
        [double]$barrierParentWatch.Elapsed.TotalMilliseconds
    $barrierHeartbeatEvents =
        New-Object 'System.Collections.Generic.List[object]'
    $barrierHeartbeatAccumulator = New-HeartbeatWindowAccumulator `
        -M0ElapsedMs 0.0
    Update-HeartbeatWindowAccumulator -State $barrierHeartbeatAccumulator `
        -Events $barrierHeartbeatEvents `
        -ThroughElapsedMs $barrierParentHorizonMs
    [long]$barrierRequestTicks =
        [System.Diagnostics.Stopwatch]::GetTimestamp()
    $transitionBarrier = $barrierBundle.client.TransitionCaptureContext(
        'after_inflight_barrier','epoch_after_inflight_barrier')
    [long]$barrierAckTicks =
        [System.Diagnostics.Stopwatch]::GetTimestamp()
    [bool]$barrierFinalizationSucceeded = $false
    [string]$barrierFinalizationError = ''
    try {
      Update-HeartbeatWindowAccumulator -State $barrierHeartbeatAccumulator `
          -Events $barrierHeartbeatEvents `
          -ThroughElapsedMs ([double]$transitionBarrier.Ground.BoundaryElapsedMs)
      [void](Get-HeartbeatWindowAccumulatorSnapshot `
          -State $barrierHeartbeatAccumulator `
          -M1ElapsedMs ([double]$transitionBarrier.Ground.BoundaryElapsedMs))
      $barrierFinalizationSucceeded = $true
    } catch {
      $barrierFinalizationError = $_.Exception.Message
    }
    Start-Sleep -Milliseconds 50
    $barrierStop = $barrierBundle.client.StopCapture()
    $barrierRecords = New-Object 'System.Collections.Generic.List[object]'
    while ($true) {
      [VcDualPortReader.CaptureRecord]$record = $null
      if (-not $barrierBundle.client.TryDequeueVehicle([ref]$record)) {break}
      $barrierRecords.Add($record)
    }
    $barrierBundle.client.CloseExit()
    $barrierExit = Complete-ReaderBrokerSelfTestProcess -Bundle $barrierBundle
    [object[]]$barrierArray = $barrierRecords.ToArray()
    $result.barrier = [pscustomobject][ordered]@{
      request_to_ack_ms=[Math]::Round(
          [double]($barrierAckTicks-$barrierRequestTicks)*1000.0 /
          [System.Diagnostics.Stopwatch]::Frequency,3)
      transition_barrier=$transitionBarrier
      clock_anchor=[ordered]@{
        qpc_origin_ticks=[long]$barrierClockAnchor.qpc_origin_ticks
        base_elapsed_ms=[double]$barrierClockAnchor.base_elapsed_ms
        bracket_span_qpc_ticks=
            [long]$barrierClockAnchor.bracket_span_qpc_ticks
        launch_delay_ms=$barrierLaunchDelayMs
        broker_source=$barrierBundle.lifecycle.clock_anchor.source
        caller_pair_provided=
            [bool]$barrierBundle.lifecycle.clock_anchor.caller_pair_provided
      }
      parent_accumulator_horizon_ms=$barrierParentHorizonMs
      producer_m1_elapsed_ms=
          [double]$transitionBarrier.Ground.BoundaryElapsedMs
      shared_completion_elapsed_ms=
          [double]$transitionBarrier.CapturedElapsedMs
      producer_m1_not_before_parent_horizon=(
          [double]$transitionBarrier.Ground.BoundaryElapsedMs -ge
          $barrierParentHorizonMs)
      exact_m1_finalization_succeeded=$barrierFinalizationSucceeded
      exact_m1_finalization_error=$barrierFinalizationError
      qual008_regression=[ordered]@{
        recorded_parent_last_update_minimum_ms=589628.479
        recorded_broker_m1_ms=589508.415
        recorded_backward_minimum_ms=120.064
        correction='paired QPC origin and elapsed base; official M1 is not clamped'
      }
      records=$barrierArray
      stop=$barrierStop.Snapshot;process_exit=$barrierExit
      exact_inflight_inclusion=(
        [long]$transitionBarrier.Vehicle.SequenceExclusive -eq 1 -and
        [long]$transitionBarrier.Vehicle.RawOffsetExclusive -eq 32 -and
        [uint32]$transitionBarrier.Vehicle.OldContextId -eq [uint32]0 -and
        [uint32]$transitionBarrier.Vehicle.NewContextId -eq [uint32]1 -and
        [uint32]$transitionBarrier.Ground.OldContextId -eq [uint32]0 -and
        [uint32]$transitionBarrier.Ground.NewContextId -eq [uint32]1 -and
        $barrierArray.Count -eq 2 -and
        [long]$barrierArray[0].Sequence -eq 0 -and
        [long]$barrierArray[0].RawStartOffset -eq 0 -and
        [int]$barrierArray[0].Count -eq 32 -and
        [uint32]$barrierArray[0].ContextId -eq [uint32]0 -and
        [long]$barrierArray[0].ProducerTimestampTicks -le
            [long]$transitionBarrier.Vehicle.BoundaryTimestampTicks -and
        [string]$barrierArray[0].ProducerPhase -ceq 'ports_opening' -and
        [string]$barrierArray[0].ProducerEpoch -ceq 'boot_observe' -and
        [long]$barrierArray[1].Sequence -eq 1 -and
        [long]$barrierArray[1].RawStartOffset -eq 32 -and
        [int]$barrierArray[1].Count -eq 32 -and
        [uint32]$barrierArray[1].ContextId -eq [uint32]1 -and
        [long]$barrierArray[1].ProducerTimestampTicks -ge
            [long]$transitionBarrier.Vehicle.BoundaryTimestampTicks -and
        [string]$barrierArray[1].ProducerPhase -eq
            'after_inflight_barrier' -and
        [string]$barrierArray[1].ProducerEpoch -ceq
            'epoch_after_inflight_barrier')
    }
  } catch {
    $harnessErrors.Add('barrier: ' + $_.Exception.GetType().FullName +
        ': ' + $_.Exception.Message)
    if ($null -ne $barrierBundle) {
      try { [void](Stop-ReaderBrokerEmergency -Bundle $barrierBundle) }
      catch {}
    }
  }

  $ackLossBundle = $null
  try {
    $ackLossBundle = Start-ReaderBrokerClient -Scenario 'ackloss' `
        -RingSlots 8 -VehicleBytes 0 -GroundBytes 0 `
        -ConnectTimeoutMs 30000 -BaseElapsedMs 5678.0 `
        -ExpectedRunnerSha256 $sourceSha256
    $uncertainState = [pscustomobject][ordered]@{
      attempt_count=0;write_count=0;write_uncertain=$false
      write_disposition='NOT_ATTEMPTED'
      final_write_elapsed_ms=$null;final_write_utc=$null
    }
    [bool]$firstUncertain = $false
    [bool]$parentSecondRejected = $false
    [bool]$childSecondRejected = $false
    try { Write-ExactRequestOnce -Serial $ackLossBundle.ground_proxy `
        -Fixture $Fixture -InjectionState $uncertainState }
    catch { $firstUncertain=$true }
    try { Write-ExactRequestOnce -Serial $ackLossBundle.ground_proxy `
        -Fixture $Fixture -InjectionState $uncertainState }
    catch { $parentSecondRejected=$true }
    try { $ackLossBundle.ground_proxy.WriteExactFixture(
        $Fixture,$script:ExpectedFixtureSha256) }
    catch { $childSecondRejected=$true }
    $ackLossStop = $ackLossBundle.client.StopCapture()
    $ackLossBundle.client.CloseExit()
    $ackLossClose = $ackLossBundle.client.LatestCloseReport
    $ackLossExit = Complete-ReaderBrokerSelfTestProcess `
        -Bundle $ackLossBundle
    $result.uncertainty = [pscustomobject][ordered]@{
      first_response_uncertain=$firstUncertain
      parent_second_attempt_rejected=$parentSecondRejected
      child_second_attempt_rejected=$childSecondRejected
      transport_write_count=[long]$ackLossClose.GroundWriteOperationCount
      injection_state=$uncertainState
      stop=$ackLossStop.Snapshot;close_report=$ackLossClose
      process_exit=$ackLossExit
    }
  } catch {
    $harnessErrors.Add('uncertainty: ' + $_.Exception.GetType().FullName +
        ': ' + $_.Exception.Message)
    if ($null -ne $ackLossBundle) {
      try { [void](Stop-ReaderBrokerEmergency -Bundle $ackLossBundle) }
      catch {}
    }
  }

  try {
    [bool]$openStartIOExceptionSurfaced = $false
    [bool]$openStartGenericPipeEof = $false
    [string]$openStartIOExceptionMessage = ''
    try {
      [void](Start-ReaderBrokerClient -Scenario 'openio' `
          -RingSlots 8 -VehicleBytes 0 -GroundBytes 0 `
          -ConnectTimeoutMs 30000 -BaseElapsedMs 6123.0 `
          -ExpectedRunnerSha256 $sourceSha256)
    } catch {
      $openStartIOExceptionMessage = [string]$_.Exception.Message
      $openStartIOExceptionSurfaced = ($openStartIOExceptionMessage -match
          'reader broker ERROR: System\.IO\.IOException: OPEN_START synthetic IOException')
      $openStartGenericPipeEof = ($openStartIOExceptionMessage -match
          'reader broker pipe closed during bounded receive')
    }
    $result.open_start_ioexception = [pscustomobject][ordered]@{
      exact_child_error_surfaced=$openStartIOExceptionSurfaced
      generic_pipe_eof=$openStartGenericPipeEof
      message=$openStartIOExceptionMessage
      serial_enumeration_count=0
      serial_port_construction_count=0
      serial_open_count=0
      request_write_count=0
    }
  } catch {
    $harnessErrors.Add('open_start_ioexception: ' +
        $_.Exception.GetType().FullName + ': ' + $_.Exception.Message)
  }

  try {
    [bool]$configMismatchRejected = $false
    [string]$configMismatchError = ''
    try {
      [void](Start-ReaderBrokerClient -Scenario 'timestamp' `
          -RingSlots 8 -VehicleBytes 32 -GroundBytes 0 `
          -ConnectTimeoutMs 30000 -BaseElapsedMs 6789.0 `
          -ExpectedRunnerSha256 $sourceSha256 `
          -SelfTestExpectedRingSlots 9)
    } catch {
      $configMismatchError = $_.Exception.Message
      $configMismatchRejected = $configMismatchError -match
          'requested configuration mismatch'
    }
    $result.config_mismatch = [pscustomobject][ordered]@{
      rejected_before_open_start=$configMismatchRejected
      actual_ring_slots=8;expected_ring_slots=9
      error=$configMismatchError
    }
  } catch {
    $harnessErrors.Add('config_mismatch: ' +
        $_.Exception.GetType().FullName + ': ' + $_.Exception.Message)
  }

  try {
    $argvRows = New-Object 'System.Collections.Generic.List[object]'
    [bool]$argvValid = $true
    foreach ($sample in @('', 'plain', 'path with spaces',
        'C:\path\with\slashes\', 'embedded"quote',
        'mix\\before"quote\tail')) {
      [string]$encoded = ConvertTo-WindowsCommandLineArgument -Value $sample
      [string[]]$decoded =
          [VcDualPortReader.BrokerProcessContainment]::ParseWindowsCommandLine(
            ('broker-selftest.exe ' + $encoded))
      [bool]$roundTrip = ($decoded.Count -eq 2 -and
          [string]$decoded[1] -ceq [string]$sample)
      if (-not $roundTrip) { $argvValid=$false }
      $argvRows.Add([pscustomobject][ordered]@{
        input=$sample;encoded=$encoded;decoded=$decoded;valid=$roundTrip
      })
    }
    $result.argv = [pscustomobject][ordered]@{
      valid=$argvValid;rows=$argvRows.ToArray()
    }
  } catch {
    $harnessErrors.Add('argv: ' + $_.Exception.GetType().FullName +
        ': ' + $_.Exception.Message)
  }

  $result.errors = $harnessErrors.ToArray()
  return [pscustomobject]$result
}

function Invoke-OfflineSelfTest {
  $repo = Split-Path -Parent $PSScriptRoot
  if ([string]::IsNullOrWhiteSpace($SelfTestEvidenceDirectory)) {
    $stamp = [DateTime]::UtcNow.ToString('yyyyMMddTHHmmssfffZ')
    $SelfTestEvidenceDirectory = Join-Path $repo `
        ('runs\validation\HIL-DUAL-DIAG-PARAM-LIST-RUNNER-SELFTEST-001\' +
         $stamp)
  }
  if (Test-Path -LiteralPath $SelfTestEvidenceDirectory) {
    throw "SelfTest evidence directory exists; refusing overwrite: $SelfTestEvidenceDirectory"
  }
  [void][System.IO.Directory]::CreateDirectory($SelfTestEvidenceDirectory)
  $cases = New-Object 'System.Collections.Generic.List[object]'
  function Add-SelfCase {
    param([string]$Name, [bool]$Passed, [string]$Detail)
    $cases.Add([pscustomobject][ordered]@{
      name = $Name; passed = $Passed; detail = $Detail
    })
  }
  function Test-ListCase {
    param([object[]]$Rows, [bool]$ExpectedValid)
    $state = New-ParamListState
    [double]$elapsed = 1000.0
    foreach ($row in $Rows) {
      [byte[]]$payload = New-ParamValuePayload -ParamId ([string]$row.id) `
          -Index ([int]$row.index) -Count ([int]$row.count) `
          -Type ([byte]$row.type)
      Add-ParamValuePayload -State $state -Payload $payload `
          -SystemId ([int]$row.system) -ComponentId ([int]$row.component) `
          -Sequence ([int]($state.events.Count % 256)) -ElapsedMs $elapsed
      $elapsed += 500.0
    }
    $assessment = Complete-ParamListAssessment -State $state
    return [pscustomobject]@{
      passed = ([bool]$assessment.valid -eq $ExpectedValid)
      assessment = $assessment
      state = $state
    }
  }
  function New-OrderedRows {
    $rows = New-Object 'System.Collections.Generic.List[object]'
    for ($index = 0; $index -lt 932; ++$index) {
      $rows.Add([pscustomobject]@{
        id = ('P{0:D4}' -f $index); index = $index; count = 932
        type = 6; system = 1; component = 1
      })
    }
    return ,$rows
  }

  $genericEventProbeRows = New-Object `
      'System.Collections.Generic.List[object]'
  [bool]$genericEventEnumerationPassed = $true
  foreach ($probeCount in @(0, 1, 2)) {
    $probeState = New-ParamListState
    for ($probeIndex = 0; $probeIndex -lt $probeCount; ++$probeIndex) {
      $probeState.events.Add([pscustomobject][ordered]@{
        index=$probeIndex;capture_scope='offline_ps51_probe'
      })
    }
    $copiedEvents = New-Object 'System.Collections.Generic.List[object]'
    [bool]$copySucceeded = $true
    [string]$copyError = ''
    try {
      foreach ($probeEvent in $probeState.events.ToArray()) {
        $copiedEvents.Add($probeEvent)
      }
    } catch {
      $copySucceeded = $false
      $copyError = $_.Exception.GetType().FullName + ': ' +
          $_.Exception.Message
    }
    [bool]$cardinalityExact = ($copiedEvents.Count -eq $probeCount)
    [bool]$orderExact = $true
    for ($probeIndex = 0; $probeIndex -lt $copiedEvents.Count;
        ++$probeIndex) {
      if ([int]$copiedEvents[$probeIndex].index -ne $probeIndex) {
        $orderExact = $false
      }
    }
    if (-not $copySucceeded -or -not $cardinalityExact -or
        -not $orderExact) {
      $genericEventEnumerationPassed = $false
    }
    $genericEventProbeRows.Add([pscustomobject][ordered]@{
      source_count=$probeCount;copy_succeeded=$copySucceeded
      copied_count=$copiedEvents.Count;cardinality_exact=$cardinalityExact
      order_exact=$orderExact;error=$copyError
    })
  }
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
      'ps51_generic_param_event_enumeration.json') -Value ([ordered]@{
        schema_version=1
        powershell_version=$PSVersionTable.PSVersion.ToString()
        passed=$genericEventEnumerationPassed
        rows=$genericEventProbeRows.ToArray()
      })
  Add-SelfCase 'ps51_generic_param_event_enumeration_0_1_n' `
      $genericEventEnumerationPassed `
      'live ParamList Generic.List event copying uses ToArray and preserves 0/1/2 cardinality and order'

  # Execute the actual live tagged-line functions from their AST extents.
  # They are declared after the early SelfTest return, so this probe loads
  # only the three pure matcher functions and never reaches live COM code.
  $taggedElapsedProbe = [ordered]@{
    schema_version=1;passed=$false;powershell_version=
        $PSVersionTable.PSVersion.ToString()
    complete_line='VCSTAT1 q=1 ms=2';explicit=$null;implicit=$null
    function_definition_count=0;serial_enumeration_count=0
    serial_port_construction_count=0;serial_open_count=0;error=''
  }
  $savedTaggedProbeRunWatch = $script:RunWatch
  $taggedProbeWatch = $null
  try {
    $taggedProbeTokens = $null
    $taggedProbeParseErrors = $null
    $taggedProbeAst =
        [System.Management.Automation.Language.Parser]::ParseFile(
          $PSCommandPath, [ref]$taggedProbeTokens,
          [ref]$taggedProbeParseErrors)
    if (@($taggedProbeParseErrors).Count -ne 0) {
      throw 'tagged elapsed probe could not parse the runner source'
    }
    foreach ($functionName in @('New-CaptureState',
        'Reset-TagMatcherCandidate','Add-TaggedMatcherByte')) {
      $definitions = @($taggedProbeAst.FindAll({
        param($node)
        $node -is
            [System.Management.Automation.Language.FunctionDefinitionAst] -and
        $node.Name -ceq $functionName
      }, $true))
      if ($definitions.Count -ne 1) {
        throw "tagged elapsed probe function cardinality failed: $functionName"
      }
      . ([ScriptBlock]::Create($definitions[0].Extent.Text))
      ++$taggedElapsedProbe.function_definition_count
    }
    $taggedProbeWatch = [System.Diagnostics.Stopwatch]::StartNew()
    $script:RunWatch = $taggedProbeWatch
    [byte[]]$taggedLineBytes = [System.Text.Encoding]::ASCII.GetBytes(
        "VCSTAT1 q=1 ms=2`n")
    foreach ($probeSpec in @(
        [pscustomobject]@{name='explicit';include_elapsed=$true},
        [pscustomobject]@{name='implicit';include_elapsed=$false})) {
      $memory = New-Object System.IO.MemoryStream
      try {
        $state = New-CaptureState -Role 'vehicle' -TagBase 'VCSTAT' `
            -RawStream $memory -Mavlink $null
        for ($byteIndex = 0; $byteIndex -lt $taggedLineBytes.Length;
            ++$byteIndex) {
          if ($probeSpec.include_elapsed) {
            Add-TaggedMatcherByte -State $state `
                -Byte $taggedLineBytes[$byteIndex] -RawOffset $byteIndex `
                -ElapsedMs 123.456 -ProducerPhase 'probe_phase' `
                -ProducerEpoch 'probe_epoch'
          } else {
            Add-TaggedMatcherByte -State $state `
                -Byte $taggedLineBytes[$byteIndex] -RawOffset $byteIndex `
                -ProducerPhase 'probe_phase' -ProducerEpoch 'probe_epoch'
          }
        }
        if ($state.TaggedLines.Count -ne 1) {
          throw "tagged elapsed $($probeSpec.name) line count was not one"
        }
        $row = $state.TaggedLines[0]
        $taggedElapsedProbe[$probeSpec.name] = [ordered]@{
          line_count=$state.TaggedLines.Count
          elapsed_ms=[double]$row.elapsed_ms
          phase=[string]$row.phase
          producer_epoch=[string]$row.producer_epoch
          valid_correlation=[bool]$row.valid_correlation
        }
      } finally {
        $memory.Dispose()
      }
    }
    $taggedElapsedProbe.passed = (
      [int]$taggedElapsedProbe.function_definition_count -eq 3 -and
      [double]$taggedElapsedProbe.explicit.elapsed_ms -eq 123.456 -and
      [double]$taggedElapsedProbe.implicit.elapsed_ms -ge 0.0 -and
      [string]$taggedElapsedProbe.explicit.phase -ceq 'probe_phase' -and
      [string]$taggedElapsedProbe.explicit.producer_epoch -ceq
          'probe_epoch' -and
      [bool]$taggedElapsedProbe.explicit.valid_correlation -and
      [bool]$taggedElapsedProbe.implicit.valid_correlation)
  } catch {
    $taggedElapsedProbe.error =
        $_.Exception.GetType().FullName + ': ' + $_.Exception.Message
  } finally {
    if ($null -ne $taggedProbeWatch) { $taggedProbeWatch.Stop() }
    $script:RunWatch = $savedTaggedProbeRunWatch
  }
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
      'tagged_elapsed_runtime_probe.json') -Value $taggedElapsedProbe
  Add-SelfCase 'tagged_elapsed_expression_ps51_runtime' `
      ([bool]$taggedElapsedProbe.passed) `
      ('the actual complete tagged-line path accepts explicit and implicit ' +
       'ElapsedMs on Windows PowerShell 5.1 without treating if as a command; ' +
       'error=' + [string]$taggedElapsedProbe.error)

  [int]$sliceRemaining = 4096
  [int]$sliceTotal = 0
  [int]$sliceMaximum = 0
  [int]$sliceCount = 0
  while ($sliceRemaining -gt 0) {
    [int]$sliceSize = Get-SerialReadSliceSize `
        -Available $sliceRemaining -BufferLength 4096
    if ($sliceSize -le 0) { break }
    $sliceMaximum = [Math]::Max($sliceMaximum, $sliceSize)
    $sliceTotal += $sliceSize
    $sliceRemaining -= $sliceSize
    ++$sliceCount
  }
  [bool]$serialReadSlicePassed = (
    $script:SerialReadSliceBytes -eq 32 -and
    $script:SerialReadSlicesPerTurn -eq 1 -and
    (Get-SerialReadSliceSize -Available 0 -BufferLength 4096) -eq 0 -and
    (Get-SerialReadSliceSize -Available 31 -BufferLength 4096) -eq 31 -and
    (Get-SerialReadSliceSize -Available 32 -BufferLength 4096) -eq 32 -and
    (Get-SerialReadSliceSize -Available 33 -BufferLength 4096) -eq 32 -and
    (Get-SerialReadSliceSize -Available 4096 -BufferLength 31) -eq 31 -and
    (Get-SerialReadSliceSize -Available 4096 -BufferLength 32) -eq 32 -and
    (Get-SerialReadSliceSize -Available 4096 -BufferLength 33) -eq 32 -and
    (Get-SerialReadSliceSize -Available 4096 -BufferLength 4096 `
        -MaximumBytesPerRead 17) -eq 17 -and
    $sliceTotal -eq 4096 -and $sliceRemaining -eq 0 -and
    $sliceMaximum -eq 32 -and $sliceCount -eq 128)
  [string]$serialReadSliceDetail =
      ('4096 pending bytes split into {0} slices; max={1}; total={2}; ' +
       'one slice per role per pump turn') -f `
          $sliceCount, $sliceMaximum, $sliceTotal
  Add-SelfCase 'serial_read_slice_bounds_32_bytes' `
      $serialReadSlicePassed $serialReadSliceDetail

  $readerPressureResult = $null
  $readerHarnessResult = $null
  $pressureHarness = $null
  [string]$readerHarnessError = ''
  try {
    Initialize-DualPortReaderWorkerType
    $pressureHarness = `
        [VcDualPortReader.WorkerHarness]::StartPowerShellPressure()
    [int]$gc0Before = [GC]::CollectionCount(0)
    [int]$gc1Before = [GC]::CollectionCount(1)
    [int]$gc2Before = [GC]::CollectionCount(2)
    $powerShellAllocationPressure = `
        New-Object 'System.Collections.Generic.List[object]'
    for ($pressureIndex = 0; $pressureIndex -lt 6000;
        ++$pressureIndex) {
      [byte[]]$pressurePayload = New-Object byte[] 512
      $pressurePayload[0] = [byte]($pressureIndex -band 0xFF)
      $powerShellAllocationPressure.Add([pscustomobject][ordered]@{
        index=$pressureIndex
        phase='stage005_style_admin_allocation_pressure'
        payload=$pressurePayload
      })
    }
    [GC]::Collect()
    [GC]::WaitForPendingFinalizers()
    [GC]::Collect()
    Start-Sleep -Milliseconds 350
    [int]$gc0Delta = [GC]::CollectionCount(0) - $gc0Before
    [int]$gc1Delta = [GC]::CollectionCount(1) - $gc1Before
    [int]$gc2Delta = [GC]::CollectionCount(2) - $gc2Before
    $readerPressureResult = $pressureHarness.Complete(
        $gc0Delta, $gc1Delta, $gc2Delta)
    $powerShellAllocationPressure.Clear()
    $powerShellAllocationPressure = $null
    $readerHarnessResult = [VcDualPortReader.WorkerHarness]::RunAll()
  } catch {
    $readerHarnessError = $_.Exception.GetType().FullName + ': ' +
        $_.Exception.Message
    try {
      if ($null -ne $pressureHarness -and
          $null -eq $readerPressureResult) {
        $readerPressureResult = $pressureHarness.Complete(0, 0, 0)
      }
    } catch {}
  }
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
      'reader_worker_harness.json') -Value ([ordered]@{
        schema_version=1
        worker_type='VcDualPortReader.DualPortReaderWorker'
        producer_clock='System.Diagnostics.Stopwatch.GetTimestamp'
        consumer_timestamp_substitution=$false
        fairness_hard_limit_ms=100.0
        fairness_comparison='producer service gap/read duration strictly < hard limit'
        power_shell_allocation_count=6000
        power_shell_allocation_bytes_each=512
        explicit_consumer_block_ms=350
        pressure=$readerPressureResult
        failure_modes=$readerHarnessResult
        error=$readerHarnessError
      })
  [bool]$readerForcedGcPassed = ($null -ne $readerPressureResult -and
      [bool]$readerPressureResult.ForcedGcPassed)
  [bool]$readerAdminBlockPassed = ($null -ne $readerPressureResult -and
      [bool]$readerPressureResult.AdminBlockPassed)
  [bool]$readerFloodPassed = ($null -ne $readerPressureResult -and
      [bool]$readerPressureResult.FloodPassed)
  [bool]$readerOverflowPassed = ($null -ne $readerHarnessResult -and
      [bool]$readerHarnessResult.OverflowPassed)
  [bool]$readerTimestampPassed = ($null -ne $readerHarnessResult -and
      [bool]$readerHarnessResult.TimestampPassed)
  [bool]$readerShutdownPassed = ($null -ne $readerHarnessResult -and
      [bool]$readerHarnessResult.ShutdownPassed)
  [bool]$readerInProcessCharacterized = (
      $null -ne $readerPressureResult -and
      [int]$readerPressureResult.Gc0Delta -gt 0 -and
      [int]$readerPressureResult.Gc1Delta -gt 0 -and
      [int]$readerPressureResult.Gc2Delta -gt 0)
  Add-SelfCase 'reader_worker_full_gc_characterized_not_selected' `
      $readerInProcessCharacterized `
      ('in-process worker remains diagnostic-only because parent full GC ' +
       'shares its CLR stop-the-world pause; broker isolation is required; error=' +
       $readerHarnessError)
  Add-SelfCase 'reader_worker_asymmetric_flood_lossless' `
      $readerFloodPassed `
      '131072 Vehicle bytes and 8192 Ground bytes retain exact sequence/raw-offset continuity without ring overflow'
  Add-SelfCase 'reader_worker_overflow_fail_closed_no_overwrite' `
      $readerOverflowPassed `
      'a four-slot ring latches overflow, keeps sequences 0..3 intact, never overwrites, and invalidates the worker'
  Add-SelfCase 'reader_worker_producer_timestamp_not_consumer_time' `
      $readerTimestampPassed `
      'a record delayed over 100 ms before consumption retains its producer Stopwatch timestamp, sequence, and raw offset'
  Add-SelfCase 'reader_worker_shutdown_barrier_exact' `
      $readerShutdownPassed `
      'barrier sequence equals final production; both threads join and exact byte/queue continuity drains to zero'

  $readerBrokerHarness = $null
  [string]$readerBrokerHarnessError = ''
  try {
    $readerBrokerHarness = Invoke-ReaderBrokerOfflineHarness `
        -EvidenceDirectory $SelfTestEvidenceDirectory `
        -Fixture (ConvertFrom-Hex -Hex $script:ExpectedFixtureHex)
  } catch {
    $readerBrokerHarnessError = $_.Exception.GetType().FullName + ': ' +
        $_.Exception.Message
  }
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
      'reader_broker_harness.json') -Value ([ordered]@{
        schema_version=1
        broker_type='VcDualPortReader.ReaderBrokerServer'
        parent_process_id=$PID
        serial_enumeration_count=0
        serial_port_construction_count=0
        serial_open_count=0
        request_write_count=0
        harness=$readerBrokerHarness
        error=$readerBrokerHarnessError
      })

  $pressure = if ($null -ne $readerBrokerHarness) {
    $readerBrokerHarness.pressure
  } else { $null }
  $overflow = if ($null -ne $readerBrokerHarness) {
    $readerBrokerHarness.overflow
  } else { $null }
  $timestamp = if ($null -ne $readerBrokerHarness) {
    $readerBrokerHarness.timestamp
  } else { $null }
  $barrier = if ($null -ne $readerBrokerHarness) {
    $readerBrokerHarness.barrier
  } else { $null }
  $uncertainty = if ($null -ne $readerBrokerHarness) {
    $readerBrokerHarness.uncertainty
  } else { $null }
  $openStartIOException = if ($null -ne $readerBrokerHarness) {
    $readerBrokerHarness.open_start_ioexception
  } else { $null }
  $configMismatch = if ($null -ne $readerBrokerHarness) {
    $readerBrokerHarness.config_mismatch
  } else { $null }
  $argv = if ($null -ne $readerBrokerHarness) {
    $readerBrokerHarness.argv
  } else { $null }

  [bool]$brokerParentFullGcPassed = (
    $null -ne $pressure -and
    [int]$pressure.parent_gc.gen0_delta -gt 0 -and
    [int]$pressure.parent_gc.gen1_delta -gt 0 -and
    [int]$pressure.parent_gc.gen2_delta -gt 0 -and
