  $r4CandidateBoundary = Get-ReadinessRawFsyncAgeDecision `
      -LastRawFlushElapsedMs 781672.113 -CurrentElapsedMs 806482.950
  $r4AfterCandidateBoundary = Get-ReadinessRawFsyncAgeDecision `
