    post_ground_status='COMPLETE';post_vehicle_status='COMPLETE'
    footer_completed=$true;parser_disabled_and_reset=$true
  }
  Add-SelfCase 'readiness_timeout_setup_invalid_fail1' `
      ($readinessTimeoutOutcome.status -eq 'FAIL' -and
       $readinessTimeoutOutcome.exit_code -eq 1 -and
       $readinessTimeoutOutcome.setup_invalid -and
       $readinessTimeoutOutcome.open_counts.vehicle -eq 1 -and
       $readinessTimeoutOutcome.open_counts.ground -eq 1 -and
       $readinessTimeoutOutcome.request_write_count -eq 0 -and
       $readinessTimeoutOutcome.post_ground_status -eq 'COMPLETE' -and
       $readinessTimeoutOutcome.post_vehicle_status -eq 'COMPLETE' -and
       $readinessTimeoutOutcome.footer_completed -and
       $readinessTimeoutOutcome.parser_disabled_and_reset) `
      'readiness timeout remains setup-invalid FAIL/1 with open1/1, write0, common post diagnostics and complete footer'

  $passiveFullCapture = [pscustomobject][ordered]@{
    started_elapsed_ms=1000.0;finished_elapsed_ms=6000.0
    completed_duration=$true
  }
  $passiveNoHeartbeat = Test-DataPlanePassiveCandidate -Events @() `
      -ParserIntegrity $readinessCleanIntegrity -Capture $passiveFullCapture `
      -Idle $true -GroundRawStartOffset 100 -GroundRawEndOffset 100
  Add-SelfCase 'passive_prefilter_no_hb_vehicle_query_zero' `
      (-not $passiveNoHeartbeat.candidate -and
       -not $passiveNoHeartbeat.sync_invalid -and
       $passiveNoHeartbeat.heartbeat.count -eq 0) `
      'HB absence is a passive retry and authorizes zero Vehicle diagnostic queries'
  $passiveWrongSource = Test-DataPlanePassiveCandidate `
      -Events $readinessWrongSourceEvents `
      -ParserIntegrity $readinessCleanIntegrity -Capture $passiveFullCapture `
      -Idle $true -GroundRawStartOffset 100 -GroundRawEndOffset 142
  Add-SelfCase 'passive_prefilter_wrong_source_vehicle_query_zero' `
      (-not $passiveWrongSource.candidate -and
       -not $passiveWrongSource.sync_invalid -and
       $passiveWrongSource.heartbeat.count -eq 0) `
      'wrong-source heartbeat cannot authorize a Vehicle diagnostic query'
  [object[]]$passiveOneHeartbeatEvents = [object[]]@(
    [pscustomobject]@{
      message_id=0;system_id=1;component_id=1;elapsed_ms=2000.0
    })
  $passiveOneHeartbeat = Test-DataPlanePassiveCandidate `
      -Events $passiveOneHeartbeatEvents `
      -ParserIntegrity $readinessCleanIntegrity -Capture $passiveFullCapture `
      -Idle $true -GroundRawStartOffset 142 -GroundRawEndOffset 163
  Add-SelfCase 'passive_prefilter_one_hb_vehicle_query_zero' `
      (-not $passiveOneHeartbeat.candidate -and
       -not $passiveOneHeartbeat.sync_invalid -and
       $passiveOneHeartbeat.heartbeat.count -eq 1 -and
       $passiveOneHeartbeat.heartbeat.tail_edge_ms -gt 2500.0) `
      'one primary heartbeat with an over-limit tail remains a zero-query retry'
  [object[]]$passiveStaleEvents = [object[]]@(
    [pscustomobject]@{
      message_id=0;system_id=1;component_id=1;elapsed_ms=500.0
    },
    [pscustomobject]@{
      message_id=0;system_id=1;component_id=1;elapsed_ms=6500.0
    })
  $passiveStale = Test-DataPlanePassiveCandidate -Events $passiveStaleEvents `
      -ParserIntegrity $readinessCleanIntegrity -Capture $passiveFullCapture `
      -Idle $true -GroundRawStartOffset 163 -GroundRawEndOffset 205
  Add-SelfCase 'passive_prefilter_stale_edge_tail_vehicle_query_zero' `
      (-not $passiveStale.candidate -and
       -not $passiveStale.sync_invalid -and
       $passiveStale.heartbeat.count -eq 0) `
      'heartbeats outside the measured passive epoch cannot authorize queries'
  $passiveParserError = Test-DataPlanePassiveCandidate `
      -Events $readinessGoodHeartbeats `
      -ParserIntegrity $readinessParserErrorIntegrity `
      -Capture $passiveFullCapture -Idle $true `
      -GroundRawStartOffset 205 -GroundRawEndOffset 268
  Add-SelfCase 'passive_prefilter_parser_errors_vehicle_query_zero' `
      (-not $passiveParserError.candidate -and
       $passiveParserError.sync_invalid -and
       -not $passiveParserError.parser_integrity.valid) `
      'parser corruption authorizes zero Vehicle queries'
  $passiveCorruptionLatch = New-ReadinessSyncInvalidLatch -Role 'ground' `
      -Stage 'passive_prefilter' -Failure 'parser_integrity_invalid' `
      -Response $passiveParserError -MatcherSnapshot $null
  Add-SelfCase 'passive_prefilter_parser_corruption_sync_invalid' `
      ($passiveParserError.sync_invalid -and
       $passiveCorruptionLatch.latched -and
       $passiveCorruptionLatch.role -eq 'ground') `
      'parser corruption is latched as Ground sync-invalid rather than retried'
  $passiveIdleBoundary = [pscustomobject][ordered]@{
    idle=$true;deadline_reached=$false;iterations=3
    ground_raw_offset=268;vehicle_raw_offset=901
  }
  Add-SelfCase 'passive_prefilter_pump_idle_boundary' `
      ($passiveIdleBoundary.idle -and
       -not $passiveIdleBoundary.deadline_reached -and
       $passiveIdleBoundary.ground_raw_offset -eq 268) `
      'pump-to-idle completes before the parser epoch start/raw boundary is taken'
  $passiveIdleTimeout = [pscustomobject][ordered]@{
    idle=$false;deadline_reached=$true;vehicle_query_count=0
  }
  Add-SelfCase 'passive_prefilter_idle_timeout_vehicle_query_zero' `
      (-not $passiveIdleTimeout.idle -and
       $passiveIdleTimeout.deadline_reached -and
       $passiveIdleTimeout.vehicle_query_count -eq 0) `
      'failure to establish an idle boundary times out before any Vehicle query'
  $passiveCandidateGood = Test-DataPlanePassiveCandidate `
      -Events $readinessGoodHeartbeats `
      -ParserIntegrity $readinessCleanIntegrity -Capture $passiveFullCapture `
      -Idle $true -GroundRawStartOffset 268 -GroundRawEndOffset 331
  Add-SelfCase 'passive_prefilter_candidate_measured_boundaries' `
      ($passiveCandidateGood.candidate -and
       $passiveCandidateGood.idle -and
       $passiveCandidateGood.capture_completed -and
       $passiveCandidateGood.window_duration_ms -eq 5000.0 -and
       $passiveCandidateGood.ground_raw_start_offset -eq 268 -and
       $passiveCandidateGood.ground_raw_end_offset -eq 331) `
      'candidate evidence contains a full measured five-second/raw-offset epoch'
  [object[]]$passiveDelayedRows = [object[]]@(
      $passiveNoHeartbeat,$passiveWrongSource,$passiveCandidateGood)
  [int]$passiveAuthorizedQueryPairs = @($passiveDelayedRows | Where-Object {
      $_.candidate}).Count
  Add-SelfCase 'passive_prefilter_delayed_candidate_one_A_B' `
      ($passiveAuthorizedQueryPairs -eq 1 -and
       @($passiveDelayedRows | Where-Object {$_.sync_invalid}).Count -eq 0) `
      'two HB-deficient passive epochs perform no query and one candidate authorizes one A/B pair'
  $passiveDeadlineCanStart = Get-ReadinessPassiveWindowDecision `
      -GateStartedElapsedMs 1000.0 -CurrentElapsedMs 688000.0 `
      -TimeoutSeconds 720 -SnapshotTimeoutSeconds 20
  $passiveDeadlineStops = Get-ReadinessPassiveWindowDecision `
      -GateStartedElapsedMs 1000.0 -CurrentElapsedMs 688001.0 `
      -TimeoutSeconds 720 -SnapshotTimeoutSeconds 20
  Add-SelfCase 'passive_prefilter_hard_720_deadline' `
      ($passiveDeadlineCanStart.deadline_elapsed_ms -eq 721000.0 -and
       $passiveDeadlineCanStart.can_start_full_pipeline -and
       -not $passiveDeadlineStops.can_start_full_pipeline -and
       $passiveDeadlineStops.timed_out) `
      'a shortened passive/A/fresh/B pipeline cannot start at the hard 720-second boundary'

  $readinessEpochDestination = New-Object `
      'System.Collections.Generic.List[object]'
  $readinessEpochRows = New-Object 'System.Collections.Generic.List[object]'
  [string[]]$readinessEpochNames = @('boot_boundary',
      'HB_noncandidate','passive_parser_reject','A_pre_dirty','A_timeout',
      'B_pre_dirty','B_timeout','assessment_invalid','finally')
  [long]$readinessEpochRawOffset = 1000
  foreach ($readinessEpochName in $readinessEpochNames) {
    $readinessEpochPathDestination = New-Object `
        'System.Collections.Generic.List[object]'
    $readinessEpochParser = New-MavlinkParserState -Definitions @{}
    $readinessEpoch = New-ReadinessParserEpoch `
        -Parser $readinessEpochParser -Name $readinessEpochName `
        -StartElapsedMs ([double]$readinessEpochRawOffset) `
        -StartRawOffset $readinessEpochRawOffset
    $readinessEpochParser.ParamList.events.Add([pscustomobject][ordered]@{
      classification='indexed';param_index=0;path=$readinessEpochName
      raw_start_offset=$readinessEpochRawOffset
      raw_end_offset_exclusive=($readinessEpochRawOffset + 25)
    })
    $readinessEpochFirst = Complete-ReadinessParserEpoch `
        -Epoch $readinessEpoch -Parser $readinessEpochParser `
        -Destination $readinessEpochPathDestination `
        -EndElapsedMs ([double]($readinessEpochRawOffset + 50)) `
        -EndRawOffset ($readinessEpochRawOffset + 25)
    [int]$readinessDestinationAfterFirst = `
        $readinessEpochPathDestination.Count
    $readinessEpochRepeat = Complete-ReadinessParserEpoch `
        -Epoch $readinessEpoch -Parser $readinessEpochParser `
        -Destination $readinessEpochPathDestination `
        -EndElapsedMs ([double]($readinessEpochRawOffset + 60)) `
        -EndRawOffset ($readinessEpochRawOffset + 30)
    foreach ($readinessEpochEvent in `
        $readinessEpochPathDestination.ToArray()) {
      $readinessEpochDestination.Add($readinessEpochEvent)
    }
    $readinessEpochRows.Add([pscustomobject][ordered]@{
      path=$readinessEpochName
      raw_start_offset=[long]$readinessEpochFirst.raw_start_offset
      raw_end_offset=[long]$readinessEpochFirst.raw_end_offset
      source_event_count=[int]$readinessEpochFirst.source_event_count
      destination_count_after_first=$readinessDestinationAfterFirst
      destination_count_after_repeat=$readinessEpochPathDestination.Count
      idempotent=[object]::ReferenceEquals($readinessEpochFirst,
          $readinessEpochRepeat)
    })
    $readinessEpochRawOffset += 100
  }
  [bool]$readinessEpochExactlyOnce = $true
  for ([int]$readinessEpochIndex = 0;
      $readinessEpochIndex -lt $readinessEpochRows.Count;
      ++$readinessEpochIndex) {
    [int]$expectedDestinationCount = 1
    $readinessEpochRow = $readinessEpochRows[$readinessEpochIndex]
    if ($readinessEpochRow.destination_count_after_first -ne
        $expectedDestinationCount -or
        $readinessEpochRow.destination_count_after_repeat -ne
        $expectedDestinationCount -or
        -not $readinessEpochRow.idempotent) {
      $readinessEpochExactlyOnce = $false
    }
  }
  Add-SelfCase 'passive_prefilter_param22_retained' `
      ($readinessEpochDestination.Count -eq 9 -and
       @($readinessEpochDestination | Group-Object path | Where-Object {
         $_.Count -ne 1}).Count -eq 0) `
      'pre-request #22 events are retained across passive and bracket parser resets'
  Add-SelfCase 'readiness_param22_harvest_exact_all_exit_paths' `
      ($readinessEpochExactlyOnce -and
       @($readinessEpochRows | Where-Object {
         $_.source_event_count -ne 1}).Count -eq 0) `
      'shared epoch close harvests one #22 exactly once on every normal/reject/finally path'
  [long[]]$readinessEpochStarts = @($readinessEpochRows | ForEach-Object {
      [long]$_.raw_start_offset})
  [bool]$readinessEpochOffsetsOrdered = $true
  for ([int]$readinessOffsetIndex = 1;
      $readinessOffsetIndex -lt $readinessEpochStarts.Count;
      ++$readinessOffsetIndex) {
    if ($readinessEpochStarts[$readinessOffsetIndex] -le
        $readinessEpochStarts[$readinessOffsetIndex - 1]) {
      $readinessEpochOffsetsOrdered = $false
    }
  }
  Add-SelfCase 'readiness_epoch_raw_offsets_unique_ordered' `
      ($readinessEpochOffsetsOrdered -and
       @($readinessEpochStarts | Sort-Object -Unique).Count -eq 9) `
      'parser epochs have unique strictly ordered raw start offsets'
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
      'readiness_epoch_harvest_model.json') -Value ([ordered]@{
        schema_version=1;destination_event_count=$readinessEpochDestination.Count
        missing_count=if($readinessEpochDestination.Count -eq 9){0}else{
          [Math]::Max(0,9 - $readinessEpochDestination.Count)
        }
        duplicate_count=@($readinessEpochDestination | Group-Object path |
          Where-Object {$_.Count -ne 1}).Count
        offsets_ordered=$readinessEpochOffsetsOrdered
        paths=$readinessEpochRows.ToArray()
      })

  $epochIntegrityRows = New-Object 'System.Collections.Generic.List[object]'
  foreach ($epochIntegritySpec in @(
      [pscustomobject]@{name='boot_boundary';stage='boot_boundary/pump_to_idle';
        case_name='readiness_boot_boundary_corruption_sync_invalid'},
      [pscustomobject]@{name='A_budget_no_query';stage='A_window_B';
        case_name='readiness_A_budget_close_corruption_sync_invalid'},
      [pscustomobject]@{name='window_incomplete';stage='A_window_B';
        case_name='readiness_window_incomplete_close_corruption_sync_invalid'},
      [pscustomobject]@{name='B_budget_no_query';stage='A_window_B';
        case_name='readiness_B_budget_close_corruption_sync_invalid'},
      [pscustomobject]@{name='finally';stage='A_window_B';
        case_name='readiness_finally_close_corruption_sync_invalid'})) {
    $epochIntegrityParser = New-MavlinkParserState -Definitions @{}
    $epochIntegrityDestination = New-Object `
        'System.Collections.Generic.List[object]'
    $epochIntegrityEpoch = New-ReadinessParserEpoch `
        -Parser $epochIntegrityParser -Name $epochIntegritySpec.name `
        -StartElapsedMs 1000 -StartRawOffset 4000
    $epochIntegrityParser.BadCrc = [uint64]1
    $epochIntegrityResult = Complete-ReadinessParserEpochChecked `
        -Epoch $epochIntegrityEpoch -Parser $epochIntegrityParser `
        -Destination $epochIntegrityDestination -EndElapsedMs 2000 `
        -EndRawOffset 4021 -Stage $epochIntegritySpec.stage `
        -MatcherSnapshot $null
    $epochIntegrityPostPlan = Get-PostDiagnosticPlan `
        -DataPlaneReadiness ([pscustomobject][ordered]@{
          sync_invalid=[bool]$epochIntegrityResult.sync_invalid}) `
        -BacklogDrainGate ([pscustomobject][ordered]@{sync_invalid=$false})
    $epochIntegrityRow = [pscustomobject][ordered]@{
      name=[string]$epochIntegritySpec.name
      epoch_integrity_valid=[bool]$epochIntegrityResult.integrity.valid
      sync_invalid=[bool]$epochIntegrityResult.sync_invalid
      ground_latch=$epochIntegrityResult.ground_sync_invalid
      vehicle_query_count=[int]$epochIntegrityResult.vehicle_query_count
      request_write_count=[int]$epochIntegrityResult.request_write_count
      post_plan=$epochIntegrityPostPlan
    }
    $epochIntegrityRows.Add($epochIntegrityRow)
    Add-SelfCase ([string]$epochIntegritySpec.case_name) `
        (-not $epochIntegrityRow.epoch_integrity_valid -and
         $epochIntegrityRow.sync_invalid -and
         $epochIntegrityRow.ground_latch.latched -and
         $epochIntegrityRow.ground_latch.role -ceq 'ground' -and
         $epochIntegrityRow.ground_latch.stage -ceq
           [string]$epochIntegritySpec.stage -and
         $epochIntegrityRow.vehicle_query_count -eq 0 -and
         $epochIntegrityRow.request_write_count -eq 0) `
        'every readiness epoch close converts parser corruption into an exact Ground sync-invalid latch'
  }
  Add-SelfCase 'readiness_epoch_corruption_both_post_suppressed' `
      (@($epochIntegrityRows | Where-Object {
        $_.post_plan.run_ground -or $_.post_plan.run_vehicle -or
        -not $_.post_plan.any_sync_invalid}).Count -eq 0) `
      'any epoch-close parser corruption suppresses both post diagnostic queries and the request'
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
      'readiness_epoch_close_integrity_model.json') -Value ([ordered]@{
        schema_version=1;cases=$epochIntegrityRows.ToArray()
      })

  $matcherCandidate = New-Object 'System.Collections.Generic.List[byte]'
  $matcherState = [pscustomobject][ordered]@{
    Role='vehicle';MatcherCandidate=$matcherCandidate
    MatcherStartOffset=[long]-1;MatcherOverflows=[uint64]0
    TaggedLines=New-Object 'System.Collections.Generic.List[object]'
    RawBytes=[long]500
  }
  $matcherClean = Test-CaptureMatcherClean -State $matcherState `
      -ExpectedOverflowCount ([uint64]0)
  $matcherState.MatcherCandidate.Add([byte]0x56)
  $matcherState.MatcherCandidate.Add([byte]0x43)
  $matcherState.MatcherStartOffset = [long]498
  $matcherPartial = Test-CaptureMatcherClean -State $matcherState `
      -ExpectedOverflowCount ([uint64]0)
  $matcherPartialLatch = New-ReadinessSyncInvalidLatch -Role 'vehicle' `
      -Stage 'A' -Failure 'preexisting_partial_matcher' -Response $null `
      -MatcherSnapshot $matcherPartial.snapshot
  Add-SelfCase 'readiness_A_preexisting_partial_query_zero' `
      ($matcherClean.valid -and -not $matcherPartial.valid -and
       $matcherPartialLatch.latched -and
       $matcherPartialLatch.matcher_at_latch.pending_byte_count -eq 2) `
      'A is suppressed before write when the Vehicle matcher is not clean'
  $matcherPartialBLatch = New-ReadinessSyncInvalidLatch -Role 'vehicle' `
      -Stage 'B' -Failure 'preexisting_partial_matcher' -Response $null `
      -MatcherSnapshot $matcherPartial.snapshot
  Add-SelfCase 'readiness_B_preexisting_partial_query_zero' `
      (-not $matcherPartial.valid -and $matcherPartialBLatch.latched -and
       $matcherPartialBLatch.stage -eq 'B') `
      'B is suppressed before write when a partial Vehicle report starts during the fresh bracket'
  Add-SelfCase 'readiness_matcher_pending_bytes_exact_latch' `
      ($matcherPartialLatch.matcher_at_latch.pending_byte_count -eq 2 -and
       $matcherPartialLatch.matcher_at_latch.pending_bytes_hex -ceq '5643' -and
       $matcherPartialLatch.matcher_at_latch.pending_start_offset -eq 498 -and
       $matcherPartialLatch.matcher_at_latch.overflow_count -eq 0) `
      'sync-invalid latch freezes exact pending matcher bytes/start/overflow evidence'

  [object[]]$readinessTransitionSpecs = [object[]]@(
    [pscustomobject]@{name='readiness_A_timeout_sync_invalid_state';stage='A';
      expected=[uint32]7;snapshot=[pscustomobject][ordered]@{
        status='TIMEOUT';query_count=1;query_attempt_count=1
        write_timed_out=$false;q_uint32=$null;responses=[object[]]@()}},
    [pscustomobject]@{name='readiness_A_write_timeout_sync_invalid_state';stage='A';
      expected=[uint32]7;snapshot=[pscustomobject][ordered]@{
        status='TIMEOUT';query_count=0;query_attempt_count=1
        write_timed_out=$true;q_uint32=$null;responses=[object[]]@()}},
    [pscustomobject]@{name='readiness_A_wrong_q_sync_invalid_state';stage='A';
      expected=[uint32]7;snapshot=(New-OfflineSnapshot `
        -Fields $readinessVehicleAFields -Q 6 -Ms ([uint64]4294967300))},
    [pscustomobject]@{name='readiness_B_timeout_sync_invalid_state';stage='B';
      expected=[uint32]8;snapshot=[pscustomobject][ordered]@{
        status='TIMEOUT';query_count=1;query_attempt_count=1
        write_timed_out=$false;q_uint32=$null;responses=[object[]]@()}},
    [pscustomobject]@{name='readiness_B_write_timeout_sync_invalid_state';stage='B';
      expected=[uint32]8;snapshot=[pscustomobject][ordered]@{
        status='TIMEOUT';query_count=0;query_attempt_count=1
        write_timed_out=$true;q_uint32=$null;responses=[object[]]@()}},
    [pscustomobject]@{name='readiness_B_wrong_q_sync_invalid_state';stage='B';
      expected=[uint32]8;snapshot=(New-OfflineSnapshot `
        -Fields $readinessVehicleBFields -Q 7 -Ms ([uint64]4294973300))})
  foreach ($transitionSpec in $readinessTransitionSpecs) {
    $transition = Get-ReadinessSnapshotTransition `
        -Stage $transitionSpec.stage -Snapshot $transitionSpec.snapshot `
        -ExpectedQ ([uint32]$transitionSpec.expected) `
        -CurrentCompleteB $readinessVehicleA `
        -PreQueryMatcherSnapshot $matcherClean.snapshot `
        -MatcherSnapshot $matcherPartial.snapshot
    Add-SelfCase ([string]$transitionSpec.name) `
        (-not $transition.valid -and
         $transition.sync_invalid_latch.latched -and
         $transition.sync_invalid_latch.role -eq 'vehicle' -and
         $transition.subsequent_diagnostic_query_count -eq 0 -and
         $transition.request_write_count -eq 0 -and
         [object]::ReferenceEquals($transition.next_complete_B,
           $readinessVehicleA)) `
        'A/B timeout, write timeout, and wrong-q share one fail-closed Vehicle sync-invalid transition'
  }

  $postQueryMatcherRows = New-Object 'System.Collections.Generic.List[object]'
  foreach ($postQuerySpec in @(
      [pscustomobject]@{name='A_partial_timeout';stage='A';
        text='VCSTAT1 q=13';start=[long]500;raw=[long]512;
        overflow=[uint64]0;complete=$false;expected=[uint32]13},
      [pscustomobject]@{name='B_partial_timeout';stage='B';
        text='VCSTAT2 q=14';start=[long]800;raw=[long]812;
        overflow=[uint64]0;complete=$false;expected=[uint32]14},
      [pscustomobject]@{name='A_overflow_timeout';stage='A';text='';
        start=[long]-1;raw=[long]1000;overflow=[uint64]1;
        complete=$false;expected=[uint32]15},
      [pscustomobject]@{name='B_overflow_timeout';stage='B';text='';
        start=[long]-1;raw=[long]1050;overflow=[uint64]1;
        complete=$false;expected=[uint32]16},
      [pscustomobject]@{name='A_complete_trailing_partial';stage='A';
        text='A';start=[long]1100;raw=[long]1101;overflow=[uint64]0;
        complete=$true;expected=[uint32]17},
      [pscustomobject]@{name='B_complete_trailing_partial';stage='B';
        text='B';start=[long]1200;raw=[long]1201;overflow=[uint64]0;
        complete=$true;expected=[uint32]18})) {
    $postQueryCandidate = New-Object 'System.Collections.Generic.List[byte]'
    $postQueryState = [pscustomobject][ordered]@{
      Role='vehicle';MatcherCandidate=$postQueryCandidate
      MatcherStartOffset=[long]-1;MatcherOverflows=[uint64]0
      TaggedLines=New-Object 'System.Collections.Generic.List[object]'
      RawBytes=if($postQuerySpec.start -ge 0){
        [long]$postQuerySpec.start
      }else{[long]$postQuerySpec.raw}
    }
    $postQueryPre = Get-CaptureMatcherSnapshot -State $postQueryState
    [byte[]]$postQueryBytes = [Text.Encoding]::ASCII.GetBytes(
        [string]$postQuerySpec.text)
    foreach ($postQueryByte in $postQueryBytes) {
      $postQueryState.MatcherCandidate.Add([byte]$postQueryByte)
    }
    $postQueryState.MatcherStartOffset = [long]$postQuerySpec.start
    $postQueryState.MatcherOverflows = [uint64]$postQuerySpec.overflow
    $postQueryState.RawBytes = [long]$postQuerySpec.raw
    $postQueryPost = Get-CaptureMatcherSnapshot -State $postQueryState
    if ($postQuerySpec.complete) {
      $postQueryFields = if ($postQuerySpec.stage -ceq 'A') {
        $readinessVehicleAFields
      } else { $readinessVehicleBFields }
      $postQuerySnapshot = New-OfflineSnapshot -Fields $postQueryFields `
          -Q ([uint32]$postQuerySpec.expected) `
          -Ms ([uint64](4294980000 + $postQuerySpec.expected))
    } else {
      $postQuerySnapshot = [pscustomobject][ordered]@{
        status='TIMEOUT';query_count=1;query_attempt_count=1
        write_timed_out=$false;q_uint32=$null;responses=[object[]]@()
      }
    }
    $postQueryTransition = Get-ReadinessSnapshotTransition `
        -Stage $postQuerySpec.stage -Snapshot $postQuerySnapshot `
        -ExpectedQ ([uint32]$postQuerySpec.expected) `
        -CurrentCompleteB $readinessVehicleA `
        -PreQueryMatcherSnapshot $postQueryPre `
        -MatcherSnapshot $postQueryPost
    $postQuerySuppressed = New-SyncInvalidSuppressedSnapshot `
        -Name ('post_vehicle_' + $postQuerySpec.name) -Role 'vehicle' `
        -State $postQueryState `
        -MatcherAtLatch $postQueryTransition.sync_invalid_latch.matcher_at_latch `
        -SuppressionSource 'readiness'
    $postQueryContinuation = New-SyncInvalidContinuationEvidence `
        -MatcherAtLatch $postQueryTransition.sync_invalid_latch.matcher_at_latch `
        -BeforeFooterPump $postQueryPost -AfterFooterPump $postQueryPost `
        -DiagnosticWriteCountBefore ([uint64]0) `
        -DiagnosticWriteCountAfter ([uint64]0)
    $postQueryRow = [pscustomobject][ordered]@{
      name=[string]$postQuerySpec.name;stage=[string]$postQuerySpec.stage
      failure=[string]$postQueryTransition.sync_invalid_latch.failure
      pre_query=$postQueryPre;post_query=$postQueryPost
      transition_matcher=$postQueryTransition.matcher_after_query
      latch_matcher=$postQueryTransition.sync_invalid_latch.matcher_at_latch
      suppressed_matcher=$postQuerySuppressed.matcher_at_latch
      continuation_matcher=$postQueryContinuation.matcher_at_latch
      transition_valid=[bool]$postQueryTransition.valid
      suppressed_query_count=[int]$postQuerySuppressed.query_count
      continuation_valid=[bool]$postQueryContinuation.valid
      continuation_write_delta=[uint64]$postQueryContinuation.diagnostic_write_count_delta
    }
    $postQueryMatcherRows.Add($postQueryRow)
  }
  $aPartialRow = @($postQueryMatcherRows | Where-Object {
      $_.name -ceq 'A_partial_timeout'})[0]
  $bPartialRow = @($postQueryMatcherRows | Where-Object {
      $_.name -ceq 'B_partial_timeout'})[0]
  $aOverflowRow = @($postQueryMatcherRows | Where-Object {
      $_.name -ceq 'A_overflow_timeout'})[0]
  $bOverflowRow = @($postQueryMatcherRows | Where-Object {
      $_.name -ceq 'B_overflow_timeout'})[0]
  $aCompleteDirtyRow = @($postQueryMatcherRows | Where-Object {
      $_.name -ceq 'A_complete_trailing_partial'})[0]
  $bCompleteDirtyRow = @($postQueryMatcherRows | Where-Object {
      $_.name -ceq 'B_complete_trailing_partial'})[0]
  Add-SelfCase 'readiness_A_post_query_partial_timeout_latch_exact' `
      (-not $aPartialRow.transition_valid -and
       $aPartialRow.latch_matcher.pending_bytes_hex -ceq
         '5643535441543120713D3133' -and
       $aPartialRow.latch_matcher.pending_start_offset -eq 500) `
      'A timeout freezes the immediate post-query partial matcher bytes and raw start'
  Add-SelfCase 'readiness_B_post_query_partial_timeout_latch_exact' `
      (-not $bPartialRow.transition_valid -and
       $bPartialRow.latch_matcher.pending_bytes_hex -ceq
         '5643535441543220713D3134' -and
       $bPartialRow.latch_matcher.pending_start_offset -eq 800) `
      'B timeout freezes the immediate post-query partial matcher bytes and raw start'
  Add-SelfCase 'readiness_post_query_partial_survives_suppression_footer' `
      (@($aPartialRow,$bPartialRow | Where-Object {
        $_.suppressed_matcher.pending_bytes_hex -cne
          $_.latch_matcher.pending_bytes_hex -or
        $_.continuation_matcher.pending_bytes_hex -cne
          $_.latch_matcher.pending_bytes_hex -or
        -not $_.continuation_valid}).Count -eq 0) `
      'A/B post-query partial bytes remain exact through suppression and footer continuation evidence'
  Add-SelfCase 'readiness_A_post_query_overflow_latch_exact' `
      (-not $aOverflowRow.transition_valid -and
       $aOverflowRow.latch_matcher.overflow_count -eq 1) `
      'A timeout attributes an immediate post-query matcher overflow delta'
  Add-SelfCase 'readiness_B_post_query_overflow_latch_exact' `
      (-not $bOverflowRow.transition_valid -and
       $bOverflowRow.latch_matcher.overflow_count -eq 1) `
      'B timeout attributes an immediate post-query matcher overflow delta'
  Add-SelfCase 'readiness_post_query_overflow_survives_suppression_footer' `
      (@($aOverflowRow,$bOverflowRow | Where-Object {
        $_.suppressed_matcher.overflow_count -ne 1 -or
        $_.continuation_matcher.overflow_count -ne 1 -or
        -not $_.continuation_valid}).Count -eq 0) `
      'A/B post-query overflow evidence survives suppression and footer continuation'
  Add-SelfCase 'readiness_A_complete_with_trailing_partial_rejected' `
      (-not $aCompleteDirtyRow.transition_valid -and
       $aCompleteDirtyRow.failure -ceq 'post_query_matcher_dirty') `
      'a COMPLETE A report plus trailing partial matcher state is sync-invalid immediately'
  Add-SelfCase 'readiness_B_complete_with_trailing_partial_rejected' `
      (-not $bCompleteDirtyRow.transition_valid -and
       $bCompleteDirtyRow.failure -ceq 'post_query_matcher_dirty') `
      'a COMPLETE B report plus trailing partial matcher state cannot advance the cursor or assessment'
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
      'readiness_post_query_matcher_model.json') -Value ([ordered]@{
        schema_version=1;cases=$postQueryMatcherRows.ToArray()
      })

  $completeBTransition = Get-ReadinessSnapshotTransition -Stage 'B' `
      -Snapshot $readinessVehicleB -ExpectedQ ([uint32]8) `
      -CurrentCompleteB $readinessVehicleA `
      -PreQueryMatcherSnapshot $matcherClean.snapshot `
      -MatcherSnapshot $matcherClean.snapshot
  $invalidWindowLastSnapshot = Select-ReadinessLastVehicleSnapshot `
      -CurrentSnapshot $readinessVehicleA -VehicleAfter $readinessVehicleB `
      -VehicleAResponse $readinessAResponse `
      -VehicleBResponse $completeBTransition.response `
      -WindowAssessment $readinessNoHeartbeat -WithinDeadline $true
  [Nullable[uint32]]$nextAFromCompleteB = Get-ReadinessExpectedA `
      -LastCompleteVehicleB $completeBTransition.next_complete_B
  Add-SelfCase 'readiness_invalid_assessment_returns_to_passive' `
      ($completeBTransition.valid -and -not $readinessNoHeartbeat.valid -and
       [object]::ReferenceEquals($invalidWindowLastSnapshot,
         $readinessVehicleA)) `
      'an exact A/B pair with an invalid HB/D7 assessment returns to passive observation'
  Add-SelfCase 'readiness_invalid_assessment_next_A_from_complete_B' `
      ($null -ne $nextAFromCompleteB -and
       [uint32]$nextAFromCompleteB -eq [uint32]9) `
      'after an invalid assessment the next A is still exact q+1 from the last complete B'
  Add-SelfCase 'readiness_complete_B_cursor_advances_on_invalid_assessment' `
      ([object]::ReferenceEquals($completeBTransition.next_complete_B,
        $readinessVehicleB) -and
       [object]::ReferenceEquals($invalidWindowLastSnapshot,
        $readinessVehicleA)) `
      'complete-B correlation seed advances independently of the valid-bracket downstream seed'

  $cursorRows = New-Object 'System.Collections.Generic.List[object]'
  foreach ($cursorSpec in @(
      @([uint32]9,[uint64]100,'VCSTAT1',0),
      @([uint32]9,[uint64]100,'VCSTAT2',1),
      @([uint32]9,[uint64]100,'VCSTAT3',2),
      @([uint32]8,[uint64]200,'VCSTAT1',3),
      @([uint32]8,[uint64]200,'VCSTAT2',4),
      @([uint32]8,[uint64]200,'VCSTAT3',5),
      @([uint32]9,[uint64]300,'VCSTAT1',6),
      @([uint32]9,[uint64]300,'VCSTAT2',7),
      @([uint32]9,[uint64]300,'VCSTAT3',8))) {
    $cursorRows.Add([pscustomobject][ordered]@{
      valid_correlation=$true;q_uint32=[uint32]$cursorSpec[0]
      ms_uint64=[uint64]$cursorSpec[1];tag=[string]$cursorSpec[2]
      sequence=[int]$cursorSpec[3];line=[string]$cursorSpec[2]
      raw_start_offset=if([int]$cursorSpec[3] -lt 3){
        [long](100 + [int]$cursorSpec[3])
      }elseif([int]$cursorSpec[3] -lt 6){
        [long](300 + [int]$cursorSpec[3])
      }else{[long](600 + [int]$cursorSpec[3])}
    })
  }
  $cursorSelected = Select-CorrelatedReportFromRows -Rows $cursorRows `
      -TagBase 'VCSTAT' -StartLineIndex 3 `
      -MinimumRawStartOffset 500 -ExpectedQ ([uint32]9)
  Add-SelfCase 'readiness_B_cursor_excludes_prequery_expected_group' `
      ($cursorSelected.complete -and $cursorSelected.q_uint32 -eq 9 -and
       $cursorSelected.ms_uint64 -eq 300 -and
       @($cursorSelected.responses | Where-Object {
         $_.sequence -lt 3}).Count -eq 0) `
      'a complete expected-q group before the write cursor cannot satisfy B'
  Add-SelfCase 'readiness_B_cursor_ignores_delayed_A_selects_fresh_B' `
      ($cursorSelected.complete -and
       @($cursorSelected.responses | Where-Object {
         $_.q_uint32 -ne 9 -or $_.sequence -lt 6}).Count -eq 0) `
      'delayed A lines after the cursor are ignored and the fresh expected B group is selected'

  $rawBoundaryRows = New-Object 'System.Collections.Generic.List[object]'
  foreach ($rawBoundarySpec in @(
      @([uint64]400,'VCSTAT1',[long]490),
      @([uint64]400,'VCSTAT2',[long]491),
      @([uint64]400,'VCSTAT3',[long]492),
      @([uint64]500,'VCSTAT1',[long]500),
      @([uint64]500,'VCSTAT2',[long]501),
      @([uint64]500,'VCSTAT3',[long]502))) {
    $rawBoundaryRows.Add([pscustomobject][ordered]@{
      valid_correlation=$true;q_uint32=[uint32]11
      ms_uint64=[uint64]$rawBoundarySpec[0]
      tag=[string]$rawBoundarySpec[1];line=[string]$rawBoundarySpec[1]
      raw_start_offset=[long]$rawBoundarySpec[2]
    })
  }
  $rawBoundarySelected = Select-CorrelatedReportFromRows `
      -Rows $rawBoundaryRows -TagBase 'VCSTAT' -StartLineIndex 0 `
      -MinimumRawStartOffset 500 -ExpectedQ ([uint32]11)
  Add-SelfCase 'snapshot_cursor_rejects_prequery_raw_start' `
      ($rawBoundarySelected.complete -and
       [uint64]$rawBoundarySelected.ms_uint64 -eq [uint64]500 -and
       @($rawBoundarySelected.responses | Where-Object {
         [long]$_.raw_start_offset -lt 500}).Count -eq 0) `
      'a row appended after the line cursor cannot correlate when its raw start predates the query boundary'
  Add-SelfCase 'snapshot_cursor_accepts_boundary_raw_start' `
      ($rawBoundarySelected.complete -and
       @($rawBoundarySelected.responses | Where-Object {
         [long]$_.raw_start_offset -ge 500}).Count -eq 3) `
      'a complete expected-q group whose raw starts are at or after the query boundary is accepted'

  $continuousParser = New-MavlinkParserState -Definitions @{}
  $continuousDestination = New-Object 'System.Collections.Generic.List[object]'
  $continuousEpoch = New-ReadinessParserEpoch -Parser $continuousParser `
      -Name 'A_window_B_continuous' -StartElapsedMs 1000 `
      -StartRawOffset 2000
  [bool]$parserEnabledAtA = $continuousParser.Enabled
  [bool]$parserEnabledDuringWindow = $continuousParser.Enabled
  [bool]$parserEnabledAtB = $continuousParser.Enabled
  $continuousResult = Complete-ReadinessParserEpoch -Epoch $continuousEpoch `
      -Parser $continuousParser -Destination $continuousDestination `
      -EndElapsedMs 7000 -EndRawOffset 2063
  Add-SelfCase 'readiness_A_B_parser_epoch_continuous' `
      ($parserEnabledAtA -and $parserEnabledDuringWindow -and
       $parserEnabledAtB -and $continuousEpoch.closed -and
       $continuousResult.integrity.valid) `
      'one Ground parser epoch remains enabled and unreset across A, fresh five seconds, and B'
  $corruptParser = New-MavlinkParserState -Definitions @{}
  $corruptDestination = New-Object 'System.Collections.Generic.List[object]'
  $corruptEpoch = New-ReadinessParserEpoch -Parser $corruptParser `
      -Name 'bracket_parser_corrupt' -StartElapsedMs 8000 `
      -StartRawOffset 2100
  $corruptParser.BadCrc = [uint64]1
  $corruptResult = Complete-ReadinessParserEpoch -Epoch $corruptEpoch `
      -Parser $corruptParser -Destination $corruptDestination `
      -EndElapsedMs 13000 -EndRawOffset 2121
  $corruptLatch = New-ReadinessSyncInvalidLatch -Role 'ground' `
      -Stage 'A_window_B' -Failure 'parser_integrity_invalid' `
      -Response $corruptResult -MatcherSnapshot $null
  Add-SelfCase 'readiness_bracket_parser_corruption_sync_invalid' `
      (-not $corruptResult.integrity.valid -and $corruptLatch.latched -and
       $corruptLatch.role -eq 'ground') `
      'CRC/noise/partial corruption anywhere in A-window-B is Ground sync-invalid'

  $readinessSyncInvalidModel = [pscustomobject][ordered]@{
    valid=$false;timed_out=$false;sync_invalid=$true
    ground_sync_invalid=$corruptLatch;vehicle_sync_invalid=$matcherPartialLatch
  }
  $backlogCleanModel = [pscustomobject][ordered]@{sync_invalid=$false}
  $backlogSyncInvalidModel = [pscustomobject][ordered]@{sync_invalid=$true}
  $baselineCleanModel = [pscustomobject][ordered]@{sync_invalid=$false}
  $baselineSyncInvalidModel = [pscustomobject][ordered]@{sync_invalid=$true}
  $readinessPostPlan = Get-PostDiagnosticPlan `
      -DataPlaneReadiness $readinessSyncInvalidModel `
      -BacklogDrainGate $backlogCleanModel `
      -BaselinePairGate $baselineCleanModel
  $backlogPostPlan = Get-PostDiagnosticPlan `
      -DataPlaneReadiness ([pscustomobject][ordered]@{sync_invalid=$false}) `
      -BacklogDrainGate $backlogSyncInvalidModel `
      -BaselinePairGate $baselineCleanModel
  $bothPostPlan = Get-PostDiagnosticPlan `
      -DataPlaneReadiness $readinessSyncInvalidModel `
      -BacklogDrainGate $backlogSyncInvalidModel `
      -BaselinePairGate $baselineSyncInvalidModel
  $baselinePostPlan = Get-PostDiagnosticPlan `
