       -not $readinessPostPlan.run_vehicle) `
      'readiness sync-invalid suppresses the Vehicle post query'
  Add-SelfCase 'readiness_sync_invalid_both_post_suppressed' `
      ($readinessPostPlan.any_sync_invalid -and
       -not $readinessPostPlan.run_ground -and
       -not $readinessPostPlan.run_vehicle) `
      'readiness sync-invalid suppresses both role post queries'
  Add-SelfCase 'post_diagnostics_sync_invalid_matrix' `
      ($readinessPostPlan.sources.Count -eq 1 -and
       $backlogPostPlan.any_sync_invalid -and
       -not $backlogPostPlan.run_ground -and
       -not $backlogPostPlan.run_vehicle -and
       $bothPostPlan.sources.Count -eq 3 -and
       -not $bothPostPlan.run_ground -and -not $bothPostPlan.run_vehicle) `
      'readiness-only, backlog-only, and combined three-gate sync-invalid suppress both post queries'
  Add-SelfCase 'baseline_retry_sync_invalid_both_post_suppressed' `
      ($baselinePostPlan.baseline_sync_invalid -and
       $baselinePostPlan.sources.Count -eq 1 -and
       $baselinePostPlan.sources[0] -ceq 'baseline' -and
       -not $baselinePostPlan.run_ground -and
       -not $baselinePostPlan.run_vehicle) `
      'baseline retry synchronization loss suppresses both post diagnostic writes'
  $suppressedGround = New-SyncInvalidSuppressedSnapshot `
      -Name 'post_ground' -Role 'ground' -State $matcherState `
      -MatcherAtLatch $corruptLatch.matcher_at_latch `
      -SuppressionSource 'readiness'
  $suppressedVehicle = New-SyncInvalidSuppressedSnapshot `
      -Name 'post_vehicle' -Role 'vehicle' -State $matcherState `
      -MatcherAtLatch $matcherPartialLatch.matcher_at_latch `
      -SuppressionSource 'readiness'
  Add-SelfCase 'readiness_sync_invalid_matcher_state_preserved' `
      ($suppressedVehicle.matcher_at_latch.pending_bytes_hex -ceq '5643' -and
       $suppressedVehicle.matcher_at_latch.pending_start_offset -eq 498 -and
       $suppressedVehicle.matcher_at_suppression.pending_bytes_hex -ceq '5643') `
      'suppressed diagnostic evidence preserves the exact matcher state latched at failure'
  $beforeFooterMatcher = Get-CaptureMatcherSnapshot -State $matcherState
  $afterFooterMatcher = Get-CaptureMatcherSnapshot -State $matcherState
  $syncContinuation = New-SyncInvalidContinuationEvidence `
      -MatcherAtLatch $matcherPartialLatch.matcher_at_latch `
      -BeforeFooterPump $beforeFooterMatcher `
      -AfterFooterPump $afterFooterMatcher `
      -DiagnosticWriteCountBefore ([uint64]2) `
      -DiagnosticWriteCountAfter ([uint64]2)
  Add-SelfCase 'readiness_sync_invalid_footer_continuation_zero_writes' `
      ($syncContinuation.valid -and
       $syncContinuation.diagnostic_write_count_delta -eq 0 -and
       $syncContinuation.before_footer_pump.pending_bytes_hex -ceq '5643' -and
       $syncContinuation.after_footer_pump.pending_bytes_hex -ceq '5643') `
      'footer passive pump preserves before/after matcher evidence with zero diagnostic writes'
  [string]$suppressedTextPath = Join-Path $SelfTestEvidenceDirectory `
