  Write-SnapshotText -Path $suppressedTextPath -Snapshot $suppressedVehicle
  [string]$expectedSuppressedText = `
      "NOT_RUN_SYNC_INVALID query_count=0 query_attempt_count=0 reason=SYNC_INVALID`n"
  [string]$actualSuppressedText = [System.IO.File]::ReadAllText(
      $suppressedTextPath, (New-Object System.Text.UTF8Encoding($false)))
  Add-SelfCase 'sync_invalid_suppressed_snapshot_text_exact' `
      ($actualSuppressedText -ceq $expectedSuppressedText) `
      'suppressed .txt evidence is one deterministic ASCII status line plus LF'

  $emptyOfficialState = New-ParamListState
  $emptyPostState = New-ParamListState -CaptureScope 'post_cutoff'
  $emptyDiagnostic = New-ParamListDiagnosticEvidence `
      -BacklogDrainGate $null -BaselineSetup $null `
      -PreRequestPairGate ([pscustomobject]@{valid=$false;status='NOT_RUN'}) `
