      -PostAssessment $null
  $oneOfficialState = New-ParamListState
  $oneOfficialState.events.Add([pscustomobject]@{param_index=0})
  $oneDiagnostic = New-ParamListDiagnosticEvidence `
      -OfficialState $oneOfficialState -PostCutoffState $emptyPostState
  $multiOfficialState = New-ParamListState
  $multiOfficialState.events.Add([pscustomobject]@{param_index=0})
  $multiOfficialState.events.Add([pscustomobject]@{param_index=1})
  $multiDiagnostic = New-ParamListDiagnosticEvidence `
