       $oneDiagnostic.official.events -is [System.Array] -and
       $multiDiagnostic.official.events -is [System.Array] -and
       @($emptyDiagnostic.official.events).Count -eq 0 -and
       @($oneDiagnostic.official.events).Count -eq 1 -and
       @($multiDiagnostic.official.events).Count -eq 2) `
      'nested collection serialization preserves root-array cardinality for 0/1/N'
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
