  $prefilterModel = [ordered]@{
    schema_version=1
    passive_cases=[object[]]@($passiveNoHeartbeat,$passiveWrongSource,
      $passiveOneHeartbeat,$passiveStale,$passiveParserError,
      $passiveCandidateGood)
    post_plan=$readinessPostPlan
  }
  [string]$prefilterModelPath = Join-Path $SelfTestEvidenceDirectory `
      'readiness_passive_prefilter_model.json'
  Write-JsonDurable -Path $prefilterModelPath -Value $prefilterModel
  [string]$prefilterRaw = Get-Content -Raw -LiteralPath $prefilterModelPath
  $prefilterParsed = $prefilterRaw | ConvertFrom-Json
  [bool]$prefilterBooleanTypes = $true
  foreach ($prefilterCase in @($prefilterParsed.passive_cases)) {
    foreach ($booleanName in @('candidate','sync_invalid','idle',
        'capture_completed')) {
      $booleanProperty = $prefilterCase.PSObject.Properties[$booleanName]
      if ($null -eq $booleanProperty -or
          -not ($booleanProperty.Value -is [bool])) {
        $prefilterBooleanTypes = $false
      }
    }
  }
  foreach ($booleanName in @('any_sync_invalid','run_ground','run_vehicle')) {
    $booleanProperty = $prefilterParsed.post_plan.PSObject.Properties[
        $booleanName]
    if ($null -eq $booleanProperty -or
        -not ($booleanProperty.Value -is [bool])) {
      $prefilterBooleanTypes = $false
    }
  }
  Add-SelfCase 'readiness_evidence_boolean_types_and_raw_literals' `
      ($prefilterBooleanTypes -and
       -not [regex]::IsMatch($prefilterRaw,
         '"(?:candidate|sync_invalid|idle|capture_completed|any_sync_invalid|run_ground|run_vehicle)"\s*:\s*\{\}') -and
       [regex]::Matches($prefilterRaw,
         '"(?:candidate|sync_invalid|idle|capture_completed|any_sync_invalid|run_ground|run_vehicle)"\s*:\s*(?:true|false)').Count -gt 0) `
      'critical evidence booleans are typed and serialize only as raw true/false literals'
  [uint64]$modeledDiagnosticWriteCount = 0
  ++$modeledDiagnosticWriteCount
  ++$modeledDiagnosticWriteCount
  Add-SelfCase 'diagnostic_query_counter_successful_write_only' `
      ($modeledDiagnosticWriteCount -eq 2) `
      'the modeled counter advances only after the two successful A/B writes'
  $m0DeadParser = New-MavlinkParserState -Definitions @{}
