  $m0CleanupParser.Buffer.Add([byte]0xFD)
  $m0CleanupParser.ExpectedLength = 25
  $m0Cleanup = Disable-AndResetMavlinkAnalysis -Parser $m0CleanupParser
  Add-SelfCase 'm0_reject_disables_resets_parser' `
