  }
  $vehiclePostFields = $vehicleBaseFields.Clone()
  $vehiclePostFields['d722'] = [uint64]932
  $vehiclePostFields['snf'] = [uint64]1
  $vehiclePostFields['snq'] = [uint64]932
  $offlineBaselineGround = New-OfflineSnapshot -Fields $groundBaseFields `
      -Q 1 -Ms ([uint64]4294967296)
  $offlinePostGround = New-OfflineSnapshot -Fields $groundPostFields `
      -Q 2 -Ms ([uint64]4294968296)
  $offlineBaselineVehicle = New-OfflineSnapshot -Fields $vehicleBaseFields `
      -Q 1 -Ms ([uint64]4294967297) -TagBase 'VCSTAT'
  $offlinePostVehicle = New-OfflineSnapshot -Fields $vehiclePostFields `
      -Q 2 -Ms ([uint64]4294968297) -TagBase 'VCSTAT'

  # A recovery queues only the exact missing tail on the target lane.  These
  # fixtures deliberately keep aggregate cancel/filter totals variable; the
  # strict oracle accepts them only through their independent partitions.
  [uint64]$modeledRecoveryExpectedIndex = 520
  [uint64]$modeledRecoveryTargetCount =
      [uint64]$script:ExpectedParamCount - $modeledRecoveryExpectedIndex
  $recoveryVehiclePostFields = $vehiclePostFields.Clone()
  $recoveryVehiclePostFields['stqf'] = $modeledRecoveryTargetCount
  $recoveryVehiclePostFields['stsel'] = $modeledRecoveryTargetCount
  $recoveryVehiclePostFields['stdone'] = $modeledRecoveryTargetCount
  $recoveryVehiclePostFields['stchunk'] =
      [uint64](2 * $modeledRecoveryTargetCount)
  $recoveryVehiclePostFields['d722'] =
      [uint64]$script:ExpectedParamCount + $modeledRecoveryTargetCount
  $offlineRecoveryPostVehicle = New-OfflineSnapshot `
      -Fields $recoveryVehiclePostFields -Q 2 -Ms ([uint64]4294968297) `
      -TagBase 'VCSTAT'

  $r5VehicleBaseFields = $vehicleBaseFields.Clone()
  $r5VehiclePostFields = $vehiclePostFields.Clone()
  $r5VehiclePostFields['sncf'] = [uint64]1
  $r5VehiclePostFields['sncb'] = [uint64]37
  $r5VehiclePostFields['sncsf'] = [uint64]1
  $r5VehiclePostFields['sncsb'] = [uint64]37
  $r5VehiclePostFields['snff'] = [uint64]172
  $r5VehiclePostFields['snfsf'] = [uint64]172
  $r5VehiclePostFields['snffm'] = [uint64]100000
  $r5VehiclePostFields['snflm'] = [uint64]5230000
  $r5VehiclePostFields['snfmg'] = [uint64]30000
  $r5VehiclePostFields['stqf'] = [uint64]2
  $r5VehiclePostFields['stsel'] = [uint64]2
  $r5VehiclePostFields['stchunk'] = [uint64]4
  $r5VehiclePostFields['stdone'] = [uint64]2
  $r5VehiclePostFields['d722'] = [uint64]1107
  $r5BaselineVehicle = New-OfflineSnapshot -Fields $r5VehicleBaseFields `
      -Q 1 -Ms ([uint64]90000) -TagBase 'VCSTAT'
  $r5PostVehicle = New-OfflineSnapshot -Fields $r5VehiclePostFields `
      -Q 2 -Ms ([uint64]5500000) -TagBase 'VCSTAT'

  $hbDiagBaseline = New-OfflineSnapshot `
      -Fields @{hgd='0';hdm='9'} -Q 10 -Ms ([uint64]1000) `
      -TagBase 'VCSTAT'
  $hbDiagM0Zero = New-OfflineSnapshot `
      -Fields @{hgd='0';hdm='9'} -Q 11 -Ms ([uint64]2000) `
      -TagBase 'VCSTAT'
  $hbDiagM1Zero = New-OfflineSnapshot `
      -Fields @{hgd='0';hdm='9'} -Q 12 -Ms ([uint64]3000) `
      -TagBase 'VCSTAT'
  $hbDiagZero = Test-VehicleHeartbeatGrantDiagnosticContract `
      -BaselineVehicle $hbDiagBaseline -M0Vehicle $hbDiagM0Zero `
      -M1Vehicle $hbDiagM1Zero
  Add-SelfCase 'vehicle_hb_grant_diag_hgd_zero_delta_allowed' `
      ($hbDiagZero.valid -and
       [uint64]$hbDiagZero.counters.hgd.baseline_to_m1 -eq [uint64]0 -and
       -not [bool]$hbDiagZero.hgd_minimum_delta_required -and
       [uint64]$hbDiagZero.counters.hdm.baseline_to_m1 -eq [uint64]0) `
      'hgd is observational and may remain zero while hdm must remain unchanged'

  $hbDiagM0Positive = New-OfflineSnapshot `
      -Fields @{hgd='2';hdm='9'} -Q 11 -Ms ([uint64]2000) `
      -TagBase 'VCSTAT'
  $hbDiagM1Positive = New-OfflineSnapshot `
      -Fields @{hgd='7';hdm='9'} -Q 12 -Ms ([uint64]3000) `
      -TagBase 'VCSTAT'
  $hbDiagPositive = Test-VehicleHeartbeatGrantDiagnosticContract `
      -BaselineVehicle $hbDiagBaseline -M0Vehicle $hbDiagM0Positive `
      -M1Vehicle $hbDiagM1Positive
  Add-SelfCase 'vehicle_hb_grant_diag_hgd_positive_delta_allowed' `
      ($hbDiagPositive.valid -and
       [uint64]$hbDiagPositive.counters.hgd.baseline_to_m0 -eq [uint64]2 -and
       [uint64]$hbDiagPositive.counters.hgd.m0_to_m1 -eq [uint64]5 -and
       [uint64]$hbDiagPositive.counters.hgd.baseline_to_m1 -eq [uint64]7) `
      'positive hgd activity is recorded with both phase deltas but is not required'

  $hbDiagMissing = New-OfflineSnapshot `
      -Fields @{hdm='9'} -Q 10 -Ms ([uint64]1000) -TagBase 'VCSTAT'
  $hbDiagNonUInt64 = New-OfflineSnapshot `
      -Fields @{hgd='not_uint64';hdm='9'} -Q 11 -Ms ([uint64]2000) `
      -TagBase 'VCSTAT'
  $hbDiagMissingResult = Test-VehicleHeartbeatGrantDiagnosticContract `
      -BaselineVehicle $hbDiagMissing -M0Vehicle $hbDiagM0Zero `
      -M1Vehicle $hbDiagM1Zero
  $hbDiagNonUInt64Result = Test-VehicleHeartbeatGrantDiagnosticContract `
      -BaselineVehicle $hbDiagBaseline -M0Vehicle $hbDiagNonUInt64 `
      -M1Vehicle $hbDiagM1Zero
  Add-SelfCase 'vehicle_hb_grant_diag_missing_or_nonuint64_rejected' `
      (-not $hbDiagMissingResult.valid -and
       -not $hbDiagMissingResult.snapshots.baseline.hgd.field_present -and
       -not $hbDiagNonUInt64Result.valid -and
       $hbDiagNonUInt64Result.snapshots.m0.hgd.field_present -and
       -not $hbDiagNonUInt64Result.snapshots.m0.hgd.uint64_valid) `
      'missing and non-UInt64 hgd/hdm fields fail closed at their exact phase'

  $hbDiagHgdDecreaseM0 = New-OfflineSnapshot `
      -Fields @{hgd='4';hdm='9'} -Q 11 -Ms ([uint64]2000) `
      -TagBase 'VCSTAT'
  $hbDiagHgdDecrease = Test-VehicleHeartbeatGrantDiagnosticContract `
      -BaselineVehicle (New-OfflineSnapshot `
        -Fields @{hgd='5';hdm='9'} -Q 10 -Ms ([uint64]1000) `
        -TagBase 'VCSTAT') `
      -M0Vehicle $hbDiagHgdDecreaseM0 -M1Vehicle $hbDiagM1Positive
  $hbDiagHdmDecrease = Test-VehicleHeartbeatGrantDiagnosticContract `
      -BaselineVehicle $hbDiagBaseline `
      -M0Vehicle (New-OfflineSnapshot `
        -Fields @{hgd='0';hdm='8'} -Q 11 -Ms ([uint64]2000) `
        -TagBase 'VCSTAT') `
      -M1Vehicle $hbDiagM1Zero
  Add-SelfCase 'vehicle_hb_grant_diag_decrease_rejected' `
      (-not $hbDiagHgdDecrease.valid -and
       -not $hbDiagHgdDecrease.counters.hgd.monotonic_non_decreasing -and
       -not $hbDiagHdmDecrease.valid -and
       -not $hbDiagHdmDecrease.counters.hdm.monotonic_non_decreasing) `
      'either counter decreasing at either phase transition fails closed'

  $hbDiagHdmIncrementM1 = New-OfflineSnapshot `
      -Fields @{hgd='0';hdm='10'} -Q 12 -Ms ([uint64]3000) `
      -TagBase 'VCSTAT'
  $hbDiagHdmIncrement = Test-VehicleHeartbeatGrantDiagnosticContract `
      -BaselineVehicle $hbDiagBaseline -M0Vehicle $hbDiagM0Zero `
      -M1Vehicle $hbDiagHdmIncrementM1
  Add-SelfCase 'vehicle_hb_grant_diag_hdm_delta_nonzero_rejected' `
      (-not $hbDiagHdmIncrement.valid -and
       $hbDiagHdmIncrement.counters.hdm.monotonic_non_decreasing -and
       [uint64]$hbDiagHdmIncrement.counters.hdm.baseline_to_m1 -eq
         [uint64]1 -and -not $hbDiagHdmIncrement.hdm_delta_zero) `
      'a monotonic but nonzero missed-deadline delta is a hard HIL failure'

  $hbDiagWrongTag = New-OfflineSnapshot `
      -Fields @{hgd='0';hdm='9'} -Q 10 -Ms ([uint64]1000)
  $hbDiagWrongTagResult = Test-VehicleHeartbeatGrantDiagnosticContract `
      -BaselineVehicle $hbDiagWrongTag -M0Vehicle $hbDiagM0Zero `
      -M1Vehicle $hbDiagM1Zero
  Add-SelfCase 'vehicle_hb_grant_diag_requires_exact_vcstat3' `
      (-not $hbDiagWrongTagResult.valid -and
       $hbDiagWrongTagResult.snapshots.baseline.hgd.vcstat3_count -eq 0 -and
       -not $hbDiagWrongTagResult.snapshots.baseline.hgd.valid) `
      'a similarly named field outside the exact VCSTAT3 response cannot satisfy the contract'

  [string]$uint64MaxText = [uint64]::MaxValue.ToString()
  $hbDiagUInt64Max = New-OfflineSnapshot `
      -Fields @{hgd=$uint64MaxText;hdm=$uint64MaxText} `
      -Q 20 -Ms ([uint64]4000) -TagBase 'VCSTAT'
  $hbDiagUInt64MaxResult = Test-VehicleHeartbeatGrantDiagnosticContract `
      -BaselineVehicle $hbDiagUInt64Max -M0Vehicle $hbDiagUInt64Max `
      -M1Vehicle $hbDiagUInt64Max
  Add-SelfCase 'vehicle_hb_grant_diag_uint64_max_supported' `
      ($hbDiagUInt64MaxResult.valid -and
       [uint64]$hbDiagUInt64MaxResult.snapshots.baseline.hgd.value -eq
         [uint64]::MaxValue -and
       [uint64]$hbDiagUInt64MaxResult.snapshots.m1.hdm.value -eq
         [uint64]::MaxValue) `
      'the full UInt64 domain is parsed without narrowing to Int64 or floating point'

  $offlineBaseline = Test-BaselineSetup `
      -GroundSnapshot $offlineBaselineGround `
      -VehicleSnapshot $offlineBaselineVehicle
  [string[]]$vehicleNativeDiagnosticKeys = @(
    'snf','snbusy','sncf','sncb','snff','snq','snseq')
  [string[]]$groundNativeDiagnosticKeys = @(
    'pnat','ppois','pnq','ppre','mcr','rfpbs','rfpfa','rfpno','rfpbl','rfpcr',
    'rfpum','rfpuf','rfprs','rfpbuf','rfdmbuf','rfdmesc','pvto','pract',
    'prold','prfut','prgap','prto','prq','prtx','prv','prusb','punm','prlv',
    'prlr','prlex','prlrx','prlcnt','prlseq','prlms')
  [object[]]$nativeBaselineChecks = @($offlineBaseline.checks | Where-Object {
      $_.key -cin @($vehicleNativeDiagnosticKeys +
        $groundNativeDiagnosticKeys) -and
      $_.name -like '*_diagnostic_*_present'
    })
  Add-SelfCase 'baseline_native_diagnostic_keys_present_pass' `
      ($offlineBaseline.valid -and $nativeBaselineChecks.Count -eq
         ($vehicleNativeDiagnosticKeys.Count + $groundNativeDiagnosticKeys.Count) -and
       @($nativeBaselineChecks | Where-Object {-not $_.valid}).Count -eq 0) `
      'all Vehicle fence and Ground native/recovery/RF parser diagnostics are numeric in the baseline snapshot'

  $baselineBadIdleSentinelFields = $groundBaseFields.Clone()
  $baselineBadIdleSentinelFields['prlrx'] = [uint64]0
  $baselineBadIdleSentinelSnapshot = New-OfflineSnapshot `
      -Fields $baselineBadIdleSentinelFields -Q 1 -Ms ([uint64]4294967296)
  $baselineBadIdleSentinel = Test-BaselineSetup `
      -GroundSnapshot $baselineBadIdleSentinelSnapshot `
      -VehicleSnapshot $offlineBaselineVehicle
  Add-SelfCase 'baseline_recovery_idle_received_sentinel_zero_rejected' `
      (-not $baselineBadIdleSentinel.valid -and
       @($baselineBadIdleSentinel.checks | Where-Object {
           $_.key -ceq 'prlrx' -and -not $_.valid -and
           [uint64]$_.expected -eq 65535
         }).Count -eq 1) `
      'an idle recovery latch has received_index FFFF; zero is not an equivalent no-evidence value'

  [bool]$missingVehicleNativeDiagnosticRejected = $true
  foreach ($missingKey in $vehicleNativeDiagnosticKeys) {
    $missingFields = $vehicleBaseFields.Clone()
    [void]$missingFields.Remove($missingKey)
    $missingSnapshot = New-OfflineSnapshot -Fields $missingFields `
        -Q 1 -Ms ([uint64]4294967297)
    $missingAssessment = Test-BaselineSetup `
        -GroundSnapshot $offlineBaselineGround `
        -VehicleSnapshot $missingSnapshot
    if ($missingAssessment.valid -or
        @($missingAssessment.checks | Where-Object {
          $_.key -ceq $missingKey -and -not $_.valid
        }).Count -lt 1) {
      $missingVehicleNativeDiagnosticRejected = $false
    }
  }
  Add-SelfCase 'baseline_vehicle_native_diagnostic_key_missing_rejected' `
      $missingVehicleNativeDiagnosticRejected `
      'removing any one Vehicle native fence counter makes the official baseline invalid'

  [bool]$missingGroundNativeDiagnosticRejected = $true
  foreach ($missingKey in $groundNativeDiagnosticKeys) {
    $missingFields = $groundBaseFields.Clone()
    [void]$missingFields.Remove($missingKey)
    $missingSnapshot = New-OfflineSnapshot -Fields $missingFields `
        -Q 1 -Ms ([uint64]4294967296)
    $missingAssessment = Test-BaselineSetup `
        -GroundSnapshot $missingSnapshot `
        -VehicleSnapshot $offlineBaselineVehicle
    if ($missingAssessment.valid -or
        @($missingAssessment.checks | Where-Object {
          $_.key -ceq $missingKey -and -not $_.valid
        }).Count -lt 1) {
      $missingGroundNativeDiagnosticRejected = $false
    }
  }
  Add-SelfCase 'baseline_ground_native_diagnostic_key_missing_rejected' `
      $missingGroundNativeDiagnosticRejected `
      'removing any native/recovery/RF parser GCSTAT3 field makes the official baseline invalid'
  $vehicleDeadFields = $vehicleBaseFields.Clone()
  $vehicleDeadFields['d7f'] = 0
  $vehicleDeadBaseline = New-OfflineSnapshot -Fields $vehicleDeadFields `
      -Q 1 -Ms ([uint64]4294967297)
  Add-SelfCase 'baseline_vehicle_d7f_zero_rejected' `
      (-not (Test-BaselineSetup -GroundSnapshot $offlineBaselineGround `
        -VehicleSnapshot $vehicleDeadBaseline).valid) `
      'official baseline rejects Vehicle d7f=0'
  $groundRfDeadFields = $groundBaseFields.Clone()
  $groundRfDeadFields['rfv'] = 0
  $groundRfDeadBaseline = New-OfflineSnapshot -Fields $groundRfDeadFields `
      -Q 1 -Ms ([uint64]4294967296)
  Add-SelfCase 'baseline_ground_rfv_zero_rejected' `
      (-not (Test-BaselineSetup -GroundSnapshot $groundRfDeadBaseline `
        -VehicleSnapshot $offlineBaselineVehicle).valid) `
      'official baseline rejects Ground rfv=0'
  $groundUsbDeadFields = $groundBaseFields.Clone()
  $groundUsbDeadFields['usbacc'] = 0
  $groundUsbDeadBaseline = New-OfflineSnapshot -Fields $groundUsbDeadFields `
      -Q 1 -Ms ([uint64]4294967296)
  Add-SelfCase 'baseline_ground_usbacc_zero_rejected' `
      (-not (Test-BaselineSetup -GroundSnapshot $groundUsbDeadBaseline `
        -VehicleSnapshot $offlineBaselineVehicle).valid) `
      'official baseline rejects Ground usbacc=0'
  $groundDemuxBufferFields = $groundBaseFields.Clone()
  $groundDemuxBufferFields['rfdmbuf'] = [uint64]1
  $groundDemuxBufferBaseline = New-OfflineSnapshot `
      -Fields $groundDemuxBufferFields -Q 1 -Ms ([uint64]4294967296)
  $groundDemuxBufferAssessment = Test-BaselineSetup `
      -GroundSnapshot $groundDemuxBufferBaseline `
      -VehicleSnapshot $offlineBaselineVehicle
  Add-SelfCase 'baseline_demux_buffer_nonzero_rejected' `
      (-not $groundDemuxBufferAssessment.valid -and
       @($groundDemuxBufferAssessment.checks | Where-Object {
           $_.name -ceq 'ground_radio_demux_buffer_empty' -and
           -not $_.valid -and [uint64]$_.actual -eq 1
         }).Count -eq 1) `
      'official baseline rejects a pending Ground demux candidate or escape byte'
  $groundDemuxModeFields = $groundBaseFields.Clone()
  $groundDemuxModeFields['rfdmesc'] = [uint64]0
  $groundDemuxModeBaseline = New-OfflineSnapshot `
      -Fields $groundDemuxModeFields -Q 1 -Ms ([uint64]4294967296)
  $groundDemuxModeAssessment = Test-BaselineSetup `
      -GroundSnapshot $groundDemuxModeBaseline `
      -VehicleSnapshot $offlineBaselineVehicle
  Add-SelfCase 'baseline_demux_escape_mode_disabled_rejected' `
      (-not $groundDemuxModeAssessment.valid -and
       @($groundDemuxModeAssessment.checks | Where-Object {
           $_.name -ceq 'ground_radio_demux_escape_mode_enabled' -and
           -not $_.valid -and [uint64]$_.actual -eq 0
         }).Count -eq 1) `
      'official baseline rejects a disabled Ground link-data escape mode'
  $staleVehicleFields = $vehicleBaseFields.Clone()
  $staleVehicleFields['d722'] = 3
  $staleVehicleBaseline = New-OfflineSnapshot -Fields $staleVehicleFields `
      -Q 1 -Ms ([uint64]4294967297)
  Add-SelfCase 'baseline_stale_generic_reconciliation_rejected' `
      (-not (Test-BaselineSetup -GroundSnapshot $offlineBaselineGround `
        -VehicleSnapshot $staleVehicleBaseline).valid) `
      'observed run pattern Vehicle d722=3 versus Ground rf22=0 cannot authorize a new request'
  foreach ($queueKey in @('pgq','pga','prq','ptq')) {
    $queueFields = $vehicleBaseFields.Clone();$queueFields[$queueKey] = 1
    $queueSnapshot = New-OfflineSnapshot -Fields $queueFields -Q 1 `
        -Ms ([uint64]4294967297)
    Add-SelfCase ('baseline_vehicle_' + $queueKey + '_nonzero_rejected') `
        (-not (Test-BaselineSetup -GroundSnapshot $offlineBaselineGround `
          -VehicleSnapshot $queueSnapshot).valid) `
        ("official baseline rejects Vehicle $queueKey nonzero")
  }
  Add-SelfCase 'baseline_normal_rb1_ew3_allowed' $offlineBaseline.valid `
      'normal active TDD/E220 diagnostics rb=1 and ew=3 are not PARAM backlog gates'
  Add-SelfCase 'baseline_normal_obf2_obb42_allowed' $offlineBaseline.valid `
      'normal two-heartbeat pacer backlog obf=2/obb=42 is permitted'
  $groundCumulativeDiscardFields = $groundBaseFields.Clone()
  $groundCumulativeDiscardFields['obdf'] = 3
  $groundCumulativeDiscardFields['obdb'] = 63
  $groundCumulativeDiscardA = New-OfflineSnapshot `
      -Fields $groundCumulativeDiscardFields -Q 1 `
      -Ms ([uint64]4294967296)
  $cumulativeDiscardBaseline = Test-BaselineSetup `
      -GroundSnapshot $groundCumulativeDiscardA `
      -VehicleSnapshot $offlineBaselineVehicle
  Add-SelfCase 'baseline_cumulative_discard_nonzero_allowed' `
      $cumulativeDiscardBaseline.valid `
      'boot-cumulative heartbeat pacer discard 3/63 is not an absolute-zero error'
  $groundBacklogFields = $groundBaseFields.Clone()
  $groundBacklogFields['obp22'] = 1
  $groundBacklogSnapshot = New-OfflineSnapshot -Fields $groundBacklogFields `
      -Q 1 -Ms ([uint64]4294967296)
  Add-SelfCase 'baseline_ground_backlog_nonempty_rejected' `
      (-not (Test-BaselineSetup -GroundSnapshot $groundBacklogSnapshot `
        -VehicleSnapshot $offlineBaselineVehicle).valid) `
      'Ground ordered PARAM_VALUE backlog obp22 nonzero is fail-closed'
  $vehicleDropFields = $vehicleBaseFields.Clone()
  $vehicleDropFields['pvbad'] = 1
  $vehicleDropSnapshot = New-OfflineSnapshot -Fields $vehicleDropFields `
      -Q 1 -Ms ([uint64]4294967297)
  Add-SelfCase 'baseline_related_drop_error_rejected' `
      (-not (Test-BaselineSetup -GroundSnapshot $offlineBaselineGround `
        -VehicleSnapshot $vehicleDropSnapshot).valid) `
      'PARAM-related drop/error evidence is fail-closed'

  $mismatchObservation = Test-BacklogDrainObservation `
      -GroundSnapshot $offlineBaselineGround `
      -VehicleSnapshot $staleVehicleBaseline -ObservedElapsedMs 1000
  $cleanVehicleB = New-OfflineSnapshot -Fields $vehicleBaseFields -Q 2 `
      -Ms ([uint64]4294973297)
  $cleanGroundB = New-OfflineSnapshot -Fields $groundBaseFields -Q 2 `
      -Ms ([uint64]4294973296)
  $cleanObservationB = Test-BacklogDrainObservation `
      -GroundSnapshot $cleanGroundB -VehicleSnapshot $cleanVehicleB `
      -ObservedElapsedMs 7000
  $cleanVehicleC = New-OfflineSnapshot -Fields $vehicleBaseFields -Q 3 `
      -Ms ([uint64]4294979297)
  $cleanGroundC = New-OfflineSnapshot -Fields $groundBaseFields -Q 3 `
      -Ms ([uint64]4294979296)
  $cleanObservationC = Test-BacklogDrainObservation `
      -GroundSnapshot $cleanGroundC -VehicleSnapshot $cleanVehicleC `
      -ObservedElapsedMs 13000
  $mismatchThenClean = Test-BacklogDrainStablePair `
      -FirstObservation $mismatchObservation `
      -SecondObservation $cleanObservationB
  $twoCleanStable = Test-BacklogDrainStablePair `
      -FirstObservation $cleanObservationB -SecondObservation $cleanObservationC
  Add-SelfCase 'backlog_drain_current_mismatch_retries' `
      (-not $mismatchObservation.valid -and -not $mismatchThenClean.valid) `
      'd722=3/rf22=0 keeps bounded drain waiting and cannot count as first clean observation'
  Add-SelfCase 'backlog_drain_delayed_stable_pass' `
      ($cleanObservationB.valid -and $cleanObservationC.valid -and
       $twoCleanStable.valid) `
      'drained counters and zero scheduler occupancy pass only after two clean stable observations'
  $promotionGate = [pscustomobject][ordered]@{
    valid=$true;timed_out=$false;sync_invalid=$false
    deadline_extended=$false;fixture_write_count=0
    required_stable_observation_count=2
    minimum_passive_separation_ms=5000
    observations=[object[]]@($cleanObservationB,$cleanObservationC)
    stable_pairs=[object[]]@($twoCleanStable)
    last_vehicle_snapshot=$cleanVehicleC
    last_ground_snapshot=$cleanGroundC
  }
  $promotion = Test-PreRequestRecoveryBacklogPairPromotion `
      -RecoveryBacklogGate $promotionGate `
      -PreviousOfficialVehicle $offlineBaselineVehicle `
      -PreviousOfficialGround $offlineBaselineGround
  Add-SelfCase 'pre_request_retry_stable_backlog_pair_promoted' `
      ($promotion.valid -and $promotion.status -ceq 'PROMOTED' -and
       [object]::ReferenceEquals(
         $promotion.selected_vehicle_snapshot,$cleanVehicleC) -and
       [object]::ReferenceEquals(
         $promotion.selected_ground_snapshot,$cleanGroundC) -and
       $promotion.baseline_setup.valid -and
       $promotion.skip_next_recovery_capture -and
       $promotion.additional_diagnostic_query_count -eq 0 -and
       $promotion.fixture_write_count -eq 0) `
      'the final two-observation stable pair is independently revalidated and promoted without another query or blind recovery interval'

  $stalePromotionGate = $promotionGate.PSObject.Copy()
  $stalePromotionGate.last_vehicle_snapshot = $cleanVehicleB
  $stalePromotion = Test-PreRequestRecoveryBacklogPairPromotion `
      -RecoveryBacklogGate $stalePromotionGate `
      -PreviousOfficialVehicle $offlineBaselineVehicle `
      -PreviousOfficialGround $offlineBaselineGround
  $invalidStablePromotionGate = $promotionGate.PSObject.Copy()
  $invalidStablePromotionGate.stable_pairs = [object[]]@($mismatchThenClean)
  $invalidStablePromotion = Test-PreRequestRecoveryBacklogPairPromotion `
      -RecoveryBacklogGate $invalidStablePromotionGate `
      -PreviousOfficialVehicle $offlineBaselineVehicle `
      -PreviousOfficialGround $offlineBaselineGround
  Add-SelfCase 'pre_request_retry_stale_or_nonfinal_pair_rejected_write0' `
      (-not $stalePromotion.valid -and
       -not $invalidStablePromotion.valid -and
       $stalePromotion.fixture_write_count -eq 0 -and
       $invalidStablePromotion.fixture_write_count -eq 0) `
      'a stale last-snapshot pointer or invalid recorded final stable pair cannot be promoted'

  $mismatchPromotionVehicleFields = $vehicleBaseFields.Clone()
  $mismatchPromotionVehicleFields['d722'] = [uint64]1
  $mismatchPromotionVehicle = New-OfflineSnapshot `
      -Fields $mismatchPromotionVehicleFields -Q 3 `
      -Ms ([uint64]4294979297)
  $mismatchPromotionObservation = Test-BacklogDrainObservation `
      -GroundSnapshot $cleanGroundC `
      -VehicleSnapshot $mismatchPromotionVehicle `
      -ObservedElapsedMs 13000
  $mismatchPromotionPair = Test-BacklogDrainStablePair `
      -FirstObservation $cleanObservationB `
      -SecondObservation $mismatchPromotionObservation
  $mismatchPromotionGate = [pscustomobject][ordered]@{
    valid=$true;timed_out=$false;sync_invalid=$false
    deadline_extended=$false;fixture_write_count=0
    required_stable_observation_count=2
    minimum_passive_separation_ms=5000
    observations=[object[]]@(
      $cleanObservationB,$mismatchPromotionObservation)
    stable_pairs=[object[]]@($mismatchPromotionPair)
    last_vehicle_snapshot=$mismatchPromotionVehicle
    last_ground_snapshot=$cleanGroundC
  }
  $mismatchPromotion = Test-PreRequestRecoveryBacklogPairPromotion `
      -RecoveryBacklogGate $mismatchPromotionGate `
      -PreviousOfficialVehicle $offlineBaselineVehicle `
      -PreviousOfficialGround $offlineBaselineGround
  Add-SelfCase 'pre_request_retry_promoted_pair_d722_rf22_mismatch_rejected_write0' `
      (-not $mismatchPromotion.valid -and
