  Add-SelfCase 'baseline_param22_persistent_mismatch_retry_exhausted_write0' `
      ($baselineAttempt1Disposition.action -ceq 'RETRY' -and
       $baselinePersistent2Disposition.action -ceq 'RETRY' -and
       $baselinePersistent3Disposition.action -ceq 'REJECT' -and
       $baselinePersistent3Disposition.retry_exhausted -and
       $persistentFixtureWriteCount -eq 0) `
      '22/23, 23/24, 24/25 exhausts three attempts and never writes fixture #21'

  $baselineVehicleAheadFields = $vehicleBaseFields.Clone()
  $baselineVehicleAheadFields['d722'] = 23
  $baselineVehicleAhead = New-OfflineSnapshot `
      -Fields $baselineVehicleAheadFields -Q 11 `
      -Ms ([uint64]4294982000)
  $baselineVehicleAheadSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineDrainGround `
      -VehicleSnapshot $baselineVehicleAhead `
      -PreviousGroundSnapshot $baselineDrainGround `
      -PreviousVehicleSnapshot $baselineDrainVehicle
  $baselineVehicleAheadDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineVehicleAheadSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  $baselineGroundAheadTwoFields = $groundBaseFields.Clone()
  $baselineGroundAheadTwoFields['rf22'] = 24
  $baselineGroundAheadTwo = New-OfflineSnapshot `
      -Fields $baselineGroundAheadTwoFields -Q 21 `
      -Ms ([uint64]4294982001)
  $baselineGroundAheadTwoSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineGroundAheadTwo `
      -VehicleSnapshot $baselineAttempt1Vehicle `
      -PreviousGroundSnapshot $baselineDrainGround `
      -PreviousVehicleSnapshot $baselineDrainVehicle
  $baselineGroundAheadTwoDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineGroundAheadTwoSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  $baselineQueueFields = $baselineDrainVehicleFields.Clone()
  $baselineQueueFields['pgq'] = 1
  $baselineQueueVehicle = New-OfflineSnapshot -Fields $baselineQueueFields `
      -Q 11 -Ms ([uint64]4294982000)
  $baselineQueueSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineAttempt1Ground `
      -VehicleSnapshot $baselineQueueVehicle `
      -PreviousGroundSnapshot $baselineDrainGround `
      -PreviousVehicleSnapshot $baselineDrainVehicle
  $baselineQueueDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineQueueSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  $baselineDiscardFields = $baselineAttempt1GroundFields.Clone()
  $baselineDiscardFields['obdf'] = 1
  $baselineDiscardGround = New-OfflineSnapshot `
      -Fields $baselineDiscardFields -Q 21 `
      -Ms ([uint64]4294982001)
  $baselineDiscardSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineDiscardGround `
      -VehicleSnapshot $baselineAttempt1Vehicle `
      -PreviousGroundSnapshot $baselineDrainGround `
      -PreviousVehicleSnapshot $baselineDrainVehicle
  $baselineDiscardDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineDiscardSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  $baselineBootFields = $baselineDrainVehicleFields.Clone()
  $baselineBootFields['boot'] = 95
  $baselineBootVehicle = New-OfflineSnapshot -Fields $baselineBootFields `
      -Q 11 -Ms ([uint64]4294982000)
  $baselineBootSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineAttempt1Ground `
      -VehicleSnapshot $baselineBootVehicle `
      -PreviousGroundSnapshot $baselineDrainGround `
      -PreviousVehicleSnapshot $baselineDrainVehicle
  $baselineBootDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineBootSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'baseline_param22_unsafe_mismatch_not_retryable' `
      ($baselineVehicleAheadDisposition.action -ceq 'REJECT' -and
       $baselineGroundAheadTwoDisposition.action -ceq 'REJECT' -and
       $baselineQueueDisposition.action -ceq 'REJECT' -and
       $baselineDiscardDisposition.action -ceq 'REJECT' -and
       $baselineBootDisposition.action -ceq 'REJECT') `
      'Vehicle-ahead, Ground+2, queue, discard growth, and boot change remain fail-closed'

  # A periodic STAT_RUNTIME sentinel can arrive after the final clean drain
  # observation but before the official Vehicle baseline line is emitted.  It
  # must never be accepted as a baseline; an exact observer-correlated race may
  # only authorize bounded full-pair reacquisition.
  $baselineSentinelPreviousVehicleFields = $baselineDrainVehicleFields.Clone()
  $baselineSentinelPreviousVehicleFields['pvok'] = 22
  $baselineSentinelPreviousVehicleFields['pvid'] = 'STAT_RUNTIME'
  $baselineSentinelPreviousVehicleFields['pvidx'] = 65535
  $baselineSentinelPreviousVehicleFields['pvcnt'] = 932
  $baselineSentinelPreviousVehicleFields['pvtype'] = 6
  $baselineSentinelPreviousVehicleFields['pvsys'] = 1
  $baselineSentinelPreviousVehicleFields['pvcomp'] = 1
  $baselineSentinelPreviousVehicleFields['pvs1'] = 0
  $baselineSentinelPreviousVehicleFields['d7pb'] = 0
  $baselineSentinelPreviousVehicleFields['pvms'] = [uint64]4294950000
  $baselineSentinelPreviousVehicle = New-OfflineSnapshot `
      -Fields $baselineSentinelPreviousVehicleFields -Q 10 `
      -Ms ([uint64]4294981000)
  $baselineSentinelVehicleFields = $baselineSentinelPreviousVehicleFields.Clone()
  $baselineSentinelVehicleFields['d722'] = 23
  $baselineSentinelVehicleFields['pvok'] = 23
  $baselineSentinelVehicleFields['pgq'] = 1
  $baselineSentinelVehicleFields['pvms'] = [uint64]4294981500
  $baselineSentinelVehicle = New-OfflineSnapshot `
      -Fields $baselineSentinelVehicleFields -Q 11 `
      -Ms ([uint64]4294982000)
  $baselineSentinelGroundFields = $baselineDrainGroundFields.Clone()
  $baselineSentinelGroundFields['rf22'] = 23
  $baselineSentinelGround = New-OfflineSnapshot `
      -Fields $baselineSentinelGroundFields -Q 21 `
      -Ms ([uint64]4294982001)
  $baselineSentinelSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineSentinelGround `
      -VehicleSnapshot $baselineSentinelVehicle `
      -PreviousGroundSnapshot $baselineDrainGround `
      -PreviousVehicleSnapshot $baselineSentinelPreviousVehicle
  $baselineSentinelDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineSentinelSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  $baselineSentinelFailed = @($baselineSentinelSetup.checks | Where-Object {
      -not $_.valid})
  Add-SelfCase 'baseline_exact_stat_runtime_race_retryable' `
      (-not $baselineSentinelSetup.valid -and
       $baselineSentinelFailed.Count -eq 1 -and
       $baselineSentinelFailed[0].name -ceq
         'vehicle_generic_param_fifo_empty' -and
       $baselineSentinelSetup.known_stat_runtime_race.valid -and
       $baselineSentinelDisposition.action -ceq 'RETRY' -and
       $baselineSentinelDisposition.reason -ceq
         'known_stat_runtime_baseline_race' -and
       $baselineSentinelDisposition.retry_eligible) `
      'exact fresh STAT_RUNTIME / 65535 / 932 / 6 with d722/pvok/rf22 +1 and sole pgq=1 triggers full-pair reacquisition, never acceptance'

  $baselineUnknownSentinelFields = $baselineSentinelVehicleFields.Clone()
  $baselineUnknownSentinelFields['pvid'] = 'STAT_OTHER'
  $baselineUnknownSentinelVehicle = New-OfflineSnapshot `
      -Fields $baselineUnknownSentinelFields -Q 11 `
      -Ms ([uint64]4294982000)
  $baselineUnknownSentinelSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineSentinelGround `
      -VehicleSnapshot $baselineUnknownSentinelVehicle `
      -PreviousGroundSnapshot $baselineDrainGround `
      -PreviousVehicleSnapshot $baselineSentinelPreviousVehicle
  $baselineUnknownSentinelDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineUnknownSentinelSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  $baselineIndexedSentinelFields = $baselineSentinelVehicleFields.Clone()
  $baselineIndexedSentinelFields['pvidx'] = 0
  $baselineIndexedSentinelVehicle = New-OfflineSnapshot `
      -Fields $baselineIndexedSentinelFields -Q 11 `
      -Ms ([uint64]4294982000)
  $baselineIndexedSentinelSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineSentinelGround `
      -VehicleSnapshot $baselineIndexedSentinelVehicle `
      -PreviousGroundSnapshot $baselineDrainGround `
      -PreviousVehicleSnapshot $baselineSentinelPreviousVehicle
  $baselineIndexedSentinelDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineIndexedSentinelSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'baseline_unknown_or_indexed_sentinel_not_retryable' `
      ($baselineUnknownSentinelDisposition.action -ceq 'REJECT' -and
       -not $baselineUnknownSentinelDisposition.retry_eligible -and
       $baselineIndexedSentinelDisposition.action -ceq 'REJECT' -and
       -not $baselineIndexedSentinelDisposition.retry_eligible) `
      'unknown or indexed PARAM_VALUE observer tuples remain fail-closed at baseline'

  $baselineStaleSentinelFields = $baselineSentinelVehicleFields.Clone()
  $baselineStaleSentinelFields['pvms'] = [uint64]4294981000
  $baselineStaleSentinelVehicle = New-OfflineSnapshot `
      -Fields $baselineStaleSentinelFields -Q 11 `
      -Ms ([uint64]4294982000)
  $baselineStaleSentinelSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineSentinelGround `
      -VehicleSnapshot $baselineStaleSentinelVehicle `
      -PreviousGroundSnapshot $baselineDrainGround `
      -PreviousVehicleSnapshot $baselineSentinelPreviousVehicle
  $baselineStaleSentinelDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineStaleSentinelSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  $baselineCounterSentinelFields = $baselineSentinelVehicleFields.Clone()
  $baselineCounterSentinelFields['pvok'] = 22
  $baselineCounterSentinelVehicle = New-OfflineSnapshot `
      -Fields $baselineCounterSentinelFields -Q 11 `
      -Ms ([uint64]4294982000)
  $baselineCounterSentinelSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineSentinelGround `
      -VehicleSnapshot $baselineCounterSentinelVehicle `
      -PreviousGroundSnapshot $baselineDrainGround `
      -PreviousVehicleSnapshot $baselineSentinelPreviousVehicle
  $baselineCounterSentinelDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineCounterSentinelSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'baseline_stale_or_unproven_stat_runtime_not_retryable' `
      ($baselineStaleSentinelDisposition.action -ceq 'REJECT' -and
       -not $baselineStaleSentinelDisposition.retry_eligible -and
       $baselineCounterSentinelDisposition.action -ceq 'REJECT' -and
       -not $baselineCounterSentinelDisposition.retry_eligible) `
      'stale pvms or missing pvok +1 observer proof never authorizes baseline retry'

  $baselineMultiFailureSentinelFields = $baselineSentinelVehicleFields.Clone()
  $baselineMultiFailureSentinelFields['pga'] = 1
  $baselineMultiFailureSentinelVehicle = New-OfflineSnapshot `
      -Fields $baselineMultiFailureSentinelFields -Q 11 `
      -Ms ([uint64]4294982000)
  $baselineMultiFailureSentinelSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineSentinelGround `
      -VehicleSnapshot $baselineMultiFailureSentinelVehicle `
      -PreviousGroundSnapshot $baselineDrainGround `
      -PreviousVehicleSnapshot $baselineSentinelPreviousVehicle
  $baselineMultiFailureSentinelDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineMultiFailureSentinelSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'baseline_stat_runtime_plus_other_failure_not_retryable' `
      ($baselineMultiFailureSentinelDisposition.action -ceq 'REJECT' -and
       -not $baselineMultiFailureSentinelDisposition.retry_eligible) `
      'exact observer tuple cannot mask any second baseline failure'

  $baselineSentinelNoBudgetDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineSentinelSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $false
  $baselineSentinelExhaustedDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineSentinelSetup -AttemptNumber 3 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'baseline_stat_runtime_retry_bounded_by_deadline_and_attempts' `
      ($baselineSentinelNoBudgetDisposition.action -ceq 'REJECT' -and
       $baselineSentinelNoBudgetDisposition.reason -ceq
         'shared_deadline_exhausted' -and
       $baselineSentinelExhaustedDisposition.action -ceq 'REJECT' -and
       $baselineSentinelExhaustedDisposition.retry_exhausted) `
      'exact sentinel retry cannot extend the shared deadline or exceed three full-pair attempts'

  $baselineSentinelCleanVehicleFields = $baselineSentinelVehicleFields.Clone()
  $baselineSentinelCleanVehicleFields['pgq'] = 0
  $baselineSentinelCleanVehicle = New-OfflineSnapshot `
      -Fields $baselineSentinelCleanVehicleFields -Q 12 `
      -Ms ([uint64]4294983000)
  $baselineSentinelCleanGround = New-OfflineSnapshot `
      -Fields $baselineSentinelGroundFields -Q 22 `
      -Ms ([uint64]4294983001)
  $baselineSentinelCleanSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineSentinelCleanGround `
      -VehicleSnapshot $baselineSentinelCleanVehicle `
      -PreviousGroundSnapshot $baselineSentinelGround `
      -PreviousVehicleSnapshot $baselineSentinelVehicle
  $baselineSentinelCleanDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineSentinelCleanSetup -AttemptNumber 2 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'baseline_stat_runtime_retry_then_full_pair_clean_pass' `
      ($baselineSentinelDisposition.action -ceq 'RETRY' -and
       $baselineSentinelCleanSetup.valid -and
       $baselineSentinelCleanDisposition.action -ceq 'ACCEPT' -and
       $baselineSentinelCleanVehicle.q_uint32 -eq 12 -and
       $baselineSentinelCleanGround.q_uint32 -eq 22 -and
       ([int]$baselineSentinelDisposition.fixture_write_count +
        [int]$baselineSentinelCleanDisposition.fixture_write_count) -eq 0) `
      'a race snapshot is never selected; only the next complete clean Vehicle/Ground pair may become baseline and fixture remains write0'

  # A 32-byte fixed Vehicle-then-Ground pump can expose the same exact
  # STAT_RUNTIME frame one slice earlier: Vehicle has parsed and queued the
  # frame, while Ground rf22 has not moved yet.  Build each variant from fresh
  # snapshots so every negative case proves the production predicate itself.
  $evaluateVehicleAheadBaseline = {
    param(
      [hashtable]$CurrentVehicleOverrides = @{},
      [hashtable]$PreviousVehicleOverrides = @{},
      [hashtable]$CurrentGroundOverrides = @{},
      [hashtable]$PreviousGroundOverrides = @{},
      [int]$AttemptNumber = 1,
      [bool]$RetryBudgetAvailable = $true,
      [uint32]$PreviousVehicleQ = 10,
      [uint32]$CurrentVehicleQ = 11,
      [uint32]$PreviousGroundQ = 20,
      [uint32]$CurrentGroundQ = 21,
      [uint64]$PreviousVehicleMs = 4294981000,
      [uint64]$CurrentVehicleMs = 4294982000,
      [uint64]$PreviousGroundMs = 4294981001,
      [uint64]$CurrentGroundMs = 4294982001
    )
    $previousVehicleFields = $baselineSentinelPreviousVehicleFields.Clone()
    $currentVehicleFields = $baselineSentinelPreviousVehicleFields.Clone()
    $previousGroundFields = $baselineDrainGroundFields.Clone()
    $currentGroundFields = $baselineDrainGroundFields.Clone()
    $currentVehicleFields['d722'] = [uint64]23
    $currentVehicleFields['pvok'] = [uint64]23
    $currentVehicleFields['pgq'] = [uint64]1
    $currentVehicleFields['d7pb'] = [uint64]22
    $currentVehicleFields['pvms'] = [uint64]4294981500
    foreach ($entry in $PreviousVehicleOverrides.GetEnumerator()) {
      $previousVehicleFields[$entry.Key] = $entry.Value
    }
    foreach ($entry in $CurrentVehicleOverrides.GetEnumerator()) {
      $currentVehicleFields[$entry.Key] = $entry.Value
    }
    foreach ($entry in $PreviousGroundOverrides.GetEnumerator()) {
      $previousGroundFields[$entry.Key] = $entry.Value
    }
    foreach ($entry in $CurrentGroundOverrides.GetEnumerator()) {
      $currentGroundFields[$entry.Key] = $entry.Value
    }
    $previousVehicle = New-OfflineSnapshot -Fields $previousVehicleFields `
        -Q $PreviousVehicleQ -Ms $PreviousVehicleMs
    $currentVehicle = New-OfflineSnapshot -Fields $currentVehicleFields `
        -Q $CurrentVehicleQ -Ms $CurrentVehicleMs
    $previousGround = New-OfflineSnapshot -Fields $previousGroundFields `
        -Q $PreviousGroundQ -Ms $PreviousGroundMs
    $currentGround = New-OfflineSnapshot -Fields $currentGroundFields `
        -Q $CurrentGroundQ -Ms $CurrentGroundMs
    $setup = Test-BaselineSetup -GroundSnapshot $currentGround `
        -VehicleSnapshot $currentVehicle `
        -PreviousGroundSnapshot $previousGround `
        -PreviousVehicleSnapshot $previousVehicle
    $disposition = Get-BaselineAttemptDisposition `
        -BaselineSetup $setup -AttemptNumber $AttemptNumber `
        -MaxAttempts 3 -RetryBudgetAvailable $RetryBudgetAvailable
    return [pscustomobject][ordered]@{
      setup=$setup;disposition=$disposition
      previous_vehicle=$previousVehicle;current_vehicle=$currentVehicle
      previous_ground=$previousGround;current_ground=$currentGround
    }
  }

  $baselineVehicleAheadExact = & $evaluateVehicleAheadBaseline
  $baselineVehicleAheadExactFailed = @(
      $baselineVehicleAheadExact.setup.checks | Where-Object {-not $_.valid})
  Add-SelfCase 'baseline_exact_stat_runtime_vehicle_ahead_race_retryable' `
      (-not $baselineVehicleAheadExact.setup.valid -and
       $baselineVehicleAheadExactFailed.Count -eq 2 -and
       $baselineVehicleAheadExactFailed.name -ccontains
         'vehicle_ground_param22_reconciled' -and
       $baselineVehicleAheadExactFailed.name -ccontains
         'vehicle_generic_param_fifo_empty' -and
       $baselineVehicleAheadExact.setup.known_stat_runtime_vehicle_ahead_race.valid -and
       $baselineVehicleAheadExact.setup.known_stat_runtime_vehicle_ahead_race.classification -ceq
         'exact_known_STAT_RUNTIME_vehicle_ahead_baseline_race' -and
       $baselineVehicleAheadExact.disposition.action -ceq 'RETRY' -and
       $baselineVehicleAheadExact.disposition.reason -ceq
         'known_stat_runtime_vehicle_ahead_baseline_race' -and
       $baselineVehicleAheadExact.disposition.retry_eligible -and
       $baselineVehicleAheadExact.disposition.fixture_write_count -eq 0) `
      'exact STAT_RUNTIME with Vehicle d722/pvok +1, Ground rf22 +0, pgq=1 and bounded d7pb authorizes only another full pair'

  [object[]]$baselineVehicleAheadReversedChecks = [object[]]@(
      $baselineVehicleAheadExact.setup.checks)
  [array]::Reverse($baselineVehicleAheadReversedChecks)
  $baselineVehicleAheadReorderedSetup =
      $baselineVehicleAheadExact.setup.PSObject.Copy()
  $baselineVehicleAheadReorderedSetup.checks =
      $baselineVehicleAheadReversedChecks
  $baselineVehicleAheadReorderedDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineVehicleAheadReorderedSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'baseline_stat_runtime_vehicle_ahead_failure_set_order_independent' `
      ($baselineVehicleAheadReorderedDisposition.action -ceq 'RETRY' -and
       $baselineVehicleAheadReorderedDisposition.exact_vehicle_ahead_failure_set -and
       $baselineVehicleAheadReorderedDisposition.failed_check_count -eq 2) `
      'the exact two-name failure set remains retryable after reversing check order'

  [bool]$baselineVehicleAheadBoundsValid = $true
  foreach ($d7pbBound in @([uint64]1,[uint64]279)) {
    $boundedEvaluation = & $evaluateVehicleAheadBaseline `
        -CurrentVehicleOverrides @{d7pb=$d7pbBound}
    if ($boundedEvaluation.disposition.action -cne 'RETRY' -or
        -not $boundedEvaluation.setup.known_stat_runtime_vehicle_ahead_race.valid) {
      $baselineVehicleAheadBoundsValid = $false
    }
  }
  Add-SelfCase 'baseline_stat_runtime_vehicle_ahead_d7pb_bounds_1_279_retryable' `
      $baselineVehicleAheadBoundsValid `
      'both inclusive d7pb boundaries 1 and 279 preserve the exact bounded race proof'

  $baselineVehicleAheadD7pbZero = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]0}
  $baselineVehicleAheadD7pb280 = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]280}
  [bool]$baselineVehicleAheadOutOfRangeRejected = (
      -not $baselineVehicleAheadD7pbZero.setup.known_stat_runtime_vehicle_ahead_race.valid -and
      $baselineVehicleAheadD7pbZero.setup.known_stat_runtime_vehicle_ahead_empty_d7_race.valid -and
      $baselineVehicleAheadD7pbZero.disposition.action -ceq 'RETRY' -and
      $baselineVehicleAheadD7pbZero.disposition.reason -ceq
        'known_stat_runtime_vehicle_ahead_empty_d7_baseline_race' -and
      -not $baselineVehicleAheadD7pb280.setup.known_stat_runtime_vehicle_ahead_race.valid -and
      -not $baselineVehicleAheadD7pb280.setup.known_stat_runtime_vehicle_ahead_empty_d7_race.valid -and
      $baselineVehicleAheadD7pb280.disposition.action -ceq 'REJECT' -and
      -not $baselineVehicleAheadD7pb280.disposition.retry_eligible)
  Add-SelfCase 'baseline_stat_runtime_vehicle_ahead_d7pb_out_of_range_not_retryable' `
      $baselineVehicleAheadOutOfRangeRejected `
      'the old partial-D7 route still excludes 0 and 280; the separate exact-empty route handles only 0 while 280 remains fail-closed'

  [bool]$baselineVehicleAheadTupleVariantsRejected = $true
  foreach ($tupleOverrides in @(
      @{pvid='STAT_OTHER'},@{pvid='stat_runtime'},@{pvidx=[uint64]0},
      @{pvcnt=[uint64]931},
      @{pvtype=[uint64]9},@{pvsys=[uint64]2},@{pvcomp=[uint64]2},
      @{pvs1=[uint64]1})) {
    $tupleEvaluation = & $evaluateVehicleAheadBaseline `
        -CurrentVehicleOverrides $tupleOverrides
    if ($tupleEvaluation.disposition.action -cne 'REJECT' -or
        $tupleEvaluation.disposition.retry_eligible) {
      $baselineVehicleAheadTupleVariantsRejected = $false
    }
  }
  Add-SelfCase 'baseline_stat_runtime_vehicle_ahead_tuple_variants_not_retryable' `
      $baselineVehicleAheadTupleVariantsRejected `
      'unknown ID, indexed/count/type/source variants, and occupied single lane cannot authorize retry'

  $baselineVehicleAheadStaleEqual = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{pvms=[uint64]4294981000}
  $baselineVehicleAheadStaleFuture = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{pvms=[uint64]4294982001}
  Add-SelfCase 'baseline_stat_runtime_vehicle_ahead_stale_pvms_not_retryable' `
      ($baselineVehicleAheadStaleEqual.disposition.action -ceq 'REJECT' -and
       -not $baselineVehicleAheadStaleEqual.disposition.retry_eligible -and
       $baselineVehicleAheadStaleFuture.disposition.action -ceq 'REJECT' -and
       -not $baselineVehicleAheadStaleFuture.disposition.retry_eligible) `
      'pvms must be strictly newer than the previous Vehicle snapshot and no newer than the current snapshot'

  [bool]$baselineVehicleAheadCounterVariantsRejected = $true
  foreach ($counterVariant in @(
      [pscustomobject]@{cv=@{d722=[uint64]22};pv=@{};cg=@{};pg=@{}},
      [pscustomobject]@{cv=@{d722=[uint64]24};pv=@{};cg=@{};pg=@{}},
      [pscustomobject]@{cv=@{pvok=[uint64]22};pv=@{};cg=@{};pg=@{}},
      [pscustomobject]@{cv=@{pvok=[uint64]24};pv=@{};cg=@{};pg=@{}},
      [pscustomobject]@{cv=@{d7cr=[uint64]1};pv=@{};cg=@{};pg=@{}},
      [pscustomobject]@{cv=@{};pv=@{d722=[uint64]21};cg=@{};pg=@{}},
      [pscustomobject]@{cv=@{};pv=@{pvok=[uint64]21};cg=@{};pg=@{}},
      [pscustomobject]@{cv=@{};pv=@{d7pb=[uint64]1};cg=@{};pg=@{}})) {
    $counterEvaluation = & $evaluateVehicleAheadBaseline `
        -CurrentVehicleOverrides $counterVariant.cv `
        -PreviousVehicleOverrides $counterVariant.pv `
        -CurrentGroundOverrides $counterVariant.cg `
        -PreviousGroundOverrides $counterVariant.pg
    if ($counterEvaluation.disposition.action -cne 'REJECT' -or
        $counterEvaluation.disposition.retry_eligible) {
      $baselineVehicleAheadCounterVariantsRejected = $false
    }
  }
  Add-SelfCase 'baseline_stat_runtime_vehicle_ahead_counter_shape_not_retryable' `
      $baselineVehicleAheadCounterVariantsRejected `
      'non-reclassifying changes to previous reconciliation, +1/0/+1 deltas, d7cr stability, or previous d7pb emptiness reject'

  [bool]$baselineVehicleAheadQueueVariantsRejected = $true
  foreach ($queueVariant in @(
      [pscustomobject]@{cv=@{pgq=[uint64]2};pv=@{}},
      [pscustomobject]@{cv=@{pvs1=[uint64]1};pv=@{}},
      [pscustomobject]@{cv=@{pga=[uint64]1};pv=@{}},
      [pscustomobject]@{cv=@{prq=[uint64]1};pv=@{}},
      [pscustomobject]@{cv=@{ptq=[uint64]1};pv=@{}},
      [pscustomobject]@{cv=@{ef=[uint64]1};pv=@{}},
      [pscustomobject]@{cv=@{};pv=@{pgq=[uint64]1}})) {
    $queueEvaluation = & $evaluateVehicleAheadBaseline `
        -CurrentVehicleOverrides $queueVariant.cv `
        -PreviousVehicleOverrides $queueVariant.pv
    if ($queueEvaluation.disposition.action -cne 'REJECT' -or
        $queueEvaluation.disposition.retry_eligible) {
      $baselineVehicleAheadQueueVariantsRejected = $false
    }
  }
  foreach ($groundQueueKey in @('dlq','obp22')) {
    $groundQueueEvaluation = & $evaluateVehicleAheadBaseline `
        -CurrentGroundOverrides @{$groundQueueKey=[uint64]1}
    if ($groundQueueEvaluation.disposition.action -cne 'REJECT' -or
        $groundQueueEvaluation.disposition.retry_eligible) {
      $baselineVehicleAheadQueueVariantsRejected = $false
    }
  }
  Add-SelfCase 'baseline_stat_runtime_vehicle_ahead_queue_or_activity_not_retryable' `
      $baselineVehicleAheadQueueVariantsRejected `
      'pgq must transition 0 to exactly 1 while pga, prq, and ptq stay zero'

  [bool]$baselineVehicleAheadErrorsRejected = $true
  foreach ($vehicleErrorKey in @('pvbad','pvov','eo','evo')) {
    $vehicleErrorEvaluation = & $evaluateVehicleAheadBaseline `
        -CurrentVehicleOverrides @{$vehicleErrorKey=[uint64]1}
    if ($vehicleErrorEvaluation.disposition.action -cne 'REJECT' -or
        $vehicleErrorEvaluation.disposition.retry_eligible) {
      $baselineVehicleAheadErrorsRejected = $false
    }
  }
  foreach ($groundErrorKey in @('obif','obof','psfail','prej')) {
    $groundErrorEvaluation = & $evaluateVehicleAheadBaseline `
        -CurrentGroundOverrides @{$groundErrorKey=[uint64]1}
    if ($groundErrorEvaluation.disposition.action -cne 'REJECT' -or
        $groundErrorEvaluation.disposition.retry_eligible) {
      $baselineVehicleAheadErrorsRejected = $false
    }
  }
  Add-SelfCase 'baseline_stat_runtime_vehicle_ahead_error_not_retryable' `
      $baselineVehicleAheadErrorsRejected `
      'any related parser, overflow, ordered-backlog, proxy-send, or rejection error remains fail-closed'

  $baselineVehicleAheadBootChanged = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{boot=[uint64]95}
  $baselineVehicleAheadGroundBootChanged = & $evaluateVehicleAheadBaseline `
      -CurrentGroundOverrides @{boot=[uint64]100}
  $baselineVehicleAheadDiscardFrameChanged = & $evaluateVehicleAheadBaseline `
      -CurrentGroundOverrides @{obdf=[uint64]1}
  $baselineVehicleAheadDiscardByteChanged = & $evaluateVehicleAheadBaseline `
      -CurrentGroundOverrides @{obdb=[uint64]1}
  Add-SelfCase 'baseline_stat_runtime_vehicle_ahead_boot_or_discard_not_retryable' `
      ($baselineVehicleAheadBootChanged.disposition.action -ceq 'REJECT' -and
       -not $baselineVehicleAheadBootChanged.disposition.retry_eligible -and
       $baselineVehicleAheadGroundBootChanged.disposition.action -ceq 'REJECT' -and
       -not $baselineVehicleAheadGroundBootChanged.disposition.retry_eligible -and
       $baselineVehicleAheadDiscardFrameChanged.disposition.action -ceq 'REJECT' -and
       -not $baselineVehicleAheadDiscardFrameChanged.disposition.retry_eligible -and
       $baselineVehicleAheadDiscardByteChanged.disposition.action -ceq 'REJECT' -and
       -not $baselineVehicleAheadDiscardByteChanged.disposition.retry_eligible) `
      'Vehicle reboot or Ground ordered-discard growth invalidates the observer boundary proof'

  $baselineVehicleAheadThirdFailure = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{pga=[uint64]1}
  $baselineVehicleAheadOnlyReconciliation = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{pgq=[uint64]0}
  Add-SelfCase 'baseline_stat_runtime_vehicle_ahead_failure_set_not_exact_not_retryable' `
      ($baselineVehicleAheadThirdFailure.disposition.action -ceq 'REJECT' -and
       -not $baselineVehicleAheadThirdFailure.disposition.retry_eligible -and
       -not $baselineVehicleAheadThirdFailure.disposition.exact_vehicle_ahead_failure_set -and
       $baselineVehicleAheadThirdFailure.disposition.failed_check_count -gt 2 -and
       $baselineVehicleAheadOnlyReconciliation.disposition.action -ceq 'REJECT' -and
       -not $baselineVehicleAheadOnlyReconciliation.disposition.retry_eligible) `
      'the Vehicle-ahead observer tuple cannot mask a third failure or a lone reconciliation mismatch'

  # R5 exposed the adjacent sequential-snapshot shape: Vehicle first sees a
  # queued periodic STAT_RUNTIME plus the beginning of the following D7 frame,
  # then Ground catches the complete PARAM_VALUE before its snapshot.  This is
  # still an invalid baseline and may only request another complete pair.
  $baselineReconciledPartialR5 = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]4} `
      -CurrentGroundOverrides @{rf22=[uint64]23}
  $baselineReconciledPartialR5Property =
      $baselineReconciledPartialR5.setup.PSObject.Properties[
        'known_stat_runtime_reconciled_partial_d7_race']
  [bool]$baselineReconciledPartialR5Exact = (
      $null -ne $baselineReconciledPartialR5Property -and
      $null -ne $baselineReconciledPartialR5Property.Value -and
      [bool]$baselineReconciledPartialR5Property.Value.valid -and
      [string]$baselineReconciledPartialR5Property.Value.classification -ceq
        'exact_known_STAT_RUNTIME_reconciled_partial_D7_baseline_race')
  $baselineReconciledPartialR5Failed = @(
      $baselineReconciledPartialR5.setup.checks | Where-Object {-not $_.valid})
  Add-SelfCase 'baseline_R5_reconciled_stat_runtime_partial_d7_retryable' `
      (-not $baselineReconciledPartialR5.setup.valid -and
       $baselineReconciledPartialR5Failed.Count -eq 1 -and
       $baselineReconciledPartialR5Failed[0].name -ceq
         'vehicle_generic_param_fifo_empty' -and
       $baselineReconciledPartialR5Exact -and
       $baselineReconciledPartialR5.disposition.action -ceq 'RETRY' -and
       $baselineReconciledPartialR5.disposition.reason -ceq
         'known_stat_runtime_reconciled_partial_d7_baseline_race' -and
       $baselineReconciledPartialR5.disposition.retry_eligible -and
       $baselineReconciledPartialR5.disposition.fixture_write_count -eq 0) `
      'R5 exact d722/rf22/pvok +1, pgq=1 and d7pb=4 shape authorizes only full-pair reacquisition'

  [bool]$baselineReconciledPartialBoundsValid = $true
  foreach ($d7pbBound in @([uint64]1,[uint64]279)) {
    $boundedEvaluation = & $evaluateVehicleAheadBaseline `
        -CurrentVehicleOverrides @{d7pb=$d7pbBound} `
        -CurrentGroundOverrides @{rf22=[uint64]23}
    $boundedProperty = $boundedEvaluation.setup.PSObject.Properties[
        'known_stat_runtime_reconciled_partial_d7_race']
    if ($null -eq $boundedProperty -or $null -eq $boundedProperty.Value -or
        -not [bool]$boundedProperty.Value.valid -or
        $boundedEvaluation.disposition.action -cne 'RETRY') {
      $baselineReconciledPartialBoundsValid = $false
    }
  }
  Add-SelfCase 'baseline_reconciled_stat_runtime_partial_d7_bounds_1_279_retryable' `
      $baselineReconciledPartialBoundsValid `
      'both partial-frame boundaries remain RETRY-only under the exact reconciled R5 envelope'

  $baselineReconciledPartialTooLarge = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]280} `
      -CurrentGroundOverrides @{rf22=[uint64]23}
  $baselineReconciledPartialPreviousBusy = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]4} `
      -PreviousVehicleOverrides @{d7pb=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23}
  $baselineReconciledPartialCrcChanged = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]4;d7cr=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23}
  $baselineReconciledPartialTupleChanged = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]4;pvid='STAT_OTHER'} `
      -CurrentGroundOverrides @{rf22=[uint64]23}
  Add-SelfCase 'baseline_reconciled_stat_runtime_partial_d7_nonexact_not_retryable' `
      (@($baselineReconciledPartialTooLarge,
          $baselineReconciledPartialPreviousBusy,
          $baselineReconciledPartialCrcChanged,
          $baselineReconciledPartialTupleChanged | Where-Object {
            $_.disposition.action -cne 'REJECT' -or
            $_.disposition.retry_eligible}).Count -eq 0) `
      'd7pb overflow, prior partial state, CRC change, or tuple change remains fail-closed'

  $baselineReconciledPartialNoBudget = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]4} `
      -CurrentGroundOverrides @{rf22=[uint64]23} `
      -AttemptNumber 1 -RetryBudgetAvailable $false
  $baselineReconciledPartialExhausted = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]4} `
      -CurrentGroundOverrides @{rf22=[uint64]23} `
      -AttemptNumber 3 -RetryBudgetAvailable $true
  Add-SelfCase 'baseline_reconciled_stat_runtime_partial_d7_retry_bounded_write0' `
      ($baselineReconciledPartialNoBudget.disposition.action -ceq 'REJECT' -and
       $baselineReconciledPartialNoBudget.disposition.reason -ceq
         'shared_deadline_exhausted' -and
       $baselineReconciledPartialExhausted.disposition.action -ceq 'REJECT' -and
       $baselineReconciledPartialExhausted.disposition.retry_exhausted -and
       ([int]$baselineReconciledPartialNoBudget.disposition.fixture_write_count +
        [int]$baselineReconciledPartialExhausted.disposition.fixture_write_count) -eq 0) `
      'the R5 retry cannot extend the shared deadline, exceed three attempts, or write the fixture'

  $baselineReconciledPartialCleanVehicleFields =
      $baselineSentinelPreviousVehicleFields.Clone()
  $baselineReconciledPartialCleanVehicleFields['d722'] = [uint64]23
  $baselineReconciledPartialCleanVehicleFields['pvok'] = [uint64]23
  $baselineReconciledPartialCleanVehicleFields['pvms'] = [uint64]4294981500
  $baselineReconciledPartialCleanVehicleFields['pgq'] = [uint64]0
  $baselineReconciledPartialCleanVehicleFields['d7pb'] = [uint64]0
  $baselineReconciledPartialCleanGroundFields = $baselineDrainGroundFields.Clone()
  $baselineReconciledPartialCleanGroundFields['rf22'] = [uint64]23
  $baselineReconciledPartialCleanVehicle = New-OfflineSnapshot `
      -Fields $baselineReconciledPartialCleanVehicleFields -Q 12 `
      -Ms ([uint64]4294983000)
  $baselineReconciledPartialCleanGround = New-OfflineSnapshot `
      -Fields $baselineReconciledPartialCleanGroundFields -Q 22 `
      -Ms ([uint64]4294983001)
  $baselineReconciledPartialCleanSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineReconciledPartialCleanGround `
      -VehicleSnapshot $baselineReconciledPartialCleanVehicle `
      -PreviousGroundSnapshot $baselineReconciledPartialR5.current_ground `
      -PreviousVehicleSnapshot $baselineReconciledPartialR5.current_vehicle
  $baselineReconciledPartialCleanDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineReconciledPartialCleanSetup -AttemptNumber 2 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'baseline_reconciled_partial_retry_then_clean_pair_pass' `
      ($baselineReconciledPartialR5.disposition.action -ceq 'RETRY' -and
       $baselineReconciledPartialCleanSetup.valid -and
       $baselineReconciledPartialCleanDisposition.action -ceq 'ACCEPT' -and
       ([int]$baselineReconciledPartialR5.disposition.fixture_write_count +
        [int]$baselineReconciledPartialCleanDisposition.fixture_write_count) -eq 0) `
      'the partial snapshot is never accepted; only a later complete clean pair may become baseline'

  # R1 captured the same reconciled periodic response with its single generic
  # lane entry still active (pgq=1,pga=1) and 33 bytes of the following D7
  # frame buffered.  It is a RETRY-only observer shape, never a baseline.
  $baselineR1ActivePartial = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23}
  $baselineR1ActivePartialProperty =
      $baselineR1ActivePartial.setup.PSObject.Properties[
        'known_stat_runtime_active_reconciled_partial_d7_race']
  $baselineR1ActivePartialFailed = @(
      $baselineR1ActivePartial.setup.checks | Where-Object {-not $_.valid})
  [bool]$baselineR1BoundaryChecksExact = $true
  foreach ($boundaryCheckName in @(
      'known_stat_runtime_active_reconciled_partial_previous_pga_empty',
      'known_stat_runtime_active_reconciled_partial_pga_one',
      'known_stat_runtime_active_reconciled_partial_previous_d7pb_empty',
      'known_stat_runtime_active_reconciled_partial_current_d7pb_bounded',
      'known_stat_runtime_active_reconciled_partial_d7cr_delta_zero',
      'known_stat_runtime_active_reconciled_partial_previous_reconciled',
      'known_stat_runtime_active_reconciled_partial_vehicle_q_next',
      'known_stat_runtime_active_reconciled_partial_ground_q_next',
      'known_stat_runtime_active_reconciled_partial_vehicle_ms_increased',
      'known_stat_runtime_active_reconciled_partial_ground_ms_increased',
      'known_stat_runtime_active_reconciled_partial_related_drop_error_zero')) {
    $matchingBoundaryChecks = @(
        $baselineR1ActivePartialProperty.Value.checks | Where-Object {
          [string]$_.name -ceq $boundaryCheckName
        })
    if ($matchingBoundaryChecks.Count -ne 1 -or
        -not [bool]$matchingBoundaryChecks[0].valid) {
      $baselineR1BoundaryChecksExact = $false
    }
  }
  Add-SelfCase 'baseline_R1_reconciled_stat_runtime_active_partial_d7_retryable' `
      (-not $baselineR1ActivePartial.setup.valid -and
       $baselineR1ActivePartialFailed.Count -eq 2 -and
       $baselineR1ActivePartialFailed.name -ccontains
         'vehicle_generic_param_fifo_empty' -and
       $baselineR1ActivePartialFailed.name -ccontains
         'vehicle_generic_param_inactive' -and
       $null -ne $baselineR1ActivePartialProperty -and
       $null -ne $baselineR1ActivePartialProperty.Value -and
       [bool]$baselineR1ActivePartialProperty.Value.valid -and
       [string]$baselineR1ActivePartialProperty.Value.classification -ceq
         'exact_known_STAT_RUNTIME_active_reconciled_partial_D7_baseline_race' -and
       $baselineR1BoundaryChecksExact -and
       $baselineR1ActivePartial.disposition.action -ceq 'RETRY' -and
       $baselineR1ActivePartial.disposition.reason -ceq
         'known_stat_runtime_active_reconciled_partial_d7_baseline_race' -and
       $baselineR1ActivePartial.disposition.retry_eligible -and
       $baselineR1ActivePartial.disposition.fixture_write_count -eq 0) `
      'R1 exact reconciled STAT_RUNTIME with pgq/pga=1 and d7pb=33 remains invalid and authorizes only another complete pair'

  [object[]]$baselineR1ReversedChecks = [object[]]@(
      $baselineR1ActivePartial.setup.checks)
  [array]::Reverse($baselineR1ReversedChecks)
  $baselineR1ReorderedSetup = $baselineR1ActivePartial.setup.PSObject.Copy()
  $baselineR1ReorderedSetup.checks = $baselineR1ReversedChecks
  $baselineR1ReorderedDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineR1ReorderedSetup -AttemptNumber 1 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'baseline_R1_active_partial_failure_set_order_independent' `
      ($baselineR1ReorderedDisposition.action -ceq 'RETRY' -and
       $baselineR1ReorderedDisposition.retry_eligible -and
       $baselineR1ReorderedDisposition.exact_active_reconciled_partial_failure_set -and
       $baselineR1ReorderedDisposition.failed_check_count -eq 2) `
      'the exact pgq/pga two-name failure set is order-independent and cannot hide a third failure'

  $baselineR1PgaTwo = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]2} `
      -CurrentGroundOverrides @{rf22=[uint64]23}
  $baselineR5ActiveProperty =
      $baselineReconciledPartialR5.setup.PSObject.Properties[
        'known_stat_runtime_active_reconciled_partial_d7_race']
  Add-SelfCase 'baseline_R1_active_partial_pga_exact_one_and_pga0_route_preserved' `
      ($baselineReconciledPartialR5.disposition.action -ceq 'RETRY' -and
       $baselineReconciledPartialR5.disposition.reason -ceq
         'known_stat_runtime_reconciled_partial_d7_baseline_race' -and
       $baselineReconciledPartialR5.setup.known_stat_runtime_reconciled_partial_d7_race.valid -and
       $null -ne $baselineR5ActiveProperty -and
       -not [bool]$baselineR5ActiveProperty.Value.valid -and
       $baselineR1PgaTwo.disposition.action -ceq 'REJECT' -and
       -not $baselineR1PgaTwo.disposition.retry_eligible) `
      'pga=0 retains the unchanged R5 route, pga=1 uses only the R1 route, and pga=2 is rejected'

  $baselineR1NonexactEvaluations = @(
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]0;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]280;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -PreviousVehicleOverrides @{d7pb=[uint64]1} `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -PreviousVehicleOverrides @{pga=[uint64]1} `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1;d7cr=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1;pvid='STAT_OTHER'} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1;pgq=[uint64]2} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1;prq=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1;d722=[uint64]24} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1;pvok=[uint64]24} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -PreviousVehicleOverrides @{d722=[uint64]21} `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23} -CurrentVehicleQ 12),
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23} `
      -CurrentGroundMs ([uint64]4294981001)),
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1;ef=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1;boot=[uint64]95} `
      -CurrentGroundOverrides @{rf22=[uint64]23}),
    (& $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23;obdf=[uint64]1})
  )
  Add-SelfCase 'baseline_R1_active_partial_nonexact_not_retryable' `
      (@($baselineR1NonexactEvaluations | Where-Object {
            $_.disposition.action -cne 'REJECT' -or
            $_.disposition.retry_eligible
          }).Count -eq 0) `
      'bounds, prior idle, CRC, tuple, queue, counters, q/ms, boot, discard, and error predicates all fail closed'

  $baselineR1Attempt1 = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23} `
      -AttemptNumber 1 -RetryBudgetAvailable $true
  $baselineR1Attempt2 = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23} `
      -AttemptNumber 2 -RetryBudgetAvailable $true
  $baselineR1NoBudget = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23} `
      -AttemptNumber 1 -RetryBudgetAvailable $false
  $baselineR1Exhausted = & $evaluateVehicleAheadBaseline `
      -CurrentVehicleOverrides @{d7pb=[uint64]33;pga=[uint64]1} `
      -CurrentGroundOverrides @{rf22=[uint64]23} `
      -AttemptNumber 3 -RetryBudgetAvailable $true
  Add-SelfCase 'baseline_R1_active_partial_retry_bounded_write0' `
      ($baselineR1Attempt1.disposition.action -ceq 'RETRY' -and
       $baselineR1Attempt2.disposition.action -ceq 'RETRY' -and
       $baselineR1NoBudget.disposition.action -ceq 'REJECT' -and
       $baselineR1NoBudget.disposition.reason -ceq
         'shared_deadline_exhausted' -and
       $baselineR1Exhausted.disposition.action -ceq 'REJECT' -and
       $baselineR1Exhausted.disposition.retry_exhausted -and
       ([int]$baselineR1Attempt1.disposition.fixture_write_count +
        [int]$baselineR1Attempt2.disposition.fixture_write_count +
        [int]$baselineR1NoBudget.disposition.fixture_write_count +
        [int]$baselineR1Exhausted.disposition.fixture_write_count) -eq 0) `
      'R1 may retry only before attempt three and inside the existing shared deadline, with fixture write0'

  $baselineR1CleanVehicleFields =
      $baselineSentinelPreviousVehicleFields.Clone()
  $baselineR1CleanVehicleFields['d722'] = [uint64]23
  $baselineR1CleanVehicleFields['pvok'] = [uint64]23
  $baselineR1CleanVehicleFields['pvms'] = [uint64]4294981500
  $baselineR1CleanVehicleFields['pgq'] = [uint64]0
  $baselineR1CleanVehicleFields['pga'] = [uint64]0
  $baselineR1CleanVehicleFields['d7pb'] = [uint64]0
  $baselineR1CleanGroundFields = $baselineDrainGroundFields.Clone()
  $baselineR1CleanGroundFields['rf22'] = [uint64]23
  $baselineR1CleanVehicle = New-OfflineSnapshot `
      -Fields $baselineR1CleanVehicleFields -Q 12 -Ms ([uint64]4294983000)
  $baselineR1CleanGround = New-OfflineSnapshot `
      -Fields $baselineR1CleanGroundFields -Q 22 -Ms ([uint64]4294983001)
  $baselineR1CleanSetup = Test-BaselineSetup `
      -GroundSnapshot $baselineR1CleanGround `
      -VehicleSnapshot $baselineR1CleanVehicle `
      -PreviousGroundSnapshot $baselineR1ActivePartial.current_ground `
      -PreviousVehicleSnapshot $baselineR1ActivePartial.current_vehicle
  $baselineR1CleanDisposition = Get-BaselineAttemptDisposition `
      -BaselineSetup $baselineR1CleanSetup -AttemptNumber 2 `
      -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'baseline_R1_active_partial_retry_then_clean_pair_pass' `
      ($baselineR1ActivePartial.disposition.action -ceq 'RETRY' -and
       -not $baselineR1ActivePartial.setup.valid -and
       $baselineR1CleanSetup.valid -and
       $baselineR1CleanDisposition.action -ceq 'ACCEPT' -and
       $baselineR1CleanVehicle.q_uint32 -eq 12 -and
       $baselineR1CleanGround.q_uint32 -eq 22 -and
       ([int]$baselineR1ActivePartial.disposition.fixture_write_count +
        [int]$baselineR1CleanDisposition.fixture_write_count) -eq 0) `
      'the R1 snapshot is never accepted; only the next full clean pair becomes the baseline'

  # R3 captured the earlier, empty-parser Vehicle-ahead instant.  Keep d7pb=0
  # explicit in every fixture so the established 1..279 classifier remains an
  # independently exercised route.
  $evaluateVehicleAheadEmptyD7Baseline = {
    param(
      [hashtable]$CurrentVehicleOverrides = @{},
      [hashtable]$PreviousVehicleOverrides = @{},
      [hashtable]$CurrentGroundOverrides = @{},
      [hashtable]$PreviousGroundOverrides = @{},
      [int]$AttemptNumber = 1,
      [bool]$RetryBudgetAvailable = $true,
      [uint32]$PreviousVehicleQ = 10,
