      [uint64]$CurrentVehicleMs = 4294982000,
      [uint64]$PreviousGroundMs = 4294981001,
      [uint64]$CurrentGroundMs = 4294982001
    )
    $emptyCurrentOverrides = @{d7pb=[uint64]0}
    foreach ($entry in $CurrentVehicleOverrides.GetEnumerator()) {
      $emptyCurrentOverrides[$entry.Key] = $entry.Value
    }
    return & $evaluateVehicleAheadBaseline `
        -CurrentVehicleOverrides $emptyCurrentOverrides `
        -PreviousVehicleOverrides $PreviousVehicleOverrides `
        -CurrentGroundOverrides $CurrentGroundOverrides `
        -PreviousGroundOverrides $PreviousGroundOverrides `
        -AttemptNumber $AttemptNumber `
        -RetryBudgetAvailable $RetryBudgetAvailable `
        -PreviousVehicleQ $PreviousVehicleQ `
        -CurrentVehicleQ $CurrentVehicleQ `
        -PreviousGroundQ $PreviousGroundQ `
        -CurrentGroundQ $CurrentGroundQ `
        -PreviousVehicleMs $PreviousVehicleMs `
        -CurrentVehicleMs $CurrentVehicleMs `
        -PreviousGroundMs $PreviousGroundMs `
        -CurrentGroundMs $CurrentGroundMs
  }

  $baselineR3VehicleAheadEmpty = & $evaluateVehicleAheadEmptyD7Baseline `
