  $baselineR3Observer =
      $baselineR3VehicleAheadEmpty.setup.PSObject.Properties[
        'known_stat_runtime_vehicle_ahead_empty_d7_race']
  [bool]$baselineR3DedicatedChecksExact = $true
  foreach ($dedicatedCheckName in @(
