  $baselineR3ReorderedSetup = $baselineR3VehicleAheadEmpty.setup.PSObject.Copy()
  $baselineR3ReorderedSetup.checks = $baselineR3ReversedChecks
  $baselineR3ReorderedDisposition = Get-BaselineAttemptDisposition `
