    if ($baselineR3Negative.disposition.action -cne 'REJECT' -or
        $baselineR3Negative.disposition.retry_eligible -or
        ($baselineR3NegativeIndex -notin
           $baselineR3EnvelopeOnlyNegativeIndexes -and
         $baselineR3Negative.setup.known_stat_runtime_vehicle_ahead_empty_d7_race.valid)) {
