      $baselineSharedDeadline,$baselineSharedDeadline,$baselineSharedDeadline)
  Add-SelfCase 'baseline_retry_shared_deadline_no_extension' `
      (-not $baselineNoPairBudget.can_query -and
       $baselineNoDeadlineDisposition.action -ceq 'REJECT' -and
       $baselineNoDeadlineDisposition.reason -ceq 'shared_deadline_exhausted' -and
       @($modeledBaselineDeadlines | Where-Object {
         $_ -ne $baselineSharedDeadline}).Count -eq 0) `
      'all attempts share the backlog absolute deadline and no pair starts without Ground reserve'
  $shortObservation = Test-BacklogDrainObservation `
      -GroundSnapshot $cleanGroundC -VehicleSnapshot $cleanVehicleC `
      -ObservedElapsedMs 11999
  $tooShortPair = Test-BacklogDrainStablePair `
      -FirstObservation $cleanObservationB -SecondObservation $shortObservation
  Add-SelfCase 'backlog_drain_two_observations_5s' `
      ($twoCleanStable.valid -and -not $tooShortPair.valid -and
       $twoCleanStable.passive_separation_ms -ge 5000) `
      'two clean observations require at least 5s passive separation, above the 550ms service floor'
  $drainTimeoutModel = [pscustomobject][ordered]@{
    valid=$false;timed_out=$true;status='FAIL';exit_code=1
    open_counts=[ordered]@{vehicle=1;ground=1};request_write_count=0
  }
  Add-SelfCase 'backlog_drain_timeout_write0' `
      (-not $drainTimeoutModel.valid -and $drainTimeoutModel.timed_out -and
       $drainTimeoutModel.status -eq 'FAIL' -and
       $drainTimeoutModel.exit_code -eq 1 -and
       $drainTimeoutModel.open_counts.vehicle -eq 1 -and
       $drainTimeoutModel.open_counts.ground -eq 1 -and
       $drainTimeoutModel.request_write_count -eq 0) `
      'never-drained backlog is setup-invalid FAIL/1 with handles open once and write0'

  $preRequestVehicleClean = New-OfflineSnapshot -Fields $vehicleBaseFields `
      -Q 2 -Ms ([uint64]4294973297)
  $preRequestGateClean = Test-PreRequestVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $preRequestVehicleClean
  Add-SelfCase 'pre_request_vehicle_clean_pass' $preRequestGateClean.valid `
      'M0-tail Vehicle recheck is q+1/same boot/d722 stable/reconciled with scheduler occupancy zero'
  $bootChangedFields = $vehicleBaseFields.Clone();$bootChangedFields['boot']=95
  $bootChangedVehicle = New-OfflineSnapshot -Fields $bootChangedFields -Q 2 `
      -Ms ([uint64]4294973297)
  Add-SelfCase 'pre_request_vehicle_boot_change_rejected' `
      (-not (Test-PreRequestVehicleGate `
        -OfficialVehicle $offlineBaselineVehicle `
        -OfficialGround $offlineBaselineGround `
        -PreRequestVehicle $bootChangedVehicle).valid) `
      'M0-tail Vehicle boot change suppresses request'
  $d722IncreasedFields = $vehicleBaseFields.Clone();$d722IncreasedFields['d722']=1
  $d722IncreasedVehicle = New-OfflineSnapshot -Fields $d722IncreasedFields `
      -Q 2 -Ms ([uint64]4294973297)
  Add-SelfCase 'pre_request_vehicle_d722_increase_rejected' `
      (-not (Test-PreRequestVehicleGate `
        -OfficialVehicle $offlineBaselineVehicle `
        -OfficialGround $offlineBaselineGround `
        -PreRequestVehicle $d722IncreasedVehicle).valid) `
      'late Vehicle PARAM_VALUE observation suppresses request'
  $groundReconcileFields = $groundBaseFields.Clone();$groundReconcileFields['rf22']=1
  $groundReconcileSnapshot = New-OfflineSnapshot -Fields $groundReconcileFields `
      -Q 1 -Ms ([uint64]4294967296)
  Add-SelfCase 'pre_request_vehicle_reconciliation_rejected' `
      (-not (Test-PreRequestVehicleGate `
        -OfficialVehicle $offlineBaselineVehicle `
        -OfficialGround $groundReconcileSnapshot `
        -PreRequestVehicle $preRequestVehicleClean).valid) `
      'M0-tail Vehicle d722 must still reconcile with official Ground rf22'
  $preQueueFields = $vehicleBaseFields.Clone();$preQueueFields['pgq']=1
  $preQueueVehicle = New-OfflineSnapshot -Fields $preQueueFields -Q 2 `
      -Ms ([uint64]4294973297)
  Add-SelfCase 'pre_request_vehicle_queue_nonzero_rejected' `
      (-not (Test-PreRequestVehicleGate `
        -OfficialVehicle $offlineBaselineVehicle `
        -OfficialGround $offlineBaselineGround `
        -PreRequestVehicle $preQueueVehicle).valid) `
      'M0-tail generic PARAM scheduler occupancy suppresses request'
  $preD7pbFields = $vehicleBaseFields.Clone();$preD7pbFields['d7pb']=1
  $preD7pbVehicle = New-OfflineSnapshot -Fields $preD7pbFields -Q 2 `
      -Ms ([uint64]4294973297)
  $preD7pbGate = Test-PreRequestVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $preD7pbVehicle
  Add-SelfCase 'pre_request_vehicle_d7pb_nonzero_rejected' `
      (-not $preD7pbGate.valid -and
       @($preD7pbGate.checks | Where-Object {
         $_.name -ceq 'd7pb_empty' -and -not $_.valid}).Count -eq 1) `
      'the final request authorization gate requires an empty Vehicle D7 parser'
  $sentinelVehicleFields = $vehicleBaseFields.Clone()
  $sentinelVehicleFields['d722'] = 1
  $sentinelVehicleFields['pgq'] = 1
  $sentinelVehicleFields['pvid'] = 'STAT_RUNTIME'
  $sentinelVehicleFields['pvidx'] = 65535
  $sentinelVehicleFields['pvcnt'] = 932
  $sentinelVehicleFields['pvtype'] = 6
  $sentinelVehicle = New-OfflineSnapshot -Fields $sentinelVehicleFields `
      -Q 2 -Ms ([uint64]4294973297)
  $sentinelVehicleGate = Test-PreRequestVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle
  $sentinelState = New-ParamListState -CaptureScope 'pre_request_m0'
  [byte[]]$retrySentinelPayload = New-ParamValuePayload `
      -ParamId 'STAT_RUNTIME' -Index 65535 -Count 932 -Type 6
  Add-ParamValuePayload -State $sentinelState -Payload $retrySentinelPayload `
      -SystemId 1 -ComponentId 1 -Sequence 22 -ElapsedMs 5000
  $sentinelCausalGate = [pscustomobject][ordered]@{
    valid=$false;parser_integrity=[pscustomobject]@{valid=$true}
    heartbeat=[pscustomobject]@{valid=$true;count=6}
    pre_request_backlog_gate=[pscustomobject]@{
      m0_epoch_completed=$true;m0_veto_events=$sentinelState.events.ToArray()
    }
  }
  $sentinelDisposition = Get-PreRequestAttemptDisposition `
      -CausalGate $sentinelCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle `
      -M0Events $sentinelState.events.ToArray() `
      -AttemptNumber 1 -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'pre_request_exact_stat_runtime_retryable' `
      ($sentinelDisposition.action -ceq 'RETRY' -and
       $sentinelDisposition.retry_eligible -and
       $sentinelDisposition.observer_exact -and
       $sentinelDisposition.fixture_write_count -eq 0) `
      'one exact STAT_RUNTIME sentinel with matching d722/pgq observer evidence triggers reacquisition, never acceptance'
  $indexedM0Event = [pscustomobject][ordered]@{
    classification='indexed';anomaly_classes=@();system_id=1;component_id=1
    param_id='P0000';param_id_hex='50303030300000000000000000000000'
    param_index=0;param_count=932;param_type=6
  }
  $indexedDisposition = Get-PreRequestAttemptDisposition `
      -CausalGate $sentinelCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle -M0Events @($indexedM0Event) `
      -AttemptNumber 1 -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'pre_request_unknown_or_indexed_not_retryable' `
      ($indexedDisposition.action -ceq 'REJECT' -and
       -not $indexedDisposition.retry_eligible -and
       $indexedDisposition.unknown_or_indexed_count -eq 1) `
      'indexed or unknown M0 PARAM_VALUE remains a hard veto'
  $parserBadCausalGate = $sentinelCausalGate.PSObject.Copy()
  $parserBadCausalGate.parser_integrity = [pscustomobject]@{valid=$false}
  $heartbeatBadCausalGate = $sentinelCausalGate.PSObject.Copy()
  $heartbeatBadCausalGate.heartbeat = [pscustomobject]@{valid=$false;count=1}
  $parserBadDisposition = Get-PreRequestAttemptDisposition `
      -CausalGate $parserBadCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle `
      -M0Events $sentinelState.events.ToArray() `
      -AttemptNumber 1 -MaxAttempts 3 -RetryBudgetAvailable $true
  $heartbeatBadDisposition = Get-PreRequestAttemptDisposition `
      -CausalGate $heartbeatBadCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle `
      -M0Events $sentinelState.events.ToArray() `
      -AttemptNumber 1 -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'pre_request_stat_runtime_plus_parser_or_hb_failure_not_retryable' `
      ($parserBadDisposition.action -ceq 'REJECT' -and
       $heartbeatBadDisposition.action -ceq 'REJECT') `
      'the known sentinel does not mask parser integrity or Heartbeat faults'
  $cleanCausalGate = [pscustomobject][ordered]@{
    valid=$true;parser_integrity=[pscustomobject]@{valid=$true}
    heartbeat=[pscustomobject]@{valid=$true;count=6}
    pre_request_backlog_gate=[pscustomobject]@{
      m0_epoch_completed=$true;m0_veto_events=@()
    }
  }
  $cleanDisposition = Get-PreRequestAttemptDisposition `
      -CausalGate $cleanCausalGate `
      -PreRequestVehicleGate $preRequestGateClean `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $preRequestVehicleClean -M0Events @() `
      -AttemptNumber 2 -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'pre_request_stat_runtime_retry_then_clean_pass' `
      ($sentinelDisposition.action -ceq 'RETRY' -and
       $cleanDisposition.action -ceq 'ACCEPT') `
      'an exact sentinel attempt is discarded and only a newly clean M0 can pass'
  $sentinelExhaustedDisposition = Get-PreRequestAttemptDisposition `
      -CausalGate $sentinelCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle `
      -M0Events $sentinelState.events.ToArray() `
      -AttemptNumber 3 -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'pre_request_stat_runtime_retry_exhausted_write0' `
      ($sentinelExhaustedDisposition.action -ceq 'REJECT' -and
       $sentinelExhaustedDisposition.retry_exhausted -and
       $sentinelExhaustedDisposition.fixture_write_count -eq 0) `
      'three epochs exhaust retry budget with request write zero'
  $sentinelDeadlineDisposition = Get-PreRequestAttemptDisposition `
      -CausalGate $sentinelCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle `
      -M0Events $sentinelState.events.ToArray() `
      -AttemptNumber 1 -MaxAttempts 3 -RetryBudgetAvailable $false
  Add-SelfCase 'pre_request_retry_shared_deadline_no_extension' `
      ($sentinelDeadlineDisposition.action -ceq 'REJECT' -and
       $sentinelDeadlineDisposition.reason -ceq 'shared_deadline_exhausted' -and
       $sentinelDeadlineDisposition.fixture_write_count -eq 0) `
      'the original backlog deadline cannot be extended for a sentinel retry'
  Add-SelfCase 'pre_request_stat_runtime_retry_fixture0_until_clean' `
      ($sentinelDisposition.fixture_write_count -eq 0 -and
       $cleanDisposition.fixture_write_count -eq 0 -and
       $sentinelDisposition.action -ceq 'RETRY' -and
       $cleanDisposition.action -ceq 'ACCEPT') `
      'all work inside the bounded gate remains write-zero; the sole fixture writer stays outside final ACCEPT'

  # R3 attempt 3 observed a COMPLETE Vehicle diagnostic whose only failed
  # authorization check was d7pb_empty (0 -> 3 bytes).  All product scheduler,
  # PARAM observer, parser/error, and bilateral reconciliation evidence stayed
  # exact while the D7 stream advanced.  Model that measured shape directly;
  # it may request one extra full gate epoch, but can never authorize a write.
  $isolatedD7OfficialVehicleFields = $vehicleBaseFields.Clone()
  foreach ($isolatedField in @{
      d722=[uint64]3;pvok=[uint64]3;pvs1=[uint64]0
      pvid='STAT_RUNTIME';pvval='4962FD10';pvidx=[uint64]65535
      pvcnt=[uint64]932;pvtype=[uint64]6;pvseq=[uint64]147
      pvsys=[uint64]1;pvcomp=[uint64]1;pvms=[uint64]82288
      d7b=[uint64]500000;d7f=[uint64]1000;d7iv=[uint64]10
      d7pb=[uint64]0;d6cr=[uint64]0;d7cr=[uint64]0
    }.GetEnumerator()) {
    $isolatedD7OfficialVehicleFields[$isolatedField.Key] = $isolatedField.Value
  }
  $isolatedD7CurrentVehicleFields =
      $isolatedD7OfficialVehicleFields.Clone()
  $isolatedD7CurrentVehicleFields['d7pb'] = [uint64]3
  $isolatedD7CurrentVehicleFields['d7b'] = [uint64]508199
  $isolatedD7CurrentVehicleFields['d7f'] = [uint64]1142
  $isolatedD7CurrentVehicleFields['d7iv'] = [uint64]123
  $isolatedD7OfficialGroundFields = $groundBaseFields.Clone()
  $isolatedD7OfficialGroundFields['rf22'] = [uint64]3

  $evaluateIsolatedD7Race = {
    param(
      [hashtable]$CurrentOverrides = @{},
      [hashtable]$OfficialVehicleOverrides = @{},
      [hashtable]$OfficialGroundOverrides = @{},
      [hashtable]$CausalOverrides = @{},
      [AllowEmptyCollection()][object[]]$Events = @(),
      [int]$AttemptNumber = 3,
      [int]$DispositionMaxAttempts = 3,
      [bool]$RetryBudgetAvailable = $true,
      [bool]$ExtraRetryAvailable = $true,
      [string]$OfficialVehicleStatus = 'COMPLETE',
      [string]$OfficialGroundStatus = 'COMPLETE',
      [string]$CurrentVehicleStatus = 'COMPLETE'
    )
    $officialFields = $isolatedD7OfficialVehicleFields.Clone()
    foreach ($key in $OfficialVehicleOverrides.Keys) {
      $officialFields[$key] = $OfficialVehicleOverrides[$key]
    }
    $groundFields = $isolatedD7OfficialGroundFields.Clone()
    foreach ($key in $OfficialGroundOverrides.Keys) {
      $groundFields[$key] = $OfficialGroundOverrides[$key]
    }
    $currentFields = $isolatedD7CurrentVehicleFields.Clone()
    foreach ($key in $CurrentOverrides.Keys) {
      $currentFields[$key] = $CurrentOverrides[$key]
    }
    $officialVehicle = New-OfflineSnapshot -Fields $officialFields `
        -Q 70 -Ms ([uint64]99834)
    $officialGround = New-OfflineSnapshot -Fields $groundFields `
        -Q 80 -Ms ([uint64]99835)
    $currentVehicle = New-OfflineSnapshot -Fields $currentFields `
        -Q 71 -Ms ([uint64]107626)
    $officialVehicle.status = $OfficialVehicleStatus
    $officialGround.status = $OfficialGroundStatus
    $currentVehicle.status = $CurrentVehicleStatus
    [bool]$causalValid = $true
    [bool]$m0Completed = $true
    [bool]$parserValid = $true
    [bool]$heartbeatValid = $true
    [int]$heartbeatCount = 7
    if ($CausalOverrides.ContainsKey('valid')) {
      $causalValid = [bool]$CausalOverrides['valid']
    }
    if ($CausalOverrides.ContainsKey('m0_epoch_completed')) {
      $m0Completed = [bool]$CausalOverrides['m0_epoch_completed']
    }
    if ($CausalOverrides.ContainsKey('parser_valid')) {
      $parserValid = [bool]$CausalOverrides['parser_valid']
    }
    if ($CausalOverrides.ContainsKey('heartbeat_valid')) {
      $heartbeatValid = [bool]$CausalOverrides['heartbeat_valid']
    }
    if ($CausalOverrides.ContainsKey('heartbeat_count')) {
      $heartbeatCount = [int]$CausalOverrides['heartbeat_count']
    }
    $causal = [pscustomobject][ordered]@{
      valid=$causalValid
      parser_integrity=[pscustomobject]@{valid=$parserValid}
      heartbeat=[pscustomobject]@{
        valid=$heartbeatValid;count=$heartbeatCount;max_interval_ms=2198.506
      }
      pre_request_backlog_gate=[pscustomobject]@{
        m0_epoch_completed=$m0Completed;m0_veto_events=$Events
      }
    }
    $vehicleGate = Test-PreRequestVehicleGate `
        -OfficialVehicle $officialVehicle -OfficialGround $officialGround `
        -PreRequestVehicle $currentVehicle
    $race = Test-IsolatedPartialD7SnapshotRaceContract `
        -CausalGate $causal -PreRequestVehicleGate $vehicleGate `
        -OfficialVehicle $officialVehicle -OfficialGround $officialGround `
        -PreRequestVehicle $currentVehicle -M0Events $Events
    $disposition = Get-PreRequestAttemptDisposition `
        -CausalGate $causal -PreRequestVehicleGate $vehicleGate `
        -OfficialVehicle $officialVehicle -OfficialGround $officialGround `
        -PreRequestVehicle $currentVehicle -M0Events $Events `
        -AttemptNumber $AttemptNumber -MaxAttempts $DispositionMaxAttempts `
        -RetryBudgetAvailable $RetryBudgetAvailable `
        -IsolatedPartialD7ExtraRetryAvailable $ExtraRetryAvailable
    return [pscustomobject][ordered]@{
      official_vehicle=$officialVehicle;official_ground=$officialGround
      current_vehicle=$currentVehicle;causal_gate=$causal
      vehicle_gate=$vehicleGate;race=$race;disposition=$disposition
      fixture_write_count=0
    }
  }

  $isolatedD7ExactAttempt3 = & $evaluateIsolatedD7Race
  Add-SelfCase 'pre_request_isolated_partial_d7_attempt3_arms_extra_write0' `
      ($isolatedD7ExactAttempt3.race.valid -and
       -not $isolatedD7ExactAttempt3.vehicle_gate.valid -and
       @($isolatedD7ExactAttempt3.vehicle_gate.checks | Where-Object {
         -not $_.valid -and $_.name -ceq 'd7pb_empty'
       }).Count -eq 1 -and
       $isolatedD7ExactAttempt3.disposition.action -ceq
         'RETRY_ISOLATED_D7PB' -and
       $isolatedD7ExactAttempt3.disposition.reason -ceq
         'exact_isolated_partial_D7_snapshot_race' -and
       $isolatedD7ExactAttempt3.disposition.retry_eligible -and
       $isolatedD7ExactAttempt3.disposition.
         isolated_partial_d7_extra_retry_selected -and
       $isolatedD7ExactAttempt3.disposition.fixture_write_count -eq 0) `
      'only the exact measured attempt-3 shadow race selects one write-zero dedicated recovery'

  $isolatedD7AtOne = & $evaluateIsolatedD7Race `
      -CurrentOverrides @{d7pb=[uint64]1}
  $isolatedD7At279 = & $evaluateIsolatedD7Race `
      -CurrentOverrides @{d7pb=[uint64]279}
  $isolatedD7AtZero = & $evaluateIsolatedD7Race `
      -CurrentOverrides @{d7pb=[uint64]0}
  $isolatedD7At280 = & $evaluateIsolatedD7Race `
      -CurrentOverrides @{d7pb=[uint64]280}
  [bool]$isolatedD7NegativeMatrixRejected = $true
  [object[]]$isolatedD7NegativeMatrix = [object[]]@(
      (& $evaluateIsolatedD7Race -CurrentOverrides @{boot=[uint64]220}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{d722=[uint64]4}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvok=[uint64]4}),
      (& $evaluateIsolatedD7Race -OfficialGroundOverrides @{rf22=[uint64]4}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvid='OTHER'}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvval='DEADBEEF'}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvidx=[uint64]0}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvcnt=[uint64]931}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvtype=[uint64]9}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvseq=[uint64]148}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvsys=[uint64]2}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvcomp=[uint64]2}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvms=[uint64]82289}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pgq=[uint64]1}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pga=[uint64]1}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{prq=[uint64]1}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{ptq=[uint64]1}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvs1=[uint64]1}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{ef=[uint64]1}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvbad=[uint64]1}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{pvov=[uint64]1}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{eo=[uint64]1}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{evo=[uint64]1}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{d6cr=[uint64]1}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{d7cr=[uint64]1}),
      (& $evaluateIsolatedD7Race -CurrentOverrides @{
          d7b=[uint64]500000;d7f=[uint64]1000;d7iv=[uint64]10}),
      (& $evaluateIsolatedD7Race -OfficialVehicleOverrides @{
          d7pb=[uint64]1}),
      (& $evaluateIsolatedD7Race -CausalOverrides @{valid=$false}),
      (& $evaluateIsolatedD7Race -CausalOverrides @{
          m0_epoch_completed=$false}),
      (& $evaluateIsolatedD7Race -CausalOverrides @{parser_valid=$false}),
      (& $evaluateIsolatedD7Race -CausalOverrides @{
          heartbeat_valid=$false}),
      (& $evaluateIsolatedD7Race -CausalOverrides @{heartbeat_count=1}),
      (& $evaluateIsolatedD7Race -Events @(
          [pscustomobject]@{classification='unknown';anomaly_classes=@('x')})),
      (& $evaluateIsolatedD7Race -CurrentVehicleStatus 'TIMEOUT'))
  foreach ($isolatedD7Negative in $isolatedD7NegativeMatrix) {
    if ($isolatedD7Negative.race.valid -or
        $isolatedD7Negative.disposition.action -ceq
          'RETRY_ISOLATED_D7PB' -or
        $isolatedD7Negative.disposition.action -ceq 'ACCEPT' -or
        $isolatedD7Negative.disposition.fixture_write_count -ne 0) {
      $isolatedD7NegativeMatrixRejected = $false
    }
  }
  $isolatedD7MalformedGate =
      $isolatedD7ExactAttempt3.vehicle_gate.PSObject.Copy()
  $isolatedD7MalformedGate.checks = [object[]]@(
      $isolatedD7MalformedGate.checks | Where-Object {
        $_.name -ceq 'd7pb_empty'
      })
  $isolatedD7MalformedRace = Test-IsolatedPartialD7SnapshotRaceContract `
      -CausalGate $isolatedD7ExactAttempt3.causal_gate `
      -PreRequestVehicleGate $isolatedD7MalformedGate `
      -OfficialVehicle $isolatedD7ExactAttempt3.official_vehicle `
      -OfficialGround $isolatedD7ExactAttempt3.official_ground `
      -PreRequestVehicle $isolatedD7ExactAttempt3.current_vehicle -M0Events @()
  Add-SelfCase 'pre_request_isolated_partial_d7_bounds_and_fail_closed' `
      ($isolatedD7AtOne.disposition.action -ceq 'RETRY_ISOLATED_D7PB' -and
       $isolatedD7At279.disposition.action -ceq 'RETRY_ISOLATED_D7PB' -and
       -not $isolatedD7AtZero.race.valid -and
       $isolatedD7AtZero.disposition.action -ceq 'ACCEPT' -and
       -not $isolatedD7At280.race.valid -and
       $isolatedD7At280.disposition.action -ceq 'REJECT' -and
       $isolatedD7NegativeMatrixRejected -and
       -not $isolatedD7MalformedRace.valid -and
       ([int]$isolatedD7AtOne.fixture_write_count +
        [int]$isolatedD7At279.fixture_write_count +
        [int]$isolatedD7AtZero.fixture_write_count +
        [int]$isolatedD7At280.fixture_write_count) -eq 0) `
      'd7pb bounds are exact and every causal, observer, queue, error, activity, status, or gate-shape mutation fails closed'

  $isolatedD7Attempt1 = & $evaluateIsolatedD7Race -AttemptNumber 1
  $isolatedD7Attempt2 = & $evaluateIsolatedD7Race -AttemptNumber 2
  $isolatedD7WrongMax = & $evaluateIsolatedD7Race `
      -AttemptNumber 2 -DispositionMaxAttempts 2
  $isolatedD7NoToken = & $evaluateIsolatedD7Race `
      -ExtraRetryAvailable $false
  $isolatedD7NoDeadline = & $evaluateIsolatedD7Race `
      -RetryBudgetAvailable $false
  $isolatedD7NoTokenOrDeadline = & $evaluateIsolatedD7Race `
      -ExtraRetryAvailable $false -RetryBudgetAvailable $false
  [int]$modeledIsolatedD7TokenLimit = 1
  [int]$modeledIsolatedD7TokenUsed = 0
  if ($isolatedD7ExactAttempt3.disposition.action -ceq
      'RETRY_ISOLATED_D7PB') { ++$modeledIsolatedD7TokenUsed }
  [bool]$modeledAttempt4ExtraAvailable = (
      $modeledIsolatedD7TokenUsed -lt $modeledIsolatedD7TokenLimit)
  Add-SelfCase 'pre_request_isolated_partial_d7_dedicated_budget_single_use_write0' `
      ($isolatedD7Attempt1.disposition.action -ceq 'REJECT' -and
       $isolatedD7Attempt2.disposition.action -ceq 'REJECT' -and
       $isolatedD7WrongMax.disposition.action -ceq 'REJECT' -and
       $isolatedD7NoToken.disposition.reason -ceq
         'isolated_partial_D7_extra_retry_exhausted' -and
       $isolatedD7NoToken.disposition.retry_exhausted -and
       $isolatedD7NoDeadline.disposition.reason -ceq
         'shared_deadline_exhausted' -and
       $isolatedD7NoTokenOrDeadline.disposition.reason -ceq
         'isolated_partial_D7_extra_retry_exhausted' -and
       $modeledIsolatedD7TokenUsed -eq 1 -and
       -not $modeledAttempt4ExtraAvailable -and
       ([int]$isolatedD7Attempt1.disposition.fixture_write_count +
        [int]$isolatedD7Attempt2.disposition.fixture_write_count +
        [int]$isolatedD7WrongMax.disposition.fixture_write_count +
        [int]$isolatedD7NoToken.disposition.fixture_write_count +
        [int]$isolatedD7NoDeadline.disposition.fixture_write_count +
        [int]$isolatedD7NoTokenOrDeadline.disposition.fixture_write_count) `
          -eq 0) `
      'the dedicated budget exists only after standard attempt 3, is single-use, deadline-bound, and write-zero'

  $isolatedD7Attempt4CleanDisposition = Get-PreRequestAttemptDisposition `
      -CausalGate $cleanCausalGate `
      -PreRequestVehicleGate $preRequestGateClean `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $preRequestVehicleClean -M0Events @() `
      -AttemptNumber 4 -MaxAttempts 3 -RetryBudgetAvailable $true `
      -IsolatedPartialD7ExtraRetryAvailable $false
  Add-SelfCase 'pre_request_isolated_partial_d7_attempt4_clean_accept_write0' `
      ($isolatedD7Attempt4CleanDisposition.action -ceq 'ACCEPT' -and
       $isolatedD7Attempt4CleanDisposition.reason -ceq
         'clean_m0_and_vehicle_gate_valid' -and
       -not $isolatedD7Attempt4CleanDisposition.retry_eligible -and
       $isolatedD7Attempt4CleanDisposition.fixture_write_count -eq 0) `
      'the dedicated fourth epoch can ACCEPT only through the unchanged ordinary clean gate and still performs no request write'

  $isolatedD7Attempt4Repeat = & $evaluateIsolatedD7Race `
      -AttemptNumber 4 -ExtraRetryAvailable $false
  $isolatedD7Attempt4Sentinel = Get-PreRequestAttemptDisposition `
      -CausalGate $sentinelCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle `
      -M0Events $sentinelState.events.ToArray() `
      -AttemptNumber 4 -MaxAttempts 3 -RetryBudgetAvailable $true `
      -IsolatedPartialD7ExtraRetryAvailable $false
  $isolatedD7Attempt4Other = & $evaluateIsolatedD7Race `
      -CurrentOverrides @{d7cr=[uint64]1} -AttemptNumber 4 `
      -ExtraRetryAvailable $false
  $isolatedD7Attempt4ParserBad = & $evaluateIsolatedD7Race `
      -CausalOverrides @{parser_valid=$false} -AttemptNumber 4 `
      -ExtraRetryAvailable $false
  [object[]]$isolatedD7Attempt4Nonclean = [object[]]@(
      $isolatedD7Attempt4Repeat.disposition,
      $isolatedD7Attempt4Sentinel,
      $isolatedD7Attempt4Other.disposition,
      $isolatedD7Attempt4ParserBad.disposition)
  [bool]$isolatedD7Attempt4AllRejected = $true
  foreach ($attempt4Disposition in $isolatedD7Attempt4Nonclean) {
    if ($attempt4Disposition.action -cne 'REJECT' -or
        $attempt4Disposition.retry_eligible -or
        $attempt4Disposition.fixture_write_count -ne 0) {
      $isolatedD7Attempt4AllRejected = $false
    }
  }
  Add-SelfCase 'pre_request_isolated_partial_d7_attempt4_nonclean_rejected_write0' `
      ($isolatedD7Attempt4AllRejected -and
       $isolatedD7Attempt4Repeat.disposition.reason -ceq
         'isolated_partial_D7_extra_retry_exhausted' -and
       $isolatedD7Attempt4Sentinel.reason -ceq 'retry_exhausted' -and
       @($isolatedD7Attempt4Nonclean | Where-Object {
         $_.action -ceq 'RETRY_ISOLATED_D7PB'
       }).Count -eq 0) `
      'isolated recurrence, ordinary retry candidate, and unrelated/parser faults on attempt 4 all reject with no attempt 5 and write zero'

  # A STAT_RUNTIME frame can be parsed by Vehicle after the official pair but
  # before the pre-request diagnostic line, while the Ground M0 capture remains
  # silent.  This exact +1 observer shape is never accepted.  It may only reuse
  # the bounded backlog-drain plus strict final stable-pair promotion path.
  $silentOfficialVehicleFields = $vehicleBaseFields.Clone()
  $silentOfficialVehicleFields['d722'] = [uint64]22
  $silentOfficialVehicleFields['pvok'] = [uint64]22
  $silentOfficialVehicleFields['pvs1'] = [uint64]0
  $silentOfficialVehicleFields['d7pb'] = [uint64]0
  $silentOfficialVehicleFields['pvid'] = 'STAT_RUNTIME'
  $silentOfficialVehicleFields['pvval'] = '0000FFFE'
  $silentOfficialVehicleFields['pvidx'] = [uint64]65535
  $silentOfficialVehicleFields['pvcnt'] = [uint64]932
  $silentOfficialVehicleFields['pvtype'] = [uint64]6
  $silentOfficialVehicleFields['pvsys'] = [uint64]1
  $silentOfficialVehicleFields['pvcomp'] = [uint64]1
  $silentOfficialVehicleFields['pvseq'] = [uint64]21
  $silentOfficialVehicleFields['pvms'] = [uint64]90000
  $silentOfficialGroundFields = $groundBaseFields.Clone()
  $silentOfficialGroundFields['rf22'] = [uint64]22
  $silentCurrentVehicleFields = $silentOfficialVehicleFields.Clone()
  $silentCurrentVehicleFields['d722'] = [uint64]23
  $silentCurrentVehicleFields['pvok'] = [uint64]23
  $silentCurrentVehicleFields['pvms'] = [uint64]105000
  $silentCurrentVehicleFields['pvval'] = '0000FFFF'
  $silentCurrentVehicleFields['pvseq'] = [uint64]22
  $silentCausalGate = [pscustomobject][ordered]@{
    valid=$true;parser_integrity=[pscustomobject]@{valid=$true}
    heartbeat=[pscustomobject]@{valid=$true;count=6}
    pre_request_backlog_gate=[pscustomobject]@{
      m0_epoch_completed=$true;m0_veto_events=@()
    }
  }
  $evaluateSilentPreRequestRace = {
    param(
      [hashtable]$CurrentVehicleOverrides = @{},
      [hashtable]$OfficialVehicleOverrides = @{},
      [hashtable]$OfficialGroundOverrides = @{},
      $RaceCausalGate = $silentCausalGate,
      [AllowNull()]$RaceVehicleGate = $null,
      [AllowEmptyCollection()][object[]]$RaceM0Events = @(),
      [AllowNull()]$RacePreM0TailEvidence = $null,
      [AllowNull()]$RaceM0Capture = $null,
      [AllowNull()]$RaceDiagnosticEndBarrier = $null,
      [string]$RacePreRequestName = 'pre_request_vehicle_1',
      [double]$RacePreRequestStartedElapsedMs = 7000.0,
      [double]$RacePreRequestFinishedElapsedMs = 9000.0,
      [long]$RaceM0GroundRawOffset = 1200,
      [long]$RaceM0GateEndGroundRawOffset = 1300,
      [int]$AttemptNumber = 1,
      [bool]$RetryBudgetAvailable = $true,
      [bool]$ExactObservedStatRuntimeExtraRetryAvailable = $false
    )
    $officialVehicleFields = $silentOfficialVehicleFields.Clone()
    $officialGroundFields = $silentOfficialGroundFields.Clone()
    $currentVehicleFields = $silentCurrentVehicleFields.Clone()
    foreach ($key in $OfficialVehicleOverrides.Keys) {
      $officialVehicleFields[$key] = $OfficialVehicleOverrides[$key]
    }
    foreach ($key in $OfficialGroundOverrides.Keys) {
      $officialGroundFields[$key] = $OfficialGroundOverrides[$key]
    }
    foreach ($key in $CurrentVehicleOverrides.Keys) {
      $currentVehicleFields[$key] = $CurrentVehicleOverrides[$key]
    }
    $officialVehicleSnapshot = New-OfflineSnapshot `
        -Fields $officialVehicleFields -Q 41 -Ms ([uint64]100000)
    $officialGroundSnapshot = New-OfflineSnapshot `
        -Fields $officialGroundFields -Q 51 -Ms ([uint64]100001)
    $currentVehicleSnapshot = New-OfflineSnapshot `
        -Fields $currentVehicleFields -Q 42 -Ms ([uint64]110000)
    $currentVehicleSnapshot | Add-Member -MemberType NoteProperty `
        -Name name -Value $RacePreRequestName -Force
    $currentVehicleSnapshot | Add-Member -MemberType NoteProperty `
        -Name started_elapsed_ms -Value $RacePreRequestStartedElapsedMs -Force
    $currentVehicleSnapshot | Add-Member -MemberType NoteProperty `
        -Name finished_elapsed_ms -Value $RacePreRequestFinishedElapsedMs -Force
    $currentVehicleSnapshot | Add-Member -MemberType NoteProperty `
        -Name capture_start_barrier -Value ([pscustomobject][ordered]@{
          active=$true
          ground_raw_offset_exclusive=$RaceM0GateEndGroundRawOffset
          ground_boundary_elapsed_ms=($RacePreRequestStartedElapsedMs - 1.0)
        }) -Force
    $computedVehicleGate = Test-PreRequestVehicleGate `
        -OfficialVehicle $officialVehicleSnapshot `
        -OfficialGround $officialGroundSnapshot `
        -PreRequestVehicle $currentVehicleSnapshot
    $vehicleGate = if ($null -ne $RaceVehicleGate) {
      $RaceVehicleGate
    } else {
      $computedVehicleGate
    }
    $disposition = Get-PreRequestAttemptDisposition `
        -CausalGate $RaceCausalGate `
        -PreRequestVehicleGate $vehicleGate `
        -OfficialVehicle $officialVehicleSnapshot `
        -OfficialGround $officialGroundSnapshot `
        -PreRequestVehicle $currentVehicleSnapshot `
        -M0Events $RaceM0Events `
        -PreM0TailEvidence $RacePreM0TailEvidence `
        -M0Capture $RaceM0Capture `
        -DiagnosticEndBarrier $RaceDiagnosticEndBarrier `
        -M0GroundRawOffset $RaceM0GroundRawOffset `
        -M0GateEndGroundRawOffset $RaceM0GateEndGroundRawOffset `
        -AttemptNumber $AttemptNumber `
        -MaxAttempts 3 -RetryBudgetAvailable $RetryBudgetAvailable `
        -ExactObservedStatRuntimeExtraRetryAvailable `
          $ExactObservedStatRuntimeExtraRetryAvailable
    return [pscustomobject][ordered]@{
      official_vehicle=$officialVehicleSnapshot
      official_ground=$officialGroundSnapshot
      pre_request_vehicle=$currentVehicleSnapshot
      vehicle_gate=$vehicleGate;disposition=$disposition
    }
  }

  # QUAL-010 R2 observed the exact sentinel at Ground while that same single
  # generic frame was still selected in Vehicle (pgq=1,pga=1). This is never
  # an ACCEPT shape. It may only enter the existing bounded RETRY/reacquisition
  # path when the event, observer, counters, queues, boot, and errors are exact.
  [object[]]$exactActiveEvents =
      [object[]]@($sentinelState.events.ToArray())
  $activeExact = & $evaluateSilentPreRequestRace `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]1} `
      -RaceCausalGate $sentinelCausalGate `
      -RaceM0Events $exactActiveEvents
  [object[]]$activeExactFailureNames =
      [object[]]@($activeExact.disposition.failed_vehicle_check_names)
  Add-SelfCase 'pre_request_exact_stat_runtime_active_frame_retryable' `
      ($activeExact.disposition.action -ceq 'RETRY' -and
       $activeExact.disposition.reason -ceq
         'exact_active_STAT_RUNTIME_m0_race' -and
       $activeExact.disposition.retry_eligible -and
       $activeExact.disposition.exact_active_STAT_RUNTIME_m0_race -and
       $activeExact.disposition.exact_active_vehicle_failure_set -and
       $activeExact.disposition.exact_active_scheduler_state -and
       $activeExact.disposition.exact_active_error_zero -and
       $activeExactFailureNames.Count -eq 4 -and
       $activeExactFailureNames -ccontains 'd722_stable' -and
       $activeExactFailureNames -ccontains 'd722_rf22_reconciled' -and
       $activeExactFailureNames -ccontains 'pgq' -and
       $activeExactFailureNames -ccontains 'pga' -and
       $activeExact.disposition.fixture_write_count -eq 0) `
      'one exact observed STAT_RUNTIME frame in the exact pgq=1,pga=1 active state authorizes bounded reacquisition only, never ACCEPT'

  $activeD7pbNonzero = & $evaluateSilentPreRequestRace `
      -CurrentVehicleOverrides @{
        pgq=[uint64]1;pga=[uint64]1;d7pb=[uint64]1
      } -RaceCausalGate $sentinelCausalGate `
      -RaceM0Events $exactActiveEvents
  Add-SelfCase 'pre_request_exact_stat_runtime_active_d7pb_nonzero_not_retryable' `
      ($activeD7pbNonzero.disposition.action -ceq 'REJECT' -and
       -not $activeD7pbNonzero.disposition.retry_eligible -and
       -not $activeD7pbNonzero.disposition.exact_active_scheduler_state -and
       $activeD7pbNonzero.disposition.fixture_write_count -eq 0) `
      'an active M0 STAT_RUNTIME race requires d7pb=0 and cannot borrow the pre-M0 tail exception'

  $activePgaTwo = & $evaluateSilentPreRequestRace `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]2} `
      -RaceCausalGate $sentinelCausalGate `
      -RaceM0Events $exactActiveEvents
  Add-SelfCase 'pre_request_exact_stat_runtime_active_pga_gt_one_not_retryable' `
      ($activePgaTwo.disposition.action -ceq 'REJECT' -and
       -not $activePgaTwo.disposition.retry_eligible -and
       -not $activePgaTwo.disposition.exact_active_scheduler_state -and
       $activePgaTwo.disposition.fixture_write_count -eq 0) `
      'pga is boolean diagnostic evidence; pga=2 remains fail-closed even beside one exact event'

  [bool]$activeQueueShapeRejected = $true
  foreach ($activeQueueOverride in @(
      @{pgq=[uint64]0;pga=[uint64]1},
      @{pgq=[uint64]2;pga=[uint64]1})) {
    $activeQueueEvaluation = & $evaluateSilentPreRequestRace `
        -CurrentVehicleOverrides $activeQueueOverride `
        -RaceCausalGate $sentinelCausalGate `
        -RaceM0Events $exactActiveEvents
    if ($activeQueueEvaluation.disposition.action -cne 'REJECT' -or
        $activeQueueEvaluation.disposition.retry_eligible -or
        $activeQueueEvaluation.disposition.exact_active_scheduler_state -or
        $activeQueueEvaluation.disposition.fixture_write_count -ne 0) {
      $activeQueueShapeRejected = $false
    }
  }
  Add-SelfCase 'pre_request_exact_stat_runtime_active_queue_shape_not_retryable' `
      $activeQueueShapeRejected `
      'pgq=0/pga=1 and pgq=2/pga=1 cannot be attributed to the one exact observed active frame'

  [bool]$activeEventShapeRejected = $true
  foreach ($activeEventOverride in @(
      @{classification='unknown_sentinel'},
      @{system_id=2},@{component_id=2},@{param_id='STAT_OTHER'},
      @{param_id_hex='00'},@{param_index=0},@{param_count=931},
      @{param_type=9},@{anomaly_classes=[object[]]@('unexpected')})) {
    $badActiveEvent = $exactActiveEvents[0].PSObject.Copy()
    foreach ($activeEventKey in $activeEventOverride.Keys) {
      $badActiveEvent.$activeEventKey = $activeEventOverride[$activeEventKey]
    }
    $badActiveEventEvaluation = & $evaluateSilentPreRequestRace `
        -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]1} `
        -RaceCausalGate $sentinelCausalGate `
        -RaceM0Events ([object[]]@($badActiveEvent))
    if ($badActiveEventEvaluation.disposition.action -cne 'REJECT' -or
        $badActiveEventEvaluation.disposition.retry_eligible -or
        $badActiveEventEvaluation.disposition.fixture_write_count -ne 0) {
      $activeEventShapeRejected = $false
    }
  }
  $activeIndexedEvent = & $evaluateSilentPreRequestRace `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]1} `
      -RaceCausalGate $sentinelCausalGate `
      -RaceM0Events ([object[]]@($indexedM0Event))
  $activeMultipleEvents = & $evaluateSilentPreRequestRace `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]1} `
      -RaceCausalGate $sentinelCausalGate `
      -RaceM0Events ([object[]]@($exactActiveEvents[0],$exactActiveEvents[0]))
  foreach ($activeObserverOverride in @(
      @{boot=[uint64]95},@{d722=[uint64]24},@{pvok=[uint64]22},
      @{pvok=[uint64]24},@{pvsys=[uint64]2},@{pvcomp=[uint64]2},
      @{pvms=[uint64]90000},@{pvms=[uint64]110001})) {
    $badActiveObserver = & $evaluateSilentPreRequestRace `
        -CurrentVehicleOverrides ($activeObserverOverride +
          @{pgq=[uint64]1;pga=[uint64]1}) `
        -RaceCausalGate $sentinelCausalGate `
        -RaceM0Events $exactActiveEvents
    if ($badActiveObserver.disposition.action -cne 'REJECT' -or
        $badActiveObserver.disposition.retry_eligible -or
        $badActiveObserver.disposition.fixture_write_count -ne 0) {
      $activeEventShapeRejected = $false
    }
  }
  Add-SelfCase 'pre_request_exact_stat_runtime_active_event_shape_not_retryable' `
      ($activeEventShapeRejected -and
       $activeIndexedEvent.disposition.action -ceq 'REJECT' -and
       -not $activeIndexedEvent.disposition.retry_eligible -and
       $activeMultipleEvents.disposition.action -ceq 'REJECT' -and
       -not $activeMultipleEvents.disposition.retry_eligible -and
       ([int]$activeIndexedEvent.disposition.fixture_write_count +
        [int]$activeMultipleEvents.disposition.fixture_write_count) -eq 0) `
      'unknown/indexed/multiple/anomalous or wrong source-ID-index-count-type, boot, delta, observer source, and freshness shapes remain fail-closed'

  [bool]$activeOtherQueueOrErrorRejected = $true
  foreach ($activeOtherOverride in @(
      @{prq=[uint64]1},@{ptq=[uint64]1},@{pvs1=[uint64]1},
      @{d7pb=[uint64]1},@{ef=[uint64]1},@{pvbad=[uint64]1},
      @{pvov=[uint64]1},@{eo=[uint64]1},@{evo=[uint64]1},
      @{d6cr=[uint64]1},@{d7cr=[uint64]1})) {
    $badActiveQueueOrError = & $evaluateSilentPreRequestRace `
        -CurrentVehicleOverrides ($activeOtherOverride +
          @{pgq=[uint64]1;pga=[uint64]1}) `
        -RaceCausalGate $sentinelCausalGate `
        -RaceM0Events $exactActiveEvents
    if ($badActiveQueueOrError.disposition.action -cne 'REJECT' -or
        $badActiveQueueOrError.disposition.retry_eligible -or
        $badActiveQueueOrError.disposition.fixture_write_count -ne 0) {
      $activeOtherQueueOrErrorRejected = $false
    }
  }
  Add-SelfCase 'pre_request_exact_stat_runtime_active_other_queue_or_error_not_retryable' `
      $activeOtherQueueOrErrorRejected `
      'any other PARAM lane/parser backlog or absolute related error rejects the active-frame attribution'

  $activeAttempt2 = & $evaluateSilentPreRequestRace `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]1} `
      -RaceCausalGate $sentinelCausalGate `
      -RaceM0Events $exactActiveEvents -AttemptNumber 2
  $activeAttempt3 = & $evaluateSilentPreRequestRace `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]1} `
      -RaceCausalGate $sentinelCausalGate `
      -RaceM0Events $exactActiveEvents -AttemptNumber 3
  $activeNoDeadline = & $evaluateSilentPreRequestRace `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]1} `
      -RaceCausalGate $sentinelCausalGate `
      -RaceM0Events $exactActiveEvents -RetryBudgetAvailable $false
  Add-SelfCase 'pre_request_exact_stat_runtime_active_attempt_or_deadline_bounded_write0' `
      ($activeAttempt2.disposition.action -ceq 'RETRY' -and
       $activeAttempt3.disposition.action -ceq 'REJECT' -and
       $activeAttempt3.disposition.retry_exhausted -and
       $activeNoDeadline.disposition.action -ceq 'REJECT' -and
       $activeNoDeadline.disposition.reason -ceq 'shared_deadline_exhausted' -and
       ([int]$activeAttempt2.disposition.fixture_write_count +
        [int]$activeAttempt3.disposition.fixture_write_count +
        [int]$activeNoDeadline.disposition.fixture_write_count) -eq 0) `
      'the active exact race neither extends the shared deadline nor exceeds the existing three-attempt bound or writes fixture #21'
  Add-SelfCase 'pre_request_exact_stat_runtime_active_retry_then_stable_pair_reacquisition' `
      ($activeExact.disposition.action -ceq 'RETRY' -and
       $promotion.valid -and $promotion.skip_next_recovery_capture -and
       $cleanDisposition.action -ceq 'ACCEPT' -and
       ([int]$activeExact.disposition.fixture_write_count +
        [int]$promotion.fixture_write_count +
       [int]$cleanDisposition.fixture_write_count) -eq 0) `
      'active exact evidence reaches the same strict stable-pair promotion path; only a later clean M0 can ACCEPT'

  # R14 can phase-align all three standard attempts with the periodic generic
  # STAT_RUNTIME producer.  Only one exact wire-observed generic event on the
  # final standard attempt may select the shared dedicated attempt-4 slot.
  # Selection is still write-zero; attempt 4 must pass the ordinary clean gate.
  $wireExactAttempt3Disposition = Get-PreRequestAttemptDisposition `
      -CausalGate $sentinelCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle `
      -M0Events $sentinelState.events.ToArray() `
      -AttemptNumber 3 -MaxAttempts 3 -RetryBudgetAvailable $true `
      -ExactObservedStatRuntimeExtraRetryAvailable $true
  Add-SelfCase 'pre_request_exact_wire_stat_runtime_attempt3_arms_extra_write0' `
      ($wireExactAttempt3Disposition.action -ceq
         'RETRY_EXACT_STAT_RUNTIME' -and
       $wireExactAttempt3Disposition.reason -ceq
         'exact_wire_observed_STAT_RUNTIME_extra_retry' -and
       $wireExactAttempt3Disposition.exact_known_event -and
       $wireExactAttempt3Disposition.
         exact_observed_stat_runtime_final_standard_attempt -and
       $wireExactAttempt3Disposition.
         exact_observed_stat_runtime_extra_retry_candidate -and
       $wireExactAttempt3Disposition.
         exact_observed_stat_runtime_extra_retry_eligible -and
       $wireExactAttempt3Disposition.
         exact_observed_stat_runtime_extra_retry_selected -and
       $wireExactAttempt3Disposition.retry_eligible -and
       -not $wireExactAttempt3Disposition.retry_exhausted -and
       $wireExactAttempt3Disposition.fixture_write_count -eq 0) `
      'only one exact wire-observed generic STAT_RUNTIME on standard attempt 3 selects the write-zero dedicated retry'

  $wireExactNoTokenDisposition = Get-PreRequestAttemptDisposition `
      -CausalGate $sentinelCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle `
      -M0Events $sentinelState.events.ToArray() `
      -AttemptNumber 3 -MaxAttempts 3 -RetryBudgetAvailable $true `
      -ExactObservedStatRuntimeExtraRetryAvailable $false
  $wireSilentCausalGate = $sentinelCausalGate.PSObject.Copy()
  $wireSilentCausalGate.pre_request_backlog_gate =
      [pscustomobject]@{m0_epoch_completed=$true;m0_veto_events=@()}
  $wireSilentAttempt3Disposition = Get-PreRequestAttemptDisposition `
      -CausalGate $wireSilentCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle -M0Events @() `
      -AttemptNumber 3 -MaxAttempts 3 -RetryBudgetAvailable $true `
      -ExactObservedStatRuntimeExtraRetryAvailable $true
  $wireParserBadAttempt3Disposition = Get-PreRequestAttemptDisposition `
      -CausalGate $parserBadCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle `
      -M0Events $sentinelState.events.ToArray() `
      -AttemptNumber 3 -MaxAttempts 3 -RetryBudgetAvailable $true `
      -ExactObservedStatRuntimeExtraRetryAvailable $true
  $wireHeartbeatBadAttempt3Disposition = Get-PreRequestAttemptDisposition `
      -CausalGate $heartbeatBadCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle `
      -M0Events $sentinelState.events.ToArray() `
      -AttemptNumber 3 -MaxAttempts 3 -RetryBudgetAvailable $true `
      -ExactObservedStatRuntimeExtraRetryAvailable $true
  $wireNoDeadlineAttempt3Disposition = Get-PreRequestAttemptDisposition `
      -CausalGate $sentinelCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle `
      -M0Events $sentinelState.events.ToArray() `
      -AttemptNumber 3 -MaxAttempts 3 -RetryBudgetAvailable $false `
      -ExactObservedStatRuntimeExtraRetryAvailable $true
  $wireNearMissEvent = $sentinelState.events.ToArray()[0].PSObject.Copy()
  $wireNearMissEvent.system_id = 2
  $wireNearMissAttempt3Disposition = Get-PreRequestAttemptDisposition `
      -CausalGate $sentinelCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle -M0Events @($wireNearMissEvent) `
      -AttemptNumber 3 -MaxAttempts 3 -RetryBudgetAvailable $true `
      -ExactObservedStatRuntimeExtraRetryAvailable $true
  [object[]]$wireExtraNegativeDispositions = [object[]]@(
      $wireExactNoTokenDisposition,$wireSilentAttempt3Disposition,
      $wireParserBadAttempt3Disposition,$wireHeartbeatBadAttempt3Disposition,
      $wireNoDeadlineAttempt3Disposition,$wireNearMissAttempt3Disposition)
  [bool]$wireExtraNegativeMatrixRejected = $true
  foreach ($wireExtraNegativeDisposition in $wireExtraNegativeDispositions) {
    if ($wireExtraNegativeDisposition.action -cne 'REJECT' -or
        $wireExtraNegativeDisposition.retry_eligible -or
        $wireExtraNegativeDisposition.
          exact_observed_stat_runtime_extra_retry_selected -or
        $wireExtraNegativeDisposition.fixture_write_count -ne 0) {
      $wireExtraNegativeMatrixRejected = $false
    }
  }
  Add-SelfCase 'pre_request_exact_wire_stat_runtime_extra_near_miss_silent_faults_rejected' `
      ($wireExtraNegativeMatrixRejected -and
       $wireExactNoTokenDisposition.reason -ceq
         'exact_wire_observed_STAT_RUNTIME_extra_retry_exhausted' -and
       $wireExactNoTokenDisposition.retry_exhausted -and
       $wireNoDeadlineAttempt3Disposition.reason -ceq
         'shared_deadline_exhausted') `
      'no token, silent evidence, near-miss wire identity, parser fault, Heartbeat fault, or exhausted deadline can select the extra attempt'

  $wireAttempt4CleanDisposition = Get-PreRequestAttemptDisposition `
      -CausalGate $cleanCausalGate `
      -PreRequestVehicleGate $preRequestGateClean `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $preRequestVehicleClean -M0Events @() `
      -AttemptNumber 4 -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'pre_request_exact_wire_stat_runtime_attempt4_clean_accept_write0' `
      ($wireAttempt4CleanDisposition.action -ceq 'ACCEPT' -and
       $wireAttempt4CleanDisposition.reason -ceq
         'clean_m0_and_vehicle_gate_valid' -and
       -not $wireAttempt4CleanDisposition.retry_eligible -and
       -not $wireAttempt4CleanDisposition.
         exact_observed_stat_runtime_extra_retry_selected -and
       $wireAttempt4CleanDisposition.fixture_write_count -eq 0) `
      'the dedicated attempt authorizes nothing directly; only its independent ordinary clean M0 and Vehicle gates ACCEPT'

  $wireAttempt4RecurrenceDisposition = Get-PreRequestAttemptDisposition `
      -CausalGate $sentinelCausalGate `
      -PreRequestVehicleGate $sentinelVehicleGate `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $sentinelVehicle `
      -M0Events $sentinelState.events.ToArray() `
      -AttemptNumber 4 -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'pre_request_exact_wire_stat_runtime_attempt4_recurrence_rejected_write0' `
      ($wireAttempt4RecurrenceDisposition.action -ceq 'REJECT' -and
       $wireAttempt4RecurrenceDisposition.reason -ceq 'retry_exhausted' -and
       $wireAttempt4RecurrenceDisposition.retry_exhausted -and
       -not $wireAttempt4RecurrenceDisposition.retry_eligible -and
       -not $wireAttempt4RecurrenceDisposition.
         exact_observed_stat_runtime_extra_retry_selected -and
       $wireAttempt4RecurrenceDisposition.fixture_write_count -eq 0) `
      'recurrence on attempt 4 cannot re-arm an attempt 5 and remains write-zero REJECT'

  [int]$modeledDedicatedExtraRetryLimit = 1
  [int]$modeledStandardAttemptLimit = 3
  [int]$modeledTotalAttemptLimit =
      $modeledStandardAttemptLimit + $modeledDedicatedExtraRetryLimit
  Add-SelfCase 'pre_request_dedicated_extra_token_mutually_exclusive_total4' `
      ($isolatedD7ExactAttempt3.disposition.
         isolated_partial_d7_extra_retry_selected -and
       -not $isolatedD7ExactAttempt3.disposition.
         exact_observed_stat_runtime_extra_retry_selected -and
       $wireExactAttempt3Disposition.
         exact_observed_stat_runtime_extra_retry_selected -and
       -not $wireExactAttempt3Disposition.
         isolated_partial_d7_extra_retry_selected -and
       $modeledDedicatedExtraRetryLimit -eq 1 -and
       $modeledTotalAttemptLimit -eq 4 -and
       $wireAttempt4RecurrenceDisposition.action -ceq 'REJECT' -and
       ([int]$isolatedD7ExactAttempt3.disposition.fixture_write_count +
        [int]$wireExactAttempt3Disposition.fixture_write_count +
        [int]$wireAttempt4RecurrenceDisposition.fixture_write_count) -eq 0) `
      'isolated D7 and exact wire STAT_RUNTIME selectors share one exclusive extra slot and the total bound remains four attempts'

  # QUAL-011 R2 observed the same exact +1 STAT_RUNTIME parser observer after
  # M0, but before the generic frame became active: pgq=1,pga=0.  The prior
  # official snapshot also had a transient d7pb=5 which was fully drained by
  # the pre-request snapshot.  This queued-only shape is never ACCEPT; it may
  # only enter the existing bounded drain + stable-pair reacquisition path.
  $queuedLateExact = & $evaluateSilentPreRequestRace `
      -OfficialVehicleOverrides @{d7pb=[uint64]5;pgq=[uint64]0} `
      -CurrentVehicleOverrides @{
        pgq=[uint64]1;pga=[uint64]0;prq=[uint64]0;ptq=[uint64]0
        pvs1=[uint64]0;d7pb=[uint64]0
      }
  [object[]]$queuedLateFailureNames =
      [object[]]@($queuedLateExact.disposition.failed_vehicle_check_names)
  $queuedLateOfficialD7pb = Get-SnapshotUInt64 `
      -Snapshot $queuedLateExact.official_vehicle -Key 'd7pb'
  $queuedLateCurrentD7pb = Get-SnapshotUInt64 `
      -Snapshot $queuedLateExact.pre_request_vehicle -Key 'd7pb'
  [bool]$queuedLateProofFieldsPresent = (
      $queuedLateExact.disposition.PSObject.Properties.Name -ccontains
        'exact_late_queued_STAT_RUNTIME_race' -and
      $queuedLateExact.disposition.PSObject.Properties.Name -ccontains
        'exact_silent_queued_vehicle_failure_set' -and
      $queuedLateExact.disposition.PSObject.Properties.Name -ccontains
        'exact_silent_queued_scheduler_state')
  Add-SelfCase 'pre_request_silent_stat_runtime_queued_pgq1_pga0_retryable' `
      ($queuedLateExact.disposition.action -ceq 'RETRY' -and
       $queuedLateExact.disposition.reason -ceq
         'exact_late_queued_STAT_RUNTIME_race' -and
       $queuedLateExact.disposition.retry_eligible -and
       $queuedLateProofFieldsPresent -and
       [bool]$queuedLateExact.disposition.exact_late_queued_STAT_RUNTIME_race -and
       [bool]$queuedLateExact.disposition.exact_silent_queued_scheduler_state -and
       $queuedLateExact.disposition.m0_event_count -eq 0 -and
       $queuedLateExact.disposition.fixture_write_count -eq 0) `
      'the exact late known STAT_RUNTIME pgq=1,pga=0 snapshot receives bounded RETRY only'
  Add-SelfCase 'pre_request_silent_stat_runtime_queued_exact_failure_set_and_baseline_d7pb_drained' `
      ($queuedLateFailureNames.Count -eq 3 -and
       $queuedLateFailureNames -ccontains 'd722_stable' -and
       $queuedLateFailureNames -ccontains 'd722_rf22_reconciled' -and
       $queuedLateFailureNames -ccontains 'pgq' -and
       $queuedLateProofFieldsPresent -and
       [bool]$queuedLateExact.disposition.exact_silent_queued_vehicle_failure_set -and
       $queuedLateOfficialD7pb.found -and
       [uint64]$queuedLateOfficialD7pb.value -eq [uint64]5 -and
       $queuedLateCurrentD7pb.found -and
       [uint64]$queuedLateCurrentD7pb.value -eq [uint64]0 -and
       $queuedLateExact.disposition.fixture_write_count -eq 0) `
      'only the exact three failures qualify and a historical bounded parser tail must already be empty now'

  [bool]$queuedLateUnknownIndexedRejected = $true
  foreach ($queuedLateObserverOverride in @(
      @{pvid='STAT_OTHER'},@{pvidx=[uint64]0})) {
    $queuedLateBadObserver = & $evaluateSilentPreRequestRace `
        -OfficialVehicleOverrides @{d7pb=[uint64]5;pgq=[uint64]0} `
        -CurrentVehicleOverrides ($queuedLateObserverOverride + @{
          pgq=[uint64]1;pga=[uint64]0;d7pb=[uint64]0
        })
    if ($queuedLateBadObserver.disposition.action -cne 'REJECT' -or
        $queuedLateBadObserver.disposition.retry_eligible -or
        $queuedLateBadObserver.disposition.fixture_write_count -ne 0) {
      $queuedLateUnknownIndexedRejected = $false
    }
  }
  $queuedLateIndexedM0Gate = [pscustomobject][ordered]@{
    valid=$false;parser_integrity=[pscustomobject]@{valid=$true}
    heartbeat=[pscustomobject]@{valid=$true;count=6}
    pre_request_backlog_gate=[pscustomobject]@{
      m0_epoch_completed=$true;m0_veto_events=[object[]]@($indexedM0Event)
    }
  }
  $queuedLateIndexedM0 = & $evaluateSilentPreRequestRace `
      -OfficialVehicleOverrides @{d7pb=[uint64]5;pgq=[uint64]0} `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]0;d7pb=[uint64]0} `
      -RaceCausalGate $queuedLateIndexedM0Gate `
      -RaceM0Events ([object[]]@($indexedM0Event))
  $queuedLateParserBadGate = [pscustomobject][ordered]@{
    valid=$false;parser_integrity=[pscustomobject]@{valid=$false}
    heartbeat=[pscustomobject]@{valid=$true;count=6}
    pre_request_backlog_gate=[pscustomobject]@{
      m0_epoch_completed=$true;m0_veto_events=@()
    }
  }
  $queuedLateCrcBad = & $evaluateSilentPreRequestRace `
      -OfficialVehicleOverrides @{d7pb=[uint64]5;pgq=[uint64]0} `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]0;d7pb=[uint64]0} `
      -RaceCausalGate $queuedLateParserBadGate
  $queuedLatePartial = & $evaluateSilentPreRequestRace `
      -OfficialVehicleOverrides @{d7pb=[uint64]5;pgq=[uint64]0} `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]0;d7pb=[uint64]1}
  Add-SelfCase 'pre_request_silent_stat_runtime_queued_unknown_indexed_crc_partial_not_retryable' `
      ($queuedLateUnknownIndexedRejected -and
       $queuedLateIndexedM0.disposition.action -ceq 'REJECT' -and
       -not $queuedLateIndexedM0.disposition.retry_eligible -and
       $queuedLateCrcBad.disposition.action -ceq 'REJECT' -and
       $queuedLateCrcBad.disposition.reason -ceq 'parser_integrity_invalid' -and
       -not $queuedLateCrcBad.disposition.retry_eligible -and
       $queuedLatePartial.disposition.action -ceq 'REJECT' -and
       -not $queuedLatePartial.disposition.retry_eligible -and
       ([int]$queuedLateIndexedM0.disposition.fixture_write_count +
        [int]$queuedLateCrcBad.disposition.fixture_write_count +
        [int]$queuedLatePartial.disposition.fixture_write_count) -eq 0) `
      'unknown/indexed evidence, parser CRC-integrity failure, or a current partial frame remains fail-closed'

  [bool]$queuedLateQueueOrErrorRejected = $true
  foreach ($queuedLateQueueOrErrorOverride in @(
      @{pgq=[uint64]2},@{pga=[uint64]1},@{prq=[uint64]1},
      @{ptq=[uint64]1},@{pvs1=[uint64]1},@{ef=[uint64]1},
      @{pvbad=[uint64]1},@{pvov=[uint64]1},@{eo=[uint64]1},
      @{evo=[uint64]1},@{d7cr=[uint64]1})) {
    $queuedLateCurrentOverrides = @{
      pgq=[uint64]1;pga=[uint64]0;d7pb=[uint64]0
    }
    foreach ($queuedLateOverrideKey in $queuedLateQueueOrErrorOverride.Keys) {
      $queuedLateCurrentOverrides[$queuedLateOverrideKey] =
          $queuedLateQueueOrErrorOverride[$queuedLateOverrideKey]
    }
    $queuedLateBadQueueOrError = & $evaluateSilentPreRequestRace `
        -OfficialVehicleOverrides @{d7pb=[uint64]5;pgq=[uint64]0} `
        -CurrentVehicleOverrides $queuedLateCurrentOverrides
    if ($queuedLateBadQueueOrError.disposition.action -cne 'REJECT' -or
        $queuedLateBadQueueOrError.disposition.retry_eligible -or
        $queuedLateBadQueueOrError.disposition.fixture_write_count -ne 0) {
      $queuedLateQueueOrErrorRejected = $false
    }
  }
  foreach ($queuedLateOfficialQueueKey in @('pga','prq','ptq','pvs1')) {
    $queuedLateOfficialQueueOverrides = @{
      d7pb=[uint64]5;pgq=[uint64]0
    }
    $queuedLateOfficialQueueOverrides[$queuedLateOfficialQueueKey] =
        [uint64]1
    $queuedLateBadOfficialQueue = & $evaluateSilentPreRequestRace `
        -OfficialVehicleOverrides $queuedLateOfficialQueueOverrides `
        -CurrentVehicleOverrides @{
          pgq=[uint64]1;pga=[uint64]0;d7pb=[uint64]0
        }
    if ($queuedLateBadOfficialQueue.disposition.action -cne 'REJECT' -or
        $queuedLateBadOfficialQueue.disposition.retry_eligible -or
        $queuedLateBadOfficialQueue.disposition.fixture_write_count -ne 0) {
      $queuedLateQueueOrErrorRejected = $false
    }
  }
  Add-SelfCase 'pre_request_silent_stat_runtime_queued_other_queue_or_error_not_retryable' `
      $queuedLateQueueOrErrorRejected `
      'any non-exact current or official queue shape or related parser/drop error remains fail-closed'

  $queuedLateAttempt2 = & $evaluateSilentPreRequestRace `
      -OfficialVehicleOverrides @{d7pb=[uint64]5;pgq=[uint64]0} `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]0;d7pb=[uint64]0} `
      -AttemptNumber 2
  $queuedLateAttempt3 = & $evaluateSilentPreRequestRace `
      -OfficialVehicleOverrides @{d7pb=[uint64]5;pgq=[uint64]0} `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]0;d7pb=[uint64]0} `
      -AttemptNumber 3
  $queuedLateNoDeadline = & $evaluateSilentPreRequestRace `
      -OfficialVehicleOverrides @{d7pb=[uint64]5;pgq=[uint64]0} `
      -CurrentVehicleOverrides @{pgq=[uint64]1;pga=[uint64]0;d7pb=[uint64]0} `
      -RetryBudgetAvailable $false
  Add-SelfCase 'pre_request_silent_stat_runtime_queued_attempt_or_deadline_bounded_write0' `
      ($queuedLateAttempt2.disposition.action -ceq 'RETRY' -and
       $queuedLateAttempt3.disposition.action -ceq 'REJECT' -and
       $queuedLateAttempt3.disposition.retry_exhausted -and
       $queuedLateNoDeadline.disposition.action -ceq 'REJECT' -and
       $queuedLateNoDeadline.disposition.reason -ceq
         'shared_deadline_exhausted' -and
       ([int]$queuedLateExact.disposition.fixture_write_count +
        [int]$queuedLateAttempt2.disposition.fixture_write_count +
        [int]$queuedLateAttempt3.disposition.fixture_write_count +
        [int]$queuedLateNoDeadline.disposition.fixture_write_count) -eq 0) `
      'the queued race cannot extend the shared deadline, exceed attempt 2, or write fixture #21'
  Add-SelfCase 'pre_request_silent_stat_runtime_queued_retry_then_stable_pair_reacquisition' `
      ($queuedLateExact.disposition.action -ceq 'RETRY' -and
       $promotion.valid -and $promotion.skip_next_recovery_capture -and
       $cleanDisposition.action -ceq 'ACCEPT' -and
       ([int]$queuedLateExact.disposition.fixture_write_count +
        [int]$promotion.fixture_write_count +
        [int]$cleanDisposition.fixture_write_count) -eq 0) `
      'queued exact evidence reaches the existing drain and strict stable-pair path; only a later clean M0 may ACCEPT'

  $silentExact = & $evaluateSilentPreRequestRace
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_retryable' `
      ($silentExact.disposition.action -ceq 'RETRY' -and
       $silentExact.disposition.reason -ceq
         'exact_silent_inflight_STAT_RUNTIME_race' -and
       $silentExact.disposition.retry_eligible -and
       $silentExact.disposition.exact_silent_inflight_STAT_RUNTIME_race -and
       $silentExact.disposition.m0_event_count -eq 0 -and
       $silentExact.disposition.fixture_write_count -eq 0) `
      'silent M0 plus exact fresh +1 d722/pvok STAT_RUNTIME observer evidence authorizes only bounded stable-pair recovery'
  [object[]]$silentFailedChecks = @($silentExact.vehicle_gate.checks |
      Where-Object {-not $_.valid})
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_exact_failure_set' `
      (-not $silentExact.vehicle_gate.valid -and
       $silentFailedChecks.Count -eq 2 -and
       @($silentFailedChecks | Where-Object {
         $_.name -cnotin @('d722_stable','d722_rf22_reconciled')
       }).Count -eq 0 -and
       $silentExact.disposition.exact_silent_vehicle_failure_set) `
      'only the order-independent d722_stable plus d722_rf22_reconciled failure set can represent the silent race'

  [object[]]$silentReversedFailureChecks =
      [object[]]@($silentFailedChecks)
  [Array]::Reverse($silentReversedFailureChecks)
  $silentReversedFailureGate = [pscustomobject][ordered]@{
    valid=$false;checks=$silentReversedFailureChecks
  }
  $silentReordered = & $evaluateSilentPreRequestRace `
      -RaceVehicleGate $silentReversedFailureGate
  [object[]]$silentReorderedFailureNames =
      [object[]]@($silentReordered.disposition.failed_vehicle_check_names)
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_failure_set_order_independent_retryable' `
      ($silentReordered.disposition.action -ceq 'RETRY' -and
       $silentReordered.disposition.retry_eligible -and
       $silentReordered.disposition.exact_silent_vehicle_failure_set -and
       $silentReorderedFailureNames.Count -eq 2 -and
       $silentReorderedFailureNames[0] -ceq 'd722_rf22_reconciled' -and
       $silentReorderedFailureNames[1] -ceq 'd722_stable' -and
       $silentReordered.disposition.fixture_write_count -eq 0) `
      'the exact two-failure set remains retryable when its diagnostic order is reversed'

  $silentExactFailureGate = [pscustomobject][ordered]@{
    valid=$false;checks=[object[]]@($silentFailedChecks)
  }
  $silentOfficialBootZero = & $evaluateSilentPreRequestRace `
      -OfficialVehicleOverrides @{boot=[uint64]0} `
      -RaceVehicleGate $silentExactFailureGate
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_official_boot_zero_not_retryable' `
      ($silentOfficialBootZero.disposition.action -ceq 'REJECT' -and
       -not $silentOfficialBootZero.disposition.retry_eligible -and
       $silentOfficialBootZero.disposition.exact_silent_vehicle_failure_set -and
       -not $silentOfficialBootZero.disposition.silent_same_boot -and
       $silentOfficialBootZero.disposition.fixture_write_count -eq 0) `
      'an official boot value of zero invalidates the silent in-flight proof independently of the exact failure set'
  $silentCurrentBootZero = & $evaluateSilentPreRequestRace `
      -CurrentVehicleOverrides @{boot=[uint64]0} `
      -RaceVehicleGate $silentExactFailureGate
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_current_boot_zero_not_retryable' `
      ($silentCurrentBootZero.disposition.action -ceq 'REJECT' -and
       -not $silentCurrentBootZero.disposition.retry_eligible -and
       $silentCurrentBootZero.disposition.exact_silent_vehicle_failure_set -and
       -not $silentCurrentBootZero.disposition.silent_same_boot -and
       $silentCurrentBootZero.disposition.fixture_write_count -eq 0) `
      'a current boot value of zero invalidates the silent in-flight proof independently of the exact failure set'
  $silentBootChanged = & $evaluateSilentPreRequestRace `
      -CurrentVehicleOverrides @{boot=[uint64]95} `
      -RaceVehicleGate $silentExactFailureGate
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_boot_change_not_retryable' `
      ($silentBootChanged.disposition.action -ceq 'REJECT' -and
       -not $silentBootChanged.disposition.retry_eligible -and
       $silentBootChanged.disposition.exact_silent_vehicle_failure_set -and
       -not $silentBootChanged.disposition.silent_same_boot -and
       $silentBootChanged.disposition.fixture_write_count -eq 0) `
      'a boot change invalidates the silent in-flight proof independently of the exact failure set'

  $silentEpochIncompleteGate = [pscustomobject][ordered]@{
    valid=$true;parser_integrity=[pscustomobject]@{valid=$true}
    heartbeat=[pscustomobject]@{valid=$true;count=6}
    pre_request_backlog_gate=[pscustomobject]@{
      m0_epoch_completed=$false;m0_veto_events=@()
    }
  }
  $silentEpochIncomplete = & $evaluateSilentPreRequestRace `
      -RaceCausalGate $silentEpochIncompleteGate
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_m0_epoch_incomplete_not_retryable' `
      ($silentEpochIncomplete.disposition.action -ceq 'REJECT' -and
       -not $silentEpochIncomplete.disposition.retry_eligible -and
       -not $silentEpochIncomplete.disposition.m0_epoch_completed -and
       $silentEpochIncomplete.disposition.m0_event_count -eq 0 -and
       $silentEpochIncomplete.disposition.exact_silent_vehicle_failure_set -and
       $silentEpochIncomplete.disposition.fixture_write_count -eq 0) `
      'an incomplete M0 epoch remains fail-closed even with the exact silent failure set and no M0 event'

  [bool]$silentTupleOrFreshnessRejected = $true
  foreach ($tupleOverride in @(
      @{pvid='STAT_OTHER'},@{pvid='stat_runtime'},@{pvidx=[uint64]0},
      @{pvcnt=[uint64]931},@{pvtype=[uint64]9},@{pvsys=[uint64]2},
      @{pvcomp=[uint64]2},@{pvms=[uint64]100000},
      @{pvms=[uint64]110001})) {
    $tupleEvaluation = & $evaluateSilentPreRequestRace `
        -CurrentVehicleOverrides $tupleOverride
    if ($tupleEvaluation.disposition.action -cne 'REJECT' -or
        $tupleEvaluation.disposition.retry_eligible) {
      $silentTupleOrFreshnessRejected = $false
    }
  }
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_tuple_or_freshness_not_retryable' `
      $silentTupleOrFreshnessRejected `
      'observer ID/index/count/type/source mismatch or stale/future pvms remains fail-closed'

  [bool]$silentDeltaRejected = $true
  foreach ($deltaOverride in @(
      @{d722=[uint64]24},
      @{pvok=[uint64]22},@{pvok=[uint64]24})) {
    $deltaEvaluation = & $evaluateSilentPreRequestRace `
        -CurrentVehicleOverrides $deltaOverride
    if ($deltaEvaluation.disposition.action -cne 'REJECT' -or
        $deltaEvaluation.disposition.retry_eligible) {
      $silentDeltaRejected = $false
    }
  }
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_delta_not_one_not_retryable' `
      $silentDeltaRejected `
      'd722 and pvok must both be exactly +1 and remain observer-aligned'

  [bool]$silentQueueOrErrorRejected = $true
  foreach ($queueOrErrorOverride in @(
      @{pgq=[uint64]2},@{pga=[uint64]1},@{prq=[uint64]1},
      @{ptq=[uint64]1},@{pvs1=[uint64]1},@{d7pb=[uint64]1},
      @{ef=[uint64]1},
      @{pvbad=[uint64]1},@{pvov=[uint64]1},@{eo=[uint64]1},
      @{evo=[uint64]1},@{d7cr=[uint64]1})) {
    $queueOrErrorEvaluation = & $evaluateSilentPreRequestRace `
        -CurrentVehicleOverrides $queueOrErrorOverride
    if ($queueOrErrorEvaluation.disposition.action -cne 'REJECT' -or
        $queueOrErrorEvaluation.disposition.retry_eligible) {
      $silentQueueOrErrorRejected = $false
    }
  }
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_queue_or_error_not_retryable' `
      $silentQueueOrErrorRejected `
      'any non-exact scheduler/parser backlog or related error keeps the pre-request gate fail-closed'

  $silentParserBadGate = [pscustomobject][ordered]@{
    valid=$false;parser_integrity=[pscustomobject]@{valid=$false}
    heartbeat=[pscustomobject]@{valid=$true;count=6}
    pre_request_backlog_gate=[pscustomobject]@{
      m0_epoch_completed=$true;m0_veto_events=@()
    }
  }
  $silentHeartbeatBadGate = [pscustomobject][ordered]@{
    valid=$false;parser_integrity=[pscustomobject]@{valid=$true}
    heartbeat=[pscustomobject]@{valid=$false;count=1}
    pre_request_backlog_gate=[pscustomobject]@{
      m0_epoch_completed=$true;m0_veto_events=@()
    }
  }
  $silentParserBad = & $evaluateSilentPreRequestRace `
      -RaceCausalGate $silentParserBadGate
  $silentHeartbeatBad = & $evaluateSilentPreRequestRace `
      -RaceCausalGate $silentHeartbeatBadGate
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_parser_or_hb_not_retryable' `
      ($silentParserBad.disposition.action -ceq 'REJECT' -and
       -not $silentParserBad.disposition.retry_eligible -and
       $silentHeartbeatBad.disposition.action -ceq 'REJECT' -and
       -not $silentHeartbeatBad.disposition.retry_eligible) `
      'silent observer evidence cannot mask parser integrity or Heartbeat failure'

  $silentUnknownM0Event = [pscustomobject][ordered]@{
    classification='unknown_sentinel';anomaly_classes=@('unknown_sentinel')
    system_id=1;component_id=1;param_id='STAT_OTHER'
    param_id_hex='535441545F4F54484552000000000000'
    param_index=65535;param_count=932;param_type=6
  }
  $silentIndexedM0Event = [pscustomobject][ordered]@{
    classification='indexed';anomaly_classes=@();system_id=1;component_id=1
    param_id='P0000';param_id_hex='50303030300000000000000000000000'
    param_index=0;param_count=932;param_type=6
  }
  $silentM0EventCausalGate = [pscustomobject][ordered]@{
    valid=$false;parser_integrity=[pscustomobject]@{valid=$true}
    heartbeat=[pscustomobject]@{valid=$true;count=6}
    pre_request_backlog_gate=[pscustomobject]@{
      m0_epoch_completed=$true
      m0_veto_events=@($silentUnknownM0Event,$silentIndexedM0Event)
    }
  }
  $silentUnknownM0 = & $evaluateSilentPreRequestRace `
      -RaceCausalGate $silentM0EventCausalGate `
      -RaceM0Events @($silentUnknownM0Event)
  $silentIndexedM0 = & $evaluateSilentPreRequestRace `
      -RaceCausalGate $silentM0EventCausalGate `
      -RaceM0Events @($silentIndexedM0Event)
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_any_m0_event_not_retryable' `
      ($silentUnknownM0.disposition.action -ceq 'REJECT' -and
       -not $silentUnknownM0.disposition.retry_eligible -and
       $silentIndexedM0.disposition.action -ceq 'REJECT' -and
       -not $silentIndexedM0.disposition.retry_eligible) `
      'unknown or indexed M0 events remain a hard veto for the silent in-flight proof'

  $silentAttempt2 = & $evaluateSilentPreRequestRace -AttemptNumber 2
  $silentAttempt3 = & $evaluateSilentPreRequestRace -AttemptNumber 3
  $silentNoDeadline = & $evaluateSilentPreRequestRace `
      -AttemptNumber 1 -RetryBudgetAvailable $false
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_attempt_or_deadline_bounded_write0' `
      ($silentExact.disposition.action -ceq 'RETRY' -and
       $silentAttempt2.disposition.action -ceq 'RETRY' -and
       $silentAttempt3.disposition.action -ceq 'REJECT' -and
       $silentAttempt3.disposition.retry_exhausted -and
       $silentNoDeadline.disposition.action -ceq 'REJECT' -and
       $silentNoDeadline.disposition.reason -ceq 'shared_deadline_exhausted' -and
       ([int]$silentExact.disposition.fixture_write_count +
        [int]$silentAttempt2.disposition.fixture_write_count +
        [int]$silentAttempt3.disposition.fixture_write_count +
        [int]$silentNoDeadline.disposition.fixture_write_count) -eq 0) `
      'the silent race cannot extend the shared deadline, exceed attempt 2, or write fixture #21'
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_retry_then_clean_pass' `
      ($silentExact.disposition.action -ceq 'RETRY' -and
       $cleanDisposition.action -ceq 'ACCEPT' -and
       $silentExact.disposition.fixture_write_count -eq 0 -and
       $cleanDisposition.fixture_write_count -eq 0) `
      'the raced snapshot is discarded; only a strictly promoted stable pair followed by a clean M0 attempt may pass'

  # QUAL-010 R3 ended one CRC-valid STAT_RUNTIME frame exactly at the Ground
  # M0 boundary while Vehicle had already parsed that frame and had begun the
  # next D7 candidate.  Model the bounded 3 s parser epoch directly; no raw
  # file reread and no fixture write is involved in this evidence path.
  [string]$preM0TailPhase = 'pre_request_attempt_1_recovery_3s'
  $preM0TailState = New-ParamListState `
      -CaptureScope 'pre_request_readiness'
  [byte[]]$preM0TailPayload = New-ParamValuePayload `
      -ParamId 'STAT_RUNTIME' -Index 65535 -Count 932 -Type 6
  Add-ParamValuePayload -State $preM0TailState -Payload $preM0TailPayload `
      -SystemId 1 -ComponentId 1 -Sequence 22 -ElapsedMs 104999 `
      -RawStartOffset 1163 -RawEndOffsetExclusive 1200 `
      -ProducerPhase $preM0TailPhase -ProducerEpoch $preM0TailPhase
  $preM0TailIntegrity = [pscustomobject][ordered]@{
    valid=$true;unsupported=0;unsupported_flags=0;bad_payload_length=0
    bad_crc=0;noise_bytes=0;invalid_length=0;partial_buffer_bytes=0
    expected_length=0
  }
  $exactPreM0TailEvidence = [pscustomobject][ordered]@{
    schema_version=1;capture_scope='pre_request_readiness'
    producer_phase=$preM0TailPhase;producer_epoch=$preM0TailPhase
    requested_milliseconds=3000
    capture=[pscustomobject]@{
      requested_milliseconds=3000;completed_duration=$true;skipped=$false
    }
    completed_duration=$true;raw_start_offset=[long]1000
    raw_end_offset=[long]1200;raw_length_bytes=[long]200
    ground_raw_offset=[long]1200;integrity=$preM0TailIntegrity
    events=[object[]]@($preM0TailState.events.ToArray())
    valid=$true;fixture_write_count=0
  }
  $evaluatePartialD7pbTailRace = {
    param(
      [uint64]$CurrentD7pb = [uint64]1,
      [uint64]$OfficialD7pb = [uint64]0,
      [AllowNull()]$TailEvidence = $exactPreM0TailEvidence,
      [hashtable]$CurrentOverrides = @{},
      $RaceCausalGate = $silentCausalGate,
      [AllowEmptyCollection()][object[]]$RaceM0Events = @(),
      [long]$M0GroundRawOffset = 1200,
      [int]$AttemptNumber = 1,
      [bool]$RetryBudgetAvailable = $true
    )
    $currentTailOverrides = @{
      d7pb=$CurrentD7pb
    } + $CurrentOverrides
    return & $evaluateSilentPreRequestRace `
        -CurrentVehicleOverrides $currentTailOverrides `
        -OfficialVehicleOverrides @{d7pb=$OfficialD7pb} `
        -RaceCausalGate $RaceCausalGate -RaceM0Events $RaceM0Events `
        -RacePreM0TailEvidence $TailEvidence `
        -RaceM0GroundRawOffset $M0GroundRawOffset `
        -AttemptNumber $AttemptNumber `
        -RetryBudgetAvailable $RetryBudgetAvailable
  }

  $partialD7pbOne = & $evaluatePartialD7pbTailRace -CurrentD7pb 1
  $partialD7pb279 = & $evaluatePartialD7pbTailRace -CurrentD7pb 279
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_bounds_1_279_retry_only_write0' `
      ($partialD7pbOne.disposition.action -ceq 'RETRY' -and
       $partialD7pb279.disposition.action -ceq 'RETRY' -and
       $partialD7pbOne.disposition.reason -ceq
         'exact_pre_M0_tail_STAT_RUNTIME_race' -and
       $partialD7pb279.disposition.reason -ceq
         'exact_pre_M0_tail_STAT_RUNTIME_race' -and
       $partialD7pbOne.disposition.exact_pre_M0_tail_STAT_RUNTIME_race -and
       $partialD7pb279.disposition.exact_pre_M0_tail_STAT_RUNTIME_race -and
       ([int]$partialD7pbOne.disposition.fixture_write_count +
        [int]$partialD7pb279.disposition.fixture_write_count) -eq 0) `
      'only d7pb 1..279 with the exact sealed tail proof receives bounded RETRY and write0'

  $partialD7pb280 = & $evaluatePartialD7pbTailRace -CurrentD7pb 280
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_280_not_retryable' `
      ($partialD7pb280.disposition.action -ceq 'REJECT' -and
       -not $partialD7pb280.disposition.retry_eligible -and
       -not $partialD7pb280.disposition.silent_partial_d7pb_bounded -and
       $partialD7pb280.disposition.fixture_write_count -eq 0) `
      'a full-size or invalid D7 candidate cannot use the bounded partial-tail exception'

  $partialOfficialD7pbNonzero = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 1 -OfficialD7pb 1
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_official_d7pb_nonzero_not_retryable' `
      ($partialOfficialD7pbNonzero.disposition.action -ceq 'REJECT' -and
       -not $partialOfficialD7pbNonzero.disposition.retry_eligible -and
       -not $partialOfficialD7pbNonzero.disposition.silent_partial_d7pb_bounded -and
       $partialOfficialD7pbNonzero.disposition.fixture_write_count -eq 0) `
      'the official baseline must prove d7pb=0 before a later bounded partial can be attributed'

  # HB-DEADLINE-R7 observed a completed STAT_RUNTIME followed contiguously by
  # two CRC-valid Vehicle HEARTBEAT frames before M0.  Both the official and
  # current Vehicle snapshots had bounded partial D7 candidates.  This exact
  # wire shape may only discard the raced pair and RETRY; it must never ACCEPT
  # or write fixture #21.
  $r7TargetValidEvent = [pscustomobject][ordered]@{
    message_id=22;crc_valid=$true;sequence=22;system_id=1;component_id=1
    payload_length=25
    payload_hex=(ConvertTo-Hex -Bytes $preM0TailPayload)
    frame_version=2;signed=$false;raw_start_offset=[long]1163
    raw_end_offset_exclusive=[long]1200;phase=$preM0TailPhase
    producer_epoch=$preM0TailPhase
  }
  $r7HeartbeatBefore = [pscustomobject][ordered]@{
    message_id=0;crc_valid=$true;sequence=142;system_id=1;component_id=1
    payload_length=9;payload_hex='040000000B03010503'
    frame_version=2;signed=$false;raw_start_offset=[long]1142
    raw_end_offset_exclusive=[long]1163;phase=$preM0TailPhase
    producer_epoch=$preM0TailPhase
  }
  $r7HeartbeatOne = [pscustomobject][ordered]@{
    message_id=0;crc_valid=$true;sequence=210;system_id=1;component_id=1
    payload_length=9;payload_hex='040000000B03010503'
    frame_version=2;signed=$false;raw_start_offset=[long]1200
    raw_end_offset_exclusive=[long]1221;phase=$preM0TailPhase
    producer_epoch=$preM0TailPhase
  }
  $r7HeartbeatTwo = [pscustomobject][ordered]@{
    message_id=0;crc_valid=$true;sequence=242;system_id=1;component_id=1
    payload_length=9;payload_hex='040000000B03010503'
    frame_version=2;signed=$false;raw_start_offset=[long]1221
    raw_end_offset_exclusive=[long]1242;phase=$preM0TailPhase
    producer_epoch=$preM0TailPhase
  }
  $r7HeartbeatGapEvidence = $exactPreM0TailEvidence.PSObject.Copy()
  $r7HeartbeatGapEvidence.raw_start_offset = [long]1142
  $r7HeartbeatGapEvidence.raw_end_offset = [long]1242
  $r7HeartbeatGapEvidence.raw_length_bytes = [long]100
  $r7HeartbeatGapEvidence.ground_raw_offset = [long]1242
  Add-Member -InputObject $r7HeartbeatGapEvidence -NotePropertyName valid_events `
      -NotePropertyValue ([object[]]@(
        $r7HeartbeatBefore,$r7TargetValidEvent,$r7HeartbeatOne,
        $r7HeartbeatTwo)) -Force
  $r7HeartbeatGap = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 25 -OfficialD7pb 31 `
      -TailEvidence $r7HeartbeatGapEvidence -M0GroundRawOffset 1242
  Add-SelfCase 'pre_request_r7_stat_runtime_two_heartbeat_gap_prior_partial_retry_only_write0' `
      ($r7HeartbeatGap.disposition.action -ceq 'RETRY' -and
       $r7HeartbeatGap.disposition.reason -ceq
         'exact_pre_M0_tail_STAT_RUNTIME_heartbeat_gap_prior_partial_D7_race' -and
       $r7HeartbeatGap.disposition.exact_pre_M0_tail_STAT_RUNTIME_heartbeat_gap_prior_partial_D7_race -and
       $r7HeartbeatGap.disposition.pre_m0_tail_race_evidence.valid -and
       $r7HeartbeatGap.disposition.pre_m0_tail_race_evidence.boundary_mode -ceq
         'contiguous_vehicle_heartbeat_chain' -and
       $r7HeartbeatGap.disposition.pre_m0_tail_race_evidence.full_tail_wire_chain_exact -and
       $r7HeartbeatGap.disposition.pre_m0_tail_race_evidence.trailing_heartbeat_count -eq 2 -and
       $r7HeartbeatGap.disposition.fixture_write_count -eq 0) `
      'the exact R7 target-plus-two-heartbeat chain receives bounded RETRY only and write0'

  $r7NonHeartbeatGapEvidence = $r7HeartbeatGapEvidence.PSObject.Copy()
  $r7NonHeartbeatTwo = $r7HeartbeatTwo.PSObject.Copy()
  $r7NonHeartbeatTwo.message_id = 1
  $r7NonHeartbeatGapEvidence.valid_events = [object[]]@(
      $r7HeartbeatBefore,$r7TargetValidEvent,$r7HeartbeatOne,
      $r7NonHeartbeatTwo)
  $r7NonHeartbeatGap = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 25 -OfficialD7pb 31 `
      -TailEvidence $r7NonHeartbeatGapEvidence -M0GroundRawOffset 1242
  $r7BrokenSpanEvidence = $r7HeartbeatGapEvidence.PSObject.Copy()
  $r7BrokenHeartbeatTwo = $r7HeartbeatTwo.PSObject.Copy()
  $r7BrokenHeartbeatTwo.raw_start_offset = [long]1222
  $r7BrokenSpanEvidence.valid_events = [object[]]@(
      $r7HeartbeatBefore,$r7TargetValidEvent,$r7HeartbeatOne,
      $r7BrokenHeartbeatTwo)
  $r7BrokenSpan = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 25 -OfficialD7pb 31 `
      -TailEvidence $r7BrokenSpanEvidence -M0GroundRawOffset 1242
  $r7PayloadMismatchEvidence = $r7HeartbeatGapEvidence.PSObject.Copy()
  $r7PayloadMismatchTarget = $r7TargetValidEvent.PSObject.Copy()
  $r7PayloadMismatchTarget.payload_hex = ('00' * 25)
  $r7PayloadMismatchEvidence.valid_events = [object[]]@(
      $r7HeartbeatBefore,$r7PayloadMismatchTarget,$r7HeartbeatOne,
      $r7HeartbeatTwo)
  $r7PayloadMismatch = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 25 -OfficialD7pb 31 `
      -TailEvidence $r7PayloadMismatchEvidence -M0GroundRawOffset 1242
  Add-SelfCase 'pre_request_r7_gap_nonheartbeat_noncontiguous_or_payload_mismatch_not_retryable' `
      ($r7NonHeartbeatGap.disposition.action -ceq 'REJECT' -and
       -not $r7NonHeartbeatGap.disposition.retry_eligible -and
       $r7BrokenSpan.disposition.action -ceq 'REJECT' -and
       -not $r7BrokenSpan.disposition.retry_eligible -and
       $r7PayloadMismatch.disposition.action -ceq 'REJECT' -and
       -not $r7PayloadMismatch.disposition.retry_eligible -and
       ([int]$r7NonHeartbeatGap.disposition.fixture_write_count +
        [int]$r7BrokenSpan.disposition.fixture_write_count +
        [int]$r7PayloadMismatch.disposition.fixture_write_count) -eq 0) `
      'non-HEARTBEAT, raw-span holes, or target payload mismatch remain fail-closed'

  $r7FalseTargetCrcEvidence = $r7HeartbeatGapEvidence.PSObject.Copy()
  $r7FalseTargetCrc = $r7TargetValidEvent.PSObject.Copy()
  $r7FalseTargetCrc.crc_valid = $false
  $r7FalseTargetCrcEvidence.valid_events = [object[]]@(
      $r7HeartbeatBefore,$r7FalseTargetCrc,$r7HeartbeatOne,
      $r7HeartbeatTwo)
  $r7FalseTargetCrcResult = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 25 -OfficialD7pb 31 `
      -TailEvidence $r7FalseTargetCrcEvidence -M0GroundRawOffset 1242
  $r7FalseHeartbeatCrcEvidence = $r7HeartbeatGapEvidence.PSObject.Copy()
  $r7FalseHeartbeatCrc = $r7HeartbeatTwo.PSObject.Copy()
  $r7FalseHeartbeatCrc.crc_valid = $false
  $r7FalseHeartbeatCrcEvidence.valid_events = [object[]]@(
      $r7HeartbeatBefore,$r7TargetValidEvent,$r7HeartbeatOne,
      $r7FalseHeartbeatCrc)
  $r7FalseHeartbeatCrcResult = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 25 -OfficialD7pb 31 `
      -TailEvidence $r7FalseHeartbeatCrcEvidence -M0GroundRawOffset 1242
  $r7StringFalseCrcEvidence = $r7HeartbeatGapEvidence.PSObject.Copy()
  $r7StringFalseCrc = $r7TargetValidEvent.PSObject.Copy()
  $r7StringFalseCrc.crc_valid = 'false'
  $r7StringFalseCrcEvidence.valid_events = [object[]]@(
      $r7HeartbeatBefore,$r7StringFalseCrc,$r7HeartbeatOne,$r7HeartbeatTwo)
  $r7StringFalseCrcResult = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 25 -OfficialD7pb 31 `
      -TailEvidence $r7StringFalseCrcEvidence -M0GroundRawOffset 1242
  Add-SelfCase 'pre_request_r7_gap_crc_false_not_retryable' `
      ($r7FalseTargetCrcResult.disposition.action -ceq 'REJECT' -and
       -not $r7FalseTargetCrcResult.disposition.retry_eligible -and
       $r7FalseHeartbeatCrcResult.disposition.action -ceq 'REJECT' -and
       -not $r7FalseHeartbeatCrcResult.disposition.retry_eligible -and
       $r7StringFalseCrcResult.disposition.action -ceq 'REJECT' -and
       -not $r7StringFalseCrcResult.disposition.retry_eligible -and
       ([int]$r7FalseTargetCrcResult.disposition.fixture_write_count +
        [int]$r7FalseHeartbeatCrcResult.disposition.fixture_write_count +
        [int]$r7StringFalseCrcResult.disposition.fixture_write_count) -eq 0) `
      'Boolean false or string-false CRC cannot authorize the R7 retry'

  [bool]$r7NullWireRejectedWithoutThrow = $false
  try {
    $r7NullWireEvidence = $r7HeartbeatGapEvidence.PSObject.Copy()
    $r7NullWireEvidence.valid_events = [object[]]@(
        $r7HeartbeatBefore,$r7TargetValidEvent,$null,$r7HeartbeatTwo)
    $r7NullWireResult = & $evaluatePartialD7pbTailRace `
        -CurrentD7pb 25 -OfficialD7pb 31 `
        -TailEvidence $r7NullWireEvidence -M0GroundRawOffset 1242
    $r7NullPrefixEvidence = $r7HeartbeatGapEvidence.PSObject.Copy()
    $r7NullPrefixEvidence.valid_events = [object[]]@(
        $null,$r7TargetValidEvent,$r7HeartbeatOne,$r7HeartbeatTwo)
    $r7NullPrefixResult = & $evaluatePartialD7pbTailRace `
        -CurrentD7pb 25 -OfficialD7pb 31 `
        -TailEvidence $r7NullPrefixEvidence -M0GroundRawOffset 1242
    $r7NullWireRejectedWithoutThrow = (
        $r7NullWireResult.disposition.action -ceq 'REJECT' -and
        -not $r7NullWireResult.disposition.retry_eligible -and
        $r7NullWireResult.disposition.fixture_write_count -eq 0 -and
        $r7NullPrefixResult.disposition.action -ceq 'REJECT' -and
        -not $r7NullPrefixResult.disposition.retry_eligible -and
        $r7NullPrefixResult.disposition.fixture_write_count -eq 0)
  } catch {
    $r7NullWireRejectedWithoutThrow = $false
  }
  Add-SelfCase 'pre_request_r7_gap_null_event_rejected_without_throw' `
      $r7NullWireRejectedWithoutThrow `
      'null sealed-event input is handled as a write-zero REJECT rather than an exception'

  $r7MissingWireEvidence = $r7HeartbeatGapEvidence.PSObject.Copy()
  $r7MissingWireEvidence.PSObject.Properties.Remove('valid_events')
  $r7MissingWire = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 25 -OfficialD7pb 31 `
      -TailEvidence $r7MissingWireEvidence -M0GroundRawOffset 1242
  $r7BadBound = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 280 -OfficialD7pb 31 `
      -TailEvidence $r7HeartbeatGapEvidence -M0GroundRawOffset 1242
  Add-SelfCase 'pre_request_r7_gap_missing_wire_or_partial_bound_not_retryable' `
      ($r7MissingWire.disposition.action -ceq 'REJECT' -and
       -not $r7MissingWire.disposition.retry_eligible -and
       $r7BadBound.disposition.action -ceq 'REJECT' -and
       -not $r7BadBound.disposition.retry_eligible -and
       ([int]$r7MissingWire.disposition.fixture_write_count +
        [int]$r7BadBound.disposition.fixture_write_count) -eq 0) `
      'missing wire evidence or an out-of-range D7 candidate cannot use the R7 exception'

  $r7D6CrcError = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 25 -OfficialD7pb 31 `
      -TailEvidence $r7HeartbeatGapEvidence -M0GroundRawOffset 1242 `
      -CurrentOverrides @{d6cr=[uint64]1}
  Add-SelfCase 'pre_request_r7_gap_any_crc_error_not_retryable' `
      ($r7D6CrcError.disposition.action -ceq 'REJECT' -and
       -not $r7D6CrcError.disposition.retry_eligible -and
       $r7D6CrcError.disposition.fixture_write_count -eq 0) `
      'an otherwise exact R7 wire shape with any diagnostic CRC error remains fail-closed'

  $r7AttemptThree = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 25 -OfficialD7pb 31 `
      -TailEvidence $r7HeartbeatGapEvidence -M0GroundRawOffset 1242 `
      -AttemptNumber 3
  $r7NoDeadline = & $evaluatePartialD7pbTailRace `
      -CurrentD7pb 25 -OfficialD7pb 31 `
      -TailEvidence $r7HeartbeatGapEvidence -M0GroundRawOffset 1242 `
      -RetryBudgetAvailable $false
  Add-SelfCase 'pre_request_r7_gap_attempt_deadline_bounded_write0' `
      ($r7AttemptThree.disposition.action -ceq 'REJECT' -and
       $r7AttemptThree.disposition.retry_exhausted -and
       $r7NoDeadline.disposition.action -ceq 'REJECT' -and
       $r7NoDeadline.disposition.reason -ceq 'shared_deadline_exhausted' -and
       ([int]$r7AttemptThree.disposition.fixture_write_count +
        [int]$r7NoDeadline.disposition.fixture_write_count) -eq 0) `
      'the R7 wire-proven retry remains bounded by max attempts and the shared deadline'

  $incompleteTailEvidence = $exactPreM0TailEvidence.PSObject.Copy()
  $incompleteTailEvidence.completed_duration = $false
  $incompleteTailEvidence.valid = $false
  $partialIncompleteTail = & $evaluatePartialD7pbTailRace `
      -TailEvidence $incompleteTailEvidence
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_pre_m0_tail_capture_incomplete_not_retryable' `
      ($partialIncompleteTail.disposition.action -ceq 'REJECT' -and
       -not $partialIncompleteTail.disposition.retry_eligible -and
       -not $partialIncompleteTail.disposition.pre_m0_tail_race_evidence.valid -and
       $partialIncompleteTail.disposition.fixture_write_count -eq 0) `
      'an incomplete 3 s pre-M0 epoch cannot prove the boundary race'

  $partialMissingTail = & $evaluatePartialD7pbTailRace -TailEvidence $null
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_pre_m0_tail_missing_not_retryable' `
      ($partialMissingTail.disposition.action -ceq 'REJECT' -and
       -not $partialMissingTail.disposition.retry_eligible -and
       -not $partialMissingTail.disposition.pre_m0_tail_race_evidence.valid -and
       $partialMissingTail.disposition.fixture_write_count -eq 0) `
      'missing tail evidence is fail-closed'

  $multipleTailEvidence = $exactPreM0TailEvidence.PSObject.Copy()
  $multipleTailEvidence.events = [object[]]@(
      $preM0TailState.events[0],$preM0TailState.events[0])
  $partialMultipleTail = & $evaluatePartialD7pbTailRace `
      -TailEvidence $multipleTailEvidence
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_pre_m0_tail_multiple_not_retryable' `
      ($partialMultipleTail.disposition.action -ceq 'REJECT' -and
       -not $partialMultipleTail.disposition.retry_eligible -and
       -not $partialMultipleTail.disposition.pre_m0_tail_race_evidence.valid -and
       $partialMultipleTail.disposition.fixture_write_count -eq 0) `
      'the sealed tail must contain exactly one PARAM_VALUE event'

  $crcInvalidTailEvent = $preM0TailState.events[0].PSObject.Copy()
  $crcInvalidTailEvent.crc_valid = $false
  $crcInvalidTailEvidence = $exactPreM0TailEvidence.PSObject.Copy()
  $crcInvalidTailEvidence.events = [object[]]@($crcInvalidTailEvent)
  $partialCrcInvalidTail = & $evaluatePartialD7pbTailRace `
      -TailEvidence $crcInvalidTailEvidence
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_pre_m0_tail_crc_invalid_not_retryable' `
      ($partialCrcInvalidTail.disposition.action -ceq 'REJECT' -and
       -not $partialCrcInvalidTail.disposition.retry_eligible -and
       -not $partialCrcInvalidTail.disposition.pre_m0_tail_race_evidence.valid -and
       $partialCrcInvalidTail.disposition.fixture_write_count -eq 0) `
      'the explicit CRC-valid fact is mandatory for tail correlation'

  $invalidTailIntegrity = $preM0TailIntegrity.PSObject.Copy()
  $invalidTailIntegrity.valid = $false
  $invalidTailIntegrity.partial_buffer_bytes = 1
  $parserInvalidTailEvidence = $exactPreM0TailEvidence.PSObject.Copy()
  $parserInvalidTailEvidence.integrity = $invalidTailIntegrity
  $parserInvalidTailEvidence.valid = $false
  $partialParserInvalidTail = & $evaluatePartialD7pbTailRace `
      -TailEvidence $parserInvalidTailEvidence
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_pre_m0_tail_parser_integrity_not_clean_not_retryable' `
      ($partialParserInvalidTail.disposition.action -ceq 'REJECT' -and
       -not $partialParserInvalidTail.disposition.retry_eligible -and
       -not $partialParserInvalidTail.disposition.pre_m0_tail_race_evidence.valid -and
       $partialParserInvalidTail.disposition.fixture_write_count -eq 0) `
      'partial/noise/CRC parser integrity faults in the tail remain fail-closed'

  $rangeInvalidTailEvent = $preM0TailState.events[0].PSObject.Copy()
  $rangeInvalidTailEvent.raw_start_offset = [long]999
  $rangeInvalidTailEvidence = $exactPreM0TailEvidence.PSObject.Copy()
  $rangeInvalidTailEvidence.events = [object[]]@($rangeInvalidTailEvent)
  $partialRangeInvalidTail = & $evaluatePartialD7pbTailRace `
      -TailEvidence $rangeInvalidTailEvidence
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_pre_m0_tail_raw_range_invalid_not_retryable' `
      ($partialRangeInvalidTail.disposition.action -ceq 'REJECT' -and
       -not $partialRangeInvalidTail.disposition.retry_eligible -and
       -not $partialRangeInvalidTail.disposition.pre_m0_tail_race_evidence.valid -and
       $partialRangeInvalidTail.disposition.fixture_write_count -eq 0) `
      'the complete frame must lie inside the sealed start/end raw range'

  $partialSequenceMismatch = & $evaluatePartialD7pbTailRace `
      -CurrentOverrides @{pvseq=[uint64]23}
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_pre_m0_tail_sequence_mismatch_not_retryable' `
      ($partialSequenceMismatch.disposition.action -ceq 'REJECT' -and
       -not $partialSequenceMismatch.disposition.retry_eligible -and
       -not $partialSequenceMismatch.disposition.pre_m0_tail_race_evidence.valid -and
       $partialSequenceMismatch.disposition.fixture_write_count -eq 0) `
      'Ground tail MAVLink sequence must equal the Vehicle pvseq observer'

  [bool]$partialTupleMismatchRejected = $true
  foreach ($tailTupleOverride in @(
      @{pvid='STAT_OTHER'},@{pvval='DEADBEEF'},@{pvidx=[uint64]0},
      @{pvcnt=[uint64]931},@{pvtype=[uint64]9})) {
    $partialTupleMismatch = & $evaluatePartialD7pbTailRace `
        -CurrentOverrides $tailTupleOverride
    if ($partialTupleMismatch.disposition.action -cne 'REJECT' -or
        $partialTupleMismatch.disposition.retry_eligible -or
        $partialTupleMismatch.disposition.fixture_write_count -ne 0) {
      $partialTupleMismatchRejected = $false
    }
  }
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_pre_m0_tail_tuple_mismatch_not_retryable' `
      $partialTupleMismatchRejected `
      'ID/value/index/count/type must all match the Vehicle observer exactly'

  $sourceMismatchTailEvent = $preM0TailState.events[0].PSObject.Copy()
  $sourceMismatchTailEvent.system_id = 2
  $sourceMismatchTailEvidence = $exactPreM0TailEvidence.PSObject.Copy()
  $sourceMismatchTailEvidence.events = [object[]]@($sourceMismatchTailEvent)
  $partialSourceMismatchTail = & $evaluatePartialD7pbTailRace `
