  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_pre_m0_tail_source_mismatch_not_retryable' `
      ($partialSourceMismatchTail.disposition.action -ceq 'REJECT' -and
       -not $partialSourceMismatchTail.disposition.retry_eligible -and
       -not $partialSourceMismatchTail.disposition.pre_m0_tail_race_evidence.valid -and
       $partialSourceMismatchTail.disposition.fixture_write_count -eq 0) `
      'tail source system/component must equal the Vehicle observer and Pixhawk 1/1'

  $boundaryMismatchTailEvent = $preM0TailState.events[0].PSObject.Copy()
  $boundaryMismatchTailEvent.raw_end_offset_exclusive = [long]1199
  $boundaryMismatchTailEvidence = $exactPreM0TailEvidence.PSObject.Copy()
  $boundaryMismatchTailEvidence.events = [object[]]@($boundaryMismatchTailEvent)
  $partialBoundaryMismatchTail = & $evaluatePartialD7pbTailRace `
      -TailEvidence $boundaryMismatchTailEvidence
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_pre_m0_tail_boundary_mismatch_not_retryable' `
      ($partialBoundaryMismatchTail.disposition.action -ceq 'REJECT' -and
       -not $partialBoundaryMismatchTail.disposition.retry_eligible -and
       -not $partialBoundaryMismatchTail.disposition.pre_m0_tail_race_evidence.valid -and
       $partialBoundaryMismatchTail.disposition.fixture_write_count -eq 0) `
      'the one complete frame must end exactly at the M0 Ground barrier'

  $tailM0EventCausalGate = [pscustomobject][ordered]@{
    valid=$false;parser_integrity=[pscustomobject]@{valid=$true}
    heartbeat=[pscustomobject]@{valid=$true;count=6}
    pre_request_backlog_gate=[pscustomobject]@{
      m0_epoch_completed=$true
      m0_veto_events=[object[]]@($preM0TailState.events[0])
    }
  }
  $partialM0Event = & $evaluatePartialD7pbTailRace `
      -RaceCausalGate $tailM0EventCausalGate `
      -RaceM0Events ([object[]]@($preM0TailState.events[0]))
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_pre_m0_tail_m0_event_nonzero_not_retryable' `
      ($partialM0Event.disposition.action -ceq 'REJECT' -and
       -not $partialM0Event.disposition.retry_eligible -and
       -not $partialM0Event.disposition.pre_m0_tail_race_evidence.valid -and
       $partialM0Event.disposition.fixture_write_count -eq 0) `
      'any M0 PARAM_VALUE event remains a veto; the exception is pre-M0 only'

  $partialAttempt2 = & $evaluatePartialD7pbTailRace -AttemptNumber 2
  $partialAttempt3 = & $evaluatePartialD7pbTailRace -AttemptNumber 3
  $partialNoDeadline = & $evaluatePartialD7pbTailRace `
      -RetryBudgetAvailable $false
  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_attempt_or_deadline_bounded_write0' `
      ($partialAttempt2.disposition.action -ceq 'RETRY' -and
       $partialAttempt3.disposition.action -ceq 'REJECT' -and
       $partialAttempt3.disposition.retry_exhausted -and
       $partialNoDeadline.disposition.action -ceq 'REJECT' -and
       $partialNoDeadline.disposition.reason -ceq 'shared_deadline_exhausted' -and
       ([int]$partialAttempt2.disposition.fixture_write_count +
        [int]$partialAttempt3.disposition.fixture_write_count +
        [int]$partialNoDeadline.disposition.fixture_write_count) -eq 0) `
      'the exact tail race shares the existing max-three/deadline bounds and cannot write fixture #21'

  Add-SelfCase 'pre_request_silent_stat_runtime_inflight_partial_d7pb_retry_then_clean_d7pb0_accept' `
      ($partialD7pbOne.disposition.action -ceq 'RETRY' -and
       $cleanDisposition.action -ceq 'ACCEPT' -and
       $partialD7pbOne.disposition.fixture_write_count -eq 0 -and
       $cleanDisposition.fixture_write_count -eq 0) `
      'partial-tail evidence can only RETRY; a later strict d7pb0 clean M0 gate is required for ACCEPT'

  # QUAL-011 R2 attempt 2 observed one complete known STAT_RUNTIME in M0 and
  # then sampled a bounded partial D7 shadow.  The complete event and Vehicle
  # observer must correlate exactly; the partial shadow is never accepted.
  $observedPartialState = New-ParamListState -CaptureScope 'pre_request_m0'
  [byte[]]$observedPartialPayload = New-ParamValuePayload `
      -ParamId 'STAT_RUNTIME' -Index 65535 -Count 932 -Type 6
  Add-ParamValuePayload -State $observedPartialState `
      -Payload $observedPartialPayload -SystemId 1 -ComponentId 1 `
      -Sequence 119 -ElapsedMs 5000 -RawStartOffset 1218 `
      -RawEndOffsetExclusive 1255 -ProducerPhase 'M0_pre_request_clean_5s' `
      -ProducerEpoch 'M0_pre_request_clean_5s'
  [object[]]$observedPartialEvents =
      [object[]]@($observedPartialState.events.ToArray())
  $newObservedPartialCausalGate = {
    param(
      [Parameter(Mandatory=$true)]
      [AllowEmptyCollection()][object[]]$Events,
      [bool]$Valid = $false,
      [bool]$ParserValid = $true,
      [bool]$HeartbeatValid = $true,
      [int]$HeartbeatCount = 6,
      [bool]$M0Completed = $true,
      [bool]$ParserBufferEmpty = $true,
      [int]$TargetCount = -1,
      [int]$KnownCount = -1
    )
    if ($TargetCount -lt 0) { $TargetCount = $Events.Count }
    if ($KnownCount -lt 0) {
      $KnownCount = @($Events | Where-Object {
        $_.classification -ceq 'known_STAT_RUNTIME_sentinel'
      }).Count
    }
    return [pscustomobject][ordered]@{
      valid=$Valid
      parser_integrity=[pscustomobject]@{valid=$ParserValid}
      target_param_value_count=$TargetCount
      parser_buffer_empty=$ParserBufferEmpty
      heartbeat=[pscustomobject]@{valid=$HeartbeatValid;count=$HeartbeatCount}
      pre_request_backlog_gate=[pscustomobject][ordered]@{
        m0_epoch_completed=$M0Completed;valid=$false
        veto_event_count=$Events.Count;stale_param_value_count=$Events.Count
        stale_generic_count=0;known_stat_runtime_sentinel_count=$KnownCount
        m0_event_count=$Events.Count;m0_veto_events=$Events
      }
      m0_ground_raw_offset=[long]1200
      m0_gate_end_ground_raw_offset=[long]1300
    }
  }
  $evaluateObservedPartialRace = {
    param(
      [AllowEmptyCollection()][object[]]$RaceEvents = $observedPartialEvents,
      [hashtable]$CurrentOverrides = @{},
      [hashtable]$OfficialOverrides = @{},
      [AllowNull()]$RaceCausalGate = $null,
      [int]$AttemptNumber = 2,
      [bool]$RetryBudgetAvailable = $true,
      [long]$M0GroundRawOffset = 1200,
      [long]$M0GateEndGroundRawOffset = 1300
    )
    $currentObservedPartialOverrides = @{
      d7pb=[uint64]14;pvseq=[uint64]119
    }
    foreach ($observedPartialKey in $CurrentOverrides.Keys) {
      $currentObservedPartialOverrides[$observedPartialKey] =
          $CurrentOverrides[$observedPartialKey]
    }
    $officialObservedPartialOverrides = @{d7pb=[uint64]0}
    foreach ($observedPartialKey in $OfficialOverrides.Keys) {
      $officialObservedPartialOverrides[$observedPartialKey] =
          $OfficialOverrides[$observedPartialKey]
    }
    $effectiveCausalGate = if ($null -ne $RaceCausalGate) {
      $RaceCausalGate
    } else {
      & $newObservedPartialCausalGate -Events $RaceEvents
    }
    return & $evaluateSilentPreRequestRace `
        -CurrentVehicleOverrides $currentObservedPartialOverrides `
        -OfficialVehicleOverrides $officialObservedPartialOverrides `
        -RaceCausalGate $effectiveCausalGate -RaceM0Events $RaceEvents `
        -RaceM0GroundRawOffset $M0GroundRawOffset `
        -RaceM0GateEndGroundRawOffset $M0GateEndGroundRawOffset `
        -AttemptNumber $AttemptNumber `
        -RetryBudgetAvailable $RetryBudgetAvailable
  }

  $observedPartialExact = & $evaluateObservedPartialRace
  [bool]$observedPartialProofFieldsPresent = (
      $observedPartialExact.disposition.PSObject.Properties.Name -ccontains
        'exact_observed_STAT_RUNTIME_partial_D7_race' -and
      $observedPartialExact.disposition.PSObject.Properties.Name -ccontains
        'observed_partial_event_evidence')
  Add-SelfCase 'pre_request_observed_stat_runtime_partial_d7_shadow_retryable' `
      ($observedPartialExact.disposition.action -ceq 'RETRY' -and
       $observedPartialExact.disposition.reason -ceq
         'exact_observed_STAT_RUNTIME_partial_D7_race' -and
       $observedPartialExact.disposition.retry_eligible -and
       $observedPartialProofFieldsPresent -and
       [bool]$observedPartialExact.disposition.exact_observed_STAT_RUNTIME_partial_D7_race -and
       $observedPartialExact.disposition.fixture_write_count -eq 0) `
      'one exact M0 STAT_RUNTIME correlated to the Vehicle observer plus d7pb 1..279 receives RETRY only'
  [object[]]$observedPartialFailedChecks = @(
      $observedPartialExact.vehicle_gate.checks | Where-Object {-not $_.valid})
  Add-SelfCase 'pre_request_observed_stat_runtime_partial_d7_exact_failure_and_correlation' `
      ($observedPartialFailedChecks.Count -eq 3 -and
       $observedPartialFailedChecks.name -ccontains 'd722_stable' -and
       $observedPartialFailedChecks.name -ccontains 'd722_rf22_reconciled' -and
       $observedPartialFailedChecks.name -ccontains 'd7pb_empty' -and
       $observedPartialProofFieldsPresent -and
       [bool]$observedPartialExact.disposition.observed_partial_event_evidence.valid -and
       $observedPartialExact.disposition.fixture_write_count -eq 0) `
      'the failure set and complete M0 event-to-observer correlation are exact and order-independent'

  [bool]$observedPartialEventShapeRejected = $true
  foreach ($eventOverride in @(
      @{crc_valid=$false},@{message_id=23},@{payload_length=24},
      @{param_id='STAT_OTHER'},@{param_id_hex='00'},
      @{param_value_hex='DEADBEEF'},@{param_value_bits_hex='DEADBEEF'},
      @{param_count=931},@{param_type=9},@{system_id=2},
      @{component_id=2},@{sequence=120},@{capture_scope='official'},
      @{producer_phase='other'},@{producer_epoch='other'},
      @{raw_start_offset=[long]1199},@{raw_end_offset_exclusive=[long]1218},
      @{raw_end_offset_exclusive=[long]1254},
      @{raw_start_offset=[long]1264;raw_end_offset_exclusive=[long]1301})) {
    $badObservedPartialEvent = $observedPartialEvents[0].PSObject.Copy()
    foreach ($eventKey in $eventOverride.Keys) {
      $badObservedPartialEvent.$eventKey = $eventOverride[$eventKey]
    }
    [object[]]$badObservedPartialEvents = @($badObservedPartialEvent)
    $badObservedPartial = & $evaluateObservedPartialRace `
        -RaceEvents $badObservedPartialEvents
    if ($badObservedPartial.disposition.action -cne 'REJECT' -or
        $badObservedPartial.disposition.retry_eligible -or
        $badObservedPartial.disposition.fixture_write_count -ne 0) {
      $observedPartialEventShapeRejected = $false
    }
  }
  Add-SelfCase 'pre_request_observed_stat_runtime_partial_d7_event_shape_not_retryable' `
      $observedPartialEventShapeRejected `
      'CRC/message/length/ID/value/count/type/source/sequence/scope/epoch/raw-range mismatch remains fail-closed'

  $unknownObservedPartialEvent = $observedPartialEvents[0].PSObject.Copy()
  $unknownObservedPartialEvent.classification = 'unknown_sentinel'
  $unknownObservedPartialEvent.anomaly_classes = @('unknown_sentinel')
  $unknownObservedPartial = & $evaluateObservedPartialRace `
      -RaceEvents ([object[]]@($unknownObservedPartialEvent))
  $indexedObservedPartialEvent = $observedPartialEvents[0].PSObject.Copy()
  $indexedObservedPartialEvent.classification = 'indexed'
  $indexedObservedPartialEvent.param_index = 0
  $indexedObservedPartial = & $evaluateObservedPartialRace `
      -RaceEvents ([object[]]@($indexedObservedPartialEvent))
  $multipleObservedPartial = & $evaluateObservedPartialRace `
      -RaceEvents ([object[]]@(
        $observedPartialEvents[0],$observedPartialEvents[0]))
  Add-SelfCase 'pre_request_observed_stat_runtime_partial_d7_unknown_indexed_multiple_not_retryable' `
      ($unknownObservedPartial.disposition.action -ceq 'REJECT' -and
       -not $unknownObservedPartial.disposition.retry_eligible -and
       $indexedObservedPartial.disposition.action -ceq 'REJECT' -and
       -not $indexedObservedPartial.disposition.retry_eligible -and
       $multipleObservedPartial.disposition.action -ceq 'REJECT' -and
       -not $multipleObservedPartial.disposition.retry_eligible -and
       ([int]$unknownObservedPartial.disposition.fixture_write_count +
        [int]$indexedObservedPartial.disposition.fixture_write_count +
        [int]$multipleObservedPartial.disposition.fixture_write_count) -eq 0) `
      'unknown, indexed, anomalous, or multiple M0 PARAM_VALUE events remain a hard veto'

  [object[]]$badObservedPartialCausalGates = @(
      (& $newObservedPartialCausalGate -Events $observedPartialEvents `
        -Valid $true),
      (& $newObservedPartialCausalGate -Events $observedPartialEvents `
        -ParserValid $false),
      (& $newObservedPartialCausalGate -Events $observedPartialEvents `
        -HeartbeatValid $false -HeartbeatCount 1),
      (& $newObservedPartialCausalGate -Events $observedPartialEvents `
        -M0Completed $false),
      (& $newObservedPartialCausalGate -Events $observedPartialEvents `
        -ParserBufferEmpty $false),
      (& $newObservedPartialCausalGate -Events $observedPartialEvents `
        -TargetCount 2),
      (& $newObservedPartialCausalGate -Events $observedPartialEvents `
        -KnownCount 0))
  [bool]$observedPartialCausalShapeRejected = $true
  foreach ($badObservedPartialCausalGate in $badObservedPartialCausalGates) {
    $badObservedPartialCausal = & $evaluateObservedPartialRace `
        -RaceCausalGate $badObservedPartialCausalGate
    if ($badObservedPartialCausal.disposition.action -cne 'REJECT' -or
        $badObservedPartialCausal.disposition.retry_eligible -or
        $badObservedPartialCausal.disposition.fixture_write_count -ne 0) {
      $observedPartialCausalShapeRejected = $false
    }
  }
  Add-SelfCase 'pre_request_observed_stat_runtime_partial_d7_causal_shape_not_retryable' `
      $observedPartialCausalShapeRejected `
      'causal-valid, parser/HB fault, incomplete M0, parser tail, or inconsistent exact-one counters remain fail-closed'

  [bool]$observedPartialObserverRejected = $true
  foreach ($observerOverride in @(
      @{boot=[uint64]95},@{d722=[uint64]24},@{pvok=[uint64]22},
      @{pvok=[uint64]24},@{pvid='STAT_OTHER'},@{pvval='DEADBEEF'},
      @{pvidx=[uint64]0},@{pvcnt=[uint64]931},@{pvtype=[uint64]9},
      @{pvseq=[uint64]120},@{pvsys=[uint64]2},@{pvcomp=[uint64]2},
      @{pvms=[uint64]100000},@{pvms=[uint64]110001})) {
    $badObservedPartialObserver = & $evaluateObservedPartialRace `
        -CurrentOverrides $observerOverride
    if ($badObservedPartialObserver.disposition.action -cne 'REJECT' -or
        $badObservedPartialObserver.disposition.retry_eligible -or
        $badObservedPartialObserver.disposition.fixture_write_count -ne 0) {
      $observedPartialObserverRejected = $false
    }
  }
  Add-SelfCase 'pre_request_observed_stat_runtime_partial_d7_observer_delta_not_retryable' `
      $observedPartialObserverRejected `
      'boot/delta/ID/value/index/count/type/sequence/source/freshness mismatch remains fail-closed'

  $observedPartialOne = & $evaluateObservedPartialRace `
      -CurrentOverrides @{d7pb=[uint64]1}
  $observedPartial279 = & $evaluateObservedPartialRace `
      -CurrentOverrides @{d7pb=[uint64]279}
  $observedPartial280 = & $evaluateObservedPartialRace `
      -CurrentOverrides @{d7pb=[uint64]280}
  $observedPartialOfficialNonzero = & $evaluateObservedPartialRace `
      -OfficialOverrides @{d7pb=[uint64]1}
  Add-SelfCase 'pre_request_observed_stat_runtime_partial_d7_bounds_and_official_empty' `
      ($observedPartialOne.disposition.action -ceq 'RETRY' -and
       $observedPartial279.disposition.action -ceq 'RETRY' -and
       $observedPartial280.disposition.action -ceq 'REJECT' -and
       -not $observedPartial280.disposition.retry_eligible -and
       $observedPartialOfficialNonzero.disposition.action -ceq 'REJECT' -and
       -not $observedPartialOfficialNonzero.disposition.retry_eligible -and
       ([int]$observedPartialOne.disposition.fixture_write_count +
        [int]$observedPartial279.disposition.fixture_write_count +
        [int]$observedPartial280.disposition.fixture_write_count +
        [int]$observedPartialOfficialNonzero.disposition.fixture_write_count) -eq 0) `
      'only current d7pb 1..279 after official d7pb=0 can use the partial-shadow exception'

  [bool]$observedPartialQueueOrErrorRejected = $true
  foreach ($queueOrErrorOverride in @(
      @{pgq=[uint64]1},@{pga=[uint64]1},@{prq=[uint64]1},
      @{ptq=[uint64]1},@{pvs1=[uint64]1},@{ef=[uint64]1},
      @{pvbad=[uint64]1},@{pvov=[uint64]1},@{eo=[uint64]1},
      @{evo=[uint64]1},@{d6cr=[uint64]1},@{d7cr=[uint64]1})) {
    $badObservedPartialQueue = & $evaluateObservedPartialRace `
        -CurrentOverrides $queueOrErrorOverride
    if ($badObservedPartialQueue.disposition.action -cne 'REJECT' -or
        $badObservedPartialQueue.disposition.retry_eligible -or
        $badObservedPartialQueue.disposition.fixture_write_count -ne 0) {
      $observedPartialQueueOrErrorRejected = $false
    }
  }
  Add-SelfCase 'pre_request_observed_stat_runtime_partial_d7_queue_or_error_not_retryable' `
      $observedPartialQueueOrErrorRejected `
      'any scheduler/proxy queue or parser/drop/CRC error remains fail-closed'

  $observedPartialAttempt3 = & $evaluateObservedPartialRace -AttemptNumber 3
  $observedPartialNoDeadline = & $evaluateObservedPartialRace `
      -RetryBudgetAvailable $false
  Add-SelfCase 'pre_request_observed_stat_runtime_partial_d7_attempt3_or_deadline_write0' `
      ($observedPartialExact.disposition.action -ceq 'RETRY' -and
       $observedPartialAttempt3.disposition.action -ceq 'REJECT' -and
       $observedPartialAttempt3.disposition.retry_exhausted -and
       $observedPartialNoDeadline.disposition.action -ceq 'REJECT' -and
       $observedPartialNoDeadline.disposition.reason -ceq
         'shared_deadline_exhausted' -and
       ([int]$observedPartialExact.disposition.fixture_write_count +
        [int]$observedPartialAttempt3.disposition.fixture_write_count +
        [int]$observedPartialNoDeadline.disposition.fixture_write_count) -eq 0) `
      'attempt 2 may RETRY, but recurrence at attempt 3 or exhausted shared deadline is final write-zero failure'
  $cleanDispositionAttempt3 = Get-PreRequestAttemptDisposition `
      -CausalGate $cleanCausalGate `
      -PreRequestVehicleGate $preRequestGateClean `
      -OfficialVehicle $offlineBaselineVehicle `
      -OfficialGround $offlineBaselineGround `
      -PreRequestVehicle $preRequestVehicleClean -M0Events @() `
      -AttemptNumber 3 -MaxAttempts 3 -RetryBudgetAvailable $true
  Add-SelfCase 'pre_request_observed_stat_runtime_partial_d7_retry_then_attempt3_clean_accept' `
      ($promotion.valid -and $promotion.skip_next_recovery_capture -and
       $observedPartialExact.disposition.action -ceq 'RETRY' -and
       $cleanDispositionAttempt3.action -ceq 'ACCEPT' -and
       ([int]$promotion.fixture_write_count +
        [int]$observedPartialExact.disposition.fixture_write_count +
        [int]$cleanDispositionAttempt3.fixture_write_count) -eq 0) `
      'skip-next timing is unchanged: exact attempt-2 race drains again and only a clean attempt 3 can ACCEPT'

  # R4 received the one known STAT_RUNTIME only after the completed five-second
  # M0 window, while the same pre_request_vehicle_N diagnostic was in flight.
  # The historical readiness rows remain audit-only.  This exact wire/observer
  # overlap may request the existing bounded stable-pair recovery, never ACCEPT.
  $postM0SnapshotState = New-ParamListState -CaptureScope 'pre_request_m0'
  Add-ParamValuePayload -State $postM0SnapshotState `
      -Payload $observedPartialPayload -SystemId 1 -ComponentId 1 `
      -Sequence 93 -ElapsedMs 8000 -RawStartOffset 2030 `
      -RawEndOffsetExclusive 2067 -ProducerPhase 'pre_request_vehicle_1' `
      -ProducerEpoch 'pre_request_vehicle_1'
  [object[]]$postM0SnapshotEvents =
      [object[]]@($postM0SnapshotState.events.ToArray())
  [object[]]$postM0HistoricalReadinessEvents = [object[]]@(
      [pscustomobject]@{classification='unknown_sentinel';sequence=16},
      [pscustomobject]@{classification='unknown_sentinel';sequence=17},
      [pscustomobject]@{classification='unknown_sentinel';sequence=18})
  $newPostM0SnapshotCausalGate = {
    param(
      [Parameter(Mandatory=$true)]
      [AllowEmptyCollection()][object[]]$Events,
      [bool]$ParserValid = $true,
      [bool]$HeartbeatValid = $true,
      [int]$HeartbeatCount = 6,
      [bool]$M0Completed = $true,
      [bool]$ParserBufferEmpty = $true,
      [string]$DecisionScope = 'fresh_m0_only',
      [bool]$ReadinessAuditOnly = $true,
      [int]$TargetCount = -1,
      [long]$M0RawStart = 1200,
      [long]$M0RawEnd = 2000
    )
    if ($TargetCount -lt 0) { $TargetCount = $Events.Count }
    [object[]]$allAuditEvents = [object[]]@(
        $postM0HistoricalReadinessEvents + $Events)
    return [pscustomobject][ordered]@{
      valid=$false;parser_integrity=[pscustomobject]@{valid=$ParserValid}
      target_param_value_count=$TargetCount
      parser_buffer_empty=$ParserBufferEmpty
      heartbeat=[pscustomobject]@{valid=$HeartbeatValid;count=$HeartbeatCount}
      pre_request_backlog_gate=[pscustomobject][ordered]@{
        decision_scope=$DecisionScope;m0_epoch_completed=$M0Completed
        valid=$false;veto_event_count=$Events.Count
        historical_readiness_event_count=$postM0HistoricalReadinessEvents.Count
        readiness_events_audit_only=$ReadinessAuditOnly
        stale_param_value_count=$allAuditEvents.Count
        stale_generic_count=$postM0HistoricalReadinessEvents.Count
        known_stat_runtime_sentinel_count=@($allAuditEvents | Where-Object {
          $_.classification -ceq 'known_STAT_RUNTIME_sentinel'
        }).Count
        readiness_event_count=$postM0HistoricalReadinessEvents.Count
        m0_event_count=$Events.Count;events=$allAuditEvents
        historical_readiness_events=$postM0HistoricalReadinessEvents
        m0_veto_events=$Events
      }
      m0_ground_raw_offset=$M0RawStart
      m0_gate_end_ground_raw_offset=$M0RawEnd
    }
  }
  $postM0SnapshotM0Capture = [pscustomobject][ordered]@{
    started_elapsed_ms=1000.0;requested_milliseconds=5000
    captured_milliseconds=5001.0;target_elapsed_ms=6000.0
    effective_end_elapsed_ms=6000.0;finished_elapsed_ms=6001.0
    completed_duration=$true;deadline_reached=$false;skipped=$false
    start_barrier=[pscustomobject][ordered]@{
      active=$true;ground_raw_offset_exclusive=[long]1200
      ground_boundary_elapsed_ms=999.0
    }
  }
  $postM0SnapshotEndBarrier = [pscustomobject][ordered]@{
    active=$true;ground_raw_offset_exclusive=[long]2500
    ground_boundary_elapsed_ms=9001.0
  }
  $evaluatePostM0SnapshotRace = {
    param(
      [AllowEmptyCollection()][object[]]$RaceEvents = $postM0SnapshotEvents,
      [hashtable]$CurrentOverrides = @{},
      [hashtable]$OfficialVehicleOverrides = @{},
      [hashtable]$OfficialGroundOverrides = @{},
      [AllowNull()]$RaceCausalGate = $null,
      [AllowNull()]$RaceM0Capture = $postM0SnapshotM0Capture,
      [AllowNull()]$RaceEndBarrier = $postM0SnapshotEndBarrier,
      [string]$RacePreRequestName = 'pre_request_vehicle_1',
      [double]$RaceSnapshotStartedMs = 7000.0,
      [double]$RaceSnapshotFinishedMs = 9000.0,
      [long]$RaceM0RawEnd = 2000,
      [int]$AttemptNumber = 1,
      [bool]$RetryBudgetAvailable = $true
    )
    $postM0Current = @{
      pgq=[uint64]1;pga=[uint64]0;prq=[uint64]0;ptq=[uint64]0
      pvs1=[uint64]0;d7pb=[uint64]3;pvseq=[uint64]93
    }
    foreach ($postM0Key in $CurrentOverrides.Keys) {
      $postM0Current[$postM0Key] = $CurrentOverrides[$postM0Key]
    }
    $postM0OfficialVehicle = @{
      pgq=[uint64]0;pga=[uint64]0;prq=[uint64]0;ptq=[uint64]0
      pvs1=[uint64]0;d7pb=[uint64]0
    }
    foreach ($postM0Key in $OfficialVehicleOverrides.Keys) {
      $postM0OfficialVehicle[$postM0Key] =
          $OfficialVehicleOverrides[$postM0Key]
    }
    $effectivePostM0CausalGate = if ($null -ne $RaceCausalGate) {
      $RaceCausalGate
    } else {
      & $newPostM0SnapshotCausalGate -Events $RaceEvents `
          -M0RawEnd $RaceM0RawEnd
    }
    return & $evaluateSilentPreRequestRace `
        -CurrentVehicleOverrides $postM0Current `
        -OfficialVehicleOverrides $postM0OfficialVehicle `
        -OfficialGroundOverrides $OfficialGroundOverrides `
        -RaceCausalGate $effectivePostM0CausalGate `
        -RaceM0Events $RaceEvents -RaceM0Capture $RaceM0Capture `
        -RaceDiagnosticEndBarrier $RaceEndBarrier `
        -RacePreRequestName $RacePreRequestName `
        -RacePreRequestStartedElapsedMs $RaceSnapshotStartedMs `
        -RacePreRequestFinishedElapsedMs $RaceSnapshotFinishedMs `
        -RaceM0GroundRawOffset 1200 -RaceM0GateEndGroundRawOffset $RaceM0RawEnd `
        -AttemptNumber $AttemptNumber `
        -RetryBudgetAvailable $RetryBudgetAvailable
  }

  $postM0SnapshotExact = & $evaluatePostM0SnapshotRace
  [object[]]$postM0SnapshotFailedNames = [object[]]@(
      $postM0SnapshotExact.disposition.failed_vehicle_check_names)
  Add-SelfCase 'pre_request_post_m0_same_vehicle_snapshot_stat_runtime_retryable' `
      ($postM0SnapshotExact.disposition.action -ceq 'RETRY' -and
       $postM0SnapshotExact.disposition.reason -ceq
         'exact_post_M0_vehicle_snapshot_STAT_RUNTIME_partial_D7_race' -and
       $postM0SnapshotExact.disposition.retry_eligible -and
       [bool]$postM0SnapshotExact.disposition.exact_post_M0_vehicle_snapshot_STAT_RUNTIME_partial_D7_race -and
       [bool]$postM0SnapshotExact.disposition.exact_post_M0_snapshot_event_evidence.valid -and
       [bool]$postM0SnapshotExact.disposition.exact_post_M0_official_idle_reconciled -and
       [bool]$postM0SnapshotExact.disposition.exact_post_M0_snapshot_scheduler_state -and
