       $postM0SnapshotFailedNames -ccontains 'd722_stable' -and
       $postM0SnapshotFailedNames -ccontains 'd722_rf22_reconciled' -and
       $postM0SnapshotFailedNames -ccontains 'pgq' -and
       $postM0SnapshotFailedNames -ccontains 'd7pb_empty' -and
       $postM0SnapshotExact.disposition.exact_post_M0_snapshot_event_evidence.fresh_m0_partition_exact -and
       $postM0SnapshotExact.disposition.fixture_write_count -eq 0) `
      'the exact four failures qualify while three historical readiness rows remain audit-only'

  [bool]$postM0SnapshotEventMismatchRejected = $true
  foreach ($postM0EventOverride in @(
      @{crc_valid=$false},@{message_id=23},@{payload_length=24},
      @{classification='unknown_sentinel';anomaly_classes=@('unknown_sentinel')},
      @{param_id='STAT_OTHER'},@{param_id_hex='00'},
      @{param_value_hex='DEADBEEF'},@{param_value_bits_hex='DEADBEEF'},
      @{param_index=0},@{param_count=931},@{param_type=9},
      @{system_id=2},@{component_id=2},@{sequence=94},
      @{capture_scope='official'},@{producer_phase='pre_request_vehicle_2'},
      @{producer_epoch='pre_request_vehicle_2'},@{elapsed_ms=6001.0},
      @{elapsed_ms=9001.0},@{raw_start_offset=[long]1999},
      @{raw_end_offset_exclusive=[long]2066},
      @{raw_start_offset=[long]2464;raw_end_offset_exclusive=[long]2501})) {
    $badPostM0Event = $postM0SnapshotEvents[0].PSObject.Copy()
    foreach ($postM0EventKey in $postM0EventOverride.Keys) {
      $badPostM0Event.$postM0EventKey = $postM0EventOverride[$postM0EventKey]
    }
    [object[]]$badPostM0Events = [object[]]@($badPostM0Event)
    $badPostM0EventResult = & $evaluatePostM0SnapshotRace `
        -RaceEvents $badPostM0Events
    if ($badPostM0EventResult.disposition.action -cne 'REJECT' -or
        $badPostM0EventResult.disposition.retry_eligible -or
        $badPostM0EventResult.disposition.fixture_write_count -ne 0) {
      $postM0SnapshotEventMismatchRejected = $false
    }
  }
  $postM0Multiple = & $evaluatePostM0SnapshotRace `
      -RaceEvents ([object[]]@($postM0SnapshotEvents[0],
        $postM0SnapshotEvents[0]))
  Add-SelfCase 'pre_request_post_m0_snapshot_wire_observer_boundary_mismatch_rejected' `
      ($postM0SnapshotEventMismatchRejected -and
       $postM0Multiple.disposition.action -ceq 'REJECT' -and
       -not $postM0Multiple.disposition.retry_eligible -and
       $postM0Multiple.disposition.fixture_write_count -eq 0) `
      'CRC/schema/ID/value/tuple/source/sequence/phase/raw/elapsed mismatch or multiple events remains fail-closed'

  [bool]$postM0SnapshotEnvelopeRejected = $true
  $badM0Captures = @(
    [pscustomobject]@{started_elapsed_ms=1000.0;requested_milliseconds=4999;
      target_elapsed_ms=5999.0;effective_end_elapsed_ms=5999.0;
      finished_elapsed_ms=6000.0;completed_duration=$true;deadline_reached=$false},
    [pscustomobject]@{started_elapsed_ms=1000.0;requested_milliseconds=5000;
      target_elapsed_ms=6000.0;effective_end_elapsed_ms=6000.0;
      finished_elapsed_ms=5999.0;completed_duration=$false;deadline_reached=$false},
    [pscustomobject]@{started_elapsed_ms=1000.0;requested_milliseconds=5000;
      target_elapsed_ms=6000.0;effective_end_elapsed_ms=6000.0;
      finished_elapsed_ms=6001.0;completed_duration=$true;deadline_reached=$true},
    [pscustomobject]@{started_elapsed_ms=1000.0;requested_milliseconds=5000;
      target_elapsed_ms=6000.0;effective_end_elapsed_ms=6000.0;
      finished_elapsed_ms=6001.0;completed_duration=$true;deadline_reached=$false;
      start_barrier=[pscustomobject]@{active=$true;
