      @{pgq=[uint64]2},@{pga=[uint64]1},@{prq=[uint64]1},
      @{ptq=[uint64]1},@{pvs1=[uint64]1},@{d7pb=[uint64]280},
      @{ef=[uint64]1},@{pvbad=[uint64]1},
