  }
  foreach ($postM0OfficialFault in @(
      @{OfficialVehicleOverrides=@{pgq=[uint64]1}},
      @{OfficialVehicleOverrides=@{d7pb=[uint64]1}},
      @{OfficialVehicleOverrides=@{pvok=[uint64]21}},
      @{OfficialVehicleOverrides=@{d7cr=[uint64]1}},
      @{OfficialGroundOverrides=@{rf22=[uint64]21}})) {
