    }
    $badPostM0Official = & $evaluatePostM0SnapshotRace @badOfficialArguments
    if ($badPostM0Official.disposition.action -cne 'REJECT' -or
        $badPostM0Official.disposition.retry_eligible -or
        $badPostM0Official.disposition.fixture_write_count -ne 0) {
      $postM0SnapshotStateFaultRejected = $false
    }
  }
  Add-SelfCase 'pre_request_post_m0_snapshot_state_or_baseline_fault_rejected' `
      $postM0SnapshotStateFaultRejected `
      'only idle/reconciled official state and exact +1 observer, pgq1/pga0/other-empty/d7pb1..279/error0 current state qualify'
  $postM0SnapshotD7pbZero = & $evaluatePostM0SnapshotRace `
      -CurrentOverrides @{d7pb=[uint64]0}
  Add-SelfCase 'pre_request_post_m0_snapshot_d7pb0_not_new_partial_classification' `
      (-not [bool]$postM0SnapshotD7pbZero.disposition.exact_post_M0_vehicle_snapshot_STAT_RUNTIME_partial_D7_race -and
       -not [bool]$postM0SnapshotD7pbZero.disposition.exact_post_M0_snapshot_vehicle_failure_set -and
       $postM0SnapshotD7pbZero.disposition.fixture_write_count -eq 0) `
      'd7pb=0 cannot enter the new partial-D7 classification; any pre-existing exact sentinel disposition remains independently bounded'

  $postM0SnapshotAttempt3 = & $evaluatePostM0SnapshotRace -AttemptNumber 3
  $postM0SnapshotNoDeadline = & $evaluatePostM0SnapshotRace `
      -RetryBudgetAvailable $false
  Add-SelfCase 'pre_request_post_m0_snapshot_attempt_and_deadline_bounded_write0' `
      ($postM0SnapshotExact.disposition.action -ceq 'RETRY' -and
       $postM0SnapshotAttempt3.disposition.action -ceq 'REJECT' -and
       $postM0SnapshotAttempt3.disposition.retry_exhausted -and
       $postM0SnapshotNoDeadline.disposition.action -ceq 'REJECT' -and
       $postM0SnapshotNoDeadline.disposition.reason -ceq
