  $directPreRequestMatcher = Get-SyncInvalidMatcherAtLatch -Role 'vehicle' `
      -DataPlaneReadiness $null -BacklogDrainGate $null `
      -BaselinePairGate $null -PreRequestPairGate $directPreRequestGateModel
  Add-SelfCase 'pre_request_direct_snapshot_invalid_sync_latched' `
      ($directPreRequestVehicleLatch.latched -and
       $directPreRequestPostPlan.any_sync_invalid -and
       -not $directPreRequestPostPlan.run_ground -and
       -not $directPreRequestPostPlan.run_vehicle -and
       $directPreRequestMatcher.pending_byte_count -eq
         $partialVehicleBytes.Length -and
       $directPreRequestGateModel.fixture_write_count -eq 0) `
      'a direct pre-request timeout latches synchronization invalid and suppresses both post diagnostic writes'
  $retryAnchorStart = New-OfflineSnapshot -Fields $vehicleBaseFields `
      -Q 5 -Ms ([uint64]1000)
  $retryBacklogVehicle = New-OfflineSnapshot -Fields $vehicleBaseFields `
      -Q 8 -Ms ([uint64]4000)
  $retryLatestVehicleAnchor = Select-LatestCompleteDiagnosticSnapshot `
      -CurrentSnapshot $retryAnchorStart `
      -CandidateSnapshot $retryBacklogVehicle
  Add-SelfCase 'post_vehicle_anchor_advances_through_retry_recovery_snapshots' `
      ($retryLatestVehicleAnchor.q_uint32 -eq 8 -and
       (Get-NextQueryId -Current `
         ([uint32]$retryLatestVehicleAnchor.q_uint32)) -eq 9) `
      'failure-path post q advances through the promoted complete backlog snapshot instead of reusing the stale pre-retry anchor'
  $modeledBaselineAnchor = New-OfflineSnapshot -Fields $vehicleBaseFields `
      -Q 5 -Ms ([uint64]1000)
  $modeledCompletePreRequest = New-OfflineSnapshot `
      -Fields $sentinelVehicleFields -Q 6 -Ms ([uint64]2000)
  $modeledPostVehicleAnchor = $modeledBaselineAnchor
  if ((Test-ReadinessSnapshotResponse -Snapshot $modeledCompletePreRequest `
      -ExpectedQ ([uint32]6)).valid) {
    $modeledPostVehicleAnchor = $modeledCompletePreRequest
  }
  [uint32]$modeledPostExpectedQ = Get-NextQueryId -Current `
      ([uint32]$modeledPostVehicleAnchor.q_uint32)
  Add-SelfCase 'post_vehicle_anchor_uses_latest_complete_pre_request' `
      ($modeledPostVehicleAnchor.q_uint32 -eq 6 -and
       $modeledPostExpectedQ -eq 7) `
      'failure-path post diagnostic expects q7 from the latest complete pre-request q6'
  $suppressedInjection = [pscustomobject][ordered]@{
    attempt_count=0;write_count=0;write_uncertain=$false
    write_disposition='NOT_ATTEMPTED'
  }
  $suppressedPostPlan = Get-PostDiagnosticPlan `
      -DataPlaneReadiness ([pscustomobject]@{sync_invalid=$false}) `
      -BacklogDrainGate ([pscustomobject]@{sync_invalid=$false}) `
      -BaselinePairGate ([pscustomobject]@{sync_invalid=$false}) `
      -PreRequestPairGate ([pscustomobject]@{sync_invalid=$false}) `
      -InjectionState $suppressedInjection
  $suppressedPostAssessment = New-RequestSuppressedPostAssessment `
      -PostDiagnosticPlan $suppressedPostPlan
  Add-SelfCase 'post_request_suppressed_assessment_not_run' `
      (-not $suppressedPostPlan.evaluate_success_contract -and
       $suppressedPostPlan.assessment_status -ceq
         'NOT_RUN_REQUEST_SUPPRESSED' -and
       -not $suppressedPostAssessment.applicable -and
       -not $suppressedPostAssessment.evaluated -and
       $suppressedPostAssessment.status -ceq
         'NOT_RUN_REQUEST_SUPPRESSED' -and
       $suppressedPostAssessment.failed_count -eq 0 -and
       $null -eq $suppressedPostAssessment.first_failed -and
       @($suppressedPostAssessment.checks).Count -eq 0) `
      'write-zero keeps complete post snapshots diagnostic-only and never evaluates the impossible +1/+932 success contract'
  Add-SelfCase 'post_request_suppressed_complete_snapshots_are_diagnostic_only' `
      ($offlinePostGround.status -ceq 'COMPLETE' -and
