  }
  $acknowledgedPostPlan = Get-PostDiagnosticPlan `
      -DataPlaneReadiness ([pscustomobject]@{sync_invalid=$false}) `
      -BacklogDrainGate ([pscustomobject]@{sync_invalid=$false}) `
      -BaselinePairGate ([pscustomobject]@{sync_invalid=$false}) `
