       -not $extra.assessment.valid) `
      'extra #22 does not prevent reaching the complete-plus-duplicate-guard state'

  $semanticStallState = New-ParamListState
  [byte[]]$semanticIndexZero = New-ParamValuePayload -ParamId 'P0000' -Index 0
  Add-ParamValuePayload -State $semanticStallState -Payload $semanticIndexZero `
      -SystemId 1 -ComponentId 1 -Sequence 0 -ElapsedMs 1000
  [double]$semanticStallAnchor =
      [double]$semanticStallState.last_accepted_elapsed_ms
  [byte[]]$semanticUnknown = New-ParamValuePayload -ParamId 'OTHER' `
      -Index 65535
  Add-ParamValuePayload -State $semanticStallState -Payload $semanticUnknown `
      -SystemId 1 -ComponentId 1 -Sequence 1 -ElapsedMs 2000
  $semanticStallDecision = Test-TimeoutDecision -ElapsedSeconds 121 `
      -StallSeconds 120 -Indexed ([int]$semanticStallState.unique_count)
  Add-SelfCase 'semantic_anomaly_does_not_reset_stall' `
      ([double]$semanticStallState.last_accepted_elapsed_ms -eq
        $semanticStallAnchor -and $semanticStallDecision.stall_timeout) `
      'semantic anomaly is recorded without resetting the existing expected-index stall clock'

  $f0State = New-ParamListState
  Add-ParamValuePayload -State $f0State -Payload $semanticUnknown `
      -SystemId 1 -ComponentId 1 -Sequence 23 -ElapsedMs 651064.672 `
      -RawStartOffset 12345 -RawEndOffsetExclusive 12382
  Add-ParamValuePayload -State $f0State -Payload $semanticUnknown `
      -SystemId 1 -ComponentId 1 -Sequence 24 -ElapsedMs 651100 `
      -RawStartOffset 12400 -RawEndOffsetExclusive 12437
  Add-SelfCase 'first_anomaly_metadata_frozen' `
      ($f0State.first_anomaly.anomaly_class -eq 'unknown_sentinel' -and
       [double]$f0State.first_anomaly.elapsed_ms -eq 651064.672 -and
       [long]$f0State.first_anomaly.raw_start_offset -eq 12345 -and
       [long]$f0State.first_anomaly.raw_end_offset_exclusive -eq 12382 -and
       [int]$f0State.first_anomaly.sequence -eq 23) `
      'F0 is immutable and carries class/time/raw span/sequence from the first anomaly'
  [bool]$capRefusedTruncation = $false
  $capState = New-ParamListState -MaxEventCount 1
  Add-ParamValuePayload -State $capState -Payload $semanticIndexZero `
      -SystemId 1 -ComponentId 1 -Sequence 0 -ElapsedMs 1
  try {
    [byte[]]$capIndexOne = New-ParamValuePayload -ParamId 'P0001' -Index 1
    Add-ParamValuePayload -State $capState -Payload $capIndexOne `
        -SystemId 1 -ComponentId 1 -Sequence 1 -ElapsedMs 2
  } catch {
    $capRefusedTruncation = $_.Exception.Message -match 'refusing truncation'
  }
  Add-SelfCase 'param_event_cap_truncation_error' `
      ($capRefusedTruncation -and $capState.events.Count -eq 1) `
      'bounded event evidence refuses silent truncation and escalates through ERROR handling'

  $cleanBacklog = Test-PreRequestBacklogGate -ReadinessEvents @() `
      -M0Events @() -M0EpochCompleted $true
  $readinessBacklog = Test-PreRequestBacklogGate `
      -ReadinessEvents $f0State.events.ToArray() -M0Events @()
  $m0BacklogState = New-ParamListState -CaptureScope 'pre_request_m0'
  Add-ParamValuePayload -State $m0BacklogState -Payload $semanticIndexZero `
      -SystemId 1 -ComponentId 1 -Sequence 0 -ElapsedMs 1
  $m0Backlog = Test-PreRequestBacklogGate -ReadinessEvents @() `
      -M0Events $m0BacklogState.events.ToArray()
  $knownBacklogState = New-ParamListState -CaptureScope 'pre_request_readiness'
  [byte[]]$knownSentinelPayload = New-ParamValuePayload `
      -ParamId 'STAT_RUNTIME' -Index 65535 -Count 932 -Type 6
  Add-ParamValuePayload -State $knownBacklogState -Payload $knownSentinelPayload `
      -SystemId 1 -ComponentId 1 -Sequence 1 -ElapsedMs 1
  $knownBacklog = Test-PreRequestBacklogGate `
      -ReadinessEvents $knownBacklogState.events.ToArray() -M0Events @()
  $m0NotCompleted = Test-PreRequestBacklogGate -ReadinessEvents @() `
      -M0Events @() -M0EpochCompleted $false
  Add-SelfCase 'pre_request_backlog_clean_pass' $cleanBacklog.valid `
      'a completed fresh M0 epoch with zero #22 is the clean request boundary'
  Add-SelfCase 'pre_request_backlog_readiness_audited_not_blocking' `
      ($readinessBacklog.valid -and
       $readinessBacklog.readiness_event_count -eq 2 -and
       $readinessBacklog.historical_readiness_event_count -eq 2 -and
       $readinessBacklog.veto_event_count -eq 0 -and
       $readinessBacklog.m0_event_count -eq 0 -and
       $readinessBacklog.readiness_events_audit_only) `
      'drained readiness-history #22 remains auditable but does not veto a fresh M0 epoch'
  Add-SelfCase 'pre_request_backlog_m0_not_completed_rejected' `
      (-not $m0NotCompleted.valid -and $m0NotCompleted.not_run -and
       -not $m0NotCompleted.m0_epoch_completed) `
      'a missing M0 epoch cannot be mistaken for a clean zero-event boundary'
  Add-SelfCase 'pre_request_backlog_m0_rejected' `
      (-not $m0Backlog.valid -and $m0Backlog.m0_event_count -eq 1) `
      'M0 indexed #22 rejects R0'
  Add-SelfCase 'pre_request_backlog_known_sentinel_audited_not_blocking' `
      ($knownBacklog.valid -and
       $knownBacklog.known_stat_runtime_sentinel_count -eq 1 -and
       $knownBacklog.m0_event_count -eq 0) `
      'readiness-history STAT_RUNTIME remains auditable but does not veto a fresh M0 epoch'

  $officialState = $positive.state
  $officialBefore = Complete-ParamListAssessment -State $officialState
  $postCutoffState = New-ParamListState -CaptureScope 'post_cutoff'
  Add-ParamValuePayload -State $postCutoffState -Payload $semanticUnknown `
      -SystemId 1 -ComponentId 1 -Sequence 44 -ElapsedMs 999999 `
      -RawStartOffset 50000 -RawEndOffsetExclusive 50037
  $officialAfter = Complete-ParamListAssessment -State $officialState
  Add-SelfCase 'official_post_cutoff_separated' `
      ($officialState.events[0].capture_scope -eq 'official' -and
       $postCutoffState.events[0].capture_scope -eq 'post_cutoff') `
      'PARAM_VALUE evidence explicitly marks official versus post-cutoff scope'
  Add-SelfCase 'post_cutoff_does_not_mutate_official' `
      ($officialBefore.valid -and $officialAfter.valid -and
       $officialBefore.event_count -eq $officialAfter.event_count -and
       $postCutoffState.unknown_sentinel_count -eq 1) `
      'post-cutoff drain records anomalies without mutating frozen official acceptance'
  $diagnosticModel = New-ParamListDiagnosticEvidence `
      -BacklogDrainGate ([pscustomobject]@{valid=$true}) `
      -BaselinePairGate ([pscustomobject]@{
        valid=$true;attempt_count=2;retry_count=1;selected_attempt=2}) `
      -BaselineSetup $offlineBaseline `
      -PreRequestPairGate ([pscustomobject]@{
        valid=$true;attempt_count=1;retry_count=0;fixture_write_count=0}) `
      -PreRequestVehicleGate $preRequestGateClean `
      -PreRequestBacklogGate $cleanBacklog `
      -M0 ([pscustomobject]@{elapsed_ms=100;ground_raw_offset=1000}) `
      -M1 ([pscustomobject]@{elapsed_ms=200;ground_raw_offset=2000}) `
      -StopReason 'complete_duplicate_guard' `
      -OfficialState $officialState -OfficialAssessment $officialAfter `
      -ParserIntegrity ([pscustomobject]@{valid=$true}) `
      -HeartbeatMetrics ([pscustomobject]@{valid=$true}) `
      -PostCutoffState $postCutoffState `
      -PostGround $offlinePostGround -PostAssessment $offlinePost
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
      'param_list_diagnostics_model.json') -Value $diagnosticModel
  Add-SelfCase 'param_list_diagnostic_schema' `
      ($diagnosticModel.schema_version -eq 1 -and
       $null -ne $diagnosticModel.backlog_drain_gate -and
       $null -ne $diagnosticModel.baseline_pair_gate -and
       $null -ne $diagnosticModel.baseline_setup -and
       $null -ne $diagnosticModel.pre_request_pair_gate -and
       $null -ne $diagnosticModel.pre_request_vehicle_gate -and
       $null -ne $diagnosticModel.pre_request_backlog_gate -and
       $diagnosticModel.official.stop_reason -eq 'complete_duplicate_guard' -and
       $diagnosticModel.post_cutoff.event_count -eq 1) `
      'diagnostic artifact exposes backlog/baseline/TOCTOU/official cutoff/post-cutoff sections'
  Add-SelfCase 'diagnostic_stop_reason_proxy_terminal' `
      ($diagnosticModel.official.first_anomaly -eq $null -and
       $diagnosticModel.official.stop_reason -eq 'complete_duplicate_guard' -and
       $diagnosticModel.proxy_terminal.classification -eq 'Complete') `
      'diagnostic artifact classifies exact stop reason and terminal proxy Complete/Failed state'

  $heartbeatEvents = @(
    [pscustomobject]@{message_id=0;system_id=1;component_id=1;elapsed_ms=1000.0},
    [pscustomobject]@{message_id=0;system_id=1;component_id=1;elapsed_ms=3000.0},
    [pscustomobject]@{message_id=0;system_id=1;component_id=1;elapsed_ms=5000.0})
  $heartbeat = Get-HeartbeatWindowMetrics -Events $heartbeatEvents `
      -M0ElapsedMs 0 -M1ElapsedMs 6000
  Add-SelfCase 'heartbeat_edge' $heartbeat.valid 'M0 edge <=2500 passes'
  Add-SelfCase 'heartbeat_consecutive' $heartbeat.valid `
      'all consecutive source1/1 edges <=2500 pass'
  Add-SelfCase 'heartbeat_tail' $heartbeat.valid 'M1 tail <=2500 passes'
  $guardTailHeartbeat = Get-HeartbeatWindowMetrics -Events @(
      [pscustomobject]@{message_id=0;system_id=1;component_id=1;elapsed_ms=1000.0},
      [pscustomobject]@{message_id=0;system_id=1;component_id=1;elapsed_ms=3000.0},
      [pscustomobject]@{message_id=0;system_id=1;component_id=1;elapsed_ms=5000.0},
      [pscustomobject]@{message_id=0;system_id=1;component_id=1;elapsed_ms=7000.0}) `
      -M0ElapsedMs 0 -M1ElapsedMs 8000
  Add-SelfCase 'duplicate_guard_tail_heartbeat' $guardTailHeartbeat.valid `
      'heartbeat remains gated through the entire duplicate-guard tail'
  $badHeartbeat = Get-HeartbeatWindowMetrics -Events $heartbeatEvents `
      -M0ElapsedMs -2000 -M1ElapsedMs 9000
  Add-SelfCase 'heartbeat_gap_rejected' (-not $badHeartbeat.valid) `
      'edge or tail above 2500 fails'

  $incrementalEvents =
      New-Object 'System.Collections.Generic.List[object]'
  $incrementalHeartbeat = New-HeartbeatWindowAccumulator -M0ElapsedMs 1000.0
  $incrementalComparisons = New-Object 'System.Collections.Generic.List[bool]'
  foreach ($comparisonEndMs in @([double]1000.0)) {
    Update-HeartbeatWindowAccumulator -State $incrementalHeartbeat `
        -Events $incrementalEvents -ThroughElapsedMs $comparisonEndMs
    $fullMetrics = Get-HeartbeatWindowMetrics -Events $incrementalEvents `
        -M0ElapsedMs 1000.0 -M1ElapsedMs $comparisonEndMs
    $incrementalMetrics = Get-HeartbeatWindowAccumulatorSnapshot `
        -State $incrementalHeartbeat -M1ElapsedMs $comparisonEndMs `
        -IncludeGaps
    $incrementalComparisons.Add(
        (($fullMetrics | ConvertTo-Json -Depth 10 -Compress) -ceq
         ($incrementalMetrics | ConvertTo-Json -Depth 10 -Compress)))
  }
  foreach ($event in @(
      [pscustomobject]@{
        message_id=0;system_id=1;component_id=1;elapsed_ms=900.0},
      [pscustomobject]@{
        message_id=0;system_id=1;component_id=1;elapsed_ms=1000.0},
      [pscustomobject]@{
        message_id=0;system_id=2;component_id=1;elapsed_ms=1500.0},
      [pscustomobject]@{
        message_id=0;system_id=1;component_id=1;elapsed_ms=2000.0})) {
    $incrementalEvents.Add($event)
  }
  foreach ($comparisonEndMs in @([double]2000.0)) {
    Update-HeartbeatWindowAccumulator -State $incrementalHeartbeat `
        -Events $incrementalEvents -ThroughElapsedMs $comparisonEndMs
    $fullMetrics = Get-HeartbeatWindowMetrics -Events $incrementalEvents `
        -M0ElapsedMs 1000.0 -M1ElapsedMs $comparisonEndMs
    $incrementalMetrics = Get-HeartbeatWindowAccumulatorSnapshot `
        -State $incrementalHeartbeat -M1ElapsedMs $comparisonEndMs `
        -IncludeGaps
    $incrementalComparisons.Add(
        (($fullMetrics | ConvertTo-Json -Depth 10 -Compress) -ceq
         ($incrementalMetrics | ConvertTo-Json -Depth 10 -Compress)))
  }
  foreach ($event in @(
      [pscustomobject]@{
        message_id=0;system_id=1;component_id=1;elapsed_ms=4500.0},
      [pscustomobject]@{
        message_id=0;system_id=1;component_id=1;elapsed_ms=7001.0},
      [pscustomobject]@{
        message_id=0;system_id=1;component_id=1;elapsed_ms=9000.0})) {
    $incrementalEvents.Add($event)
  }
  foreach ($comparisonEndMs in @([double]7001.0, [double]9500.0)) {
    Update-HeartbeatWindowAccumulator -State $incrementalHeartbeat `
        -Events $incrementalEvents -ThroughElapsedMs $comparisonEndMs
    $fullMetrics = Get-HeartbeatWindowMetrics -Events $incrementalEvents `
        -M0ElapsedMs 1000.0 -M1ElapsedMs $comparisonEndMs
    $incrementalMetrics = Get-HeartbeatWindowAccumulatorSnapshot `
        -State $incrementalHeartbeat -M1ElapsedMs $comparisonEndMs `
        -IncludeGaps
    $incrementalComparisons.Add(
        (($fullMetrics | ConvertTo-Json -Depth 10 -Compress) -ceq
         ($incrementalMetrics | ConvertTo-Json -Depth 10 -Compress)))
  }
  $incrementalProgressMetrics = Get-HeartbeatWindowAccumulatorSnapshot `
      -State $incrementalHeartbeat -M1ElapsedMs 9500.0
  [bool]$smallIncrementalEquivalent = (
    $incrementalComparisons.Count -eq 4 -and
    @($incrementalComparisons | Where-Object { -not $_ }).Count -eq 0 -and
    $incrementalProgressMetrics.gaps.Count -eq 0 -and
    [double]$incrementalProgressMetrics.maximum_gap_ms -eq
      [double]$fullMetrics.maximum_gap_ms -and
    [int]$incrementalHeartbeat.next_event_index -eq
      $incrementalEvents.Count -and
    [int]$incrementalHeartbeat.closed_gaps.Count -eq
      [int]$incrementalHeartbeat.count)

  [int]$largeHeartbeatCount = 4096
  [double]$largeHeartbeatM0Ms = 1000.0
  $largeHeartbeatEvents =
      New-Object 'System.Collections.Generic.List[object]'
  for ([int]$heartbeatIndex = 0;
      $heartbeatIndex -lt $largeHeartbeatCount; ++$heartbeatIndex) {
    $largeHeartbeatEvents.Add([pscustomobject]@{
      message_id=0;system_id=1;component_id=1
      elapsed_ms=$largeHeartbeatM0Ms + ([double]$heartbeatIndex * 1000.0)
    })
  }
  [double]$largeHeartbeatM1Ms = $largeHeartbeatM0Ms +
      ([double]$largeHeartbeatCount * 1000.0)
  $largeHeartbeatAccumulator = New-HeartbeatWindowAccumulator `
      -M0ElapsedMs $largeHeartbeatM0Ms
  Update-HeartbeatWindowAccumulator -State $largeHeartbeatAccumulator `
      -Events $largeHeartbeatEvents -ThroughElapsedMs $largeHeartbeatM1Ms
  [int]$largeNextIndexBeforeNoNew =
      [int]$largeHeartbeatAccumulator.next_event_index
  [int]$largeClosedGapsBeforeNoNew =
      [int]$largeHeartbeatAccumulator.closed_gaps.Count
  [bool]$noNewEventStateStable = $true
  for ([int]$repeat = 0; $repeat -lt 32; ++$repeat) {
    Update-HeartbeatWindowAccumulator -State $largeHeartbeatAccumulator `
        -Events $largeHeartbeatEvents -ThroughElapsedMs $largeHeartbeatM1Ms
    $noNewProgressMetrics = Get-HeartbeatWindowAccumulatorSnapshot `
        -State $largeHeartbeatAccumulator -M1ElapsedMs $largeHeartbeatM1Ms
    if ([int]$largeHeartbeatAccumulator.next_event_index -ne
          $largeNextIndexBeforeNoNew -or
        [int]$largeHeartbeatAccumulator.closed_gaps.Count -ne
          $largeClosedGapsBeforeNoNew -or
        $noNewProgressMetrics.gaps.Count -ne 0) {
      $noNewEventStateStable = $false
    }
  }
  $largeFullMetrics = Get-HeartbeatWindowMetrics `
      -Events $largeHeartbeatEvents -M0ElapsedMs $largeHeartbeatM0Ms `
      -M1ElapsedMs $largeHeartbeatM1Ms
  $includeGapSamples = New-Object 'System.Collections.Generic.List[double]'
  $largeIncrementalMetrics = $null
  for ([int]$sampleIndex = 0; $sampleIndex -lt 10; ++$sampleIndex) {
    $includeGapWatch = [Diagnostics.Stopwatch]::StartNew()
    $largeIncrementalMetrics = Get-HeartbeatWindowAccumulatorSnapshot `
        -State $largeHeartbeatAccumulator -M1ElapsedMs $largeHeartbeatM1Ms `
        -IncludeGaps
    $includeGapWatch.Stop()
    $includeGapSamples.Add(
        [Math]::Round($includeGapWatch.Elapsed.TotalMilliseconds, 3))
  }
  [bool]$largeIncrementalEquivalent = (
    $noNewEventStateStable -and
    [int]$largeHeartbeatAccumulator.next_event_index -eq
      $largeHeartbeatCount -and
    [int]$largeHeartbeatAccumulator.closed_gaps.Count -eq
      $largeHeartbeatCount -and
    ($largeFullMetrics | ConvertTo-Json -Depth 10 -Compress) -ceq
      ($largeIncrementalMetrics | ConvertTo-Json -Depth 10 -Compress))
  $includeGapMeasures = $includeGapSamples |
      Measure-Object -Average -Maximum
  $heartbeatAccumulatorBenchmark = [ordered]@{
    schema_version=1
    event_count=$largeHeartbeatCount
    repeated_no_new_event_update_count=32
    next_event_index_unchanged=$noNewEventStateStable
    exact_legacy_equivalence=$largeIncrementalEquivalent
    include_gaps_sample_count=$includeGapSamples.Count
    include_gaps_elapsed_ms=$includeGapSamples.ToArray()
    include_gaps_mean_ms=[Math]::Round(
      [double]$includeGapMeasures.Average, 3)
    include_gaps_max_ms=[Math]::Round(
      [double]$includeGapMeasures.Maximum, 3)
  }
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
      'heartbeat_incremental_benchmark.json') `
      -Value $heartbeatAccumulatorBenchmark
  [bool]$incrementalEquivalent = (
    $smallIncrementalEquivalent -and $largeIncrementalEquivalent)
  Add-SelfCase 'heartbeat_incremental_matches_full_history' `
      $incrementalEquivalent `
      ('four batched snapshots plus 4096-event final fields/gap order ' +
       'exactly match legacy; 32 no-new-event updates are immutable; ' +
       'progress snapshots omit gap materialization')

  $definitions = Import-MavlinkDefinitions -Path `
      (Join-Path $repo 'core\src\mavlink_frame.cpp')
  [byte[]]$heartbeatPayload = New-Object byte[] 9
  [byte[]]$heartbeatFrameA = New-Mavlink2TestFrame -MessageId 0 `
      -Payload $heartbeatPayload -CrcExtra 50 -Sequence 255
  [byte[]]$heartbeatFrameB = New-Mavlink2TestFrame -MessageId 0 `
      -Payload $heartbeatPayload -CrcExtra 50 -Sequence 0
  $parser = New-MavlinkParserState -Definitions $definitions.definitions
  [long]$offset = 0
  foreach ($value in @($heartbeatFrameA + $heartbeatFrameB)) {
    Add-MavlinkAnalysisByte -Parser $parser -Byte $value `
        -RawOffset $offset -ElapsedMs ([double]$offset)
    ++$offset
  }
  $parserIntegrity = Get-ParserIntegrity -Parser $parser
  Add-SelfCase 'parser_integrity' `
      ($parserIntegrity.valid -and $parser.ValidEvents.Count -eq 2 -and
       $definitions.count -eq 80) `
      'canonical80 byte-fragmented parser clean predicate accepts good frames'

  $unsupportedParser = New-MavlinkParserState `
      -Definitions $definitions.definitions
  [byte[]]$unsupportedFrame = New-Mavlink2TestFrame -MessageId 250 `
      -Payload ([byte[]]@()) -CrcExtra 0
  [long]$testOffset = 0
  foreach ($value in $unsupportedFrame) {
    Add-MavlinkAnalysisByte -Parser $unsupportedParser -Byte $value `
        -RawOffset $testOffset -ElapsedMs ([double]$testOffset)
    ++$testOffset
  }
  Add-SelfCase 'parser_unsupported_id' `
      ($unsupportedParser.Unsupported -eq 1 -and
       -not (Get-ParserIntegrity -Parser $unsupportedParser).valid) `
      'unsupported message ID independently fails parser-clean predicate'

  $flagsParser = New-MavlinkParserState -Definitions $definitions.definitions
  [byte[]]$flagsFrame = [byte[]]$heartbeatFrameA.Clone()
  $flagsFrame[2] = 2
  foreach ($value in $flagsFrame) {
    Add-MavlinkAnalysisByte -Parser $flagsParser -Byte $value `
        -RawOffset $testOffset -ElapsedMs ([double]$testOffset)
    ++$testOffset
  }
  Add-SelfCase 'parser_unsupported_flags' `
      ($flagsParser.UnsupportedFlags -eq 1 -and
       -not (Get-ParserIntegrity -Parser $flagsParser).valid) `
      'unsupported MAVLink2 flags independently fail parser-clean predicate'

  $lengthParser = New-MavlinkParserState -Definitions $definitions.definitions
  [byte[]]$shortHeartbeatPayload = New-Object byte[] 8
  [byte[]]$shortHeartbeat = New-Mavlink2TestFrame -MessageId 0 `
      -Payload $shortHeartbeatPayload -CrcExtra 50
  foreach ($value in $shortHeartbeat) {
    Add-MavlinkAnalysisByte -Parser $lengthParser -Byte $value `
        -RawOffset $testOffset -ElapsedMs ([double]$testOffset)
    ++$testOffset
  }
  Add-SelfCase 'parser_bad_length' `
      ($lengthParser.BadPayloadLength -eq 1 -and
       -not (Get-ParserIntegrity -Parser $lengthParser).valid) `
      'bad payload length independently fails parser-clean predicate'

  $crcParser = New-MavlinkParserState -Definitions $definitions.definitions
  [byte[]]$badFrame = [byte[]]$heartbeatFrameA.Clone()
  $badFrame[10] = $badFrame[10] -bxor 1
  foreach ($value in $badFrame) {
    Add-MavlinkAnalysisByte -Parser $crcParser -Byte $value `
        -RawOffset $testOffset -ElapsedMs ([double]$testOffset)
    ++$testOffset
  }
  Add-SelfCase 'parser_bad_crc' `
      ($crcParser.BadCrc -eq 1 -and
       -not (Get-ParserIntegrity -Parser $crcParser).valid) `
      'bad CRC independently fails parser-clean predicate'

  $noiseParser = New-MavlinkParserState -Definitions $definitions.definitions
  Add-MavlinkAnalysisByte -Parser $noiseParser -Byte 0x41 `
      -RawOffset $testOffset -ElapsedMs ([double]$testOffset)
  Add-SelfCase 'parser_noise' `
      ($noiseParser.NoiseBytes -eq 1 -and
       -not (Get-ParserIntegrity -Parser $noiseParser).valid) `
      'non-frame noise independently fails parser-clean predicate'

  $partialParser = New-MavlinkParserState -Definitions $definitions.definitions
  for ($partialIndex = 0; $partialIndex -lt 3; ++$partialIndex) {
    Add-MavlinkAnalysisByte -Parser $partialParser `
        -Byte $heartbeatFrameA[$partialIndex] -RawOffset $testOffset `
        -ElapsedMs ([double]$testOffset)
    ++$testOffset
  }
  Add-SelfCase 'parser_partial' `
      ($partialParser.Buffer.Count -eq 3 -and
       -not (Get-ParserIntegrity -Parser $partialParser).valid) `
      'partial tail independently fails parser-clean predicate'

  $listParser = New-MavlinkParserState -Definitions $definitions.definitions
  [long]$largeOffset = [long]4294967300
  for ($listIndex = 0; $listIndex -lt 932; ++$listIndex) {
    [byte[]]$listPayload = New-ParamValuePayload `
        -ParamId ('P{0:D4}' -f $listIndex) -Index $listIndex
    [byte[]]$listFrame = New-Mavlink2TestFrame -MessageId 22 `
        -Payload $listPayload -CrcExtra 220 `
        -Sequence ([byte]($listIndex % 256))
    foreach ($value in $listFrame) {
      Add-MavlinkAnalysisByte -Parser $listParser -Byte $value `
          -RawOffset $largeOffset -ElapsedMs ([double]$largeOffset)
      ++$largeOffset
    }
  }
  $listParserAssessment = Complete-ParamListAssessment `
      -State $listParser.ParamList
  [bool]$multipleSequenceWraps = `
      ($listParser.ValidEvents[255].sequence -eq 255 -and
       $listParser.ValidEvents[256].sequence -eq 0 -and
       $listParser.ValidEvents[511].sequence -eq 255 -and
       $listParser.ValidEvents[512].sequence -eq 0 -and
       $listParser.ValidEvents[767].sequence -eq 255 -and
       $listParser.ValidEvents[768].sequence -eq 0)
  Add-SelfCase 'positive_932_mavlink_sequence_wraps' `
      ($listParserAssessment.valid -and $multipleSequenceWraps) `
      '932 streamed MAVLink #22 frames pass across three sequence wraps'
  Add-SelfCase 'long_counter_boundaries' `
      ($largeOffset -gt [long][uint32]::MaxValue -and
       [double]$listParser.ValidEvents[-1].elapsed_ms -gt 4294967295.0 -and
       $listParser.ValidEvents[-1].raw_end_offset_exclusive -gt
           [long][uint32]::MaxValue -and
       $listParserAssessment.indexed_frame_count.GetType().Name -eq 'UInt64') `
      'diagnostic ms/raw offsets/counters remain safe beyond UInt32'

  $stallDecision = Test-TimeoutDecision -ElapsedSeconds 1000 `
      -StallSeconds 120 -Indexed 100
  Add-SelfCase 'stall' `
      ($stallDecision.stall_timeout -and -not $stallDecision.overall_timeout) `
      '120-second next-index stall fails'
  $overallDecision = Test-TimeoutDecision -ElapsedSeconds 7200 `
      -StallSeconds 0 -Indexed 100
  Add-SelfCase 'overall_timeout' $overallDecision.overall_timeout `
      '7200-second overall timeout fails'

  $stallState = New-ParamListState
  [byte[]]$indexZeroPayload = New-ParamValuePayload -ParamId 'P0000' -Index 0
  Add-ParamValuePayload -State $stallState -Payload $indexZeroPayload `
      -SystemId 1 -ComponentId 1 -Sequence 0 -ElapsedMs 1000
  [double]$stallAnchor = [double]$stallState.last_accepted_elapsed_ms
  Add-ParamValuePayload -State $stallState -Payload $indexZeroPayload `
      -SystemId 1 -ComponentId 1 -Sequence 1 -ElapsedMs 2000
  [byte[]]$indexTwoPayload = New-ParamValuePayload -ParamId 'P0002' -Index 2
  Add-ParamValuePayload -State $stallState -Payload $indexTwoPayload `
      -SystemId 1 -ComponentId 1 -Sequence 2 -ElapsedMs 3000
  Add-SelfCase 'stall_invalid_progress_no_reset' `
      ([double]$stallState.last_accepted_elapsed_ms -eq $stallAnchor) `
      'duplicate and out-of-order frames cannot reset expected-index stall'

  $progressState = New-ProgressState
  $progress = Write-ProgressIfDue -ProgressState $progressState `
      -Indexed 25 -LastIndex 24 -ElapsedSeconds 10 `
      -HeartbeatMaximumMs 2000 -StallSeconds 0 -SuppressConsole
  Add-SelfCase 'progress_format' `
      ($progress.emitted -and $progress.line -eq
