      'ports_reappeared','ports_opened','data_plane_readiness_started',
      'data_plane_readiness_progress','data_plane_readiness_window',
      'data_plane_readiness_result','backlog_drain_started',
      'backlog_drain_progress','backlog_drain_progress',
      'backlog_drain_result','baseline_complete',
      'pre_request_vehicle_complete','request_sent',
      'progress','progress','list_complete','duplicate_guard_complete',
      'post_snapshots','footer_fsynced','final_status')
    [double]$modeledElapsed = 0
    [int]$modeledIndexed = 0
    foreach ($name in $modeledNames) {
      if ($name -eq 'progress' -and $modeledIndexed -eq 0) {
        $modeledElapsed = 30; $modeledIndexed = 0
      } elseif ($name -eq 'progress') {
        $modeledElapsed = 31; $modeledIndexed = 25
      } else {
        $modeledElapsed += 1
