  } finally {
    $liveProgressStream.Dispose()
  }
  $progressRecords = @(Get-Content -LiteralPath $liveProgressPath |
      ForEach-Object { $_ | ConvertFrom-Json })
  [bool]$progressOrderValid = ($progressRecords.Count -eq
      $modeledNames.Count)
  for ($progressEventIndex = 0;
      $progressEventIndex -lt $progressRecords.Count;
      ++$progressEventIndex) {
    if ([string]$progressRecords[$progressEventIndex].event -ne
        [string]$modeledNames[$progressEventIndex]) {
      $progressOrderValid = $false
    }
  }
  [bool]$progressMonotonic = $true
  for ($progressIndex = 1; $progressIndex -lt $progressRecords.Count;
      ++$progressIndex) {
    if ([double]$progressRecords[$progressIndex].elapsed_s -lt
        [double]$progressRecords[$progressIndex - 1].elapsed_s -or
        [int]$progressRecords[$progressIndex].indexed -lt
        [int]$progressRecords[$progressIndex - 1].indexed) {
      $progressMonotonic = $false
    }
  }
