  Write-JsonDurable -Path $jsonMultiplePath -Value $jsonMultiple
  Write-JsonDurable -Path $jsonObjectPath -Value $jsonObject
  Write-JsonDurable -Path $jsonDictionaryPath -Value $jsonDictionary
  Write-JsonDurable -Path $jsonScalarPath -Value $jsonScalar
  [byte[]]$jsonEmptyBytes = [System.IO.File]::ReadAllBytes($jsonEmptyPath)
