  Add-SelfCase 'durable_json_empty_array_exact' `
      ($jsonEmptyBytes.Length -eq 4 -and $jsonEmptyHex -ceq '5B5D0D0A' -and
       (Get-FileHash -Algorithm SHA256 -LiteralPath $jsonEmptyPath).Hash -ceq
         'A5338D955B09046EC0B16F3A9625B7955C763AAE07DC722E474E6078745F932F' -and
       $jsonEmptyParsed -is [Array] -and $jsonEmptyParsed.Count -eq 0) `
      'empty collection is canonical UTF-8 no-BOM [] plus one CRLF'
  [object]$jsonSingletonParsed = $jsonUtf8.GetString(
      [System.IO.File]::ReadAllBytes($jsonSingletonPath)) |
      ConvertFrom-Json -ErrorAction Stop
  [object]$jsonMultipleParsed = $jsonUtf8.GetString(
      [System.IO.File]::ReadAllBytes($jsonMultiplePath)) |
      ConvertFrom-Json -ErrorAction Stop
  Add-SelfCase 'durable_json_array_cardinality_preserved' `
      ($jsonSingletonParsed -is [Array] -and
       $jsonSingletonParsed.Count -eq 1 -and
       $jsonMultipleParsed -is [Array] -and $jsonMultipleParsed.Count -eq 2 -and
       (Get-FileHash -Algorithm SHA256 -LiteralPath $jsonSingletonPath).Hash -ceq
         '571D45902182A6795A0AACC05975EBEF7E1BCAF0B941E948B6F66C0FF89C5CF3' -and
       (Get-FileHash -Algorithm SHA256 -LiteralPath $jsonMultiplePath).Hash -ceq
         'B7A920259B711710D604758872473EA9E08941473217AF3C3FD011FA243D3AAB') `
      'singleton and multi-item collections retain JSON root-array cardinality'
  Add-SelfCase 'durable_json_nonarray_bytes_unchanged' `
      ((Get-FileHash -Algorithm SHA256 -LiteralPath $jsonObjectPath).Hash -ceq
         '04C86103A8B857B17F30B1124FD78843B654C12746367D1635F5002D6096C63A' -and
       (Get-FileHash -Algorithm SHA256 -LiteralPath $jsonDictionaryPath).Hash -ceq
         '04C86103A8B857B17F30B1124FD78843B654C12746367D1635F5002D6096C63A' -and
       (Get-FileHash -Algorithm SHA256 -LiteralPath $jsonScalarPath).Hash -ceq
         'DF85F2951CF8505298F6B51B6C01942AFBA9C8CD90DB4F5CF615B37041F4D02C') `
      'root object, dictionary, and scalar keep their established JSON bytes'

  $emptyFailureDirectory = Join-Path $SelfTestEvidenceDirectory `
