    }
    Write-JsonDurable -Path (Join-Path $syncModelDirectory `
        'capture_footer.json') -Value ([ordered]@{
          schema_version=1;status='FAIL';completed=$true
          failure_classification='SETUP_INVALID'
          errors=@('setup_invalid: data-plane diagnostic synchronization failed; request suppressed')
          open_counts=[ordered]@{vehicle=1;ground=1}
          fixture_write_count=0
          data_plane_readiness=[ordered]@{
            valid=$false;timed_out=$false;sync_invalid=$true
            evidence_file='data_plane_readiness.json'
          }
          snapshots=[ordered]@{
            baseline_vehicle='NOT_RUN';baseline_ground='NOT_RUN'
            post_ground='NOT_RUN_SYNC_INVALID'
            post_vehicle='NOT_RUN_SYNC_INVALID'
          }
          post_diagnostics=[ordered]@{
            ground_query_count=0;vehicle_query_count=0
            suppression_reason='SYNC_INVALID'
            sync_invalid_continuation_file='sync_invalid_continuation.json'
          }
          durability=[ordered]@{
            file_options='WriteThrough';flush_to_disk='Flush(true)'
            footer_fsync_before_both_COM_close=$true
          }
        })
    Write-JsonDurable -Path (Join-Path $syncModelDirectory `
        'summary.json') -Value ([ordered]@{
          schema_version=1;status='FAIL';completed=$true;exit_code=1
          setup_invalid=$true;serial_open_count=2
          open_counts=[ordered]@{vehicle=1;ground=1}
          request_write_count=0;upload_count=0
          post_ground_status='NOT_RUN_SYNC_INVALID'
          post_vehicle_status='NOT_RUN_SYNC_INVALID'
          post_ground_query_count=0;post_vehicle_query_count=0
          sync_invalid_continuation=$syncContinuation
          capture_footer_recorded=$true
        })
    $syncModelRows = New-Object 'System.Collections.Generic.List[object]'
    $syncModelManifestPath = Join-Path $syncModelDirectory `
        'artifact_hashes.json'
    foreach ($syncModelFile in @(Get-ChildItem -LiteralPath `
        $syncModelDirectory -File | Where-Object {
          $_.FullName -ne $syncModelManifestPath
        } | Sort-Object Name)) {
      $syncModelHashResult = Get-FileHash -Algorithm SHA256 `
          -LiteralPath $syncModelFile.FullName -ErrorAction Stop
      [string]$syncModelSha256 = [string]$syncModelHashResult.Hash
      $syncModelRows.Add([pscustomobject][ordered]@{
        file=$syncModelFile.Name;size_bytes=[long]$syncModelFile.Length
        sha256=$syncModelSha256
      })
    }
    Write-JsonDurable -Path $syncModelManifestPath -Value ([ordered]@{
      schema_version=1
      coverage='all modeled readiness-sync-invalid files before artifact_hashes.json'
      covered_file_count=$syncModelRows.Count;files=$syncModelRows.ToArray()
    })
    [bool]$syncModelValid = ($syncModelRows.Count -eq
        @(Get-ChildItem -LiteralPath $syncModelDirectory -File |
          Where-Object {$_.FullName -ne $syncModelManifestPath}).Count -and
        @($syncModelRows | Group-Object file | Where-Object {
          $_.Count -ne 1}).Count -eq 0)
    Add-SelfCase 'readiness_sync_invalid_durable_artifacts' `
        $syncModelValid `
        'sync-invalid setup FAIL/1 has exact post suppression, continuation, footer, and manifest evidence'
  }

  # Regression for R10 R5C: a real post-ground COM closure was followed by a
  # broker STOP_CAPTURE pipe failure.  Finalization must retain the first
  # exception, keep exact-once request evidence, and never depend on a late
  # assignment of the backlog evidence projection.
  [string]$finalizationPrimaryFailure =
      'post_ground: reader broker ERROR: System.InvalidOperationException: port is closed'
  [string]$finalizationShutdownFailure =
      'durable footer failure: reader broker STOP_CAPTURE pipe was broken'
  $backlogProjectionCommand = Get-Command `
      -Name 'Get-BacklogDrainEvidenceProjection' -ErrorAction SilentlyContinue
  $failureResolutionCommand = Get-Command `
      -Name 'Resolve-FinalizationFailure' -ErrorAction SilentlyContinue
  $rawFallbackCommand = Get-Command `
      -Name 'Get-RawEvidenceFallbackProjection' -ErrorAction SilentlyContinue
  $pumpFallbackCommand = Get-Command `
      -Name 'Get-PumpFairnessFallbackProjection' -ErrorAction SilentlyContinue
  $preTryBacklogProjection = $null
  $completedBacklogProjection = $null
  $finalizationFailureResolution = $null
  $rawFallbackProjection = $null
  $pumpFallbackProjection = $null
  if ($null -ne $backlogProjectionCommand -and
      $null -ne $failureResolutionCommand -and
      $null -ne $rawFallbackCommand -and
      $null -ne $pumpFallbackCommand) {
    $projectionParser = [pscustomobject]@{Enabled=$false}
    $preTryBacklogProjection = & $backlogProjectionCommand `
        -BacklogDrainGate $null -GroundParser $projectionParser `
        -TimeoutSeconds 720
    $modeledCompletedBacklogGate = [pscustomobject][ordered]@{
      schema_version=1;valid=$true;timed_out=$false;sync_invalid=$false
      not_run=$false;timeout_seconds=720;attempt_count=11
      observations=@();stable_pairs=@();last_vehicle_snapshot=$null
      last_ground_snapshot=$null;ground_parser_disabled_and_reset=$true
    }
    $completedBacklogProjection = & $backlogProjectionCommand `
        -BacklogDrainGate $modeledCompletedBacklogGate `
        -GroundParser $projectionParser -TimeoutSeconds 720
    $finalizationFailureResolution = & $failureResolutionCommand `
        -PrimaryFailure $finalizationPrimaryFailure `
        -FinalizationFailure $finalizationShutdownFailure
    $rawFallbackProjection = & $rawFallbackCommand `
        -VehicleRawBytes 35948 -GroundRawBytes 69665 `
        -FailureReason 'seal_skipped_after_broker_shutdown_failure'
    $pumpFallbackProjection = & $pumpFallbackCommand `
        -TargetMs 75 -HardLimitMs 100 `
        -FailureReason 'measurement_skipped_after_broker_shutdown_failure'
  }
  $modeledFinalizationSummary = [ordered]@{
    status='ERROR';exit_code=2
    failure=if($null -ne $finalizationFailureResolution){
      $finalizationFailureResolution.primary_failure
    }else{$null}
    errors=@($finalizationPrimaryFailure,$finalizationShutdownFailure)
    fixture=[ordered]@{
      attempt_count=1;write_count=1;write_uncertain=$false
      write_disposition='ACKNOWLEDGED_EXACTLY_ONCE'
    }
    backlog_drain=$completedBacklogProjection
    raw_capture=$rawFallbackProjection
    pump_fairness=$pumpFallbackProjection
  }
  [string]$modeledFinalizationJson = $modeledFinalizationSummary | `
      ConvertTo-Json -Depth 16 -Compress
  [bool]$finalizationRegressionValid = (
    $null -ne $backlogProjectionCommand -and
    $null -ne $failureResolutionCommand -and
    $null -ne $rawFallbackCommand -and
    $null -ne $pumpFallbackCommand -and
    $null -ne $preTryBacklogProjection -and
    [bool]$preTryBacklogProjection.not_run -and
    -not [bool]$preTryBacklogProjection.valid -and
    [bool]$preTryBacklogProjection.ground_parser_disabled_and_reset -and
    $null -ne $completedBacklogProjection -and
    [bool]$completedBacklogProjection.valid -and
    -not [bool]$completedBacklogProjection.not_run -and
    [int]$completedBacklogProjection.attempt_count -eq 11 -and
    $null -ne $finalizationFailureResolution -and
    [string]$finalizationFailureResolution.primary_failure -ceq
        $finalizationPrimaryFailure -and
    [string]$finalizationFailureResolution.finalization_failure -ceq
        $finalizationShutdownFailure -and
    [bool]$finalizationFailureResolution.primary_preserved -and
    $null -ne $rawFallbackProjection -and
    -not [bool]$rawFallbackProjection.seal_valid -and
    [long]$rawFallbackProjection.vehicle_bytes -eq 35948 -and
    [long]$rawFallbackProjection.ground_bytes -eq 69665 -and
    $null -eq $rawFallbackProjection.vehicle_sha256 -and
    $null -eq $rawFallbackProjection.ground_sha256 -and
    -not [bool]$rawFallbackProjection.streams_disposed_before_hash -and
    $null -ne $pumpFallbackProjection -and
    -not [bool]$pumpFallbackProjection.valid -and
    -not [bool]$pumpFallbackProjection.measurement_complete -and
    [double]$pumpFallbackProjection.target_ms -eq 75.0 -and
    [double]$pumpFallbackProjection.hard_limit_ms -eq 100.0 -and
    [string]$modeledFinalizationSummary.status -ceq 'ERROR' -and
    [int]$modeledFinalizationSummary.exit_code -eq 2 -and
    [int]$modeledFinalizationSummary.fixture.attempt_count -eq 1 -and
    [int]$modeledFinalizationSummary.fixture.write_count -eq 1 -and
    [string]$modeledFinalizationSummary.fixture.write_disposition -ceq
        'ACKNOWLEDGED_EXACTLY_ONCE' -and
    $modeledFinalizationJson -notmatch
        'backlogDrainEvidence|not been set|uninitialized')
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
      'finalization_primary_error_regression.json') -Value ([ordered]@{
        schema_version=1;modeled_offline=$true
        primary_failure=$finalizationPrimaryFailure
        finalization_failure=$finalizationShutdownFailure
        backlog_projection_helper_present=($null -ne $backlogProjectionCommand)
        failure_resolution_helper_present=($null -ne $failureResolutionCommand)
        raw_fallback_helper_present=($null -ne $rawFallbackCommand)
        pump_fallback_helper_present=($null -ne $pumpFallbackCommand)
        pre_try_backlog_projection=$preTryBacklogProjection
        completed_backlog_projection=$completedBacklogProjection
        raw_fallback_projection=$rawFallbackProjection
        pump_fallback_projection=$pumpFallbackProjection
        summary=$modeledFinalizationSummary
        passed=$finalizationRegressionValid
      })
  Add-SelfCase 'post_ground_closed_then_shutdown_failure_preserves_primary' `
      $finalizationRegressionValid `
      ('post_ground COM-closed remains primary through broken-pipe shutdown; ' +
       'ERROR/2 and ACKNOWLEDGED_EXACTLY_ONCE write1 survive without an ' +
       'uninitialized backlog projection')

  $failedCases = @($cases | Where-Object { -not $_.passed })
  [string]$modeledStatus = if ($failedCases.Count -ne 0) {
    'FAIL'
  } elseif ($SelfTestScenario -eq 'MEASURED_FAIL') {
    'FAIL'
  } elseif ($SelfTestScenario -eq 'POWER_OFF_TIMEOUT') {
    'FAIL'
  } elseif ($SelfTestScenario -eq 'READINESS_TIMEOUT') {
    'FAIL'
  } elseif ($SelfTestScenario -eq 'READINESS_SYNC_INVALID') {
    'FAIL'
  } elseif ($SelfTestScenario -eq 'POSTCLOSE_ERROR') {
    'ERROR'
  } else { 'PASS' }
  if ($SelfTestScenario -eq 'POSTCLOSE_ERROR') {
    Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
        'postclose_finalization_error.json') -Value ([ordered]@{
          schema_version=1; status='ERROR'; completed=$false
          modeled_offline=$true
          error='modeled post-close finalization error for exit-2 contract'
        })
  }
  $summary = [ordered]@{
    schema_version = 1
    test_id = 'HIL-DUAL-DIAG-PARAM-LIST-RUNNER-SELFTEST-001'
    status = $modeledStatus
    scenario = $SelfTestScenario
    serial_enumeration_count = 0
    serial_port_construction_count = 0
    serial_open_count = 0
    request_write_count = 0
    upload_count = 0
    fixture_hex = $script:ExpectedFixtureHex
    fixture_sha256 = $script:ExpectedFixtureSha256
    canonical_definition_sha256 = $definitions.sha256
    canonical_definition_count = $definitions.count
    cases = $cases.ToArray()
    failed_case_count = $failedCases.Count
  }
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
      'selftest_summary.json') -Value $summary
  $hashRows = New-Object 'System.Collections.Generic.List[object]'
  foreach ($file in @(Get-ChildItem -LiteralPath $SelfTestEvidenceDirectory `
      -File -Recurse | Sort-Object FullName)) {
    $relative = $file.FullName.Substring(
        $SelfTestEvidenceDirectory.Length).TrimStart('\')
    $hashRows.Add([pscustomobject][ordered]@{
      file = $relative
      size_bytes = [long]$file.Length
      sha256 = (Get-FileHash -Algorithm SHA256 `
          -LiteralPath $file.FullName).Hash
    })
  }
  Write-JsonDurable -Path (Join-Path $SelfTestEvidenceDirectory `
      'artifact_hashes.json') -Value $hashRows.ToArray()
  [string]$selfStatus = [string]$summary.status
  Write-Host ('FINAL {0} output={1}' -f $selfStatus,
      $SelfTestEvidenceDirectory)
  return $modeledStatus
}

# The hidden broker branch precedes SelfTest and every live COM enumeration.
# Synthetic broker modes remain COM-free; serial OPEN occurs only after the
# parent has assigned the child to its kill-on-close Job Object and HELLO has
# authenticated the recomputed runner hash, parent PID, and nonce.
if ($ReaderBrokerMode) {
  [int]$readerBrokerExitCode = Invoke-ReaderBrokerMode
  exit $readerBrokerExitCode
}

# This immediate return deliberately precedes every live COM enumeration,
# serial-port construction, and handle-open statement. SelfTest is disk-only.
if ($SelfTest) {
  [string]$offlineStatus = Invoke-OfflineSelfTest
  if ($offlineStatus -eq 'ERROR') { exit 2 }
  if ($offlineStatus -eq 'FAIL') { exit 1 }
  return
}

# LIVE_IMPLEMENTATION_FOLLOWS

function Add-TimelineEvent {
  param([string]$Name, [hashtable]$Details = @{})
  $script:Timeline.Add([pscustomobject][ordered]@{
    event=$Name
    elapsed_ms=[Math]::Round($script:RunWatch.Elapsed.TotalMilliseconds, 3)
    utc=[DateTime]::UtcNow.ToString('o')
    phase=$script:CurrentPhase
    details=[pscustomobject]$Details
  })
}

function Add-LiveProgressRecord {
  param([string]$Event, [hashtable]$Details = @{})
  [string[]]$reservedKeys = @('event','elapsed_s','utc','phase')
  $row = [ordered]@{
    event=$Event
    elapsed_s=[Math]::Round($script:RunWatch.Elapsed.TotalSeconds, 3)
    utc=[DateTime]::UtcNow.ToString('o')
    phase=$script:CurrentPhase
  }
  foreach ($key in $Details.Keys) {
    if ($reservedKeys -contains [string]$key) {
      throw "Live progress detail cannot override reserved field '$key'."
    }
    $row[$key] = $Details[$key]
  }
  Write-DurableJsonlRecord -Stream $script:LiveProgressStream -Value $row
}

function Get-LivePortInventory {
  [string[]]$portNames = @([System.IO.Ports.SerialPort]::GetPortNames())
  $rows = New-Object 'System.Collections.Generic.List[object]'
  $entities = @(Get-CimInstance -ClassName Win32_PnPEntity |
      Where-Object { [string]$_.Name -match '\(COM[0-9]+\)' })
  foreach ($portName in $portNames) {
    $matches = @($entities | Where-Object {
        [string]$_.Name -match ('\(' + [regex]::Escape($portName) + '\)') })
    foreach ($entity in $matches) {
      $rows.Add([pscustomobject][ordered]@{
        port=$portName
        pnp_device_id=[string]$entity.PNPDeviceID
        status=[string]$entity.Status
        problem_code=[int]$entity.ConfigManagerErrorCode
        name=[string]$entity.Name
      })
    }
  }
  return $rows.ToArray()
}

function Wait-ForBothPortsAbsent {
  param([string]$First, [string]$Second, [int]$RequiredAbsentMs,
        [int]$TimeoutSeconds)
  $watch = [System.Diagnostics.Stopwatch]::StartNew()
  [Nullable[double]]$absentSince = $null
  [string[]]$lastPorts = @()
  while ($watch.Elapsed.TotalSeconds -lt $TimeoutSeconds) {
    $lastPorts = @([System.IO.Ports.SerialPort]::GetPortNames())
    [bool]$firstFound = @($lastPorts | Where-Object {
        $_ -ieq $First }).Count -gt 0
    [bool]$secondFound = @($lastPorts | Where-Object {
        $_ -ieq $Second }).Count -gt 0
    [double]$nowMs = $watch.Elapsed.TotalMilliseconds
    if (-not $firstFound -and -not $secondFound) {
      if ($null -eq $absentSince) { $absentSince = $nowMs }
      if ($nowMs - [double]$absentSince -ge $RequiredAbsentMs) {
        return [pscustomobject][ordered]@{
          confirmed=$true; required_absent_ms=$RequiredAbsentMs
          continuous_absent_ms=[Math]::Round(
              $nowMs - [double]$absentSince, 3)
          elapsed_ms=[Math]::Round($nowMs, 3); ports=$lastPorts
        }
      }
    } else {
      $absentSince = $null
    }
    Start-Sleep -Milliseconds 100
  }
  return [pscustomobject][ordered]@{
    confirmed=$false; required_absent_ms=$RequiredAbsentMs
    continuous_absent_ms=0
    elapsed_ms=[Math]::Round($watch.Elapsed.TotalMilliseconds, 3)
    ports=$lastPorts
  }
}

function Wait-ForBoundPortIdentities {
  param(
    [int]$TimeoutSeconds,
    [ValidateRange(1000,60000)][int]$RequiredStableMs =
        $script:BoundPortIdentityStableMs
  )
  $watch = [System.Diagnostics.Stopwatch]::StartNew()
  $lastInventory = @()
  $lastBinding = $null
  $validSinceMs = $null
  [double]$continuousStableMs = 0.0
  while ($watch.Elapsed.TotalSeconds -lt $TimeoutSeconds) {
    $lastInventory = @(Get-LivePortInventory)
    $lastBinding = Test-RoleIdentityBinding -Inventory $lastInventory `
        -ExpectedVehiclePort $VehiclePort `
        -ExpectedVehicleIdentity $VehiclePnpDeviceId `
        -ExpectedGroundPort $GroundPort `
        -ExpectedGroundIdentity $GroundPnpDeviceId
    if ($lastBinding.valid) {
      [double]$nowMs = $watch.Elapsed.TotalMilliseconds
      if ($null -eq $validSinceMs) { $validSinceMs = $nowMs }
      $continuousStableMs = $nowMs - [double]$validSinceMs
      if ($continuousStableMs -ge $RequiredStableMs) {
        return [pscustomobject][ordered]@{
          found=$true; elapsed_ms=[Math]::Round($nowMs, 3)
          required_stable_ms=$RequiredStableMs
          continuous_stable_ms=[Math]::Round($continuousStableMs, 3)
          inventory=$lastInventory; binding=$lastBinding
        }
      }
    } else {
      $validSinceMs = $null
      $continuousStableMs = 0.0
    }
    Start-Sleep -Milliseconds 250
  }
  return [pscustomobject][ordered]@{
    found=$false; elapsed_ms=[Math]::Round(
        $watch.Elapsed.TotalMilliseconds, 3)
    required_stable_ms=$RequiredStableMs
    continuous_stable_ms=[Math]::Round($continuousStableMs, 3)
    inventory=$lastInventory; binding=$lastBinding
  }
}

function New-ConfiguredSerialPort {
  param([string]$Port, [int]$Baud)
  $serial = New-Object System.IO.Ports.SerialPort
  $serial.PortName = $Port
  $serial.BaudRate = $Baud
  $serial.DataBits = 8
  $serial.Parity = [System.IO.Ports.Parity]::None
  $serial.StopBits = [System.IO.Ports.StopBits]::One
  $serial.Handshake = [System.IO.Ports.Handshake]::None
  $serial.ReadTimeout = 20
  $serial.WriteTimeout = 2000
  $serial.DtrEnable = $false
  $serial.RtsEnable = $false
  return $serial
}

function New-CaptureState {
  param([string]$Role, [string]$TagBase, $RawStream, $Mavlink)
  return [pscustomobject][ordered]@{
    Role=$Role; TagBase=$TagBase
    TagBaseBytes=[System.Text.Encoding]::ASCII.GetBytes($TagBase)
    RawStream=$RawStream; RawBytes=[long]0
    LastProducerSequence=[long]-1
    ReadBuffer=New-Object byte[] 4096
    Chunks=New-Object 'System.Collections.Generic.List[object]'
    TaggedLines=New-Object 'System.Collections.Generic.List[object]'
    MatcherCandidate=New-Object 'System.Collections.Generic.List[byte]'
    MatcherStartOffset=[long]-1; MatcherOverflows=[uint64]0
    Mavlink=$Mavlink
  }
}

function Reset-TagMatcherCandidate {
  param($State)
  $State.MatcherCandidate.Clear()
  $State.MatcherStartOffset = [long]-1
}

function Add-TaggedMatcherByte {
  param($State, [byte]$Byte, [long]$RawOffset,
        [Nullable[double]]$ElapsedMs = $null,
        [string]$ProducerPhase = '', [string]$ProducerEpoch = '')
  [byte]$first = $State.TagBaseBytes[0]
  if ($State.MatcherCandidate.Count -eq 0) {
    if ($Byte -eq $first) {
      $State.MatcherStartOffset = $RawOffset
      $State.MatcherCandidate.Add($Byte)
    }
    return
  }
  $State.MatcherCandidate.Add($Byte)
  [int]$count = $State.MatcherCandidate.Count
  [bool]$validPrefix = $true
  if ($count -le $State.TagBaseBytes.Length) {
    $validPrefix = ($Byte -eq $State.TagBaseBytes[$count - 1])
  } elseif ($count -eq $State.TagBaseBytes.Length + 1) {
    $validPrefix = ($Byte -ge [byte][char]'1' -and
        $Byte -le [byte][char]'3')
  } elseif ($count -eq $State.TagBaseBytes.Length + 2) {
    $validPrefix = ($Byte -eq [byte][char]' ')
  }
  if (-not $validPrefix) {
    Reset-TagMatcherCandidate -State $State
    if ($Byte -eq $first) {
      $State.MatcherStartOffset = $RawOffset
      $State.MatcherCandidate.Add($Byte)
    }
    return
  }
  if ($count -gt $script:MaximumTaggedLineBytes) {
    ++$State.MatcherOverflows
    Reset-TagMatcherCandidate -State $State
    return
  }
  if ($count -le $State.TagBaseBytes.Length + 2 -or $Byte -ne 0x0A) {
    return
  }
  [byte[]]$lineBytes = $State.MatcherCandidate.ToArray()
  [int]$lineLength = $lineBytes.Length
  while ($lineLength -gt 0 -and
      ($lineBytes[$lineLength - 1] -eq 0x0A -or
       $lineBytes[$lineLength - 1] -eq 0x0D)) { --$lineLength }
  [string]$line = [System.Text.Encoding]::ASCII.GetString(
      $lineBytes, 0, $lineLength)
  [string[]]$tokens = @($line -split '\s+')
  $fields = [ordered]@{}
  for ($index = 1; $index -lt $tokens.Count; ++$index) {
    [int]$separator = $tokens[$index].IndexOf('=')
    if ($separator -le 0) { continue }
    [string]$key = $tokens[$index].Substring(0, $separator)
    if ($key -match '^[A-Za-z][A-Za-z0-9_.-]*$') {
      $fields[$key] = $tokens[$index].Substring($separator + 1)
    }
  }
  [uint32]$q = 0
  [uint64]$ms = 0
  [bool]$validCorrelation = ($fields.Contains('q') -and
      $fields.Contains('ms') -and
      [uint32]::TryParse([string]$fields['q'], [ref]$q) -and
      $q -ne 0 -and
      [uint64]::TryParse([string]$fields['ms'], [ref]$ms))
  [double]$effectiveElapsedMs = if ($null -ne $ElapsedMs) {
    [double]$ElapsedMs
  } else {
    [double]$script:RunWatch.Elapsed.TotalMilliseconds
  }
  $State.TaggedLines.Add([pscustomobject][ordered]@{
    sequence=$State.TaggedLines.Count; role=$State.Role; tag=$tokens[0]
    line=$line; fields=[pscustomobject]$fields
    valid_correlation=$validCorrelation
    q_uint32=if ($validCorrelation) {$q} else {$null}
    ms_uint64=if ($validCorrelation) {$ms} else {$null}
    raw_start_offset=$State.MatcherStartOffset
    raw_end_offset_exclusive=$RawOffset + 1
    elapsed_ms=[Math]::Round($effectiveElapsedMs, 3)
    utc=[DateTime]::UtcNow.ToString('o')
    phase=if([string]::IsNullOrEmpty($ProducerPhase)){
      [string]$script:CurrentPhase
    }else{$ProducerPhase}
    producer_epoch=if([string]::IsNullOrEmpty($ProducerEpoch)){
      [string]$script:CurrentPhase
    }else{$ProducerEpoch}
  })
  Reset-TagMatcherCandidate -State $State
}

function Add-CaptureBytes {
  param(
    $State,
    [byte[]]$Buffer,
    [int]$Count,
    [Nullable[double]]$ProducerElapsedMs = $null,
    [Nullable[long]]$ProducerSequence = $null,
    [Nullable[long]]$ProducerRawStartOffset = $null,
    [Nullable[long]]$ProducerTimestampTicks = $null,
    [string]$ProducerPhase = '',
    [string]$ProducerEpoch = ''
  )
  if ($Count -le 0) { return }
  [long]$startOffset = $State.RawBytes
  [bool]$hasProducerMetadata = ($null -ne $ProducerElapsedMs -or
      $null -ne $ProducerSequence -or
      $null -ne $ProducerRawStartOffset -or
      $null -ne $ProducerTimestampTicks)
  if ($hasProducerMetadata -and ($null -eq $ProducerElapsedMs -or
      $null -eq $ProducerSequence -or
      $null -eq $ProducerRawStartOffset -or
      $null -eq $ProducerTimestampTicks)) {
    throw 'incomplete producer capture metadata'
  }
  if ($hasProducerMetadata -and
      [long]$ProducerRawStartOffset -ne $startOffset) {
    throw ('producer raw offset discontinuity: role={0} expected={1} actual={2}' -f
      $State.Role, $startOffset, [long]$ProducerRawStartOffset)
  }
  [long]$expectedProducerSequence = [long]$State.LastProducerSequence + 1
  if ($hasProducerMetadata -and
      [long]$ProducerSequence -ne $expectedProducerSequence) {
    throw ('producer sequence discontinuity: role={0} expected={1} actual={2}' -f
      $State.Role, $expectedProducerSequence, [long]$ProducerSequence)
  }
  [double]$consumerElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
  [double]$captureElapsedMs = if ($hasProducerMetadata) {
    [double]$ProducerElapsedMs
  } else { $consumerElapsedMs }
  $State.RawStream.Write($Buffer, 0, $Count)
  $State.RawBytes = [long]$State.RawBytes + $Count
  if ($hasProducerMetadata) {
    $State.LastProducerSequence = [long]$ProducerSequence
  }
  $State.Chunks.Add([pscustomobject][ordered]@{
    raw_start_offset=$startOffset; byte_count=$Count
    producer_sequence=if($hasProducerMetadata){[long]$ProducerSequence}else{$null}
    producer_timestamp_ticks=if($hasProducerMetadata){
      [long]$ProducerTimestampTicks
    }else{$null}
    producer_phase=if($hasProducerMetadata){$ProducerPhase}else{
      [string]$script:CurrentPhase
    }
    producer_epoch=if($hasProducerMetadata){$ProducerEpoch}else{
      [string]$script:CurrentPhase
    }
    elapsed_ms=[Math]::Round($captureElapsedMs, 3)
    consumer_elapsed_ms=[Math]::Round($consumerElapsedMs, 3)
    consumer_delay_ms=[Math]::Round(
        [Math]::Max(0.0, $consumerElapsedMs - $captureElapsedMs), 3)
    utc=[DateTime]::UtcNow.ToString('o')
    phase=if($hasProducerMetadata){$ProducerPhase}else{
      [string]$script:CurrentPhase
    }
    consumer_phase=[string]$script:CurrentPhase
  })
  [double]$elapsedMs = $captureElapsedMs
  for ($index = 0; $index -lt $Count; ++$index) {
    [long]$offset = $startOffset + $index
    Add-TaggedMatcherByte -State $State -Byte $Buffer[$index] `
        -RawOffset $offset -ElapsedMs $elapsedMs `
        -ProducerPhase $ProducerPhase -ProducerEpoch $ProducerEpoch
    if ($null -ne $State.Mavlink) {
      Add-MavlinkAnalysisByte -Parser $State.Mavlink -Byte $Buffer[$index] `
          -RawOffset $offset -ElapsedMs $elapsedMs `
          -ProducerPhase $ProducerPhase -ProducerEpoch $ProducerEpoch
    }
  }
}

function Get-PumpFairnessRoleState {
  param([Parameter(Mandatory = $true)]$CaptureState)
  if ($null -eq $script:PumpFairness) { return $null }
  if ([string]$CaptureState.Role -ceq 'vehicle') {
    return $script:PumpFairness.vehicle
  }
  if ([string]$CaptureState.Role -ceq 'ground') {
    return $script:PumpFairness.ground
  }
  return $null
}

function Add-PumpFairnessViolation {
  param(
    [Parameter(Mandatory = $true)]$RoleState,
    [Parameter(Mandatory = $true)][string]$Kind,
    [Parameter(Mandatory = $true)][double]$StartedElapsedMs,
    [Parameter(Mandatory = $true)][double]$FinishedElapsedMs,
    [Parameter(Mandatory = $true)][double]$DurationMs,
    [Parameter(Mandatory = $true)][string]$Phase,
    [Parameter(Mandatory = $true)][int]$BytesRead,
    [Parameter(Mandatory = $true)][long]$RawStartOffset,
    [Parameter(Mandatory = $true)][long]$RawEndOffsetExclusive,
    [Parameter(Mandatory = $true)][string]$AdminStage,
    [Parameter(Mandatory = $true)][int]$Gc0Start,
    [Parameter(Mandatory = $true)][int]$Gc0End,
    [Parameter(Mandatory = $true)][int]$Gc1Start,
    [Parameter(Mandatory = $true)][int]$Gc1End,
    [Parameter(Mandatory = $true)][int]$Gc2Start,
    [Parameter(Mandatory = $true)][int]$Gc2End
  )
  if ($DurationMs -lt $script:PumpFairnessTargetMs) { return }
  $RoleState.violation_event_total_count =
      [uint64]$RoleState.violation_event_total_count + [uint64]1
  if ($RoleState.violation_events.Count -ge
      $script:MaxPumpFairnessViolationEvents) {
    $RoleState.violation_event_overflow_count =
        [uint64]$RoleState.violation_event_overflow_count + [uint64]1
    return
  }
  $RoleState.violation_events.Add([pscustomobject][ordered]@{
    sequence=[uint64]$RoleState.violation_event_total_count - [uint64]1
    role=[string]$RoleState.role;kind=$Kind
    started_elapsed_ms=[Math]::Round($StartedElapsedMs,3)
    finished_elapsed_ms=[Math]::Round($FinishedElapsedMs,3)
    duration_ms=[Math]::Round($DurationMs,3)
    phase=$Phase;bytes_read=$BytesRead
    raw_start_offset=$RawStartOffset
    raw_end_offset_exclusive=$RawEndOffsetExclusive
    admin_stage=$AdminStage
    gc0_start=$Gc0Start;gc0_end=$Gc0End
    gc1_start=$Gc1Start;gc1_end=$Gc1End
    gc2_start=$Gc2Start;gc2_end=$Gc2End
    overflow=$false
  })
}

function Start-PumpFairnessService {
  param(
    [Parameter(Mandatory = $true)]$CaptureState,
    [AllowNull()]$RoleState
  )
  if ($null -eq $RoleState) { return }
  if ([bool]$RoleState.service_active) {
    $RoleState.reentry_count = [uint64]$RoleState.reentry_count + [uint64]1
    $RoleState.integrity_failure_latched = $true
    throw ('pump fairness service reentry refused: role=' +
      [string]$RoleState.role)
  }
  [double]$startedMs = if ($null -ne $script:RunWatch) {
    $script:RunWatch.Elapsed.TotalMilliseconds
  } else { [double]0 }
  [double]$gapMs = $startedMs -
      [double]$RoleState.last_service_started_elapsed_ms
  [long]$rawOffset = [long]$CaptureState.RawBytes
  [int]$gc0 = [GC]::CollectionCount(0)
  [int]$gc1 = [GC]::CollectionCount(1)
  [int]$gc2 = [GC]::CollectionCount(2)
  if ($gapMs -gt [double]$RoleState.max_service_gap_ms) {
    $RoleState.max_service_gap_ms = $gapMs
    $RoleState.max_service_gap_phase = [string]$script:CurrentPhase
  }
  if ($gapMs -ge $script:PumpFairnessTargetMs) {
    $RoleState.service_gap_over_target_count =
        [uint64]$RoleState.service_gap_over_target_count + [uint64]1
    Add-PumpFairnessViolation -RoleState $RoleState -Kind 'service_gap' `
        -StartedElapsedMs ([double]$RoleState.last_service_started_elapsed_ms) `
        -FinishedElapsedMs $startedMs -DurationMs $gapMs `
        -Phase ([string]$script:CurrentPhase) -BytesRead ([int][Math]::Max(
          0, $rawOffset - [long]$RoleState.last_service_start_raw_offset)) `
        -RawStartOffset ([long]$RoleState.last_service_start_raw_offset) `
        -RawEndOffsetExclusive $rawOffset `
        -AdminStage ([string]$script:PumpAdminStage) `
        -Gc0Start ([int]$RoleState.last_service_start_gc0) -Gc0End $gc0 `
        -Gc1Start ([int]$RoleState.last_service_start_gc1) -Gc1End $gc1 `
        -Gc2Start ([int]$RoleState.last_service_start_gc2) -Gc2End $gc2
  }
  if ($gapMs -ge $script:PumpFairnessHardLimitMs) {
    $RoleState.service_gap_over_hard_limit_count =
        [uint64]$RoleState.service_gap_over_hard_limit_count + [uint64]1
  }
  $RoleState.service_count = [uint64]$RoleState.service_count + [uint64]1
  $RoleState.last_service_started_elapsed_ms = $startedMs
  $RoleState.last_service_start_raw_offset = $rawOffset
  $RoleState.last_service_start_gc0 = $gc0
  $RoleState.last_service_start_gc1 = $gc1
  $RoleState.last_service_start_gc2 = $gc2
  $RoleState.service_started_elapsed_ms = $startedMs
  $RoleState.service_start_raw_offset = $rawOffset
  $RoleState.service_start_phase = [string]$script:CurrentPhase
  $RoleState.service_start_admin_stage = [string]$script:PumpAdminStage
  $RoleState.service_start_gc0 = $gc0
  $RoleState.service_start_gc1 = $gc1
  $RoleState.service_start_gc2 = $gc2
  $RoleState.service_active = $true
}

function Complete-PumpFairnessService {
  param(
    [Parameter(Mandatory = $true)]$CaptureState,
    [AllowNull()]$RoleState,
    [int]$BytesRead
  )
  if ($null -eq $RoleState) { return }
  if (-not [bool]$RoleState.service_active) {
    $RoleState.completion_without_start_count =
        [uint64]$RoleState.completion_without_start_count + [uint64]1
    $RoleState.integrity_failure_latched = $true
    throw ('pump fairness completion_without_start refused: role=' +
      [string]$RoleState.role)
  }
  [double]$finishedMs = if ($null -ne $script:RunWatch) {
    $script:RunWatch.Elapsed.TotalMilliseconds
  } else { [double]$RoleState.service_started_elapsed_ms }
  [double]$durationMs = $finishedMs -
      [double]$RoleState.service_started_elapsed_ms
  [int]$gc0 = [GC]::CollectionCount(0)
  [int]$gc1 = [GC]::CollectionCount(1)
  [int]$gc2 = [GC]::CollectionCount(2)
  try {
    $RoleState.bytes_read = [uint64]$RoleState.bytes_read +
        [uint64][Math]::Max(0, $BytesRead)
    if ($BytesRead -eq 0) {
      $RoleState.zero_byte_service_count =
          [uint64]$RoleState.zero_byte_service_count + [uint64]1
    }
    if ($durationMs -gt [double]$RoleState.max_read_parse_duration_ms) {
      $RoleState.max_read_parse_duration_ms = $durationMs
      $RoleState.max_read_parse_duration_phase = [string]$script:CurrentPhase
      $RoleState.max_read_parse_duration_bytes = $BytesRead
    }
    if ($durationMs -ge $script:PumpFairnessTargetMs) {
      $RoleState.read_parse_duration_over_target_count =
          [uint64]$RoleState.read_parse_duration_over_target_count + [uint64]1
      Add-PumpFairnessViolation -RoleState $RoleState `
          -Kind 'read_parse_duration' `
          -StartedElapsedMs ([double]$RoleState.service_started_elapsed_ms) `
          -FinishedElapsedMs $finishedMs -DurationMs $durationMs `
          -Phase ([string]$RoleState.service_start_phase) `
          -BytesRead $BytesRead `
          -RawStartOffset ([long]$RoleState.service_start_raw_offset) `
          -RawEndOffsetExclusive ([long]$CaptureState.RawBytes) `
          -AdminStage ([string]$RoleState.service_start_admin_stage) `
          -Gc0Start ([int]$RoleState.service_start_gc0) -Gc0End $gc0 `
          -Gc1Start ([int]$RoleState.service_start_gc1) -Gc1End $gc1 `
          -Gc2Start ([int]$RoleState.service_start_gc2) -Gc2End $gc2
    }
    if ($durationMs -ge $script:PumpFairnessHardLimitMs) {
      $RoleState.read_parse_duration_over_hard_limit_count =
          [uint64]$RoleState.read_parse_duration_over_hard_limit_count +
          [uint64]1
    }
  } finally {
    $RoleState.service_active = $false
  }
}

function Copy-PumpFairnessRoleEvidence {
  param([Parameter(Mandatory = $true)]$RoleState)
  return [pscustomobject][ordered]@{
    role=[string]$RoleState.role
    service_count=[uint64]$RoleState.service_count
    bytes_read=[uint64]$RoleState.bytes_read
    zero_byte_service_count=[uint64]$RoleState.zero_byte_service_count
    last_service_started_elapsed_ms=[Math]::Round(
        [double]$RoleState.last_service_started_elapsed_ms,3)
    max_service_gap_ms=[Math]::Round(
        [double]$RoleState.max_service_gap_ms,3)
    max_service_gap_phase=$RoleState.max_service_gap_phase
    service_gap_over_target_count=
        [uint64]$RoleState.service_gap_over_target_count
    service_gap_over_hard_limit_count=
        [uint64]$RoleState.service_gap_over_hard_limit_count
    max_read_parse_duration_ms=[Math]::Round(
        [double]$RoleState.max_read_parse_duration_ms,3)
    max_read_parse_duration_phase=$RoleState.max_read_parse_duration_phase
    max_read_parse_duration_bytes=[int]$RoleState.max_read_parse_duration_bytes
    read_parse_duration_over_target_count=
        [uint64]$RoleState.read_parse_duration_over_target_count
    read_parse_duration_over_hard_limit_count=
        [uint64]$RoleState.read_parse_duration_over_hard_limit_count
    service_active=[bool]$RoleState.service_active
    reentry_count=[uint64]$RoleState.reentry_count
    completion_without_start_count=
        [uint64]$RoleState.completion_without_start_count
    integrity_failure_latched=[bool]$RoleState.integrity_failure_latched
    violation_event_cap=$script:MaxPumpFairnessViolationEvents
    violation_event_count=$RoleState.violation_events.Count
    violation_event_total_count=
        [uint64]$RoleState.violation_event_total_count
    violation_event_overflow_count=
        [uint64]$RoleState.violation_event_overflow_count
    violation_events=$RoleState.violation_events.ToArray()
  }
}

function Get-PumpFairnessEvidence {
  param($VehicleState = $null, $GroundState = $null)
  if ($null -ne $script:DualPortReaderWorker) {
    $readerSnapshot = $script:DualPortReaderWorker.Snapshot()
    $newReaderRoleEvidence = {
      param($RoleSnapshot, $CaptureState)
      [double]$consumerMaximumDelayMs = 0.0
      if ($null -ne $CaptureState -and $CaptureState.Chunks.Count -gt 0) {
        $delayMeasurement = @($CaptureState.Chunks.ToArray() |
            Measure-Object -Property consumer_delay_ms -Maximum)
        if ($delayMeasurement.Count -eq 1 -and
            $null -ne $delayMeasurement[0].Maximum) {
          $consumerMaximumDelayMs = [double]$delayMeasurement[0].Maximum
        }
      }
      $roleViolationEvents =
          New-Object 'System.Collections.Generic.List[object]'
      foreach ($violation in @($RoleSnapshot.ViolationEvents)) {
        $roleViolationEvents.Add([pscustomobject][ordered]@{
          role=[string]$RoleSnapshot.Role
          sequence=[long]$violation.Sequence
          kind=[string]$violation.Kind
          started_timestamp_ticks=[long]$violation.StartedTimestampTicks
          finished_timestamp_ticks=[long]$violation.FinishedTimestampTicks
          duration_ms=[Math]::Round([double]$violation.DurationMs,3)
          context_id=[uint32]$violation.ContextId
          phase=[string]$violation.Phase
          epoch=[string]$violation.Epoch
          bytes_read=[int]$violation.BytesRead
          raw_start_offset=[long]$violation.RawStartOffset
          raw_end_offset_exclusive=[long]$violation.RawEndOffsetExclusive
          service_ordinal=[long]$violation.ServiceOrdinal
          boundary_generation=[long]$violation.BoundaryGeneration
          boundary_kind=[string]$violation.BoundaryKind
        })
      }
      return [pscustomobject][ordered]@{
        role=[string]$RoleSnapshot.Role
        producer_thread_started=[bool]$RoleSnapshot.Started
        producer_thread_stop_requested=[bool]$RoleSnapshot.StopRequested
        producer_thread_joined=[bool]$RoleSnapshot.Joined
        producer_thread_alive=[bool]$RoleSnapshot.ThreadAlive
        service_count=[uint64]$RoleSnapshot.ServiceCount
        bytes_read=[uint64]$RoleSnapshot.BytesRead
        zero_byte_service_count=[uint64]$RoleSnapshot.ZeroByteServiceCount
        max_service_gap_ms=[Math]::Round(
            [double]$RoleSnapshot.MaxServiceGapMs,3)
        service_gap_over_target_count=
            [uint64]$RoleSnapshot.ServiceGapOverTargetCount
        service_gap_over_hard_limit_count=
            [uint64]$RoleSnapshot.ServiceGapOverHardLimitCount
        max_read_parse_duration_ms=[Math]::Round(
            [double]$RoleSnapshot.MaxReadDurationMs,3)
        read_parse_duration_over_target_count=
            [uint64]$RoleSnapshot.ReadDurationOverTargetCount
        read_parse_duration_over_hard_limit_count=
            [uint64]$RoleSnapshot.ReadDurationOverHardLimitCount
        ring_capacity=[int]$RoleSnapshot.RingCapacity
        queue_depth=[int]$RoleSnapshot.QueueDepth
        produced_sequence=[long]$RoleSnapshot.ProducedSequence
        consumed_sequence=[long]$RoleSnapshot.ConsumedSequence
        produced_raw_bytes=[long]$RoleSnapshot.ProducedRawBytes
        consumed_raw_bytes=[long]$RoleSnapshot.ConsumedRawBytes
        overflow_latched=[bool]$RoleSnapshot.OverflowLatched
        overflow_count=[uint64]$RoleSnapshot.OverflowCount
        fatal_error=$RoleSnapshot.FatalError
        producer_fair=[bool]$RoleSnapshot.IsFair
        ring_consistent=[bool]$RoleSnapshot.IsConsistent
        consumer_max_delay_ms=[Math]::Round($consumerMaximumDelayMs,3)
        consumer_delay_is_fairness_clock=$false
        violation_event_cap=[int]$RoleSnapshot.ViolationEventCap
        violation_event_count=[int]$RoleSnapshot.ViolationEventCount
        violation_event_total_count=
            [uint64]$RoleSnapshot.ViolationEventTotalCount
        violation_event_overflow_count=
            [uint64]$RoleSnapshot.ViolationEventOverflowCount
        violation_events=$roleViolationEvents.ToArray()
      }
    }
    $vehicle = & $newReaderRoleEvidence $readerSnapshot.Vehicle $VehicleState
    $ground = & $newReaderRoleEvidence $readerSnapshot.Ground $GroundState
    [bool]$measurementComplete = ($vehicle.service_count -gt 0 -and
        $ground.service_count -gt 0)
    [bool]$valid = ($measurementComplete -and
        [bool]$readerSnapshot.Valid -and
        [double]$vehicle.max_service_gap_ms -lt
            $script:PumpFairnessHardLimitMs -and
        [double]$ground.max_service_gap_ms -lt
            $script:PumpFairnessHardLimitMs -and
        [double]$vehicle.max_read_parse_duration_ms -lt
            $script:PumpFairnessHardLimitMs -and
        [double]$ground.max_read_parse_duration_ms -lt
            $script:PumpFairnessHardLimitMs -and
        -not [bool]$vehicle.overflow_latched -and
        -not [bool]$ground.overflow_latched -and
        ($null -eq $script:ReaderShutdownEvidence -or
          [bool]$script:ReaderShutdownEvidence.valid))
    $rootViolationEvents =
        New-Object 'System.Collections.Generic.List[object]'
    foreach ($violation in @($vehicle.violation_events)) {
      [void]$rootViolationEvents.Add($violation)
    }
    foreach ($violation in @($ground.violation_events)) {
      [void]$rootViolationEvents.Add($violation)
    }
    return [pscustomobject][ordered]@{
      schema_version=4;measurement_complete=$measurementComplete;valid=$valid
      clock='producer_stopwatch';consumer_timestamp_substitution=$false
      target_ms=$script:PumpFairnessTargetMs
      hard_limit_ms=$script:PumpFairnessHardLimitMs
      strict_comparison='max producer gap and read/enqueue duration < hard_limit_ms'
      ring_slot_count=$script:ReaderRingSlotCount
      violation_event_cap=$script:MaxPumpFairnessViolationEvents
      violation_event_cap_scope='per_role'
      violation_event_count=([int]$vehicle.violation_event_count +
          [int]$ground.violation_event_count)
      violation_event_total_count=(
          [uint64]$vehicle.violation_event_total_count +
          [uint64]$ground.violation_event_total_count)
      violation_event_overflow_count=(
          [uint64]$vehicle.violation_event_overflow_count +
          [uint64]$ground.violation_event_overflow_count)
      violation_events=$rootViolationEvents.ToArray()
      started_elapsed_ms=$portsOpenedElapsedMs
      completed_elapsed_ms=[Math]::Round(
          [double]$script:RunWatch.Elapsed.TotalMilliseconds,3)
      reader_shutdown=$script:ReaderShutdownEvidence
      vehicle=$vehicle;ground=$ground
    }
  }
  if ($null -eq $script:PumpFairness) {
    return [pscustomobject][ordered]@{
      schema_version=2;measurement_complete=$false;valid=$false
      target_ms=$script:PumpFairnessTargetMs
      hard_limit_ms=$script:PumpFairnessHardLimitMs
      violation_event_cap=$script:MaxPumpFairnessViolationEvents
      violation_event_cap_scope='per_role'
      violation_event_count=0;violation_event_overflow_count=0
      violation_events=[object[]]@()
      started_elapsed_ms=$null;completed_elapsed_ms=$null
      vehicle=$null;ground=$null
    }
  }
  $vehicle = Copy-PumpFairnessRoleEvidence `
      -RoleState $script:PumpFairness.vehicle
  $ground = Copy-PumpFairnessRoleEvidence `
      -RoleState $script:PumpFairness.ground
  [bool]$measurementComplete = ($vehicle.service_count -gt 0 -and
      $ground.service_count -gt 0)
  [bool]$valid = ($measurementComplete -and
      $vehicle.service_gap_over_hard_limit_count -eq 0 -and
      $ground.service_gap_over_hard_limit_count -eq 0 -and
      $vehicle.read_parse_duration_over_hard_limit_count -eq 0 -and
      $ground.read_parse_duration_over_hard_limit_count -eq 0 -and
      -not [bool]$vehicle.service_active -and
      -not [bool]$ground.service_active -and
      -not [bool]$vehicle.integrity_failure_latched -and
      -not [bool]$ground.integrity_failure_latched -and
      $vehicle.reentry_count -eq 0 -and $ground.reentry_count -eq 0 -and
      $vehicle.completion_without_start_count -eq 0 -and
      $ground.completion_without_start_count -eq 0 -and
      [double]$vehicle.max_service_gap_ms -lt
          $script:PumpFairnessHardLimitMs -and
      [double]$ground.max_service_gap_ms -lt
          $script:PumpFairnessHardLimitMs -and
      [double]$vehicle.max_read_parse_duration_ms -lt
          $script:PumpFairnessHardLimitMs -and
      [double]$ground.max_read_parse_duration_ms -lt
          $script:PumpFairnessHardLimitMs)
  return [pscustomobject][ordered]@{
    schema_version=2;measurement_complete=$measurementComplete;valid=$valid
    target_ms=$script:PumpFairnessTargetMs
    hard_limit_ms=$script:PumpFairnessHardLimitMs
    violation_event_cap=$script:MaxPumpFairnessViolationEvents
    violation_event_cap_scope='per_role'
    violation_event_count=([int]$vehicle.violation_event_count +
        [int]$ground.violation_event_count)
    violation_event_overflow_count=(
        [uint64]$vehicle.violation_event_overflow_count +
        [uint64]$ground.violation_event_overflow_count)
    violation_events=[object[]]@(
        @($vehicle.violation_events) + @($ground.violation_events))
    started_elapsed_ms=[Math]::Round(
        [double]$script:PumpFairness.started_elapsed_ms,3)
    completed_elapsed_ms=[Math]::Round(
        [double]$script:RunWatch.Elapsed.TotalMilliseconds,3)
    vehicle=$vehicle;ground=$ground
  }
}

function Read-SerialAvailable {
  param(
    $Serial,
    $State,
    [int]$MaximumReads = $script:SerialReadSlicesPerTurn,
    [int]$MaximumBytesPerRead = $script:SerialReadSliceBytes
  )
  if ($null -eq $Serial -or -not $Serial.IsOpen) { return 0 }
  if ($null -ne $script:DualPortReaderWorker) {
    [int]$workerTotal = 0
    for ($workerIteration = 0; $workerIteration -lt $MaximumReads;
        ++$workerIteration) {
      [VcDualPortReader.CaptureRecord]$workerRecord = $null
      [bool]$dequeued = if ([string]$State.Role -ceq 'vehicle') {
        $script:DualPortReaderWorker.TryDequeueVehicle([ref]$workerRecord)
      } elseif ([string]$State.Role -ceq 'ground') {
        $script:DualPortReaderWorker.TryDequeueGround([ref]$workerRecord)
      } else {
        throw "unknown capture role for reader worker: $($State.Role)"
      }
      if (-not $dequeued) { break }
      Add-CaptureBytes -State $State -Buffer $workerRecord.Bytes `
          -Count $workerRecord.Count `
          -ProducerElapsedMs $workerRecord.ProducerElapsedMs `
          -ProducerSequence $workerRecord.Sequence `
          -ProducerRawStartOffset $workerRecord.RawStartOffset `
          -ProducerTimestampTicks $workerRecord.ProducerTimestampTicks `
          -ProducerPhase $workerRecord.ProducerPhase `
          -ProducerEpoch $workerRecord.ProducerEpoch
      $workerTotal += $workerRecord.Count
    }
    $workerFairnessRoleState = Get-PumpFairnessRoleState `
        -CaptureState $State
    if ($null -ne $workerFairnessRoleState) {
      $workerFairnessRoleState.service_count =
          [uint64]$workerFairnessRoleState.service_count + [uint64]1
      $workerFairnessRoleState.bytes_read =
          [uint64]$workerFairnessRoleState.bytes_read +
          [uint64][Math]::Max(0, $workerTotal)
      if ($workerTotal -eq 0) {
        $workerFairnessRoleState.zero_byte_service_count =
            [uint64]$workerFairnessRoleState.zero_byte_service_count +
            [uint64]1
      }
    }
    if ($script:DualPortReaderWorker.HasFatalFailure) {
      throw 'dual-port reader worker latched overflow or reader failure'
    }
    return $workerTotal
  }
  [int]$total = 0
  $fairnessRoleState = Get-PumpFairnessRoleState -CaptureState $State
  Start-PumpFairnessService -CaptureState $State `
      -RoleState $fairnessRoleState
  try {
    for ($iteration = 0; $iteration -lt $MaximumReads; ++$iteration) {
      [int]$available = $Serial.BytesToRead
      if ($available -le 0) { break }
      [int]$wanted = Get-SerialReadSliceSize -Available $available `
          -BufferLength $State.ReadBuffer.Length `
          -MaximumBytesPerRead $MaximumBytesPerRead
      if ($wanted -le 0) { break }
      try {
        [int]$read = $Serial.Read($State.ReadBuffer, 0, $wanted)
      } catch [System.TimeoutException] { break }
      if ($read -le 0) { break }
      Add-CaptureBytes -State $State -Buffer $State.ReadBuffer -Count $read
      $total += $read
    }
  } finally {
    Complete-PumpFairnessService -CaptureState $State `
        -RoleState $fairnessRoleState -BytesRead $total
  }
  return $total
}

function Invoke-ReaderBarrierDrain {
  param(
    [Parameter(Mandatory = $true)]$VehicleState,
    [Parameter(Mandatory = $true)]$GroundState,
    $Barrier = $null
  )
  if ($null -eq $script:DualPortReaderWorker) {
    return [pscustomobject][ordered]@{
      active=$false;vehicle_sequence_exclusive=0
      ground_sequence_exclusive=0;vehicle_records_drained=0
      ground_records_drained=0;bytes_drained=0
    }
  }
  $barrier = if ($null -ne $Barrier) {
    $Barrier
  } else { $script:DualPortReaderWorker.CaptureBarrier() }
  [long]$vehicleSequenceExclusive =
      [long]$barrier.Vehicle.SequenceExclusive
  [long]$groundSequenceExclusive =
      [long]$barrier.Ground.SequenceExclusive
  [long]$vehicleDrained = 0
  [long]$groundDrained = 0
  [long]$bytesDrained = 0
  while ([long]$VehicleState.LastProducerSequence + 1 -lt
      $vehicleSequenceExclusive) {
    [VcDualPortReader.CaptureRecord]$vehicleRecord = $null
    if (-not $script:DualPortReaderWorker.TryDequeueVehicle(
        [ref]$vehicleRecord)) {
      throw 'Vehicle reader barrier record unavailable before sequence_exclusive'
    }
    Add-CaptureBytes -State $VehicleState -Buffer $vehicleRecord.Bytes `
        -Count $vehicleRecord.Count `
        -ProducerElapsedMs $vehicleRecord.ProducerElapsedMs `
        -ProducerSequence $vehicleRecord.Sequence `
        -ProducerRawStartOffset $vehicleRecord.RawStartOffset `
        -ProducerTimestampTicks $vehicleRecord.ProducerTimestampTicks `
        -ProducerPhase $vehicleRecord.ProducerPhase `
        -ProducerEpoch $vehicleRecord.ProducerEpoch
    ++$vehicleDrained
    $bytesDrained += $vehicleRecord.Count
  }
  while ([long]$GroundState.LastProducerSequence + 1 -lt
      $groundSequenceExclusive) {
    [VcDualPortReader.CaptureRecord]$groundRecord = $null
    if (-not $script:DualPortReaderWorker.TryDequeueGround(
        [ref]$groundRecord)) {
      throw 'Ground reader barrier record unavailable before sequence_exclusive'
    }
    Add-CaptureBytes -State $GroundState -Buffer $groundRecord.Bytes `
        -Count $groundRecord.Count `
        -ProducerElapsedMs $groundRecord.ProducerElapsedMs `
        -ProducerSequence $groundRecord.Sequence `
        -ProducerRawStartOffset $groundRecord.RawStartOffset `
        -ProducerTimestampTicks $groundRecord.ProducerTimestampTicks `
        -ProducerPhase $groundRecord.ProducerPhase `
        -ProducerEpoch $groundRecord.ProducerEpoch
    ++$groundDrained
    $bytesDrained += $groundRecord.Count
  }
  return [pscustomobject][ordered]@{
    active=$true
    captured_timestamp_ticks=[long]$barrier.CapturedTimestampTicks
    captured_elapsed_ms=[Math]::Round(
        [double]$barrier.CapturedElapsedMs,3)
    vehicle_sequence_exclusive=$vehicleSequenceExclusive
    vehicle_raw_offset_exclusive=[long]$barrier.Vehicle.RawOffsetExclusive
    vehicle_boundary_timestamp_ticks=
        [long]$barrier.Vehicle.BoundaryTimestampTicks
    vehicle_boundary_elapsed_ms=[Math]::Round(
        [double]$barrier.Vehicle.BoundaryElapsedMs,3)
    vehicle_old_context_id=[uint32]$barrier.Vehicle.OldContextId
    vehicle_new_context_id=[uint32]$barrier.Vehicle.NewContextId
    ground_sequence_exclusive=$groundSequenceExclusive
    ground_raw_offset_exclusive=[long]$barrier.Ground.RawOffsetExclusive
    ground_boundary_timestamp_ticks=
        [long]$barrier.Ground.BoundaryTimestampTicks
    ground_boundary_elapsed_ms=[Math]::Round(
        [double]$barrier.Ground.BoundaryElapsedMs,3)
    ground_old_context_id=[uint32]$barrier.Ground.OldContextId
    ground_new_context_id=[uint32]$barrier.Ground.NewContextId
    vehicle_records_drained=$vehicleDrained
    ground_records_drained=$groundDrained
    bytes_drained=$bytesDrained
  }
}

function Stop-DualPortReaderWorkerAndDrain {
  param(
    [Parameter(Mandatory = $true)]$VehicleState,
    [Parameter(Mandatory = $true)]$GroundState
  )
  if ($null -eq $script:DualPortReaderWorker) {
    $script:ReaderShutdownEvidence = [pscustomobject][ordered]@{
      active=$false;joined=$false;valid=$false
      vehicle=[pscustomobject]@{queue_depth=0}
      ground=[pscustomobject]@{queue_depth=0}
    }
    return $script:ReaderShutdownEvidence
  }
  [bool]$joined = $script:DualPortReaderWorker.StopAndJoin(5000)
  $barrierDrain = $null
  if ($joined) {
    $stoppedBarrier = $script:DualPortReaderWorker.CaptureStoppedBarrier()
    $barrierDrain = Invoke-ReaderBarrierDrain -VehicleState $VehicleState `
        -GroundState $GroundState -Barrier $stoppedBarrier
  }
  $snapshot = $script:DualPortReaderWorker.Snapshot()
  [bool]$valid = ($joined -and [bool]$snapshot.Joined -and
      -not [bool]$snapshot.Vehicle.ThreadAlive -and
      -not [bool]$snapshot.Ground.ThreadAlive -and
      [int]$snapshot.Vehicle.QueueDepth -eq 0 -and
      [int]$snapshot.Ground.QueueDepth -eq 0 -and
      [long]$snapshot.Vehicle.ProducedRawBytes -eq
          [long]$VehicleState.RawBytes -and
      [long]$snapshot.Ground.ProducedRawBytes -eq
          [long]$GroundState.RawBytes -and
      [long]$snapshot.Vehicle.ProducedSequence -eq
          [long]$snapshot.Vehicle.ConsumedSequence -and
      [long]$snapshot.Ground.ProducedSequence -eq
          [long]$snapshot.Ground.ConsumedSequence)
  $script:ReaderShutdownEvidence = [pscustomobject][ordered]@{
    active=$true;joined=$joined;valid=$valid
    barrier=$barrierDrain
    vehicle=[pscustomobject][ordered]@{
      queue_depth=[int]$snapshot.Vehicle.QueueDepth
      produced_sequence=[long]$snapshot.Vehicle.ProducedSequence
      consumed_sequence=[long]$snapshot.Vehicle.ConsumedSequence
      produced_raw_bytes=[long]$snapshot.Vehicle.ProducedRawBytes
      capture_raw_bytes=[long]$VehicleState.RawBytes
      thread_alive=[bool]$snapshot.Vehicle.ThreadAlive
    }
    ground=[pscustomobject][ordered]@{
      queue_depth=[int]$snapshot.Ground.QueueDepth
      produced_sequence=[long]$snapshot.Ground.ProducedSequence
      consumed_sequence=[long]$snapshot.Ground.ConsumedSequence
      produced_raw_bytes=[long]$snapshot.Ground.ProducedRawBytes
      capture_raw_bytes=[long]$GroundState.RawBytes
      thread_alive=[bool]$snapshot.Ground.ThreadAlive
    }
  }
  return $script:ReaderShutdownEvidence
}

function Invoke-PumpPair {
  param($VehicleSerial, $VehicleState, $GroundSerial, $GroundState)
  [int]$read = 0
  $read += Read-SerialAvailable -Serial $VehicleSerial -State $VehicleState
  $read += Read-SerialAvailable -Serial $GroundSerial -State $GroundState
  return $read
}

function Invoke-ReadinessPumpCheckpoint {
  param(
    [Parameter(Mandatory = $true)][string]$Stage,
    [Parameter(Mandatory = $true)]$GroundParser,
    [Parameter(Mandatory = $true)]$Epoch,
    [Parameter(Mandatory = $true)]$VehicleSerial,
    [Parameter(Mandatory = $true)]$VehicleState,
    [Parameter(Mandatory = $true)]$GroundSerial,
    [Parameter(Mandatory = $true)]$GroundState
  )
  $script:PumpAdminStage = $Stage
  [bool]$groundParserEnabledBefore = [bool]$GroundParser.Enabled
  [bool]$epochOpenBefore = ($null -ne $Epoch -and -not [bool]$Epoch.closed)
  if (-not $groundParserEnabledBefore -or -not $epochOpenBefore) {
    throw ('readiness pump checkpoint refused while the Ground parser ' +
      "epoch is not open: stage=$Stage")
  }
  $readerBarrierDrain = Invoke-ReaderBarrierDrain `
      -VehicleState $VehicleState -GroundState $GroundState
  $vehicleFairness = Get-PumpFairnessRoleState -CaptureState $VehicleState
  $groundFairness = Get-PumpFairnessRoleState -CaptureState $GroundState
  if ($null -eq $vehicleFairness -or $null -eq $groundFairness) {
    throw "readiness pump checkpoint has no fairness state: stage=$Stage"
  }
  [uint64]$vehicleServiceCountBefore =
      [uint64]$vehicleFairness.service_count
  [uint64]$groundServiceCountBefore = [uint64]$groundFairness.service_count
  [long]$vehicleRawBefore = [long]$VehicleState.RawBytes
  [long]$groundRawBefore = [long]$GroundState.RawBytes
  [double]$startedElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
  [int]$bytesRead = Invoke-PumpPair -VehicleSerial $VehicleSerial `
      -VehicleState $VehicleState -GroundSerial $GroundSerial `
      -GroundState $GroundState
  [double]$finishedElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
  [bool]$groundParserEnabledAfter = [bool]$GroundParser.Enabled
  [bool]$epochOpenAfter = ($null -ne $Epoch -and -not [bool]$Epoch.closed)
  [uint64]$vehicleServiceCountAfter = [uint64]$vehicleFairness.service_count
  [uint64]$groundServiceCountAfter = [uint64]$groundFairness.service_count
  if (-not $groundParserEnabledAfter -or -not $epochOpenAfter -or
      $vehicleServiceCountAfter -ne $vehicleServiceCountBefore + [uint64]1 -or
      $groundServiceCountAfter -ne $groundServiceCountBefore + [uint64]1) {
    throw ('readiness pump checkpoint did not preserve one parser-safe ' +
      "Vehicle/Ground service turn: stage=$Stage")
  }
  return [pscustomobject][ordered]@{
    stage=$Stage
    started_elapsed_ms=[Math]::Round($startedElapsedMs,3)
    finished_elapsed_ms=[Math]::Round($finishedElapsedMs,3)
    duration_ms=[Math]::Round($finishedElapsedMs-$startedElapsedMs,3)
    bytes_read=$bytesRead
    ground_parser_enabled_before=$groundParserEnabledBefore
    ground_parser_enabled_after=$groundParserEnabledAfter
    epoch_name=[string]$Epoch.name
    epoch_open_before=$epochOpenBefore;epoch_open_after=$epochOpenAfter
    vehicle_service_count_before=$vehicleServiceCountBefore
    vehicle_service_count_after=$vehicleServiceCountAfter
    ground_service_count_before=$groundServiceCountBefore
    ground_service_count_after=$groundServiceCountAfter
    vehicle_raw_bytes_before=$vehicleRawBefore
    vehicle_raw_bytes_after=[long]$VehicleState.RawBytes
    ground_raw_bytes_before=$groundRawBefore
    ground_raw_bytes_after=[long]$GroundState.RawBytes
    reader_barrier_drain=$readerBarrierDrain
  }
}

function Invoke-ReadinessRawFsyncBoundary {
  param(
    [Parameter(Mandatory = $true)][string]$Stage,
    [Parameter(Mandatory = $true)][double]$LastRawFlushElapsedMs,
    [Parameter(Mandatory = $true)]$GroundParser,
    [Parameter(Mandatory = $true)]$Epoch,
    [Parameter(Mandatory = $true)]$VehicleSerial,
    [Parameter(Mandatory = $true)]$VehicleState,
    [Parameter(Mandatory = $true)]$GroundSerial,
    [Parameter(Mandatory = $true)]$GroundState
  )
  [double]$startedElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
  $startDecision = Get-ReadinessRawFsyncAgeDecision `
      -LastRawFlushElapsedMs $LastRawFlushElapsedMs `
      -CurrentElapsedMs $startedElapsedMs
  if (-not $startDecision.valid) {
    Add-TimelineEvent -Name 'readiness_raw_fsync_boundary' -Details @{
      stage=$Stage;status='REFUSED_OVERDUE';fixture_write_count=0
      previous_flush_elapsed_ms=[Math]::Round($LastRawFlushElapsedMs,3)
      started_elapsed_ms=[Math]::Round($startedElapsedMs,3)
      finished_elapsed_ms=$null;start_age_ms=[Math]::Round($startDecision.age_ms,3)
      finished_age_ms=$null;hard_limit_ms=$script:RawCaptureFlushIntervalMs
      vehicle_flush_completed=$false;ground_flush_completed=$false
      pump_checkpoint_count=0
    }
    throw ('readiness raw evidence Flush(true) interval exceeded {0} ms' -f
      [int]$script:RawCaptureFlushIntervalMs)
  }

  $pumpCheckpoints = New-Object 'System.Collections.Generic.List[object]'
  $VehicleState.RawStream.Flush($true)
  $betweenCheckpoint = Invoke-ReadinessPumpCheckpoint `
      -Stage ($Stage + '_between_raw_fsync') `
      -GroundParser $GroundParser -Epoch $Epoch `
      -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
      -GroundSerial $GroundSerial -GroundState $GroundState
  [void]$pumpCheckpoints.Add($betweenCheckpoint)
  $GroundState.RawStream.Flush($true)
  $afterCheckpoint = Invoke-ReadinessPumpCheckpoint `
      -Stage ($Stage + '_after_raw_fsync') `
      -GroundParser $GroundParser -Epoch $Epoch `
      -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
      -GroundSerial $GroundSerial -GroundState $GroundState
  [void]$pumpCheckpoints.Add($afterCheckpoint)

  [double]$finishedElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
  $finishedDecision = Get-ReadinessRawFsyncAgeDecision `
      -LastRawFlushElapsedMs $LastRawFlushElapsedMs `
      -CurrentElapsedMs $finishedElapsedMs
  Add-TimelineEvent -Name 'readiness_raw_fsync_boundary' -Details @{
    stage=$Stage
    status=if($finishedDecision.valid){'COMPLETE'}else{'COMPLETED_OVERDUE'}
    fixture_write_count=0
    previous_flush_elapsed_ms=[Math]::Round($LastRawFlushElapsedMs,3)
    started_elapsed_ms=[Math]::Round($startedElapsedMs,3)
    finished_elapsed_ms=[Math]::Round($finishedElapsedMs,3)
    start_age_ms=[Math]::Round($startDecision.age_ms,3)
    finished_age_ms=[Math]::Round($finishedDecision.age_ms,3)
    hard_limit_ms=$script:RawCaptureFlushIntervalMs
    vehicle_flush_completed=$true;ground_flush_completed=$true
    pump_checkpoint_count=$pumpCheckpoints.Count
  }
  if (-not $finishedDecision.valid) {
    throw ('readiness raw evidence Flush(true) interval exceeded {0} ms' -f
      [int]$script:RawCaptureFlushIntervalMs)
  }
  return [pscustomobject][ordered]@{
    stage=$Stage;flushed=$true
    started_elapsed_ms=$startedElapsedMs
    finished_elapsed_ms=$finishedElapsedMs
    start_decision=$startDecision;finished_decision=$finishedDecision
    last_raw_flush_elapsed_ms=$finishedElapsedMs
    pump_checkpoints=$pumpCheckpoints.ToArray()
  }
}

function Invoke-PumpPairUntilIdle {
  param(
    [Parameter(Mandatory = $true)]$VehicleSerial,
    [Parameter(Mandatory = $true)]$VehicleState,
    [Parameter(Mandatory = $true)]$GroundSerial,
    [Parameter(Mandatory = $true)]$GroundState,
    [Parameter(Mandatory = $true)]$GroundParser,
    [Parameter(Mandatory = $true)]$Epoch,
    [Parameter(Mandatory = $true)][double]$LastRawFlushElapsedMs,
    [Parameter(Mandatory = $true)][double]$AbsoluteDeadlineElapsedMs,
    [ValidateRange(1, 100)][int]$ConsecutiveIdlePolls = 3
  )
  [int]$idlePolls = 0
  [uint64]$iterations = 0
  [long]$vehicleRawStartOffset = [long]$VehicleState.RawBytes
  [long]$groundRawStartOffset = [long]$GroundState.RawBytes
  [double]$idleLastRawFlushElapsedMs = $LastRawFlushElapsedMs
  $rawFsyncPumpCheckpoints =
      New-Object 'System.Collections.Generic.List[object]'
  while ($script:RunWatch.Elapsed.TotalMilliseconds -lt
      $AbsoluteDeadlineElapsedMs) {
    [int]$read = Invoke-PumpPair -VehicleSerial $VehicleSerial `
        -VehicleState $VehicleState -GroundSerial $GroundSerial `
        -GroundState $GroundState
    [bool]$activityObserved = ($read -gt 0)
    ++$iterations
    [double]$pumpElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
    if ($pumpElapsedMs - $idleLastRawFlushElapsedMs -ge
        $script:RawCaptureFlushScheduleMs) {
      $rawFsyncBoundary = Invoke-ReadinessRawFsyncBoundary `
          -Stage 'pump_to_idle_scheduled' `
          -LastRawFlushElapsedMs $idleLastRawFlushElapsedMs `
          -GroundParser $GroundParser -Epoch $Epoch `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState
      foreach ($checkpoint in $rawFsyncBoundary.pump_checkpoints) {
        [void]$rawFsyncPumpCheckpoints.Add($checkpoint)
        if ([long]$checkpoint.bytes_read -gt 0 -or
            [long]$checkpoint.reader_barrier_drain.bytes_drained -gt 0) {
          $activityObserved = $true
        }
      }
      $idleLastRawFlushElapsedMs =
          [double]$rawFsyncBoundary.last_raw_flush_elapsed_ms
      Add-LiveProgressRecord -Event 'data_plane_readiness_progress' -Details @{
        stage='pump_to_idle';idle=$false;iterations=$iterations
        raw_fsync_completed=$true
        last_raw_flush_elapsed_ms=[Math]::Round(
          $idleLastRawFlushElapsedMs,3)
        fixture_write_count=0
      }
    }
    if (-not $activityObserved) {
      ++$idlePolls
      if ($idlePolls -ge $ConsecutiveIdlePolls) {
        return [pscustomobject][ordered]@{
          idle=$true;deadline_reached=$false;iterations=$iterations
          iteration_count=$iterations
          consecutive_idle_polls=$idlePolls
          finished_elapsed_ms=[Math]::Round(
            $script:RunWatch.Elapsed.TotalMilliseconds,3)
          vehicle_raw_start_offset=$vehicleRawStartOffset
          vehicle_raw_end_offset=[long]$VehicleState.RawBytes
          ground_raw_start_offset=$groundRawStartOffset
          ground_raw_end_offset=[long]$GroundState.RawBytes
          last_raw_flush_elapsed_ms=$idleLastRawFlushElapsedMs
          raw_fsync_pump_checkpoints=$rawFsyncPumpCheckpoints.ToArray()
        }
      }
      Start-Sleep -Milliseconds 1
    } else {
      $idlePolls = 0
    }
  }
  return [pscustomobject][ordered]@{
    idle=$false;deadline_reached=$true;iterations=$iterations
    iteration_count=$iterations
    consecutive_idle_polls=$idlePolls
    finished_elapsed_ms=[Math]::Round(
      $script:RunWatch.Elapsed.TotalMilliseconds,3)
    vehicle_raw_start_offset=$vehicleRawStartOffset
    vehicle_raw_end_offset=[long]$VehicleState.RawBytes
    ground_raw_start_offset=$groundRawStartOffset
    ground_raw_end_offset=[long]$GroundState.RawBytes
    last_raw_flush_elapsed_ms=$idleLastRawFlushElapsedMs
    raw_fsync_pump_checkpoints=$rawFsyncPumpCheckpoints.ToArray()
  }
}

function Invoke-CaptureInterval {
  param([int]$Milliseconds, [string]$Phase,
        $VehicleSerial, $VehicleState, $GroundSerial, $GroundState,
        [Nullable[double]]$AbsoluteDeadlineElapsedMs = $null,
        [switch]$PassThru,
        [AllowNull()]$StartBarrier = $null,
        [AllowNull()]$ParserToEnable = $null,
        [string]$ParserCaptureScope = '')
  $captureStartBarrier = $StartBarrier
  if ($null -eq $captureStartBarrier) {
    $captureStartBarrier = Set-ReaderCaptureContext -Phase $Phase
  }
  if ($null -ne $ParserToEnable) {
    $ParserToEnable.Enabled = $false
    Reset-MavlinkAnalysis -Parser $ParserToEnable
    if (-not [string]::IsNullOrEmpty($ParserCaptureScope)) {
      $ParserToEnable.ParamList.capture_scope = $ParserCaptureScope
    }
    $ParserToEnable.Enabled = $true
  }
  $script:CurrentPhase = $Phase
  Add-TimelineEvent -Name ($Phase + '_start')
  [double]$startedElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
  [double]$targetElapsedMs = $startedElapsedMs + [double]$Milliseconds
  [double]$effectiveEndElapsedMs = $targetElapsedMs
  if ($null -ne $AbsoluteDeadlineElapsedMs -and
      [double]$AbsoluteDeadlineElapsedMs -lt $effectiveEndElapsedMs) {
    $effectiveEndElapsedMs = [double]$AbsoluteDeadlineElapsedMs
  }
  while ($script:RunWatch.Elapsed.TotalMilliseconds -lt
      $effectiveEndElapsedMs) {
    [int]$read = Invoke-PumpPair -VehicleSerial $VehicleSerial `
        -VehicleState $VehicleState -GroundSerial $GroundSerial `
        -GroundState $GroundState
    if ($read -eq 0) {
      [double]$remainingMs = $effectiveEndElapsedMs -
          $script:RunWatch.Elapsed.TotalMilliseconds
      [int]$sleepMs = [Math]::Min(2,
          [Math]::Max(0, [Math]::Floor($remainingMs)))
      if ($sleepMs -gt 0) { Start-Sleep -Milliseconds $sleepMs }
    }
  }
  [double]$beforeFinalPumpMs = $script:RunWatch.Elapsed.TotalMilliseconds
  if ($null -eq $AbsoluteDeadlineElapsedMs -or
      $beforeFinalPumpMs -lt [double]$AbsoluteDeadlineElapsedMs) {
    [void](Invoke-PumpPair -VehicleSerial $VehicleSerial `
        -VehicleState $VehicleState -GroundSerial $GroundSerial `
        -GroundState $GroundState)
  }
  [double]$finishedElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
  [bool]$completedDuration = ($finishedElapsedMs -ge $targetElapsedMs)
  [bool]$deadlineReached = ($null -ne $AbsoluteDeadlineElapsedMs -and
      $finishedElapsedMs -ge [double]$AbsoluteDeadlineElapsedMs)
  Add-TimelineEvent -Name ($Phase + '_end')
  if ($PassThru.IsPresent) {
    return [pscustomobject][ordered]@{
      started_elapsed_ms=$startedElapsedMs
      requested_milliseconds=$Milliseconds
      captured_milliseconds=[Math]::Round(
        [Math]::Max(0.0,$finishedElapsedMs - $startedElapsedMs),3)
      target_elapsed_ms=$targetElapsedMs
      effective_end_elapsed_ms=$effectiveEndElapsedMs
      finished_elapsed_ms=$finishedElapsedMs
      completed_duration=$completedDuration
      deadline_reached=$deadlineReached
      skipped=$false
      start_barrier=$captureStartBarrier
    }
  }
}

function Select-CorrelatedReport {
  param($State, [int]$StartLineIndex, [long]$MinimumRawStartOffset,
        [Nullable[uint32]]$ExpectedQ)
  return Select-CorrelatedReportFromRows -Rows $State.TaggedLines `
      -TagBase $State.TagBase -StartLineIndex $StartLineIndex `
      -MinimumRawStartOffset $MinimumRawStartOffset `
      -ExpectedQ $ExpectedQ
}

function Invoke-SnapshotQuery {
  param([string]$Name, $Serial, $State, [byte[]]$Command,
        [int]$TimeoutSeconds, [Nullable[uint32]]$ExpectedQ,
        $VehicleSerial, $VehicleState, $GroundSerial, $GroundState,
        [Nullable[double]]$AbsoluteDeadlineElapsedMs = $null,
        [switch]$AllowVehiclePartialUsbWake)
  $queryStartBarrier = Set-ReaderCaptureContext -Phase $Name
  $script:CurrentPhase = $Name
  if ($null -ne $script:DualPortReaderWorker) {
    [void](Invoke-ReaderBarrierDrain -VehicleState $VehicleState `
        -GroundState $GroundState)
  }
  [int]$startLineIndex = $State.TaggedLines.Count
  [long]$startRawOffset = $State.RawBytes
  $preQueryMatcherSnapshot = if ($AllowVehiclePartialUsbWake) {
    Get-CaptureMatcherSnapshot -State $State
  } else { $null }
  [double]$startedMs = $script:RunWatch.Elapsed.TotalMilliseconds
  [double]$configuredDeadlineElapsedMs = $startedMs +
      ([double]$TimeoutSeconds * 1000.0)
  [double]$effectiveDeadlineElapsedMs = $configuredDeadlineElapsedMs
  if ($null -ne $AbsoluteDeadlineElapsedMs -and
      [double]$AbsoluteDeadlineElapsedMs -lt $effectiveDeadlineElapsedMs) {
    $effectiveDeadlineElapsedMs = [double]$AbsoluteDeadlineElapsedMs
  }
  [int]$queryCount = 0
  [int]$queryAttemptCount = 0
  [bool]$writeTimedOut = $false
  [bool]$baseStreamFlushPerformed = $false
  [bool]$flushSkippedForAbsoluteDeadline = $false
  $writePlan = $null
  [Nullable[int]]$originalWriteTimeout = $null
  [long]$lastRawBytes = $startRawOffset
  [double]$lastRawProgressElapsedMs = $startedMs
  [int]$usbWakeAttemptCount = 0
  [int]$usbWakeWriteCount = 0
  [bool]$usbWakeWriteTimedOut = $false
  [Nullable[int]]$usbWakeOriginalWriteTimeout = $null
  [Nullable[double]]$usbWakeElapsedMs = $null
  $usbWakeWritePlan = $null
  $usbWakeTriggerDecision = $null
  $usbWakeLastDecision = $null
  [bool]$canAttemptWrite = ($startedMs -lt $effectiveDeadlineElapsedMs)
  if ($canAttemptWrite -and $null -ne $AbsoluteDeadlineElapsedMs) {
    [double]$writeRemainingMs = $effectiveDeadlineElapsedMs - $startedMs
    $writePlan = Get-DeadlineBoundWritePlan `
        -RemainingMs $writeRemainingMs `
        -ConfiguredWriteTimeoutMs ([double]$Serial.WriteTimeout) `
        -MarginMs $script:SnapshotWriteDeadlineMarginMs
    $canAttemptWrite = [bool]$writePlan.can_write
  }
  if ($canAttemptWrite) {
    ++$queryAttemptCount
    if ($null -ne $AbsoluteDeadlineElapsedMs) {
      $originalWriteTimeout = [int]$Serial.WriteTimeout
      try {
        $Serial.WriteTimeout = [int]$writePlan.write_timeout_ms
        try {
          $Serial.Write($Command, 0, $Command.Length)
          ++$script:DiagnosticQueryWriteCount
        } catch [System.TimeoutException] {
          $writeTimedOut = $true
        }
      } finally {
        $Serial.WriteTimeout = $originalWriteTimeout
      }
      $flushSkippedForAbsoluteDeadline =
          (-not [bool]$writePlan.base_stream_flush_allowed)
    } else {
      $Serial.Write($Command, 0, $Command.Length)
      ++$script:DiagnosticQueryWriteCount
      $Serial.BaseStream.Flush()
      $baseStreamFlushPerformed = $true
    }
    if (-not $writeTimedOut) { $queryCount = 1 }
    Add-TimelineEvent -Name ($Name + '_query_sent') -Details @{
      raw_offset=$startRawOffset
      effective_deadline_elapsed_ms=[Math]::Round(
        $effectiveDeadlineElapsedMs,3)
      write_timed_out=$writeTimedOut
      base_stream_flush_performed=$baseStreamFlushPerformed
      flush_skipped_for_absolute_deadline=$flushSkippedForAbsoluteDeadline
    }
  }
  $report = Select-CorrelatedReport -State $State `
      -StartLineIndex $startLineIndex `
      -MinimumRawStartOffset $startRawOffset -ExpectedQ $ExpectedQ
  while (-not $report.complete -and $queryCount -eq 1) {
    if ($script:RunWatch.Elapsed.TotalMilliseconds -ge
        $effectiveDeadlineElapsedMs) { break }
    [int]$read = Invoke-PumpPair -VehicleSerial $VehicleSerial `
        -VehicleState $VehicleState -GroundSerial $GroundSerial `
        -GroundState $GroundState
    [double]$afterPumpElapsedMs =
        $script:RunWatch.Elapsed.TotalMilliseconds
    if ([long]$State.RawBytes -ne $lastRawBytes) {
      $lastRawBytes = [long]$State.RawBytes
      $lastRawProgressElapsedMs = $afterPumpElapsedMs
    }
    $report = Select-CorrelatedReport -State $State `
        -StartLineIndex $startLineIndex `
        -MinimumRawStartOffset $startRawOffset -ExpectedQ $ExpectedQ
    if ($AllowVehiclePartialUsbWake -and -not $report.complete) {
      $currentMatcherSnapshot = Get-CaptureMatcherSnapshot -State $State
      $usbWakeLastDecision = Get-VehiclePartialUsbWakeDecision `
          -AllowVehiclePartialUsbWake ([bool]$AllowVehiclePartialUsbWake) `
          -Role ([string]$State.Role) -ExpectedQ $ExpectedQ `
          -QueryCount $queryCount -QueryAttemptCount $queryAttemptCount `
          -WriteTimedOut $writeTimedOut -ReportComplete ([bool]$report.complete) `
          -PreQueryMatcherSnapshot $preQueryMatcherSnapshot `
          -CurrentMatcherSnapshot $currentMatcherSnapshot `
          -StartLineIndex $startLineIndex -StartRawOffset $startRawOffset `
          -LastRawProgressElapsedMs $lastRawProgressElapsedMs `
          -CurrentElapsedMs $afterPumpElapsedMs `
          -WakeAttemptCount $usbWakeAttemptCount `
          -EffectiveDeadlineElapsedMs $effectiveDeadlineElapsedMs
      if ([bool]$usbWakeLastDecision.eligible) {
        ++$usbWakeAttemptCount
        $usbWakeTriggerDecision = $usbWakeLastDecision
        $usbWakeWritePlan = $usbWakeLastDecision.write_plan
        $usbWakeElapsedMs = $afterPumpElapsedMs
        $usbWakeOriginalWriteTimeout = [int]$Serial.WriteTimeout
        try {
          $Serial.WriteTimeout = [int]$usbWakeWritePlan.write_timeout_ms
          try {
            $Serial.Write($script:VehiclePartialUsbWakeByte, 0,
                $script:VehiclePartialUsbWakeByte.Length)
            ++$usbWakeWriteCount
          } catch [System.TimeoutException] {
            $usbWakeWriteTimedOut = $true
          }
        } finally {
          $Serial.WriteTimeout = $usbWakeOriginalWriteTimeout
        }
        Add-TimelineEvent -Name ($Name + '_vehicle_usb_wake') -Details @{
          wake_byte_hex='0D';wake_attempt_count=$usbWakeAttemptCount
          wake_write_count=$usbWakeWriteCount
          wake_write_timed_out=$usbWakeWriteTimedOut
          raw_offset=[long]$State.RawBytes
          pending_byte_count=[int]$currentMatcherSnapshot.pending_byte_count
          pending_sha256=[string]$usbWakeTriggerDecision.pending_sha256
          expected_q=$ExpectedQ;stall_ms=[double]$usbWakeTriggerDecision.stall_ms
          effective_deadline_elapsed_ms=[Math]::Round(
            $effectiveDeadlineElapsedMs,3)
          deadline_extended=$false;base_stream_flush_performed=$false
        }
      }
    }
    if ($read -eq 0 -and -not $report.complete) {
      [double]$remainingMs = $effectiveDeadlineElapsedMs -
          $script:RunWatch.Elapsed.TotalMilliseconds
      [int]$sleepMs = [Math]::Min(2,
          [Math]::Max(0, [Math]::Floor($remainingMs)))
      if ($sleepMs -gt 0) { Start-Sleep -Milliseconds $sleepMs }
    }
  }
  [double]$finishedMs = $script:RunWatch.Elapsed.TotalMilliseconds
  [bool]$absoluteDeadlineReached = (
    $null -ne $AbsoluteDeadlineElapsedMs -and
    $finishedMs -ge [double]$AbsoluteDeadlineElapsedMs)
  return [pscustomobject][ordered]@{
    name=$Name; role=$State.Role
    status=if ($report.complete) {'COMPLETE'} else {'TIMEOUT'}
    query_count=$queryCount; expected_q=$ExpectedQ; q_uint32=$report.q_uint32
    query_attempt_count=$queryAttemptCount;write_timed_out=$writeTimedOut
    original_write_timeout_ms=$originalWriteTimeout;write_plan=$writePlan
    base_stream_flush_performed=$baseStreamFlushPerformed
    flush_skipped_for_absolute_deadline=$flushSkippedForAbsoluteDeadline
    ms_uint64=$report.ms_uint64; responses=@($report.responses)
    started_elapsed_ms=[Math]::Round($startedMs, 3)
    finished_elapsed_ms=[Math]::Round($finishedMs, 3)
    configured_deadline_elapsed_ms=[Math]::Round(
        $configuredDeadlineElapsedMs,3)
    effective_deadline_elapsed_ms=[Math]::Round(
        $effectiveDeadlineElapsedMs,3)
    absolute_deadline_elapsed_ms=if($null -ne $AbsoluteDeadlineElapsedMs){
      [Math]::Round([double]$AbsoluteDeadlineElapsedMs,3)
    }else{$null}
    absolute_deadline_reached=$absoluteDeadlineReached
    tagged_line_start_index=$startLineIndex
    raw_rx_start_offset=$startRawOffset; raw_rx_end_offset=$State.RawBytes
    capture_start_barrier=$queryStartBarrier
    usb_wake_allowed=[bool]$AllowVehiclePartialUsbWake
    usb_wake_byte_hex='0D';usb_wake_max_attempts=1
    usb_wake_attempt_count=$usbWakeAttemptCount
    usb_wake_write_count=$usbWakeWriteCount
    usb_wake_write_timed_out=$usbWakeWriteTimedOut
    usb_wake_original_write_timeout_ms=$usbWakeOriginalWriteTimeout
    usb_wake_elapsed_ms=if($null -ne $usbWakeElapsedMs){
      [Math]::Round([double]$usbWakeElapsedMs,3)
    }else{$null}
    usb_wake_write_plan=$usbWakeWritePlan
    usb_wake_trigger_decision=$usbWakeTriggerDecision
    usb_wake_last_decision=$usbWakeLastDecision
    usb_wake_deadline_extended=$false
    usb_wake_base_stream_flush_performed=$false
  }
}

function Invoke-BacklogSnapshotWithRecovery {
  param(
    [Parameter(Mandatory = $true)][string]$Name,
    [Parameter(Mandatory = $true)][ValidateSet('vehicle','ground')]
      [string]$Role,
    [Parameter(Mandatory = $true)]$Serial,
    [Parameter(Mandatory = $true)]$State,
    [Parameter(Mandatory = $true)][byte[]]$Command,
    [Parameter(Mandatory = $true)][int]$SnapshotTimeoutSeconds,
    [Nullable[uint32]]$ExpectedQ,
    [Parameter(Mandatory = $true)][AllowNull()]$PreviousSnapshot,
    [Parameter(Mandatory = $true)][double]$DeadlineElapsedMs,
    [double]$ReserveAfterMs = 0.0,
    [int]$MaxAttempts = 3,
    [bool]$RecoveryAlreadyUsed = $false,
    [Parameter(Mandatory = $true)]$VehicleSerial,
    [Parameter(Mandatory = $true)]$VehicleState,
    [Parameter(Mandatory = $true)]$GroundSerial,
    [Parameter(Mandatory = $true)]$GroundState
  )
  $attempts = New-Object 'System.Collections.Generic.List[object]'
  $MatcherBefore = Get-CaptureMatcherSnapshot -State $State
  $latestCompleteSnapshot = Select-LatestCompleteDiagnosticSnapshot `
      -CurrentSnapshot $null -CandidateSnapshot $PreviousSnapshot
  $initialBudget = Get-DeadlineBoundSnapshotBudget `
      -CurrentElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
      -DeadlineElapsedMs $DeadlineElapsedMs `
      -ConfiguredTimeoutSeconds $SnapshotTimeoutSeconds `
      -ReserveAfterMs $ReserveAfterMs
  if (-not $initialBudget.can_query) {
    return [pscustomobject][ordered]@{
      valid=$false;recovered=$false;status='REJECT'
      reason='shared_deadline_exhausted';snapshot=$null;response=$null
      deadline_elapsed_ms=$DeadlineElapsedMs;deadline_extended=$false
      max_attempts=$MaxAttempts;attempt_count=0;retry_exhausted=$false
      attempts=$attempts.ToArray();fixture_write_count=0
      matcher_before=$MatcherBefore;matcher_after=$MatcherBefore
      matcher_at_failure=$MatcherBefore
      latest_complete_snapshot=$latestCompleteSnapshot
    }
  }
  [int]$startTaggedLineIndex = $State.TaggedLines.Count
  $initialSnapshot = Invoke-SnapshotQuery -Name ($Name + '_initial') `
      -Serial $Serial -State $State -Command $Command `
      -TimeoutSeconds $SnapshotTimeoutSeconds -ExpectedQ $ExpectedQ `
      -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
      -GroundSerial $GroundSerial -GroundState $GroundState `
      -AbsoluteDeadlineElapsedMs $initialBudget.query_deadline_elapsed_ms
  $initialResponse = Test-ReadinessSnapshotResponse `
      -Snapshot $initialSnapshot -ExpectedQ $ExpectedQ
  $latestCompleteSnapshot = Select-LatestCompleteDiagnosticSnapshot `
      -CurrentSnapshot $latestCompleteSnapshot `
      -CandidateSnapshot $initialSnapshot
  $MatcherAfter = Get-CaptureMatcherSnapshot -State $State
  [int]$unexpectedTaggedRows = [Math]::Max(0,
      $State.TaggedLines.Count - $startTaggedLineIndex)
  $recoveryBudget = Get-DeadlineBoundSnapshotBudget `
      -CurrentElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
      -DeadlineElapsedMs $DeadlineElapsedMs `
      -ConfiguredTimeoutSeconds $SnapshotTimeoutSeconds `
      -ReserveAfterMs ($ReserveAfterMs +
        ([double]$SnapshotTimeoutSeconds * 1000.0))
  [bool]$allowUnanchoredGroundRecovery = ($Role -ceq 'ground' -and
      $null -eq $PreviousSnapshot -and $null -eq $ExpectedQ)
  $disposition = Get-BacklogSnapshotRecoveryDisposition `
      -Response $initialResponse -AttemptNumber 1 -MaxAttempts $MaxAttempts `
      -RetryBudgetAvailable ([bool]$recoveryBudget.can_query) `
      -MatcherBefore $MatcherBefore -MatcherAfter $MatcherAfter -Role $Role `
      -ExpectedQ $ExpectedQ -UnexpectedTaggedRowCount $unexpectedTaggedRows `
      -RecoveryAlreadyUsed $RecoveryAlreadyUsed `
      -AllowUnanchoredGroundRecovery $allowUnanchoredGroundRecovery
  $attempts.Add([pscustomobject][ordered]@{
    attempt=1;kind='initial';snapshot=$initialSnapshot
    response=$initialResponse;matcher_before=$MatcherBefore
    matcher_after=$MatcherAfter;disposition=$disposition
  })
  if ($disposition.action -ceq 'ACCEPT') {
    return [pscustomobject][ordered]@{
      valid=$true;recovered=$false;status='ACCEPT'
      reason=$disposition.reason;snapshot=$initialSnapshot
      response=$initialResponse;deadline_elapsed_ms=$DeadlineElapsedMs
      deadline_extended=$false;max_attempts=$MaxAttempts;attempt_count=1
      retry_exhausted=$false;attempts=$attempts.ToArray()
      fixture_write_count=0;matcher_before=$MatcherBefore
      matcher_after=$MatcherAfter;disposition=$disposition
      matcher_at_failure=$null
      latest_complete_snapshot=$latestCompleteSnapshot
    }
  }
  if ($disposition.action -cne 'RESYNC') {
    return [pscustomobject][ordered]@{
      valid=$false;recovered=$false;status='REJECT'
      reason=$disposition.reason;snapshot=$initialSnapshot
      response=$initialResponse;deadline_elapsed_ms=$DeadlineElapsedMs
      deadline_extended=$false;max_attempts=$MaxAttempts;attempt_count=1
      retry_exhausted=[bool]$disposition.retry_exhausted
      attempts=$attempts.ToArray();fixture_write_count=0
      matcher_before=$MatcherBefore;matcher_after=$MatcherAfter
      matcher_at_failure=$MatcherAfter;disposition=$disposition
      latest_complete_snapshot=$latestCompleteSnapshot
    }
  }

  $settleCapture = Invoke-CaptureInterval -Milliseconds 250 `
      -Phase ($Name + '_resync_settle') `
      -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
      -GroundSerial $GroundSerial -GroundState $GroundState `
      -AbsoluteDeadlineElapsedMs $DeadlineElapsedMs -PassThru
  $matcherAfterSettle = Get-CaptureMatcherSnapshot -State $State
  [bool]$settleOverflowStable = ([uint64]$matcherAfterSettle.overflow_count -eq
      [uint64]$MatcherBefore.overflow_count)
  [long]$rawBeforeReset = [long]$State.RawBytes
  if (-not $settleCapture.completed_duration -or -not $settleOverflowStable) {
    return [pscustomobject][ordered]@{
      valid=$false;recovered=$false;status='REJECT'
      reason=if(-not $settleOverflowStable){'matcher_overflow_changed'}else{
        'shared_deadline_exhausted'}
      snapshot=$initialSnapshot;response=$initialResponse
      deadline_elapsed_ms=$DeadlineElapsedMs;deadline_extended=$false
      max_attempts=$MaxAttempts;attempt_count=1;retry_exhausted=$false
      attempts=$attempts.ToArray();fixture_write_count=0
      matcher_before=$MatcherBefore;matcher_after=$MatcherAfter
      matcher_after_settle=$matcherAfterSettle
      matcher_after_settle_pending_byte_count=
        [int]$matcherAfterSettle.pending_byte_count
      matcher_after_reset=$null;matcher_at_failure=$matcherAfterSettle
      raw_before_reset=$rawBeforeReset
      latest_complete_snapshot=$latestCompleteSnapshot
    }
  }
  Reset-TagMatcherCandidate -State $State
  $matcherAfterReset = Get-CaptureMatcherSnapshot -State $State

  $anchorBudget = Get-DeadlineBoundSnapshotBudget `
      -CurrentElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
      -DeadlineElapsedMs $DeadlineElapsedMs `
      -ConfiguredTimeoutSeconds $SnapshotTimeoutSeconds `
      -ReserveAfterMs ($ReserveAfterMs +
        ([double]$SnapshotTimeoutSeconds * 1000.0))
  if (-not $anchorBudget.can_query) {
    return [pscustomobject][ordered]@{
      valid=$false;recovered=$false;status='REJECT'
      reason='shared_deadline_exhausted';snapshot=$initialSnapshot
      response=$initialResponse;deadline_elapsed_ms=$DeadlineElapsedMs
      deadline_extended=$false;max_attempts=$MaxAttempts;attempt_count=1
      retry_exhausted=$false;attempts=$attempts.ToArray()
      fixture_write_count=0;matcher_after_reset=$matcherAfterReset
      matcher_at_failure=$matcherAfterReset
      latest_complete_snapshot=$latestCompleteSnapshot
    }
  }
  [Nullable[uint32]]$anchorExpectedQ = $null
  if ($disposition.unanchored_ground_recovery) {
    [uint32]$unanchoredPartialQ = [uint32]$disposition.pending_q_uint32
    [uint32]$unanchoredNextQ = Get-NextQueryId -Current $unanchoredPartialQ
    $anchorExpectedQ = $unanchoredNextQ
  }
  if ($disposition.unanchored_ground_recovery) {
    $AnchorSnapshot = Invoke-SnapshotQuery -Name ($Name + '_anchor') `
        -Serial $Serial -State $State -Command $Command `
        -TimeoutSeconds $SnapshotTimeoutSeconds -ExpectedQ $anchorExpectedQ `
        -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
        -GroundSerial $GroundSerial -GroundState $GroundState `
        -AbsoluteDeadlineElapsedMs $anchorBudget.query_deadline_elapsed_ms
  } else {
    $AnchorSnapshot = Invoke-SnapshotQuery -Name ($Name + '_anchor') `
        -Serial $Serial -State $State -Command $Command `
        -TimeoutSeconds $SnapshotTimeoutSeconds -ExpectedQ $null `
        -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
        -GroundSerial $GroundSerial -GroundState $GroundState `
        -AbsoluteDeadlineElapsedMs $anchorBudget.query_deadline_elapsed_ms
  }
  $anchorResponse = Test-ReadinessSnapshotResponse `
      -Snapshot $AnchorSnapshot -ExpectedQ $anchorExpectedQ
  $latestCompleteSnapshot = Select-LatestCompleteDiagnosticSnapshot `
      -CurrentSnapshot $latestCompleteSnapshot `
      -CandidateSnapshot $AnchorSnapshot
  $attempts.Add([pscustomobject][ordered]@{
    attempt=2;kind='anchor';snapshot=$AnchorSnapshot;response=$anchorResponse
  })
  if (-not $anchorResponse.valid) {
    return [pscustomobject][ordered]@{
      valid=$false;recovered=$false;status='REJECT'
      reason='anchor_snapshot_invalid';snapshot=$AnchorSnapshot
      response=$anchorResponse;deadline_elapsed_ms=$DeadlineElapsedMs
      deadline_extended=$false;max_attempts=$MaxAttempts;attempt_count=2
      retry_exhausted=$true;attempts=$attempts.ToArray()
      fixture_write_count=0;matcher_after_reset=$matcherAfterReset
      matcher_at_failure=(Get-CaptureMatcherSnapshot -State $State)
      latest_complete_snapshot=$latestCompleteSnapshot
    }
  }
  [uint32]$recoveredExpectedQ = Get-NextQueryId -Current `
      ([uint32]$AnchorSnapshot.q_uint32)
  $confirmationBudget = Get-DeadlineBoundSnapshotBudget `
      -CurrentElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
      -DeadlineElapsedMs $DeadlineElapsedMs `
      -ConfiguredTimeoutSeconds $SnapshotTimeoutSeconds `
      -ReserveAfterMs $ReserveAfterMs
  if (-not $confirmationBudget.can_query) {
    return [pscustomobject][ordered]@{
      valid=$false;recovered=$false;status='REJECT'
      reason='shared_deadline_exhausted';snapshot=$AnchorSnapshot
      response=$anchorResponse;deadline_elapsed_ms=$DeadlineElapsedMs
      deadline_extended=$false;max_attempts=$MaxAttempts;attempt_count=2
      retry_exhausted=$false;attempts=$attempts.ToArray()
      fixture_write_count=0;matcher_after_reset=$matcherAfterReset
      matcher_at_failure=(Get-CaptureMatcherSnapshot -State $State)
      latest_complete_snapshot=$latestCompleteSnapshot
    }
  }
  $recoveredSnapshot = Invoke-SnapshotQuery -Name ($Name + '_confirmation') `
      -Serial $Serial -State $State -Command $Command `
      -TimeoutSeconds $SnapshotTimeoutSeconds `
      -ExpectedQ $recoveredExpectedQ `
      -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
      -GroundSerial $GroundSerial -GroundState $GroundState `
      -AbsoluteDeadlineElapsedMs $confirmationBudget.query_deadline_elapsed_ms
  $recoveredResponse = Test-ReadinessSnapshotResponse `
      -Snapshot $recoveredSnapshot -ExpectedQ $recoveredExpectedQ
  $latestCompleteSnapshot = Select-LatestCompleteDiagnosticSnapshot `
      -CurrentSnapshot $latestCompleteSnapshot `
      -CandidateSnapshot $recoveredSnapshot
  [int]$queryWriteCount = [int]$initialSnapshot.query_count +
      [int]$AnchorSnapshot.query_count + [int]$recoveredSnapshot.query_count
  $continuity = Test-BacklogRecoveredSnapshotContinuity -Role $Role `
      -PreviousSnapshot $PreviousSnapshot -AnchorSnapshot $AnchorSnapshot `
      -RecoveredSnapshot $recoveredSnapshot `
      -QueryWriteCount $queryWriteCount `
      -FailedPartialQ $disposition.pending_q_uint32
  $attempts.Add([pscustomobject][ordered]@{
    attempt=3;kind='confirmation';snapshot=$recoveredSnapshot
    response=$recoveredResponse;continuity=$continuity
  })
  [bool]$valid = ($recoveredResponse.valid -and $continuity.valid)
  return [pscustomobject][ordered]@{
    valid=$valid;recovered=$valid
    status=if($valid){'RESYNCED'}else{'REJECT'}
    reason=if($valid){'resynchronized_and_confirmed'}else{
      'recovered_snapshot_continuity_invalid'}
    snapshot=$recoveredSnapshot;response=$recoveredResponse
    anchor_snapshot=$AnchorSnapshot;continuity=$continuity
    failed_snapshot=$initialSnapshot;failed_response=$initialResponse
    deadline_elapsed_ms=$DeadlineElapsedMs;deadline_extended=$false
    max_attempts=$MaxAttempts;attempt_count=3
    retry_exhausted=(-not $valid);attempts=$attempts.ToArray()
    fixture_write_count=0;matcher_before=$MatcherBefore
    matcher_after=$MatcherAfter;matcher_after_settle=$matcherAfterSettle
    matcher_after_reset=$matcherAfterReset;raw_before_reset=$rawBeforeReset
    matcher_at_failure=if($valid){$null}else{
      Get-CaptureMatcherSnapshot -State $State
    }
    latest_complete_snapshot=$latestCompleteSnapshot
  }
}

function New-ReadinessAdministrativeState {
  param(
    [Parameter(Mandatory = $true)][double]$GateStartedElapsedMs,
    [Parameter(Mandatory = $true)][int]$TimeoutSeconds,
    [Parameter(Mandatory = $true)][int]$SnapshotTimeoutSeconds,
    [Parameter(Mandatory = $true)]$VehicleState
  )
  [int]$readinessSnapshotTimeoutSeconds =
      [Math]::Min($SnapshotTimeoutSeconds, 20)
  [double]$deadlineElapsedMs = $GateStartedElapsedMs +
      ([double]$TimeoutSeconds * 1000.0)
  [double]$vehicleBReserveMs =
      [double]$script:ReadinessVehicleBReserveMs
  $checkpointBound = Get-MaxReadinessPumpCheckpointCount `
      -TimeoutSeconds $TimeoutSeconds `
      -SnapshotTimeoutSeconds $SnapshotTimeoutSeconds
  if (-not $checkpointBound.valid) {
    throw ('readiness checkpoint cap is smaller than its calculated ' +
      'maximum: calculated=' + $checkpointBound.calculated_checkpoint_maximum +
      '; cap=' + $checkpointBound.fixed_cap)
  }
  return [pscustomobject][ordered]@{
    windows=New-Object 'System.Collections.Generic.List[object]'
    passive_windows=New-Object 'System.Collections.Generic.List[object]'
    pre_request_param_value_events=
        New-Object 'System.Collections.Generic.List[object]'
    attempt=0;passive_attempt=0;valid=$false;timed_out=$false
    sync_invalid=$false;last_vehicle_snapshot=$null
    last_complete_vehicle_B=$null
    ground_sync_invalid=[pscustomobject][ordered]@{
      latched=$false;role='ground';stage=$null;failure=$null
      elapsed_ms=$null;response=$null;matcher_at_latch=$null
    }
    vehicle_sync_invalid=[pscustomobject][ordered]@{
      latched=$false;role='vehicle';stage=$null;failure=$null
      elapsed_ms=$null;response=$null;matcher_at_latch=$null
    }
    expected_vehicle_matcher_overflows=
        [uint64]$VehicleState.MatcherOverflows
    last_raw_flush_elapsed_ms=
        [double]$script:RunWatch.Elapsed.TotalMilliseconds
    readiness_snapshot_timeout_seconds=$readinessSnapshotTimeoutSeconds
    deadline_elapsed_ms=$deadlineElapsedMs
    vehicle_B_reserve_ms=$vehicleBReserveMs
    checkpoint_bound=$checkpointBound
  }
}

function Invoke-PumpHotPathPrewarm {
  param([Parameter(Mandatory = $true)][hashtable]$Definitions)
  [string]$savedPhase = [string]$script:CurrentPhase
  [int]$gc0Before = [GC]::CollectionCount(0)
  [int]$gc1Before = [GC]::CollectionCount(1)
  [int]$gc2Before = [GC]::CollectionCount(2)
  $vehicleMemory = New-Object System.IO.MemoryStream
  $groundMemory = New-Object System.IO.MemoryStream
  $vehicleDummy = $null
  $groundDummy = $null
  $dummyParser = $null
  $epochResult = $null
  $administrativeState = $null
  $assessment = $null
  try {
    [void](Set-ReaderCaptureContext -Phase 'pump_hot_path_prewarm')
    $script:CurrentPhase = 'pump_hot_path_prewarm'
    $dummyParser = New-MavlinkParserState -Definitions $Definitions
    $dummyParser.Enabled = $false
    $vehicleDummy = New-CaptureState -Role 'vehicle' -TagBase 'VCSTAT' `
        -RawStream $vehicleMemory -Mavlink $null
    $groundDummy = New-CaptureState -Role 'ground' -TagBase 'GCSTAT' `
        -RawStream $groundMemory -Mavlink $dummyParser

    [byte[]]$vehicleLine = [System.Text.Encoding]::ASCII.GetBytes(
        ('VCSTAT1 q=1 ms=100 boot=1 r=1 f=0 d7b=1 d7f=1 pad=' +
         [string]::new('7', 4096) + "`n"))
    [byte[]]$groundLine = [System.Text.Encoding]::ASCII.GetBytes(
        ('GCSTAT1 q=1 ms=100 pad=' + [string]::new('8', 4096) + "`n"))
    foreach ($line in @($vehicleLine, $groundLine)) {
      $target = if ([object]::ReferenceEquals($line, $vehicleLine)) {
        $vehicleDummy
      } else { $groundDummy }
      for ([int]$offset = 0; $offset -lt $line.Length; $offset += 32) {
        [int]$count = [Math]::Min(32, $line.Length - $offset)
        [byte[]]$chunk = New-Object byte[] $count
        [Array]::Copy($line, $offset, $chunk, 0, $count)
        Add-CaptureBytes -State $target -Buffer $chunk -Count $count
      }
    }

    Reset-MavlinkAnalysis -Parser $dummyParser
    $dummyEpoch = New-ReadinessParserEpoch -Parser $dummyParser `
        -Name 'isolated_prewarm_epoch' -StartElapsedMs 0.0 `
        -StartRawOffset ([long]$groundDummy.RawBytes)
    [byte[]]$heartbeatPayload = New-Object byte[] 9
    [byte[]]$heartbeatFrame = New-Mavlink2TestFrame -MessageId 0 `
        -Payload $heartbeatPayload -CrcExtra ([byte]50)
    foreach ($sequence in 1,2) {
      $heartbeatFrame[4] = [byte]$sequence
      [int]$crc = Get-MavlinkCrc -Bytes $heartbeatFrame -Start 1 `
          -Count 18 -Extra ([byte]50)
      $heartbeatFrame[19] = [byte]($crc -band 0xFF)
      $heartbeatFrame[20] = [byte](($crc -shr 8) -band 0xFF)
      Add-CaptureBytes -State $groundDummy -Buffer $heartbeatFrame `
          -Count $heartbeatFrame.Length
    }
    $dummyDestination =
        New-Object 'System.Collections.Generic.List[object]'
    $epochResult = Complete-ReadinessParserEpoch -Epoch $dummyEpoch `
        -Parser $dummyParser -Destination $dummyDestination `
        -EndElapsedMs 5000.0 -EndRawOffset ([long]$groundDummy.RawBytes)

    $administrativeState = New-ReadinessAdministrativeState `
        -GateStartedElapsedMs 0.0 -TimeoutSeconds 720 `
        -SnapshotTimeoutSeconds 20 -VehicleState $vehicleDummy
    $beforeSnapshot = [pscustomobject]@{
      status='COMPLETE';responses=@([pscustomobject]@{fields=[pscustomobject]@{
        q='1';boot='1';ms='100';r='1';f='0';d7b='10';d7f='10'}})
    }
    $afterSnapshot = [pscustomobject]@{
      status='COMPLETE';responses=@([pscustomobject]@{fields=[pscustomobject]@{
        q='2';boot='1';ms='5100';r='1';f='0';d7b='20';d7f='20'}})
    }
    $syntheticHeartbeatEvents = @(
      [pscustomobject]@{message_id=0;system_id=1;component_id=1;elapsed_ms=1000.0},
      [pscustomobject]@{message_id=0;system_id=1;component_id=1;elapsed_ms=3000.0},
      [pscustomobject]@{message_id=0;system_id=1;component_id=1;elapsed_ms=4500.0})
    $assessment = Test-DataPlaneReadinessWindow `
        -Events $syntheticHeartbeatEvents `
        -ParserIntegrity $epochResult.integrity `
        -WindowStartElapsedMs 0.0 -WindowEndElapsedMs 5000.0 `
        -VehicleBefore $beforeSnapshot -VehicleAfter $afterSnapshot
  } finally {
    [void](Set-ReaderCaptureContext -Phase $savedPhase)
    $script:CurrentPhase = $savedPhase
    $groundMemory.Dispose()
    $vehicleMemory.Dispose()
  }
  [GC]::Collect()
  [GC]::WaitForPendingFinalizers()
  [GC]::Collect()
  [bool]$valid = ($null -ne $epochResult -and
      [bool]$epochResult.integrity.valid -and
      $vehicleDummy.TaggedLines.Count -eq 1 -and
      $groundDummy.TaggedLines.Count -eq 1 -and
      [bool]$administrativeState.checkpoint_bound.valid -and
      [bool]$assessment.valid)
  return [pscustomobject][ordered]@{
    schema_version=1;valid=$valid;completed=$true
    isolation='MemoryStream/dummy_parser/dummy_capture_only'
    actual_capture_or_parser_passed=$false
    fixture_passed_or_read=$false
    serial_port_constructed=$false;serial_port_opened=$false
    request_write_count=0
    vehicle_raw_bytes=[long]$vehicleDummy.RawBytes
    ground_raw_bytes=[long]$groundDummy.RawBytes
    vehicle_tagged_line_count=$vehicleDummy.TaggedLines.Count
    ground_tagged_line_count=$groundDummy.TaggedLines.Count
    parser_epoch_valid=[bool]$epochResult.integrity.valid
    parser_valid_event_count=$epochResult.valid_events.Count
    readiness_administrative_state_valid=
        [bool]$administrativeState.checkpoint_bound.valid
    readiness_assessment_valid=[bool]$assessment.valid
    gc_completed=$true
    gc0_before=$gc0Before;gc0_after=[GC]::CollectionCount(0)
    gc1_before=$gc1Before;gc1_after=[GC]::CollectionCount(1)
    gc2_before=$gc2Before;gc2_after=[GC]::CollectionCount(2)
  }
}

function Invoke-DataPlaneReadinessGate {
  param(
    [Parameter(Mandatory = $true)][double]$GateStartedElapsedMs,
    [Parameter(Mandatory = $true)][int]$TimeoutSeconds,
    [Parameter(Mandatory = $true)][int]$SnapshotTimeoutSeconds,
    [Parameter(Mandatory = $true)]$GroundParser,
    [Parameter(Mandatory = $true)]$VehicleSerial,
    [Parameter(Mandatory = $true)]$VehicleState,
    [Parameter(Mandatory = $true)]$GroundSerial,
    [Parameter(Mandatory = $true)]$GroundState,
    [Parameter(Mandatory = $true)][byte[]]$VehicleCommand
  )
  $readinessPumpCheckpoints = `
      New-Object 'System.Collections.Generic.List[object]'
  $windows = $null
  $passiveWindows = $null
  $preRequestParamValueEvents = $null
  [int]$attempt = 0
  [int]$passiveAttempt = 0
  [bool]$valid = $false
  [bool]$timedOut = $false
  [bool]$syncInvalid = $false
  $lastVehicleSnapshot = $null
  $lastCompleteVehicleB = $null
  $activeEpoch = $null
  $groundSyncInvalid = $null
  $vehicleSyncInvalid = $null
  [uint64]$expectedVehicleMatcherOverflows = [uint64]0
  [double]$lastRawFlushElapsedMs = [double]0
  [int]$readinessSnapshotTimeoutSeconds = 0
  [double]$deadlineElapsedMs = [double]0
  [double]$vehicleBReserveMs = [double]0
  $checkpointBound = $null
  try {
    $GroundParser.Enabled = $false
    Reset-MavlinkAnalysis -Parser $GroundParser
    $activeEpoch = New-ReadinessParserEpoch -Parser $GroundParser `
        -Name 'boot_boundary_1' `
        -StartElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
        -StartRawOffset ([long]$GroundState.RawBytes)
    $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
        -Stage 'readiness_entry_epoch_open' `
        -GroundParser $GroundParser -Epoch $activeEpoch `
        -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
        -GroundSerial $GroundSerial -GroundState $GroundState))
    $administrativeState = New-ReadinessAdministrativeState `
        -GateStartedElapsedMs $GateStartedElapsedMs `
        -TimeoutSeconds $TimeoutSeconds `
        -SnapshotTimeoutSeconds $SnapshotTimeoutSeconds `
        -VehicleState $VehicleState
    $windows = $administrativeState.windows
    $passiveWindows = $administrativeState.passive_windows
    $preRequestParamValueEvents =
        $administrativeState.pre_request_param_value_events
    $attempt = [int]$administrativeState.attempt
    $passiveAttempt = [int]$administrativeState.passive_attempt
    $valid = [bool]$administrativeState.valid
    $timedOut = [bool]$administrativeState.timed_out
    $syncInvalid = [bool]$administrativeState.sync_invalid
    $lastVehicleSnapshot = $administrativeState.last_vehicle_snapshot
    $lastCompleteVehicleB = $administrativeState.last_complete_vehicle_B
    $groundSyncInvalid = $administrativeState.ground_sync_invalid
    $vehicleSyncInvalid = $administrativeState.vehicle_sync_invalid
    $expectedVehicleMatcherOverflows =
        [uint64]$administrativeState.expected_vehicle_matcher_overflows
    $lastRawFlushElapsedMs =
        [double]$administrativeState.last_raw_flush_elapsed_ms
    $readinessSnapshotTimeoutSeconds =
        [int]$administrativeState.readiness_snapshot_timeout_seconds
    $deadlineElapsedMs = [double]$administrativeState.deadline_elapsed_ms
    $vehicleBReserveMs = [double]$script:ReadinessVehicleBReserveMs
    if ($vehicleBReserveMs -ne
        [double]$administrativeState.vehicle_B_reserve_ms) {
      throw 'readiness Vehicle-B reserve changed during setup'
    }
    $checkpointBound = $administrativeState.checkpoint_bound
    $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
        -Stage 'readiness_entry_after_setup' `
        -GroundParser $GroundParser -Epoch $activeEpoch `
        -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
        -GroundSerial $GroundSerial -GroundState $GroundState))
    $VehicleState.RawStream.Flush($true)
    $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
        -Stage 'readiness_start_between_raw_fsync' `
        -GroundParser $GroundParser -Epoch $activeEpoch `
        -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
        -GroundSerial $GroundSerial -GroundState $GroundState))
    $GroundState.RawStream.Flush($true)
    $lastRawFlushElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
    [void](Set-ReaderCaptureContext -Phase 'data_plane_readiness')
    $script:CurrentPhase = 'data_plane_readiness'
    Add-TimelineEvent -Name 'data_plane_readiness_started' -Details @{
      gate_started_elapsed_ms=[Math]::Round($GateStartedElapsedMs,3)
      deadline_elapsed_ms=[Math]::Round($deadlineElapsedMs,3)
      timeout_seconds=$TimeoutSeconds;window_ms=5000
      passive_prefilter_window_ms=5000
      vehicle_B_reserve_ms=$vehicleBReserveMs
    }
    Add-LiveProgressRecord -Event 'data_plane_readiness_started' -Details @{
      gate_started_elapsed_ms=[Math]::Round($GateStartedElapsedMs,3)
      deadline_elapsed_ms=[Math]::Round($deadlineElapsedMs,3)
      timeout_seconds=$TimeoutSeconds;window_ms=5000
      passive_prefilter_window_ms=5000
      vehicle_B_reserve_ms=$vehicleBReserveMs
    }
    $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
        -Stage 'readiness_start_after_progress_fsync' `
        -GroundParser $GroundParser -Epoch $activeEpoch `
        -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
        -GroundSerial $GroundSerial -GroundState $GroundState))
    while (-not $valid -and -not $syncInvalid) {
      $passiveDecision = Get-ReadinessPassiveWindowDecision `
          -GateStartedElapsedMs $GateStartedElapsedMs `
          -CurrentElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -TimeoutSeconds $TimeoutSeconds `
          -SnapshotTimeoutSeconds $readinessSnapshotTimeoutSeconds
      if (-not $passiveDecision.can_start_full_pipeline) {
        $timedOut = $true
        break
      }

      ++$passiveAttempt
      $boundaryEpoch = if ($null -ne $activeEpoch -and
          -not [bool]$activeEpoch.closed) {
        $activeEpoch
      } else {
        New-ReadinessParserEpoch -Parser $GroundParser `
            -Name ('boot_boundary_{0}' -f $passiveAttempt) `
            -StartElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
            -StartRawOffset ([long]$GroundState.RawBytes)
      }
      $activeEpoch = $boundaryEpoch
      $idleResult = Invoke-PumpPairUntilIdle `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState `
          -GroundParser $GroundParser -Epoch $activeEpoch `
          -LastRawFlushElapsedMs $lastRawFlushElapsedMs `
          -AbsoluteDeadlineElapsedMs $deadlineElapsedMs
      foreach ($idleRawFsyncCheckpoint in
          $idleResult.raw_fsync_pump_checkpoints) {
        [void]$readinessPumpCheckpoints.Add($idleRawFsyncCheckpoint)
      }
      $lastRawFlushElapsedMs =
          [double]$idleResult.last_raw_flush_elapsed_ms
      $boundaryEpochResult = Complete-ReadinessParserEpochChecked `
          -Epoch $boundaryEpoch -Parser $GroundParser `
          -Destination $preRequestParamValueEvents `
          -EndElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -EndRawOffset ([long]$GroundState.RawBytes) `
          -Stage 'boot_boundary/pump_to_idle' `
          -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $GroundState)
      $activeEpoch = $null
      if ($boundaryEpochResult.sync_invalid) {
        $groundSyncInvalid = $boundaryEpochResult.ground_sync_invalid
        $syncInvalid = $true
        break
      }
      if (-not $idleResult.idle) {
        $timedOut = $true
        break
      }

      [long]$passiveStartRawOffset = [long]$GroundState.RawBytes
      [double]$passiveStartMs = `
          $script:RunWatch.Elapsed.TotalMilliseconds
      $passiveEpoch = New-ReadinessParserEpoch -Parser $GroundParser `
          -Name ('data_plane_readiness_passive_window_{0}' -f `
            $passiveAttempt) -StartElapsedMs $passiveStartMs `
          -StartRawOffset $passiveStartRawOffset
      $activeEpoch = $passiveEpoch
      [double]$passiveAbsoluteDeadlineMs = $deadlineElapsedMs -
          (([double]$readinessSnapshotTimeoutSeconds * 1000.0) +
           5000.0 + $vehicleBReserveMs)
      $passiveCapture = Invoke-CaptureInterval -Milliseconds 5000 `
          -Phase ('data_plane_readiness_passive_window_{0}' -f `
            $passiveAttempt) `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState `
          -AbsoluteDeadlineElapsedMs $passiveAbsoluteDeadlineMs -PassThru
      $passiveEpochResult = Complete-ReadinessParserEpochChecked `
          -Epoch $passiveEpoch -Parser $GroundParser `
          -Destination $preRequestParamValueEvents `
          -EndElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -EndRawOffset ([long]$GroundState.RawBytes) `
          -Stage 'passive_prefilter' `
          -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $GroundState)
      $activeEpoch = $null
      $passiveCandidate = Test-DataPlanePassiveCandidate `
          -Events $passiveEpochResult.heartbeat_events `
          -ParserIntegrity $passiveEpochResult.integrity `
          -Capture $passiveCapture -Idle $idleResult.idle `
          -GroundRawStartOffset $passiveStartRawOffset `
          -GroundRawEndOffset ([long]$GroundState.RawBytes)
      $passiveRow = [pscustomobject][ordered]@{
        attempt=$passiveAttempt;phase='passive_prefilter'
        idle_boundary=$idleResult;boundary_epoch=$boundaryEpochResult
        parser_epoch=$passiveEpochResult;candidate=$passiveCandidate
        vehicle_diagnostic_query_count=0
      }
      $passiveWindows.Add($passiveRow)
      $bracketEpoch = $null
      if (-not $passiveCandidate.sync_invalid) {
        [string]$nextEpochName = if ($passiveCandidate.candidate) {
          [void](++$attempt)
          'readiness_A_window_B_{0}' -f $attempt
        } else {
          'boot_boundary_{0}' -f ($passiveAttempt + 1)
        }
        $bracketEpoch = New-ReadinessParserEpoch -Parser $GroundParser `
            -Name $nextEpochName `
            -StartElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
            -StartRawOffset ([long]$GroundState.RawBytes)
        $activeEpoch = $bracketEpoch
        $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
            -Stage ('passive_{0}_administration_start' -f $passiveAttempt) `
            -GroundParser $GroundParser -Epoch $activeEpoch `
            -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
            -GroundSerial $GroundSerial -GroundState $GroundState))
      }
      [double]$passiveProgressElapsedMs =
          $script:RunWatch.Elapsed.TotalMilliseconds
      if ($passiveCandidate.sync_invalid) {
        $VehicleState.RawStream.Flush($true)
        $GroundState.RawStream.Flush($true)
        $lastRawFlushElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
      } elseif ($passiveCandidate.candidate -or
          $passiveProgressElapsedMs - $lastRawFlushElapsedMs -ge
          $script:RawCaptureFlushScheduleMs) {
        $passiveRawFsyncBoundary = Invoke-ReadinessRawFsyncBoundary `
            -Stage $(if ($passiveCandidate.candidate) {
              'candidate_before_A_{0}' -f $attempt
            } else {
              'passive_{0}_scheduled' -f $passiveAttempt
            }) `
            -LastRawFlushElapsedMs $lastRawFlushElapsedMs `
            -GroundParser $GroundParser -Epoch $activeEpoch `
            -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
            -GroundSerial $GroundSerial -GroundState $GroundState
        foreach ($passiveRawFsyncCheckpoint in
            $passiveRawFsyncBoundary.pump_checkpoints) {
          [void]$readinessPumpCheckpoints.Add($passiveRawFsyncCheckpoint)
        }
        $lastRawFlushElapsedMs =
            [double]$passiveRawFsyncBoundary.last_raw_flush_elapsed_ms
      }
      Add-TimelineEvent -Name 'data_plane_readiness_window' -Details @{
        attempt=$passiveAttempt;phase='passive_prefilter'
        valid=$passiveCandidate.candidate
        sync_invalid=$passiveCandidate.sync_invalid
        heartbeat_count=$passiveCandidate.heartbeat.count
        fixture_write_count=0
      }
      Add-LiveProgressRecord -Event 'data_plane_readiness_window' -Details @{
        attempt=$passiveAttempt;readiness_phase='passive_prefilter'
        valid=$passiveCandidate.candidate
        sync_invalid=$passiveCandidate.sync_invalid
        heartbeat_count=$passiveCandidate.heartbeat.count
        elapsed_from_ports_opened_s=[Math]::Round(
          (($passiveProgressElapsedMs - $GateStartedElapsedMs) / 1000.0),3)
        fixture_write_count=0
      }
      if (-not $passiveCandidate.sync_invalid) {
        $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
            -Stage ('passive_{0}_after_progress_fsync' -f $passiveAttempt) `
            -GroundParser $GroundParser -Epoch $activeEpoch `
            -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
            -GroundSerial $GroundSerial -GroundState $GroundState))
      }
      if ($passiveCandidate.sync_invalid) {
        $groundSyncInvalid = $passiveEpochResult.ground_sync_invalid
        $syncInvalid = $true
        break
      }
      if (-not $passiveCandidate.candidate) {
        [string]$phase = 'passive_prefilter'
        [void]$phase
        continue
      }

      if (-not [bool]$GroundParser.Enabled -or $null -eq $bracketEpoch -or
          [bool]$bracketEpoch.closed) {
        throw 'readiness A refused without the open parser-safe bracket epoch'
      }
      $GroundParser.Enabled = $true
      $vehicleAMatcherGate = Test-CaptureMatcherClean -State $VehicleState `
          -ExpectedOverflowCount $expectedVehicleMatcherOverflows
      if (-not $vehicleAMatcherGate.valid) {
        $vehicleSyncInvalid = New-ReadinessSyncInvalidLatch -Role 'vehicle' `
            -Stage 'A' -Failure 'preexisting_partial_matcher' `
            -Response $null `
            -MatcherSnapshot $vehicleAMatcherGate.snapshot
        $vehicleSyncInvalid.matcher_at_latch = $vehicleAMatcherGate.snapshot
        $syncInvalid = $true
        $aPreDirtyClose = Complete-ReadinessParserEpochChecked `
          -Epoch $bracketEpoch `
          -Parser $GroundParser -Destination $preRequestParamValueEvents `
          -EndElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -EndRawOffset ([long]$GroundState.RawBytes) -Stage 'A_window_B' `
          -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $GroundState)
        if ($aPreDirtyClose.sync_invalid) {
          $groundSyncInvalid = $aPreDirtyClose.ground_sync_invalid
        }
        $activeEpoch = $null
        break
      }
      [Nullable[uint32]]$expectedA = Get-ReadinessExpectedA `
          -LastCompleteVehicleB $lastCompleteVehicleB
      $aBudget = Get-DeadlineBoundSnapshotBudget `
          -CurrentElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -DeadlineElapsedMs $deadlineElapsedMs `
          -ConfiguredTimeoutSeconds $readinessSnapshotTimeoutSeconds `
          -ReserveAfterMs (5000.0 + $vehicleBReserveMs)
      if (-not $aBudget.can_query) {
        $aBudgetClose = Complete-ReadinessParserEpochChecked `
          -Epoch $bracketEpoch `
          -Parser $GroundParser -Destination $preRequestParamValueEvents `
          -EndElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -EndRawOffset ([long]$GroundState.RawBytes) -Stage 'A_window_B' `
          -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $GroundState)
        if ($aBudgetClose.sync_invalid) {
          $groundSyncInvalid = $aBudgetClose.ground_sync_invalid
          $syncInvalid = $true
        } else {
          $timedOut = $true
        }
        $activeEpoch = $null
        break
      }
      $vehicleA = Invoke-SnapshotQuery `
          -Name ('readiness_vehicle_A_{0}' -f $attempt) `
          -Serial $VehicleSerial -State $VehicleState `
          -Command $VehicleCommand `
          -TimeoutSeconds $readinessSnapshotTimeoutSeconds `
          -ExpectedQ $expectedA -VehicleSerial $VehicleSerial `
          -VehicleState $VehicleState -GroundSerial $GroundSerial `
          -GroundState $GroundState `
          -AbsoluteDeadlineElapsedMs $aBudget.query_deadline_elapsed_ms
      $vehicleAPostQueryMatcher = Get-CaptureMatcherSnapshot `
          -State $VehicleState
      $vehicleATransition = Get-ReadinessSnapshotTransition -Stage 'A' `
          -Snapshot $vehicleA -ExpectedQ $expectedA `
          -CurrentCompleteB $lastCompleteVehicleB `
          -PreQueryMatcherSnapshot $vehicleAMatcherGate.snapshot `
          -MatcherSnapshot $vehicleAPostQueryMatcher
      $vehicleAResponse = $vehicleATransition.response
      if (-not $vehicleATransition.valid) {
        [string]$failure='vehicle_A_invalid_or_timeout'
        $vehicleSyncInvalid = $vehicleATransition.sync_invalid_latch
        $syncInvalid = $true
        $aRejectClose = Complete-ReadinessParserEpochChecked `
          -Epoch $bracketEpoch `
          -Parser $GroundParser -Destination $preRequestParamValueEvents `
          -EndElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -EndRawOffset ([long]$GroundState.RawBytes) -Stage 'A_window_B' `
          -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $GroundState)
        if ($aRejectClose.sync_invalid) {
          $groundSyncInvalid = $aRejectClose.ground_sync_invalid
        }
        $activeEpoch = $null
        break
      }

      [double]$windowStartMs = `
          $script:RunWatch.Elapsed.TotalMilliseconds
      [long]$windowStartRawOffset = [long]$GroundState.RawBytes
      $windowCapture = Invoke-CaptureInterval -Milliseconds 5000 `
          -Phase ('data_plane_readiness_window_{0}' -f $attempt) `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState `
          -AbsoluteDeadlineElapsedMs ($deadlineElapsedMs - $vehicleBReserveMs) `
          -PassThru
      [double]$windowEndMs = $script:RunWatch.Elapsed.TotalMilliseconds
      [long]$windowEndRawOffset = [long]$GroundState.RawBytes
      if (-not $windowCapture.completed_duration) {
        $windowIncompleteClose = Complete-ReadinessParserEpochChecked `
          -Epoch $bracketEpoch `
          -Parser $GroundParser -Destination $preRequestParamValueEvents `
          -EndElapsedMs $windowEndMs -EndRawOffset $windowEndRawOffset `
          -Stage 'A_window_B' `
          -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $GroundState)
        if ($windowIncompleteClose.sync_invalid) {
          $groundSyncInvalid = $windowIncompleteClose.ground_sync_invalid
          $syncInvalid = $true
        } else {
          $timedOut = $true
        }
        $activeEpoch = $null
        break
      }
      $windowRawFsyncBoundary = Invoke-ReadinessRawFsyncBoundary `
          -Stage ('window_before_B_{0}' -f $attempt) `
          -LastRawFlushElapsedMs $lastRawFlushElapsedMs `
          -GroundParser $GroundParser -Epoch $activeEpoch `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState
      foreach ($windowRawFsyncCheckpoint in
          $windowRawFsyncBoundary.pump_checkpoints) {
        [void]$readinessPumpCheckpoints.Add($windowRawFsyncCheckpoint)
      }
      $lastRawFlushElapsedMs =
          [double]$windowRawFsyncBoundary.last_raw_flush_elapsed_ms
      $vehicleBMatcherGate = Test-CaptureMatcherClean -State $VehicleState `
          -ExpectedOverflowCount $expectedVehicleMatcherOverflows
      if (-not $vehicleBMatcherGate.valid) {
        $vehicleSyncInvalid = New-ReadinessSyncInvalidLatch -Role 'vehicle' `
            -Stage 'B' -Failure 'preexisting_partial_matcher' `
            -Response $null `
            -MatcherSnapshot $vehicleBMatcherGate.snapshot
        $vehicleSyncInvalid.matcher_at_latch = $vehicleBMatcherGate.snapshot
        $syncInvalid = $true
        $bPreDirtyClose = Complete-ReadinessParserEpochChecked `
          -Epoch $bracketEpoch `
          -Parser $GroundParser -Destination $preRequestParamValueEvents `
          -EndElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -EndRawOffset ([long]$GroundState.RawBytes) -Stage 'A_window_B' `
          -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $GroundState)
        if ($bPreDirtyClose.sync_invalid) {
          $groundSyncInvalid = $bPreDirtyClose.ground_sync_invalid
        }
        $activeEpoch = $null
        break
      }
      [Nullable[uint32]]$expectedB = Get-NextQueryId -Current `
          ([uint32]$vehicleA.q_uint32)
      $bBudget = Get-DeadlineBoundSnapshotBudget `
          -CurrentElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -DeadlineElapsedMs $deadlineElapsedMs `
          -ConfiguredTimeoutSeconds $readinessSnapshotTimeoutSeconds `
          -ReserveAfterMs 0.0
      if (-not $bBudget.can_query) {
        $bBudgetClose = Complete-ReadinessParserEpochChecked `
          -Epoch $bracketEpoch `
          -Parser $GroundParser -Destination $preRequestParamValueEvents `
          -EndElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -EndRawOffset ([long]$GroundState.RawBytes) -Stage 'A_window_B' `
          -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $GroundState)
        if ($bBudgetClose.sync_invalid) {
          $groundSyncInvalid = $bBudgetClose.ground_sync_invalid
          $syncInvalid = $true
        } else {
          $timedOut = $true
        }
        $activeEpoch = $null
        break
      }
      $vehicleB = Invoke-SnapshotQuery `
          -Name ('readiness_vehicle_B_{0}' -f $attempt) `
          -Serial $VehicleSerial -State $VehicleState `
          -Command $VehicleCommand `
          -TimeoutSeconds $readinessSnapshotTimeoutSeconds `
          -ExpectedQ $expectedB -VehicleSerial $VehicleSerial `
          -VehicleState $VehicleState -GroundSerial $GroundSerial `
          -GroundState $GroundState `
          -AbsoluteDeadlineElapsedMs $bBudget.query_deadline_elapsed_ms `
          -AllowVehiclePartialUsbWake
      $vehicleBPostQueryMatcher = Get-CaptureMatcherSnapshot `
          -State $VehicleState
      $vehicleBTransition = Get-ReadinessSnapshotTransition -Stage 'B' `
          -Snapshot $vehicleB -ExpectedQ $expectedB `
          -CurrentCompleteB $lastCompleteVehicleB `
          -PreQueryMatcherSnapshot $vehicleBMatcherGate.snapshot `
          -MatcherSnapshot $vehicleBPostQueryMatcher
      $vehicleBResponse = $vehicleBTransition.response
      if (-not $vehicleBTransition.valid) {
        [string]$failure='vehicle_B_invalid_or_timeout'
        $vehicleSyncInvalid = $vehicleBTransition.sync_invalid_latch
        $syncInvalid = $true
        $bRejectClose = Complete-ReadinessParserEpochChecked `
          -Epoch $bracketEpoch `
          -Parser $GroundParser -Destination $preRequestParamValueEvents `
          -EndElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -EndRawOffset ([long]$GroundState.RawBytes) -Stage 'A_window_B' `
          -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $GroundState)
        if ($bRejectClose.sync_invalid) {
          $groundSyncInvalid = $bRejectClose.ground_sync_invalid
        }
        $activeEpoch = $null
        break
      }
      $lastCompleteVehicleB = $vehicleB
      $bracketEpochResult = Complete-ReadinessParserEpochChecked `
          -Epoch $bracketEpoch -Parser $GroundParser `
          -Destination $preRequestParamValueEvents `
          -EndElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -EndRawOffset ([long]$GroundState.RawBytes) -Stage 'A_window_B' `
          -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $GroundState)
      $activeEpoch = $null
      if (-not $bracketEpochResult.integrity.valid) {
        $groundSyncInvalid = $bracketEpochResult.ground_sync_invalid
        $syncInvalid = $true
        break
      }
      $activeEpoch = New-ReadinessParserEpoch -Parser $GroundParser `
          -Name ('post_readiness_bracket_boundary_{0}' -f $attempt) `
          -StartElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -StartRawOffset ([long]$GroundState.RawBytes)
      $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
          -Stage ('bracket_{0}_administration_start' -f $attempt) `
          -GroundParser $GroundParser -Epoch $activeEpoch `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState))
      $windowAssessment = Test-DataPlaneReadinessWindow `
          -Events $bracketEpochResult.heartbeat_events `
          -ParserIntegrity $bracketEpochResult.integrity `
          -WindowStartElapsedMs $windowStartMs `
          -WindowEndElapsedMs $windowEndMs `
          -VehicleBefore $vehicleA -VehicleAfter $vehicleB
      [bool]$withinDeadline = (
        $script:RunWatch.Elapsed.TotalMilliseconds -le $deadlineElapsedMs)
      $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
          -Stage ('bracket_{0}_after_assessment' -f $attempt) `
          -GroundParser $GroundParser -Epoch $activeEpoch `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState))
      $lastVehicleSnapshot = Select-ReadinessLastVehicleSnapshot `
          -CurrentSnapshot $lastVehicleSnapshot -VehicleAfter $vehicleB `
          -VehicleAResponse $vehicleAResponse `
          -VehicleBResponse $vehicleBResponse `
          -WindowAssessment $windowAssessment -WithinDeadline $withinDeadline
      $windowRow = [pscustomobject][ordered]@{
        attempt=$attempt;phase='A_window_B'
        valid=($windowAssessment.valid -and $withinDeadline)
        within_deadline=$withinDeadline;vehicle_A=$vehicleA
        vehicle_A_response=$vehicleAResponse
        vehicle_A_matcher_before_query=$vehicleATransition.matcher_before_query
        vehicle_A_matcher_after_query=$vehicleATransition.matcher_after_query
        capture=$windowCapture;vehicle_B=$vehicleB
        vehicle_B_response=$vehicleBResponse
        vehicle_B_matcher_before_query=$vehicleBTransition.matcher_before_query
        vehicle_B_matcher_after_query=$vehicleBTransition.matcher_after_query
        parser_epoch=$bracketEpochResult;assessment=$windowAssessment
      }
      $windows.Add($windowRow)
      $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
          -Stage ('bracket_{0}_after_window_row' -f $attempt) `
          -GroundParser $GroundParser -Epoch $activeEpoch `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState))
      [double]$rawFlushCheckElapsedMs =
          $script:RunWatch.Elapsed.TotalMilliseconds
      if ($rawFlushCheckElapsedMs - $lastRawFlushElapsedMs -ge
          $script:RawCaptureFlushScheduleMs) {
        if ($rawFlushCheckElapsedMs - $lastRawFlushElapsedMs -gt
            $script:RawCaptureFlushIntervalMs) {
          throw 'readiness raw evidence Flush(true) interval exceeded 30000 ms'
        }
        $bracketRawFsyncBoundary = Invoke-ReadinessRawFsyncBoundary `
            -Stage ('bracket_{0}_scheduled' -f $attempt) `
            -LastRawFlushElapsedMs $lastRawFlushElapsedMs `
            -GroundParser $GroundParser -Epoch $activeEpoch `
            -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
            -GroundSerial $GroundSerial -GroundState $GroundState
        foreach ($bracketRawFsyncCheckpoint in
            $bracketRawFsyncBoundary.pump_checkpoints) {
          [void]$readinessPumpCheckpoints.Add($bracketRawFsyncCheckpoint)
        }
        $lastRawFlushElapsedMs =
            [double]$bracketRawFsyncBoundary.last_raw_flush_elapsed_ms
      }
      Add-TimelineEvent -Name 'data_plane_readiness_window' -Details @{
        attempt=$attempt;phase='A_window_B';valid=$windowRow.valid
        heartbeat_count=$windowAssessment.heartbeat.count
        heartbeat_maximum_gap_ms=$windowAssessment.heartbeat.maximum_gap_ms
        parser_valid=$windowAssessment.parser_integrity.valid
        d7b_delta=$windowAssessment.vehicle_transition.d7b_delta
        d7f_delta=$windowAssessment.vehicle_transition.d7f_delta
      }
      Add-LiveProgressRecord -Event 'data_plane_readiness_window' -Details @{
        attempt=$attempt;readiness_phase='A_window_B';valid=$windowRow.valid
        heartbeat_count=$windowAssessment.heartbeat.count
        d7b_delta=$windowAssessment.vehicle_transition.d7b_delta
        d7f_delta=$windowAssessment.vehicle_transition.d7f_delta
        fixture_write_count=0
      }
      $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
          -Stage ('bracket_{0}_after_progress_fsync' -f $attempt) `
          -GroundParser $GroundParser -Epoch $activeEpoch `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState))
      if ($windowRow.valid) {
        $valid = $true
      } else {
        [string]$phase = 'passive_prefilter'
        [void]$phase
        continue
      }
    }
  } finally {
    if ($null -ne $activeEpoch -and -not $activeEpoch.closed) {
      $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
          -Stage 'readiness_finally_before_raw_fsync' `
          -GroundParser $GroundParser -Epoch $activeEpoch `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState))
      $VehicleState.RawStream.Flush($true)
      $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
          -Stage 'readiness_finally_between_raw_fsync' `
          -GroundParser $GroundParser -Epoch $activeEpoch `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState))
      $GroundState.RawStream.Flush($true)
      $readinessPumpCheckpoints.Add((Invoke-ReadinessPumpCheckpoint `
          -Stage 'readiness_finally_after_raw_fsync' `
          -GroundParser $GroundParser -Epoch $activeEpoch `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState))
      $lastRawFlushElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
      $finallyClose = Complete-ReadinessParserEpochChecked `
        -Epoch $activeEpoch `
        -Parser $GroundParser -Destination $preRequestParamValueEvents `
        -EndElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
        -EndRawOffset ([long]$GroundState.RawBytes) -Stage 'A_window_B' `
        -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $GroundState)
      if ($finallyClose.sync_invalid) {
        $groundSyncInvalid = $finallyClose.ground_sync_invalid
        $syncInvalid = $true
        $valid = $false
      }
      $activeEpoch = $null
    } else {
      $VehicleState.RawStream.Flush($true)
      $GroundState.RawStream.Flush($true)
      $lastRawFlushElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
    }
    $GroundParser.Enabled = $false
    Reset-MavlinkAnalysis -Parser $GroundParser
  }
  if ($readinessPumpCheckpoints.Count -gt
      $script:MaxReadinessPumpCheckpointEvents) {
    throw ('readiness pump checkpoint evidence cap exceeded; refusing ' +
      'truncation')
  }
  $result = [pscustomobject][ordered]@{
    schema_version=1;valid=[bool]$valid
    timed_out=[bool]($timedOut -and -not $valid -and -not $syncInvalid)
    sync_invalid=[bool]($syncInvalid -and -not $valid)
    gate_started_elapsed_ms=[Math]::Round($GateStartedElapsedMs,3)
    gate_finished_elapsed_ms=[Math]::Round(
      $script:RunWatch.Elapsed.TotalMilliseconds,3)
    timeout_seconds=$TimeoutSeconds;window_duration_ms=5000
    passive_prefilter_window_duration_ms=5000
    deadline_elapsed_ms=[Math]::Round($deadlineElapsedMs,3)
    vehicle_B_reserve_ms=$vehicleBReserveMs
    device_ms_tolerance_ms=$script:ReadinessDeviceMsToleranceMs
    raw_capture_buffer_bytes=$script:RawCaptureBufferBytes
    raw_flush_schedule_ms=$script:RawCaptureFlushScheduleMs
    raw_flush_max_interval_ms=$script:RawCaptureFlushIntervalMs
    readiness_pump_checkpoint_cap=$script:MaxReadinessPumpCheckpointEvents
    readiness_pump_checkpoint_bound=$checkpointBound
    readiness_pump_checkpoint_count=$readinessPumpCheckpoints.Count
    readiness_pump_checkpoints=$readinessPumpCheckpoints.ToArray()
    attempt_count=$attempt
    passive_attempt_count=$passiveAttempt
    passive_windows=$passiveWindows.ToArray();windows=$windows.ToArray()
    last_complete_vehicle_B=$lastCompleteVehicleB
    last_vehicle_snapshot=$lastVehicleSnapshot
    pre_request_param_value_count=$preRequestParamValueEvents.Count
    pre_request_param_value_events=$preRequestParamValueEvents.ToArray()
    ground_sync_invalid=$groundSyncInvalid
    vehicle_sync_invalid=$vehicleSyncInvalid
    ground_parser_disabled_and_reset=$true
  }
  Add-TimelineEvent -Name 'data_plane_readiness_result' -Details @{
    valid=$result.valid;timed_out=$result.timed_out
    sync_invalid=$result.sync_invalid;attempt_count=$attempt
    passive_attempt_count=$passiveAttempt
  }
  Add-LiveProgressRecord -Event 'data_plane_readiness_result' -Details @{
    valid=$result.valid;timed_out=$result.timed_out
    sync_invalid=$result.sync_invalid;attempt_count=$attempt
    passive_attempt_count=$passiveAttempt;fixture_write_count=0
  }
  return $result
}

function Invoke-PreBaselineBacklogDrainGate {
  param(
    [Parameter(Mandatory = $true)][double]$GateStartedElapsedMs,
    [Parameter(Mandatory = $true)][int]$TimeoutSeconds,
    [Parameter(Mandatory = $true)][int]$SnapshotTimeoutSeconds,
    [Parameter(Mandatory = $true)]$GroundParser,
    [Parameter(Mandatory = $true)]$VehicleSerial,
    [Parameter(Mandatory = $true)]$VehicleState,
    [Parameter(Mandatory = $true)]$GroundSerial,
    [Parameter(Mandatory = $true)]$GroundState,
    [Parameter(Mandatory = $true)][byte[]]$VehicleCommand,
    [Parameter(Mandatory = $true)][byte[]]$GroundCommand,
    [Parameter(Mandatory = $true)]$InitialVehicleSnapshot,
    [AllowNull()]$InitialGroundSnapshot = $null,
    [Nullable[double]]$AbsoluteDeadlineElapsedMs = $null
  )
  [double]$computedDeadlineElapsedMs = $GateStartedElapsedMs +
      ([double]$TimeoutSeconds * 1000.0)
  [double]$deadlineElapsedMs = if ($null -ne $AbsoluteDeadlineElapsedMs) {
    [double]$AbsoluteDeadlineElapsedMs
  } else { $computedDeadlineElapsedMs }
  [string]$deadlineSource = if ($null -ne $AbsoluteDeadlineElapsedMs) {
    'caller_absolute_deadline'
  } else { 'gate_start_plus_timeout' }
  $observations = New-Object 'System.Collections.Generic.List[object]'
  $stablePairs = New-Object 'System.Collections.Generic.List[object]'
  $recoveries = New-Object 'System.Collections.Generic.List[object]'
  $failedRecoveries = New-Object 'System.Collections.Generic.List[object]'
  $failedSnapshots = New-Object 'System.Collections.Generic.List[object]'
  $previousObservation = $null
  $lastVehicleSnapshot = $InitialVehicleSnapshot
  $lastGroundSnapshot = $InitialGroundSnapshot
  [bool]$valid = $false
  [bool]$timedOut = $false
  [bool]$syncInvalid = $false
  [bool]$vehicleRecoveryUsed = $false
  [bool]$groundRecoveryUsed = $false
  $vehicleSyncInvalid = [pscustomobject][ordered]@{
    latched=$false;role='vehicle';stage=$null;failure=$null
    response=$null;matcher_at_latch=$null
  }
  $groundSyncInvalid = [pscustomobject][ordered]@{
    latched=$false;role='ground';stage=$null;failure=$null
    response=$null;matcher_at_latch=$null
  }
  [int]$attempt = 0
  [void](Set-ReaderCaptureContext -Phase 'prebaseline_backlog_drain')
  $script:CurrentPhase = 'prebaseline_backlog_drain'
  Add-TimelineEvent -Name 'backlog_drain_started' -Details @{
    gate_started_elapsed_ms=[Math]::Round($GateStartedElapsedMs,3)
    deadline_elapsed_ms=[Math]::Round($deadlineElapsedMs,3)
    timeout_seconds=$TimeoutSeconds;fixture_write_count=0
  }
  Add-LiveProgressRecord -Event 'backlog_drain_started' -Details @{
    gate_started_elapsed_ms=[Math]::Round($GateStartedElapsedMs,3)
    deadline_elapsed_ms=[Math]::Round($deadlineElapsedMs,3)
    timeout_seconds=$TimeoutSeconds;fixture_write_count=0
  }
  try {
    $GroundParser.Enabled = $false
    Reset-MavlinkAnalysis -Parser $GroundParser
    while (-not $valid) {
      [double]$groundReserveMs = [double]$SnapshotTimeoutSeconds * 1000.0
      ++$attempt
      [Nullable[uint32]]$expectedVehicleQ = $null
      if ($null -ne $lastVehicleSnapshot -and
          $lastVehicleSnapshot.status -eq 'COMPLETE') {
        $expectedVehicleQ = Get-NextQueryId -Current `
            ([uint32]$lastVehicleSnapshot.q_uint32)
      }
      $vehicleRecovery = Invoke-BacklogSnapshotWithRecovery `
          -Name ('backlog_drain_vehicle_{0}' -f $attempt) `
          -Role 'vehicle' `
          -Serial $VehicleSerial -State $VehicleState -Command $VehicleCommand `
          -SnapshotTimeoutSeconds $SnapshotTimeoutSeconds `
          -ExpectedQ $expectedVehicleQ `
          -PreviousSnapshot $lastVehicleSnapshot `
          -DeadlineElapsedMs $deadlineElapsedMs `
          -ReserveAfterMs $groundReserveMs -MaxAttempts 3 `
          -RecoveryAlreadyUsed $vehicleRecoveryUsed `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState
      if (-not $vehicleRecovery.valid) {
        $failedRecoveries.Add($vehicleRecovery)
        $lastVehicleSnapshot = Select-LatestCompleteDiagnosticSnapshot `
            -CurrentSnapshot $lastVehicleSnapshot `
            -CandidateSnapshot $vehicleRecovery.latest_complete_snapshot
        if ($null -ne $vehicleRecovery.snapshot) {
          $failedSnapshots.Add($vehicleRecovery.snapshot)
        }
        $vehicleSyncInvalid = New-ReadinessSyncInvalidLatch `
            -Role 'vehicle' -Stage 'backlog_drain' `
            -Failure ([string]$vehicleRecovery.reason) `
            -Response $vehicleRecovery.response `
            -MatcherSnapshot $vehicleRecovery.matcher_at_failure
        $syncInvalid = $true
        $timedOut = ([string]$vehicleRecovery.reason -ceq
            'shared_deadline_exhausted')
        break
      }
      $vehicleSnapshot = $vehicleRecovery.snapshot
      if ($vehicleRecovery.recovered) {
        $vehicleRecoveryUsed = $true
        $recoveries.Add($vehicleRecovery)
        $lastVehicleSnapshot = $vehicleSnapshot
        $previousObservation = $null
        Add-TimelineEvent -Name 'backlog_diagnostic_recovery_result' `
            -Details @{role='vehicle';valid=$true;fixture_write_count=0}
        Add-LiveProgressRecord -Event 'backlog_diagnostic_recovery_result' `
            -Details @{role='vehicle';valid=$true;fixture_write_count=0}
        continue
      }

      [Nullable[uint32]]$expectedGroundQ = $null
      if ($null -ne $lastGroundSnapshot -and
          $lastGroundSnapshot.status -eq 'COMPLETE') {
        $expectedGroundQ = Get-NextQueryId -Current `
            ([uint32]$lastGroundSnapshot.q_uint32)
      }
      $groundRecovery = Invoke-BacklogSnapshotWithRecovery `
          -Name ('backlog_drain_ground_{0}' -f $attempt) `
          -Role 'ground' `
          -Serial $GroundSerial -State $GroundState -Command $GroundCommand `
          -SnapshotTimeoutSeconds $SnapshotTimeoutSeconds `
          -ExpectedQ $expectedGroundQ `
          -PreviousSnapshot $lastGroundSnapshot `
          -DeadlineElapsedMs $deadlineElapsedMs -ReserveAfterMs 0.0 `
          -MaxAttempts 3 -RecoveryAlreadyUsed $groundRecoveryUsed `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState
      if (-not $groundRecovery.valid) {
        $failedRecoveries.Add($groundRecovery)
        $lastGroundSnapshot = Select-LatestCompleteDiagnosticSnapshot `
            -CurrentSnapshot $lastGroundSnapshot `
            -CandidateSnapshot $groundRecovery.latest_complete_snapshot
        if ($null -ne $groundRecovery.snapshot) {
          $failedSnapshots.Add($groundRecovery.snapshot)
        }
        $groundSyncInvalid = New-ReadinessSyncInvalidLatch `
            -Role 'ground' -Stage 'backlog_drain' `
            -Failure ([string]$groundRecovery.reason) `
            -Response $groundRecovery.response `
            -MatcherSnapshot $groundRecovery.matcher_at_failure
        $syncInvalid = $true
        $timedOut = ([string]$groundRecovery.reason -ceq
            'shared_deadline_exhausted')
        break
      }
      $groundSnapshot = $groundRecovery.snapshot
      if ($groundRecovery.recovered) {
        $groundRecoveryUsed = $true
        $recoveries.Add($groundRecovery)
        $lastVehicleSnapshot = $vehicleSnapshot
        $lastGroundSnapshot = $groundSnapshot
        $previousObservation = $null
        Add-TimelineEvent -Name 'backlog_diagnostic_recovery_result' `
            -Details @{role='ground';valid=$true;fixture_write_count=0}
        Add-LiveProgressRecord -Event 'backlog_diagnostic_recovery_result' `
            -Details @{role='ground';valid=$true;fixture_write_count=0}
        continue
      }
      [double]$observedElapsedMs =
          $script:RunWatch.Elapsed.TotalMilliseconds
      $observation = Test-BacklogDrainObservation `
          -GroundSnapshot $groundSnapshot -VehicleSnapshot $vehicleSnapshot `
          -ObservedElapsedMs $observedElapsedMs
      $observations.Add($observation)
      $stablePair = $null
      if ($null -ne $previousObservation) {
        $stablePair = Test-BacklogDrainStablePair `
            -FirstObservation $previousObservation `
            -SecondObservation $observation
        $stablePairs.Add($stablePair)
        if ($stablePair.valid) { $valid = $true }
      }
      $previousObservation = $observation
      $lastVehicleSnapshot = $vehicleSnapshot
      $lastGroundSnapshot = $groundSnapshot
      $VehicleState.RawStream.Flush($true)
      $GroundState.RawStream.Flush($true)
      [string[]]$failedCheckNames = @(
        $observation.baseline_setup.checks | Where-Object {-not $_.valid} |
          ForEach-Object {[string]$_.name})
      $d722 = Get-SnapshotUInt64 -Snapshot $vehicleSnapshot -Key 'd722'
      $rf22 = Get-SnapshotUInt64 -Snapshot $groundSnapshot -Key 'rf22'
      $rfdmbuf = Get-SnapshotUInt64 -Snapshot $groundSnapshot -Key 'rfdmbuf'
      $rfdmesc = Get-SnapshotUInt64 -Snapshot $groundSnapshot -Key 'rfdmesc'
      $pgq = Get-SnapshotUInt64 -Snapshot $vehicleSnapshot -Key 'pgq'
      $pga = Get-SnapshotUInt64 -Snapshot $vehicleSnapshot -Key 'pga'
      Add-TimelineEvent -Name 'backlog_drain_observation' -Details @{
        attempt=$attempt;observation_valid=$observation.valid
        stable_pair_valid=($null -ne $stablePair -and $stablePair.valid)
        failed_check_names=$failedCheckNames
        d722=$d722.value;rf22=$rf22.value
        rfdmbuf=$rfdmbuf.value;rfdmesc=$rfdmesc.value
        pgq=$pgq.value;pga=$pga.value
      }
      Add-LiveProgressRecord -Event 'backlog_drain_progress' -Details @{
        attempt=$attempt;observation_valid=$observation.valid
        stable_pair_valid=($null -ne $stablePair -and $stablePair.valid)
        failed_check_names=$failedCheckNames
        d722=$d722.value;rf22=$rf22.value
        rfdmbuf=$rfdmbuf.value;rfdmesc=$rfdmesc.value
        pgq=$pgq.value;pga=$pga.value
        gate_elapsed_s=[Math]::Round(
          ($observedElapsedMs-$GateStartedElapsedMs)/1000,3)
        fixture_write_count=0
      }
      if ($valid) { break }
      $passiveCapture = Invoke-CaptureInterval -Milliseconds 5000 `
          -Phase ('backlog_drain_passive_{0}' -f $attempt) `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState `
          -AbsoluteDeadlineElapsedMs $deadlineElapsedMs -PassThru
      if (-not $passiveCapture.completed_duration) {
        $timedOut = $true; break
      }
    }
  } finally {
    $GroundParser.Enabled = $false
    Reset-MavlinkAnalysis -Parser $GroundParser
    $VehicleState.RawStream.Flush($true)
    $GroundState.RawStream.Flush($true)
  }
  $result = [pscustomobject][ordered]@{
    schema_version=1;valid=$valid;timed_out=($timedOut -and -not $valid)
    sync_invalid=($syncInvalid -and -not $valid)
    gate_started_elapsed_ms=[Math]::Round($GateStartedElapsedMs,3)
    gate_finished_elapsed_ms=[Math]::Round(
      $script:RunWatch.Elapsed.TotalMilliseconds,3)
    deadline_elapsed_ms=[Math]::Round($deadlineElapsedMs,3)
    computed_deadline_elapsed_ms=[Math]::Round($computedDeadlineElapsedMs,3)
    deadline_source=$deadlineSource;deadline_extended=$false
    timeout_seconds=$TimeoutSeconds;required_stable_observation_count=2
    minimum_passive_separation_ms=5000;attempt_count=$attempt
    observations=$observations.ToArray();stable_pairs=$stablePairs.ToArray()
    recovery_limit_per_role=1
    recovery_count=$recoveries.Count;recoveries=$recoveries.ToArray()
    failed_recoveries=$failedRecoveries.ToArray()
    failed_snapshots=$failedSnapshots.ToArray()
    vehicle_sync_invalid=$vehicleSyncInvalid
    ground_sync_invalid=$groundSyncInvalid
    last_vehicle_snapshot=$lastVehicleSnapshot
    last_ground_snapshot=$lastGroundSnapshot
    ground_parser_disabled_and_reset=$true;fixture_write_count=0
  }
  Add-TimelineEvent -Name 'backlog_drain_result' -Details @{
    valid=$result.valid;timed_out=$result.timed_out
    sync_invalid=$result.sync_invalid;attempt_count=$attempt
  }
  Add-LiveProgressRecord -Event 'backlog_drain_result' -Details @{
    valid=$result.valid;timed_out=$result.timed_out
    sync_invalid=$result.sync_invalid;attempt_count=$attempt
    fixture_write_count=0
  }
  return $result
}

function Invoke-OfficialBaselineGate {
  param(
    [Parameter(Mandatory = $true)][double]$DeadlineElapsedMs,
    [Parameter(Mandatory = $true)][int]$SnapshotTimeoutSeconds,
    [Parameter(Mandatory = $true)]$GroundParser,
    [Parameter(Mandatory = $true)]$VehicleSerial,
    [Parameter(Mandatory = $true)]$VehicleState,
    [Parameter(Mandatory = $true)]$GroundSerial,
    [Parameter(Mandatory = $true)]$GroundState,
    [Parameter(Mandatory = $true)][byte[]]$VehicleCommand,
    [Parameter(Mandatory = $true)][byte[]]$GroundCommand,
    [Parameter(Mandatory = $true)]$InitialVehicleSnapshot,
    [Parameter(Mandatory = $true)]$InitialGroundSnapshot,
    [ValidateRange(1,3)][int]$MaxAttempts = 3
  )
  [double]$gateStartedElapsedMs =
      $script:RunWatch.Elapsed.TotalMilliseconds
  $attempts = New-Object 'System.Collections.Generic.List[object]'
  $previousVehicleSnapshot = $InitialVehicleSnapshot
  $previousGroundSnapshot = $InitialGroundSnapshot
  $finalVehicleSnapshot = $null
  $finalGroundSnapshot = $null
  $baselineSetup = $null
  [bool]$valid = $false
  [bool]$timedOut = $false
  [bool]$syncInvalid = $false
  [bool]$retryExhausted = $false
  [int]$attempt = 0
  [int]$retryCount = 0
  [Nullable[int]]$selectedAttempt = $null
  [string]$failureReason = 'not_run'
  $vehicleSyncInvalid = [pscustomobject][ordered]@{
    latched=$false;role='vehicle';stage=$null;failure=$null
    response=$null;matcher_at_latch=$null
  }
  $groundSyncInvalid = [pscustomobject][ordered]@{
    latched=$false;role='ground';stage=$null;failure=$null
    response=$null;matcher_at_latch=$null
  }
  [void](Set-ReaderCaptureContext -Phase 'official_baseline_pair')
  $script:CurrentPhase = 'official_baseline_pair'
  try {
    $GroundParser.Enabled = $false
    Reset-MavlinkAnalysis -Parser $GroundParser
    while (-not $valid -and $attempt -lt $MaxAttempts) {
      [double]$attemptStartedElapsedMs =
          $script:RunWatch.Elapsed.TotalMilliseconds
      [double]$groundReserveMs =
          [double]$SnapshotTimeoutSeconds * 1000.0
      $vehicleBudget = Get-DeadlineBoundSnapshotBudget `
          -CurrentElapsedMs $attemptStartedElapsedMs `
          -DeadlineElapsedMs $DeadlineElapsedMs `
          -ConfiguredTimeoutSeconds $SnapshotTimeoutSeconds `
          -ReserveAfterMs $groundReserveMs
      if (-not $vehicleBudget.can_query) {
        $timedOut = $true;$failureReason = 'shared_deadline_before_pair'
        break
      }
      ++$attempt
      [uint32]$expectedVehicleQ = Get-NextQueryId -Current `
          ([uint32]$previousVehicleSnapshot.q_uint32)
      [uint32]$expectedGroundQ = Get-NextQueryId -Current `
          ([uint32]$previousGroundSnapshot.q_uint32)
      [string]$vehicleName = if ($attempt -eq 1) {
        'baseline_vehicle'
      } else { 'baseline_vehicle_retry_{0}' -f $attempt }
      [string]$groundName = if ($attempt -eq 1) {
        'baseline_ground'
      } else { 'baseline_ground_retry_{0}' -f $attempt }
      $vehicleSnapshot = Invoke-SnapshotQuery -Name $vehicleName `
          -Serial $VehicleSerial -State $VehicleState -Command $VehicleCommand `
          -TimeoutSeconds $SnapshotTimeoutSeconds `
          -ExpectedQ $expectedVehicleQ `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState `
          -AbsoluteDeadlineElapsedMs $vehicleBudget.query_deadline_elapsed_ms
      $finalVehicleSnapshot = $vehicleSnapshot
      $vehicleResponse = Test-ReadinessSnapshotResponse `
          -Snapshot $vehicleSnapshot -ExpectedQ $expectedVehicleQ
      if (-not $vehicleResponse.valid) {
        $syncInvalid = $true
        $failureReason = 'vehicle_snapshot_invalid'
        $vehicleSyncInvalid = New-ReadinessSyncInvalidLatch `
            -Role 'vehicle' -Stage ('baseline_attempt_{0}' -f $attempt) `
            -Failure $failureReason -Response $vehicleResponse `
            -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $VehicleState)
        $attempts.Add([pscustomobject][ordered]@{
          attempt=$attempt;started_elapsed_ms=$attemptStartedElapsedMs
          finished_elapsed_ms=$script:RunWatch.Elapsed.TotalMilliseconds
          deadline_elapsed_ms=$DeadlineElapsedMs
          expected_vehicle_q=$expectedVehicleQ
          expected_ground_q=$expectedGroundQ
          vehicle_response=$vehicleResponse;ground_response=$null
          vehicle_snapshot=$vehicleSnapshot;ground_snapshot=$null
          baseline_setup=$null;disposition=$null
        })
        break
      }

      $groundBudget = Get-DeadlineBoundSnapshotBudget `
          -CurrentElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -DeadlineElapsedMs $DeadlineElapsedMs `
          -ConfiguredTimeoutSeconds $SnapshotTimeoutSeconds `
          -ReserveAfterMs 0.0
      if (-not $groundBudget.can_query) {
        $timedOut = $true;$failureReason = 'shared_deadline_before_ground'
        $attempts.Add([pscustomobject][ordered]@{
          attempt=$attempt;started_elapsed_ms=$attemptStartedElapsedMs
          finished_elapsed_ms=$script:RunWatch.Elapsed.TotalMilliseconds
          deadline_elapsed_ms=$DeadlineElapsedMs
          expected_vehicle_q=$expectedVehicleQ
          expected_ground_q=$expectedGroundQ
          vehicle_response=$vehicleResponse;ground_response=$null
          vehicle_snapshot=$vehicleSnapshot;ground_snapshot=$null
          baseline_setup=$null;disposition=$null
        })
        break
      }
      $groundSnapshot = Invoke-SnapshotQuery -Name $groundName `
          -Serial $GroundSerial -State $GroundState -Command $GroundCommand `
          -TimeoutSeconds $SnapshotTimeoutSeconds `
          -ExpectedQ $expectedGroundQ `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState `
          -AbsoluteDeadlineElapsedMs $groundBudget.query_deadline_elapsed_ms
      $finalGroundSnapshot = $groundSnapshot
      $groundResponse = Test-ReadinessSnapshotResponse `
          -Snapshot $groundSnapshot -ExpectedQ $expectedGroundQ
      if (-not $groundResponse.valid) {
        $syncInvalid = $true
        $failureReason = 'ground_snapshot_invalid'
        $groundSyncInvalid = New-ReadinessSyncInvalidLatch `
            -Role 'ground' -Stage ('baseline_attempt_{0}' -f $attempt) `
            -Failure $failureReason -Response $groundResponse `
            -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $GroundState)
        $attempts.Add([pscustomobject][ordered]@{
          attempt=$attempt;started_elapsed_ms=$attemptStartedElapsedMs
          finished_elapsed_ms=$script:RunWatch.Elapsed.TotalMilliseconds
          deadline_elapsed_ms=$DeadlineElapsedMs
          expected_vehicle_q=$expectedVehicleQ
          expected_ground_q=$expectedGroundQ
          vehicle_response=$vehicleResponse;ground_response=$groundResponse
          vehicle_snapshot=$vehicleSnapshot;ground_snapshot=$groundSnapshot
          baseline_setup=$null;disposition=$null
        })
        break
      }

      $baselineSetup = Test-BaselineSetup `
          -GroundSnapshot $groundSnapshot `
          -VehicleSnapshot $vehicleSnapshot `
          -PreviousGroundSnapshot $previousGroundSnapshot `
          -PreviousVehicleSnapshot $previousVehicleSnapshot
      $nextPairBudget = Get-DeadlineBoundSnapshotBudget `
          -CurrentElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
          -DeadlineElapsedMs $DeadlineElapsedMs `
          -ConfiguredTimeoutSeconds $SnapshotTimeoutSeconds `
          -ReserveAfterMs $groundReserveMs
      $disposition = Get-BaselineAttemptDisposition `
          -BaselineSetup $baselineSetup -AttemptNumber $attempt `
          -MaxAttempts $MaxAttempts `
          -RetryBudgetAvailable ([bool]$nextPairBudget.can_query)
      [double]$attemptFinishedElapsedMs =
          $script:RunWatch.Elapsed.TotalMilliseconds
      $attempts.Add([pscustomobject][ordered]@{
        attempt=$attempt;started_elapsed_ms=$attemptStartedElapsedMs
        finished_elapsed_ms=$attemptFinishedElapsedMs
        deadline_elapsed_ms=$DeadlineElapsedMs
        expected_vehicle_q=$expectedVehicleQ;expected_ground_q=$expectedGroundQ
        vehicle_response=$vehicleResponse;ground_response=$groundResponse
        vehicle_snapshot=$vehicleSnapshot;ground_snapshot=$groundSnapshot
        baseline_setup=$baselineSetup;disposition=$disposition
      })
      Add-TimelineEvent -Name 'baseline_pair_attempt' -Details @{
        attempt=$attempt;action=$disposition.action;reason=$disposition.reason
        d722=(Get-SnapshotUInt64 -Snapshot $vehicleSnapshot -Key 'd722').value
        rf22=(Get-SnapshotUInt64 -Snapshot $groundSnapshot -Key 'rf22').value
        fixture_write_count=0
      }
      $previousVehicleSnapshot = $vehicleSnapshot
      $previousGroundSnapshot = $groundSnapshot
      $VehicleState.RawStream.Flush($true)
      $GroundState.RawStream.Flush($true)
      if ($disposition.action -ceq 'ACCEPT') {
        $valid = $true;$selectedAttempt = $attempt
        $failureReason = $null
        break
      }
      if ($disposition.action -ceq 'RETRY') {
        ++$retryCount
        continue
      }
      $retryExhausted = [bool]$disposition.retry_exhausted
      $timedOut = ($disposition.reason -ceq 'shared_deadline_exhausted')
      $failureReason = [string]$disposition.reason
      break
    }
  } finally {
    $GroundParser.Enabled = $false
    Reset-MavlinkAnalysis -Parser $GroundParser
    $VehicleState.RawStream.Flush($true)
    $GroundState.RawStream.Flush($true)
  }
  return [pscustomobject][ordered]@{
    schema_version=1;valid=$valid;status=if($valid){'PASS'}else{'FAIL'}
    failure_reason=$failureReason
    timed_out=($timedOut -and -not $valid)
    sync_invalid=($syncInvalid -and -not $valid)
    retry_exhausted=($retryExhausted -and -not $valid)
    deadline_source='backlog_drain_gate.deadline_elapsed_ms'
    deadline_extended=$false
    gate_started_elapsed_ms=[Math]::Round($gateStartedElapsedMs,3)
    gate_finished_elapsed_ms=[Math]::Round(
      $script:RunWatch.Elapsed.TotalMilliseconds,3)
    deadline_elapsed_ms=[Math]::Round($DeadlineElapsedMs,3)
    max_attempts=$MaxAttempts;attempt_count=$attempt;retry_count=$retryCount
    selected_attempt=$selectedAttempt;fixture_write_count=0
    attempts=$attempts.ToArray()
    final_vehicle_snapshot=$finalVehicleSnapshot
    final_ground_snapshot=$finalGroundSnapshot
    baseline_setup=$baselineSetup
    vehicle_sync_invalid=$vehicleSyncInvalid
    ground_sync_invalid=$groundSyncInvalid
    ground_parser_disabled_and_reset=$true
  }
}

function Invoke-OfficialPreRequestGate {
  param(
    [Parameter(Mandatory = $true)][double]$DeadlineElapsedMs,
    [Parameter(Mandatory = $true)][int]$SnapshotTimeoutSeconds,
    [Parameter(Mandatory = $true)][int]$BacklogDrainTimeoutSeconds,
    [Parameter(Mandatory = $true)]$GroundParser,
    [Parameter(Mandatory = $true)]$VehicleSerial,
    [Parameter(Mandatory = $true)]$VehicleState,
    [Parameter(Mandatory = $true)]$GroundSerial,
    [Parameter(Mandatory = $true)]$GroundState,
    [Parameter(Mandatory = $true)][byte[]]$VehicleCommand,
    [Parameter(Mandatory = $true)][byte[]]$GroundCommand,
    [Parameter(Mandatory = $true)]$InitialVehicleSnapshot,
    [Parameter(Mandatory = $true)]$InitialGroundSnapshot,
    [Parameter(Mandatory = $true)][AllowEmptyCollection()]
      [object[]]$ReadinessParamValueEvents,
    [ValidateRange(1,3)][int]$MaxAttempts = 3
  )
  $attempts = New-Object 'System.Collections.Generic.List[object]'
  $officialVehicle = $InitialVehicleSnapshot
  $officialGround = $InitialGroundSnapshot
  $finalVehicleSnapshot = $officialVehicle
  $finalGroundSnapshot = $officialGround
  $latestCompleteVehicleSnapshot = $officialVehicle
  $preRequestVehicle = $null
  $preRequestVehicleGate = $null
  $causalGate = $null
  $m0 = $null
  $finalDisposition = $null
  $recoveryBacklogGate = $null
  $recoveryBaselineGate = $null
  $recoveryPairPromotion = $null
  $preM0TailEvidence = $null
  $m0Capture = $null
  $postM0DiagnosticEndBarrier = $null
  [bool]$skipNextRecoveryCapture = $false
  [bool]$valid = $false
  [bool]$timedOut = $false
  [bool]$syncInvalid = $false
  [bool]$retryExhausted = $false
  [int]$retryCount = 0
  [int]$attempt = 0
  [int]$dedicatedExtraRetryLimit = 1
  [int]$isolatedPartialD7ExtraRetryLimit = $dedicatedExtraRetryLimit
  [int]$isolatedPartialD7ExtraRetryUsed = 0
  [bool]$isolatedPartialD7ExtraAttemptArmed = $false
  [int]$exactObservedStatRuntimeExtraRetryLimit = $dedicatedExtraRetryLimit
  [int]$exactObservedStatRuntimeExtraRetryUsed = 0
  [bool]$exactObservedStatRuntimeExtraAttemptArmed = $false
  [bool]$dedicatedExtraAttemptExecuted = $false
  [string]$executedDedicatedExtraAttemptKind = 'NONE'
  [int]$totalAttemptLimit = $MaxAttempts + $dedicatedExtraRetryLimit
  [string]$failureReason = 'not_run'
  $vehicleSyncInvalid = [pscustomobject][ordered]@{
    latched=$false;role='vehicle';stage=$null;failure=$null
    response=$null;matcher_at_latch=$null
  }
  $groundSyncInvalid = [pscustomobject][ordered]@{
    latched=$false;role='ground';stage=$null;failure=$null
    response=$null;matcher_at_latch=$null
  }
  $notRunBacklogEvidence = Test-PreRequestBacklogGate `
      -ReadinessEvents $ReadinessParamValueEvents `
      -M0Events @() -M0EpochCompleted $false

  while ($attempt -lt $totalAttemptLimit -and
      ($attempt -lt $MaxAttempts -or
       $isolatedPartialD7ExtraAttemptArmed -or
       $exactObservedStatRuntimeExtraAttemptArmed) -and -not $valid) {
    [bool]$dedicatedExtraAttempt = $false
    [string]$dedicatedExtraAttemptKind = 'NONE'
    if ($attempt -ge $MaxAttempts) {
      if ($isolatedPartialD7ExtraAttemptArmed -and
          $exactObservedStatRuntimeExtraAttemptArmed) {
        throw 'dedicated extra retry arms must be mutually exclusive'
      }
      if (-not $isolatedPartialD7ExtraAttemptArmed -and
          -not $exactObservedStatRuntimeExtraAttemptArmed) { break }
      $dedicatedExtraAttempt = $true
      $dedicatedExtraAttemptExecuted = $true
      $dedicatedExtraAttemptKind = if (
          $exactObservedStatRuntimeExtraAttemptArmed) {
        'EXACT_WIRE_STAT_RUNTIME'
      } else { 'ISOLATED_PARTIAL_D7' }
      $executedDedicatedExtraAttemptKind = $dedicatedExtraAttemptKind
      # Disarm before attempt 4.  No result from the dedicated attempt can
      # arm attempt 5, including recurrence of either accepted retry shape.
      $isolatedPartialD7ExtraAttemptArmed = $false
      $exactObservedStatRuntimeExtraAttemptArmed = $false
    }
    ++$attempt
    $postM0DiagnosticEndBarrier = $null
    $GroundParser.Enabled = $false
    Reset-MavlinkAnalysis -Parser $GroundParser
    [string]$preM0TailPhase =
        ('pre_request_attempt_{0}_recovery_3s' -f $attempt)
    $preM0TailStartBarrier = Set-ReaderCaptureContext `
        -Phase ('pre_request_attempt_{0}_recovery_3s' -f $attempt) `
        -Epoch $preM0TailPhase
    if ($null -eq $preM0TailStartBarrier) {
      throw 'pre-M0 tail start barrier was not returned by the reader broker'
    }
    [long]$preM0TailStartRawOffset =
        [long]$preM0TailStartBarrier.ground_raw_offset_exclusive
    $GroundParser.ParamList.capture_scope = 'pre_request_readiness'
    if ($skipNextRecoveryCapture) {
      $recoveryCapture = [pscustomobject][ordered]@{
        completed_duration=$true;deadline_reached=$false
        requested_milliseconds=0;captured_milliseconds=0;skipped=$true
        reason='recovery_capture_skipped_after_verified_stable_pair'
        start_barrier=$preM0TailStartBarrier
      }
      Add-TimelineEvent `
          -Name 'recovery_capture_skipped_after_verified_stable_pair' `
          -Details @{attempt=$attempt;fixture_write_count=0}
      Add-LiveProgressRecord `
          -Event 'recovery_capture_skipped_after_verified_stable_pair' `
          -Details @{attempt=$attempt;fixture_write_count=0}
      $skipNextRecoveryCapture = $false
    } else {
      $GroundParser.Enabled = $true
      $recoveryCapture = Invoke-CaptureInterval -Milliseconds 3000 `
          -Phase $preM0TailPhase `
          -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
          -GroundSerial $GroundSerial -GroundState $GroundState `
          -AbsoluteDeadlineElapsedMs $DeadlineElapsedMs -PassThru `
          -StartBarrier $preM0TailStartBarrier
    }
    if (-not $recoveryCapture.completed_duration) {
      $timedOut = $true;$failureReason = 'shared_deadline_exhausted'
      $GroundParser.Enabled = $false
      Reset-MavlinkAnalysis -Parser $GroundParser
      break
    }
    $preM0TailEndBarrier = Set-ReaderCaptureContext `
        -Phase 'M0_pre_request_clean_5s' -Epoch 'M0_pre_request_clean_5s'
    if ($null -eq $preM0TailEndBarrier) {
      throw 'pre-M0 tail end barrier was not returned by the reader broker'
    }
    [long]$preM0TailEndRawOffset =
        [long]$preM0TailEndBarrier.ground_raw_offset_exclusive
    $GroundParser.Enabled = $false
    $preM0TailIntegrity = Get-ParserIntegrity -Parser $GroundParser
    [object[]]$preM0TailEvents =
        [object[]]$GroundParser.ParamList.events.ToArray()
    [object[]]$preM0TailValidEvents =
        [object[]]$GroundParser.ValidEvents.ToArray()
    [bool]$preM0TailRangeValid = ($preM0TailStartRawOffset -ge 0 -and
        $preM0TailEndRawOffset -ge $preM0TailStartRawOffset -and
        [long]$GroundState.RawBytes -eq $preM0TailEndRawOffset)
    $preM0TailEvidence = [pscustomobject][ordered]@{
      schema_version=1;capture_scope='pre_request_readiness'
      producer_phase=$preM0TailPhase;producer_epoch=$preM0TailPhase
      requested_milliseconds=3000;capture=$recoveryCapture
      completed_duration=[bool]$recoveryCapture.completed_duration
      raw_start_offset=$preM0TailStartRawOffset
      raw_end_offset=$preM0TailEndRawOffset
      raw_length_bytes=if($preM0TailRangeValid){
        [long]($preM0TailEndRawOffset - $preM0TailStartRawOffset)
      }else{$null}
      ground_raw_offset=[long]$preM0TailEndRawOffset
      start_barrier=$preM0TailStartBarrier;end_barrier=$preM0TailEndBarrier
      integrity=$preM0TailIntegrity;events=$preM0TailEvents
      valid_events=$preM0TailValidEvents
      valid=($preM0TailRangeValid -and $preM0TailIntegrity.valid -and
        -not [bool]$recoveryCapture.skipped -and
        [int]$recoveryCapture.requested_milliseconds -eq 3000 -and
        [bool]$recoveryCapture.completed_duration)
      fixture_write_count=0
    }
    $script:CurrentPhase = 'M0_pre_request_clean_5s'
    Reset-MavlinkAnalysis -Parser $GroundParser
    $GroundParser.ParamList.capture_scope = 'pre_request_m0'
    $GroundParser.Enabled = $true
    $m0 = [pscustomobject][ordered]@{
      attempt=$attempt
      elapsed_ms=[Math]::Round($script:RunWatch.Elapsed.TotalMilliseconds,3)
      utc=[DateTime]::UtcNow.ToString('o')
      ground_raw_offset=[long]$preM0TailEndRawOffset
    }
    Add-TimelineEvent -Name 'M0' -Details @{attempt=$attempt}
    $m0Capture = Invoke-CaptureInterval -Milliseconds 5000 `
        -Phase 'M0_pre_request_clean_5s' `
        -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
        -GroundSerial $GroundSerial -GroundState $GroundState `
        -AbsoluteDeadlineElapsedMs $DeadlineElapsedMs -PassThru `
        -StartBarrier $preM0TailEndBarrier
    if (-not $m0Capture.completed_duration) {
      $timedOut = $true;$failureReason = 'shared_deadline_exhausted'
      [void](Disable-AndResetMavlinkAnalysis -Parser $GroundParser)
      break
    }
    [uint32]$preRequestVehicleExpectedQ = Get-NextQueryId -Current `
        ([uint32]$officialVehicle.q_uint32)
    $preRequestVehicle = Invoke-SnapshotQuery `
        -Name ('pre_request_vehicle_{0}' -f $attempt) `
        -Serial $VehicleSerial -State $VehicleState `
        -Command $VehicleCommand -TimeoutSeconds $SnapshotTimeoutSeconds `
        -ExpectedQ $preRequestVehicleExpectedQ `
        -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
        -GroundSerial $GroundSerial -GroundState $GroundState `
        -AbsoluteDeadlineElapsedMs $DeadlineElapsedMs
    [void](Invoke-PumpPair -VehicleSerial $VehicleSerial `
        -VehicleState $VehicleState -GroundSerial $GroundSerial `
        -GroundState $GroundState)
    [string]$postM0DiagnosticSealPhase =
        ('pre_request_vehicle_{0}_sealed' -f $attempt)
    $postM0DiagnosticEndBarrier = Set-ReaderCaptureContext `
        -Phase $postM0DiagnosticSealPhase -Epoch $postM0DiagnosticSealPhase
    if ($null -eq $postM0DiagnosticEndBarrier) {
      throw 'post-M0 Vehicle diagnostic end barrier was not returned by the reader broker'
    }
    [double]$m0GateEndElapsedMs =
        $script:RunWatch.Elapsed.TotalMilliseconds
    $preRequestVehicleGate = Test-PreRequestVehicleGate `
        -OfficialVehicle $officialVehicle -OfficialGround $officialGround `
        -PreRequestVehicle $preRequestVehicle
    $causalGate = Test-M0CausalGate -Parser $GroundParser `
        -M0ElapsedMs ([double]$m0.elapsed_ms) `
        -GateEndElapsedMs $m0GateEndElapsedMs `
        -ReadinessParamValueEvents $ReadinessParamValueEvents `
        -M0GroundRawOffset ([long]$m0.ground_raw_offset) `
        -M0GateEndGroundRawOffset `
          ([long]$preRequestVehicle.capture_start_barrier.ground_raw_offset_exclusive)
    $preResponse = Test-ReadinessSnapshotResponse `
        -Snapshot $preRequestVehicle -ExpectedQ $preRequestVehicleExpectedQ
    $latestCompleteVehicleSnapshot = Select-LatestCompleteDiagnosticSnapshot `
        -CurrentSnapshot $latestCompleteVehicleSnapshot `
        -CandidateSnapshot $preRequestVehicle
    [object[]]$M0Events = [object[]]$GroundParser.ParamList.events.ToArray()
    if (-not $preResponse.valid) {
      $vehicleSyncInvalid = New-ReadinessSyncInvalidLatch `
          -Role 'vehicle' -Stage ('pre_request_attempt_{0}' -f $attempt) `
          -Failure 'pre_request_vehicle_snapshot_invalid' `
          -Response $preResponse `
          -MatcherSnapshot (Get-CaptureMatcherSnapshot -State $VehicleState)
      if (-not [bool]$vehicleSyncInvalid.latched) {
        throw 'pre-request synchronization-invalid latch was not retained'
      }
      $syncInvalid = $true
      $failureReason = 'pre_request_vehicle_snapshot_invalid'
      $finalDisposition = [pscustomobject][ordered]@{
        action='REJECT';reason=$failureReason;attempt_number=$attempt
        max_attempts=$MaxAttempts;retry_eligible=$false
        retry_exhausted=$false;fixture_write_count=0
      }
      $attemptRecord = [pscustomobject][ordered]@{
        attempt=$attempt;m0=$m0;m0_capture=$m0Capture;m0_events=$M0Events
        dedicated_extra_attempt=$dedicatedExtraAttempt
        pre_m0_tail_evidence=$preM0TailEvidence
        post_m0_diagnostic_end_barrier=$postM0DiagnosticEndBarrier
        pre_request_vehicle=$preRequestVehicle
        pre_request_vehicle_gate=$preRequestVehicleGate
        causal_gate=$causalGate;disposition=$finalDisposition
        recovery_backlog_gate=$null;recovery_baseline_gate=$null
        recovery_pair_promotion=$null
        deadline_elapsed_ms=$DeadlineElapsedMs;fixture_write_count=0
      }
      $attempts.Add($attemptRecord)
      Add-TimelineEvent -Name 'pre_request_gate_attempt' -Details @{
        attempt=$attempt;action='REJECT';reason=$failureReason
        sync_invalid=$true;dedicated_extra_attempt=$dedicatedExtraAttempt
        fixture_write_count=0
      }
      Add-LiveProgressRecord -Event 'pre_request_gate_attempt' -Details @{
        attempt=$attempt;action='REJECT';reason=$failureReason
        sync_invalid=$true;dedicated_extra_attempt=$dedicatedExtraAttempt
        fixture_write_count=0
      }
      [void](Disable-AndResetMavlinkAnalysis -Parser $GroundParser)
      break
    }
    $retryBudget = Get-DeadlineBoundSnapshotBudget `
        -CurrentElapsedMs $script:RunWatch.Elapsed.TotalMilliseconds `
        -DeadlineElapsedMs $DeadlineElapsedMs `
        -ConfiguredTimeoutSeconds $SnapshotTimeoutSeconds -ReserveAfterMs 0.0
    [int]$dedicatedExtraRetryUsed = (
        $isolatedPartialD7ExtraRetryUsed +
        $exactObservedStatRuntimeExtraRetryUsed)
    [bool]$dedicatedExtraRetryAvailable = (
        -not $dedicatedExtraAttempt -and $attempt -eq $MaxAttempts -and
        $dedicatedExtraRetryUsed -lt $dedicatedExtraRetryLimit -and
        -not $isolatedPartialD7ExtraAttemptArmed -and
        -not $exactObservedStatRuntimeExtraAttemptArmed)
    [bool]$isolatedPartialD7ExtraRetryAvailable =
        $dedicatedExtraRetryAvailable
    [bool]$exactObservedStatRuntimeExtraRetryAvailable =
        $dedicatedExtraRetryAvailable
    $finalDisposition = Get-PreRequestAttemptDisposition `
        -CausalGate $causalGate `
        -PreRequestVehicleGate $preRequestVehicleGate `
        -OfficialVehicle $officialVehicle `
        -OfficialGround $officialGround `
        -PreRequestVehicle $preRequestVehicle -M0Events $M0Events `
        -PreM0TailEvidence $preM0TailEvidence `
        -M0Capture $m0Capture `
        -DiagnosticEndBarrier $postM0DiagnosticEndBarrier `
        -M0GroundRawOffset ([long]$m0.ground_raw_offset) `
        -M0GateEndGroundRawOffset `
          ([long]$preRequestVehicle.capture_start_barrier.ground_raw_offset_exclusive) `
        -AttemptNumber $attempt -MaxAttempts $MaxAttempts `
        -RetryBudgetAvailable ([bool]$retryBudget.can_query) `
        -IsolatedPartialD7ExtraRetryAvailable `
          $isolatedPartialD7ExtraRetryAvailable `
        -ExactObservedStatRuntimeExtraRetryAvailable `
          $exactObservedStatRuntimeExtraRetryAvailable
    $attemptRecord = [pscustomobject][ordered]@{
      attempt=$attempt;m0=$m0;m0_capture=$m0Capture;m0_events=$M0Events
      dedicated_extra_attempt=$dedicatedExtraAttempt
      dedicated_extra_attempt_kind=$dedicatedExtraAttemptKind
      isolated_partial_d7_extra_retry_available=
          $isolatedPartialD7ExtraRetryAvailable
      exact_observed_stat_runtime_extra_retry_available=
          $exactObservedStatRuntimeExtraRetryAvailable
      pre_m0_tail_evidence=$preM0TailEvidence
      post_m0_diagnostic_end_barrier=$postM0DiagnosticEndBarrier
      pre_request_vehicle=$preRequestVehicle
      pre_request_vehicle_gate=$preRequestVehicleGate
      causal_gate=$causalGate;disposition=$finalDisposition
      recovery_backlog_gate=$null;recovery_baseline_gate=$null
      recovery_pair_promotion=$null
      deadline_elapsed_ms=$DeadlineElapsedMs;fixture_write_count=0
    }
    $attempts.Add($attemptRecord)
    Add-TimelineEvent -Name 'pre_request_gate_attempt' -Details @{
      attempt=$attempt;action=$finalDisposition.action
      reason=$finalDisposition.reason;fixture_write_count=0
    }
    Add-LiveProgressRecord -Event 'pre_request_gate_attempt' -Details @{
      attempt=$attempt;action=$finalDisposition.action
      reason=$finalDisposition.reason;fixture_write_count=0
    }
    if ($finalDisposition.action -ceq 'ACCEPT') {
      $valid = $true;$failureReason = $null
      $finalVehicleSnapshot = $preRequestVehicle
      $finalGroundSnapshot = $officialGround
      break
    }
    [bool]$isolatedPartialD7Recovery = (
        $finalDisposition.action -ceq 'RETRY_ISOLATED_D7PB')
    [bool]$exactObservedStatRuntimeRecovery = (
        $finalDisposition.action -ceq 'RETRY_EXACT_STAT_RUNTIME')
    if ($finalDisposition.action -cne 'RETRY' -and
        -not $isolatedPartialD7Recovery -and
        -not $exactObservedStatRuntimeRecovery) {
      $failureReason = [string]$finalDisposition.reason
      $retryExhausted = [bool]$finalDisposition.retry_exhausted
      [void](Disable-AndResetMavlinkAnalysis -Parser $GroundParser)
      break
    }

    if ($isolatedPartialD7Recovery) {
      if ($dedicatedExtraAttempt -or $attempt -ne $MaxAttempts -or
          $dedicatedExtraRetryUsed -ge $dedicatedExtraRetryLimit) {
        throw 'isolated partial D7 extra-retry invariant violated'
      }
    } elseif ($exactObservedStatRuntimeRecovery) {
      if ($dedicatedExtraAttempt -or $attempt -ne $MaxAttempts -or
          $dedicatedExtraRetryUsed -ge $dedicatedExtraRetryLimit -or
          -not [bool]$finalDisposition.exact_known_event -or
          -not [bool]$finalDisposition.exact_observed_stat_runtime_extra_retry_selected) {
        throw 'exact wire STAT_RUNTIME extra-retry invariant violated'
      }
    } else {
      ++$retryCount
    }
    [void](Disable-AndResetMavlinkAnalysis -Parser $GroundParser)
    $recoveryPairPromotion = $null
    [double]$retryDrainStartedElapsedMs =
        $script:RunWatch.Elapsed.TotalMilliseconds
    $recoveryBacklogGate = Invoke-PreBaselineBacklogDrainGate `
        -GateStartedElapsedMs $retryDrainStartedElapsedMs `
        -TimeoutSeconds $BacklogDrainTimeoutSeconds `
        -SnapshotTimeoutSeconds $SnapshotTimeoutSeconds `
        -GroundParser $GroundParser `
        -VehicleSerial $VehicleSerial -VehicleState $VehicleState `
        -GroundSerial $GroundSerial -GroundState $GroundState `
        -VehicleCommand $VehicleCommand -GroundCommand $GroundCommand `
        -InitialVehicleSnapshot $preRequestVehicle `
        -InitialGroundSnapshot $officialGround `
        -AbsoluteDeadlineElapsedMs $DeadlineElapsedMs
    $attemptRecord.recovery_backlog_gate = $recoveryBacklogGate
    $latestCompleteVehicleSnapshot = Select-LatestCompleteDiagnosticSnapshot `
        -CurrentSnapshot $latestCompleteVehicleSnapshot `
        -CandidateSnapshot $recoveryBacklogGate.last_vehicle_snapshot
    $finalVehicleSnapshot = Select-LatestCompleteDiagnosticSnapshot `
        -CurrentSnapshot $finalVehicleSnapshot `
        -CandidateSnapshot $recoveryBacklogGate.last_vehicle_snapshot
    $finalGroundSnapshot = Select-LatestCompleteDiagnosticSnapshot `
        -CurrentSnapshot $finalGroundSnapshot `
        -CandidateSnapshot $recoveryBacklogGate.last_ground_snapshot
    if (-not $recoveryBacklogGate.valid) {
      $failureReason = 'retry_backlog_drain_failed'
      $timedOut = [bool]$recoveryBacklogGate.timed_out
      break
    }
    $recoveryPairPromotion = Test-PreRequestRecoveryBacklogPairPromotion `
        -RecoveryBacklogGate $recoveryBacklogGate `
        -PreviousOfficialVehicle $officialVehicle `
        -PreviousOfficialGround $officialGround
    $attemptRecord.recovery_pair_promotion = $recoveryPairPromotion
    if (-not $recoveryPairPromotion.valid) {
      $failureReason = 'retry_stable_pair_promotion_failed'
      break
    }
    $officialVehicle = $recoveryPairPromotion.selected_vehicle_snapshot
    $officialGround = $recoveryPairPromotion.selected_ground_snapshot
    $finalVehicleSnapshot = $officialVehicle
    $finalGroundSnapshot = $officialGround
    $skipNextRecoveryCapture = $true
    if ($isolatedPartialD7Recovery) {
      ++$isolatedPartialD7ExtraRetryUsed
      $isolatedPartialD7ExtraAttemptArmed = $true
    } elseif ($exactObservedStatRuntimeRecovery) {
      ++$exactObservedStatRuntimeExtraRetryUsed
      $exactObservedStatRuntimeExtraAttemptArmed = $true
    }
    if ($isolatedPartialD7ExtraAttemptArmed -and
        $exactObservedStatRuntimeExtraAttemptArmed) {
      throw 'dedicated extra retry arms must be mutually exclusive'
    }
    Add-TimelineEvent -Name 'retry_stable_pair_promoted' -Details @{
      attempt=$attempt
      recovery_action=$finalDisposition.action
      isolated_partial_d7_extra_attempt_armed=
          $isolatedPartialD7ExtraAttemptArmed
      exact_observed_stat_runtime_extra_attempt_armed=
          $exactObservedStatRuntimeExtraAttemptArmed
      dedicated_extra_attempt_kind=if($isolatedPartialD7Recovery){
        'ISOLATED_PARTIAL_D7'
      }elseif($exactObservedStatRuntimeRecovery){
        'EXACT_WIRE_STAT_RUNTIME'
      }else{'NONE'}
      d722=(Get-SnapshotUInt64 -Snapshot $officialVehicle -Key 'd722').value
      rf22=(Get-SnapshotUInt64 -Snapshot $officialGround -Key 'rf22').value
      fixture_write_count=0
    }
    Add-LiveProgressRecord -Event 'retry_stable_pair_promoted' -Details @{
      attempt=$attempt
      recovery_action=$finalDisposition.action
      isolated_partial_d7_extra_attempt_armed=
          $isolatedPartialD7ExtraAttemptArmed
      exact_observed_stat_runtime_extra_attempt_armed=
          $exactObservedStatRuntimeExtraAttemptArmed
      dedicated_extra_attempt_kind=if($isolatedPartialD7Recovery){
        'ISOLATED_PARTIAL_D7'
      }elseif($exactObservedStatRuntimeRecovery){
        'EXACT_WIRE_STAT_RUNTIME'
      }else{'NONE'}
      d722=(Get-SnapshotUInt64 -Snapshot $officialVehicle -Key 'd722').value
      rf22=(Get-SnapshotUInt64 -Snapshot $officialGround -Key 'rf22').value
      fixture_write_count=0
    }
    continue
  }
  if (-not $valid) { [void](Disable-AndResetMavlinkAnalysis -Parser $GroundParser) }
  $syncInvalid = ($syncInvalid -or ($null -ne $recoveryBacklogGate -and
      [bool]$recoveryBacklogGate.sync_invalid) -or
      ($null -ne $recoveryBaselineGate -and
       [bool]$recoveryBaselineGate.sync_invalid))
  return [pscustomobject][ordered]@{
    schema_version=1;valid=$valid;status=if($valid){'PASS'}else{'FAIL'}
    failure_reason=$failureReason;timed_out=($timedOut -and -not $valid)
    sync_invalid=($syncInvalid -and -not $valid)
    retry_exhausted=($retryExhausted -and -not $valid)
    deadline_source='backlog_drain_gate.deadline_elapsed_ms'
    deadline_elapsed_ms=[Math]::Round($DeadlineElapsedMs,3)
    deadline_extended=$false;max_attempts=$MaxAttempts
    standard_max_attempts=$MaxAttempts;total_attempt_limit=$totalAttemptLimit
    dedicated_extra_retry_limit=$dedicatedExtraRetryLimit
    dedicated_extra_retry_used=(
        $isolatedPartialD7ExtraRetryUsed +
        $exactObservedStatRuntimeExtraRetryUsed)
    dedicated_extra_attempt_kind=$executedDedicatedExtraAttemptKind
    isolated_partial_d7_extra_retry_limit=$isolatedPartialD7ExtraRetryLimit
    isolated_partial_d7_extra_retry_used=$isolatedPartialD7ExtraRetryUsed
    isolated_partial_d7_extra_attempt_armed=$isolatedPartialD7ExtraAttemptArmed
    exact_observed_stat_runtime_extra_retry_limit=
        $exactObservedStatRuntimeExtraRetryLimit
    exact_observed_stat_runtime_extra_retry_used=
        $exactObservedStatRuntimeExtraRetryUsed
    exact_observed_stat_runtime_extra_attempt_armed=
        $exactObservedStatRuntimeExtraAttemptArmed
    dedicated_extra_attempt_executed=$dedicatedExtraAttemptExecuted
    attempt_count=$attempt;retry_count=$retryCount
    fixture_write_count=0;attempts=$attempts.ToArray()
    latest_complete_vehicle_snapshot=$latestCompleteVehicleSnapshot
    final_vehicle_snapshot=$finalVehicleSnapshot
    final_ground_snapshot=$finalGroundSnapshot
    pre_request_vehicle=$preRequestVehicle
    pre_request_vehicle_gate=$preRequestVehicleGate
    causal_gate=$causalGate;m0=$m0;disposition=$finalDisposition
    m0_capture=$m0Capture
    pre_m0_tail_evidence=$preM0TailEvidence
    post_m0_diagnostic_end_barrier=$postM0DiagnosticEndBarrier
    vehicle_sync_invalid=$vehicleSyncInvalid
    ground_sync_invalid=$groundSyncInvalid
    last_recovery_backlog_gate=$recoveryBacklogGate
    last_recovery_baseline_gate=$recoveryBaselineGate
    last_recovery_pair_promotion=$recoveryPairPromotion
    not_run_backlog_evidence=$notRunBacklogEvidence
  }
}

function Test-FooterCloseOrdering {
  param($FooterFsyncElapsedMs, $VehicleCloseElapsedMs, $GroundCloseElapsedMs)
  return ($null -ne $FooterFsyncElapsedMs -and
      $null -ne $VehicleCloseElapsedMs -and
      $null -ne $GroundCloseElapsedMs -and
      [double]$FooterFsyncElapsedMs -lt [double]$VehicleCloseElapsedMs -and
      [double]$FooterFsyncElapsedMs -lt [double]$GroundCloseElapsedMs)
}

function Stop-MeasuredFailure {
  param([Parameter(Mandatory = $true)][string]$Message)
  throw ('MEASURED_FAIL: ' + $Message)
}

# Live-only infrastructure failures are ERROR/2. This trap is registered only
# after the offline SelfTest branch has returned, so it cannot widen that
# branch into COM, inventory, or hardware work.
trap {
  [string]$unhandledMessage = "unhandled live runner error: $($_.Exception.Message) stack=$($_.ScriptStackTrace)"
  try {
    if ($script:OutputDirectoryOwned -and
        -not [string]::IsNullOrWhiteSpace($OutputDirectory) -and
        (Test-Path -LiteralPath $OutputDirectory -PathType Container)) {
      $unhandledPath = Join-Path $OutputDirectory `
          'runner_unhandled_error.json'
      if (-not (Test-Path -LiteralPath $unhandledPath)) {
        Write-JsonDurable -Path $unhandledPath -Value ([ordered]@{
          schema_version=1;status='ERROR';completed=$false
          written_utc=[DateTime]::UtcNow.ToString('o')
          upload=$false;error=$unhandledMessage
        })
      }
    }
  } catch {}
  [Console]::Error.WriteLine(
      ('FINAL ERROR output={0} message={1}' -f $OutputDirectory,
       $unhandledMessage))
  exit 2
}

if ([string]::Equals($VehiclePort, $GroundPort,
    [StringComparison]::OrdinalIgnoreCase)) {
  throw 'VehiclePort and GroundPort must be different.'
}
if ([string]::Equals($VehiclePnpDeviceId, $GroundPnpDeviceId,
    [StringComparison]::OrdinalIgnoreCase)) {
  throw 'Vehicle and Ground PNP identities must be different.'
}

$repo = Split-Path -Parent $PSScriptRoot
$runnerHashResult = Get-FileHash -Algorithm SHA256 `
    -LiteralPath $PSCommandPath -ErrorAction Stop
[string]$runnerSha256 = [string]$runnerHashResult.Hash
if ($runnerSha256 -notmatch '^[0-9A-F]{64}$') {
  throw 'Runner SHA-256 was not an exact uppercase 64-hex value.'
}
if ([string]::IsNullOrWhiteSpace($FixturePath)) {
  $FixturePath = Join-Path $repo `
      'runs\hil\E2E-PARAM-PROXY-PRODUCTION-001\20260823T145616839Z\param_request_list.bin'
}
if (-not (Test-Path -LiteralPath $FixturePath -PathType Leaf)) {
  throw "FixturePath is missing: $FixturePath"
}
[byte[]]$fixture = [System.IO.File]::ReadAllBytes(
    (Resolve-Path -LiteralPath $FixturePath).Path)
$fixtureContract = Test-ExactRequestFixture -Bytes $fixture
if (-not $fixtureContract.valid) {
  throw "Frozen #21 fixture contract failed: $($fixtureContract.errors -join '; ')"
}
$mavlinkDefinitionSet = Import-MavlinkDefinitions -Path `
    (Join-Path $repo 'core\src\mavlink_frame.cpp')

$timestamp = [DateTime]::UtcNow.ToString('yyyyMMddTHHmmssfffZ')
if ([string]::IsNullOrWhiteSpace($OutputDirectory)) {
  $OutputDirectory = Join-Path $repo `
      "runs\hil\HIL-DUAL-DIAG-PARAM-LIST-001\$timestamp"
}
if (Test-Path -LiteralPath $OutputDirectory) {
  throw "HIL evidence directory exists; refusing overwrite: $OutputDirectory"
}
[void][System.IO.Directory]::CreateDirectory($OutputDirectory)
$script:OutputDirectoryOwned = $true

$script:RunWatch = [System.Diagnostics.Stopwatch]::StartNew()
$script:Timeline = New-Object 'System.Collections.Generic.List[object]'
$script:DiagnosticQueryWriteCount = [uint64]0
[void](Set-ReaderCaptureContext -Phase 'runner_start')
$script:CurrentPhase = 'runner_start'
$script:LiveProgressStream = $null
$vehicleRawStream = $null
$groundRawStream = $null
try {
  $script:LiveProgressStream = New-DurableJsonlStream -Path `
      (Join-Path $OutputDirectory 'live_progress.jsonl')
  $vehicleRawStream = New-Object System.IO.FileStream(
      (Join-Path $OutputDirectory 'vehicle_rx.raw.bin'),
      [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write,
      [System.IO.FileShare]::Read, $script:RawCaptureBufferBytes,
      [System.IO.FileOptions]::SequentialScan)
  $groundRawStream = New-Object System.IO.FileStream(
      (Join-Path $OutputDirectory 'ground_rx.raw.bin'),
      [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write,
      [System.IO.FileShare]::Read, $script:RawCaptureBufferBytes,
      [System.IO.FileOptions]::SequentialScan)
} catch {
  try { if ($null -ne $groundRawStream) {$groundRawStream.Dispose()} } catch {}
  try { if ($null -ne $vehicleRawStream) {$vehicleRawStream.Dispose()} } catch {}
  try {
    if ($null -ne $script:LiveProgressStream) {
      $script:LiveProgressStream.Dispose()
      $script:LiveProgressStream = $null
    }
  } catch {}
  throw
}
$groundParser = New-MavlinkParserState `
    -Definitions $mavlinkDefinitionSet.definitions
$groundParser.Enabled = $false
$vehicleCapture = New-CaptureState -Role 'vehicle' -TagBase 'VCSTAT' `
    -RawStream $vehicleRawStream -Mavlink $null
$groundCapture = New-CaptureState -Role 'ground' -TagBase 'GCSTAT' `
    -RawStream $groundRawStream -Mavlink $groundParser

$vehicleSerial = $null
$groundSerial = $null
$readerBrokerBundle = $null
$readerBrokerLifecycle = $null
$vehicleOpenCount = 0
$groundOpenCount = 0
$vehicleCloseElapsedMs = $null
$groundCloseElapsedMs = $null
$footerFsyncElapsedMs = $null
$footerFsyncQpcTicks = $null
$brokerChildExitElapsedMs = $null
$footerRecorded = $false
$rawEvidenceSeal = Get-RawEvidenceFallbackProjection `
    -VehicleRawBytes 0 -GroundRawBytes 0 `
    -FailureReason 'raw_evidence_seal_not_attempted'
$pumpFairnessEvidence = Get-PumpFairnessFallbackProjection `
    -TargetMs $script:PumpFairnessTargetMs `
    -HardLimitMs $script:PumpFairnessHardLimitMs `
    -FailureReason 'pump_fairness_measurement_not_completed'
$hotPathPrewarm = $null
$footerSequenceCompleted = $false
$preCloseStatus = 'ERROR'
$failure = $null
$errors = New-Object 'System.Collections.Generic.List[string]'
$prePowerIdentity = $null
$prePowerDecision = $null
$postPowerIdentity = $null
$powerOffWait = $null
$baselineVehicle = $null
$baselineGround = $null
$postVehicle = $null
$postGround = $null
$baselineSetup = $null
$backlogDrainGate = $null
$backlogDrainEvidence = Get-BacklogDrainEvidenceProjection `
    -BacklogDrainGate $null -GroundParser $groundParser `
    -TimeoutSeconds $BacklogDrainTimeoutSeconds
$baselinePairGate = $null
$preRequestPairGate = $null
$preRequestVehicle = $null
$preRequestVehicleGate = $null
$postVehicleAnchor = $null
$postAssessment = $null
$postDiagnosticPlan = $null
$syncInvalidContinuation = $null
$parserIntegrity = $null
$listAssessment = $null
$heartbeatMetrics = $null
$vehicleHeartbeatGrantDiagnostics = $null
$m0 = $null
$r0 = $null
$m1 = $null
$causalGate = $null
$portsOpenedElapsedMs = $null
$dataPlaneReadiness = $null
$dataPlaneReadinessEvidence = $null
$baselinePairEvidence = $null
$preRequestPairEvidence = $null
$officialParamListState = $null
$postCutoffParamListState = $null
$paramListDiagnosticEvidence = $null
[string]$captureStopReason = 'not_run'
$guardCompleted = $false
$setupInvalid = $false
$injection = [pscustomobject][ordered]@{
  attempt_count=0;write_count=0;write_uncertain=$false
  write_disposition='NOT_ATTEMPTED'
  final_write_elapsed_ms=$null; final_write_utc=$null
}
$progressState = New-ProgressState
[byte[]]$vehicleCommand = [System.Text.Encoding]::ASCII.GetBytes("VCSTAT?`n")
[byte[]]$groundCommand = [System.Text.Encoding]::ASCII.GetBytes("VCGSTAT?`n")
Add-TimelineEvent -Name 'runner_started' -Details @{
  test_id='HIL-DUAL-DIAG-PARAM-LIST-001'; upload=$false
}
Add-LiveProgressRecord -Event 'runner_started' -Details @{
  indexed=0; last=-1; overall_timeout_s=$OverallTimeoutSeconds
  stall_timeout_s=$StallTimeoutSeconds
  duplicate_guard_s=$DuplicateGuardSeconds
  data_plane_readiness_timeout_s=$DataPlaneReadinessTimeoutSeconds
}

try {
  $prewarmIsolationBefore = [pscustomobject][ordered]@{
    vehicle_raw_bytes=[long]$vehicleCapture.RawBytes
    vehicle_chunk_count=$vehicleCapture.Chunks.Count
    vehicle_tagged_line_count=$vehicleCapture.TaggedLines.Count
    vehicle_stream_position=[long]$vehicleRawStream.Position
    ground_raw_bytes=[long]$groundCapture.RawBytes
    ground_chunk_count=$groundCapture.Chunks.Count
    ground_tagged_line_count=$groundCapture.TaggedLines.Count
    ground_stream_position=[long]$groundRawStream.Position
    parser_enabled=[bool]$groundParser.Enabled
    parser_valid_event_count=$groundParser.ValidEvents.Count
    parser_heartbeat_event_count=$groundParser.HeartbeatEvents.Count
    parser_partial_buffer_count=$groundParser.Buffer.Count
    diagnostic_query_write_count=[uint64]$script:DiagnosticQueryWriteCount
    fixture_write_count=[int]$injection.write_count
  }
  $hotPathPrewarm = Invoke-PumpHotPathPrewarm `
      -Definitions $mavlinkDefinitionSet.definitions
  [bool]$actualStateUnchanged = (
      [long]$vehicleCapture.RawBytes -eq
          [long]$prewarmIsolationBefore.vehicle_raw_bytes -and
      $vehicleCapture.Chunks.Count -eq
          $prewarmIsolationBefore.vehicle_chunk_count -and
      $vehicleCapture.TaggedLines.Count -eq
          $prewarmIsolationBefore.vehicle_tagged_line_count -and
      [long]$vehicleRawStream.Position -eq
          [long]$prewarmIsolationBefore.vehicle_stream_position -and
      [long]$groundCapture.RawBytes -eq
          [long]$prewarmIsolationBefore.ground_raw_bytes -and
      $groundCapture.Chunks.Count -eq
          $prewarmIsolationBefore.ground_chunk_count -and
      $groundCapture.TaggedLines.Count -eq
          $prewarmIsolationBefore.ground_tagged_line_count -and
      [long]$groundRawStream.Position -eq
          [long]$prewarmIsolationBefore.ground_stream_position -and
      [bool]$groundParser.Enabled -eq
          [bool]$prewarmIsolationBefore.parser_enabled -and
      $groundParser.ValidEvents.Count -eq
          $prewarmIsolationBefore.parser_valid_event_count -and
      $groundParser.HeartbeatEvents.Count -eq
          $prewarmIsolationBefore.parser_heartbeat_event_count -and
      $groundParser.Buffer.Count -eq
          $prewarmIsolationBefore.parser_partial_buffer_count -and
      [uint64]$script:DiagnosticQueryWriteCount -eq
          [uint64]$prewarmIsolationBefore.diagnostic_query_write_count -and
      [int]$injection.write_count -eq
          [int]$prewarmIsolationBefore.fixture_write_count -and
      $null -eq $vehicleSerial -and $null -eq $groundSerial -and
      $vehicleOpenCount -eq 0 -and $groundOpenCount -eq 0)
  $hotPathPrewarm = [pscustomobject][ordered]@{
    schema_version=1
    valid=([bool]$hotPathPrewarm.valid -and $actualStateUnchanged)
    isolated_execution=$hotPathPrewarm
    actual_capture_parser_state_unchanged=$actualStateUnchanged
    fixture_passed_to_prewarm=$false
    serial_objects_before_prewarm=$false
    serial_open_count_before_prewarm=0
    request_write_count_before_prewarm=0
  }
  Write-JsonDurable -Path (Join-Path $OutputDirectory `
      'hot_path_prewarm.json') -Value $hotPathPrewarm
  if (-not $hotPathPrewarm.valid) {
    throw 'isolated pump hot-path prewarm failed before COM construction'
  }
  Add-TimelineEvent -Name 'pump_hot_path_prewarm_complete' -Details @{
    valid=$hotPathPrewarm.valid
    actual_capture_parser_state_unchanged=$actualStateUnchanged
  }
  Add-LiveProgressRecord -Event 'pump_hot_path_prewarm_complete' -Details @{
    valid=$hotPathPrewarm.valid;serial_open_count=0;request_write_count=0
  }
  if (-not ('System.IO.Ports.SerialPort' -as [type])) {
    Add-Type -AssemblyName System.IO.Ports
  }
  Initialize-DualPortReaderWorkerType

  [void](Set-ReaderCaptureContext -Phase 'pre_power_identity')
  $script:CurrentPhase = 'pre_power_identity'
  $preInventory = @(Get-LivePortInventory)
  $preBinding = Test-RoleIdentityBinding -Inventory $preInventory `
      -ExpectedVehiclePort $VehiclePort `
      -ExpectedVehicleIdentity $VehiclePnpDeviceId `
      -ExpectedGroundPort $GroundPort `
      -ExpectedGroundIdentity $GroundPnpDeviceId
  $prePowerDecision = Get-PrePowerIdentityDecision -Binding $preBinding
  $prePowerIdentity = [pscustomobject][ordered]@{
    inventory=$preInventory; binding=$preBinding; decision=$prePowerDecision
  }
  if (-not $prePowerDecision.valid) {
    Stop-MeasuredFailure -Message $prePowerDecision.message
  }
  Add-TimelineEvent -Name 'pre_power_identity_bound'
  Add-LiveProgressRecord -Event 'pre_power_identity_bound' -Details @{
    vehicle_port=$VehiclePort; ground_port=$GroundPort
  }
  Write-Host 'IDENTITY_BOUND_POWER_OFF_REQUIRED'

  [void](Set-ReaderCaptureContext -Phase 'confirm_full_power_off')
  $script:CurrentPhase = 'confirm_full_power_off'
  $powerOffWait = Wait-ForBothPortsAbsent -First $VehiclePort `
      -Second $GroundPort -RequiredAbsentMs $PowerOffConfirmMs `
      -TimeoutSeconds $PortWaitTimeoutSeconds
  if (-not $powerOffWait.confirmed) {
    Stop-MeasuredFailure -Message `
        "both ports were not absent continuously for $PowerOffConfirmMs ms"
  }
  Write-Host 'POWER_OFF_CONFIRMED_WAITING_FOR_PORTS'
  Add-TimelineEvent -Name 'power_off_confirmed_waiting_for_ports' `
      -Details @{continuous_absent_ms=$powerOffWait.continuous_absent_ms}
  Add-LiveProgressRecord `
      -Event 'power_off_confirmed_waiting_for_ports' `
      -Details @{continuous_absent_ms=$powerOffWait.continuous_absent_ms}

  [void](Set-ReaderCaptureContext -Phase 'wait_bound_ports_reappear')
  $script:CurrentPhase = 'wait_bound_ports_reappear'
  $postPowerIdentity = Wait-ForBoundPortIdentities `
      -TimeoutSeconds $PortWaitTimeoutSeconds
  if (-not $postPowerIdentity.found) {
    Stop-MeasuredFailure -Message `
        'ports did not reappear with exact role/PNP/status/problem binding'
  }
  Add-TimelineEvent -Name 'ports_reappeared' -Details @{
    required_stable_ms=$postPowerIdentity.required_stable_ms
    continuous_stable_ms=$postPowerIdentity.continuous_stable_ms
  }
  Add-LiveProgressRecord -Event 'ports_reappeared' -Details @{
    vehicle_port=$VehiclePort; ground_port=$GroundPort
    required_stable_ms=$postPowerIdentity.required_stable_ms
    continuous_stable_ms=$postPowerIdentity.continuous_stable_ms
  }

  $portsOpeningClockAnchor = New-ReaderClockAnchor `
      -RunWatch $script:RunWatch
  $readerBrokerBundle = Start-ReaderBrokerClient -Scenario 'serial' `
      -RingSlots $script:ReaderRingSlotCount `
      -QpcOriginTicks ([long]$portsOpeningClockAnchor.qpc_origin_ticks) `
      -BaseElapsedMs ([double]$portsOpeningClockAnchor.base_elapsed_ms) `
      -ExpectedRunnerSha256 $runnerSha256
  $readerBrokerLifecycle = $readerBrokerBundle.lifecycle
  $vehicleSerial = $readerBrokerBundle.vehicle_proxy
  $groundSerial = $readerBrokerBundle.ground_proxy
  $vehicleSerial.DtrEnable = $false
  $vehicleSerial.RtsEnable = $false
  $groundSerial.DtrEnable = $false
  $groundSerial.RtsEnable = $false
  $script:DualPortReaderWorker = $readerBrokerBundle.worker
  $vehicleSerial.Open()
  ++$vehicleOpenCount
  $groundSerial.Open()
  ++$groundOpenCount
  $portsOpenedElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
  $script:PumpFairness =
      New-PumpFairnessStateFromReaderClockAnchor `
        -ClockAnchor $portsOpeningClockAnchor
  [void](Set-ReaderCaptureContext -Phase 'ports_opening' `
      -Epoch 'boot_observe')
  Add-TimelineEvent -Name 'ports_opened' -Details @{
    vehicle_open_count=$vehicleOpenCount; ground_open_count=$groundOpenCount
    dtr=$false; rts=$false
    elapsed_ms=[Math]::Round($portsOpenedElapsedMs,3)
  }
  Add-LiveProgressRecord -Event 'ports_opened' -Details @{
    vehicle_open_count=$vehicleOpenCount; ground_open_count=$groundOpenCount
    elapsed_ms=[Math]::Round($portsOpenedElapsedMs,3)
  }

  Invoke-CaptureInterval -Milliseconds 15000 -Phase 'boot_observe_15s' `
      -VehicleSerial $vehicleSerial -VehicleState $vehicleCapture `
      -GroundSerial $groundSerial -GroundState $groundCapture

  if ([bool]$groundParser.Enabled) {
    throw 'boot-to-readiness raw boundary requires the Ground parser disabled'
  }
  Add-TimelineEvent -Name 'boot_to_readiness_raw_boundary' -Details @{
    ground_parser_enabled=$false
    vehicle_raw_bytes=[long]$vehicleCapture.RawBytes
    ground_raw_bytes=[long]$groundCapture.RawBytes
  }
  $script:PumpAdminStage = 'boot_to_readiness_raw_boundary'
  [void](Invoke-PumpPair -VehicleSerial $vehicleSerial `
      -VehicleState $vehicleCapture -GroundSerial $groundSerial `
      -GroundState $groundCapture)
  $dataPlaneReadiness = Invoke-DataPlaneReadinessGate `
      -GateStartedElapsedMs $portsOpenedElapsedMs `
      -TimeoutSeconds $DataPlaneReadinessTimeoutSeconds `
      -SnapshotTimeoutSeconds $SnapshotTimeoutSeconds `
      -GroundParser $groundParser `
      -VehicleSerial $vehicleSerial -VehicleState $vehicleCapture `
      -GroundSerial $groundSerial -GroundState $groundCapture `
      -VehicleCommand $vehicleCommand
  if (-not $dataPlaneReadiness.valid) {
    $setupInvalid = $true
    [string]$readinessFailureReason = if ($dataPlaneReadiness.sync_invalid) {
      'data_plane_diagnostic_sync_invalid'
    } else { 'data_plane_readiness_timeout' }
    [string]$readinessFailureMessage = if ($dataPlaneReadiness.sync_invalid) {
      'setup_invalid: data-plane diagnostic synchronization failed; request suppressed'
    } else {
      'setup_invalid: data-plane readiness timeout; request suppressed'
    }
    $errors.Add($readinessFailureMessage)
    Add-TimelineEvent -Name 'setup_invalid' -Details @{
      reason=$readinessFailureReason;fixture_write_count=0
    }
    Add-LiveProgressRecord -Event 'setup_invalid' -Details @{
      reason=$readinessFailureReason;fixture_write_count=0
    }
  } else {
    [double]$backlogDrainStartedElapsedMs =
        $script:RunWatch.Elapsed.TotalMilliseconds
    $backlogDrainGate = Invoke-PreBaselineBacklogDrainGate `
        -GateStartedElapsedMs $backlogDrainStartedElapsedMs `
        -TimeoutSeconds $BacklogDrainTimeoutSeconds `
        -SnapshotTimeoutSeconds $SnapshotTimeoutSeconds `
        -GroundParser $groundParser `
        -VehicleSerial $vehicleSerial -VehicleState $vehicleCapture `
        -GroundSerial $groundSerial -GroundState $groundCapture `
        -VehicleCommand $vehicleCommand -GroundCommand $groundCommand `
        -InitialVehicleSnapshot $dataPlaneReadiness.last_vehicle_snapshot
    $backlogDrainEvidence = Get-BacklogDrainEvidenceProjection `
        -BacklogDrainGate $backlogDrainGate -GroundParser $groundParser `
        -TimeoutSeconds $BacklogDrainTimeoutSeconds
    if (-not $backlogDrainGate.valid) {
      $setupInvalid = $true
      $errors.Add('setup_invalid: cold-boot generic PARAM backlog did not drain to two stable clean observations; request suppressed')
      Add-TimelineEvent -Name 'setup_invalid' -Details @{
        reason='prebaseline_backlog_drain_timeout_or_sync_invalid'
        fixture_write_count=0
      }
      Add-LiveProgressRecord -Event 'setup_invalid' -Details @{
        reason='prebaseline_backlog_drain_timeout_or_sync_invalid'
        fixture_write_count=0
      }
    } else {
    $baselinePairGate = Invoke-OfficialBaselineGate `
        -DeadlineElapsedMs $backlogDrainGate.deadline_elapsed_ms `
        -SnapshotTimeoutSeconds $SnapshotTimeoutSeconds `
        -GroundParser $groundParser `
        -VehicleSerial $vehicleSerial -VehicleState $vehicleCapture `
        -GroundSerial $groundSerial -GroundState $groundCapture `
        -VehicleCommand $vehicleCommand -GroundCommand $groundCommand `
        -InitialVehicleSnapshot $backlogDrainGate.last_vehicle_snapshot `
        -InitialGroundSnapshot $backlogDrainGate.last_ground_snapshot `
        -MaxAttempts 3
    $baselineVehicle = $baselinePairGate.final_vehicle_snapshot
    $baselineGround = $baselinePairGate.final_ground_snapshot
    $baselineSetup = $baselinePairGate.baseline_setup
    Add-TimelineEvent -Name 'baseline_complete' -Details @{
      vehicle=if($null -ne $baselineVehicle){$baselineVehicle.status}else{'NOT_RUN'}
      ground=if($null -ne $baselineGround){$baselineGround.status}else{'NOT_RUN'}
      valid=$baselinePairGate.valid;attempt_count=$baselinePairGate.attempt_count
      retry_count=$baselinePairGate.retry_count
    }
    Add-LiveProgressRecord -Event 'baseline_complete' -Details @{
      vehicle_status=if($null -ne $baselineVehicle){$baselineVehicle.status}else{'NOT_RUN'}
      ground_status=if($null -ne $baselineGround){$baselineGround.status}else{'NOT_RUN'}
      valid=$baselinePairGate.valid
      attempt_count=$baselinePairGate.attempt_count
      retry_count=$baselinePairGate.retry_count;fixture_write_count=0
    }
    if (-not $baselinePairGate.valid) {
      $setupInvalid = $true
      $errors.Add('setup_invalid: official baseline pair gate failed reason=' +
          [string]$baselinePairGate.failure_reason + '; request suppressed')
      Add-TimelineEvent -Name 'setup_invalid' -Details @{
        reason=$baselinePairGate.failure_reason;fixture_write_count=0
      }
      Add-LiveProgressRecord -Event 'setup_invalid' -Details @{
        reason=$baselinePairGate.failure_reason;fixture_write_count=0
      }
    } else {
      $postVehicleAnchor = $baselineVehicle
      $preRequestPairGate = Invoke-OfficialPreRequestGate `
          -DeadlineElapsedMs $backlogDrainGate.deadline_elapsed_ms `
          -InitialVehicleSnapshot $baselineVehicle `
          -InitialGroundSnapshot $baselineGround `
          -SnapshotTimeoutSeconds $SnapshotTimeoutSeconds `
          -BacklogDrainTimeoutSeconds $BacklogDrainTimeoutSeconds `
          -GroundParser $groundParser `
          -VehicleSerial $vehicleSerial -VehicleState $vehicleCapture `
          -GroundSerial $groundSerial -GroundState $groundCapture `
          -VehicleCommand $vehicleCommand -GroundCommand $groundCommand `
          -ReadinessParamValueEvents `
            @($dataPlaneReadiness.pre_request_param_value_events) `
          -MaxAttempts 3
      $preRequestVehicle = $preRequestPairGate.pre_request_vehicle
      $preRequestVehicleGate = $preRequestPairGate.pre_request_vehicle_gate
      $causalGate = $preRequestPairGate.causal_gate
      $m0 = $preRequestPairGate.m0
      if ($null -ne $preRequestPairGate.latest_complete_vehicle_snapshot) {
        $postVehicleAnchor = $preRequestPairGate.latest_complete_vehicle_snapshot
      }
      $baselineVehicle = $preRequestPairGate.final_vehicle_snapshot
      $baselineGround = $preRequestPairGate.final_ground_snapshot
      if (-not $preRequestPairGate.valid) {
        $setupInvalid = $true
        $errors.Add('R0 pre-request gate failed reason=' +
            [string]$preRequestPairGate.failure_reason +
            '; request suppressed')
        Add-TimelineEvent -Name 'R0_causal_gate_stop_no_request'
        Add-LiveProgressRecord -Event 'setup_invalid' -Details @{
          reason=$preRequestPairGate.failure_reason;fixture_write_count=0
        }
      } else {
        [void](Set-ReaderCaptureContext `
            -Phase 'R0_request_and_list_capture' -Epoch 'official_R0_M1')
        $groundParser.ParamList.capture_scope = 'official'
        $script:CurrentPhase = 'R0_request_and_list_capture'
        $heartbeatAccumulator = New-HeartbeatWindowAccumulator `
            -M0ElapsedMs ([double]$m0.elapsed_ms)
        Update-HeartbeatWindowAccumulator -State $heartbeatAccumulator `
            -Events $groundParser.HeartbeatEvents `
            -ThroughElapsedMs ([Math]::Round(
              $script:RunWatch.Elapsed.TotalMilliseconds, 3))
        Write-ExactRequestOnce -Serial $groundSerial -Fixture $fixture `
            -InjectionState $injection
        $r0 = [pscustomobject][ordered]@{
          elapsed_ms=[Math]::Round($script:RunWatch.Elapsed.TotalMilliseconds, 3)
          utc=[DateTime]::UtcNow.ToString('o')
          ground_raw_offset=[long]$groundCapture.RawBytes
        }
        Add-TimelineEvent -Name 'request_sent_R0' -Details @{
          bytes=14; sha256=$script:ExpectedFixtureSha256; write_count=1
        }
        Add-LiveProgressRecord -Event 'request_sent' -Details @{
          marker='R0'; indexed=0; last=-1; fixture_write_count=1
        }

      [double]$requestStartSeconds = $script:RunWatch.Elapsed.TotalSeconds
      [double]$lastRawFlushSeconds = $requestStartSeconds
      [double]$guardStartSeconds = -1
      [bool]$listCompleteRecorded = $false
      [bool]$captureLoopDone = $false
      while (-not $captureLoopDone) {
        [int]$read = Invoke-PumpPair -VehicleSerial $vehicleSerial `
            -VehicleState $vehicleCapture -GroundSerial $groundSerial `
            -GroundState $groundCapture
        [double]$nowSeconds = $script:RunWatch.Elapsed.TotalSeconds
        [double]$elapsedSinceR0 = $nowSeconds - $requestStartSeconds
        [double]$stallAnchorSeconds = $requestStartSeconds
        if ($null -ne $groundParser.ParamList.last_accepted_elapsed_ms) {
          $stallAnchorSeconds = [double]$groundParser.ParamList.last_accepted_elapsed_ms /
              1000.0
        }
        [double]$stallSeconds = $nowSeconds - $stallAnchorSeconds
        $timeoutDecision = Test-TimeoutDecision `
            -ElapsedSeconds $elapsedSinceR0 -StallSeconds $stallSeconds `
            -Indexed ([int]$groundParser.ParamList.unique_count) `
            -OverallLimitSeconds $OverallTimeoutSeconds `
            -StallLimitSeconds $StallTimeoutSeconds

        [double]$nowElapsedMs = [Math]::Round($nowSeconds * 1000.0, 3)
        Update-HeartbeatWindowAccumulator -State $heartbeatAccumulator `
            -Events $groundParser.HeartbeatEvents `
            -ThroughElapsedMs $nowElapsedMs
        [int]$lastIndex = if ($null -ne $groundParser.ParamList.last_index) {
          [int]$groundParser.ParamList.last_index
        } else { -1 }
        [bool]$progressDue = (($elapsedSinceR0 -
            [double]$progressState.last_elapsed_seconds) -ge 30.0 -or
            ([int]$groundParser.ParamList.unique_count -
             [int]$progressState.last_indexed) -ge 25)
        if ($progressDue) {
          $partialHeartbeat = Get-HeartbeatWindowAccumulatorSnapshot `
              -State $heartbeatAccumulator -M1ElapsedMs $nowElapsedMs
          [double]$heartbeatMaximum = if ($null -ne
              $partialHeartbeat.maximum_gap_ms) {
            [double]$partialHeartbeat.maximum_gap_ms
          } else { 0.0 }
          $progress = Write-ProgressIfDue -ProgressState $progressState `
              -Indexed ([int]$groundParser.ParamList.unique_count) `
              -LastIndex $lastIndex -ElapsedSeconds $elapsedSinceR0 `
              -HeartbeatMaximumMs $heartbeatMaximum `
              -StallSeconds $stallSeconds
          if (-not $progress.emitted) {
            throw 'Heartbeat progress due decision diverged from writer.'
          }
          Add-LiveProgressRecord -Event 'progress' -Details @{
            indexed=[int]$groundParser.ParamList.unique_count
            last=$lastIndex
            acquisition_elapsed_s=[Math]::Round($elapsedSinceR0,3)
            hb_max_ms=[Math]::Round($heartbeatMaximum,3)
            stall_s=[Math]::Round($stallSeconds,3)
          }
        }
        if (($nowSeconds - $lastRawFlushSeconds) * 1000.0 -ge
            $script:RawCaptureFlushScheduleMs) {
          $vehicleRawStream.Flush($true)
          [void](Invoke-PumpPair -VehicleSerial $vehicleSerial `
              -VehicleState $vehicleCapture -GroundSerial $groundSerial `
              -GroundState $groundCapture)
          $groundRawStream.Flush($true)
          [void](Invoke-PumpPair -VehicleSerial $vehicleSerial `
              -VehicleState $vehicleCapture -GroundSerial $groundSerial `
              -GroundState $groundCapture)
          $lastRawFlushSeconds = $script:RunWatch.Elapsed.TotalSeconds
        }

        if ($groundParser.ParamList.next_expected_index -eq 932) {
          if (-not $listCompleteRecorded) {
            $listCompleteRecorded = $true
            $guardStartSeconds = $nowSeconds
            Add-TimelineEvent -Name 'list_complete' -Details @{
              indexed=932; last=931
            }
            Add-LiveProgressRecord -Event 'list_complete' -Details @{
              indexed=932; last=931
            }
          }
          if ($nowSeconds - $guardStartSeconds -ge $DuplicateGuardSeconds) {
            $guardCompleted = $true
            $captureLoopDone = $true
            $captureStopReason = 'complete_duplicate_guard'
            Add-TimelineEvent -Name 'duplicate_guard_complete' -Details @{
              seconds=$DuplicateGuardSeconds
            }
            Add-LiveProgressRecord -Event 'duplicate_guard_complete' `
                -Details @{indexed=932;last=931;seconds=$DuplicateGuardSeconds}
          }
        } elseif ($timeoutDecision.stall_timeout) {
          $errors.Add("expected-index stall timeout after $StallTimeoutSeconds seconds")
          $captureLoopDone = $true
          $captureStopReason = 'expected_index_stall_timeout'
        } elseif ($timeoutDecision.overall_timeout) {
          $errors.Add("overall timeout after $OverallTimeoutSeconds seconds")
          $captureLoopDone = $true
          $captureStopReason = 'overall_timeout'
        }
        if ($read -eq 0 -and -not $captureLoopDone) {
          Start-Sleep -Milliseconds 2
        }
      }
      $m1Transition = Set-ReaderCaptureContext `
          -Phase 'post_cutoff_drain' -Epoch 'post_cutoff'
      $m1 = [pscustomobject][ordered]@{
        elapsed_ms=[Math]::Round(
            [double]$m1Transition.ground_boundary_elapsed_ms, 3)
        shared_completion_elapsed_ms=[Math]::Round(
            [double]$m1Transition.captured_elapsed_ms, 3)
        utc=[DateTime]::UtcNow.ToString('o')
        ground_raw_offset=[long]$m1Transition.ground_raw_offset_exclusive
        ground_sequence_exclusive=
            [long]$m1Transition.ground_sequence_exclusive
      }
      $parserIntegrity = Get-ParserIntegrity -Parser $groundParser
      $officialParamListState = $groundParser.ParamList
      $listAssessment = Complete-ParamListAssessment `
          -State $officialParamListState
      Update-HeartbeatWindowAccumulator -State $heartbeatAccumulator `
          -Events $groundParser.HeartbeatEvents `
          -ThroughElapsedMs ([double]$m1.elapsed_ms)
      $heartbeatMetrics = Get-HeartbeatWindowAccumulatorSnapshot `
          -State $heartbeatAccumulator -M1ElapsedMs ([double]$m1.elapsed_ms) `
          -IncludeGaps
      $groundParser.ParamList = New-ParamListState `
          -CaptureScope 'post_cutoff'
      $script:CurrentPhase = 'post_cutoff_drain'
      [void](Invoke-PumpPair -VehicleSerial $vehicleSerial `
          -VehicleState $vehicleCapture -GroundSerial $groundSerial `
          -GroundState $groundCapture)
      [void](Set-ReaderCaptureContext -Phase 'post_cutoff_drain' `
          -Epoch 'post_cutoff_parser_closed')
      $postCutoffParamListState = $groundParser.ParamList
      $groundParser.Enabled = $false
      Add-TimelineEvent -Name 'M1' -Details @{
        list_valid=$listAssessment.valid
        parser_valid=$parserIntegrity.valid
        heartbeat_valid=$heartbeatMetrics.valid
      }
      if (-not $listAssessment.valid) {
        $errors.Add('full #22 acceptance failed: exact/unique/ordered/count/source/ID/type contract')
      }
      if ($null -ne $officialParamListState.first_anomaly) {
        $errors.Add('strict #22 semantic anomaly recorded first=' +
          [string]$officialParamListState.first_anomaly.anomaly_class)
      }
      if (-not $parserIntegrity.valid) {
        $errors.Add('M0-M1 canonical80 parser integrity failed')
      }
      if (-not $heartbeatMetrics.valid) {
        $errors.Add('primary source1/1 heartbeat edge/consecutive/tail exceeded 2500 ms')
      }
      if (-not $guardCompleted) {
        $errors.Add('30-second duplicate guard did not complete')
      }
    }
  }
  }
  }

  if ($null -ne $vehicleSerial -and $vehicleSerial.IsOpen -and
      $null -ne $groundSerial -and $groundSerial.IsOpen) {
    $postDiagnosticPlan = Get-PostDiagnosticPlan `
        -DataPlaneReadiness $dataPlaneReadiness `
        -BacklogDrainGate $backlogDrainGate `
        -BaselinePairGate $baselinePairGate `
        -PreRequestPairGate $preRequestPairGate `
        -InjectionState $injection
    [Nullable[uint32]]$expectedGroundQ = $null
    if ($null -ne $baselineGround -and $baselineGround.status -eq 'COMPLETE') {
      $expectedGroundQ = Get-NextQueryId -Current `
          ([uint32]$baselineGround.q_uint32)
    }
    if ($postDiagnosticPlan.run_ground) {
      $postGround = Invoke-SnapshotQuery -Name 'post_ground' `
          -Serial $groundSerial -State $groundCapture -Command $groundCommand `
          -TimeoutSeconds $SnapshotTimeoutSeconds -ExpectedQ $expectedGroundQ `
          -VehicleSerial $vehicleSerial -VehicleState $vehicleCapture `
          -GroundSerial $groundSerial -GroundState $groundCapture
    } else {
      $groundMatcherAtLatch = Get-SyncInvalidMatcherAtLatch -Role 'ground' `
          -DataPlaneReadiness $dataPlaneReadiness `
          -BacklogDrainGate $backlogDrainGate `
          -BaselinePairGate $baselinePairGate `
          -PreRequestPairGate $preRequestPairGate
      $postGround = New-SyncInvalidSuppressedSnapshot `
          -Name 'post_ground' -Role 'ground' -State $groundCapture `
          -MatcherAtLatch $groundMatcherAtLatch `
          -SuppressionSource ($postDiagnosticPlan.sources -join '+')
    }
    [Nullable[uint32]]$expectedVehicleQ = $null
    if ($null -ne $postVehicleAnchor -and
        $postVehicleAnchor.status -eq 'COMPLETE') {
      $expectedVehicleQ = Get-NextQueryId -Current `
          ([uint32]$postVehicleAnchor.q_uint32)
      $postVehicleAnchorBoot = Get-SnapshotUInt64 `
          -Snapshot $postVehicleAnchor -Key 'boot'
      if (-not $postVehicleAnchorBoot.found) { $expectedVehicleQ = $null }
    }
    if ($postDiagnosticPlan.run_vehicle) {
      $postVehicle = Invoke-SnapshotQuery -Name 'post_vehicle' `
          -Serial $vehicleSerial -State $vehicleCapture `
          -Command $vehicleCommand `
          -TimeoutSeconds $SnapshotTimeoutSeconds `
          -ExpectedQ $expectedVehicleQ `
          -VehicleSerial $vehicleSerial -VehicleState $vehicleCapture `
          -GroundSerial $groundSerial -GroundState $groundCapture
    } else {
      $vehicleMatcherAtLatch = Get-SyncInvalidMatcherAtLatch `
          -Role 'vehicle' -DataPlaneReadiness $dataPlaneReadiness `
          -BacklogDrainGate $backlogDrainGate `
          -BaselinePairGate $baselinePairGate `
          -PreRequestPairGate $preRequestPairGate
      $postVehicle = New-SyncInvalidSuppressedSnapshot `
          -Name 'post_vehicle' -Role 'vehicle' -State $vehicleCapture `
          -MatcherAtLatch $vehicleMatcherAtLatch `
          -SuppressionSource ($postDiagnosticPlan.sources -join '+')
    }
    $vehicleHeartbeatGrantDiagnostics =
        Test-VehicleHeartbeatGrantDiagnosticContract `
          -BaselineVehicle $baselineVehicle `
          -M0Vehicle $preRequestVehicle -M1Vehicle $postVehicle
    if ([int]$injection.write_count -eq 1 -and
        -not [bool]$vehicleHeartbeatGrantDiagnostics.valid) {
      $errors.Add('Vehicle heartbeat Grant diagnostic contract failed first=' +
          [string]$vehicleHeartbeatGrantDiagnostics.first_failed)
    }
    if ($postDiagnosticPlan.run_ground -and
        $postDiagnosticPlan.run_vehicle) {
      if ([int]$injection.attempt_count -eq 1 -and
          [int]$injection.write_count -eq 1 -and
          -not [bool]$injection.write_uncertain -and
          [string]$injection.write_disposition -ceq
            'ACKNOWLEDGED_EXACTLY_ONCE') {
        if ($null -ne $baselineGround -and $null -ne $postVehicleAnchor) {
          $postAssessment = Test-PostSnapshotContract `
              -BaselineGround $baselineGround -PostGround $postGround `
              -Baseline $postVehicleAnchor -PostVehicle $postVehicle `
              -MatchingUsbParamValues $(if ($null -ne $listAssessment) {
                  [uint64]$listAssessment.unique_count
                } else { [uint64]0 }) `
              -ExpectedDiagnosticFaultMode $ExpectedDiagnosticFaultMode `
              -ExpectedDiagnosticFaultDropIndex `
                $ExpectedDiagnosticFaultDropIndex
          if (-not $postAssessment.valid) {
            $errors.Add("post diagnostic contract failed first=$($postAssessment.first_failed)")
          }
        }
      } else {
        $postAssessment = New-RequestSuppressedPostAssessment `
            -PostDiagnosticPlan $postDiagnosticPlan
        Add-TimelineEvent `
            -Name 'post_success_contract_not_run_request_suppressed' `
            -Details @{
              attempt_count=[int]$injection.attempt_count
              write_count=[int]$injection.write_count
              write_disposition=[string]$injection.write_disposition
            }
        Add-LiveProgressRecord `
            -Event 'post_success_contract_not_run_request_suppressed' `
            -Details @{
              attempt_count=[int]$injection.attempt_count
              write_count=[int]$injection.write_count
              write_disposition=[string]$injection.write_disposition
            }
      }
    }
    if ($postDiagnosticPlan.any_sync_invalid) {
      Add-TimelineEvent -Name 'post_snapshots_suppressed_sync_invalid' `
          -Details @{
            ground=$postGround.status;vehicle=$postVehicle.status
            reason='SYNC_INVALID';sources=$postDiagnosticPlan.sources
          }
      Add-LiveProgressRecord `
          -Event 'post_snapshots_suppressed_sync_invalid' -Details @{
            ground_status=$postGround.status
            vehicle_status=$postVehicle.status
            ground_query_count=0;vehicle_query_count=0
            reason='SYNC_INVALID';sources=$postDiagnosticPlan.sources
          }
    }
    Add-TimelineEvent -Name 'post_snapshots' -Details @{
      ground=$postGround.status; vehicle=$postVehicle.status
      valid=($null -ne $postAssessment -and $postAssessment.valid)
    }
    Add-LiveProgressRecord -Event 'post_snapshots' -Details @{
      ground_status=$postGround.status; vehicle_status=$postVehicle.status
      valid=($null -ne $postAssessment -and $postAssessment.valid)
    }
    $matcherAtLatch = $null
    if ($postDiagnosticPlan.any_sync_invalid) {
      $matcherAtLatch = [pscustomobject][ordered]@{
        ground=$postGround.matcher_at_latch
        vehicle=$postVehicle.matcher_at_latch
      }
    }
    $beforeFooterPump = [pscustomobject][ordered]@{
      ground=Get-CaptureMatcherSnapshot -State $groundCapture
      vehicle=Get-CaptureMatcherSnapshot -State $vehicleCapture
    }
    [uint64]$diagnosticWriteCountBeforeFooterPump = `
        [uint64]$script:DiagnosticQueryWriteCount
    Invoke-CaptureInterval -Milliseconds 250 -Phase 'footer_drain' `
        -VehicleSerial $vehicleSerial -VehicleState $vehicleCapture `
        -GroundSerial $groundSerial -GroundState $groundCapture
    if ($postDiagnosticPlan.any_sync_invalid) {
      $afterFooterPump = [pscustomobject][ordered]@{
        ground=Get-CaptureMatcherSnapshot -State $groundCapture
        vehicle=Get-CaptureMatcherSnapshot -State $vehicleCapture
      }
      [uint64]$diagnosticWriteCountAfterFooterPump = `
          [uint64]$script:DiagnosticQueryWriteCount
      $syncInvalidContinuation = New-SyncInvalidContinuationEvidence `
          -MatcherAtLatch $matcherAtLatch `
          -BeforeFooterPump $beforeFooterPump `
          -AfterFooterPump $afterFooterPump `
          -DiagnosticWriteCountBefore $diagnosticWriteCountBeforeFooterPump `
          -DiagnosticWriteCountAfter $diagnosticWriteCountAfterFooterPump
      Write-JsonDurable -Path (Join-Path $OutputDirectory `
          'sync_invalid_continuation.json') -Value $syncInvalidContinuation
    }
    $footerSequenceCompleted = $true
  }
  $preCloseStatus = if ($setupInvalid -or $errors.Count -ne 0) {
    'FAIL'
  } elseif ($injection.write_count -eq 1 -and
      $vehicleOpenCount -eq 1 -and $groundOpenCount -eq 1 -and
      $null -ne $dataPlaneReadiness -and $dataPlaneReadiness.valid -and
      $null -ne $backlogDrainGate -and $backlogDrainGate.valid -and
      $null -ne $preRequestPairGate -and $preRequestPairGate.valid -and
      $null -ne $preRequestVehicleGate -and $preRequestVehicleGate.valid -and
      $null -ne $causalGate -and $causalGate.valid -and
      $null -ne $listAssessment -and $listAssessment.valid -and
      $null -ne $heartbeatMetrics -and $heartbeatMetrics.valid -and
      $null -ne $vehicleHeartbeatGrantDiagnostics -and
      $vehicleHeartbeatGrantDiagnostics.valid -and
      $null -ne $parserIntegrity -and $parserIntegrity.valid -and
      $null -ne $postAssessment -and $postAssessment.valid -and
      $guardCompleted -and $footerSequenceCompleted) {
    'PASS'
  } else { 'FAIL' }
} catch {
  [string]$caughtMessage = $_.Exception.Message
  if ($caughtMessage.StartsWith('MEASURED_FAIL:')) {
    $errors.Add($caughtMessage.Substring('MEASURED_FAIL:'.Length).Trim())
    $preCloseStatus = 'FAIL'
    try {
      Add-LiveProgressRecord -Event 'error' -Details @{
        status='FAIL'; message=$caughtMessage
      }
    } catch {}
  } else {
    $failure = $caughtMessage
    $errors.Add($caughtMessage)
    $preCloseStatus = 'ERROR'
    try {
      Add-LiveProgressRecord -Event 'error' -Details @{
        status='ERROR'; message=$caughtMessage
      }
    } catch {}
  }
} finally {
  try {
    try {
      if ($null -eq $postDiagnosticPlan -or
          -not $postDiagnosticPlan.any_sync_invalid -or
          -not $footerSequenceCompleted) {
        [void](Invoke-PumpPair -VehicleSerial $vehicleSerial `
            -VehicleState $vehicleCapture -GroundSerial $groundSerial `
            -GroundState $groundCapture)
      }
    } catch {
      $errors.Add("final pump failed: $($_.Exception.Message)")
      $preCloseStatus = 'ERROR'
    }
    if ($null -ne $script:DualPortReaderWorker) {
      $readerShutdown = if ($null -ne $readerBrokerBundle) {
        Stop-ReaderBrokerAndDrain -Bundle $readerBrokerBundle `
            -VehicleState $vehicleCapture -GroundState $groundCapture
      } else {
        Stop-DualPortReaderWorkerAndDrain -VehicleState $vehicleCapture `
            -GroundState $groundCapture
      }
      if (-not [bool]$readerShutdown.joined -or
          -not [bool]$readerShutdown.valid) {
        throw 'dual-port reader shutdown/drain consistency failed before raw seal'
      }
    }
    $pumpFairnessEvidence = Get-PumpFairnessEvidence `
        -VehicleState $vehicleCapture -GroundState $groundCapture
    if ($vehicleOpenCount -eq 1 -and $groundOpenCount -eq 1 -and
        -not $pumpFairnessEvidence.valid) {
      $errors.Add('runner dual-COM pump fairness exceeded the 100 ms hard limit')
      if ($preCloseStatus -cne 'ERROR') {
        $preCloseStatus = 'FAIL'
      }
    }
    $rawEvidenceSeal = Seal-EvidenceStreamsBeforeRawHash `
        -VehicleRawStream $vehicleRawStream `
        -GroundRawStream $groundRawStream `
        -LiveProgressStream $script:LiveProgressStream `
        -VehicleRawPath (Join-Path $OutputDirectory 'vehicle_rx.raw.bin') `
        -GroundRawPath (Join-Path $OutputDirectory 'ground_rx.raw.bin') `
        -ExpectedVehicleBytes ([long]$vehicleCapture.RawBytes) `
        -ExpectedGroundBytes ([long]$groundCapture.RawBytes)
    $script:LiveProgressStream = $null
    $script:LiveProgressStream = Open-DurableJsonlAppendStream -Path `
        (Join-Path $OutputDirectory 'live_progress.jsonl')
    Write-JsonDurable -Path (Join-Path $OutputDirectory 'timeline.json') `
        -Value $script:Timeline.ToArray()
    Write-JsonDurable -Path (Join-Path $OutputDirectory `
        'pump_fairness.json') -Value $pumpFairnessEvidence
    Write-JsonDurable -Path (Join-Path $OutputDirectory `
        'vehicle_read_spans.json') -Value $vehicleCapture.Chunks.ToArray()
    Write-JsonDurable -Path (Join-Path $OutputDirectory `
        'ground_read_spans.json') -Value $groundCapture.Chunks.ToArray()
    Write-JsonDurable -Path (Join-Path $OutputDirectory `
        'vehicle_tagged_ascii_spans.json') `
        -Value $vehicleCapture.TaggedLines.ToArray()
    Write-JsonDurable -Path (Join-Path $OutputDirectory `
        'ground_tagged_ascii_spans.json') `
        -Value $groundCapture.TaggedLines.ToArray()
    Write-JsonDurable -Path (Join-Path $OutputDirectory `
