    if ($null -ne $dataPlaneReadiness) {
      foreach ($event in @($dataPlaneReadiness.pre_request_param_value_events)) {
        $paramValueEvidenceEvents.Add($event)
      }
    }
    if ($null -ne $officialParamListState) {
