    } else {
      [pscustomobject][ordered]@{
        schema_version=1;valid=$false;status='NOT_RUN';failure_reason='not_run'
        timed_out=$false;sync_invalid=$false;retry_exhausted=$false
        deadline_source='backlog_drain_gate.deadline_elapsed_ms'
        deadline_extended=$false;gate_started_elapsed_ms=$null
        gate_finished_elapsed_ms=$null;deadline_elapsed_ms=$null
