        fixture_write_count=0;attempts=[object[]]@()
        latest_complete_vehicle_snapshot=$null
        final_vehicle_snapshot=$null;final_ground_snapshot=$null
        pre_request_vehicle=$null;pre_request_vehicle_gate=$null
