    } else {
      Test-PreRequestBacklogGate `
          -ReadinessEvents @($dataPlaneReadinessEvidence.pre_request_param_value_events) `
          -M0Events @() -M0EpochCompleted $false
    }
    if ($null -eq $vehicleHeartbeatGrantDiagnostics) {
      $vehicleHeartbeatGrantDiagnostics =
          Test-VehicleHeartbeatGrantDiagnosticContract `
            -BaselineVehicle $baselineVehicle `
            -M0Vehicle $preRequestVehicle -M1Vehicle $postVehicle
    }
    Write-JsonDurable -Path (Join-Path $OutputDirectory `
        'vehicle_heartbeat_grant_diagnostics.json') `
        -Value $vehicleHeartbeatGrantDiagnostics
    $paramListDiagnosticEvidence = New-ParamListDiagnosticEvidence `
        -BacklogDrainGate $backlogDrainEvidence `
        -BaselinePairGate $baselinePairEvidence `
        -BaselineSetup $baselineSetup `
        -PreRequestPairGate $preRequestPairEvidence `
        -PreRequestVehicleGate $preRequestVehicleGate `
        -PreRequestBacklogGate $preRequestBacklogEvidence `
        -M0 $m0 -M1 $m1 -StopReason $captureStopReason `
        -OfficialState $officialParamListState `
        -OfficialAssessment $listAssessment `
        -ParserIntegrity $parserIntegrity `
        -HeartbeatMetrics $heartbeatMetrics `
        -PostCutoffState $postCutoffParamListState `
