        -SyncInvalidContinuation $syncInvalidContinuation
    Write-JsonDurable -Path (Join-Path $OutputDirectory `
        'param_list_diagnostics.json') -Value $paramListDiagnosticEvidence
    Write-JsonDurable -Path (Join-Path $OutputDirectory 'snapshots.json') `
