      errors=$errors.ToArray()
      fixture_attempt_count=[int]$injection.attempt_count
      fixture_write_count=$injection.write_count
      fixture_write_uncertain=[bool]$injection.write_uncertain
      fixture_write_disposition=[string]$injection.write_disposition
      open_counts=[ordered]@{vehicle=$vehicleOpenCount;ground=$groundOpenCount}
      data_plane_readiness=[ordered]@{
        valid=[bool]$dataPlaneReadinessEvidence.valid
