      raw_capture=[ordered]@{
        seal_valid=[bool]$rawEvidenceSeal.seal_valid
        failure_reason=[string]$rawEvidenceSeal.failure_reason
        vehicle_file='vehicle_rx.raw.bin'
        vehicle_bytes=[long]$rawEvidenceSeal.vehicle_bytes
        vehicle_sha256=[string]$rawEvidenceSeal.vehicle_sha256
