        }else{$null}
        stop_capture_sent=if($null -ne $readerBrokerLifecycle){
          [bool]$readerBrokerLifecycle.stop_capture_sent
        }else{$false}
        stop_capture_valid=if($null -ne $readerBrokerLifecycle){
          [bool]$readerBrokerLifecycle.stop_capture_valid
        }else{$false}
        com_open_until_after_capture_footer_fsync=$true
        lifecycle_file='reader_broker_lifecycle.json'
      }
      hot_path_prewarm=$hotPathPrewarm
      durability=[ordered]@{
