    $footerFsyncQpcTicks =
        [System.Diagnostics.Stopwatch]::GetTimestamp()
    $footerRecorded = $true
  } catch {
    [string]$footerFailureMessage =
        "durable footer failure: $($_.Exception.Message)"
    $footerFailureResolution = Resolve-FinalizationFailure `
