    $failure = [string]$footerFailureResolution.primary_failure
    $errors.Add($footerFailureMessage)
    $preCloseStatus = 'ERROR'
    if (-not [bool]$rawEvidenceSeal.seal_valid) {
      $rawEvidenceSeal = Get-RawEvidenceFallbackProjection `
