      }
    } catch {
      [string]$postFooterFailureMessage =
          "post-footer live progress failure: $($_.Exception.Message)"
      $postFooterFailureResolution = Resolve-FinalizationFailure `
          -PrimaryFailure $failure `
          -FinalizationFailure $postFooterFailureMessage
      $failure = [string]$postFooterFailureResolution.primary_failure
      $errors.Add($postFooterFailureMessage)
      $preCloseStatus = 'ERROR'
      try {
        Write-JsonDurable -Path (Join-Path $OutputDirectory `
            'post_footer_live_progress_error.json') -Value ([ordered]@{
              schema_version=1;status='ERROR';completed=$false
              capture_footer_recorded=$true;primary_failure=$failure
              error=$postFooterFailureMessage
              fixture_attempt_count=[int]$injection.attempt_count
              fixture_write_count=[int]$injection.write_count
              fixture_write_uncertain=[bool]$injection.write_uncertain
              fixture_write_disposition=[string]$injection.write_disposition
            })
      } catch {}
    }
  }
