        $vehicleCloseElapsedMs = $script:RunWatch.Elapsed.TotalMilliseconds
      }
    } catch {
      $errors.Add("Vehicle close failed: $($_.Exception.Message)")
      $preCloseStatus='ERROR'
    } finally { $vehicleSerial.Dispose() }
  }
  try { if ($null -ne $groundRawStream) {$groundRawStream.Dispose()} } catch {
