      macro='VC_LORA_HIL_DROP_NATIVE_PARAM_INDEX_930'
      one_shot=$true;expected_future_index=[uint64]931
      expected_missing_tail=[uint64]2;runtime_command_used=$false
      verified_exact=$faultVerifiedExact
    }
  }

  $summary = [ordered]@{
    schema_version=1
    test_id='HIL-DUAL-DIAG-PARAM-LIST-001'
    status=$status
    acceptance_scope=('one exact PARAM_REQUEST_LIST #21 followed by exactly ' +
      '932 unique strictly ordered indexed PARAM_VALUE #22 frames from 1/1, ' +
      'separately permitted exact STAT_RUNTIME sentinel, full primary ' +
      'HEARTBEAT continuity, a fresh pre-request FC data-plane readiness gate, ' +
      'and correlated diagnostic state transitions')
    started_utc=if($script:Timeline.Count -gt 0){$script:Timeline[0].utc}else{$null}
    finished_utc=[DateTime]::UtcNow.ToString('o')
