      sha256=$script:ExpectedFixtureSha256
      strict_contract=$fixtureContract
      attempt_count=[int]$injection.attempt_count
      write_count=$injection.write_count
      write_uncertain=[bool]$injection.write_uncertain
      write_disposition=[string]$injection.write_disposition
      final_write_elapsed_ms=$injection.final_write_elapsed_ms
      final_write_utc=$injection.final_write_utc
    }
    timeout_contract=[ordered]@{
      overall_timeout_seconds=$OverallTimeoutSeconds
      expected_index_stall_timeout_seconds=$StallTimeoutSeconds
      post_index_931_duplicate_guard_seconds=$DuplicateGuardSeconds
      data_plane_readiness_timeout_seconds=$DataPlaneReadinessTimeoutSeconds
      backlog_drain_timeout_seconds=$BacklogDrainTimeoutSeconds
    }
    data_plane_readiness=$dataPlaneReadinessEvidence
    backlog_drain=$backlogDrainEvidence
    baseline_pair_gate=$baselinePairEvidence
    pre_request_pair_gate=$preRequestPairEvidence
    post_diagnostic_plan=$postDiagnosticPlan
    post_ground_status=if($null -ne $postGround){$postGround.status}else{'NOT_RUN'}
    post_vehicle_status=if($null -ne $postVehicle){$postVehicle.status}else{'NOT_RUN'}
    post_ground_query_count=if($null -ne $postGround){
      [int]$postGround.query_count
    }else{0}
    post_vehicle_query_count=if($null -ne $postVehicle){
      [int]$postVehicle.query_count
    }else{0}
    diagnostic_query_write_count=[uint64]$script:DiagnosticQueryWriteCount
    sync_invalid_continuation=$syncInvalidContinuation
    timeline_markers=[ordered]@{M0=$m0;R0=$r0;M1=$m1}
    causal_gate=$causalGate
    setup_invalid_request_suppressed=($setupInvalid -and
        $injection.write_count -eq 0)
    snapshots=[ordered]@{
      baseline_vehicle=$baselineVehicle;baseline_ground=$baselineGround
      pre_request_vehicle=$preRequestVehicle
      post_ground=$postGround;post_vehicle=$postVehicle
      vehicle_heartbeat_grant_diagnostics=$vehicleHeartbeatGrantDiagnostics
    }
    baseline_setup=$baselineSetup
    pre_request_vehicle_gate=$preRequestVehicleGate
    post_diagnostic_assessment=$postAssessment
    param_list=$listAssessment
    param_list_diagnostics=$paramListDiagnosticEvidence
    capture_stop_reason=$captureStopReason
    heartbeat=$heartbeatMetrics
    vehicle_heartbeat_grant_diagnostics=$vehicleHeartbeatGrantDiagnostics
    parser_integrity=$parserIntegrity
    hot_path_prewarm=$hotPathPrewarm
    reader_broker=$readerBrokerLifecycle
    duplicate_guard_completed=$guardCompleted
    mavlink_definitions=[ordered]@{
      source=$mavlinkDefinitionSet.path
      sha256=$mavlinkDefinitionSet.sha256
