    raw_capture=[ordered]@{
      seal_valid=[bool]$rawEvidenceSeal.seal_valid
      failure_reason=[string]$rawEvidenceSeal.failure_reason
      vehicle_file='vehicle_rx.raw.bin'
      vehicle_bytes=[long]$rawEvidenceSeal.vehicle_bytes
      vehicle_sha256=[string]$rawEvidenceSeal.vehicle_sha256
      ground_file='ground_rx.raw.bin'
      ground_bytes=[long]$rawEvidenceSeal.ground_bytes
      ground_sha256=[string]$rawEvidenceSeal.ground_sha256
      streams_disposed_before_hash=`
          [bool]$rawEvidenceSeal.streams_disposed_before_hash
      raw_offsets_and_byte_counters='Int64/UInt64'
      streams_never_reset_or_overwritten=$true
    }
    pump_fairness=$pumpFairnessEvidence
    durability=[ordered]@{
      file_mode='CreateNew';json_file_options='WriteThrough'
      raw_file_options='SequentialScan'
      raw_buffer_bytes=$script:RawCaptureBufferBytes
      raw_flush_schedule_ms=$script:RawCaptureFlushScheduleMs
      raw_flush_max_interval_ms=$script:RawCaptureFlushIntervalMs
      flush_to_disk='Flush(true)';footer_fsync_before_both_close=$closeAfterFooter
      live_progress_file='live_progress.jsonl'
      post_close_summary=$true;artifact_hashes_after_close=$true
      broker_child_exit_before_final_seal=if(
          $null -ne $readerBrokerLifecycle){
        [bool]$readerBrokerLifecycle.final_seal_after_broker_exit
      }else{$false}
    }
    external_actions=[ordered]@{
      upload=$false;firmware_write=$false;actuator_command=$false
    }
    runner_sha256=$runnerSha256
  }
  if ($ExpectedDiagnosticFaultMode -ceq 'FUTURE_INDEX_RECOVERY') {
    $summary['diagnostic_fault_intervention'] =
        $diagnosticFaultIntervention
  }
  Write-JsonDurable -Path (Join-Path $OutputDirectory 'summary.json') `
      -Value $summary
  Add-LiveProgressRecord -Event 'final_status' -Details @{
    status=$status;output_path=$OutputDirectory
    indexed=if($null -ne $listAssessment){$listAssessment.unique_count}else{0}
    last=if($null -ne $listAssessment){$listAssessment.last_index}else{-1}
    error_count=$errors.Count
  }
  $script:LiveProgressStream.Dispose()
  $script:LiveProgressStream = $null

  $artifactRows = New-Object 'System.Collections.Generic.List[object]'
  foreach ($file in @(Get-ChildItem -LiteralPath $OutputDirectory -File |
      Where-Object {$_.Name -ne 'artifact_hashes.json'} | Sort-Object Name)) {
    $artifactRows.Add([pscustomobject][ordered]@{
      file=$file.Name;size_bytes=[long]$file.Length
      sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $file.FullName).Hash
    })
  }
  Write-JsonDurable -Path (Join-Path $OutputDirectory `
      'artifact_hashes.json') -Value ([ordered]@{
        schema_version=1
        coverage='all regular files present before artifact_hashes.json'
        covered_file_count=$artifactRows.Count
        files=$artifactRows.ToArray()
      })
} catch {
  [string]$postCloseMessage = `
      "post-close finalization error: $($_.Exception.Message)"
  $postCloseFailureResolution = Resolve-FinalizationFailure `
      -PrimaryFailure $failure -FinalizationFailure $postCloseMessage
  $failure = [string]$postCloseFailureResolution.primary_failure
  try {
    if ($null -ne $script:LiveProgressStream) {
      Add-LiveProgressRecord -Event 'error' -Details @{
        status='ERROR';message=$postCloseMessage;primary_failure=$failure
      }
      Add-LiveProgressRecord -Event 'final_status' -Details @{
        status='ERROR';output_path=$OutputDirectory;failure=$failure
      }
      $script:LiveProgressStream.Dispose()
      $script:LiveProgressStream = $null
    }
  } catch {}
  try {
    Write-JsonDurable -Path (Join-Path $OutputDirectory `
        'postclose_finalization_error.json') -Value ([ordered]@{
          schema_version=1;status='ERROR';completed=$false
          written_utc=[DateTime]::UtcNow.ToString('o')
          capture_footer_recorded=$footerRecorded
          capture_footer_fsync_elapsed_ms=$footerFsyncElapsedMs
          vehicle_close_elapsed_ms=$vehicleCloseElapsedMs
          ground_close_elapsed_ms=$groundCloseElapsedMs
          primary_failure=$failure;error=$postCloseMessage
          fixture_attempt_count=[int]$injection.attempt_count
          fixture_write_count=[int]$injection.write_count
          fixture_write_uncertain=[bool]$injection.write_uncertain
          fixture_write_disposition=[string]$injection.write_disposition
        })
  } catch {}
  [Console]::Error.WriteLine(
      ('FINAL ERROR output={0} message={1}' -f $OutputDirectory,
       $postCloseMessage))
  exit 2
}

Write-Host ('FINAL {0} output={1}' -f $status, $OutputDirectory)
if ($status -eq 'PASS') { exit 0 }
if ($status -eq 'ERROR') { exit 2 }
exit 1
